import { hex } from '../../world/biomes';
import type { DrivingKind, EnergyKind, FindKind, InstitutionKind, SupplyKind, ThemeKind } from '../../world/tiles';
import type { Draw } from './kit';
import { FINDS_DRAW } from './finds';
import { INDUSTRY_DRAW } from './industry';
import { MOTORING_DRAW } from './motoring';
import { INSTITUTION_DRAW } from './institutions';
import { WORLD_A_DRAW } from './worldStylesA';
import { WORLD_B_DRAW } from './worldStylesB';
import { WORLD_C_DRAW } from './worldStylesC';
import { FICTION_A_DRAW } from './fictionA';
import { FICTION_B_DRAW } from './fictionB';

/**
 * The September 2026 expansion's draw tables, gathered: things to find, heavy industry and energy, the
 * driver's destinations, the institutions, and the signature buildings of the twenty newer town styles.
 * A kind whose model is not drawn yet stands as a plain block, so a world never has a hole in it.
 */

type SiteKindNew = FindKind | SupplyKind | EnergyKind | DrivingKind | InstitutionKind;

/** Every expansion kind that stands out in the country or on a town's edge, by group (the gallery's groups). */
const SITE_GROUPS = {
  finds: ['ghostTown', 'abandonedMine', 'shipwreck', 'planeWreck', 'ruinedAbbey', 'bunker', 'crashedSatellite', 'capeLight', 'hermitCabin'],
  industry: ['refinery', 'steelworks', 'textileMill', 'paperMill', 'cementPlant', 'containerTerminal', 'autoPlant', 'solarFarm', 'offshoreWind', 'tidalBarrage', 'pumpedHydro'],
  motoring: ['summitCafe', 'scenicOverlook', 'hillClimb', 'rallyStage', 'dragStrip', 'provingGround', 'iceRoadCheckpoint', 'motorwayServices'],
  institutions: ['filmStudio', 'militaryBase', 'borderFort', 'cableCarStation', 'researchDome', 'festivalGrounds'],
} as const satisfies Record<string, readonly SiteKindNew[]>;

/** The newer styles' signature buildings, by the file that draws them. */
const STYLE_GROUPS = {
  worldA: ['tajMahal', 'stepwell', 'hawaMahal', 'alhambra', 'giralda', 'machuPicchu', 'sunTemple', 'mudMosque', 'mudGranary', 'dzong'],
  worldB: ['longhouse', 'runestone', 'campanile', 'dogePalace', 'marcoBasilica', 'gondolaStation', 'bigBen', 'gherkin', 'jazzClub', 'tombYard', 'cigarFactory', 'morroFort'],
  worldC: ['bankTower', 'walledCity', 'casinoPyramid', 'welcomeSign', 'needleTower', 'fountainResort', 'sphereTheatre', 'supertall', 'sailHotel', 'neonMotel', 'wigwamMotel', 'giantArrows'],
  fictionA: ['hobbitHole', 'partyTree', 'hobbitInn', 'whiteCitadel', 'beaconTower', 'grandBathhouse', 'clockGate'],
  fictionB: ['clockworkTower', 'boilerWorks', 'skyDock', 'gardenTower', 'solarCanopy', 'bioDome', 'megablock', 'holoTower', 'nightMarket'],
} as const satisfies Record<string, readonly ThemeKind[]>;

type StyleKindNew = (typeof STYLE_GROUPS)[keyof typeof STYLE_GROUPS][number];

const placeholder: Draw = (k, W, D) => { k.box(0, 0, 0, Math.max(0.4, W - 0.3), 0.5, Math.max(0.4, D - 0.3), hex(0xd8d0c0)); };

const sites: Partial<Record<SiteKindNew, Draw>> = { ...FINDS_DRAW, ...INDUSTRY_DRAW, ...MOTORING_DRAW, ...INSTITUTION_DRAW };
const styles: Partial<Record<ThemeKind, Draw>> = { ...WORLD_A_DRAW, ...WORLD_B_DRAW, ...WORLD_C_DRAW, ...FICTION_A_DRAW, ...FICTION_B_DRAW };

export const SITE_DRAW = Object.fromEntries(
  Object.values(SITE_GROUPS).flat().map((kind) => [kind, sites[kind] ?? placeholder]),
) as Record<SiteKindNew, Draw>;

export const STYLE_EXTRA_DRAW = Object.fromEntries(
  Object.values(STYLE_GROUPS).flat().map((kind) => [kind, styles[kind] ?? placeholder]),
) as Record<StyleKindNew, Draw>;

/** Per-group draw tables for the gallery: gallery.html?group=finds|industry|motoring|institutions|worldA|worldB|worldC|fictionA|fictionB */
export const EXPANSION_GALLERY: Record<string, Record<string, Draw>> = {
  ...Object.fromEntries(Object.entries(SITE_GROUPS).map(([g, kinds]) => [g, Object.fromEntries(kinds.map((k) => [k, SITE_DRAW[k]]))])),
  ...Object.fromEntries(Object.entries(STYLE_GROUPS).map(([g, kinds]) => [g, Object.fromEntries(kinds.map((k) => [k, STYLE_EXTRA_DRAW[k]]))])),
};
