import * as THREE from 'three';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { Contrail, PlaneShadow } from '../render/skyLayer';
import { VEHICLES, type AirDef, type Controls, type VehicleState } from './vehicles';
import { allAirports, allRunways, cellCentre, frameOf, lockOf, pointOf, stripFor, type Runway } from '../world/runways';
import { hasMega } from '../world/macro';
import { OPEN_SEA, cellOf } from '../world/tiles';
import { GLIDE } from './air';
import type { JetFlight, JetPhase } from './jetFlight';
import { rand } from '../util/math';
import { mulberry32 } from '../world/rng';

/**
 * The sky's own traffic (docs/rides.html). Two things share one list of flights:
 *
 *  - Airport life: every airfield near the camera sends a jet out now and then (a Jumbo mostly, from an
 *    international), which taxis from a stand at the end of the apron, holds short, rolls, lifts off and
 *    climbs out; and some flights end here, turning onto final, landing, rolling out and taxiing in.
 *  - Overhead: zero to two jets crossing high above the camera on lanes between the world's airports,
 *    mostly straight, sometimes in a slow turn at a constant rate, with contrails and a shadow.
 *
 * A flight is scripted, not simulated: its phase says what it does, in world tiles, and it is drawn with
 * the very mesh the dealer sells. A runway is a lock one mover holds at a time, and the player always
 * wins it: ambient jets hold short or go around.
 */

export interface SkyHost {
  /** What the camera looks at, in world tiles and units, and how high above it the camera stands. */
  focus(): { x: number; y: number; z: number };
  camHeight(): number;
  /** Where the camera stands, world units. */
  camera(): { x: number; y: number; z: number };
  seedHash(): number;
  /** Ground height (world units) under a world tile, or sea level where nothing is loaded. */
  ground(gx: number, gz: number): number;
  night(): number;
  rain(): number;
  /** Unit vector toward the sun. */
  sun(): THREE.Vector3;
  wind(): number;
  /** The player's jet, if they're in one: world tiles, and the runway it's on or landing on. */
  playerRunway(): Runway | null;
  /** Busy spell: spawn more often (the title reel). */
  lively?: boolean;
  /** A line in the log: a flypast coming in over a venue. `group` stacks it with the venue's own. */
  say?(title: string, body: string, group?: string): void;
}

type Phase = 'taxiOut' | 'hold' | 'roll' | 'climb' | 'cruise' | 'inbound' | 'final' | 'rollout' | 'taxiIn' | 'wait' | 'show';

/**
 * A flypast (the user, 2 Nov 2026): three to seven jets or helicopters in formation, low over a stadium or a
 * circuit just as the big day there is about to begin. The formation is a shape of slots (back from and right
 * of the lead, in gaps of a wingspan or two) flown as one along a straight line through the venue; past it the
 * jets pull up and fan out, and each goes on as ordinary cruising traffic until it leaves the view.
 */
type Shape = 'vic' | 'diamond' | 'arrow' | 'echelon' | 'abreast' | 'trail';
const SHAPE_NAME: Record<Shape, string> = { vic: 'a vic', diamond: 'a diamond', arrow: 'an arrowhead', echelon: 'an echelon', abreast: 'a line abreast', trail: 'a line astern' };
/** Each member's place: gaps back from the lead and to its right (negative: left). */
function slotsOf(shape: Shape, n: number): { back: number; right: number }[] {
  const out: { back: number; right: number }[] = [];
  for (let k = 0; k < n; k++) {
    const r = Math.ceil(k / 2), side = k % 2 ? -1 : 1;
    switch (shape) {
      case 'vic': out.push({ back: r, right: k ? side * r : 0 }); break;
      case 'arrow': out.push(k === n - 1 && n % 2 === 0 ? { back: r + 0.5, right: 0 } : { back: r, right: k ? side * r : 0 }); break;
      case 'diamond': out.push(k === 0 ? { back: 0, right: 0 } : k === 1 ? { back: 1, right: -1 } : k === 2 ? { back: 1, right: 1 } : k === 3 ? { back: 2, right: 0 } : { back: 2 + Math.ceil((k - 3) / 2), right: ((k - 3) % 2 ? -1 : 1) * 2 }); break;
      case 'echelon': out.push({ back: k * 0.8, right: k }); break;
      case 'abreast': out.push({ back: 0, right: k - (n - 1) / 2 }); break;
      case 'trail': out.push({ back: k, right: 0 }); break;
    }
  }
  return out;
}

interface Flypast {
  over: { x: number; z: number };
  venue: string;
  heading: number;
  v: number;
  alt: number;
  jets: boolean;
  defs: AirDef[];
  slots: { back: number; right: number }[];
  gap: number;
  /** The display team's smoke, one colour a jet, or none. */
  smoke: ([number, number, number] | null)[];
  callsign: string;
  /** Whose they are, for the card. */
  from: string;
  desc: string;
  /** Seconds until the lead crosses the venue (negative after); its members, once they are in the air. */
  t: number;
  members: Flight[] | null;
}

/** How far back from the venue a formation comes into being, tiles, and how far past it the lead flies before the break. */
const SHOW_START = 150, SHOW_BREAK = 10;
/** The display teams' smoke: red, white and blue in turn. */
const SMOKE: [number, number, number][] = [[1, 0.3, 0.25], [1, 1, 1], [0.35, 0.55, 1]];
const CALLSIGNS = { military: ['Viper', 'Sabre', 'Talon', 'Falcon', 'Raptor', 'Lancer'], civil: ['Skylark', 'Swallow', 'Comet', 'Meteor'], heli: ['Hornet', 'Hawk', 'Osprey', 'Condor'] };
const SPELL = ['', '', '', 'three', 'four', 'five', 'six', 'seven'];

/** A flight's pose, in the shape poseVehicleMesh reads. */
class FlyState implements VehicleState {
  x = 0; y = 0; z = 0; heading = 0; v = 0;
  pitch = 0; roll = 0; bob = 0; lean = 0; wheelSpin = 0; steerVis = 0;
  power = 0.6; blocked = 0; trailerHeading = 0; sailAngle = 0; surfaceY = NaN;
  gear = 0;
  step(_w: unknown, _c: Controls, _dt: number): void { /* scripted */ }
  status(): string { return ''; }
}

export interface Flight {
  id: number;
  def: AirDef;
  no: string;
  from: string; to: string;
  phase: Phase;
  st: FlyState;
  mesh: VehicleMesh;
  trails: Contrail[];
  /** Each trail's engine, as a sideways offset from the centreline in tiles. */
  engines: number[];
  shadow: PlaneShadow;
  /** Constant turn rate while cruising (rad/s), or a bearing it turns onto and then holds. */
  yawRate: number;
  bearing: number | null;
  /** The height it cruises at, world units. */
  alt: number;
  /** The airport it's working, the end it uses, and the taxi route still to go. */
  rw: Runway | null;
  dir: 1 | -1;
  path: { x: number; z: number }[];
  wait: number;
  stand: number;
  /** An overhead flight isn't tied to an airport near here. */
  overhead: boolean;
  /** The speed it settles to once cruising overhead. */
  cruiseV: number;
  /** A hired pilot's jet (game/jetPilots.ts): flown there, only drawn here. */
  crew?: JetFlight;
}

/** A hired jet's phase as an airport's own flight's, for its card and its sound. */
const CREW_PHASE: Record<JetPhase, Phase> = {
  stand: 'wait', taxiOut: 'taxiOut', hold: 'hold', roll: 'roll', climb: 'climb', cruise: 'cruise',
  inbound: 'inbound', around: 'inbound', final: 'final', rollout: 'rollout', taxiIn: 'taxiIn',
};

const pick = <T,>(a: T[]): T => a[Math.floor(Math.random() * a.length)];
const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
const FAR_NAMES = ['Meridian', 'Northreach', 'Calder', 'Halcyon', 'Sable', 'Westgate', 'Aurelia', 'Kestrel Point', 'Brightwater'];
const OVERSEAS = ['Port Aurelia', 'Vesterhaven', 'Saint Maren', 'Kolonna', 'Isla Serena', 'Oriel'];
const AIRLINES = ['PR', 'SK', 'AQ', 'MW', 'TL', 'OR'];
/** Most overhead flights at once, and the most working one airport. */
const MAX_OVERHEAD = 2;
const MAX_PER_PORT = 2;
/** How far from the camera an airport's life is kept going, in tiles. */
const PORT_RANGE = 200;

export class SkyTraffic {
  readonly group = new THREE.Group();
  flights: Flight[] = [];
  private nextId = 1;
  private overheadT = rand(4, 12);
  private portT = new Map<Runway, number>();
  /** Which flight holds each runway, if one does. */
  private lock = new Map<Runway, number>();
  private jumbo = VEHICLES.find((d) => d.id === 'jumbo') as AirDef;
  private swift = VEHICLES.find((d) => d.id === 'swift') as AirDef;
  private time = 0;
  /** Flypasts booked over the venues, in the air or still to come. */
  private flypasts: Flypast[] = [];

  constructor(scene: THREE.Scene, private host: SkyHost) {
    scene.add(this.group);
  }

  // ---- places ----

  /** Airports this flight could be going to or coming from: the runways loaded, and the internationals the macro promises. */
  private places(): { name: string; x: number; z: number }[] {
    const out = allAirports().map((r) => ({ name: r.name, x: (r.ax + r.bx) / 2, z: (r.az + r.bz) / 2 }));
    const f = this.host.focus();
    const cx = cellOf(f.x), cz = cellOf(f.z), h = this.host.seedHash();
    const loaded = new Set(allRunways().map((r) => `${r.w.cx},${r.w.cz}`));
    for (let dz = -6; dz <= 6; dz++) {
      for (let dx = -6; dx <= 6; dx++) {
        const x = cx + dx, z = cz + dz;
        if (loaded.has(`${x},${z}`) || !hasMega(h, x, z)) continue;
        const c = cellCentre(x, z);
        out.push({ name: `${FAR_NAMES[Math.abs(x * 31 + z * 17) % FAR_NAMES.length]} International`, ...c });
      }
    }
    return out;
  }

  // ---- making flights ----

  private make(def: AirDef, overhead: boolean, engines = def.id === 'jumbo' ? [-0.62, 0.62] : [-0.13, 0.13]): Flight {
    const mesh = buildVehicleMesh(def);
    this.group.add(mesh.holder);
    const f: Flight = {
      id: this.nextId++, def, no: `${pick(AIRLINES)} ${100 + Math.floor(Math.random() * 900)}`,
      from: '', to: '', phase: 'cruise', st: new FlyState(), mesh,
      trails: engines.map(() => new Contrail(this.group)), engines, shadow: new PlaneShadow(this.group, def),
      yawRate: 0, bearing: null, alt: 0, rw: null, dir: 1, path: [], wait: 0, stand: -1, overhead, cruiseV: this.cruiseSpeed(def),
    };
    // the ground shadow is the decal's job (the sun's shadow map doesn't reach up there)
    mesh.holder.traverse((o) => { o.castShadow = false; });
    this.flights.push(f);
    return f;
  }

  private remove(f: Flight): void {
    if (!f.crew) for (const [r, id] of this.lock) if (id === f.id) this.lock.delete(r);
    this.group.remove(f.mesh.holder);
    disposeVehicleMesh(f.mesh);
    f.trails.forEach((t) => t.dispose());
    f.shadow.dispose();
    this.flights = this.flights.filter((g) => g !== f);
  }

  /**
   * The height overhead traffic cruises at: high over the ground but well under the camera. The view is
   * narrow (an 18° lens far back), so anything much higher crosses the frame in a blink; at about two
   * fifths of the camera's height a jet reads as far overhead and stays in sight for a few seconds.
   */
  private cruiseAlt(x: number, z: number): number {
    const f = this.host.focus();
    // the flight crosses the view through about the focus: clear whatever stands anywhere along that line,
    // so a range in big country is flown over rather than through
    let g = -Infinity;
    for (let k = 0; k <= 8; k++) {
      const t = k / 4;
      g = Math.max(g, this.host.ground(x + (f.x - x) * t, z + (f.z - z) * t));
    }
    return Math.max(f.y + Math.min(44, Math.max(14, this.host.camHeight() * 0.4)), g + 14);
  }

  /** The visible radius round the focus: flights spawn just outside it and leave past it. */
  private radius(): number {
    return Math.min(90, Math.max(22, this.host.camHeight() * 0.5));
  }

  /**
   * The point under the middle of the screen at height y: the camera looks down at a slant, so what is
   * in view high up lies back toward the camera from the ground it looks at.
   */
  private aim(y: number): { x: number; z: number } {
    const f = this.host.focus(), c = this.host.camera();
    const t = Math.min(0.9, Math.max(0, (y - f.y) / Math.max(1, c.y - f.y)));
    return { x: f.x + (c.x - f.x) * t, z: f.z + (c.z - f.z) * t };
  }

  /** How fast a jet seems to go up there: slow, the way something far overhead does. */
  private cruiseSpeed(def: AirDef): number {
    return def.id === 'jumbo' ? rand(3.8, 4.6) : rand(4.6, 5.6);
  }

  /** An overhead flight: on the ring, pointed across the view toward an airport (or overseas), straight or on a steady turn. */
  private spawnOverhead(): void {
    const f0 = this.host.focus(), R = this.radius() * 1.35;
    const alt = this.cruiseAlt(f0.x, f0.z), c0 = this.aim(alt);
    const places = this.places().filter((p) => Math.hypot(p.x - f0.x, p.z - f0.z) > 120);
    const def = Math.random() < 0.7 ? this.jumbo : this.swift;
    const f = this.make(def, true);
    // a line that crosses the view off-centre, heading for somewhere real where there is somewhere
    let heading: number;
    if (places.length >= 1) {
      const to = pick(places);
      heading = Math.atan2(to.x - f0.x, to.z - f0.z) + rand(-0.35, 0.35);
      f.to = to.name;
      const from = places.filter((p) => p !== to);
      f.from = from.length ? pick(from).name : `Overseas · ${pick(OVERSEAS)}`;
    } else {
      heading = rand(0, Math.PI * 2);
      f.from = `Overseas · ${pick(OVERSEAS)}`;
      f.to = `Overseas · ${pick(OVERSEAS.filter((n) => !f.from.endsWith(n)))}`;
    }
    const side = rand(-0.35, 0.35) * R;
    const st = f.st;
    st.heading = heading;
    st.x = c0.x - Math.sin(heading) * R + Math.cos(heading) * side;
    st.z = c0.z - Math.cos(heading) * R - Math.sin(heading) * side;
    st.v = f.cruiseV = this.cruiseSpeed(def);
    f.alt = this.cruiseAlt(st.x, st.z);
    st.y = f.alt;
    // three in ten on a slow, steady turn
    if (Math.random() < 0.3) f.yawRate = (Math.random() < 0.5 ? -1 : 1) * st.v / rand(40, 140);
    f.phase = 'cruise';
    st.gear = 0;
  }

  /** A departure from one of this airport's stands, off down the runway into the wind (a two-runway airport's either one). */
  private spawnDeparture(port: Runway): void {
    const stands = port.stands.map((_, k) => k).filter((k) => !this.flights.some((f) => f.rw?.stands === port.stands && f.stand === k));
    if (!stands.length) return;
    const k = pick(stands);
    const def = port.major && Math.random() < 0.75 ? this.jumbo : this.swift;
    const f = this.make(def, false);
    const r = stripFor(port, this.host.wind(), f.id);
    f.rw = r;
    f.stand = k;
    f.dir = this.windEnd(r);
    f.from = r.name;
    const dest = this.places().filter((p) => p.name !== r.name);
    f.to = dest.length && Math.random() < 0.7 ? pick(dest).name : `Overseas · ${pick(OVERSEAS)}`;
    const s = r.stands[k], st = f.st;
    st.x = s.x; st.z = s.z; st.heading = s.heading; st.y = r.y; st.v = 0; st.gear = 1;
    const fs = frameOf(r, s.x, s.z);
    const start = f.dir === 1 ? -1.5 : r.len + 1.5;
    f.path = [pointOf(r, fs.along, r.taxiOff), pointOf(r, start, r.taxiOff), pointOf(r, start, 0)];
    f.phase = 'taxiOut';
    f.wait = rand(2, 8);
  }

  /** An arrival: comes in from the ring toward the final approach of this airport's runway (either one, at a two-runway airport). */
  private spawnArrival(port: Runway): void {
    const def = port.major && Math.random() < 0.7 ? this.jumbo : this.swift;
    const f = this.make(def, false);
    const r = stripFor(port, this.host.wind(), f.id);
    f.rw = r;
    f.dir = this.windEnd(r);
    f.to = r.name;
    const others = this.places().filter((p) => p.name !== r.name);
    f.from = others.length && Math.random() < 0.7 ? pick(others).name : `Overseas · ${pick(OVERSEAS)}`;
    const [tx, tz] = f.dir === 1 ? [r.ax, r.az] : [r.bx, r.bz];
    const ux = r.ux * f.dir, uz = r.uz * f.dir;
    // start well out, off to one side of the extended centreline, and turn in
    const st = f.st, out = rand(90, 120), side = rand(-40, 40);
    st.x = tx - ux * out + uz * side;
    st.z = tz - uz * out - ux * side;
    st.v = def.topSpeed * 0.65;
    f.alt = Math.max(r.y + 20, this.cruiseAlt(st.x, st.z) - 10);
    st.y = f.alt;
    st.heading = Math.atan2(tx - st.x, tz - st.z);
    st.gear = 0;
    f.phase = 'inbound';
  }

  /** The runway end that faces into the wind: both directions use it, so an airport's traffic all goes one way. */
  windEnd(r: Runway): 1 | -1 {
    const w = this.host.wind();
    // wind blows toward windHeading; take off and land into it
    const into = Math.cos(wrap(r.heading - (w + Math.PI)));
    return into >= 0 ? 1 : -1;
  }

  // ---- the runway lock ----

  /**
   * May flight `id` have the runway? Never while the player is on it; otherwise when nobody else holds it. A two-runway
   * airport's two are one lock (lockOf): they cross, or meet at a corner.
   */
  free(r: Runway, id: number): boolean {
    const mine = this.host.playerRunway();
    if (mine && lockOf(mine) === lockOf(r)) return false;
    const held = this.lock.get(lockOf(r));
    return held === undefined || held === id;
  }
  take(r: Runway, id: number): void { this.lock.set(lockOf(r), id); }
  release(r: Runway, id: number): void { if (this.lock.get(lockOf(r)) === id) this.lock.delete(lockOf(r)); }
  /** Is stand k of runway r taken by any flight but `id`? (A two-runway airport's runways share their stands.) */
  standTaken(r: Runway, k: number, id: number): boolean {
    return this.flights.some((f) => f.id !== id && f.rw?.stands === r.stands && f.stand === k);
  }
  /**
   * Which of an airport's runways a hired jet's movement uses (world/runways.ts stripFor): its id, and the five
   * minutes it is in, so one jet's legs don't all take the same runway (steady through any one approach or roll).
   */
  strip(r: Runway, id: number): Runway { return stripFor(r, this.host.wind(), id + Math.floor(this.time / 300)); }

  // ---- flypasts over the venues ----

  /**
   * Book a flypast over (x, z): the lead crosses it `secs` from now. The seed picks jets or helicopters, the
   * military or a civil display team, three to seven of them and the shape. Returns what is coming, in words.
   */
  flyover(x: number, z: number, secs: number, seed: number, venue: string): string {
    const r = mulberry32(seed);
    const jets = r() < 0.5, military = r() < 0.5;
    const n = 3 + Math.floor(r() * 5);
    const shapes: Shape[] = jets ? (n === 4 ? ['diamond', 'vic', 'echelon'] : n % 2 ? ['vic', 'arrow', 'echelon'] : ['arrow', 'echelon', 'vic']) : ['abreast', 'vic', 'trail', 'echelon'];
    const shape = shapes[Math.floor(r() * shapes.length)];
    const team = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0xf4f2ec][Math.floor(r() * 4)];
    const base = VEHICLES.find((d) => d.id === (jets ? (military ? 'fighter' : 'swift') : military ? 'chinook' : 'dragonfly')) as AirDef;
    const def: AirDef = military ? base : { ...base, color: team };
    const callsign = (military ? (jets ? CALLSIGNS.military : CALLSIGNS.heli) : jets ? CALLSIGNS.civil : CALLSIGNS.heli)[Math.floor(r() * 4)];
    const who = jets ? (military ? `Stingers of the Air Force` : `Swifts of the ${callsign} display team`) : military ? `Bumblebees of the Army` : `Dragonflies of the ${callsign} air display`;
    const desc = `${SPELL[n]} ${who}, in ${SHAPE_NAME[shape]}`;
    const heading = r() * Math.PI * 2;
    const v = jets ? 9 + r() * 2 : 4.5 + r() * 0.8;
    // low over the venue, but over anything that stands along the line
    let g = -Infinity;
    for (let d = -60; d <= 40; d += 5) g = Math.max(g, this.host.ground(x + Math.sin(heading) * d, z + Math.cos(heading) * d) + (Math.abs(d) < 12 ? 0 : -4));
    const alt = Math.max(this.host.ground(x, z) + (jets ? 13 : 8), g + (jets ? 11 : 7));
    this.flypasts.push({
      over: { x, z }, venue, heading, v, alt, jets, defs: Array.from({ length: n }, () => def), slots: slotsOf(shape, n), gap: jets ? def.halfWid * 2.6 : Math.max(def.halfLen, def.halfWid) * 2.8,
      smoke: Array.from({ length: n }, (_, k) => (jets ? (military ? [0.9, 0.9, 0.9] : SMOKE[k % 3]) : null)),
      callsign, from: military ? (jets ? 'The Air Force' : 'The Army') : `${callsign} display team`, desc, t: secs, members: null,
    });
    return desc;
  }

  /** The flypasts: into the air when the start of the line is a few seconds off, flown as one, then released past the venue. */
  private stepFlypasts(dt: number): void {
    for (const fp of [...this.flypasts]) {
      fp.t -= dt;
      const lead = -fp.t * fp.v;
      if (!fp.members) {
        if (lead < -SHOW_START) continue;
        // nobody near enough to see it: the display team stays at home
        const c = this.host.focus();
        if (Math.hypot(fp.over.x - c.x, fp.over.z - c.z) > 260) { this.flypasts = this.flypasts.filter((q) => q !== fp); continue; }
        fp.members = fp.defs.map((def, k) => {
          const f = this.make(def, false, fp.smoke[k] ? [0] : []);
          f.phase = 'show';
          f.no = `${fp.callsign} ${k + 1}`;
          f.from = fp.from;
          f.to = fp.venue;
          f.cruiseV = fp.v;
          f.alt = fp.alt;
          if (fp.smoke[k]) f.trails[0].tint = fp.smoke[k]!;
          return f;
        });
        if (Math.hypot(fp.over.x - c.x, fp.over.z - c.z) < 140) this.host.say?.(`${fp.jets ? '✈️' : '🚁'} Flypast at ${fp.venue}`, `${fp.desc[0].toUpperCase()}${fp.desc.slice(1)} coming in low`, fp.venue);
      }
      const sx = Math.sin(fp.heading), cz = Math.cos(fp.heading);
      const lx = fp.over.x + sx * lead, lz = fp.over.z + cz * lead;
      let left = 0;
      fp.members.forEach((f, k) => {
        if (f.phase !== 'show' || !this.flights.includes(f)) return;
        const s = fp.slots[k], st = f.st;
        st.x = lx - sx * s.back * fp.gap + cz * s.right * fp.gap;
        st.z = lz - cz * s.back * fp.gap - sx * s.right * fp.gap;
        st.y = fp.alt;
        st.heading = fp.heading;
        st.v = fp.v;
        st.power = 0.9;
        // a helicopter's nose down into its forward flight
        st.pitch = fp.jets ? 0 : 0.1; st.roll = 0; st.gear = 0;
        left++;
        // past the venue: the jets pull up and fan out, the helicopters climb away gently
        if (lead - s.back * fp.gap > SHOW_BREAK) {
          f.phase = 'cruise';
          f.overhead = true;
          f.alt = fp.alt + (fp.jets ? 30 : 6);
          f.bearing = fp.heading + (s.right === 0 ? 0 : Math.sign(s.right) * (fp.jets ? 0.55 : 0.2));
          f.yawRate = 0;
        }
      });
      if (!left) this.flypasts = this.flypasts.filter((q) => q !== fp);
    }
  }

  // ---- hired jets (game/jetPilots.ts): flown there, drawn here like the rest ----

  /** Draw a hired pilot's jet: its own mesh, trails and shadow, its card as a flight's. */
  adopt(crew: JetFlight, def: AirDef, name: string): void {
    const f = this.make(def, false);
    f.crew = crew;
    f.id = crew.id;
    f.no = name;
    this.syncCrew(f);
  }

  /** The mesh a hired jet is drawn with here (for the fleet's badge over it, main.ts drawBadges), or null. */
  crewMesh(crew: JetFlight): VehicleMesh | null {
    return this.flights.find((g) => g.crew === crew)?.mesh ?? null;
  }

  /** Stop drawing a hired jet. */
  disown(crew: JetFlight): void {
    const f = this.flights.find((g) => g.crew === crew);
    if (f) this.remove(f);
  }

  private syncCrew(f: Flight): void {
    const c = f.crew!, st = f.st;
    st.x = c.st.x; st.y = c.st.y; st.z = c.st.z; st.heading = c.st.heading; st.v = c.st.v;
    st.pitch = c.st.pitch; st.roll = c.st.roll; st.gear = c.st.gear; st.wheelSpin = c.st.wheelSpin; st.power = c.st.power;
    f.phase = CREW_PHASE[c.phase];
    f.rw = c.rw;
    f.stand = c.stand;
    f.to = c.goal.kind === 'overseas' ? c.goal.name : c.goal.r.name;
  }

  // ---- stepping ----

  update(dt: number, liveDt: number): void {
    this.time += dt;
    const focus = this.host.focus();
    const R = this.radius();

    // who holds each runway: the player takes theirs, whatever an ambient jet was doing
    const mine = this.host.playerRunway();
    if (mine) this.lock.delete(lockOf(mine));

    if (liveDt > 0) {
      // overhead traffic
      this.overheadT -= liveDt;
      if (this.overheadT <= 0) {
        const near = allRunways().some((r) => r.major && Math.hypot(r.ax - focus.x, r.az - focus.z) < PORT_RANGE);
        const base = this.host.lively ? rand(12, 30) : rand(30, 70);
        this.overheadT = base * (this.host.night() > 0.5 ? 2 : 1) / (near ? 2 : 1);
        if (this.flights.filter((f) => f.overhead).length < MAX_OVERHEAD) this.spawnOverhead();
      }
      // airport life
      for (const r of allAirports()) {
        if (Math.hypot((r.ax + r.bx) / 2 - focus.x, (r.az + r.bz) / 2 - focus.z) > PORT_RANGE) continue;
        let t = this.portT.get(r);
        if (t === undefined) { t = rand(5, 25); this.portT.set(r, t); }
        t -= liveDt;
        if (t <= 0) {
          t = r.major ? rand(60, 120) : rand(240, 480);
          if (this.flights.filter((f) => f.rw && lockOf(f.rw) === r).length < MAX_PER_PORT) {
            if (Math.random() < 0.5) this.spawnDeparture(r); else this.spawnArrival(r);
          }
        }
        this.portT.set(r, t);
      }
      for (const r of [...this.portT.keys()]) if (!allAirports().includes(r)) this.portT.delete(r);
      this.stepFlypasts(liveDt);
    }

    for (const f of [...this.flights]) {
      if (f.crew) { this.syncCrew(f); this.draw(f, dt); continue; }
      if (liveDt > 0) this.stepFlight(f, liveDt);
      if (!this.flights.includes(f)) continue;
      // an airport that has gone out of memory takes its ground traffic with it
      if (f.rw && !allRunways().includes(f.rw) && (f.phase !== 'cruise')) { this.remove(f); continue; }
      const st = f.st;
      // measured from where the camera's line of sight crosses the flight's height, which is what's on screen
      const c = this.aim(st.y);
      const away = Math.hypot(st.x - c.x, st.z - c.z);
      const leaving = Math.sin(st.heading) * (st.x - c.x) + Math.cos(st.heading) * (st.z - c.z) > 0;
      if (f.phase === 'cruise' && away > R * 1.7 && leaving) { this.remove(f); continue; }
      if (away > 700) { this.remove(f); continue; }
      this.draw(f, dt);
    }
  }

  private stepFlight(f: Flight, dt: number): void {
    const st = f.st, def = f.def, j = def.jet!, r = f.rw;
    switch (f.phase) {
      case 'taxiOut':
      case 'taxiIn': {
        if (f.wait > 0) { f.wait -= dt; break; }
        const done = this.taxi(f, dt, j.taxi * 0.8);
        if (done) {
          if (f.phase === 'taxiOut') { f.phase = 'hold'; st.v = 0; }
          else { f.phase = 'wait'; f.wait = rand(20, 35); st.v = 0; }
        }
        break;
      }
      case 'hold': {
        // lined up on the centreline; roll once the runway is free
        const rh = f.dir === 1 ? r!.heading : wrap(r!.heading + Math.PI);
        st.heading += wrap(rh - st.heading) * Math.min(1, dt * 2);
        if (Math.abs(wrap(rh - st.heading)) < 0.05 && this.free(r!, f.id)) {
          this.take(r!, f.id);
          f.phase = 'roll';
        }
        break;
      }
      case 'roll': {
        st.v += j.groundAccel * 1.3 * dt;
        this.forward(st, dt);
        const rot = Math.min(1, Math.max(0, (st.v - j.rotate * 0.85) / (j.rotate * 0.15)));
        st.pitch = -0.09 * rot;
        if (st.v >= j.rotate) { f.phase = 'climb'; }
        break;
      }
      case 'climb': {
        st.v = Math.min(def.topSpeed * 0.8, st.v + def.accel * 0.6 * dt);
        this.forward(st, dt);
        st.y += def.climbRate * 0.7 * dt;
        st.pitch += (-0.14 - st.pitch) * Math.min(1, dt * 2);
        if (r && st.y - r.y > 3) this.release(r, f.id);
        const top = this.cruiseAlt(st.x, st.z);
        if (st.y >= top - 1) {
          f.phase = 'cruise';
          f.alt = top;
          f.rw = null;
          f.overhead = true;
          // turn gently onto a heading away from here, then hold it
          f.bearing = st.heading + rand(-0.8, 0.8);
        }
        break;
      }
      case 'cruise': {
        if (f.bearing !== null) {
          const d = wrap(f.bearing - st.heading);
          const rate = Math.sign(d) * Math.min(0.1, Math.abs(d));
          st.heading += rate * dt;
          st.roll = -Math.max(-0.3, Math.min(0.3, rate * st.v * 0.12));
          if (Math.abs(d) < 0.01) f.bearing = null;
        } else {
          st.heading += f.yawRate * dt;
          st.roll = -Math.max(-0.35, Math.min(0.35, f.yawRate * st.v * 0.12));
        }
        st.v += (f.cruiseV - st.v) * Math.min(1, dt * 0.3);
        this.forward(st, dt);
        st.y += (f.alt - st.y) * Math.min(1, dt * 0.5);
        // nose up while there is height to gain (a flypast pulling up past the venue)
        const climb = f.alt - st.y;
        st.pitch += ((climb > 2 ? -Math.min(0.35, climb * 0.025) : 0) - st.pitch) * Math.min(1, dt * 2);
        break;
      }
      case 'inbound': {
        // fly to a point on the extended centreline 45 tiles out, coming down toward the glide slope
        const [tx, tz] = f.dir === 1 ? [r!.ax, r!.az] : [r!.bx, r!.bz];
        const ux = r!.ux * f.dir, uz = r!.uz * f.dir;
        const ex = tx - ux * 45, ez = tz - uz * 45;
        const want = Math.atan2(ex - st.x, ez - st.z);
        const rh = Math.atan2(ux, uz);
        const dist = Math.hypot(ex - st.x, ez - st.z);
        // near the gate, blend onto the runway heading
        const aim = dist < 25 ? wrap(want + wrap(rh - want) * (1 - dist / 25)) : want;
        const d = wrap(aim - st.heading);
        const rate = Math.sign(d) * Math.min(0.35, Math.abs(d) * 1.5);
        st.heading += rate * dt;
        st.roll = -Math.max(-0.35, Math.min(0.35, rate * st.v * 0.1));
        st.v += (def.jet!.approach * 1.3 - st.v) * Math.min(1, dt * 0.3);
        this.forward(st, dt);
        const gate = r!.y + 45 * GLIDE + 1;
        st.y += (Math.max(gate, st.y - dist * 0.05) - st.y) * Math.min(1, dt * 0.4);
        if (dist < 20) st.gear = Math.min(1, st.gear + dt);
        if (dist < 6) {
          if (this.free(r!, f.id)) { this.take(r!, f.id); f.phase = 'final'; }
          else {
            // somebody's on the runway: go around, and away
            f.phase = 'cruise'; f.overhead = true; f.rw = null; f.alt = this.cruiseAlt(st.x, st.z); f.bearing = st.heading + 0.6;
          }
        }
        break;
      }
      case 'final': {
        const rh = f.dir === 1 ? r!.heading : wrap(r!.heading + Math.PI);
        const off = (st.x - r!.ax) * Math.cos(rh) - (st.z - r!.az) * Math.sin(rh);
        const d = wrap(rh - Math.max(-0.4, Math.min(0.4, off * 0.12)) - st.heading);
        st.heading += d * Math.min(1, dt * 2);
        st.roll = -d * 0.5;
        st.v += (j.approach - st.v) * Math.min(1, dt * 0.8);
        this.forward(st, dt);
        const fr = frameOf(r!, st.x, st.z);
        const out = f.dir === 1 ? -fr.along : fr.along - r!.len;
        const target = r!.y + Math.max(0, out) * GLIDE;
        st.y += (target - st.y) * Math.min(1, dt * 2);
        st.pitch += (-0.05 - st.pitch) * Math.min(1, dt * 2);
        st.gear = 1;
        if (out < 0 && st.y - r!.y < 0.1) { st.y = r!.y; f.phase = 'rollout'; }
        break;
      }
      case 'rollout': {
        st.v = Math.max(j.taxi * 0.8, st.v - j.groundBrake * dt);
        this.forward(st, dt);
        st.pitch += (0 - st.pitch) * Math.min(1, dt * 3);
        st.roll = 0;
        st.y = r!.y;
        if (st.v <= j.taxi * 0.8 + 0.01) {
          // off the runway to the taxi line, along it to a free stand
          const fr = frameOf(r!, st.x, st.z);
          const taken = new Set(this.flights.filter((g) => g !== f && g.rw?.stands === r!.stands).map((g) => g.stand));
          const k = r!.stands.findIndex((_, i) => !taken.has(i));
          this.release(r!, f.id);
          if (k < 0) { this.remove(f); return; }
          f.stand = k;
          const s = r!.stands[k], fs = frameOf(r!, s.x, s.z);
          f.path = [pointOf(r!, fr.along, r!.taxiOff), pointOf(r!, fs.along, r!.taxiOff), { x: s.x, z: s.z }];
          f.phase = 'taxiIn';
        }
        break;
      }
      case 'wait': {
        f.wait -= dt;
        if (f.wait <= 0) this.remove(f);
        break;
      }
      case 'show':
        // flown as one by its formation (stepFlypasts)
        return;
    }
    // engines: harder on the roll and the climb
    st.power = f.phase === 'roll' || f.phase === 'climb' ? 1 : f.phase === 'cruise' ? 0.7 : f.phase === 'taxiIn' || f.phase === 'taxiOut' ? 0.3 : 0.45;
    if (f.phase === 'climb' || f.phase === 'cruise') st.gear = Math.max(0, st.gear - dt * (st.y - (r?.y ?? 0) > 3 ? 1 : 0));
  }

  private forward(st: FlyState, dt: number): void {
    st.x += Math.sin(st.heading) * st.v * dt;
    st.z += Math.cos(st.heading) * st.v * dt;
  }

  /** Follow the taxi route; true once at its end. */
  private taxi(f: Flight, dt: number, speed: number): boolean {
    const st = f.st;
    const p = f.path[0];
    if (!p) return true;
    const dx = p.x - st.x, dz = p.z - st.z, d = Math.hypot(dx, dz);
    if (d < 0.25) { f.path.shift(); return f.path.length === 0; }
    const want = Math.atan2(dx, dz);
    st.heading += Math.max(-1.2 * dt, Math.min(1.2 * dt, wrap(want - st.heading)));
    // slow for a sharp turn
    st.v += ((Math.abs(wrap(want - st.heading)) > 0.5 ? speed * 0.35 : speed) - st.v) * Math.min(1, dt * 2);
    this.forward(st, Math.min(dt, d / Math.max(0.1, st.v)));
    st.wheelSpin += st.v * dt * 6;
    st.roll = 0;
    st.pitch = 0;
    return false;
  }

  /**
   * Where a plane's shadow lands: down the sun's ray from the plane to the first ground or roof it meets. The
   * height was once read straight under the plane, and the shadow, cast away along the sun from there, jumped
   * sideways and up whenever the plane crossed a building; this way it runs along the ground and climbs onto a
   * roof only where the ray really meets one.
   */
  private shadowFall(x: number, y: number, z: number, sun: THREE.Vector3): number {
    const sy = Math.max(0.12, sun.y);
    const ground = this.host.ground(x, z);
    for (let h = y - 0.4; h > ground - 2; h -= 0.4) {
      const k = (y - h) / sy;
      const g = this.host.ground(x - sun.x * k, z - sun.z * k);
      if (g >= h) return g;
    }
    return ground;
  }

  private draw(f: Flight, dt: number): void {
    const st = f.st;
    poseVehicleMesh(f.mesh, st, f.def, OPEN_SEA);
    // on the ground the airfield is level: the shadow sits right under the wheels
    const grounded = f.phase === 'taxiOut' || f.phase === 'taxiIn' || f.phase === 'hold' || f.phase === 'roll' || f.phase === 'rollout' || f.phase === 'wait';
    const gy = grounded ? st.y : this.host.ground(st.x, st.z);
    const night = this.host.night();
    const sun = this.host.sun();
    f.shadow.place(st.x, st.y, st.z, st.heading, grounded ? gy : this.shadowFall(st.x, st.y, st.z, sun), sun, 1 - night);
    // contrails behind each engine, once it's up high and the air's dry; a display team's smoke all through its pass
    const high = f.phase === 'show' || (f.trails.length > 0 && f.engines.length === 1 && f.phase === 'cruise') || (st.y - gy > 12 && f.phase === 'cruise' && this.host.rain() < 0.3);
    const back = f.def.halfLen * 0.9;
    const wind = this.host.wind();
    f.trails.forEach((t, k) => {
      const o = f.engines[k] ?? 0;
      const x = st.x - Math.sin(st.heading) * back + Math.cos(st.heading) * o;
      const z = st.z - Math.cos(st.heading) * back - Math.sin(st.heading) * o;
      t.update(dt, x, st.y, z, high, Math.sin(wind), Math.cos(wind), 1 - night * 0.7);
    });
    for (const sp of f.mesh.spinners) sp.obj.rotation[sp.axis] += sp.speed * st.power * dt;
  }

  /** How loud the nearest flight is at the focus, and how hard its engines are working. */
  noise(): { level: number; pitch: number } {
    const f0 = this.host.focus();
    let level = 0, pitch = 0;
    for (const f of this.flights) {
      const d = Math.hypot(f.st.x - f0.x, f.st.y - f0.y, f.st.z - f0.z);
      const l = (1 / (1 + d / 30)) * (f.phase === 'wait' ? 0.2 : f.phase === 'roll' || f.phase === 'climb' || f.phase === 'show' ? 1 : 0.75);
      if (l > level) { level = l; pitch = f.st.power; }
    }
    return { level, pitch };
  }

  /** What a flight is doing, in words for its card, and how high it is over the ground in feet (0 on the ground). */
  describe(f: Flight): { doing: string; feet: number } {
    const doing: Record<Phase, string> = {
      taxiOut: 'Taxiing out', hold: 'Holding short', roll: 'On the take-off roll', climb: 'Climbing out',
      cruise: 'Cruising', inbound: 'Descending in', final: 'On final approach',
      rollout: 'Just landed', taxiIn: 'Taxiing in', wait: 'At the stand', show: 'In formation · flypast',
    };
    const up = f.phase === 'climb' || f.phase === 'cruise' || f.phase === 'inbound' || f.phase === 'final' || f.phase === 'show';
    const gy = this.host.ground(f.st.x, f.st.z);
    return { doing: doing[f.phase], feet: up ? Math.max(0, Math.round(((f.st.y - gy) * 1000) / 50) * 50) : 0 };
  }

  clear(): void {
    for (const f of [...this.flights]) this.remove(f);
    this.lock.clear();
    this.portT.clear();
    this.flypasts = [];
  }
}

