import type { BuildingKind } from '../../../world/tiles';
import { hex, type RGB } from '../../../world/biomes';
import { Vis } from '../../nightLights';
import { BRIGHT, DARK, GLASS_LIGHT, METAL, WATER, WHITE, pick, type Draw, type Kit } from '../kit';
import { LIDO_BOARDS, LIDO_HALL, LIDO_SLIDES, WATER_Y, blockOf, freeArea, layout, type P3 } from '../lidoPlan';

/**
 * Alternatives for the lido (venues.ts draws the kind's own): a racing lido with a tower of diving boards and
 * a stand, a family lido with a flume and a speed slide, and an aquatic centre whose glass roof slides back
 * and whose walls fold away for the summer. Everything is where lidoPlan.ts says, so the bathers
 * (game/pools.ts) and a swim meet find the boards, slides and lanes that are drawn.
 *
 * The changing block stands at the +x end as the original's does, inside the kind's solid shape; the rest is
 * laid out along the longer side of the ground left (turned a quarter on a deep lot). Out of doors the water
 * is in from spring to autumn and drained in winter; the hall's is in all year.
 */

const TILES = hex(0xeaf2f2), DRAINED = hex(0xcfd0cc), CONCRETE = hex(0xd9d6cc), DEEP = hex(0x2f8fc4);
const LANE = hex(0x1d4f8a), PLANK = hex(0x2f7fb5), SCORE = hex(0x1f2329), AMBER = hex(0xffb347);
const SEATS = [0x2f7fb5, 0xe2412f, 0xf2c14e];

/** The changing rooms at the +x end, with a roof in the lido's colours; `flat` for a plain slab. */
function changing(k: Kit, W: number, D: number, wall: RGB, roof: RGB, flat = false): void {
  const c = blockOf(W, D);
  k.box(c.cx, 0, c.cz, c.w, 0.3, c.d, wall);
  if (flat) { k.box(c.cx, 0.3, c.cz, c.w + 0.06, 0.03, c.d + 0.06, roof); return; }
  for (let i = 0; i < 5; i++) k.box(c.cx, 0.3, c.cz - c.d / 2 + (i + 0.5) * (c.d / 5), c.w + 0.04, 0.03, c.d / 5, i % 2 ? wall : roof);
  // the door the bathers come and go by, on the water's side
  k.box(c.cx - c.w / 2 - 0.005, 0, c.cz + Math.min(0.3, c.d / 2 - 0.1), 0.01, 0.2, 0.12, DARK);
}

/** A rectangular pool, x0..x1 × z0..z1: tiled rim, the water (when it is in), a drained floor when it isn't. */
function pool(k: Kit, x0: number, z0: number, x1: number, z1: number, outdoor: boolean): void {
  const cx = (x0 + x1) / 2, cz = (z0 + z1) / 2, w = x1 - x0, d = z1 - z0;
  k.box(cx, 0, cz, w + 0.12, 0.05, d + 0.12, TILES);
  k.tagged(outdoor ? Vis.NotWinter : Vis.Always, () => k.box(cx, 0.02, cz, w, WATER_Y - 0.02, d, WATER));
  if (outdoor) k.tagged(Vis.Winter, () => k.box(cx, 0.002, cz, w, 0.03, d, DRAINED));
}

/** A round pool: rim, water, drained floor. */
function roundPool(k: Kit, x: number, z: number, r: number): void {
  k.cyl(x, 0, z, r + 0.06, 0.05, TILES, 14);
  k.tagged(Vis.NotWinter, () => k.cyl(x, 0.02, z, r, WATER_Y - 0.02, WATER, 14));
  k.tagged(Vis.Winter, () => k.cyl(x, 0.002, z, r, 0.03, DRAINED, 14));
}

/** Lines on the water between `n` lanes running along x, and the T at each end. */
function laneLines(k: Kit, x0: number, z0: number, x1: number, z1: number, n: number, tag: Vis): void {
  k.tagged(tag, () => k.detail(() => {
    const lane = (z1 - z0) / n;
    for (let i = 0; i < n; i++) {
      const z = z0 + lane * (i + 0.5);
      k.box((x0 + x1) / 2, WATER_Y, z, x1 - x0 - 0.16, 0.003, 0.018, LANE);
      for (const x of [x0 + 0.08, x1 - 0.08]) k.box(x, WATER_Y, z, 0.018, 0.003, 0.07, LANE);
    }
  }));
}

/** Starting blocks on the rim at the +x end, one a lane. */
function startBlocks(k: Kit, x1: number, z0: number, z1: number, n: number): void {
  const lane = (z1 - z0) / n;
  for (let i = 0; i < n; i++) k.box(x1 + 0.035, 0.05, z0 + lane * (i + 0.5), 0.05, 0.035, 0.05, WHITE, i % 2 ? WHITE : hex(0x2f7fb5));
}

/** Loungers along a line, lying along x (yaw ±π/2) or z. */
function loungers(k: Kit, list: { x: number; z: number; yaw: number }[], col: RGB): void {
  k.detail(() => {
    for (const l of list) {
      const along = Math.abs(Math.sin(l.yaw)) > 0.5;
      k.box(l.x, 0.02, l.z, along ? 0.18 : 0.08, 0.02, along ? 0.08 : 0.18, col);
    }
  });
}

/** A lifeguard's high chair, its seat at y. */
function guardChair(k: Kit, p: P3, col: RGB): void {
  const [x, y, z] = p;
  for (const s of [-1, 1]) k.bar([x + s * 0.04, 0, z + 0.04], [x + s * 0.03, y, z], 0.008, WHITE);
  k.box(x, y - 0.01, z, 0.08, 0.02, 0.07, col);
  k.box(x, y, z - 0.04, 0.08, 0.07, 0.015, col);
}

/** A stand along the back: tiers stepping up away from the water. */
function stand(k: Kit, s: NonNullable<ReturnType<typeof layout>['stand']>): void {
  const deep = (s.z1 - s.z0) / s.tiers, w = s.x1 - s.x0, x = (s.x0 + s.x1) / 2;
  for (let t = 0; t < s.tiers; t++) {
    const z = s.z1 - deep * (t + 0.5);
    k.box(x, 0, z, w, s.rise * (t + 1), deep, CONCRETE, hex(SEATS[t % SEATS.length]));
  }
}

/** A scoreboard's face at (x, y, z): dark, a row of amber lamps a lane; it faces +z (turned `yaw`). */
function scoreboard(k: Kit, x: number, y: number, z: number, yaw: number, lanes: number, posts: boolean): void {
  k.turned(yaw, () => {
    // (x, z) given in the frame before the turn: turn them with it
    const c = Math.cos(-yaw), s = Math.sin(-yaw);
    const lx = x * c + z * s, lz = -x * s + z * c;
    if (posts) for (const sx of [-0.14, 0.14]) k.box(lx + sx, 0, lz - 0.01, 0.025, y, 0.025, METAL);
    k.box(lx, y - 0.02, lz, 0.36, 0.2, 0.03, SCORE);
    for (let i = 0; i < lanes; i++) {
      k.glowBox(lx - 0.14 + (0.28 * i) / Math.max(1, lanes - 1), y + 0.1, lz + 0.016, 0.026, 0.026, 0.006, hex(0x6a5a3a), [8, 21, 1.4], AMBER);
    }
    k.box(lx, y + 0.17, lz + 0.016, 0.24, 0.025, 0.006, WHITE);
  });
}

// ---- 1. the racing lido: a tower of boards over the diving well, a stand, a scoreboard ----------------------------

const boards: Draw = (k, W, D, _b, r) => {
  const A = freeArea(W, D), L = layout(LIDO_BOARDS, A);
  changing(k, W, D, WHITE, hex(0x2f7fb5), true);
  k.turned(A.rot ? Math.PI / 2 : 0, () => {
    const { px0, px1, pz0, pz1 } = L, lanes = Math.max(3, Math.min(6, Math.floor((pz1 - pz0) / 0.17)));
    pool(k, px0, pz0, px1, pz1, true);
    // the diving well: deeper water at the boards' end, no lanes over it
    k.tagged(Vis.NotWinter, () => k.detail(() => k.box(px0 + 0.22, WATER_Y, (pz0 + pz1) / 2, 0.42, 0.002, pz1 - pz0, DEEP)));
    laneLines(k, px0 + 0.44, pz0, px1, pz1, lanes, Vis.NotWinter);
    startBlocks(k, px1, pz0, pz1, lanes);
    // the boards: each on its own concrete pier, the platform's the tallest, with a ladder up its side
    for (const b of L.boards) {
      const [tx, y, z] = b.top, tip = b.tip[0];
      k.box(tx - 0.02, 0, z, 0.11, y - 0.015, 0.1, CONCRETE);
      k.box((tx - 0.06 + tip) / 2, y - 0.015, z, tip - tx + 0.06, 0.022, b.spring ? 0.06 : 0.11, b.spring ? PLANK : WHITE, b.spring ? hex(0x6fb0e0) : WHITE);
      const lz = b.foot.z - 0.03;
      for (const sx of [-0.03, 0.03]) k.bar([b.foot.x + sx, 0, lz], [b.foot.x + sx, y + 0.08, lz], 0.006, METAL);
      if (!b.spring) {
        // rails round the platform
        for (const sz of [-0.05, 0.05]) k.bar([tx - 0.05, y + 0.07, z + sz], [tip - 0.06, y + 0.07, z + sz], 0.005, METAL);
      }
    }
    if (L.stand) stand(k, L.stand);
    if (L.board) scoreboard(k, L.board[0], L.board[1], L.board[2], L.boardYaw, lanes, true);
    loungers(k, L.loungers, pick(r, BRIGHT));
    if (L.guard) guardChair(k, L.guard, hex(0xe2412f));
  });
};

// ---- 2. the family lido: a flume into a splash pool, a speed slide into the deep end -----------------------------

const slides: Draw = (k, W, D, _b, r) => {
  const A = freeArea(W, D), L = layout(LIDO_SLIDES, A);
  const roof = pick(r, BRIGHT), flume = pick(r, [0xf2c14e, 0xe2412f, 0x2bb3a3]), speed = pick(r, [0x8e5cc7, 0x2f7fb5, 0xf28c38]);
  changing(k, W, D, hex(0xf6f0de), roof);
  k.turned(A.rot ? Math.PI / 2 : 0, () => {
    const { px0, px1, pz0, pz1 } = L;
    pool(k, px0, pz0, px1, pz1, true);
    // a shallow end, paler, where the steps go in
    k.tagged(Vis.NotWinter, () => k.detail(() => k.box(px1 - (px1 - px0) * 0.15, WATER_Y, (pz0 + pz1) / 2, (px1 - px0) * 0.3, 0.002, pz1 - pz0, hex(0x9fdcef))));
    for (const c of L.rounds) roundPool(k, c.x, c.z, c.r);
    // the tower: four legs, a deck, a peaked canopy, the stair up its side
    const t = L.tower, hw = t.w / 2, hd = t.d / 2;
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([t.x + sx * hw, 0, t.z + sz * hd], [t.x + sx * hw, t.h + 0.14, t.z + sz * hd], 0.012, METAL);
    k.box(t.x, t.h - 0.025, t.z, t.w + 0.02, 0.025, t.d + 0.02, hex(0xd9d6cc));
    k.cone(t.x, t.h + 0.14, t.z, t.w * 0.85, 0.12, roof, 4);
    const foot = L.slides[0].foot, top = L.slides[0].top;
    k.bar([foot.x, 0, foot.z], [top[0], top[1] - 0.02, top[2]], 0.03, CONCRETE);
    // the flume, a tube coiling down on posts; the speed slide, a chute over a hump
    const run = (path: P3[], col: RGB, rad: number) => {
      for (let i = 1; i < path.length; i++) k.bar(path[i - 1], path[i], rad, col);
      for (let i = 2; i < path.length - 1; i += 3) if (path[i][1] > 0.1) k.bar([path[i][0], 0, path[i][2]], [path[i][0], path[i][1] - 0.03, path[i][2]], 0.008, METAL);
    };
    run(L.slides[0].path, flume, 0.032);
    run(L.slides[1].path, speed, 0.028);
    // umbrellas between the loungers along the front
    loungers(k, L.loungers, WHITE);
    L.loungers.forEach((l, i) => {
      if (i % 2) return;
      k.bar([l.x + 0.11, 0, l.z], [l.x + 0.11, 0.2, l.z], 0.005, WHITE);
      k.cone(l.x + 0.11, 0.17, l.z, 0.11, 0.06, hex(BRIGHT[i % BRIGHT.length]), 6);
    });
    if (L.guard) guardChair(k, L.guard, roof);
  });
};

// ---- 3. the aquatic centre: lane ropes in a glass hall that opens for the summer ---------------------------------

const hall: Draw = (k, W, D, _b, r) => {
  const A = freeArea(W, D), L = layout(LIDO_HALL, A);
  const frame = pick(r, [0xf4f2ec, 0x3a3f45, 0x2f7fb5]);
  changing(k, W, D, hex(0xe8e4da), hex(0x8c8a84), true);
  k.turned(A.rot ? Math.PI / 2 : 0, () => {
    const { px0, px1, pz0, pz1 } = L, lanes = Math.max(3, Math.min(6, Math.floor((pz1 - pz0) / 0.17)));
    pool(k, px0, pz0, px1, pz1, false);
    // lane ropes of floats, red at the ends, white between
    const lane = (pz1 - pz0) / lanes;
    k.detail(() => {
      for (let i = 1; i < lanes; i++) {
        const z = pz0 + lane * i, y = WATER_Y + 0.004, x0 = px0 + 0.02, x1 = px1 - 0.02, e = (x1 - x0) * 0.18;
        k.bar([x0, y, z], [x0 + e, y, z], 0.007, hex(0xe2412f));
        k.bar([x0 + e, y, z], [x1 - e, y, z], 0.007, i % 2 ? WHITE : hex(0x2f7fb5));
        k.bar([x1 - e, y, z], [x1, y, z], 0.007, hex(0xe2412f));
      }
    });
    startBlocks(k, px1, pz0, pz1, lanes);
    if (L.stand) stand(k, L.stand);
    if (L.board) scoreboard(k, L.board[0], L.board[1], L.board[2], L.boardYaw, lanes, false);
    if (L.guard) guardChair(k, L.guard, hex(0xe2412f));
    // the hall: columns down both sides, an eave beam, arched ribs; glass between the ribs and down the sides
    const { ax0, ax1, az0, az1 } = A, eave = 0.5, rise = Math.min(0.32, (az1 - az0) * 0.2), zc = (az0 + az1) / 2, half = (az1 - az0) / 2;
    const bays = Math.max(3, Math.round((ax1 - ax0) / 0.6)), bay = (ax1 - ax0) / bays, SEG = 6;
    const arc = (x: number, j: number): P3 => {
      const a = Math.PI * (1 - j / SEG);
      return [x, eave + Math.sin(a) * rise, zc + Math.cos(a) * half];
    };
    for (let i = 0; i <= bays; i++) {
      const x = ax0 + i * bay;
      for (const z of [az0 + 0.01, az1 - 0.01]) k.box(x, 0, z, 0.035, eave, 0.035, frame);
      for (let j = 0; j < SEG; j++) k.bar(arc(x, j), arc(x, j + 1), 0.012, frame);
    }
    for (const z of [az0 + 0.01, az1 - 0.01]) k.box((ax0 + ax1) / 2, eave - 0.03, z, ax1 - ax0, 0.03, 0.04, frame);
    const inside: P3 = [(ax0 + ax1) / 2, eave * 0.5, zc];
    for (let i = 0; i < bays; i++) {
      const xa = ax0 + i * bay, xb = xa + bay;
      // the roof slides back over the last bay for the summer: that one is glazed all year
      k.tagged(i === bays - 1 ? Vis.Always : Vis.NotSummer, () => {
        for (let j = 0; j < SEG; j++) k.quad(arc(xa, j), arc(xb, j), arc(xb, j + 1), arc(xa, j + 1), GLASS_LIGHT, inside);
      });
    }
    // the gable ends, glazed above the eaves
    for (const x of [ax0, ax1]) {
      for (let j = 0; j < SEG; j++) k.tri([x, eave, zc], arc(x, j), arc(x, j + 1), GLASS_LIGHT, [x + (x === ax0 ? 0.05 : -0.05), eave, zc]);
    }
    // the side and end walls: glass doors that fold away in summer, a low kerb under them always
    k.tagged(Vis.NotSummer, () => {
      for (const z of [az0 + 0.01, az1 - 0.01]) k.box((ax0 + ax1) / 2, 0.06, z, ax1 - ax0, eave - 0.09, 0.012, GLASS_LIGHT);
      for (const x of [ax0, ax1]) k.box(x, 0.06, zc, 0.012, eave - 0.09, az1 - az0, GLASS_LIGHT);
    });
    for (const z of [az0 + 0.01, az1 - 0.01]) k.box((ax0 + ax1) / 2, 0, z, ax1 - ax0, 0.06, 0.03, hex(0xb9b1a0));
  });
};

export const LIDO_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  lido: [boards, slides, hall],
};
