import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, TAU, TRUNK, WARM_GLOW, WHITE, WOOD, win, type Draw, type Kit, type P3 } from '../kit';
import { flag } from '../civic';

/**
 * The Sands: mud-brick and canvas for the desert towns — a souk under striped awnings, a caravanserai
 * round its well, a wind tower, the kasbah, a tent camp, a date grove, and the pyramids.
 */

const MUD = hex(0xd9b584), MUD_L = hex(0xe8cfa4), MUD_D = hex(0xb98d5e), RED_MUD = hex(0xc58a58), RED_D = hex(0xa4683e);
const PAVE = hex(0xdcc69a), DOOR = hex(0x4a3222), FRONDS = hex(0x5a8a3a), FRONDS2 = hex(0x6f9a42), DATES = hex(0xc2682a);
const CAMEL = hex(0xc49a64), TENT = hex(0x3e3230), TENT_D = hex(0x2c2422), FIRE = hex(0xff9a40), FLAME = hex(0xf2b04a);
const LIME = hex(0xe6d2a2), LIME2 = hex(0xdcc592), WORN = hex(0xcfb07e), GOLD = hex(0xe8b93a), BRONZE = hex(0x6a4a2a);
const AWN = [0xc0392b, 0x2f6fa8, 0xe8b33a, 0x3f8a5a, 0x8e3a6a];
const RUGS = [0xa8322a, 0x2f5a8a, 0xc88a2a, 0x6a2a5a, 0x2f7a5a];
const SPICE = [0xd84a2a, 0xe8b030, 0x7a9a3a, 0x8a4a2a, 0xf2e6c8];
const TORCH: Sched = [17.8, 30, 2.6];

/** A four-sided tapering block (w0 at the foot, w1 at the head), for towers, pylons and obelisks. */
function frustum(k: Kit, x: number, y: number, z: number, w0: number, d0: number, w1: number, d1: number, h: number, col: RGB, top: RGB = col): void {
  const I: P3 = [x, y + h / 2, z], y1 = y + h;
  const a: P3[] = [[x - w0 / 2, y, z - d0 / 2], [x + w0 / 2, y, z - d0 / 2], [x + w0 / 2, y, z + d0 / 2], [x - w0 / 2, y, z + d0 / 2]];
  const b: P3[] = [[x - w1 / 2, y1, z - d1 / 2], [x + w1 / 2, y1, z - d1 / 2], [x + w1 / 2, y1, z + d1 / 2], [x - w1 / 2, y1, z + d1 / 2]];
  for (let i = 0; i < 4; i++) k.quad(a[i], a[(i + 1) % 4], b[(i + 1) % 4], b[i], col, I);
  k.quad(b[0], b[1], b[2], b[3], top, I);
}

/** A row of merlons along a wall top from (x0, z0) to (x1, z1). */
function merlons(k: Kit, x0: number, z0: number, x1: number, z1: number, y: number, col: RGB, step = 0.25, s = 0.08): void {
  const n = Math.max(1, Math.round(Math.hypot(x1 - x0, z1 - z0) / step));
  for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, y, z0 + ((z1 - z0) * i) / n, s, s, s, col);
}

/** A camel standing along x (dir ±1 the way it looks) or along z. */
function camel(k: Kit, x: number, z: number, alongX: boolean, dir: number, col = CAMEL): void {
  const p = (f: number, y: number, s: number): P3 => alongX ? [x + f * dir, y, z + s] : [x + s, y, z + f * dir];
  const bx = (f: number, y: number, s: number, l: number, h: number, w: number, c: RGB) => {
    const [px, , pz] = p(f, 0, s);
    if (alongX) k.box(px, y, pz, l, h, w, c); else k.box(px, y, pz, w, h, l, c);
  };
  bx(0, 0.17, 0, 0.3, 0.1, 0.11, col);
  k.hip(...p(0, 0.27, 0), alongX ? 0.16 : 0.1, 0.09, alongX ? 0.1 : 0.16, col);
  for (const f of [-0.11, 0.11]) for (const s of [-0.04, 0.04]) bx(f, 0, s, 0.025, 0.17, 0.025, scale(col, 0.85));
  k.bar(p(0.14, 0.23, 0), p(0.23, 0.36, 0), 0.025, col);
  bx(0.26, 0.33, 0, 0.1, 0.05, 0.05, col);
}

/** A date palm: a tall straight trunk and a crown of drooping fronds with the fruit hanging under it. */
function datePalm(k: Kit, x: number, z: number, h: number, r: () => number): void {
  k.cyl(x, 0, z, 0.03, h, scale(TRUNK, 1.1), 5);
  const I: P3 = [x, h - 0.3, z], turn = r() * TAU;
  for (let f = 0; f < 8; f++) {
    const a = turn + (f / 8) * TAU, c = Math.cos(a), s = Math.sin(a), up = f % 2 ? 0.03 : 0.08;
    const mid: P3 = [x + c * 0.17, h + up, z + s * 0.17];
    k.quad([x, h, z], [mid[0] - s * 0.055, mid[1], mid[2] + c * 0.055], [x + c * 0.36, h - 0.14, z + s * 0.36], [mid[0] + s * 0.055, mid[1], mid[2] - c * 0.055], f % 2 ? FRONDS : FRONDS2, I);
  }
  k.box(x, h - 0.12, z, 0.1, 0.08, 0.1, DATES);
}

/** A torch bowl on a short pillar, burning after dark. */
function torch(k: Kit, x: number, z: number, h = 0.35, s = 1): void {
  k.box(x, 0, z, 0.12 * s, h, 0.12 * s, LIME2);
  k.cyl(x, h, z, 0.1 * s, 0.07 * s, BRONZE, 6);
  k.glowBox(x, h + 0.07 * s, z, 0.09 * s, 0.1 * s, 0.09 * s, FLAME, TORCH, FIRE);
}

// ---- 1. souk -----------------------------------------------------------------------------------

const souk: Draw = (k, W, D, _b, r) => {
  // the aisle down the middle, rugs laid out on it
  k.box(0, 0, 0, W - 0.1, 0.01, 0.5, PAVE);
  const n = Math.max(3, Math.floor((W - 0.2) / 0.8)), cell = (W - 0.2) / n;
  for (const side of [-1, 1]) for (let i = 0; i < n; i++) {
    const x = -W / 2 + 0.1 + cell * (i + 0.5), x0 = x - cell / 2 + 0.04, x1 = x + cell / 2 - 0.04;
    const zo = side * (D / 2 - 0.08), zi = side * 0.3, awn = hex(AWN[Math.floor(r() * AWN.length)]);
    for (const px of [x0 + 0.02, x1 - 0.02]) {
      k.box(px, 0, zo, 0.03, 0.52, 0.03, WOOD);
      k.box(px, 0, zi, 0.03, 0.4, 0.03, WOOD);
    }
    // the striped awning, sloping down to the aisle
    for (let s = 0; s < 4; s++) {
      const a = x0 + ((x1 - x0) * s) / 4, bb = x0 + ((x1 - x0) * (s + 1)) / 4;
      k.quad([a, 0.52, zo], [bb, 0.52, zo], [bb, 0.4, zi], [a, 0.4, zi], s % 2 ? WHITE : awn, [x, 0, (zo + zi) / 2]);
    }
    k.box(x, 0.35, zi, x1 - x0, 0.05, 0.012, awn);
    // the counter and what is on it
    k.box(x, 0, side * 0.45, cell - 0.2, 0.14, 0.14, WOOD);
    for (let g = 0; g < 3; g++) k.hip(x - cell * 0.25 + g * cell * 0.25, 0.14, side * 0.45, 0.1, 0.06, 0.09, hex(SPICE[Math.floor(r() * SPICE.length)]));
    // a carpet hung at the back of the stall
    k.box(x, 0.08, side * (D / 2 - 0.12), cell * 0.5, 0.34, 0.012, hex(RUGS[Math.floor(r() * RUGS.length)]));
    if (r() < 0.5) k.box(x, 0.01, side * 0.12, cell * 0.45, 0.004, 0.2, hex(RUGS[Math.floor(r() * RUGS.length)]));
    k.glowBox(x, 0.3, zi, 0.04, 0.05, 0.04, FLAME, [17.8, 23.5, 2.2], WARM_GLOW);
  }
  // water jars at the ends of the aisle
  for (const sx of [-1, 1]) for (let j = 0; j < 2; j++) k.cyl(sx * (W / 2 - 0.1), 0, -0.08 + j * 0.14, 0.05, 0.12, RED_MUD, 6);
};

// ---- 2. caravanserai ---------------------------------------------------------------------------

const caravanserai: Draw = (k, W, _D, b, r) => {
  const H = 0.6, T = 0.36, o = W / 2 - 0.12, i = o - T, g = 0.5, dark = scale(DOOR, 0.8);
  k.box(0, 0, 0, 2 * i, 0.008, 2 * i, PAVE);
  // the four ranges of rooms round the court, the front one split by the gate
  k.box(0, 0, -(o - T / 2), 2 * o, H, T, MUD, MUD_L);
  for (const sx of [-1, 1]) {
    k.box(sx * (o - T / 2), 0, 0.0, T, H, 2 * i, MUD, MUD_L);
    k.box(sx * (g / 2 + (o - g / 2) / 2), 0, o - T / 2, o - g / 2, H, T, MUD, MUD_L);
  }
  // the arcade inside: dark bays behind a row of piers under a ledge
  const arcade = (face: number) => {
    const n = 7, span = 2 * i;
    for (let j = 0; j < n; j++) {
      const t = -i + (span * (j + 0.5)) / n;
      if (face === 1 && Math.abs(t) < g / 2 + 0.05) continue;
      const [px, pz] = face === 3 ? [t, -i] : face === 1 ? [t, i] : face === 0 ? [i, t] : [-i, t];
      const along = face === 1 || face === 3;
      if (along) k.box(px, 0, pz, span / n - 0.08, 0.32, 0.02, dark); else k.box(px, 0, pz, 0.02, 0.32, span / n - 0.08, dark);
      if (j % 2 === 0) win(k, b, r, px, 0.06, pz + (face === 3 ? 0.012 : face === 1 ? -0.012 : 0), 0.08, 0.14, face === 3 ? 1 : face === 1 ? 3 : face === 0 ? 2 : 0, DOOR);
      const [qx, qz] = along ? [px + span / n / 2, pz] : [px, pz + span / n / 2];
      if (j < n - 1) k.box(qx, 0, qz, 0.07, 0.36, 0.07, MUD_L);
    }
    const [lx, lz] = face === 3 ? [0, -i + 0.06] : face === 1 ? [0, i - 0.06] : face === 0 ? [i - 0.06, 0] : [-i + 0.06, 0];
    if (face === 1) for (const sx of [-1, 1]) k.box(sx * (g / 2 + (i - g / 2) / 2), 0.36, lz, i - g / 2, 0.05, 0.14, MUD_D);
    else if (face === 3) k.box(lx, 0.36, lz, span, 0.05, 0.14, MUD_D);
    else k.box(lx, 0.36, lz, 0.14, 0.05, span, MUD_D);
  };
  for (const f of [0, 1, 2, 3]) arcade(f);
  // the parapet
  merlons(k, -o + 0.04, -o + 0.04, o - 0.04, -o + 0.04, H, MUD_L, 0.3);
  for (const sx of [-1, 1]) merlons(k, sx * (o - 0.04), -o + 0.34, sx * (o - 0.04), o - 0.04, H, MUD_L, 0.3);
  // the gate: a tall portal with a dark arch through it
  for (const sx of [-1, 1]) k.box(sx * (g / 2 + 0.08), 0, o - T / 2 + 0.04, 0.16, H + 0.34, T + 0.08, MUD_L);
  k.box(0, 0.5, o - T / 2 + 0.04, g, H + 0.34 - 0.5, T + 0.08, MUD_L);
  k.box(0, 0.5, o + 0.12, g - 0.06, 0.22, 0.008, hex(0x2f6fa8));
  k.gable(0, 0.44, o - T / 2 + 0.04, g, 0.06, T + 0.1, dark, dark);
  for (const sx of [-1, 1]) k.glowBox(sx * (g / 2 + 0.08), 0.38, o + 0.1, 0.05, 0.06, 0.03, FLAME, TORCH, FIRE);
  // small windows high on the outside walls
  for (const sx of [-1, 1]) for (const z of [-0.6, 0, 0.6]) win(k, b, r, sx * o, 0.38, z, 0.08, 0.1, sx > 0 ? 0 : 2, DOOR);
  // the well, two camels and their loads
  k.cyl(0, 0, -0.1, 0.13, 0.12, LIME2, 8);
  k.disc(0, 0.121, -0.1, 0.1, hex(0x2f5a6a), 8);
  for (const sx of [-1, 1]) k.box(sx * 0.12, 0.12, -0.1, 0.025, 0.2, 0.025, WOOD);
  k.box(0, 0.31, -0.1, 0.28, 0.025, 0.025, WOOD);
  camel(k, -0.45, 0.35, true, 1);
  camel(k, 0.5, -0.45, false, -1, scale(CAMEL, 0.9));
  for (let j = 0; j < 3; j++) k.box(0.45 + j * 0.13, 0, 0.45, 0.11, 0.08 + (j % 2) * 0.04, 0.11, hex(RUGS[j]));
};

// ---- 3. wind tower -----------------------------------------------------------------------------

const windTower: Draw = (k, _W, _D, b, r) => {
  // the house under it
  k.box(0.08, 0, 0.1, 0.7, 0.34, 0.6, MUD, MUD_L);
  merlons(k, -0.24, 0.39, 0.4, 0.39, 0.34, MUD_L, 0.16, 0.05);
  k.box(0.2, 0, 0.405, 0.14, 0.22, 0.012, DOOR);
  win(k, b, r, -0.08, 0.14, 0.4, 0.1, 0.1, 1, DOOR);
  win(k, b, r, 0.43, 0.14, 0.2, 0.1, 0.1, 0, DOOR);
  // the badgir: a square tower, vented at the top, poles through it
  const tx = -0.16, tz = -0.22, s = 0.28, top = 1.3;
  k.box(tx, 0, tz, s, top, s, MUD_L, MUD_L);
  for (const f of [0, 1, 2, 3]) {
    for (const o of [-0.08, 0, 0.08]) {
      const [x, z] = f === 1 ? [tx + o, tz + s / 2] : f === 3 ? [tx + o, tz - s / 2] : f === 0 ? [tx + s / 2, tz + o] : [tx - s / 2, tz + o];
      if (f % 2) k.box(x, 0.98, z, 0.045, 0.24, 0.012, DARK); else k.box(x, 0.98, z, 0.012, 0.24, 0.045, DARK);
    }
  }
  k.box(tx, 0.92, tz, s + 0.04, 0.03, s + 0.04, MUD_D);
  k.box(tx, top, tz, s + 0.06, 0.04, s + 0.06, MUD_D);
  merlons(k, tx - s / 2, tz - s / 2, tx + s / 2, tz - s / 2, top + 0.04, MUD_L, 0.14, 0.05);
  merlons(k, tx - s / 2, tz + s / 2, tx + s / 2, tz + s / 2, top + 0.04, MUD_L, 0.14, 0.05);
  for (const y of [0.55, 0.8]) {
    k.box(tx, y, tz, s + 0.12, 0.02, 0.02, WOOD);
    k.box(tx, y + 0.1, tz, 0.02, 0.02, s + 0.12, WOOD);
  }
  k.cyl(0.36, 0, -0.3, 0.06, 0.14, RED_MUD, 6);
};

// ---- 4. kasbah ---------------------------------------------------------------------------------

const kasbah: Draw = (k, W, _D, b, r) => {
  const o = W / 2 - 0.2, H = 0.55, t = 0.12, g = 0.5;
  k.box(0, 0, 0, 2 * o, 0.006, 2 * o, PAVE);
  // the curtain wall with a gap for the gate
  k.box(0, 0, -o, 2 * o, H, t, RED_MUD);
  for (const sx of [-1, 1]) {
    k.box(sx * o, 0, 0, t, H, 2 * o, RED_MUD);
    k.box(sx * (g / 2 + (o - g / 2) / 2), 0, o, o - g / 2, H, t, RED_MUD);
    merlons(k, sx * o, -o + 0.3, sx * o, o - 0.3, H, RED_MUD);
    merlons(k, sx * (g / 2 + 0.3), o, sx * (o - 0.3), o, H, RED_MUD);
  }
  merlons(k, -o + 0.3, -o, o - 0.3, -o, H, RED_MUD);
  // four corner towers, tapering, with a dark frieze and crenellations
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * o, z = sz * o;
    frustum(k, x, 0, z, 0.52, 0.52, 0.42, 0.42, 1.05, RED_MUD);
    k.box(x, 0.78, z, 0.46, 0.08, 0.46, RED_D);
    k.box(x, 1.05, z, 0.48, 0.05, 0.48, RED_D);
    for (const [ax, az] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) k.box(x + ax * 0.2, 1.1, z + az * 0.2, 0.08, 0.1, 0.08, RED_MUD);
    for (const [ax, az] of [[0, -1], [0, 1], [-1, 0], [1, 0]]) k.box(x + ax * 0.2, 1.1, z + az * 0.2, 0.08, 0.1, 0.08, RED_MUD);
    win(k, b, r, x + sx * 0.001, 0.55, z + sz * 0.23, 0.07, 0.12, sz > 0 ? 1 : 3, DOOR);
  }
  // the gatehouse
  for (const sx of [-1, 1]) frustum(k, sx * (g / 2 + 0.12), 0, o, 0.26, 0.3, 0.22, 0.26, 0.85, RED_MUD);
  k.box(0, 0.45, o, g, 0.3, 0.2, RED_MUD);
  k.box(0, 0, o + 0.104, g, 0.44, 0.004, DOOR);
  merlons(k, -g / 2 - 0.12, o, g / 2 + 0.12, o, 0.85, RED_MUD, 0.14);
  for (const sx of [-1, 1]) k.glowBox(sx * (g / 2 + 0.26), 0.36, o + 0.12, 0.05, 0.07, 0.03, FLAME, TORCH, FIRE);
  // the keep: city hall itself, windows all round, the flag on top
  const kw = 1.3, kd = 0.9, kh = 1.0, kz = -0.35;
  k.box(0, 0, kz, kw, kh, kd, MUD, MUD_L);
  k.box(0, 0.62, kz, kw + 0.02, 0.07, kd + 0.02, RED_D);
  for (let f = 0; f < 2; f++) {
    const y = 0.14 + f * 0.48;
    for (let j = 0; j < 5; j++) win(k, b, r, -kw / 2 + 0.13 + j * 0.26, y + (f ? 0.1 : 0), kz + kd / 2, 0.08, 0.14, 1, DOOR);
    for (const sx of [-1, 1]) for (let j = 0; j < 3; j++) win(k, b, r, sx * kw / 2, y + (f ? 0.1 : 0), kz - 0.3 + j * 0.3, 0.08, 0.14, sx > 0 ? 0 : 2, DOOR);
  }
  k.box(0, 0, kz + kd / 2 + 0.005, 0.22, 0.3, 0.01, DOOR);
  merlons(k, -kw / 2, kz + kd / 2, kw / 2, kz + kd / 2, kh, MUD_L, 0.2);
  merlons(k, -kw / 2, kz - kd / 2, kw / 2, kz - kd / 2, kh, MUD_L, 0.2);
  flag(k, 0, kh, kz, 0.6, hex(0x2f7a4a));
  // a fountain and two palms in the court
  k.cyl(0, 0, 0.62, 0.18, 0.06, LIME2, 10);
  k.disc(0, 0.061, 0.62, 0.15, hex(0x3f9ab0), 10);
  for (const sx of [-1, 1]) datePalm(k, sx * 0.7, 0.55, 0.75, r);
};

// ---- 5. tent camp ------------------------------------------------------------------------------

const tentCamp: Draw = (k, W, D, _b, r) => {
  // three long black tents facing the fire
  const tent = (col: RGB) => {
    const z = -0.95, w = 1.05, d = 0.55, h = 0.2;
    k.box(0, 0, z - d / 2, w, h, 0.02, col);
    for (const sx of [-1, 1]) k.box(sx * w / 2, 0, z, 0.02, h, d, col);
    k.gable(0, h, z, w + 0.06, 0.12, d + 0.06, col, TENT_D);
    for (const px of [-0.35, 0, 0.35]) k.box(px, h + 0.1, z, 0.02, 0.06, 0.02, WOOD);
    k.box(0, 0.005, z, w - 0.1, 0.004, d - 0.1, hex(RUGS[Math.floor(r() * RUGS.length)]));
    k.box(0, 0.005, z + d / 2 + 0.12, 0.4, 0.004, 0.22, hex(RUGS[Math.floor(r() * RUGS.length)]));
    for (const sx of [-1, 1]) {
      k.bar([sx * (w / 2 + 0.03), h, z + d / 2 + 0.03], [sx * (w / 2 + 0.2), 0, z + d / 2 + 0.2], 0.005, hex(0x8a7a60));
      k.box(sx * 0.3, 0, z + d / 2 - 0.1, 0.12, 0.05, 0.08, hex(RUGS[Math.floor(r() * RUGS.length)]));
    }
    k.glowBox(0, 0.12, z - 0.1, 0.04, 0.05, 0.04, FLAME, [18, 24.5, 1.6], WARM_GLOW);
  };
  tent(TENT);
  k.turned(Math.PI / 2, () => tent(scale(TENT, 1.2)));
  k.turned(-Math.PI / 2, () => tent(hex(0x54463a)));
  // the fire in its ring of stones
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    k.box(Math.cos(a) * 0.17, 0, Math.sin(a) * 0.17, 0.06, 0.04, 0.06, hex(0x9a8a74));
  }
  k.bar([-0.1, 0.02, -0.04], [0.1, 0.02, 0.04], 0.018, TRUNK);
  k.bar([-0.06, 0.02, 0.1], [0.06, 0.02, -0.1], 0.018, TRUNK);
  k.glowBox(0, 0.02, 0, 0.12, 0.08, 0.12, FLAME, [17.5, 30, 3], FIRE);
  k.glowBox(0, 0.1, 0, 0.06, 0.08, 0.06, hex(0xf8d27a), [17.5, 30, 3.2], hex(0xffc060));
  for (const [x, z] of [[-0.35, 0.3], [0.35, 0.3]]) k.box(x, 0, z, 0.2, 0.05, 0.08, hex(0x8a5a3a));
  // camels hitched at the front, a trough and a palm
  const hx = -W / 2 + 0.3, hz = D / 2 - 0.3;
  k.box(hx, 0, hz, 0.04, 0.3, 0.04, WOOD);
  camel(k, hx + 0.35, hz - 0.05, true, -1);
  camel(k, hx + 0.1, hz - 0.4, false, 1, scale(CAMEL, 0.92));
  k.box(W / 2 - 0.6, 0, D / 2 - 0.25, 0.4, 0.08, 0.14, WOOD);
  k.box(W / 2 - 0.6, 0.081, D / 2 - 0.25, 0.34, 0.005, 0.09, hex(0x4f8aa0));
  datePalm(k, W / 2 - 0.25, D / 2 - 0.6, 0.8, r);
  datePalm(k, W / 2 - 0.4, -D / 2 + 0.3, 0.95, r);
};

// ---- 6. date grove -----------------------------------------------------------------------------

const dateGrove: Draw = (k, W, D, _b, r) => {
  const nx = Math.max(3, Math.round(W - 1)), nz = Math.max(3, Math.round(D - 1));
  const sx = (W - 0.6) / nx, sz = (D - 0.6) / nz, water = hex(0x4f9ab0), bank = hex(0xc8a878);
  // an irrigation channel down each row, fed by one along the front
  k.box(0, 0, D / 2 - 0.15, W - 0.2, 0.05, 0.14, bank);
  k.box(0, 0.051, D / 2 - 0.15, W - 0.26, 0.005, 0.07, water);
  for (let i = 0; i <= nx; i++) {
    const x = -W / 2 + 0.3 + i * sx;
    k.box(x, 0, -0.1, 0.12, 0.04, D - 0.4, bank);
    k.box(x, 0.041, -0.1, 0.05, 0.005, D - 0.46, water);
  }
  for (let i = 0; i < nx; i++) for (let j = 0; j < nz; j++) {
    const x = -W / 2 + 0.3 + (i + 0.5) * sx + (r() - 0.5) * 0.1, z = -D / 2 + 0.3 + (j + 0.5) * sz + (r() - 0.5) * 0.1;
    k.disc(x, 0, z, 0.16, hex(0xb8986a), 7);
    datePalm(k, x, z, 0.8 + r() * 0.35, r);
  }
  // a mud-brick pump house at the corner
  k.box(-W / 2 + 0.2, 0, D / 2 - 0.2, 0.28, 0.24, 0.24, MUD, MUD_L);
  k.box(-W / 2 + 0.2, 0, D / 2 - 0.076, 0.08, 0.14, 0.004, DOOR);
};

// ---- 7. pyramid (wonder) -----------------------------------------------------------------------

const pyramid: Draw = (k, W, D, _b, r) => {
  const front = D / 2;
  // the great pyramid: smooth courses of casing stone and a gold capstone
  const gz = -8, base = 10, H = 6.4, bands = 8;
  for (let i = 0; i < bands; i++) {
    const f0 = i / bands, f1 = (i + 1) / bands;
    if (i < bands - 1) frustum(k, 0, H * f0, gz, base * (1 - f0), base * (1 - f0), base * (1 - f1), base * (1 - f1), H * (f1 - f0), i % 2 ? LIME : LIME2);
    else k.hip(0, H * f0, gz, base * (1 - f0), H * (1 - f0), base * (1 - f0), GOLD);
  }
  k.box(0, 0.7, gz + base / 2 - 0.7 * (base / 2 / H) - 0.05, 0.36, 0.34, 0.14, DARK);
  // two lesser pyramids, stepped and weathered
  const stepped = (x: number, z: number, b0: number, h: number, n: number) => {
    for (let i = 0; i < n; i++) {
      const f = 1 - i / n;
      k.box(x, (h * i) / n, z, b0 * f, h / n, b0 * f, i % 2 ? WORN : scale(WORN, 1.05));
    }
    k.hip(x, h, z, b0 / n, (h / n) * 0.9, b0 / n, GOLD);
  };
  stepped(-7.4, -10.5, 4.2, 2.8, 7);
  stepped(7.5, -6.5, 3.8, 2.4, 6);
  // drifts of sand against their feet
  for (const [x, z, w] of [[-5.4, -4, 2.4], [5.2, -12, 3], [-9, -7, 1.6], [9.2, -3.8, 1.2]]) k.hip(x, 0, z, w, 0.28, w * 0.6, hex(0xe6c98e));
  // the forecourt and the avenue up to the pylon gate
  k.box(0, 0, -1.2, 12, 0.02, 3.6, PAVE);
  k.box(0, 0, (0.6 + front) / 2, 2, 0.02, front - 0.6, PAVE);
  for (const sx of [-1, 1]) k.box(sx * 1.02, 0, (0.6 + front) / 2, 0.05, 0.05, front - 0.6, LIME2);
  // obelisks in pairs, torch bowls between them
  for (let j = 0; j < 4; j++) {
    const z = front - 4 - j * 2.6;
    for (const sx of [-1, 1]) {
      const x = sx * 1.4;
      k.box(x, 0, z, 0.42, 0.14, 0.42, LIME2);
      frustum(k, x, 0.14, z, 0.24, 0.24, 0.15, 0.15, 1.9, hex(0xd8a878));
      k.hip(x, 2.04, z, 0.15, 0.16, 0.15, GOLD);
      torch(k, x, z - 1.3, 0.35);
    }
  }
  // the pylon gate at the avenue's mouth
  const pz = front - 1.2;
  for (const sx of [-1, 1]) {
    frustum(k, sx * 1.85, 0, pz, 1.7, 0.9, 1.35, 0.7, 2.3, LIME, LIME);
    k.box(sx * 1.85, 2.3, pz, 1.45, 0.12, 0.8, WORN);
    k.box(sx * 1.85, 1.3, pz + 0.41, 0.8, 0.6, 0.02, hex(0x3f6a8a));
    k.box(sx * 1.85, 1.45, pz + 0.42, 0.5, 0.3, 0.02, GOLD);
    torch(k, sx * 2.9, pz + 0.8, 0.45, 1.3);
  }
  k.box(0, 1.55, pz, 1.1, 0.3, 0.6, LIME2);
  k.box(0, 1.85, pz, 1.2, 0.06, 0.66, WORN);
  // the sphinx, lying beside the forecourt looking down the avenue
  const sxp = -4.3, szp = 2.6, SPH = hex(0xd6b27a);
  k.box(sxp, 0, szp, 1.7, 0.12, 3.8, LIME2);
  k.box(sxp, 0.12, szp - 0.5, 1.0, 0.72, 2.4, SPH);
  k.box(sxp, 0.12, szp - 1.5, 1.05, 0.55, 0.6, scale(SPH, 0.95));
  for (const sx of [-1, 1]) k.box(sxp + sx * 0.3, 0.12, szp + 1.2, 0.3, 0.2, 1.1, SPH);
  k.box(sxp, 0.12, szp + 0.55, 0.82, 1.2, 0.6, SPH);
  k.box(sxp, 1.1, szp + 0.6, 0.86, 0.5, 0.46, hex(0xc9a468));
  for (const sx of [-1, 1]) frustum(k, sxp + sx * 0.36, 0.62, szp + 0.66, 0.16, 0.34, 0.16, 0.34, 0.5, hex(0xb89458));
  k.box(sxp, 1.2, szp + 0.84, 0.42, 0.48, 0.14, SPH);
  k.box(sxp, 1.33, szp + 0.915, 0.3, 0.04, 0.01, DARK);
  k.hip(sxp, 1.6, szp + 0.6, 0.86, 0.14, 0.46, hex(0xc9a468));
  torch(k, sxp - 1.1, szp + 1.9, 0.4, 1.2);
  torch(k, sxp + 1.1, szp + 1.9, 0.4, 1.2);
  // torches round the forecourt, a few palms and fallen blocks
  for (const sx of [-1, 1]) for (const z of [-2.8, 0.4]) torch(k, sx * 5.8, z, 0.45, 1.3);
  for (const [x, z] of [[4.2, 12], [5, 10.2], [-4, 13], [8.6, 3], [-8.8, 6.5], [7.6, 7.4]]) datePalm(k, x, z, 1.1 + r() * 0.4, r);
  for (let i = 0; i < 10; i++) {
    const x = (r() - 0.5) * (W - 2), z = -3 + r() * 5;
    if (Math.abs(x) < 6.5 && z > -3.2 && z < 0.8) continue;
    k.box(x, 0, z, 0.3 + r() * 0.3, 0.2, 0.3, r() < 0.5 ? LIME2 : WORN);
  }
};

export const SANDS_DRAW: Partial<Record<RegionBuildingKind, Draw>> = {
  souk, caravanserai, windTower, kasbah, tentCamp, dateGrove, pyramid,
};

