import * as THREE from 'three';

/**
 * The moving lights of the rare specials (0.7.0, behind NEXT_WORLD; docs/trains.html "Specials"): the rave
 * train's lasers sweeping out over the line, and its disco car's mirror ball turning above the roof with
 * spots of coloured light wheeling round it on the ground. They are each car's own (built by buildCar for a
 * special car id, run by Trains each frame with the clock and how dark it is); everything they draw is
 * additive and shared, like the events' searchlight beams, so a car costs a few meshes and no new materials.
 *
 * The Christmas train's bulbs and the stealth train's night-only red lamps are plain finishes on the cars
 * themselves (render/trainMeshes.ts), so they need nothing here.
 */

const NEON = [0xff2bd6, 0x22e6ff, 0x7cff4a, 0xffe14a];

let shared: {
  beam: THREE.BufferGeometry; beamMats: THREE.MeshBasicMaterial[];
  ball: THREE.BufferGeometry; ballMat: THREE.MeshStandardMaterial;
  spot: THREE.BufferGeometry; spotMats: THREE.MeshBasicMaterial[];
} | null = null;

/** The rave train's shared pieces (the lasers, the mirror ball, the spots), built once: render/wonderBall.ts wears the same ball. */
export function discoParts() { return parts(); }
export { NEON };

function parts() {
  if (shared) return shared;
  // a laser: a long thin cone out from its emitter along +y, brightest at the foot
  const beam = new THREE.CylinderGeometry(0.05, 0.008, 7, 6, 1, true).translate(0, 3.5, 0);
  const col: number[] = [];
  const pos = beam.getAttribute('position');
  for (let i = 0; i < pos.count; i++) { const k = 1 - pos.getY(i) / 7; col.push(k, k, k); }
  beam.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  const additive = (c: number, o: number) => new THREE.MeshBasicMaterial({ color: c, vertexColors: false, transparent: true, opacity: o, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
  const beamMats = NEON.map((c) => { const m = additive(c, 0.5); m.vertexColors = true; return m; });
  // the mirror ball: a faceted sphere, bright and glinting
  const ball = new THREE.IcosahedronGeometry(0.07, 1);
  const ballMat = new THREE.MeshStandardMaterial({ color: 0xd9dde2, metalness: 0.95, roughness: 0.18, flatShading: true, emissive: 0xffffff, emissiveIntensity: 0.15 });
  const spot = new THREE.CircleGeometry(0.09, 10).rotateX(-Math.PI / 2);
  const spotMats = NEON.map((c) => additive(c, 0.7));
  shared = { beam, beamMats, ball, ballMat, spot, spotMats };
  return shared;
}

/** A special car's moving lights, added to its group: the function to run them each frame, or null for a car with none. */
export function specialRig(id: string, group: THREE.Group, seed: number): ((t: number, night: number) => void) | null {
  if (id !== 'discoCar' && id !== 'raveCoach') return null;
  const p = parts();
  const rig = new THREE.Group();
  rig.name = 'specialRig';
  group.add(rig);
  // two lasers off the roof (four off the disco car), each sweeping its own fan
  const lasers: { m: THREE.Mesh; side: number; ph: number }[] = [];
  const n = id === 'discoCar' ? 4 : 2;
  for (let i = 0; i < n; i++) {
    const m = new THREE.Mesh(p.beam, p.beamMats[(i + seed) % p.beamMats.length]);
    m.renderOrder = 5;
    m.frustumCulled = false;
    m.position.set(0, 0.39, (i - (n - 1) / 2) * 0.32);
    rig.add(m);
    lasers.push({ m, side: i % 2 ? 1 : -1, ph: i * 1.7 + seed * 0.37 });
  }
  let ball: THREE.Mesh | null = null;
  const spots: { m: THREE.Mesh; r: number; a: number }[] = [];
  if (id === 'discoCar') {
    ball = new THREE.Mesh(p.ball, p.ballMat);
    ball.position.set(0, 0.44, 0);
    rig.add(ball);
    // the spots the ball throws: on the ground round the car, wheeling as it turns
    for (let i = 0; i < 18; i++) {
      const m = new THREE.Mesh(p.spot, p.spotMats[i % p.spotMats.length]);
      m.renderOrder = 4;
      m.frustumCulled = false;
      rig.add(m);
      spots.push({ m, r: 0.45 + (i % 3) * 0.35, a: (i / 18) * Math.PI * 2 });
    }
  }
  return (t, night) => {
    // by day the lasers are faint and the spots barely there; after dark they are the show
    const show = 0.18 + 0.82 * night;
    for (const L of lasers) {
      const sweep = Math.sin(t * 1.3 + L.ph);
      L.m.rotation.set(0.25 * Math.sin(t * 0.7 + L.ph), 0, L.side * (0.45 + 0.6 * (0.5 + 0.5 * sweep)));
      L.m.visible = show > 0.25;
      L.m.scale.set(1, 0.6 + 0.4 * night, 1);
    }
    for (const m of p.beamMats) m.opacity = 0.12 + 0.45 * night;
    if (ball) ball.rotation.y = t * 1.6;
    const spin = t * 1.6;
    for (const s of spots) {
      const a = s.a + spin;
      s.m.position.set(Math.cos(a) * s.r * 1.6, -0.02, Math.sin(a) * s.r);
      s.m.visible = night > 0.2;
    }
    for (const m of p.spotMats) m.opacity = 0.75 * show;
  };
}
