import { N, Flag, Lot, RailBit, World, idx, inB, type Building, type Poi, type RailPath, type RailStation } from '../world/tiles';
import { clearRoadTile } from '../world/roads';
import { builtRailAt, removeRail, removeStation } from '../world/railBuild';
import { propsOn } from '../render/props';
import { SITE_LABEL } from './cargoTypes';
import { CLEAR_PROPS, CLEAR_ROAD, demolishCost } from './economy';

/** What the bulldozer would clear on a tile, what it's called and what it costs. */
export interface Target {
  /** 'rail' a track the player laid (world/railBuild.ts), 'station' a station they put up: either goes whole. */
  kind: 'building' | 'poi' | 'road' | 'props' | 'rail' | 'station' | 'none';
  label: string;
  detail: string;
  cost: number;
  tiles: number[];          // everything that goes, for the highlight
  building?: Building;
  poi?: Poi;
  path?: RailPath;
  station?: RailStation;
}

/** Clearing a tile of the player's own track, a tile of it (the bulldozer takes the whole track up). */
const CLEAR_RAIL = 2;

/** Every tile a path's centreline runs over, for the highlight. */
function pathTiles(p: RailPath): number[] {
  const out = new Set<number>();
  for (let i = 0; i < p.s.length; i++) {
    const x = Math.floor(p.xz[i * 2]), z = Math.floor(p.xz[i * 2 + 1]);
    if (inB(x, z)) out.add(idx(x, z));
  }
  return [...out];
}

/** A track or a station the player laid, under tile (x, z): what the bulldozer would take up. A road on the tile wins. */
function builtRailTarget(w: World, x: number, z: number): Target | null {
  const i = idx(x, z);
  if (w.road[i]) return null;
  const hit = builtRailAt(w, x + 0.5, z + 0.5);
  if (!hit) return null;
  const { path, station } = hit;
  if (station) {
    const b = station.building;
    const tiles = pathTiles(path);
    if (b) for (let tz = b.z; tz < b.z + b.d; tz++) for (let tx = b.x; tx < b.x + b.w; tx++) tiles.push(idx(tx, tz));
    const joined = w.rails.filter((q) => q !== path && [q.start, q.end].some((e) => e.kind === 'join' && e.path === path.id)).length;
    return {
      kind: 'station', label: `${station.name} · built station`,
      detail: `Takes the building and its platform track down${joined ? `\n${joined === 1 ? 'The track' : `The ${joined} tracks`} laid from it will end at buffers there` : ''}`,
      cost: b ? demolishCost(b) : 100, tiles, building: b ?? undefined, station, path,
    };
  }
  const len = Math.max(1, Math.round(path.length));
  const joined = w.rails.filter((q) => q !== path && [q.start, q.end].some((e) => e.kind === 'join' && e.path === path.id)).length;
  return {
    kind: 'rail', label: `${path.name} · built track`,
    detail: `Takes the whole track up · ${len} tiles${joined ? `\n${joined === 1 ? 'The track' : `The ${joined} tracks`} joining it will end at buffers there` : ''}`,
    cost: CLEAR_RAIL * len, tiles: pathTiles(path), path,
  };
}

const NOTHING: Target = { kind: 'none', label: 'Nothing to clear', detail: 'Bare ground', cost: 0, tiles: [] };

const ROAD_NAME = ['', 'Dirt lane', 'Brick lane', 'Paved lane', 'Two-lane road', 'Four-lane highway'];

/** The building standing on a tile, if one still does. */
export function buildingAt(w: World, x: number, z: number): Building | null {
  for (const b of w.allBuildings) {
    if (b.gone) continue;
    if (x >= b.x && z >= b.z && x < b.x + b.w && z < b.z + b.d) return b;
  }
  return null;
}

/** Look at a tile: a building goes as a whole, otherwise the road, otherwise whatever grows there. */
export function targetAt(w: World, x: number, z: number): Target {
  if (!inB(x, z)) return NOTHING;
  const i = idx(x, z);
  const b = buildingAt(w, x, z);
  // a station the player put up comes down whole, its platform track with it
  const own = b && w.stations.find((s) => s.building === b);
  if (own) {
    const t = builtRailTarget(w, Math.floor(own.building!.x), Math.floor(own.building!.z));
    const p = w.rails[own.path];
    if (p && t?.station === own) return t;
    if (p && t?.kind !== 'station') {
      // the lot itself sits off the track: point the target at the station by its platform
      const mid = Math.floor(p.s.length / 2);
      const t2 = builtRailTarget(w, Math.floor(p.xz[mid * 2]), Math.floor(p.xz[mid * 2 + 1]));
      if (t2?.station === own) return t2;
    }
    // the railway's own: its track and its stations stay
    return { kind: 'none', label: SITE_LABEL[b!.kind] ?? 'Station', detail: 'Railway stations stay', cost: 0, tiles: [] };
  }
  // a track the player laid comes up whole
  if (!b) { const t = builtRailTarget(w, x, z); if (t) return t; }
  if (!b && (w.rail[i] & (RailBit.Track | RailBit.Pad | RailBit.Loop)) && !w.road[i]) return { kind: 'none', label: 'Railway', detail: 'The line can’t be bulldozed', cost: 0, tiles: [] };
  if (b) {
    const tiles: number[] = [];
    for (let tz = b.z; tz < b.z + b.d; tz++) for (let tx = b.x; tx < b.x + b.w; tx++) tiles.push(idx(tx, tz));
    const name = SITE_LABEL[b.kind] ?? b.kind;
    const size = `${b.w}×${b.d} tiles${b.floors > 1 ? ` · ${b.floors} floors` : ''}`;
    return { kind: 'building', label: name, detail: size, cost: demolishCost(b), tiles, building: b };
  }
  const poi = w.pois.find((p) => p.x === x && p.z === z);
  if (poi) {
    const name = poi.type === 'cabin' ? 'Forest cabin' : poi.type === 'barn' ? 'Farm barn' : 'Lighthouse';
    return { kind: 'poi', label: name, detail: 'Out in the country', cost: 199, tiles: [i], poi };
  }
  if (w.road[i]) {
    return { kind: 'road', label: ROAD_NAME[w.road[i]] ?? 'Road', detail: 'Clears this tile and splits the road', cost: CLEAR_ROAD, tiles: [i] };
  }
  const { trees, rocks, cacti } = propsOn(w, x, z);
  if (trees || rocks || cacti) {
    const what = trees ? (trees > 1 ? 'Trees' : 'Tree') : rocks ? 'Rocks' : 'Cactus';
    return { kind: 'props', label: what, detail: 'Clears the tile', cost: CLEAR_PROPS, tiles: [i] };
  }
  return NOTHING;
}

/**
 * Clear it. Returns every tile that changed, so the chunks covering them can be rebuilt.
 * The caller pays first, and afterwards rebuilds what reads the world (traffic, cargo sites, x-ray).
 */
export function demolish(w: World, t: Target): number[] {
  if (t.kind === 'station' && t.station) return removeStation(w, t.station);
  if (t.kind === 'rail' && t.path) return removeRail(w, t.path);

  if (t.kind === 'building' && t.building) {
    const b = t.building;
    b.gone = true;
    for (const town of w.towns) {
      const k = town.buildings.indexOf(b);
      if (k >= 0) town.buildings.splice(k, 1);
    }
    for (const p of w.ports) {
      const k = p.buildings.indexOf(b);
      if (k >= 0) p.buildings.splice(k, 1);
    }
    const out = w.countryside.indexOf(b);
    if (out >= 0) w.countryside.splice(out, 1);
    for (const i of t.tiles) {
      w.blocked[i] = 0;
      w.roof[i] = 0;
      w.cleared[i] = 1;                       // nothing regrows on the rubble
      w.flags[i] &= ~Flag.Field;
      if (w.lot[i] === Lot.None) w.lot[i] = Lot.Lawn;
    }
    // what reads the island again: the earthworks' guard (land.ts) frees the ground it stood on
    w.revision++;
    return t.tiles;
  }
  if (t.kind === 'poi' && t.poi) {
    const k = w.pois.indexOf(t.poi);
    if (k >= 0) w.pois.splice(k, 1);
    const i = idx(t.poi.x, t.poi.z);
    w.flags[i] &= ~Flag.Poi;
    w.cleared[i] = 1;
    w.revision++;
    return [i];
  }
  if (t.kind === 'road') {
    const i = t.tiles[0];
    const touched = clearRoadTile(w, i);
    w.cleared[i] = 1;
    return touched.length ? touched : [i];
  }
  if (t.kind === 'props') {
    w.cleared[t.tiles[0]] = 1;
    return t.tiles;
  }
  return [];
}

/** Every tile of the chunk-sized neighbourhood around a tile, for rebuilding drivability. */
export const around = (i: number): number[] => {
  const x = i % N, z = (i - x) / N, out: number[] = [];
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (inB(x + dx, z + dz)) out.push(idx(x + dx, z + dz));
  return out;
};
