import { hex, type RGB } from '../../world/biomes';
import { DIRS, STEP, idx, inB, waterDepth, type Building } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, TAU, WARM_GLOW, WHITE, type Kit, type P3 } from './kit';
import { hull } from './worldStylesB';

/**
 * The pieces a lake town's models share (render/buildings/lake.ts, lakeB.ts, render/lakeDress.ts): which side of a
 * lot the lake lies on, planked docks on their piles, the boats tied up at them (Okoboji's pontoons, Como's varnished
 * Riva launches, the sailing boats at Léman's moorings, rowing boats and canoes), the lake steamers and ferries that
 * run between the landings, cypress and plane trees, lamps and benches along the walk, flags, and people on the shore
 * and in the water.
 */

export const PLANK = hex(0xa8865e), PLANK_DARK = hex(0x7a5c3e), PILE = hex(0x5e4a36), PAINT = hex(0xf6f4ee), NAVY = hex(0x26365a);
export const MAHOGANY = hex(0x8a3e22), VARNISH = hex(0xb05a2c), CREAM = hex(0xf2e8d0), CHROME = hex(0xd8dcdf), SAND = hex(0xeedcae);
export const STONE = hex(0xd6cdb6), STONE_DARK = hex(0xaea38c), IRON = hex(0x2a2e30), CYPRESS = hex(0x2c5634), CYPRESS2 = hex(0x356440);
export const PLANE = hex(0x6a9a4a), PLANE2 = hex(0x5a8a3e), BARK = hex(0x9a907a), GRASS = hex(0x7aa85a), LAKE = hex(0x4f8fae);
export const FLOWERS = [0xe2412f, 0xf2c14e, 0xe85a9a, 0xf4f2ec, 0x8e5cc7, 0xf28c38].map(hex);
/** Lamps along the walk: dusk to the small hours. */
export const LAMPS: Sched = [17.4, 29.5, 1.4];
/** Rooms of a hotel or a house: lit through the evening. */
export const ROOMS: Sched = [17.6, 23.6, 1.4];

/** Which side of the lot the lake lies on (a face of the lot's own frame: 1 front +z, 0 +x, 3 back, 2 -x), its surface in the lot's frame, and how far out it reaches (tiles). */
export function waterSide(k: Kit, b: Building, W: number, D: number): { face: number; y: number; reach: number; wet: boolean } {
  const w = k.world, yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]), c = Math.cos(yaw), s = Math.sin(yaw);
  const ox = b.x + b.w / 2, oz = b.z + b.d / 2;
  let best = 3, most = 0, level = 0, reach = 2;
  if (w?.water) {
    for (const f of [3, 1, 0, 2]) {
      const [nx, nz] = f === 1 ? [0, 1] : f === 0 ? [1, 0] : f === 2 ? [-1, 0] : [0, -1];
      const along = nx ? D : W, out = nx ? W / 2 : D / 2;
      let n = 0, lv = 0, far = 0;
      for (let u = -along / 2 + 0.5; u < along / 2; u += 1) {
        for (const o of [0.5, 1.5, 2.5, 3.5]) {
          const lx = nx * (out + o) + nz * u, lz = nz * (out + o) - nx * u;
          const tx = Math.floor(ox + lx * c + lz * s), tz = Math.floor(oz - lx * s + lz * c);
          if (!inB(tx, tz)) continue;
          const i = idx(tx, tz);
          if (waterDepth(w, i) > 0) { n++; lv = w.water[i]; far = Math.max(far, o); } else if (o > 0.5 && far < o - 1) break;
        }
      }
      if (n > most) { most = n; best = f; level = lv; reach = far; }
    }
  }
  return { face: best, y: most ? Math.min(-0.1, (level - b.level) * STEP) : -0.4, reach: most ? reach : 3, wet: most > 0 };
}

/**
 * Draw in a frame turned so the lake lies past local +z: `draw(L, Dp, y, reach)`, L the lot's length along the shore,
 * Dp its depth back from the water (the shore edge at z = Dp / 2), y the water's surface, reach how far out it goes.
 */
export function toWater(k: Kit, b: Building, W: number, D: number, draw: (L: number, Dp: number, y: number, reach: number) => void): void {
  const ws = waterSide(k, b, W, D);
  const yaw = ws.face === 1 ? 0 : ws.face === 0 ? Math.PI / 2 : ws.face === 2 ? -Math.PI / 2 : Math.PI;
  const across = ws.face === 0 || ws.face === 2;
  k.turned(yaw, () => draw(across ? D : W, across ? W : D, ws.y, ws.reach));
}

/** A planked deck w × d (along x, z) at height y, its piles down into the water at wy (or the ground at 0). */
export function deck(k: Kit, x: number, z: number, w: number, d: number, y: number, wy: number, col: RGB = PLANK): void {
  k.box(x, y - 0.025, z, w, 0.025, d, col);
  // the planks' seams, across the run
  const n = Math.max(2, Math.round(Math.max(w, d) / 0.12));
  k.detail(() => {
    for (let i = 1; i < n; i++) {
      if (w >= d) k.box(x - w / 2 + (w * i) / n, y + 0.0005, z, 0.006, 0.002, d, PLANK_DARK);
      else k.box(x, y + 0.0005, z - d / 2 + (d * i) / n, w, 0.002, 0.006, PLANK_DARK);
    }
  });
  const px = Math.max(1, Math.round(w / 0.35)), pz = Math.max(1, Math.round(d / 0.35));
  for (let i = 0; i <= px; i++) for (const j of [0, pz]) {
    const xx = x - w / 2 + 0.02 + ((w - 0.04) * i) / px, zz = z - d / 2 + 0.02 + ((d - 0.04) * j) / pz;
    k.cyl(xx, wy - 0.15, zz, 0.016, y - wy + 0.12, PILE, 5);
  }
}

/** A cleat-and-rope bollard on a dock's edge. */
export function bollard(k: Kit, x: number, y: number, z: number): void {
  k.cyl(x, y, z, 0.014, 0.03, IRON, 6);
}

// ---- boats --------------------------------------------------------------------------------------

/** A pontoon boat lying along x at the water's surface y: two silver tubes, a carpeted deck, a rail round it, a canopy. */
export function pontoon(k: Kit, x: number, y: number, z: number, r: Rng, canopy = true): void {
  const deckC = hex([0x4a6a8a, 0x7a3a3a, 0x3a5a4a, 0x8a7a5a][Math.floor(r() * 4)]);
  for (const s of [-1, 1]) {
    k.bar([x - 0.24, y, z + s * 0.07], [x + 0.22, y, z + s * 0.07], 0.02, CHROME);
    k.cone(x + 0.22, y - 0.02, z + s * 0.07, 0.02, 0.04, CHROME, 6);
  }
  k.box(x - 0.01, y + 0.02, z, 0.46, 0.012, 0.2, deckC);
  // the rail panels round the deck, a gap at the bow gate
  k.box(x - 0.03, y + 0.032, z - 0.098, 0.42, 0.05, 0.006, PAINT);
  k.box(x - 0.03, y + 0.032, z + 0.098, 0.42, 0.05, 0.006, PAINT);
  k.box(x - 0.24, y + 0.032, z, 0.006, 0.05, 0.2, PAINT);
  // bench seats, the helm console, the outboard
  k.box(x - 0.15, y + 0.032, z, 0.05, 0.035, 0.18, hex(0xe8e0cc));
  k.box(x + 0.08, y + 0.032, z - 0.06, 0.05, 0.05, 0.05, hex(0xd8d4c8));
  k.box(x - 0.26, y + 0.01, z, 0.035, 0.07, 0.03, hex(0x2a2a2e));
  if (canopy) {
    const top = hex([0x2f5f9a, 0xe8e2d4, 0x3a7a5a, 0xc8402e][Math.floor(r() * 4)]);
    for (const [dx, dz] of [[-0.18, -0.09], [-0.18, 0.09], [0.05, -0.09], [0.05, 0.09]]) k.cyl(x + dx, y + 0.032, z + dz, 0.005, 0.14, CHROME, 4);
    k.box(x - 0.065, y + 0.172, z, 0.27, 0.012, 0.21, top);
  }
}

/**
 * A Riva launch (an Aquarama or a Tritone) lying along x, bow to +x, at the water's surface y: the varnished mahogany
 * hull and deck with its pale seams, the chrome-framed windscreen, the blue-and-white leather seats.
 */
export function riva(k: Kit, x: number, y: number, z: number, s = 1): void {
  hull(k, x, y - 0.03 * s, z, 0.5 * s, 0.15 * s, 0.06 * s, 0.025 * s, MAHOGANY, VARNISH, 8);
  k.detail(() => { for (const o of [-0.035, 0, 0.035]) k.box(x + 0.06 * s, y + 0.035 * s, z + o * s, 0.24 * s, 0.002, 0.003, CREAM); });
  // the cockpits and their seats, the engine hatch between them
  for (const cx of [-0.02, -0.12]) {
    k.box(x + cx * s, y + 0.02 * s, z, 0.07 * s, 0.025 * s, 0.11 * s, hex(0x3a5a8a));
    k.box(x + (cx - 0.03) * s, y + 0.045 * s, z, 0.015 * s, 0.03 * s, 0.11 * s, hex(0xe8ecef));
  }
  k.box(x + 0.035 * s, y + 0.035 * s, z, 0.004 * s, 0.045 * s, 0.12 * s, hex(0x9ab8c8));
  k.box(x + 0.035 * s, y + 0.08 * s, z, 0.008 * s, 0.004 * s, 0.12 * s, CHROME);
  k.box(x - 0.22 * s, y + 0.035 * s, z, 0.01 * s, 0.03 * s, 0.006 * s, hex(0xc8323a));
}

/** A small sailing boat lying along x at the water's surface y, its sail furled along the boom (or set, `up`). */
export function sailboat(k: Kit, x: number, y: number, z: number, r: Rng, up = false): void {
  const hullC = r() < 0.75 ? PAINT : hex([0x26365a, 0x8a2a24, 0x2f6a4a][Math.floor(r() * 3)]);
  hull(k, x, y - 0.03, z, 0.48, 0.15, 0.06, 0.03, hullC, hex(0xd8ccb0), 8);
  k.box(x + 0.03, y + 0.035, z, 0.1, 0.03, 0.08, PAINT);
  k.cyl(x + 0.08, y + 0.03, z, 0.006, 0.55, hex(0xc8ccd0), 4);
  if (up) {
    k.tri([x + 0.08, y + 0.08, z], [x + 0.08, y + 0.56, z], [x - 0.18, y + 0.08, z], PAINT, [x, y + 0.2, z - 0.1]);
    k.tri([x + 0.08, y + 0.08, z], [x + 0.08, y + 0.56, z], [x - 0.18, y + 0.08, z], PAINT, [x, y + 0.2, z + 0.1]);
    k.tri([x + 0.1, y + 0.08, z], [x + 0.09, y + 0.5, z], [x + 0.24, y + 0.06, z], hex(0xe8ecef), [x + 0.1, y + 0.2, z - 0.1]);
    k.tri([x + 0.1, y + 0.08, z], [x + 0.09, y + 0.5, z], [x + 0.24, y + 0.06, z], hex(0xe8ecef), [x + 0.1, y + 0.2, z + 0.1]);
  } else {
    k.bar([x + 0.08, y + 0.1, z], [x - 0.18, y + 0.1, z], 0.008, hex(0xc8ccd0));
    k.box(x - 0.05, y + 0.105, z, 0.24, 0.025, 0.025, hex([0x2a4a7a, 0xf2ece0, 0x3a6a8a][Math.floor(r() * 3)]));
  }
}

/** A rowing boat or a canoe, along x at the water's surface y. */
export function rowboat(k: Kit, x: number, y: number, z: number, r: Rng): void {
  if (r() < 0.45) {
    hull(k, x, y - 0.015, z, 0.36, 0.07, 0.03, 0.03, hex([0xc8402e, 0x2f6a4a, 0xe8b040, 0x2f5f9a][Math.floor(r() * 4)]), hex(0xd8c49a), 7);
    return;
  }
  hull(k, x, y - 0.02, z, 0.3, 0.12, 0.04, 0.02, hex([0xf2ece0, 0x4a8ac0, 0x2f7a4a][Math.floor(r() * 3)]), PLANK, 6);
  k.box(x, y + 0.02, z, 0.025, 0.008, 0.11, PLANK_DARK);
  k.bar([x - 0.02, y + 0.03, z - 0.08], [x + 0.06, y + 0.01, z - 0.14], 0.004, PLANK);
}

/** One of the boats a dock in this style keeps: Okoboji's pontoons, Como's launches, Léman's sailing boats. */
export function dockBoat(k: Kit, style: string, x: number, y: number, z: number, r: Rng): void {
  const q = r();
  if (style === 'como') { if (q < 0.7) riva(k, x, y, z); else rowboat(k, x, y, z, r); }
  else if (style === 'leman') { if (q < 0.65) sailboat(k, x, y, z, r); else if (q < 0.85) riva(k, x, y, z, 0.9); else rowboat(k, x, y, z, r); }
  else if (style === 'victorian') { if (q < 0.4) riva(k, x, y, z, 1.05); else if (q < 0.7) sailboat(k, x, y, z, r); else pontoon(k, x, y, z, r); }
  else if (q < 0.7) pontoon(k, x, y, z, r, q < 0.5); else rowboat(k, x, y, z, r);
}

/** The lake steamer or ferry a town's landings are served by, by its style. */
export type Ferry = 'queen' | 'mail' | 'paddle' | 'battello';
export function ferryOf(style: string): Ferry {
  return style === 'lakeside' ? 'queen' : style === 'victorian' ? 'mail' : style === 'leman' ? 'paddle' : 'battello';
}

/**
 * A lake boat drawn round its own origin, bow to +z, its waterline at y = 0:
 * - queen: Okoboji's Queen II, a white excursion steamer, two decks under a canopy, a tall black stack amidships
 * - mail: Geneva Lake's mail boat (the Walworth II), a long low white launch with an open upper deck and a canvas top
 * - paddle: a Lac Léman belle époque paddle steamer (La Suisse, Montreux), white hull, paddle boxes, a buff funnel
 *   with a black top and the Swiss flag at the stern
 * - battello: Lake Como's motor ferry, white with a blue band, a wheelhouse forward and an open deck aft
 */
export function ferry(k: Kit, kind: Ferry, s = 1): void {
  const L = (kind === 'paddle' ? 1.8 : kind === 'queen' ? 1.4 : kind === 'mail' ? 1.3 : 1.25) * s, B = (kind === 'mail' ? 0.3 : 0.38) * s;
  const turnedHull = (col: RGB, deckC: RGB) => k.turned(-Math.PI / 2, () => hull(k, 0, -0.06 * s, 0, L, B, 0.13 * s, 0.03 * s, col, deckC, 10));
  const glass = hex(0x3a4a56);
  if (kind === 'paddle') {
    turnedHull(PAINT, hex(0xc8b890));
    k.box(0, 0.04 * s, 0, L * 0.8, 0.012 * s, B * 0.98, hex(0x2a3a4a));
    k.turned(-Math.PI / 2, () => {
      // the saloon deck and the promenade deck over it, the paddle boxes either side, the funnel and the flag
      k.box(0, 0.07 * s, 0, L * 0.7, 0.13 * s, B * 0.78, PAINT);
      for (let i = 0; i < 10; i++) k.pane(-L * 0.32 + (L * 0.64 * i) / 9, 0.1 * s, B * 0.39, 0.05 * s, 0.05 * s, 1, glass, ROOMS, WARM_GLOW);
      k.box(0, 0.2 * s, 0, L * 0.74, 0.012 * s, B * 0.84, PLANK);
      k.box(0, 0.212 * s, B * 0.41, L * 0.74, 0.03 * s, 0.006, PAINT);
      k.box(0, 0.212 * s, -B * 0.41, L * 0.74, 0.03 * s, 0.006, PAINT);
      k.box(L * 0.22, 0.212 * s, 0, 0.16 * s, 0.07 * s, 0.16 * s, PAINT);
      for (const sd of [-1, 1]) {
        k.box(0, 0.0, sd * (B / 2 + 0.05 * s), 0.3 * s, 0.17 * s, 0.1 * s, PAINT);
        k.face(0, 0.1 * s, sd * (B / 2 + 0.1 * s + 0.001), 0.07 * s, hex(0xd8b048), 10);
      }
      k.cyl(-0.05 * s, 0.212 * s, 0, 0.045 * s, 0.22 * s, hex(0xe0c890), 8);
      k.cyl(-0.05 * s, 0.4 * s, 0, 0.047 * s, 0.05 * s, DARK, 8);
      k.cyl(-L * 0.46, 0.04 * s, 0, 0.005, 0.22 * s, IRON, 4);
      k.box(-L * 0.46 - 0.05 * s, 0.22 * s, 0, 0.1 * s, 0.07 * s, 0.004, hex(0xd8262a));
      k.box(-L * 0.46 - 0.05 * s, 0.245 * s, 0.003, 0.06 * s, 0.018 * s, 0.002, WHITE);
      k.box(-L * 0.46 - 0.05 * s, 0.235 * s, 0.003, 0.018 * s, 0.04 * s, 0.002, WHITE);
      k.glowBox(L * 0.3, 0.3 * s, 0, 0.02, 0.02, 0.02, hex(0xf6f0d8), LAMPS, WARM_GLOW);
    });
    return;
  }
  if (kind === 'queen') {
    turnedHull(PAINT, hex(0xb8a888));
    k.turned(-Math.PI / 2, () => {
      // two decks under a canopy, gingerbread rails, the stack and the pilot house up top
      k.box(-0.05 * s, 0.05 * s, 0, L * 0.72, 0.13 * s, B * 0.82, PAINT);
      for (let i = 0; i < 9; i++) k.pane(-L * 0.36 + (L * 0.62 * i) / 8, 0.08 * s, B * 0.41, 0.06 * s, 0.07 * s, 1, glass, ROOMS, WARM_GLOW);
      k.box(-0.05 * s, 0.18 * s, 0, L * 0.76, 0.012 * s, B * 0.9, hex(0x2f5a3a));
      for (const sd of [-1, 1]) k.box(-0.05 * s, 0.192 * s, sd * B * 0.44, L * 0.74, 0.035 * s, 0.006, PAINT);
      for (let i = 0; i < 6; i++) for (const sd of [-1, 1]) k.cyl(-L * 0.38 + (L * 0.66 * i) / 5, 0.192 * s, sd * B * 0.42, 0.006, 0.12 * s, PAINT, 4);
      k.box(-0.05 * s, 0.31 * s, 0, L * 0.78, 0.014 * s, B * 0.96, hex(0xeae2d0));
      k.box(L * 0.27, 0.324 * s, 0, 0.16 * s, 0.08 * s, 0.14 * s, PAINT);
      k.hip(L * 0.27, 0.404 * s, 0, 0.19 * s, 0.04 * s, 0.17 * s, hex(0x2f5a3a));
      k.cyl(0, 0.324 * s, 0, 0.035 * s, 0.24 * s, DARK, 8);
      k.cyl(0, 0.56 * s, 0, 0.045 * s, 0.02 * s, hex(0xc8402e), 8);
      k.box(-L * 0.44, 0.33 * s, 0, 0.002, 0.06 * s, 0.09 * s, hex(0x2a3a7a));
      k.glowBox(L * 0.36, 0.33 * s, 0, 0.02, 0.02, 0.02, hex(0xf6f0d8), LAMPS, WARM_GLOW);
    });
    return;
  }
  if (kind === 'mail') {
    turnedHull(PAINT, hex(0xa87a4a));
    k.turned(-Math.PI / 2, () => {
      k.box(0, 0.045 * s, 0, L * 0.82, 0.012 * s, B * 0.92, PLANK);
      k.box(L * 0.06, 0.057 * s, 0, L * 0.5, 0.11 * s, B * 0.8, PAINT);
      for (let i = 0; i < 8; i++) k.pane(-L * 0.18 + (L * 0.48 * i) / 7, 0.08 * s, B * 0.4, 0.05 * s, 0.05 * s, 1, glass, ROOMS, WARM_GLOW);
      // the open top deck under its striped canvas, and the mail jumper's step at the bow
      k.box(L * 0.06, 0.167 * s, 0, L * 0.52, 0.01 * s, B * 0.84, PLANK);
      for (const [dx, dz] of [[-0.18, -1], [-0.18, 1], [0.3, -1], [0.3, 1]]) k.cyl(L * dx, 0.177 * s, dz * B * 0.38, 0.005, 0.11 * s, PAINT, 4);
      k.box(L * 0.06, 0.287 * s, 0, L * 0.54, 0.008 * s, B * 0.86, hex(0x2a4a7a));
      k.box(-L * 0.38, 0.06 * s, 0, 0.12 * s, 0.03 * s, B * 0.6, hex(0xe8e2d0));
      k.box(L * 0.4, 0.06 * s, 0, 0.08 * s, 0.01 * s, 0.05 * s, hex(0xc8402e));
      k.box(-L * 0.46, 0.06 * s, 0, 0.002, 0.07 * s, 0.1 * s, hex(0xb8322a));
    });
    return;
  }
  // battello
  turnedHull(PAINT, hex(0xa8a8a0));
  k.turned(-Math.PI / 2, () => {
    k.box(0, 0.035 * s, B / 2 - 0.004, L * 0.9, 0.035 * s, 0.006, hex(0x2a5aa8));
    k.box(0, 0.035 * s, -B / 2 + 0.004, L * 0.9, 0.035 * s, 0.006, hex(0x2a5aa8));
    k.box(-0.08 * s, 0.05 * s, 0, L * 0.62, 0.12 * s, B * 0.8, PAINT);
    for (let i = 0; i < 8; i++) k.pane(-L * 0.36 + (L * 0.56 * i) / 7, 0.09 * s, B * 0.4, 0.055 * s, 0.05 * s, 1, glass, ROOMS, WARM_GLOW);
    k.box(-0.08 * s, 0.17 * s, 0, L * 0.64, 0.012 * s, B * 0.84, hex(0x6a7a8a));
    k.box(L * 0.22, 0.182 * s, 0, 0.16 * s, 0.09 * s, B * 0.6, PAINT);
    k.box(L * 0.22 + 0.081 * s, 0.22 * s, 0, 0.002, 0.04 * s, B * 0.5, glass);
    k.cyl(L * 0.1, 0.182 * s, 0, 0.03 * s, 0.1 * s, hex(0x2a5aa8), 6);
    k.box(-L * 0.46, 0.06 * s, 0, 0.002, 0.07 * s, 0.1 * s, hex(0x2f8a3a));
    k.box(-L * 0.46 - 0.001, 0.06 * s, 0.033 * s, 0.002, 0.07 * s, 0.034 * s, hex(0xc8323a));
    k.box(-L * 0.46 - 0.001, 0.06 * s, 0, 0.002, 0.07 * s, 0.033 * s, WHITE);
  });
}

// ---- the shore ------------------------------------------------------------------------------------

/** An Italian cypress: a tall dark spindle. */
export function cypress(k: Kit, x: number, y: number, z: number, h = 0.7): void {
  k.box(x, y, z, 0.03, 0.08, 0.03, hex(0x5a4632));
  k.cyl(x, y + 0.05, z, 0.07 * h, h * 0.55, CYPRESS, 7);
  k.cone(x, y + 0.05 + h * 0.55, z, 0.07 * h, h * 0.45, CYPRESS2, 7);
}

/** A pollarded plane tree (or a lime) along a quay: a pale trunk and a flat-topped crown. */
export function planeTree(k: Kit, x: number, y: number, z: number, s = 1): void {
  k.cyl(x, y, z, 0.025 * s, 0.3 * s, BARK, 6);
  k.cyl(x, y + 0.28 * s, z, 0.17 * s, 0.12 * s, PLANE, 8, PLANE2);
  k.dome(x, y + 0.4 * s, z, 0.17 * s, PLANE2, 8, 2);
}

/** A palm, as the Italian lakes grow them in their sheltered gardens. */
export function lakePalm(k: Kit, x: number, y: number, z: number, h: number, r: Rng): void {
  const lean = (r() - 0.5) * 0.06, top: P3 = [x + lean, y + h, z];
  k.bar([x, y, z], top, 0.022, hex(0x8a6a4a));
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU + r();
    k.bar(top, [x + lean + Math.cos(a) * 0.18, y + h - 0.06, z + Math.sin(a) * 0.18], 0.018, hex(0x4f8a3e));
  }
}

/** A lamp along the walk, in the style's own iron (a lantern for Léman, a globe for Como, a plain post on the American lakes). */
export function lakeLamp(k: Kit, style: string, x: number, y: number, z: number): void {
  const iron = style === 'lakeside' || style === 'victorian' ? hex(0x2a3a2e) : IRON;
  k.box(x, y, z, 0.035, 0.025, 0.035, iron);
  k.cyl(x, y, z, 0.01, 0.34, iron, 5);
  if (style === 'como') {
    k.glowBox(x, y + 0.34, z, 0.045, 0.045, 0.045, hex(0xf2ead6), LAMPS, WARM_GLOW);
  } else {
    k.glowBox(x, y + 0.34, z, 0.05, 0.065, 0.05, hex(0xe8e0c8), LAMPS, WARM_GLOW);
    k.hip(x, y + 0.405, z, 0.07, 0.03, 0.07, iron);
  }
}

/** A slatted bench facing +z (or turned). */
export function bench(k: Kit, x: number, y: number, z: number, col: RGB = hex(0x3a5a3a)): void {
  k.box(x, y + 0.04, z, 0.2, 0.012, 0.05, col);
  k.box(x, y + 0.052, z - 0.025, 0.2, 0.04, 0.008, col);
  for (const sx of [-0.08, 0.08]) k.box(x + sx, y, z, 0.01, 0.04, 0.045, IRON);
}

/** A flag on a staff: `stripes` top to bottom, or the Swiss cross (`swiss`). */
export function flagpole(k: Kit, x: number, y: number, z: number, h: number, stripes: number[], swiss = false): void {
  k.cyl(x, y, z, 0.007, h, hex(0xe8e8ea), 4);
  const fw = 0.14, fh = 0.09;
  if (swiss) {
    k.box(x + fw / 2, y + h - fh, z, fw, fh, 0.004, hex(0xd8262a));
    k.box(x + fw / 2, y + h - fh / 2 - 0.006, z, 0.05, 0.012, 0.006, WHITE);
    k.box(x + fw / 2, y + h - fh / 2 - 0.025, z, 0.012, 0.05, 0.006, WHITE);
    return;
  }
  stripes.forEach((c, i) => k.box(x + fw / 2, y + h - ((i + 1) * fh) / stripes.length, z, fw, fh / stripes.length, 0.004, hex(c)));
}

const SKIN = [0xe8c0a0, 0xc8946a, 0x8d5a3b, 0xf0d0b0, 0xa86e48].map(hex);
const SUIT = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0x1f2329].map(hex);
const CLOTHES = [0xf4f2ec, 0x2f5f9a, 0xe2412f, 0x3a7a5a, 0xf2c14e, 0x8a8f96, 0xd88aa8].map(hex);

/** Someone standing on the shore (or on a deck), feet at y, in summer clothes. */
export function stroller(k: Kit, r: Rng, x: number, y: number, z: number): void {
  const skin = SKIN[Math.floor(r() * SKIN.length)], top = CLOTHES[Math.floor(r() * CLOTHES.length)];
  k.box(x, y, z, 0.03, 0.05, 0.022, r() < 0.5 ? hex(0x2a3a5a) : hex(0xe8dcc0));
  k.box(x, y + 0.05, z, 0.036, 0.045, 0.024, top);
  k.box(x, y + 0.097, z, 0.024, 0.024, 0.024, skin);
  if (r() < 0.3) k.box(x, y + 0.122, z, 0.04, 0.006, 0.04, hex(0xe8d8a8));
}

/** A bather: lying on a towel (`lying`), or standing at the water's edge in a swimsuit. */
export function beachgoer(k: Kit, r: Rng, x: number, y: number, z: number, lying: boolean): void {
  const skin = SKIN[Math.floor(r() * SKIN.length)], suit = SUIT[Math.floor(r() * SUIT.length)];
  if (lying) {
    k.box(x, y + 0.002, z, 0.06, 0.003, 0.14, hex([0xe85a5a, 0x4a8ac0, 0xf2d04a, 0x6ab0a0][Math.floor(r() * 4)]));
    k.box(x, y + 0.005, z + 0.02, 0.03, 0.016, 0.1, skin);
    k.box(x, y + 0.008, z + 0.01, 0.032, 0.016, 0.04, suit);
    k.box(x, y + 0.008, z - 0.045, 0.022, 0.02, 0.022, skin);
    return;
  }
  k.box(x, y, z, 0.028, 0.05, 0.02, skin);
  k.box(x, y + 0.045, z, 0.032, 0.03, 0.022, suit);
  k.box(x, y + 0.075, z, 0.032, 0.02, 0.022, skin);
  k.box(x, y + 0.096, z, 0.022, 0.022, 0.022, skin);
}

/** A swimmer at the surface y, head and shoulders out, in a cap or not. */
export function swimmer(k: Kit, r: Rng, x: number, y: number, z: number): void {
  const skin = SKIN[Math.floor(r() * SKIN.length)];
  k.box(x, y - 0.012, z, 0.036, 0.018, 0.024, skin);
  k.box(x, y + 0.006, z, 0.022, 0.022, 0.022, skin);
  if (r() < 0.5) k.box(x, y + 0.024, z, 0.024, 0.008, 0.024, SUIT[Math.floor(r() * SUIT.length)]);
}

/** A beach umbrella standing in the sand. */
export function umbrella(k: Kit, x: number, y: number, z: number, col: RGB): void {
  k.cyl(x, y, z, 0.005, 0.17, hex(0xd8d4c8), 4);
  k.cone(x, y + 0.14, z, 0.11, 0.05, col, 8);
}

