/**
 * The factions' own vehicles (docs/factions.html, "Their presence in the world"). Every faction building in
 * the cells round the camera keeps a vehicle or a few at its door, in the faction's colours and always of
 * the faction's own kind: the post runs vans on rounds through the homes, the Brotherhood's lorries go
 * between the yards and the building sites, the army's 4x4s between its bases, the Family's black cars
 * from club to casino after dark. They are traffic agents driven like a touring act's (the faction says
 * where each goes next), they count against nobody's traffic, and nothing of them is simulated out of
 * memory: a cell that leaves the camera's 3x3 takes its faction vehicles with it.
 */

interface FactionTrafficHost {
  /** Islands in memory. */
  worlds(): World[];
  /** What the camera looks at, in world tiles. */
  focus(): { x: number; z: number };
  trafficOf(w: World): Traffic | null;
  /** The hour of the day. */
  hour(): number;
  seed(): string;
  /** A faction vehicle has stopped here (world tiles): it takes a load of its faction's own work waiting nearby, if there is one. */
  collect?(f: FactionId, x: number, z: number): void;
}

