/** How many vehicles a building of each kind keeps: the depots several, a plain office one, a mast none. */
const KEEPS: Record<string, number> = {
  militaryBase: 3, armyDepot: 4, airbase: 2, borderFort: 1, navalDock: 1, checkpoint: 0, bunker: 0,
  sortingOffice: 4, postOffice: 1, mailDock: 0, mailboxRow: 0,
  motorPool: 3, ministry: 1, parliament: 1, statehouse: 1, embassy: 1, mint: 1, customsPost: 1, hangar18: 1, courthouse: 0,
  buildersYard: 3, unionHall: 1, cementPlant: 2, crusher: 1, asphaltPlant: 1,
  police: 1, highwayPatrol: 2, impoundYard: 1, prison: 1,
  socialClub: 1, chopShop: 1, bossVilla: 2,
  filmStudio: 2, studioGate: 1, backlot: 2, premiereTheatre: 1, starMansion: 1,
  cannery: 1, fishMarket: 2, guildHall: 1, netLoft: 0, lifeboatStation: 0, fishFarm: 0, fishRacks: 0, shrimpShack: 1,
  newsStation: 1, broadcastCentre: 3, printworks: 2, radioStation: 1, radioMast: 0, radioTower: 0, newsstand: 0,
  crashSite: 1, landingRing: 1, crashedSatellite: 0, cropCircle: 0,
};

/** Factions out only after dark (and parked at their door by day), and only by day. */
const NIGHT_ONLY = new Set<FactionId>(['family', 'visitors']);
const DAY_ONLY = new Set<FactionId>(['police']);
const isNight = (h: number): boolean => h >= 19 || h < 5.5;

/** Where each faction's vehicles go when they go out: kinds of place, besides the faction's own other doors. */
const ERRANDS: Record<FactionId, string[]> = {
  police: ['cityHall', 'plaza', 'marketSquare', 'mall', 'bank', 'pub', 'busStation', 'hospital', 'school'],
  family: ['casino', 'nightclub', 'pub', 'bank', 'scrapyard', 'hotel', 'restaurant', 'mansion'],
  ministry: ['cityHall', 'courthouse', 'bank', 'hotel', 'airport', 'embassy', 'customsPost', 'exchange'],
  visitors: ['observatory', 'researchDome', 'farmhouse', 'barn', 'field', 'cabin'],
  unions: ['factory', 'warehouse', 'logisticsDepot', 'cementPlant', 'crusher', 'lumberYard', 'sawmill', 'office', 'towerBlock'],
  post: ['house', 'cottage', 'townhouse', 'apartment', 'bungalow', 'farmhouse', 'shop', 'store', 'mall', 'office'],
  army: ['logisticsDepot', 'police', 'hospital', 'airport', 'cityHall', 'warehouse'],
  studios: ['theatre', 'cinema', 'hotel', 'mansion', 'landmark', 'operaHouse', 'driveIn', 'concertHall'],
  guild: ['grocery', 'marketHall', 'diner', 'hotel', 'harbourOffice', 'warehouse', 'sushiBar', 'chippy'],
  press: ['cityHall', 'stadium', 'courthouse', 'police', 'theatre', 'landmark', 'arena', 'hotel'],
};

/** Seconds parked at home, and at each stop, between drives. */
const HOME_WAIT: [number, number] = [25, 80], STOP_WAIT: [number, number] = [6, 22];
/** Most faction vehicles on the road in one cell, and seconds between putting another one down. */
const CELL_CAP = 12, LAUNCH_EVERY = 0.6;
/** A post round's stops; anybody else's. */
const ROUND: Record<string, [number, number]> = { post: [3, 5], police: [2, 4], press: [1, 2] };

interface Home { w: World; b: Building; f: FactionId; x: number; z: number; key: string }
interface FVeh {
  f: FactionId; def: VehicleDef; home: Home; a: Agent | null; tr: Traffic | null;
  stops: { x: number; z: number }[]; state: 'home' | 'out' | 'back'; until: number; fails: number; air: boolean;
}
interface Cell { w: World; vehs: FVeh[]; stamp: number }

/** Which faction vehicle an agent is (the inspector, the behaviours). */
const OF = new WeakMap<Agent, FVeh>();
function factionOfAgent(a: Agent): FactionId | null { return (a.faction as FactionId | undefined) ?? null; }
/** Where it is going and what for, in words (the inspector). */
export function factionDoing(a: Agent): string | null {
  const v = OF.get(a);
  if (!v) return null;
  const at = homeName(v.home.b.kind);
  return v.state === 'home' ? `parked at the ${at}` : v.state === 'back' ? `on its way back to the ${at}` : `on its round from the ${at}`;
}
const homeName = (kind: string): string => kind.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();

const DEFS = new Map<string, VehicleDef>();
const BASE = new Map<string, VehicleDef>(ALL_VEHICLES.map((d) => [d.id, d]));
/** A model in a faction's paint (one definition per faction and model, so they share a body). */
function factionDef(f: FactionId, model: string): VehicleDef | null {
  const key = `${f}|${model}`;
  let d = DEFS.get(key);
  if (d) return d;
  const base = model === 'patrol' ? PATROL : BASE.get(model);
  if (!base) return null;
  d = paintFor(f, base);
  DEFS.set(key, d);
  return d;
}

export class FactionTraffic {
  private cells = new Map<World, Cell>();
  private clock = 0;
  private t = 0;
  private launchT = 0;
  /** Off for testing (pr.factions.traffic(false)). */
  on = true;

  constructor(private host: FactionTrafficHost) {}

  /** Everything off the road (a new world, the title). */
  clear(): void {
    for (const c of this.cells.values()) this.dropCell(c);
    this.cells.clear();
  }

  /** Every faction vehicle on the road now. */
  agents(): Agent[] {
    const out: Agent[] = [];
    for (const c of this.cells.values()) for (const v of c.vehs) if (v.a) out.push(v.a);
    return out;
  }

  /** How many are out, by faction (the gate, the console). */
  census(): Record<string, number> {
    const n: Record<string, number> = {};
    for (const c of this.cells.values()) for (const v of c.vehs) if (v.a) n[v.f] = (n[v.f] ?? 0) + 1;
    return n;
  }

  update(dt: number): void {
    if (dt <= 0) return;
    this.clock += dt;
    this.t -= dt;
    this.launchT -= dt;
    if (this.t > 0) return;
    this.t = 0.5;
    const f = this.host.focus();
    const fx = Math.floor(f.x / N), fz = Math.floor(f.z / N);
    const near = new Set<World>();
    if (this.on) for (const w of this.host.worlds()) if (Math.max(Math.abs(w.cx - fx), Math.abs(w.cz - fz)) <= 1 && this.host.trafficOf(w)) near.add(w);
    for (const [w, c] of this.cells) if (!near.has(w)) { this.dropCell(c); this.cells.delete(w); }
    const hour = this.host.hour();
    for (const w of near) {
      let c = this.cells.get(w);
      // a cell's roster is read again when its buildings change (a new one built, one knocked down)
      if (!c || c.stamp !== w.allBuildings.length) {
        if (c) this.dropCell(c);
        c = { w, vehs: this.roster(w), stamp: w.allBuildings.length };
        this.cells.set(w, c);
      }
      for (const v of c.vehs) this.steer(v, hour);
    }
  }

  private dropCell(c: Cell): void {
    for (const v of c.vehs) this.drop(v);
  }

  private drop(v: FVeh): void {
    if (v.a && v.tr) v.tr.dropTour(v.a);
    v.a = null; v.tr = null;
  }

  /** The vehicles a cell's faction buildings keep, in their order (depots first), up to the cell's cap. */
  private roster(w: World): FVeh[] {
    const homes: { h: Home; n: number }[] = [];
    for (const b of w.allBuildings) {
      if (b.gone || builtShare(b) < 1) continue;
      const f = buildingFaction(b.kind) as FactionId | undefined;
      if (!f) continue;
      const n = KEEPS[b.kind] ?? 1;
      if (n <= 0) continue;
      const k = kerbNear(w, b.x + b.w / 2, b.z + b.d / 2, 8);
      if (!k) continue;
      homes.push({ h: { w, b, f, x: k.x, z: k.z, key: `${w.cx},${w.cz}#${b.uid}` }, n });
    }
    homes.sort((a, b) => b.n - a.n || a.h.b.uid - b.h.b.uid);
    const out: FVeh[] = [];
    for (let round = 0; out.length < CELL_CAP && homes.some((h) => h.n > round); round++) {
      for (const { h, n } of homes) {
        if (round >= n || out.length >= CELL_CAP) continue;
        const r = mulberry32(hashString(`${this.host.seed()}|fac|${h.key}|${round}`));
        const pick = this.pickModel(h.f, r);
        if (!pick) continue;
        out.push({ f: h.f, def: pick.def, home: h, a: null, tr: null, stops: [], state: 'home', until: this.clock + r() * 20, fails: 0, air: pick.air });
      }
    }
    return out;
  }

  private pickModel(f: FactionId, r: () => number): { def: VehicleDef; air: boolean } | null {
    const list = ROSTER[f].filter((e) => factionDef(f, e.model));
    const total = list.reduce((s, e) => s + e.w, 0);
    if (!total) return null;
    let x = r() * total;
    for (const e of list) { x -= e.w; if (x <= 0) return { def: factionDef(f, e.model)!, air: !!e.air || factionDef(f, e.model)!.kind === 'air' }; }
    const e = list[list.length - 1];
    return { def: factionDef(f, e.model)!, air: !!e.air };
  }

  private steer(v: FVeh, hour: number): void {
    const off = (NIGHT_ONLY.has(v.f) && !isNight(hour)) || (DAY_ONLY.has(v.f) && isNight(hour));
    const tr = this.host.trafficOf(v.home.w);
    if (!tr) return;
    // the traffic gave up on it (stuck fast, nobody to tow it): it is put down at home again later
    if (v.a && v.tr && !v.tr.agents.includes(v.a)) { OF.delete(v.a); v.a = null; v.tr = null; v.state = 'home'; v.until = this.clock + 30; }
    if (!v.a) {
      // out of hours, a faction keeps one car parked at its door at most
      if (off && this.parkedOf(v)) return;
      if (this.launchT > 0) return;
      // put down out of view where it can be: a car appearing at a kerb in plain sight is a pop
      if (TRAFFIC_VIEW.on && inView(v.home.w.ox + v.home.x, v.home.w.oz + v.home.z) && this.clock - v.until < 15) return;
      const r = mulberry32(hashString(`${v.home.key}|${Math.floor(this.clock)}`));
      const a = tr.launchFaction(v.def, v.home.x, v.home.z, r() * Math.PI * 2, v.f);
      if (!a) { v.fails++; v.until = this.clock + 20; return; }
      this.launchT = LAUNCH_EVERY;
      v.a = a; v.tr = tr; v.state = 'home'; v.stops = [];
      v.until = this.clock + rand(HOME_WAIT) * 0.5;
      OF.set(a, v);
      return;
    }
    const a = v.a;
    if (a.phase !== 'parked') return;
    if (this.clock < v.until) return;
    if (off) {
      // out of hours: home, and stay there
      if (v.state !== 'home') this.go(v, { x: v.home.x, z: v.home.z }, 'back');
      return;
    }
    if (v.state === 'back') { v.state = 'home'; v.until = this.clock + rand(HOME_WAIT); return; }
    if (v.state === 'home') {
      v.stops = this.round(v);
      if (!v.stops.length) { v.until = this.clock + rand(HOME_WAIT); return; }
      this.go(v, v.stops.shift()!, 'out');
      return;
    }
    // out, and stopped: anything of the faction's own waiting here goes with it; then the next stop, or home
    this.host.collect?.(v.f, a.w.ox + a.state.x, a.w.oz + a.state.z);
    const next = v.stops.shift();
    if (next) this.go(v, next, 'out');
    else this.go(v, { x: v.home.x, z: v.home.z }, 'back');
  }

  /** Is another of this home's faction already standing at the door out of hours? */
  private parkedOf(v: FVeh): boolean {
    const c = this.cells.get(v.home.w);
    return !!c && c.vehs.some((o) => o !== v && o.home === v.home && o.a);
  }

  private go(v: FVeh, to: { x: number; z: number }, state: 'out' | 'back'): void {
    const a = v.a!, tr = v.tr!;
    // the target in the vehicle's own frame (it may have wandered over a border)
    const tx = to.x + v.home.w.ox - a.w.ox, tz = to.z + v.home.w.oz - a.w.oz;
    if (tr.driveOwned(a, tx, tz)) { v.state = state; v.fails = 0; v.until = this.clock + rand(STOP_WAIT); return; }
    v.fails++;
    v.until = this.clock + 4;
    // nowhere it can get to from here: home, or off the road if even that fails
    if (v.fails > 4) { OF.delete(a); this.drop(v); v.state = 'home'; v.until = this.clock + 60; }
    else if (state === 'out') { v.stops = []; v.state = 'out'; }
  }

  /** The stops of one drive out: the faction's other doors in the cell, or its kind of errand, as kerbs. */
  private round(v: FVeh): { x: number; z: number }[] {
    const w = v.home.w;
    const r = mulberry32(hashString(`${v.home.key}|round|${Math.floor(this.clock / 7)}`));
    const own = w.allBuildings.filter((b) => !b.gone && b !== v.home.b && buildingFaction(b.kind) === v.f);
    const errand = new Set(ERRANDS[v.f]);
    // the Brotherhood goes where the building sites are
    const sites = v.f === 'unions' ? w.allBuildings.filter((b) => !b.gone && builtShare(b) < 1) : [];
    const there = w.allBuildings.filter((b) => !b.gone && errand.has(b.kind));
    const [lo, hi] = ROUND[v.f] ?? [1, 2];
    const n = lo + Math.floor(r() * (hi - lo + 1));
    const out: { x: number; z: number }[] = [];
    for (let k = 0; k < n * 3 && out.length < n; k++) {
      const pool = sites.length && r() < 0.6 ? sites : own.length && r() < 0.45 ? own : there.length ? there : own;
      if (!pool.length) break;
      const b = pool[Math.floor(r() * pool.length)];
      if (v.air) { out.push({ x: b.x + b.w / 2, z: b.z + b.d / 2 }); continue; }
      const kb = kerbNear(w, b.x + b.w / 2, b.z + b.d / 2, 8);
      if (kb && Math.hypot(kb.x - v.home.x, kb.z - v.home.z) > 6) out.push(kb);
    }
    return out;
  }

  /** Console: what is out, by faction. */
  console(): unknown {
    return { census: this.census(), cells: [...this.cells.values()].map((c) => ({ cell: `${c.w.cx},${c.w.cz}`, keeps: c.vehs.length, out: c.vehs.filter((v) => v.a).length })) };
  }
}

const rand = ([a, b]: [number, number]): number => a + Math.random() * (b - a);

function inView(x: number, z: number): boolean {
  const f = TRAFFIC_VIEW.frustum;
  for (const p of f.planes) if (p.normal.x * x + p.normal.y * 1 + p.normal.z * z + p.constant < -6) return false;
  return true;
}

export { FACTIONS };
