import type { Arch, TownKind } from '../world/tiles';
import { press } from './press/desk';
import { ARCH_LABEL } from './missions/passport';
import { goodOf, METEORITE_MASS } from './cultureGoods';
import { deeds } from './deeds';
import type { CultureBookMsg, CultureReport, TownCultureWire } from '../../shared/culture';

/**
 * Culture (docs/passport.html): a second scale for a town, beside its size. The only way to raise a town's
 * culture is to go somewhere it has never received anything from, pick up the cultural goods waiting there (its
 * food, its art, its cloth: game/cultureGoods.ts), and carry them to one of the fleet's halls (docs/culturegate.html):
 * the town its HQ stands in, or any town it holds, each with a book of its own. Their culture is the style of the
 * place they came from; their points grow with the distance, in cells, from the hall they are handed in at.
 *
 * On the ground and in the hold they are ordinary cargo (game/cargo.ts carries them, the host keeps the two in
 * step). One rule is theirs: a vehicle carries five units of cultural goods at most, whatever its hold, so the
 * big consignments that seal an Influenced town (10) and an Infatuated one (20) need the fleet in formation behind you.
 *
 * Nothing here draws or reads the world: the host says where home is, who is in the convoy and what a
 * sighting was, so the rules run headless (npm run culture).
 */

export const CULTURE = {
  /** Units of cultural goods one vehicle may carry, however big its hold. */
  per: 5,
  /** Points to Curiosity, Influenced and Infatuated (RUNG_NAME). */
  rungs: [50, 150, 400] as const,
  /** The consignment that seals Influenced and Infatuated, in units: more than one vehicle's worth. */
  seal: [10, 20] as const,
  /** Diamonds at each rung. */
  gems: [2, 5, 12] as const,
  /** The most distance can multiply a sighting's points by. */
  maxMul: 6,
  /** A delivery's festival: game hours, and what goods put out in the town are worth meanwhile. */
  festival: 24, festivalMul: 1.15,
  /** A twinned style's share of the town's own new buildings. */
  twinChance: 0.3,
  /** Dollars per unit per (1 + cells). */
  pay: 40,
  /** A Visitors Twin: what goods put out in the town after dark are worth. */
  nightMul: 1.25,
};

/**
 * The Visitors (the user, 27 Oct 2026): a culture with no town of its own. Its goods are the meteorites a shower
 * leaves (game/meteorites.ts), and the consignment that seals its Quarter and Twin is a meteorite's main mass, found
 * after a shower once the town has the points. What it does at each rung is its own: the Visitors warm to the
 * fleet with every stone, a Quarter offers their buildings on the town's menu (game/lobby.ts), a Twin makes the
 * town's night trade dearer. It never dresses a building, so it is kept out of the styles the town builds in.
 */
export const VISITOR = 'visitor' as const;
/** The plain style: what open country with no town builds in (world/towns.ts pickStyle's fallback), for the culture gate. */
const PLAIN: Arch = 'classic';
/** A culture a town can import: a town style, or the Visitors'. */
export type CultureStyle = Arch | typeof VISITOR;
/** A culture's name. */
export const styleLabel = (s: CultureStyle): string => (s === VISITOR ? 'Visitors' : ARCH_LABEL[s] ?? s);

type CrateType = 'arch' | 'wonder' | 'sig' | 'biome' | 'landform' | 'meteor' | 'seal';
const BASE: Record<Exclude<CrateType, 'seal'>, number> = { arch: 40, wonder: 40, sig: 15, biome: 20, landform: 10, meteor: 25 };
const WEIGHT: Record<Exclude<CrateType, 'seal'>, number> = { arch: 3, wonder: 3, sig: 2, biome: 2, landform: 1, meteor: 2 };
/** How many imported styles a town of each size holds at Influenced or above (slots.quarter), and at Infatuated (slots.twin). */
export const SLOTS: Record<TownKind, { quarter: number; twin: number }> = {
  rural: { quarter: 1, twin: 0 }, suburb: { quarter: 1, twin: 0 }, city: { quarter: 2, twin: 1 }, metro: { quarter: 3, twin: 1 }, mega: { quarter: 4, twin: 2 },
};
/**
 * The rungs as the player reads them (the user, 4 Nov 2026: Quarter and Twin confused; docs/culturegate.html).
 * The code keeps its old names (SLOTS.quarter, twinStyle, seal levels 2 and 3) so nothing in the saves moves.
 */
export const RUNG_NAME = ['', 'Curiosity', 'Influenced', 'Infatuated'] as const;
/** The rung with its style in a sentence: "Influenced by Tokyo", "Infatuated with Tokyo", "curious about Tokyo". */
export const rungPhrase = (rung: number, label: string): string => (rung >= 3 ? `Infatuated with ${label}` : rung === 2 ? `Influenced by ${label}` : rung === 1 ? `curious about ${label}` : label);

/** One load of cultural goods, waiting where it was found or aboard on its way home. */
export interface Crate {
  id: number;
  type: CrateType;
  /** What it is a first of: the style, the wonder's kind, the building's, the biome, the landform; for a seal, the style. */
  key: string;
  /** The culture it carries. */
  style: CultureStyle;
  /** What it is: the good, its icon and its colour on the ground. */
  good: { name: string; icon: string; color: number };
  /** The place it waits at. */
  from: string;
  cx: number; cz: number;
  /** Where it stands, in world tiles. */
  x: number; z: number; y: number;
  /** Units of hold it fills. */
  weight: number;
  /** A seal's rung: 2 Influenced, 3 Infatuated. */
  level?: 2 | 3;
  /** The game hour it is gone from the ground if nobody has picked it up (a meteorite). */
  until?: number;
  /** A meteorite's stone (game/meteorites.ts Fall.id): which crater it lies in. */
  stone?: string;
  /** The town the place stands in, by key: its own hall gains nothing from it. */
  town?: string;
}

/**
 * A hall (docs/culturegate.html): a town where the fleet may hand cultural goods in, and whose book they write in.
 * The HQ's town (`hq`; or the nearest town of the HQ's county when the HQ stands in open country), and every town
 * the fleet holds as uncontested territory. The host keeps the list.
 */
export interface Hall {
  key: string; name: string; style: Arch; kind: TownKind;
  cx: number; cz: number;
  /** Where the goods are handed over, in world tiles: the HQ's door, or the town hall's. */
  x: number; z: number; y: number;
  /** The HQ's own town. */
  hq?: boolean;
}
/** (The one home town, before halls: 4 Nov 2026.) */
export type Home = Hall;

/** One town's culture: points per style, what it has received and from how far, the seals, the rungs paid for. */
interface TownCulture {
  pts: Partial<Record<CultureStyle, number>>;
  got: Record<string, number>;
  seal: Partial<Record<CultureStyle, number>>;
  paid: Partial<Record<CultureStyle, number>>;
  /** The game hour its festival ends. */
  fest: number;
  kind: TownKind; style: Arch; name: string;
}

export interface CultureHost {
  /** Where goods may be handed in: the HQ's town first, then every town held (docs/culturegate.html). */
  halls(): Hall[];
  /** Where the player's vehicle is, in world tiles, for which hall a load is bound for on a tie. */
  at?(): { x: number; z: number } | null;
  /** The game clock, in hours. */
  hours(): number;
  /** The holds in the convoy: the vehicle in the player's hands, then every one in formation behind it. */
  convoy(): number[];
  /** Trade carried for a town, by key: it counts for the fleet's standing there. */
  credit(key: string, dollars: number): void;
  gems(n: number): void;
  announce(title: string, body: string): void;
}

/**
 * `pts` and `seal` are the town's, every fleet's together online (docs: shared/culture.ts); `mine` the player's own part;
 * `lead` the fleet with the most points in it, by name ('' offline or with nobody else's part yet).
 */
export interface Strand { style: CultureStyle; label: string; pts: number; rung: number; raw: number; seal: number; next: number | null; needs: string; mine: number; lead: string }

export interface SavedCulture {
  towns: Record<string, TownCulture>;
  waiting: Crate[];
  aboard: Crate[];
  next: number;
}

const cellsBetween = (ax: number, az: number, bx: number, bz: number): number => Math.round(Math.hypot(ax - bx, az - bz));
const typeKey = (type: CrateType, key: string, level?: number): string => (type === 'seal' ? `seal:${key}:${level}` : `${type}:${key}`);
const crateKey = (c: Crate): string => typeKey(c.type, c.key, c.level);

export class Culture {
  private towns = new Map<string, TownCulture>();
  waiting: Crate[] = [];
  aboard: Crate[] = [];
  private next = 1;
  private lastHalls = '';
  /** Bumped whenever anything changes, for the card and the book. */
  revision = 0;

  /**
   * Online, every fleet's parts in each town (server/townCulture.ts): a town's culture is all of theirs together with
   * the player's own book, so what one fleet brings a town shows, and counts, for everyone (the user, 4 Nov 2026).
   */
  private world = new Map<string, TownCultureWire>();
  /** The player's own id online: their part in the world's book is their own book here, never counted twice. */
  me: string | null = null;
  /** A town's book changed: the fleet's own running totals there, for the world's book (net/cultureNet.ts). */
  onShare: ((key: string, t: CultureReport['towns'][string]) => void) | null = null;

  constructor(private host: CultureHost) {}

  /** Everyone else's points and strongest seal in a town's style, and the fleet with the most points (theirs or the player's). */
  private others(key: string, style: CultureStyle): { pts: number; seal: number; lead: string; leadPts: number } {
    const rows = this.world.get(key)?.st[style];
    let pts = 0, seal = 0, lead = '', leadPts = 0;
    for (const [pid, name, p, sl] of rows ?? []) {
      if (p > leadPts) { lead = name; leadPts = p; }
      if (pid === this.me) continue;
      pts += p;
      seal = Math.max(seal, sl);
    }
    return { pts, seal, lead, leadPts };
  }
  /** A town's points in a style: the player's own and everyone else's. */
  private ptsOf(key: string, style: CultureStyle): number { return (this.towns.get(key)?.pts[style] ?? 0) + this.others(key, style).pts; }
  /** A town's seal in a style: the strongest anyone has handed in. */
  private sealOf(key: string, style: CultureStyle): number { return Math.max(this.towns.get(key)?.seal[style] ?? 0, this.others(key, style).seal); }

  // ---- reading ----

  /** A town's book, made the first time it is asked for. */
  private book(h: Hall): TownCulture {
    let t = this.towns.get(h.key);
    if (!t) this.towns.set(h.key, (t = { pts: {}, got: {}, seal: {}, paid: {}, fest: 0, kind: h.kind, style: h.style, name: h.name }));
    t.kind = h.kind; t.style = h.style; t.name = h.name;
    return t;
  }

  /** The rung the points and the seal reach, before the town's size is asked: 0 none, 1 Curiosity, 2 Influenced, 3 Infatuated. */
  private raw(key: string, style: CultureStyle): number {
    const p = this.ptsOf(key, style), s = this.sealOf(key, style);
    if (p >= CULTURE.rungs[2] && s >= 3) return 3;
    if (p >= CULTURE.rungs[1] && s >= 2) return 2;
    return p >= CULTURE.rungs[0] ? 1 : 0;
  }

  /** Every style a town has points in, strongest first, at the rung its size lets it hold. */
  strands(key: string): Strand[] {
    const t = this.towns.get(key), w = this.world.get(key);
    if (!t && !w) return [];
    const kind = (t?.kind ?? w!.k) as TownKind, name = t?.name || w?.n || '', own = t?.style ?? w?.s;
    const slots = SLOTS[kind] ?? SLOTS.rural;
    let quarter = slots.quarter, twin = slots.twin;
    const all = new Set<CultureStyle>([...Object.keys(t?.pts ?? {}), ...Object.keys(w?.st ?? {})] as CultureStyle[]);
    const styles = [...all].filter((s) => s !== own && this.ptsOf(key, s) > 0).sort((a, b) => this.ptsOf(key, b) - this.ptsOf(key, a) || (a < b ? -1 : 1));
    return styles.map((style) => {
      const pts = this.ptsOf(key, style), raw = this.raw(key, style), seal = this.sealOf(key, style);
      let rung = raw;
      if (rung >= 3) { if (twin > 0) twin--; else rung = 2; }
      if (rung >= 2) { if (quarter > 0) quarter--; else rung = 1; }
      const next = pts < CULTURE.rungs[0] ? CULTURE.rungs[0] : pts < CULTURE.rungs[1] ? CULTURE.rungs[1] : pts < CULTURE.rungs[2] ? CULTURE.rungs[2] : null;
      let needs = '';
      if (rung < raw) needs = `${name} is too small to hold another ${RUNG_NAME[raw]}`;
      else if (style === VISITOR && pts >= CULTURE.rungs[1] && seal < (pts >= CULTURE.rungs[2] && seal >= 2 ? 3 : 2)) needs = `a meteorite's main mass (${CULTURE.seal[seal >= 2 ? 1 : 0]} units), found after a meteor shower`;
      else if (pts >= CULTURE.rungs[2] && seal < 3 && seal >= 2) needs = `the ${RUNG_NAME[3]} consignment: ${CULTURE.seal[1]} units from any ${styleLabel(style)} town`;
      else if (pts >= CULTURE.rungs[1] && seal < 2) needs = `the ${RUNG_NAME[2]} consignment: ${CULTURE.seal[0]} units from any ${styleLabel(style)} town`;
      return { style, label: styleLabel(style), pts, rung, raw, seal, next, needs, mine: t?.pts[style] ?? 0, lead: this.others(key, style).lead };
    });
  }

  rung(key: string, style: CultureStyle): number { return this.strands(key).find((s) => s.style === style)?.rung ?? 0; }

  /**
   * Who brought a town its culture in a style (docs/townregister.html, the town card's Culture tab): every fleet's
   * points, most first, the player's own marked. Online the other fleets come from the world's book; alone, only yours.
   */
  contributors(key: string, style: CultureStyle): { name: string; pts: number; you: boolean }[] {
    const out: { name: string; pts: number; you: boolean }[] = [];
    const mine = this.towns.get(key)?.pts[style] ?? 0;
    if (mine > 0) out.push({ name: '', pts: mine, you: true });
    for (const [pid, name, p] of this.world.get(key)?.st[style] ?? []) if (pid !== this.me && p > 0) out.push({ name, pts: p, you: false });
    return out.sort((a, b) => b.pts - a.pts || (a.you ? -1 : b.you ? 1 : a.name.localeCompare(b.name)));
  }

  /** Every town with a book that has anything in it (points or a seal), for the Passport: once a hall, its book is kept. */
  books(): { key: string; name: string; style: Arch; kind: TownKind }[] {
    const out: { key: string; name: string; style: Arch; kind: TownKind }[] = [];
    for (const [key, t] of this.towns) if (Object.values(t.pts).some((p) => (p ?? 0) > 0) || Object.keys(t.seal).length) out.push({ key, name: t.name, style: t.style, kind: t.kind });
    return out;
  }
  points(key: string, style: CultureStyle): number { return this.ptsOf(key, style); }

  /** The styles native to a town beyond its own: Influenced and up (the culture gate, docs/culturegate.html). The Visitors dress no building. */
  styles(key: string): { style: Arch; label: string }[] {
    const out: { style: Arch; label: string }[] = [];
    for (const s of this.strands(key)) if (s.rung >= 2 && s.style !== VISITOR) out.push({ style: s.style, label: s.label });
    return out;
  }

  /**
   * The culture gate (docs/culturegate.html): why a building in `style` may not go up inside a town's lines, or
   * null when it may. The town's own style is always native; so is any style the town is Influenced by or
   * Infatuated with, at the rung its size lets it hold. Otherwise the line says how far the town's book is.
   */
  whyNotNative(key: string, style: Arch, townName: string, ownStyle: Arch): string | null {
    if (style === ownStyle) return null;
    const label = styleLabel(style);
    const s = this.strands(key).find((q) => q.style === style);
    if (s && s.rung >= 2) return null;
    const pts = s?.pts ?? 0;
    if (pts <= 0) return `${townName} has taken no ${label} goods yet: bring it some first`;
    if (s && s.rung < s.raw) return `${townName} is too small to be ${RUNG_NAME[2]} by another style`;
    if (pts < CULTURE.rungs[1]) return `${townName} is not ${rungPhrase(2, label)} yet: bring it ${label} goods · ${pts} of ${CULTURE.rungs[1]}`;
    return `${townName} has the points to be ${rungPhrase(2, label)} but needs ${s?.needs || `the ${RUNG_NAME[2]} consignment: ${CULTURE.seal[0]} units from any ${label} town`}`;
  }

  /**
   * The gate in open country: native there is the own style of any town of the county, or any style one of them is
   * Influenced by. A county with no towns builds in the plain style only, so no variant can ever stand in it.
   */
  whyNotNativeCounty(towns: { key: string; style: Arch }[], style: Arch): string | null {
    const label = styleLabel(style);
    if (!towns.length) return style === PLAIN ? null : `Nothing out here builds in ${label} style`;
    for (const t of towns) if (t.style === style || this.rung(t.key, style) >= 2) return null;
    return `No town in this county is ${rungPhrase(2, label)}: bring one ${label} goods first`;
  }

  /** The Visitors' rung in a town: Influenced puts their buildings on its menu, Infatuated makes its night trade dearer. */
  visitors(key: string): number { return this.rung(key, VISITOR); }

  /** The style a twinned town puts its own next building up in, for a roll in 0..1; null for its own. */
  twinStyle(key: string, u: number): Arch | null {
    const twins = this.strands(key).filter((s) => s.rung >= 3);
    for (const s of twins) {
      if (s.style === VISITOR) continue;
      if (u < CULTURE.twinChance) return s.style;
      u -= CULTURE.twinChance;
    }
    return null;
  }

  /** "Chicago + Tokyo": the styles a town is twinned with, for its card. */
  twins(key: string): string[] { return this.strands(key).filter((s) => s.rung >= 3 && s.style !== VISITOR).map((s) => s.label); }

  /** What goods put out in a town are worth: more while its festival runs, and after dark in a Visitors Twin. */
  festivalMul(key: string, night = false): number {
    return (this.festivalLeft(key) > 0 ? CULTURE.festivalMul : 1) * (night && this.visitors(key) >= 3 ? CULTURE.nightMul : 1);
  }
  festivalLeft(key: string): number { return Math.max(0, (this.towns.get(key)?.fest ?? 0) - this.host.hours()); }

  /** What a town has received, as type keys, for the book's "never received from". */
  received(key: string): string[] { return Object.keys(this.towns.get(key)?.got ?? {}); }

  // ---- the halls ----

  /** Where the fleet may hand cultural goods in: its HQ's town first, then every town it holds (docs/culturegate.html). */
  halls(): Hall[] { return this.host.halls(); }
  /** The HQ's hall (else the first): the Passport's first page and the console's default. */
  hq(): Hall | null { const halls = this.halls(); return halls.find((h) => h.hq) ?? halls[0] ?? null; }

  /** The consignment a hall's town is ready for in a style (the points, no seal yet, a slot at its size): 2, 3, or 0 for none. */
  private sealReady(h: Hall, style: CultureStyle): 2 | 3 | 0 {
    if (style === h.style) return 0;
    const t = this.book(h);
    const pts = this.ptsOf(h.key, style), seal = this.sealOf(h.key, style);
    const level: 2 | 3 | 0 = pts >= CULTURE.rungs[2] && seal === 2 ? 3 : pts >= CULTURE.rungs[1] && seal < 2 ? 2 : 0;
    if (!level) return 0;
    const slots = SLOTS[t.kind];
    const sealed = new Set<CultureStyle>([...Object.keys(t.seal), ...Object.keys(this.world.get(h.key)?.st ?? {})] as CultureStyle[]);
    const others = [...sealed].filter((q) => q !== VISITOR && q !== style && this.sealOf(h.key, q) >= level).length;
    return others >= (level === 3 ? slots.twin : slots.quarter) ? 0 : level;
  }

  /**
   * The hall a load is bound for: a consignment, the nearest hall whose town is ready for it; anything else, the
   * hall it brings most to, the nearest on a tie (never the town it came from). Null when no hall takes it.
   */
  bound(c: Crate): Hall | null {
    const at = this.host.at?.() ?? null;
    const dist = (h: Hall) => (at ? Math.hypot(h.x - at.x, h.z - at.z) : cellsBetween(h.cx, h.cz, c.cx, c.cz));
    let best: Hall | null = null, bestPts = -1, bestD = Infinity;
    for (const h of this.halls()) {
      if (c.type === 'seal') {
        if (this.sealReady(h, c.style) !== c.level) continue;
        const d = dist(h);
        if (d < bestD) { best = h; bestD = d; }
        continue;
      }
      if (c.town && c.town === h.key) continue;
      const pts = this.worth(h, c.type, c.key, c.style, c.cx, c.cz).pts, d = dist(h);
      if (pts > bestPts || (pts === bestPts && d < bestD)) { best = h; bestPts = pts; bestD = d; }
    }
    return best;
  }

  /** Does any hall gain from this load (points, or a consignment its town is ready for)? */
  private gains(c: Crate): boolean {
    if (c.type === 'seal') return c.style === VISITOR || this.halls().some((h) => this.sealReady(h, c.style) === c.level);
    const type = c.type as Exclude<CrateType, 'seal'>;
    return this.halls().some((h) => c.town !== h.key && this.worth(h, type, c.key, c.style, c.cx, c.cz).pts > 0);
  }

  /** Why a load can't be handed in at this hall, or null: a consignment goes only to a town ready for its rung. */
  whyNotDue(c: Crate, h: Hall): string | null {
    if (c.type !== 'seal' || this.sealReady(h, c.style) === c.level) return null;
    const ready = this.bound(c);
    return `${h.name} is not ready to be ${rungPhrase(c.level ?? 2, styleLabel(c.style))}: ${ready ? `hand it in at ${ready.name}` : 'no town of yours has the points yet'}`;
  }

  /** The halls may have changed (a town gained or lost, the HQ moved): loads that would bring none of them anything are let go of. The host calls it as it syncs. */
  sync(): void { this.rehall(); }

  // ---- what a load is worth ----

  /**
   * The points a first of this type from this far would bring the home town: the base times one more than
   * the cells between, the full base for a type it has never received, half for one it has only had from
   * nearer, nothing otherwise. Goods in the town's own style bring nothing: it has that already.
   */
  worth(h: Hall, type: Exclude<CrateType, 'seal'>, key: string, style: CultureStyle, cx: number, cz: number): { pts: number; cells: number } {
    const cells = cellsBetween(h.cx, h.cz, cx, cz);
    if (style === h.style) return { pts: 0, cells };
    const had = this.towns.get(h.key)?.got[typeKey(type, key)];
    const base = had === undefined ? BASE[type] : cells > had ? BASE[type] / 2 : 0;
    return { pts: Math.round(base * Math.min(CULTURE.maxMul, 1 + cells)), cells };
  }

  /** What a load pays on delivery, in dollars: like any long haul, by its size and the distance. */
  pay(c: Crate, h: Hall | null = this.bound(c)): number {
    return Math.round(CULTURE.pay * c.weight * (1 + (h ? cellsBetween(h.cx, h.cz, c.cx, c.cz) : 0)));
  }

  /**
   * The hover card's line: which hall the goods are bound for and what they would do there, and what the other
   * halls would gain. "Hand it in at Dunmere's hall to raise Tokyo culture there (+160 · 40 of 150 to Influenced) · or Port Alder +90".
   */
  tip(c: Crate, h: Hall | null = this.bound(c)): string {
    const style = styleLabel(c.style);
    if (!h) {
      if (c.type === 'seal') return `Cultural cargo: all ${c.weight} units, for a town of yours ready to be ${rungPhrase(c.level ?? 2, style)}.`;
      return `Cultural cargo: ${style}. Hand it in at your HQ, or at the hall of a town you hold, to raise its ${style} culture.`;
    }
    const where = (q: Hall) => (q.hq ? `your HQ in ${q.name}` : `${q.name}’s hall`);
    if (c.type === 'seal') return `Cultural cargo: bring all ${c.weight} units to ${where(h)} to make it ${rungPhrase(c.level ?? 2, style)}.`;
    const s = this.strands(h.key).find((q) => q.style === c.style);
    const pts = s?.pts ?? 0;
    const gain = this.worth(h, c.type, c.key, c.style, c.cx, c.cz).pts;
    const next = s?.next ?? (pts < CULTURE.rungs[0] ? CULTURE.rungs[0] : pts < CULTURE.rungs[1] ? CULTURE.rungs[1] : pts < CULTURE.rungs[2] ? CULTURE.rungs[2] : null);
    const rung = next === null ? '' : RUNG_NAME[CULTURE.rungs.indexOf(next as 50 | 150 | 400) + 1];
    const how = next === null ? `${pts} so far` : `${pts} of ${next} to ${rung}`;
    const type = c.type as Exclude<CrateType, 'seal'>;
    const others = this.halls().filter((q) => q.key !== h.key && q.key !== c.town).map((q) => ({ q, gain: this.worth(q, type, c.key, c.style, c.cx, c.cz).pts })).filter((o) => o.gain > 0).sort((a, b) => b.gain - a.gain).slice(0, 2);
    return `Cultural cargo: hand it in at ${where(h)} to raise ${style} culture in ${h.name} (+${gain} · ${how})${others.length ? ` · or ${others.map((o) => `${o.q.name} +${o.gain}`).join(', ')}` : ''}.`;
  }

  private has(k: string): boolean { return this.waiting.some((c) => crateKey(c) === k) || this.aboard.some((c) => crateKey(c) === k); }

  // ---- sightings ----

  /**
   * The player has reached something: if any hall's town has never received its like (or only from nearer),
   * cultural goods wait there from now on. `style` is the town's the place stands in, or the nearest town's.
   * Returns the load when one was put out. Nothing is announced: it is just more cargo on the ground.
   */
  sight(type: Exclude<CrateType, 'seal'>, key: string, style: CultureStyle, at: { cx: number; cz: number; x: number; z: number; y: number; name: string; town?: string }): Crate | null {
    const halls = this.halls();
    if (!halls.length || !key) return null;
    this.rehall();
    const k = typeKey(type, key);
    if (this.has(k)) return null;
    // a town's own buildings and ground are not imports for it: some other hall must gain
    if (!halls.some((h) => at.town !== h.key && this.worth(h, type, key, style, at.cx, at.cz).pts > 0)) return null;
    const c: Crate = { id: this.next++, type, key, style, good: goodOf(style, k), from: at.name, cx: at.cx, cz: at.cz, x: at.x, z: at.z, y: at.y, weight: WEIGHT[type], ...(at.town ? { town: at.town } : {}) };
    this.waiting.push(c);
    this.revision++;
    return c;
  }

  /**
   * A meteorite has come down (game/meteorites.ts): it waits where it fell until `until`, a Visitors good. The
   * shower's first stone is the main mass instead when a hall's town has the points for the Visitors' next rung and
   * room for it, the consignment that seals the rung. Nothing for a stone every hall already has.
   */
  fall(id: string, first: boolean, until: number, at: { cx: number; cz: number; x: number; z: number; y: number; name: string }): Crate | null {
    const halls = this.halls();
    if (!halls.length || this.host.hours() >= until) return null;
    this.rehall();
    if (first) {
      for (const h of halls) {
        const level = this.sealReady(h, VISITOR);
        const k = typeKey('seal', VISITOR, level);
        if (!level || this.has(k)) continue;
        const c: Crate = { id: this.next++, type: 'seal', key: VISITOR, style: VISITOR, good: METEORITE_MASS, from: at.name, cx: at.cx, cz: at.cz, x: at.x, z: at.z, y: at.y, weight: CULTURE.seal[level - 2], level, until, stone: id };
        this.waiting.push(c);
        this.revision++;
        return c;
      }
    }
    const c = this.sight('meteor', id, VISITOR, at);
    if (c) { c.until = until; c.stone = id; }
    return c;
  }

  /** Meteorites nobody picked up are gone after their day. Aboard, a stone is the player's to keep. */
  prune(): void {
    const now = this.host.hours();
    const left = this.waiting.filter((c) => c.until === undefined || c.until > now);
    if (left.length === this.waiting.length) return;
    this.waiting = left;
    this.revision++;
  }

  /**
   * The player has driven into a town of a style: if a hall's town has the points for the next rung in it and room
   * at its size, the consignment that seals the rung waits at this town from now on, bound for that hall.
   */
  visit(style: Arch, at: { cx: number; cz: number; x: number; z: number; y: number; name: string; town?: string }): Crate | null {
    const halls = this.halls();
    if (!halls.length) return null;
    this.rehall();
    for (const h of halls) {
      if (style === h.style || at.town === h.key) continue;
      const level = this.sealReady(h, style);
      if (!level) continue;
      const k = typeKey('seal', style, level);
      if (this.has(k)) continue;
      const c: Crate = { id: this.next++, type: 'seal', key: style, style, good: goodOf(style, k), from: at.name, cx: at.cx, cz: at.cz, x: at.x, z: at.z, y: at.y, weight: CULTURE.seal[level - 2], level, ...(at.town ? { town: at.town } : {}) };
      this.waiting.push(c);
      this.revision++;
      return c;
    }
    return null;
  }

  /** The halls have changed (a town gained or lost, the HQ moved): goods waiting that would bring none of them anything are no longer put out. */
  private rehall(): void {
    const halls = this.halls();
    if (!halls.length) return;
    for (const h of halls) this.book(h);
    const sig = halls.map((h) => h.key).sort().join('|');
    if (sig === this.lastHalls) return;
    const first = !this.lastHalls;
    this.lastHalls = sig;
    if (first) return;
    // a town's seals were put out for a hall now gone; a meteorite's main mass is just gone with its day
    const n = this.waiting.length;
    this.waiting = this.waiting.filter((c) => this.gains(c));
    if (this.waiting.length !== n) this.revision++;
  }

  // ---- carrying ----

  /** Units of cultural goods the convoy may carry: five a vehicle, or its whole hold if that is less. */
  room(): number { return this.host.convoy().reduce((s, cap) => s + Math.min(CULTURE.per, cap), 0); }
  weight(): number { return this.aboard.reduce((s, c) => s + c.weight, 0); }

  /** Why a load can't be taken aboard with what is aboard now, or null: the five-a-vehicle rule. The hold's own space is the cargo's to judge. */
  whyNot(c: Crate): string | null {
    const convoy = this.host.convoy();
    const room = this.room() - this.weight();
    if (c.weight <= room) return null;
    const need = Math.ceil((this.weight() + c.weight) / CULTURE.per);
    if (need > convoy.length) return `Cultural goods travel ${CULTURE.per} units a vehicle: ${need} vehicles in formation needed, you have ${convoy.length}`;
    return `No room for more cultural goods: ${Math.max(0, room)} units free across your convoy (${CULTURE.per} a vehicle at most)`;
  }

  find(id: number): Crate | null { return this.waiting.find((c) => c.id === id) ?? this.aboard.find((c) => c.id === id) ?? null; }

  /** A waiting load has been taken aboard. */
  taken(id: number): void {
    const k = this.waiting.findIndex((c) => c.id === id);
    if (k < 0) return;
    this.aboard.push(...this.waiting.splice(k, 1));
    this.revision++;
  }

  /** A load aboard has been left behind (abandoned, or no room in a new vehicle): it waits where it came from again. */
  putBack(id: number): void {
    const k = this.aboard.findIndex((c) => c.id === id);
    if (k < 0) return;
    this.waiting.push(...this.aboard.splice(k, 1));
    this.revision++;
  }

  /** Loads paid for but handed over with no home town to take their points: off the books, so they can't be paid twice. */
  discard(ids: number[]): void {
    const n = this.aboard.length;
    this.aboard = this.aboard.filter((c) => !ids.includes(c.id));
    if (this.aboard.length !== n) this.revision++;
  }

  /**
   * Loads handed over at the HQ: their points go to the home town, its festival starts, and any rung reached
   * for the first time pays in diamonds. The cargo has already paid `paid` dollars for them; it counts as
   * trade carried for the town. Returns the points gained.
   */
  deliver(h: Hall, ids: number[] = this.aboard.map((c) => c.id), paid = 0): number {
    const t = this.book(h);
    this.rehall();
    const list = this.aboard.filter((c) => ids.includes(c.id));
    if (!list.length) return 0;
    const before = new Map(this.strands(h.key).map((s) => [s.style, s.rung]));
    let gained = 0, far = 0;
    const lines: string[] = [];
    for (const c of list) {
      const cells = cellsBetween(h.cx, h.cz, c.cx, c.cz);
      far = Math.max(far, cells);
      if (c.type === 'seal') {
        t.seal[c.style] = Math.max(t.seal[c.style] ?? 0, c.level ?? 2);
        continue;
      }
      const w = this.worth(h, c.type, c.key, c.style, c.cx, c.cz);
      const k = typeKey(c.type, c.key);
      t.got[k] = Math.max(t.got[k] ?? 0, cells);
      if (w.pts > 0) {
        t.pts[c.style] = (t.pts[c.style] ?? 0) + w.pts;
        gained += w.pts;
        lines.push(`${styleLabel(c.style)} +${w.pts}`);
      }
    }
    this.aboard = this.aboard.filter((c) => !list.includes(c));
    t.fest = this.host.hours() + CULTURE.festival;
    if (paid > 0) this.host.credit(h.key, paid);
    deeds.add('imports', list.length);
    deeds.best('farFetched', far);
    if (lines.length) this.host.announce(`${h.name} · culture`, `${lines.join(' · ')} · a festival for a day`);
    this.share(h.key);
    // rungs reached for the first time pay in diamonds, once each; where another fleet has a part in the style
    // online, only the rungs this delivery itself reached (one the town already held is theirs as much as anyone's)
    for (const s of this.strands(h.key)) {
      const o = this.others(h.key, s.style), shared = o.pts > 0 || o.seal > 0;
      const prev = Math.max(t.paid[s.style] ?? 0, shared ? before.get(s.style) ?? 0 : 0);
      if (s.rung <= prev) { t.paid[s.style] = Math.max(t.paid[s.style] ?? 0, s.rung); continue; }
      let gems = 0;
      for (let r = prev; r < s.rung; r++) gems += CULTURE.gems[r];
      t.paid[s.style] = s.rung;
      this.host.gems(gems);
      deeds.add('cultured', s.rung - prev);
      if (s.rung > (before.get(s.style) ?? 0)) press.write({ k: 'culture', who: 'you', town: h.key, at: { x: h.x, z: h.z }, f: { town: h.name, style: s.label, rung: RUNG_NAME[s.rung] } });
      if (s.rung > (before.get(s.style) ?? 0)) this.host.announce(`${h.name} · ${rungPhrase(s.rung, s.label)}`, s.rung === 3 ? `The town now builds in ${s.label} style beside its own · ◆ ${gems}` : s.rung === 2 ? `Your fleet may now put up ${s.label} buildings here and in the county · ◆ ${gems}` : `${s.label} culture has taken root · ◆ ${gems}`);
    }
    this.revision++;
    return gained;
  }

  // ---- the world's book (online) ----

  /** The fleet's own running totals in a town, as the world's book takes them. */
  private report(key: string): CultureReport['towns'][string] | null {
    const t = this.towns.get(key);
    if (!t) return null;
    const st: Record<string, [number, number]> = {};
    for (const style of new Set([...Object.keys(t.pts), ...Object.keys(t.seal)]) as Set<CultureStyle>) {
      if (style === t.style) continue;
      const pts = Math.floor(t.pts[style] ?? 0), seal = t.seal[style] ?? 0;
      if (pts > 0 || seal > 0) st[style] = [pts, seal === 3 ? 3 : seal === 2 ? 2 : 0];
    }
    return Object.keys(st).length ? { k: t.kind, s: t.style, n: t.name, st } : null;
  }
  private share(key: string): void { const r = this.report(key); if (r) this.onShare?.(key, r); }
  /** Every town the fleet has written in, for the world's book at sign-in (a save from before keeps its part). */
  shareAll(): Record<string, CultureReport['towns'][string]> {
    const out: Record<string, CultureReport['towns'][string]> = {};
    for (const key of this.towns.keys()) { const r = this.report(key); if (r) out[key] = r; }
    return out;
  }

  /**
   * The world's book, all of it or the towns that changed. A rung another fleet's goods have just reached in one of the
   * player's halls is told: the town is theirs too.
   */
  fromWorld(m: CultureBookMsg): void {
    const keys = m.full ? new Set([...this.world.keys(), ...Object.keys(m.towns ?? {})]) : new Set(Object.keys(m.towns ?? {}));
    const halls = new Map(this.halls().map((h) => [h.key, h]));
    const before = new Map<string, Map<CultureStyle, number>>();
    for (const k of keys) if (halls.has(k)) before.set(k, new Map(this.strands(k).map((s) => [s.style, s.rung])));
    if (m.full) this.world.clear();
    for (const [k, t] of Object.entries(m.towns ?? {})) if (t && typeof t === 'object' && t.st) this.world.set(k, t);
    for (const [k, was] of before) {
      const h = halls.get(k)!;
      for (const s of this.strands(k)) {
        if (s.rung <= (was.get(s.style) ?? 0) || s.rung < 2) continue;
        const by = s.lead ? ` · brought by ${s.lead}` : '';
        this.host.announce(`${h.name} · ${rungPhrase(s.rung, s.label)}`, s.rung === 3 ? `The town now builds in ${s.label} style beside its own${by}` : `${s.label} buildings may now go up here and in the county${by}`);
      }
    }
    this.revision++;
  }

  /** Signed out: the world's book is let go of, and the player's own book is the towns' culture again. */
  leaveWorld(): void {
    if (!this.world.size) return;
    this.world.clear();
    this.revision++;
  }

  // ---- saving ----

  toSave(): SavedCulture {
    return { towns: Object.fromEntries(this.towns), waiting: this.waiting, aboard: this.aboard, next: this.next };
  }

  fromSave(s: SavedCulture | undefined): void {
    this.towns.clear();
    this.lastHalls = '';
    for (const [key, t] of Object.entries(s?.towns ?? {})) {
      if (!t || typeof t !== 'object') continue;
      this.towns.set(key, { pts: { ...t.pts }, got: { ...t.got }, seal: { ...t.seal }, paid: { ...t.paid }, fest: Number(t.fest) || 0, kind: t.kind ?? 'rural', style: t.style ?? 'classic', name: t.name ?? '' });
    }
    // loads saved before they were goods have a good picked for them now
    const crates = (list: Crate[] | undefined) => (Array.isArray(list) ? list.filter((c) => c && typeof c.id === 'number' && typeof c.weight === 'number')
      .map((c) => ({ ...c, good: c.good ?? goodOf(c.style, crateKey(c)) })) : []);
    this.waiting = crates(s?.waiting);
    this.aboard = crates(s?.aboard);
    this.next = Math.max(1, Number(s?.next) || 1, ...this.waiting.map((c) => c.id + 1), ...this.aboard.map((c) => c.id + 1));
    this.revision++;
  }

  // ---- the console (pr.culture) ----

  console() {
    return {
      halls: () => this.halls().map((h) => `${h.name}${h.hq ? ' (your HQ)' : ''} · ${h.key} · ${styleLabel(h.style)} ${h.kind}`),
      strands: (key?: string) => this.strands(key ?? this.hq()?.key ?? ''),
      waiting: () => this.waiting.map((c) => `${c.good.icon} ${c.good.name} · ${styleLabel(c.style)} · ${c.weight}u · ${c.from} (${c.cx},${c.cz})${c.until !== undefined ? ` · gone at ${Math.floor(c.until % 24)}h day ${Math.floor(c.until / 24) + 1}` : ''}`),
      aboard: () => this.aboard.map((c) => `${c.good.icon} ${c.good.name} · ${c.weight}u`),
      room: () => `${this.weight()} of ${this.room()} units of cultural goods · convoy ${this.host.convoy().join('+')}`,
      /** Give a hall's town (the HQ's, or by key) points in a style, as if imported. */
      give: (style: CultureStyle, pts: number, key?: string) => { const h = key ? this.halls().find((q) => q.key === key) ?? null : this.hq(); if (!h) return 'no such hall: pr.culture.halls()'; const t = this.book(h); t.pts[style] = (t.pts[style] ?? 0) + pts; this.share(h.key); this.revision++; return this.strands(h.key); },
      /** Seal a rung without the consignment: 2 Influenced, 3 Infatuated. */
      seal: (style: CultureStyle, level: 2 | 3, key?: string) => { const h = key ? this.halls().find((q) => q.key === key) ?? null : this.hq(); if (!h) return 'no such hall: pr.culture.halls()'; this.book(h).seal[style] = level; this.share(h.key); this.revision++; return this.strands(h.key); },
      /** Put a load out right here. */
      crate: (style: Arch, at: { cx: number; cz: number; x: number; z: number; y: number }, weight = 3) => {
        const key = `console-${this.next}`;
        this.waiting.push({ id: this.next++, type: 'arch', key, style, good: goodOf(style, key), from: 'the console', ...at, weight });
        this.revision++;
      },
    };
  }
}
