/**
 * The interstates' macro layer (docs/interstates.html, the user, 9 Nov 2026; 0.8.0 behind NEXT_080): which
 * routes run through a county, which borders they cross and on which tile, their numbers, names and exits —
 * all from hashes, as the railway's trunks are (world/rail.ts), so two counties that never see each other lay
 * the two halves of one road and meet on the same tile.
 *
 * The network is a grid. East–west route k lives in the band of rows [6k, 6k+5], three rows off the railway's
 * trunk bands, and north–south route k in the band of columns [6k, 6k+5]. Each holds one row (or column) for a
 * run of four counties, the one in its band that suits those counties best: through a megalopolis or a city,
 * inland rather than on a coast, near a nominal line that wanders slowly. Where two runs disagree it steps
 * across through whichever of the two columns is all continent. Only continental counties with land in their
 * middle carry a route: it stops at the coast, and a piece shorter than MIN_RUN counties is never built.
 */
import { N } from './tiles';
import { CONT_THR, cellKind, coastalContinent, contField, crossingAt, hasMega, landable, riverAt, straitAt } from './macro';
import { railAt } from './rail';
import { rosterOf } from './shapes';
import { cell01, cellNoise } from './rng';

/** Rows (columns) of counties between one route's band and the next's. */
export const ROUTE_SPACING = 8;
/** Counties a route holds one row (column) across before it may step. */
const RUN = 6;
/** The fewest counties a piece of route is built for: a shorter piece of continent has none. */
export const MIN_RUN = 5;
/** What a county a route may not cross costs a run: more than every county in the band put together. */
const BLOCKED = 40;
/** Tiles a route's border crossing keeps from any road, rail, river or causeway crossing on the same border. */
const GAP = 18;
/** Tiles two routes' crossings keep from each other on one border. */
const ROUTE_GAP = 48;
/** How far in from a border's ends a crossing may sit, in tiles. */
const END_MARGIN = 44;

const DX = [1, 0, -1, 0], DZ = [0, 1, 0, -1];

/** 0: an east–west route (even numbers), 1: a north–south one (odd numbers). */
export type RouteAxis = 0 | 1;

/** One route's share of a county. `sides` are the borders it crosses, in the order it runs (west to east, north to south). */
export interface InterstateLine {
  key: string;
  axis: RouteAxis;
  k: number;
  sides: number[];
  /** The route's number, I-<number>: even east–west, odd north–south. */
  number: number;
  name: string;
  /** The county where a piece of route ends at the coast or at a break: one side only. */
  terminus: boolean;
}

// ---------------- the cells a route wants ----------------

const cellCostCache = new Map<string, number>();

/** How much a route wants this county, lower being better; BLOCKED where it may not go at all. */
function cellCost(seedHash: number, cx: number, cz: number): number {
  const key = `${seedHash}:${cx},${cz}`;
  const have = cellCostCache.get(key);
  if (have !== undefined) return have;
  let c: number;
  if (!passable(seedHash, cx, cz)) c = BLOCKED;
  else {
    c = coastalContinent(seedHash, cx, cz) ? 1.5 : 0;
    if (hasMega(seedHash, cx, cz)) c -= 3;
    else {
      const towns = rosterOf(seedHash, cx, cz).towns;
      if (towns.includes('metro')) c -= 2;
      else if (towns.includes('city')) c -= 1;
    }
  }
  cellCostCache.set(key, c);
  if (cellCostCache.size > 50000) cellCostCache.delete(cellCostCache.keys().next().value as string);
  return c;
}

/** May a route cross this county: continental, with land in its middle. */
export function passable(seedHash: number, cx: number, cz: number): boolean {
  return cellKind(seedHash, cx, cz) === 'continent' && landable(seedHash, cx, cz);
}

/** The county at `along` (cx for an east–west route, cz for a north–south one) and `across`. */
const cellOf = (axis: RouteAxis, along: number, across: number): [number, number] => (axis === 0 ? [along, across] : [across, along]);

// ---------------- the line through the band ----------------

const rowCache = new Map<string, number>();

/** The row (column) route k of this axis runs on at `along`. */
export function routeRow(seedHash: number, axis: RouteAxis, k: number, along: number): number {
  const off = Math.floor(cell01(seedHash, k, axis, 2401) * RUN);
  const run = Math.floor((along + off) / RUN);
  const key = `${seedHash}:${axis}:${k}:${run}`;
  const have = rowCache.get(key);
  if (have !== undefined) return have;
  const lo = ROUTE_SPACING * k, hi = lo + ROUTE_SPACING - 1;
  const nominal = lo + (ROUTE_SPACING - 1) / 2 + (cellNoise(seedHash, run, k * 17 + axis * 7919, 3, 2400) - 0.5) * 4;
  // never a band's first or last row, so two neighbouring routes keep at least two counties between them
  let best = lo + 1, bestScore = Infinity;
  for (let a = lo + 1; a <= hi - 1; a++) {
    let score = Math.abs(a - nominal) * 1.1;
    for (let j = 0; j < RUN; j++) score += cellCost(seedHash, ...cellOf(axis, run * RUN - off + j, a));
    if (score < bestScore) { bestScore = score; best = a; }
  }
  rowCache.set(key, best);
  if (rowCache.size > 50000) rowCache.delete(rowCache.keys().next().value as string);
  return best;
}

/**
 * What a step leg in column `c` between rows a and b costs: each county on it a route may not cross, and half
 * as much for each where the other way's route runs along that same column, so the two don't run side by side.
 */
function legCost(seedHash: number, axis: RouteAxis, c: number, a: number, b: number): number {
  let n = 0;
  const other = (1 - axis) as RouteAxis;
  for (let r = Math.min(a, b); r <= Math.max(a, b); r++) {
    if (cellCost(seedHash, ...cellOf(axis, c, r)) >= BLOCKED) n++;
    // the other way's route through this county's band runs along `c` at `r` when its row there is c
    if (routeRow(seedHash, other, Math.floor(c / ROUTE_SPACING), r) === c) n += 0.5;
  }
  return n;
}

/** Where route k steps between `c` and `c + 1`: in c or in c + 1, whichever leg is clearer (NaN when it doesn't step). */
function stepColumn(seedHash: number, axis: RouteAxis, k: number, c: number): number {
  const a = routeRow(seedHash, axis, k, c), b = routeRow(seedHash, axis, k, c + 1);
  if (a === b) return NaN;
  return legCost(seedHash, axis, c + 1, a, b) < legCost(seedHash, axis, c, a, b) ? c + 1 : c;
}

/** The rows route k enters column c by (from the low side) and leaves it by (to the high side). */
function through(seedHash: number, axis: RouteAxis, k: number, c: number): [number, number] {
  const here = routeRow(seedHash, axis, k, c);
  const entry = stepColumn(seedHash, axis, k, c - 1) === c ? routeRow(seedHash, axis, k, c - 1) : here;
  const exit = stepColumn(seedHash, axis, k, c) === c ? routeRow(seedHash, axis, k, c + 1) : here;
  return [entry, exit];
}

/** Sides (DIRS) for the low and high ends along, and for stepping down and up across, by axis. */
const LOW = [2, 3], HIGH = [0, 1], ACROSS_DOWN = [3, 2], ACROSS_UP = [1, 0];

/** The borders route k crosses in this county, in its order, before any is cut: null where it doesn't pass. */
function rawSides(seedHash: number, axis: RouteAxis, k: number, cx: number, cz: number): number[] | null {
  const along = axis === 0 ? cx : cz, across = axis === 0 ? cz : cx;
  const [r0, r1] = through(seedHash, axis, k, along);
  if (across < Math.min(r0, r1) || across > Math.max(r0, r1)) return null;
  if (r0 === r1) return [LOW[axis], HIGH[axis]];
  const up = r1 > r0;
  // entering the leg's column at r0 from the low side, leaving at r1 to the high side
  const inSide = up ? ACROSS_DOWN[axis] : ACROSS_UP[axis], outSide = up ? ACROSS_UP[axis] : ACROSS_DOWN[axis];
  if (across === r0) return [LOW[axis], outSide];
  if (across === r1) return [inSide, HIGH[axis]];
  return [inSide, outSide];
}

/** The sides that stay once every one leading off the continent (or onto a county it may not cross) is cut. */
function liveSides(seedHash: number, axis: RouteAxis, k: number, cx: number, cz: number): number[] {
  if (!passable(seedHash, cx, cz)) return [];
  const raw = rawSides(seedHash, axis, k, cx, cz);
  if (!raw) return [];
  return raw.filter((d) => passable(seedHash, cx + DX[d], cz + DZ[d]));
}

/** The band of route k that row (column) `across` lies in. */
const bandOf = (across: number): number => Math.floor(across / ROUTE_SPACING);

/** Counties of the piece this county is on, walked out both ways but no further than `cap` each way. */
function pieceLength(seedHash: number, axis: RouteAxis, k: number, cx: number, cz: number, sides: number[], cap: number): number {
  let n = 1;
  for (const first of sides) {
    let x = cx, z = cz, d = first;
    for (let s = 0; s < cap; s++) {
      const nx = x + DX[d], nz = z + DZ[d], back = (d + 2) % 4;
      const there = liveSides(seedHash, axis, k, nx, nz);
      if (!there.includes(back)) break;
      n++;
      const on = there.find((e) => e !== back);
      if (on === undefined) break;
      x = nx; z = nz; d = on;
    }
  }
  return n;
}

// ---------------- names ----------------

const NAME_A = [
  'Amber', 'Bramble', 'Cinder', 'Copper', 'Crown', 'Drover', 'Ember', 'Fennel', 'Golden', 'Granite', 'Harrow',
  'Heron', 'Juniper', 'Kestrel', 'Lantern', 'Meridian', 'Osprey', 'Prairie', 'Quarry', 'Saffron', 'Silver',
  'Summit', 'Thistle', 'Timber', 'Union', 'Valley', 'Wagon', 'Yarrow',
];
const NAME_B = ['Turnpike', 'Expressway', 'Freeway', 'Parkway', 'Highway', 'Thruway'];

const mod = (a: number, m: number) => ((a % m) + m) % m;

/** The route's number: even across, odd down, two digits. */
export function routeNumber(axis: RouteAxis, k: number): number {
  return 2 * mod(k, 45) + (axis === 0 ? 4 : 5);
}

export function routeName(seedHash: number, axis: RouteAxis, k: number): string {
  const a = Math.floor(cell01(seedHash, k, axis, 2410) * NAME_A.length);
  const b = Math.floor(cell01(seedHash, k, axis, 2411) * NAME_B.length);
  return `${NAME_A[a]} ${NAME_B[b]}`;
}

/** “I-12” */
export const routeLabel = (number: number): string => `I-${number}`;

/**
 * The number of a county's exit `j` (0 or 1) along a route: counted up the way the route runs, two to a
 * county, from an origin hashed per route so neighbouring routes don't share numbers. 1 to 199.
 */
export function exitNumber(seedHash: number, line: Pick<InterstateLine, 'axis' | 'k'>, cx: number, cz: number, j: number): number {
  const along = line.axis === 0 ? cx : cz;
  const base = Math.floor(cell01(seedHash, line.k, line.axis, 2412) * 100);
  return mod((along - base) * 2 + j, 198) + 1;
}

// ---------------- what runs through a county ----------------

const linesCache = new Map<string, InterstateLine[]>();

/** Every route through this county: at most one each way. */
export function interstateLines(seedHash: number, cx: number, cz: number): InterstateLine[] {
  const key = `${seedHash}:${cx},${cz}`;
  const have = linesCache.get(key);
  if (have) return have;
  const out: InterstateLine[] = [];
  for (const axis of [0, 1] as const) {
    const k = bandOf(axis === 0 ? cz : cx);
    const sides = liveSides(seedHash, axis, k, cx, cz);
    if (!sides.length) continue;
    if (pieceLength(seedHash, axis, k, cx, cz, sides, MIN_RUN) < MIN_RUN) continue;
    const number = routeNumber(axis, k);
    out.push({ key: `${axis === 0 ? 'e' : 'n'}${k}`, axis, k, sides, number, name: routeName(seedHash, axis, k), terminus: sides.length === 1 });
  }
  linesCache.set(key, out);
  if (linesCache.size > 20000) linesCache.delete(linesCache.keys().next().value as string);
  return out;
}

/** The two counties either side of side d, named by the lower one, and the border's axis. */
function sharedEdge(cx: number, cz: number, d: number): [number, number, number] {
  return [d === 2 ? cx - 1 : cx, d === 3 ? cz - 1 : cz, d % 2];
}

/**
 * The tiles where routes cross side d of this county, one per route that does, keyed by route: hashed from
 * the shared edge, so both counties get the same tile, and walked out until it keeps GAP from every road
 * crossing, causeway landing, river and railway on that border and ROUTE_GAP from another route's crossing.
 */
export function interstatesAt(seedHash: number, cx: number, cz: number, d: number): { key: string; at: number }[] {
  const here = interstateLines(seedHash, cx, cz).filter((l) => l.sides.includes(d));
  if (!here.length) return [];
  const [ax, az, axis] = sharedEdge(cx, cz, d);
  const taken: number[] = [];
  for (const c of crossingAt(seedHash, cx, cz, d)) taken.push(c.at);
  const s = straitAt(seedHash, cx, cz, d);
  if (s >= 0) taken.push(s);
  const r = riverAt(seedHash, cx, cz, d);
  if (r >= 0) taken.push(r);
  const rl = railAt(seedHash, cx, cz, d);
  if (rl >= 0) taken.push(rl);
  const out: { key: string; at: number }[] = [];
  const keys = here.map((l) => l.key).sort();
  keys.forEach((key) => {
    // where along the border: a slow wander along the route, so the tile it leaves one county by is near the
    // one it enters the next by and the road between runs nearly straight (a hash per border had it zigzag
    // a hundred tiles across every county)
    const line = here.find((l) => l.key === key)!;
    const along = axis === 0 ? ax : az;
    const wander = cellNoise(seedHash, along, line.k * 7 + line.axis * 3 + axis * 101, 3, 2520) - 0.5;
    const base = Math.round(N / 2 + wander * N * 0.55);
    // the first tile out from the hashed one that keeps every distance; failing any, the one that keeps the most
    let at = base, best = -Infinity;
    for (let j = 0; j < N; j++) {
      const c = base + (j % 2 === 0 ? j / 2 : -(j + 1) / 2);
      if (c < END_MARGIN || c > N - 1 - END_MARGIN) continue;
      // on land: the field the coast is drawn from, read along the border a few tiles either side of it
      // (a wet tile only where the whole border is: it scores under every dry one)
      const dry = dryAt(seedHash, axis, ax, az, c);
      const apart = Math.min(ROUTE_GAP, ...out.map((o) => Math.abs(o.at - c)));
      // two routes side by side is worst of all, then the sea, then crowding the border's other crossings
      const near = Math.min(GAP, ...taken.map((t) => Math.abs(t - c))) / GAP + apart / ROUTE_GAP - (dry ? 0 : 3) - (apart < 40 ? 6 : 0);
      if (near > best + 1e-9) { best = near; at = c; }
      if (near >= 2) break;
    }
    out.push({ key, at });
  });
  return out;
}

/**
 * Is the border between (ax, az) and the county past it (along x for axis 0) dry land at tile `at` and a few tiles
 * either side? The macro field draws every continental coast (world/generate.ts), so a crossing read off it never
 * lands in a bay.
 */
function dryAt(seedHash: number, axis: number, ax: number, az: number, at: number): boolean {
  for (let u = -10; u <= 10; u += 2) {
    const f = (at + u + 0.5) / N;
    // on the border, and a dozen tiles in on either side, where the stubs run
    for (const inward of [-12, -6, 0, 6, 12]) {
      const g = inward / N;
      const v = axis === 0 ? contField(seedHash, ax + 1 + g, az + f) : contField(seedHash, ax + f, az + 1 + g);
      if (v < CONT_THR + 0.06) return false;
    }
  }
  return true;
}

/** The tile route `key` crosses side d of this county on, or -1. */
export function interstateAt(seedHash: number, cx: number, cz: number, d: number, key: string): number {
  return interstatesAt(seedHash, cx, cz, d).find((c) => c.key === key)?.at ?? -1;
}

/** Every route through the counties in a box, for the console and the maps. */
export function interstatesAround(seedHash: number, cx: number, cz: number, r = 1): { cell: [number, number]; key: string; number: number; sides: number[]; at: number[]; terminus: boolean }[] {
  const out: { cell: [number, number]; key: string; number: number; sides: number[]; at: number[]; terminus: boolean }[] = [];
  for (let z = cz - r; z <= cz + r; z++) {
    for (let x = cx - r; x <= cx + r; x++) {
      for (const l of interstateLines(seedHash, x, z)) {
        out.push({ cell: [x, z], key: l.key, number: l.number, sides: l.sides, at: l.sides.map((s) => interstateAt(seedHash, x, z, s, l.key)), terminus: l.terminus });
      }
    }
  }
  return out;
}
