import type { BuildingKind } from '../../../world/tiles';
import { hex, scale } from '../../../world/biomes';
import {
  BRIGHT, COOL_GLOW, DARK, METAL, RED_LIGHT, ROOF_GREY, SHOP_GLOW, WARM_GLOW, WHITE, WOOD,
  pick, row, win, type Draw,
} from '../kit';

/**
 * Alternatives for the harbour and roadside kinds: piers, fish shacks, cranes, container stacks,
 * boathouses, customs posts and crate piles. They are drawn with no town (the classic style), so what
 * sets them apart is their job and silhouette, not a town's colours.
 */

const SAFETY = hex(0xf2c14e);
const CONTAINER = [0xe2412f, 0x2bb3a3, 0xf2c14e, 0x4a6fa5, 0xf28c38, 0x8e5cc7, 0x6f9e6b, 0xb9bdc2];
const TARP = [0x3f7a5a, 0x2f5d8a, 0x8a3a32, 0x6b6f4a];

/**
 * A stone jetty on a thin pier (kerbed both sides, iron bollards, a lantern on a plinth at the sea
 * end), or on a wide one a timber-fendered wharf with mushroom bollards, a white edge line and tall
 * twin-headed floodlight masts, where the original has yellow lines and short lamps.
 */
const stoneJetty: Draw = (k, W, D, _b, r) => {
  if (W < 2) {
    const stone = hex(0xb9b1a0), edge = W / 2 - 0.06;
    for (const sx of [-1, 1]) k.box(sx * edge, 0, 0, 0.08, 0.05, D - 0.04, stone, hex(0xd2cbbb));
    let i = 0;
    for (let z = -D / 2 + 0.55; z < D / 2 - 0.45; z += 1.1, i++) {
      const x = (i % 2 ? -1 : 1) * (edge - 0.1);
      k.cyl(x, 0, z, 0.04, 0.08, DARK, 6);
      k.cyl(x, 0.08, z, 0.055, 0.025, DARK, 6);
    }
    // the lantern at the end, on its plinth
    const lz = D / 2 - 0.18;
    k.box(0, 0, lz, 0.18, 0.08, 0.18, stone);
    k.cyl(0, 0.08, lz, 0.018, 0.5, DARK, 5);
    k.glowBox(0, 0.58, lz, 0.09, 0.1, 0.09, hex(0xfff2b0), [17.4, 30, 2.2], WARM_GLOW);
    k.hip(0, 0.68, lz, 0.13, 0.06, 0.13, DARK);
    // a life ring on its post by the landing
    const lr = r() < 0.5 ? -1 : 1;
    k.box(lr * (edge - 0.12), 0, -D / 2 + 0.3, 0.02, 0.24, 0.02, WOOD);
    k.box(lr * (edge - 0.12), 0.1, -D / 2 + 0.315, 0.11, 0.11, 0.015, hex(0xe2412f));
    return;
  }
  const timber = hex(0x5a4632), rubber = hex(0x2a2c2f), edge = W / 2 - 0.03;
  for (const sx of [-1, 1]) {
    k.box(sx * edge, 0, 0, 0.06, 0.04, D - 0.02, timber);
    k.box(sx * (W / 2 - 0.2), 0.003, 0, 0.035, 0.01, D - 0.2, WHITE);
    // fender pads hung down the face, and a bollard between each pair
    for (let z = -D / 2 + 0.5; z < D / 2; z += 1.5) {
      k.box(sx * (W / 2 + 0.01), -0.14, z, 0.03, 0.16, 0.22, rubber);
      const bz = z + 0.75;
      if (bz < D / 2 - 0.2) {
        k.cyl(sx * (W / 2 - 0.1), 0, bz, 0.035, 0.08, DARK, 5);
        k.cyl(sx * (W / 2 - 0.1), 0.08, bz, 0.055, 0.02, DARK, 5);
      }
    }
    // a floodlight mast halfway down each side, two heads on its crossbar
    const mz = D >= 3 ? sx * 0.4 : 0, mx = sx * (W / 2 - 0.26), mh = D >= 3 ? 0.95 : 0.6;
    k.box(mx, 0, mz, 0.035, mh, 0.035, METAL);
    k.box(mx, mh, mz, 0.04, 0.03, 0.34, METAL);
    for (const dz of [-0.14, 0.14]) k.glowBox(mx, mh - 0.06, mz + dz, 0.08, 0.05, 0.08, hex(0xfff2b0), [17.4, 30, 2.2], COOL_GLOW);
  }
};

/**
 * A slewing level-luffing crane on a portal: short legs astride the rails, a turret with its
 * machinery house and counterweight, a raking mast, and a raised jib slewed out over one berth with its
 * hook down, against the original's tall gantry and long flat boom.
 */
const portalCrane: Draw = (k, W, _D, _b, r) => {
  const hw = W / 2 - 0.12, body = pick(r, [0xe2412f, 0x2f7fb5, 0xf28c38, 0x3f9b4a]), ph = 0.85;
  for (const sx of [-hw, hw]) for (const sz of [-0.3, 0.3]) k.box(sx, 0, sz, 0.08, ph, 0.08, body);
  for (const sz of [-0.3, 0.3]) k.box(0, ph, sz, 2 * hw + 0.08, 0.1, 0.08, body);
  const yaw = (r() < 0.5 ? 0 : Math.PI) + (r() - 0.5) * 0.6, y0 = ph + 0.1;
  k.turned(yaw, () => {
    k.box(-0.05, y0, 0, 0.56, 0.34, 0.42, WHITE, ROOF_GREY);
    k.box(0.3, y0 + 0.12, 0.14, 0.16, 0.16, 0.14, hex(0x9cc6d9), WHITE);
    k.bar([-0.12, y0 + 0.34, 0], [0.02, y0 + 1.08, 0], 0.035, body);
    // the jib from its foot to the tip, the tie from the mast, the balance arm and its weight
    k.bar([0.18, y0 + 0.42, 0], [2.6, y0 + 1.14, 0], 0.035, body);
    k.bar([0.02, y0 + 1.08, 0], [2.6, y0 + 1.14, 0], 0.012, DARK);
    k.bar([0.02, y0 + 1.08, 0], [-0.62, y0 + 0.86, 0], 0.025, body);
    k.box(-0.66, y0 + 0.66, 0, 0.22, 0.22, 0.22, DARK);
    k.box(2.6, y0 + 0.36, 0, 0.012, 0.78, 0.012, DARK);
    k.box(2.6, y0 + 0.28, 0, 0.09, 0.08, 0.09, SAFETY);
    k.glowBox(2.62, y0 + 1.18, 0, 0.06, 0.06, 0.06, hex(0x882222), [16.5, 30, 2.8], RED_LIGHT);
  });
};

/**
 * Forty-foot boxes in long rows, mostly in one shipping line's colour, and on a wide lot a straddle
 * carrier standing over its row with a box slung under it; the original stacks short boxes in every
 * colour.
 */
const containerRows: Draw = (k, W, D, _b, r) => {
  const line = pick(r, CONTAINER), alongZ = W === D ? r() < 0.5 : D > W;
  const L = alongZ ? D : W, S = alongZ ? W : D;
  const nl = Math.max(1, Math.floor((L - 0.1) / 1.44)), len = (L - 0.1) / nl - 0.05;
  const ns = Math.max(1, Math.floor((S - 0.1) / 0.44)), s0 = -(ns * 0.44) / 2 + 0.22;
  const at = (s: number, l: number, y: number, w: number, h: number, d: number, col: ReturnType<typeof hex>) =>
    alongZ ? k.box(s, y, l, w, h, d, col) : k.box(l, y, s, d, h, w, col);
  const carrier = ns >= 4 ? 1 + Math.floor(r() * (ns - 2)) : -1, cl = nl > 1 ? 1 : 0;
  for (let is = 0; is < ns; is++) {
    for (let il = 0; il < nl; il++) {
      const s = s0 + is * 0.44, l = -L / 2 + 0.05 + (il + 0.5) * (len + 0.05);
      if (is === carrier && il === cl) {
        // the straddle carrier: four legs, two top rails, its cab and beacon, a box hanging between
        for (const ds of [-0.25, 0.25]) {
          for (const dl of [-len / 2 + 0.06, len / 2 - 0.06]) at(s + ds, l + dl, 0, 0.05, 0.74, 0.05, WHITE);
          at(s + ds, l, 0.74, 0.05, 0.06, len - 0.04, SAFETY);
        }
        at(s, l + len / 2 - 0.15, 0.8, 0.3, 0.14, 0.2, DARK);
        at(s, l, 0.2, 0.38, 0.26, len - 0.2, pick(r, CONTAINER));
        const [bx, bz] = alongZ ? [s, l - len / 2 + 0.12] : [l - len / 2 + 0.12, s];
        k.glowBox(bx, 0.8, bz, 0.05, 0.05, 0.05, hex(0xf2a93b), [0, 24, 2.5], hex(0xffb030));
        continue;
      }
      const h = 1 + Math.floor(r() * 3);
      for (let lvl = 0; lvl < h; lvl++) at(s, l, lvl * 0.27, 0.4, 0.26, len, r() < 0.65 ? line : pick(r, CONTAINER));
    }
  }
};

/**
 * A rowing club: the boat hall below with its wide door onto the slip, and a clubroom set back on
 * top behind a terrace, its ridge running across the front, where the original is one tall shed
 * gable-end on to the water.
 */
const rowingClub: Draw = (k, W, D, b, r) => {
  const wood = pick(r, [0x8a5a3a, 0x6f8a9a, 0xa0523d, 0x5f7a5a]), upper = pick(r, [0xf4f2ec, 0xe8d3b0, 0xcfe0e8]);
  const bw = W - 0.3, bd = D - 0.5, bz = -0.1, front = bz + bd / 2;
  k.box(0, 0, bz, bw, 0.44, bd, wood, hex(0x9a9690));
  const ud = bd * 0.7, uz = bz - (bd - ud) / 2;
  k.box(0, 0.44, uz, bw, 0.28, ud, upper);
  k.gable(0, 0.72, uz, bw + 0.08, 0.26, ud + 0.1, hex(0x4a4f55), upper);
  row(k, b, r, 0, 0.52, uz + ud / 2, bw * 0.6, 0.12, 2, 1);
  k.box(0, 0, front + 0.01, bw * 0.7, 0.36, 0.02, scale(wood, 0.6));
  k.glowBox(0, 0.39, front + 0.04, 0.06, 0.04, 0.05, hex(0xc9b27a), [18 + r(), 23 + r(), 1.8], WARM_GLOW);
  k.box(0, 0.002, D / 2 - 0.18, bw * 0.7, 0.01, 0.36, hex(0x8a6a48));
};

/**
 * A bait shop: a shed-roofed hut rising to its lit sign at the front, a lean-to down one side and
 * nets hung on the other wall; the original is a little gabled hut. It spreads out on a big lot.
 */
const baitShop: Draw = (k, W, D, b, r) => {
  const f = Math.min(W, D) >= 2 ? 1.6 : 1, hf = 1 + (f - 1) * 0.4;
  const wood = pick(r, [0x8a5a3a, 0x6f8a9a, 0xc9b27a, 0x7a8a6a]), roof = hex(0x4a5560);
  const mx = -0.08 * f, mz = -0.06 * f, mw = 0.48 * f, md = 0.56 * f, mh = 0.32 * hf;
  k.box(mx, 0, mz, mw, mh, md, wood);
  k.wedge(mx, mh, mz, mw + 0.06, 0.12 * hf, md + 0.06, roof);
  // the lean-to down the right, its roof falling away from the hut
  const lw = 0.26 * f, lx = mx + mw / 2 + lw / 2;
  k.box(lx, 0, mz, lw, 0.24 * hf, md * 0.9, scale(wood, 0.85));
  k.turned(-Math.PI / 2, () => k.wedge(mz, 0.24 * hf, -lx, md * 0.9 + 0.04, 0.07 * hf, lw + 0.04, roof));
  const fz = mz + md / 2;
  k.box(mx - mw * 0.22, 0, fz + 0.01, 0.12 * f, 0.22 * hf, 0.02, scale(wood, 0.6));
  win(k, b, r, mx + mw * 0.18, 0.1 * hf, fz, 0.16 * f, 0.12 * hf, 1);
  const sign = pick(r, BRIGHT);
  k.glowBox(mx, mh + 0.02, fz + 0.04, mw * 0.8, 0.08, 0.04, sign, [17, 22, 1.6], sign);
  // nets drying on the left wall
  k.box(mx - mw / 2 - 0.01, 0.06, mz, 0.02, 0.22 * hf, md * 0.7, hex(0x5a6a62));
};

/**
 * A timber stack and a tarped pallet: sawn planks piled in courses, a load of sacks under a
 * roped-down tarpaulin and a drum, low and long where the original is a heap of cubes.
 */
const timberStack: Draw = (k, W, D, _b, r) => {
  const f = Math.min(W, D) >= 2 ? 1.6 : 1;
  const plank = [hex(0xc9a06a), hex(0xb08658), hex(0xd4b07a)];
  for (let c = 0; c < 3; c++) {
    const w = (c === 2 ? 0.44 : 0.64) * f;
    k.box(0.04 * f + (c === 2 ? 0.08 * f : 0), c * 0.088, 0.2 * f, w, 0.082, 0.26 * f, plank[c]);
  }
  const tarp = pick(r, TARP), px = -0.14 * f, pz = -0.16 * f;
  k.box(px, 0, pz, 0.42 * f, 0.05, 0.36 * f, scale(WOOD, 0.8));
  k.box(px, 0.05, pz, 0.38 * f, 0.3, 0.32 * f, tarp);
  k.hip(px, 0.35, pz, 0.38 * f, 0.06, 0.32 * f, scale(tarp, 1.1));
  k.cyl(0.26 * f, 0, -0.18 * f, 0.1, 0.3, hex(r() < 0.5 ? 0x4a6fa5 : 0x3f7a5a), 6);
};

/**
 * A customs gateway: the two booths under little hipped roofs, a gantry across the lane behind them
 * carrying the lit sign and the lane lights, the barrier arms raised, and a row of three flags; the
 * original has one flat canopy over everything and its barrier down.
 */
const customsGate: Draw = (k, W, D, b, r) => {
  const trim = hex(0x2f5d8a), lane = Math.min(W * 0.5, 1.2);
  for (const sx of [-1, 1]) {
    const x = sx * (lane / 2 + 0.3);
    k.box(x, 0, 0, 0.42, 0.48, 0.5, WHITE, trim);
    k.hip(x, 0.48, 0, 0.52, 0.16, 0.6, trim);
    k.glowBox(x - sx * 0.22, 0.2, 0, 0.02, 0.18, 0.34, hex(0xdfe8ee), [0, 24, 2.2], SHOP_GLOW);
    win(k, b, r, x, 0.2, 0.26, 0.24, 0.16, 1);
    // the gantry post behind the booth, its lane light, and the barrier arm raised beside it
    const gx = sx * (lane / 2 + 0.3), gz = -0.34;
    k.box(gx, 0, gz, 0.06, 0.96, 0.06, METAL);
    k.glowBox(gx - sx * 0.1, 0.72, gz + 0.04, 0.06, 0.06, 0.03, hex(0x3cc05a), [0, 24, 2.4], hex(0x3cff6a));
    const px = sx * (lane / 2 + 0.04), pz = 0.4;
    k.box(px, 0, pz, 0.08, 0.3, 0.08, hex(0xe2412f));
    k.bar([px, 0.27, pz], [px - sx * 0.2, 0.9, pz], 0.018, WHITE);
  }
  k.box(0, 0.96, -0.34, lane + 0.72, 0.1, 0.06, trim);
  k.glowBox(0, 0.86, -0.3, 0.9, 0.16, 0.02, hex(0xe8f0f4), [0, 24, 1.6], SHOP_GLOW);
  k.box(0, 0.002, D / 2 - 0.3, lane, 0.01, 0.12, SAFETY);
  // three flags on their poles at the back corner
  for (let i = 0; i < 3; i++) {
    const fx = -W / 2 + 0.2 + i * 0.2, fz = -D / 2 + 0.25;
    k.box(fx, 0, fz, 0.03, 0.82, 0.03, WHITE);
    k.box(fx + 0.08, 0.66, fz, 0.15, 0.1, 0.01, pick(r, [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2c14e]));
  }
};

export const HARBOUR_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  pier: [stoneJetty],
  shack: [baitShop],
  crane: [portalCrane],
  containers: [containerRows],
  boathouse: [rowingClub],
  customsPost: [customsGate],
  crates: [timberStack],
};
