import * as THREE from 'three';
import { N, STEP, type World } from '../../world/tiles';
import { buildingHeight } from '../../world/towns';
import { roofTopAt } from '../../render/roofTop';
import { VEHICLES, halfSize, type WaterDef } from '../vehicles';
import { waterRoute } from '../traffic';
import { DAYS_PER_YEAR } from '../../render/season';
import { KIND_OF } from './kinds';
import type { Happening } from './calendar';
import { mid, type Place, type Pt } from './venues';
import { Bulbs, Crowd, Rig, Way, beam, block, dressed, flat, waterY } from './props';
import { Closure, HOUR_S, Show, clamp01, lineStreet, toWorld, u01, type ShowCtx } from './shows';

/**
 * The showpieces of phase 2 (docs/events.html): the water, the air, the military and the light. As in phase 1,
 * each is worked out from the world clock every frame, so whoever comes by sees the same race leg, the same pass
 * of the display team, the same ship at its berth.
 */

const PRIDE = [0xe40303, 0xff8c00, 0xffed00, 0x008026, 0x24408e, 0x732982];
/** National colours a region may fly (a capital's flyover smoke and its soldiers' flags), chosen by the event's hash. */
const NATIONS: number[][] = [
  [0xd52b1e, 0xffffff, 0x1f4e9e], [0x009246, 0xffffff, 0xce2b37], [0x111111, 0xdd0000, 0xffce00], [0x0057b7, 0xffd700, 0x0057b7],
  [0xff9933, 0xffffff, 0x138808], [0xc8102e, 0xffffff, 0xc8102e], [0x002395, 0xffffff, 0xed2939], [0x006aa7, 0xfecc00, 0x006aa7],
];
const OLIVE = [0x4b5320, 0x556b2f, 0x3e4a22, 0x5a6332];

/** The season of a game hour: 0 spring … 3 winter. */
const seasonOf = (h: number) => ((Math.floor(h / 24) % DAYS_PER_YEAR) + DAYS_PER_YEAR) % DAYS_PER_YEAR;
/** The hour of the day. */
const hourOf = (h: number) => ((h % 24) + 24) % 24;

// ---- little models ---------------------------------------------------------------------------------------------------

/** A racing dinghy: a white hull, a mast and a sail in its colour that swings out with the wind. */
class Dinghy {
  readonly root = new THREE.Group();
  private sail = new THREE.Group();
  constructor(parent: THREE.Object3D, colour: number) {
    const hull = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.06, 0.42), flat(0xf8f6ee));
    hull.position.y = 0.03;
    hull.castShadow = true;
    const bow = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.12, 4), flat(0xf8f6ee));
    bow.rotation.set(Math.PI / 2, Math.PI / 4, 0);
    bow.position.set(0, 0.03, 0.27);
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.007, 0.009, 0.52, 5), flat(0xc9ccd1));
    mast.position.set(0, 0.32, 0.06);
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([0, 0.08, 0, 0, 0.56, 0, 0, 0.08, -0.3], 3));
    g.computeVertexNormals();
    const sail = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ color: colour, side: THREE.DoubleSide, roughness: 0.7, flatShading: true }));
    sail.castShadow = true;
    this.sail.position.set(0, 0, 0.06);
    this.sail.add(sail);
    this.root.add(hull, bow, mast, this.sail);
    parent.add(this.root);
  }
  place(x: number, y: number, z: number, heading: number, sail: number, heel: number): void {
    this.root.position.set(x, y, z);
    this.root.rotation.set(0, heading, heel, 'YXZ');
    this.sail.rotation.y = sail;
  }
  set visible(v: boolean) { this.root.visible = v; }
}

/** A racing mark: an orange buoy riding the water. */
function buoy(parent: THREE.Object3D, x: number, y: number, z: number, colour = 0xff6a13): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.1, 0.24, 8), flat(colour, 0.25));
  m.position.set(x, y + 0.08, z);
  parent.add(m);
  return m;
}

// ---- the regatta ---------------------------------------------------------------------------------------------------

/**
 * A regatta in a bay: a dozen dinghies mill about behind the line between the committee boat and the start mark,
 * then race two laps of a triangle of orange buoys, tacking up the windward leg, and the townsfolk watch from the
 * shore.
 */
export class RegattaShow extends Show {
  private boats: { d: Dinghy; pace: number; side: number }[] = [];
  private committee: Rig;
  private crowd: Crowd;
  private legs: Way;
  private lap: number;
  private marks: Pt[];
  private start: Pt;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    this.marks = place.course!.map((p) => toWorld(w, p));
    // two laps: the line, windward, wing, back to the line; again; finish at the line
    const tour = [this.marks[0], this.marks[1], this.marks[2], this.marks[0]];
    this.legs = new Way([...tour, ...tour.slice(1)]);
    this.lap = this.legs.length;
    this.start = this.marks[0];
    const colours = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0x3a3f45, 0xffffff, 0xc9463d, 0x6fb8e0];
    const n = 8 + Math.floor(u01(e.h, 1) * 5);
    for (let i = 0; i < n; i++) this.boats.push({ d: new Dinghy(this.g, colours[i % colours.length]), pace: 0.88 + u01(e.h, 10 + i) * 0.2, side: (i % 2 ? 1 : -1) * (0.3 + u01(e.h, 30 + i) * 0.5) });
    for (const m of this.marks) buoy(this.g, m.x, waterY(ctx, m.x, m.z), m.z);
    const cb = toWorld(w, place.committee!);
    this.committee = new Rig(this.g, dressed('yacht'));
    this.committee.float(ctx.worldAt, cb.x, cb.z, Math.atan2(this.marks[1].x - cb.x, this.marks[1].z - cb.z) + Math.PI / 2, 0, 0);
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { const r = this.place.water!; return { x: this.w.ox + (r.x0 + r.x1) / 2, z: this.w.oz + (r.z0 + r.z1) / 2 }; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.regatta;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const race = (now - e.start) / (spec.dur * 0.8);
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.cheer = race > 0.95 && race < 1.3 ? 0.8 : 0;
    this.crowd.update(dt);
    this.committee.float(this.ctx.worldAt, this.committee.state.x, this.committee.state.z, this.committee.state.heading, 0, dt);
    const total = this.lap * 2;
    // the wind blows down the first leg: the windward one is beaten up in tacks, the others reached and run
    const wind = Math.atan2(this.marks[0].x - this.marks[1].x, this.marks[0].z - this.marks[1].z);
    const t = performance.now() / 1000;
    this.boats.forEach((b, i) => {
      let x: number, z: number, heading: number, sail: number;
      if (race < 0) {
        // before the gun: circling behind the line
        const a = t * 0.35 + (i / this.boats.length) * Math.PI * 2;
        const back = { x: this.start.x + Math.sin(wind) * 2.2, z: this.start.z + Math.cos(wind) * 2.2 };
        x = back.x + Math.cos(a) * 1.6; z = back.z + Math.sin(a) * 1.6;
        heading = Math.atan2(-Math.sin(a), Math.cos(a));
        sail = 0.5;
      } else {
        const s = Math.min(total, race * total * b.pace);
        const p = this.legs.at(s);
        // which leg: the windward legs zigzag in tacks either side of the line
        const legLen = this.legs.L[1];
        const inLap = s % this.lap;
        const upwind = inLap < legLen && s < total;
        const tack = upwind ? Math.sin((inLap / 3.2) * Math.PI) : 0;
        const nx = Math.cos(p.heading), nz = -Math.sin(p.heading);
        const off = b.side * 0.4 + tack * 1.2 * Math.min(1, inLap / 2, (legLen - inLap) / 2);
        x = p.x + nx * off; z = p.z + nz * off;
        heading = p.heading + (upwind ? Math.cos((inLap / 3.2) * Math.PI) * 0.6 : 0);
        sail = Math.max(-1.1, Math.min(1.1, (wind - heading + Math.PI * 3) % (Math.PI * 2) - Math.PI)) * 0.6;
        if (s >= total) { x += Math.sin(wind) * (1 + i * 0.2); z += Math.cos(wind) * (1 + i * 0.2); sail = 0; }
      }
      const y = waterY(this.ctx, x, z);
      b.d.place(x, y, z, heading, sail, Math.sin(t * 1.4 + i) * 0.05 - sail * 0.12);
    });
  }

  dispose(): void { this.committee.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- the boat parade ---------------------------------------------------------------------------------------------------

const PARADE_BOATS = ['yacht', 'riverboat', 'breeze', 'splash', 'defender', 'galleon', 'rowboat', 'yacht', 'breeze', 'riverboat', 'splash', 'defender', 'yacht', 'galleon'];

/**
 * Boats of every kind in single file along a town's waterfront at dusk, strung with lights from bow to masthead,
 * two fireboats ahead throwing arcs of spray. In winter the lights are every colour and it ends in fireworks.
 */
export class BoatParadeShow extends Show {
  private way: Way;
  private boats: { rig: Rig; off: number; mast: number; half: number }[] = [];
  private fire: { rig: Rig; off: number }[] = [];
  private bulbs: Bulbs;
  private crowd: Crowd;
  private winter: boolean;
  private bangs = 0;

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    this.way = new Way(place.path!.map((p) => toWorld(w, p)));
    this.winter = seasonOf(e.start) === 3;
    let off = 0;
    for (const side of [0, 1]) { this.fire.push({ rig: new Rig(this.g, dressed('breeze', 0xc8102e)), off: off + side * 0.2 }); }
    off = 2.2;
    const n = 10 + Math.floor(u01(e.h, 2) * 5);
    for (let i = 0; i < n; i++) {
      const id = PARADE_BOATS[(i + Math.floor(u01(e.h, 3) * 5)) % PARADE_BOATS.length];
      const def = dressed(id);
      // nose to tail, a boat's length and a bit apart
      const half = halfSize(def)[0];
      off += half;
      this.boats.push({ rig: new Rig(this.g, def), off, mast: (def as WaterDef).sail ? 0.9 : 0.35, half });
      off += half + 0.8;
    }
    this.bulbs = new Bulbs(this.g, 6 * n, this.winter ? [0xff3b3b, 0x3dff8a, 0x5ad1ff, 0xffd166, 0xff6ad5] : [0xfff2c4, 0xffe39a]);
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { return this.way.at(this.way.length / 2); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.boatParade;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const run = (now - e.start) / (spec.dur * 0.85);
    const L = this.way.length, last = this.boats[this.boats.length - 1].off;
    // the line comes in from one end of the front and files out at the other
    const lead = -0.5 + clamp01(run) * (L + last + 1);
    const v = run > 0 && run < 1 ? (L + last) / (spec.dur * 0.85 * HOUR_S) : 0;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.2)) / 0.2));
    this.crowd.cheer = run > 0 && run < 1 ? 0.5 : 0;
    this.crowd.update(dt);
    const lit = Math.max(0.4, this.ctx.night());
    this.bulbs.begin();
    const place = (rig: Rig, s: number, mast: number, half = 0.5) => {
      if (s < 0 || s > L) { rig.hide(); return null; }
      const p = this.way.at(s);
      rig.float(this.ctx.worldAt, p.x, p.z, p.heading, v, dt, 0.3);
      if (lit > 0 && mast) {
        // a string from the bow up to the masthead and down to the stern
        const fx = Math.sin(p.heading), fz = Math.cos(p.heading), y = rig.state.y;
        for (let k = 0; k < 6; k++) {
          const u = k / 5, along = (0.5 - u) * half * 1.8, up = 0.12 + mast * (1 - Math.abs(u - 0.5) * 2);
          this.bulbs.at(p.x + fx * along, y + up, p.z + fz * along);
        }
      }
      return p;
    };
    for (const b of this.boats) place(b.rig, lead - b.off, b.mast, b.half);
    for (const f of this.fire) {
      const p = place(f.rig, lead - f.off + 1.5, 0);
      if (p && run > 0 && run < 1 && Math.random() < dt * 30) {
        // the fireboats' arcs of spray, crossed over the line
        const side = f === this.fire[0] ? 1 : -1, nx = Math.cos(p.heading) * side, nz = -Math.sin(p.heading) * side;
        this.ctx.particles.spark({ x: p.x, y: f.rig.state.y + 0.3, z: p.z, vx: nx * 1.1 + Math.sin(p.heading) * 0.4, vy: 2.6, vz: nz * 1.1 + Math.cos(p.heading) * 0.4, life: 1.3, colour: 0x9fc8e8, size: 0.07, gravity: 3.4, drag: 0.3 });
      }
    }
    this.bulbs.end();
    // a winter parade ends in fireworks over the water
    if (this.winter && run > 0.85 && run < 1.1 && this.bangs < 24 && Math.random() < dt * 2.5) {
      this.bangs++;
      const p = this.way.at(Math.random() * L);
      this.ctx.particles.burst(p.x, waterY(this.ctx, p.x, p.z) + 4 + Math.random() * 3, p.z, [[0xff3b3b, 0xffd166], [0x5ad1ff, 0xffffff], [0x3dff8a, 0xff6ad5]][this.bangs % 3], 90, 3.6);
    }
  }

  dispose(): void { for (const b of [...this.boats, ...this.fire]) b.rig.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- flyovers ---------------------------------------------------------------------------------------------------

/**
 * Aircraft in formation across the sky on a timed line: each at an offset (across, back) from the leader, which
 * crosses `over` at `at` (game hours) heading `heading`, at `speed` tiles a second, trailing smoke if it has colours.
 */
class Formation {
  private rigs: Rig[] = [];
  constructor(parent: THREE.Object3D, id: string, private slots: [number, number][], private smoke: number[] | null, colour?: number) {
    for (let i = 0; i < slots.length; i++) this.rigs.push(new Rig(parent, dressed(id, colour)));
    for (const r of this.rigs) r.hide();
  }
  update(ctx: ShowCtx, now: number, at: number, over: Pt, heading: number, speed: number, alt: number, dt: number): boolean {
    const along = (now - at) * HOUR_S * speed;
    if (Math.abs(along) > 90) { for (const r of this.rigs) r.hide(); return false; }
    const fx = Math.sin(heading), fz = Math.cos(heading), sx = Math.cos(heading), sz = -Math.sin(heading);
    const y = ctx.ground(over.x, over.z) + alt;
    this.rigs.forEach((r, i) => {
      const [across, back] = this.slots[i];
      const x = over.x + fx * (along - back) + sx * across, z = over.z + fz * (along - back) + sz * across;
      r.fly(x, y, z, heading, 0, 0, dt);
      if (this.smoke && Math.random() < dt * 40) {
        ctx.particles.puff({ x: x - fx * 0.7, y: y - 0.1, z: z - fz * 0.7, vx: 0, vy: -0.05, vz: 0, life: 4.5, colour: this.smoke[i % this.smoke.length], size: 0.35, drag: 1 });
      }
    });
    return true;
  }
  dispose(): void { for (const r of this.rigs) r.dispose(); }
}

/** A marching column: ranks of four a step apart, kept on a way by hand. */
function march(crowd: Crowd, way: Way, s: number, rankGap: number, dt: number): void {
  for (let k = 0; k < crowd.size; k++) {
    const row = Math.floor(k / 4), col = k % 4;
    const p = way.at(s - row * rankGap);
    const side = (col - 1.5) * 0.12, nx = Math.cos(p.heading), nz = -Math.sin(p.heading);
    crowd.setAt(k, p.x + nx * side, p.z + nz * side, dt);
  }
}

// ---- the military parade ---------------------------------------------------------------------------------------------------

/**
 * A capital's national day: ranks of soldiers marching down a closed avenue, Tortoise tanks, Badgers and trucks
 * behind them, crowds on the kerbs; then a V of five Stingers low overhead trailing the nation's colours, and the
 * Bumblebees after them.
 */
export class MilitaryParadeShow extends Show {
  private way: Way;
  private soldiers: Crowd;
  private crowd: Crowd;
  private rigs: { rig: Rig; off: number }[] = [];
  private jets: Formation;
  private helis: Formation;
  private closure: Closure;
  private colours: number[];
  private head: number;
  private soldierLen: number;

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    const P = place.path!;
    this.way = new Way(P.map((p) => toWorld(w, p)));
    this.colours = NATIONS[e.h % NATIONS.length];
    this.soldiers = new Crowd(this.g, ctx.ground, 0, OLIVE);
    this.soldiers.manual = true;
    for (let i = 0; i < 40; i++) this.soldiers.add(this.way.pts[0].x, this.way.pts[0].z);
    this.soldiers.roam = null;
    this.soldierLen = 10 * 0.17;
    let off = this.soldierLen + 0.8;
    for (const id of ['tank', 'tank', 'humvee', 'humvee', 'deuce', 'deuce']) {
      const def = dressed(id);
      const half = (def as { halfLen?: number }).halfLen ?? 0.6;
      off += half;
      this.rigs.push({ rig: new Rig(this.g, def), off });
      off += half + 0.6;
    }
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    lineStreet(this.crowd, w, P, e.h, 52);
    this.closure = new Closure(w, P.map((p) => Math.floor(p.x) + Math.floor(p.z) * N));
    const a = this.way.pts[0], b = this.way.pts[this.way.pts.length - 1];
    this.head = Math.atan2(b.x - a.x, b.z - a.z);
    this.jets = new Formation(this.g, 'fighter', [[0, 0], [1.3, 1.3], [-1.3, 1.3], [2.6, 2.6], [-2.6, 2.6]], [this.colours[0], this.colours[1], this.colours[1], this.colours[2], this.colours[2]]);
    this.helis = new Formation(this.g, 'chinook', [[0, 0], [2.4, 0], [-2.4, 0]], null);
  }

  centre(): Pt | null { return this.way.at(this.way.length / 2); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.militaryParade, drive = spec.dur * 0.75;
    const out = now >= e.start - spec.lead && now < e.end;
    this.closure.set(out);
    this.g.visible = out;
    if (!out) return;
    const run = (now - e.start) / drive;
    const L = this.way.length, total = this.rigs[this.rigs.length - 1].off + 1;
    const lead = total + clamp01(run) * Math.max(0, L - total);
    const v = run > 0 && run < 1 ? (L - total) / (drive * HOUR_S) : 0;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / (spec.lead * 0.8)) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.cheer = run > 0 && run < 1 ? 0.6 : 0;
    this.crowd.update(dt);
    this.soldiers.shown = this.soldiers.size;
    march(this.soldiers, this.way, lead, 0.17, dt);
    this.soldiers.update(dt);
    for (const { rig, off } of this.rigs) {
      const p = this.way.at(lead - off);
      rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (rig.w) this.ctx.obstacles.push({ state: rig.local, def: rig.def, w: rig.w });
    }
    // the flyover over the middle of the avenue, then the twin-rotors
    const over = this.way.at(L / 2);
    this.jets.update(this.ctx, now, e.start + drive * 0.45, over, this.head, 13, 6.5, dt);
    this.helis.update(this.ctx, now, e.start + drive * 0.75, over, this.head, 5, 4.5, dt);
  }

  dispose(): void {
    this.closure.set(false);
    for (const r of this.rigs) r.rig.dispose();
    this.jets.dispose(); this.helis.dispose();
    this.soldiers.dispose(); this.crowd.dispose();
    super.dispose();
  }
}

// ---- Pride ---------------------------------------------------------------------------------------------------

/**
 * Pride on summer's day: rainbow flags along the main street, floats decked in the colours, people marching behind
 * them waving; and after dark the city's towers in rainbow bands, the tallest slowly cycling through the colours.
 */
export class PrideShow extends Show {
  private way: Way;
  private floats: { rig: Rig; off: number }[] = [];
  private walkers: Crowd;
  private crowd: Crowd;
  private closure: Closure;
  private box: { x0: number; z0: number; x1: number; z1: number };
  private walkLen = 0;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const P = place.path!;
    this.way = new Way(P.map((p) => toWorld(w, p)));
    let off = 0;
    ['bus', 'liveTruck', 'bus', 'dump', 'bus', 'postal'].forEach((id, i) => {
      const def = dressed(id, PRIDE[i % PRIDE.length], PRIDE[(i + 3) % PRIDE.length]);
      const half = (def as { halfLen?: number }).halfLen ?? 0.6;
      off += half;
      this.floats.push({ rig: new Rig(this.g, def, 8), off });
      off += half + 0.7;
    });
    this.walkLen = off + 0.4;
    this.walkers = new Crowd(this.g, ctx.ground, 0, PRIDE);
    this.walkers.manual = true;
    for (let i = 0; i < 36; i++) this.walkers.add(this.way.pts[0].x, this.way.pts[0].z);
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    lineStreet(this.crowd, w, P, e.h, 44);
    this.closure = new Closure(w, P.map((p) => Math.floor(p.x) + Math.floor(p.z) * N));
    // the flags: a pole every few tiles of the street, a rainbow on each
    for (let k = 2; k < P.length - 1; k += 3) {
      const a = P[k - 1], b = P[k + 1], d = Math.hypot(b.x - a.x, b.z - a.z) || 1;
      const nx = -(b.z - a.z) / d, nz = (b.x - a.x) / d;
      for (const side of [1, -1]) {
        const x = w.ox + P[k].x + nx * side * 0.47, z = w.oz + P[k].z + nz * side * 0.47;
        const y = ctx.ground(x, z);
        block(this.g, x, y, z, 0.012, 0.42, 0.012, 0xdddddd);
        PRIDE.forEach((c, j) => block(this.g, x + nx * side * 0.07, y + 0.39 - j * 0.022, z + nz * side * 0.07, 0.008, 0.022, 0.13, c, Math.atan2(b.x - a.x, b.z - a.z)));
      }
    }
    const t = place.town!;
    this.box = { x0: w.ox + t.x0 - 2, z0: w.oz + t.z0 - 2, x1: w.ox + t.x0 + t.size + 2, z1: w.oz + t.z0 + t.size + 2 };
  }

  centre(): Pt | null { return this.way.at(this.way.length / 2); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.pride, drive = 2;
    const day = now >= e.start - spec.lead && now < e.start + drive + 0.4;
    this.closure.set(day);
    const run = (now - e.start) / drive;
    const L = this.way.length, total = this.walkLen + 9 * 0.2;
    const lead = total + clamp01(run) * Math.max(0, L - total);
    const v = run > 0 && run < 1 ? (L - total) / (drive * HOUR_S) : 0;
    for (const { rig, off } of this.floats) {
      if (!day) { rig.hide(); continue; }
      const p = this.way.at(lead - off);
      rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (rig.w) this.ctx.obstacles.push({ state: rig.local, def: rig.def, w: rig.w });
    }
    this.walkers.shown = day ? this.walkers.size : 0;
    this.walkers.cheer = run > 0 && run < 1 ? 0.7 : 0;
    if (day) march(this.walkers, this.way, lead - this.walkLen, 0.2, dt);
    this.walkers.update(dt);
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.start + drive)) / 0.4));
    this.crowd.cheer = run > 0 && run < 1 ? 0.8 : 0;
    this.crowd.update(dt);
    // the towers at night
    const dusk = hourOf(now) >= 19 || hourOf(now) < 3;
    const tower = this.place.tower;
    if (dusk && now < e.end) {
      this.light(0, { ...this.box, uid: -1, walls: true, mode: 'rainbow', a: 0xffffff, strength: 0.4, minY: this.place.town!.level * STEP + 1.6 });
      if (tower) this.light(1, { x0: this.w.ox + tower.x - 0.5, z0: this.w.oz + tower.z - 0.5, x1: this.w.ox + tower.x + tower.w + 0.5, z1: this.w.oz + tower.z + tower.d + 0.5, uid: tower.uid, mode: 'rainbow', a: 0xffffff, strength: 1.2, phase: now * 0.4 });
    } else { this.light(0, null); this.light(1, null); }
  }

  dispose(): void {
    this.closure.set(false);
    for (const f of this.floats) f.rig.dispose();
    this.walkers.dispose(); this.crowd.dispose();
    super.dispose();
  }
}

// ---- the air show ---------------------------------------------------------------------------------------------------

/**
 * An afternoon at an airfield: two Barnstormers looping in smoke over the strip, a Stinger's low pass down the
 * runway and its climb away, parachutists drifting down onto the apron, and a crowd along the fence.
 */
export class AirShowShow extends Show {
  private planes: Rig[] = [];
  private jet: Rig;
  private chutes: { g: THREE.Group; canopy: THREE.Mesh; x: number; z: number }[] = [];
  private crowd: Crowd;
  private r: NonNullable<Place['runway']>;

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    this.r = place.runway!;
    this.planes = [new Rig(this.g, dressed('barnstormer', 0xc8102e)), new Rig(this.g, dressed('barnstormer', 0xf4f2ec))];
    this.jet = new Rig(this.g, dressed('fighter'));
    this.jet.hide();
    const r = this.r;
    for (let i = 0; i < 5; i++) {
      const g = new THREE.Group();
      const canopy = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 5, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: PRIDE[i], side: THREE.DoubleSide, flatShading: true }));
      canopy.position.y = 0.32;
      const body = new THREE.Mesh(new THREE.IcosahedronGeometry(0.045, 1), flat(0x3a3f45));
      g.add(canopy, body);
      g.visible = false;
      this.g.add(g);
      const along = r.len * (0.35 + i * 0.07), across = r.taxiOff + 3 + (i % 2) * 1.2;
      this.chutes.push({ g, canopy, x: r.ax + r.ux * along + r.sx * across, z: r.az + r.uz * along + r.sz * across });
    }
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { const r = this.r; return { x: r.ax + r.ux * r.len / 2, z: r.az + r.uz * r.len / 2 }; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.airShow, r = this.r;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = now - e.start;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.update(dt);
    const heading = Math.atan2(r.ux, r.uz);
    // the Barnstormers: loops in the vertical over the strip, the pair half a loop apart, their centre drifting along it
    const looping = t > 0 && t < spec.dur * 0.55;
    this.planes.forEach((p, i) => {
      if (!looping) { p.hide(); return; }
      const th = t * HOUR_S * 0.9 + i * Math.PI;
      const R = 2.6, drift = r.len * (0.5 + 0.3 * Math.sin(t * 0.9));
      const cx = r.ax + r.ux * drift, cz = r.az + r.uz * drift, cy = r.y + R + 2.2;
      const x = cx + r.ux * R * Math.sin(th), y = cy - R * Math.cos(th), z = cz + r.uz * R * Math.sin(th);
      p.fly(x, y, z, heading, -th, 0, dt);
      if (Math.random() < dt * 45) this.ctx.particles.puff({ x: x - r.ux * 0.5 * Math.cos(th), y: y - 0.5 * Math.sin(th), z: z - r.uz * 0.5 * Math.cos(th), vx: 0, vy: 0, vz: 0, life: 3.5, colour: 0xf4f4f4, size: 0.3 });
    });
    // the Stinger's pass: in low down the runway, the burners lit, and straight up at the far end
    const pass = (t - spec.dur * 0.6) / 0.28;
    if (pass > 0 && pass < 1) {
      const along = -40 + pass * (r.len + 70);
      const climb = Math.max(0, along - r.len * 0.8);
      const x = r.ax + r.ux * along, z = r.az + r.uz * along, y = r.y + 2.2 + climb * 0.9;
      this.jet.fly(x, y, z, heading, -Math.min(1.2, climb * 0.12), 0, dt);
      for (let k = 0; k < 3; k++) this.ctx.particles.spark({ x: x - r.ux * 0.8, y, z: z - r.uz * 0.8, vx: -r.ux * 2, vy: 0, vz: -r.uz * 2, life: 0.25, colour: 0xffa040, size: 0.14, gravity: 0, drag: 2 });
    } else this.jet.hide();
    // the parachutists: out high over the apron, down slowly, the canopies folding on landing
    const drop = (t - spec.dur * 0.75) / 0.55;
    this.chutes.forEach((c, i) => {
      const f = drop - i * 0.06;
      if (f < 0 || f > 1.25) { c.g.visible = false; return; }
      const gy = this.ctx.ground(c.x, c.z);
      const y = gy + Math.max(0, 12 * (1 - f));
      c.g.visible = true;
      c.g.position.set(c.x + Math.sin(f * 6 + i) * 0.6 * (1 - Math.min(1, f)), y, c.z + Math.cos(f * 5 + i) * 0.6 * (1 - Math.min(1, f)));
      c.canopy.scale.y = f >= 1 ? Math.max(0.1, 1 - (f - 1) * 4) : 1;
    });
    this.crowd.cheer = (pass > 0 && pass < 1) || (drop > 0.9 && drop < 1.3) ? 1 : looping ? 0.25 : 0;
  }

  dispose(): void { for (const p of this.planes) p.dispose(); this.jet.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- the tall ships ---------------------------------------------------------------------------------------------------

/**
 * A fleet of galleons sails in from the offing in the morning to moor off the harbour for an open day, people
 * along the quay, and sails out again the next morning.
 */
export class TallShipsShow extends Show {
  private ships: { rig: Rig; way: Way | null; berth: Pt; delay: number }[] = [];
  private crowd: Crowd;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const def = VEHICLES.find((v) => v.id === 'galleon') as WaterDef;
    const off = place.offing!;
    place.berths!.slice(0, 5).forEach((b, i) => {
      const pts = waterRoute(w, def, off.x, off.z, b.x, b.z, new Set());
      this.ships.push({ rig: new Rig(this.g, dressed('galleon')), way: pts && pts.length > 1 ? new Way([off, ...pts].map((p) => toWorld(w, p))) : null, berth: toWorld(w, b), delay: i * 0.3 });
    });
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { const b = this.place.berths![0]; return toWorld(this.w, b); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.tallShips, SAIL = 1.6;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    for (const s of this.ships) {
      if (!s.way) { s.rig.hide(); continue; }
      const L = s.way.length;
      const inT = (now - e.start - s.delay) / SAIL, outT = (now - (e.end - SAIL - 0.3 + s.delay * 0.5)) / SAIL;
      let d: number, v = 0, back = false;
      if (inT < 0) { s.rig.hide(); continue; }
      if (inT < 1) { d = inT * L; v = L / (SAIL * HOUR_S); }
      else if (outT < 0) d = L;
      else if (outT < 1) { d = (1 - outT) * L; v = L / (SAIL * HOUR_S); back = true; }
      else { s.rig.hide(); continue; }
      const p = s.way.at(d);
      s.rig.float(this.ctx.worldAt, p.x, p.z, back ? p.heading + Math.PI : p.heading, v, dt, v ? 0.4 : 0);
    }
    // an open day along the quay, in the daytime
    const h = hourOf(now), open = now > e.start + SAIL && now < e.end - SAIL && h > 9 && h < 19;
    this.crowd.shown += ((open ? this.crowd.size : 0) - this.crowd.shown) * Math.min(1, dt * 0.5);
    this.crowd.update(dt);
  }

  dispose(): void { for (const s of this.ships) s.rig.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- lights ---------------------------------------------------------------------------------------------------

/** A landmark washed in colour for an evening, its colours changing on the half hour, four searchlights sweeping the sky round it. */
export class LightShowShow extends Show {
  private beams: THREE.Group[] = [];
  private corners: Pt[] = [];
  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const b = place.tower!;
    const pad = 0.8;
    this.corners = [[b.x - pad, b.z - pad], [b.x + b.w + pad, b.z - pad], [b.x + b.w + pad, b.z + b.d + pad], [b.x - pad, b.z + b.d + pad]].map(([x, z]) => ({ x: w.ox + x, z: w.oz + z }));
    for (let i = 0; i < 4; i++) this.beams.push(beam(this.g));
  }
  centre(): Pt | null { const b = this.place.tower!; return toWorld(this.w, mid(b)); }
  update(now: number, dt: number): void {
    void dt;
    const e = this.e, b = this.place.tower!, on = now >= e.start && now < e.end;
    this.g.visible = on;
    if (!on) { this.light(0, null); return; }
    const pal = NATIONS[(e.h + Math.floor((now - e.start) * 2)) % NATIONS.length];
    const modes = ['bands', 'rainbow', 'chase', 'solid'] as const;
    const mode = modes[Math.floor((now - e.start) * 2) % modes.length];
    this.light(0, { x0: this.w.ox + b.x - 0.5, z0: this.w.oz + b.z - 0.5, x1: this.w.ox + b.x + b.w + 0.5, z1: this.w.oz + b.z + b.d + 0.5, uid: b.uid, mode, a: pal[0], b: pal[2], strength: 0.6 + this.ctx.night() * 0.9 });
    const t = performance.now() / 1000;
    this.beams.forEach((g, i) => {
      const c = this.corners[i];
      g.position.set(c.x, this.ctx.ground(c.x, c.z), c.z);
      g.rotation.set(0.35 + 0.2 * Math.sin(t * 0.7 + i), t * 0.4 + (i * Math.PI) / 2, 0, 'YXZ');
      g.visible = this.ctx.night() > 0.2;
    });
  }
}

/** A town's winter night: strings of coloured lights on every house, a great tree hung with bulbs in the square. */
export class WinterLightsShow extends Show {
  private box: { x0: number; z0: number; x1: number; z1: number };
  private bulbs: Bulbs | null = null;
  private tree: Pt & { y: number } | null = null;
  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const t = place.town!;
    this.box = { x0: w.ox + t.x0 - 2, z0: w.oz + t.z0 - 2, x1: w.ox + t.x0 + t.size + 2, z1: w.oz + t.z0 + t.size + 2 };
    if (place.lot) {
      const c = toWorld(w, mid(place.lot)), y = ctx.ground(c.x, c.z);
      this.tree = { ...c, y };
      [[0.55, 0.7, 0], [0.42, 0.6, 0.45], [0.28, 0.5, 0.85]].forEach(([r, h, at]) => {
        const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 8), flat(0x1f5a2e));
        cone.position.set(c.x, y + 0.15 + at + h / 2, c.z);
        cone.castShadow = true;
        this.g.add(cone);
      });
      block(this.g, c.x, y, c.z, 0.1, 0.18, 0.1, 0x5a3a22);
      const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.1), flat(0xffd166, 2));
      star.position.set(c.x, y + 1.62, c.z);
      this.g.add(star);
      this.bulbs = new Bulbs(this.g, 40, [0xff3b3b, 0x3dff8a, 0x5ad1ff, 0xffd166, 0xff6ad5, 0xffffff]);
    }
  }
  centre(): Pt | null { return this.tree ?? toWorld(this.w, { x: this.place.town!.x0 + this.place.town!.size / 2, z: this.place.town!.z0 + this.place.town!.size / 2 }); }
  update(now: number, dt: number): void {
    void dt;
    const e = this.e, on = now >= e.start && now < e.end;
    this.g.visible = on;
    const night = this.ctx.night();
    if (on && night > 0.15) this.light(0, { ...this.box, uid: -1, walls: true, mode: 'twinkle', a: 0xffffff, strength: 0.55 * night });
    else this.light(0, null);
    if (this.bulbs && this.tree) {
      this.bulbs.begin();
      const t = performance.now() / 1000;
      for (let k = 0; k < 40; k++) {
        // a spiral of bulbs up the tree, every other one dimmed in turn
        const u = k / 40, a = u * Math.PI * 9, r = 0.55 * (1 - u) + 0.05;
        if ((k + Math.floor(t * 2)) % 5 === 0) continue;
        this.bulbs.at(this.tree.x + Math.cos(a) * r, this.tree.y + 0.2 + u * 1.35, this.tree.z + Math.sin(a) * r);
      }
      this.bulbs.end();
    }
  }
}

/** A town's autumn night: orange and violet on its walls, a carved pumpkin glowing on many a doorstep, mist in the streets. */
export class SpookyNightShow extends Show {
  private box: { x0: number; z0: number; x1: number; z1: number };
  private pumpkins: THREE.InstancedMesh;
  private mat: THREE.MeshStandardMaterial;
  private doors: Pt[];
  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const t = place.town!;
    this.box = { x0: w.ox + t.x0 - 2, z0: w.oz + t.z0 - 2, x1: w.ox + t.x0 + t.size + 2, z1: w.oz + t.z0 + t.size + 2 };
    this.doors = (place.doors ?? []).map((d) => toWorld(w, d));
    this.mat = new THREE.MeshStandardMaterial({ color: 0xf28c1e, emissive: 0xff7a10, emissiveIntensity: 0.2, roughness: 0.6, flatShading: true });
    this.pumpkins = new THREE.InstancedMesh(new THREE.SphereGeometry(0.055, 8, 5).scale(1, 0.8, 1), this.mat, Math.max(1, this.doors.length));
    const m = new THREE.Matrix4();
    this.doors.forEach((d, i) => { m.makeTranslation(d.x, ctx.ground(d.x, d.z) + 0.045, d.z); this.pumpkins.setMatrixAt(i, m); });
    this.pumpkins.count = this.doors.length;
    this.g.add(this.pumpkins);
  }
  centre(): Pt | null { const t = this.place.town!; return toWorld(this.w, { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 }); }
  update(now: number, dt: number): void {
    const e = this.e, on = now >= e.start - KIND_OF.spookyNight.lead && now < e.end;
    this.g.visible = on;
    const night = this.ctx.night();
    this.mat.emissiveIntensity = 0.2 + night * 1.8 * (0.85 + 0.15 * Math.sin(performance.now() / 180));
    if (on && night > 0.15) this.light(0, { ...this.box, uid: -1, walls: true, mode: 'bands', a: 0xff7a1a, b: 0x8e44ff, strength: 0.3 * night });
    else this.light(0, null);
    // mist drifting low through the streets
    if (on && this.doors.length && Math.random() < dt * 14) {
      const d = this.doors[Math.floor(Math.random() * this.doors.length)];
      this.ctx.particles.puff({ x: d.x + (Math.random() - 0.5) * 3, y: this.ctx.ground(d.x, d.z) + 0.12, z: d.z + (Math.random() - 0.5) * 3, vx: 0.08, vy: 0.01, vz: 0.05, life: 8, colour: 0x7d7a96, size: 0.55, drag: 0.2, alpha: 0.28 });
    }
  }
}

/** The tallest building's top, for anything that goes up from it. */
function towerTop(w: World, b: NonNullable<Place['tower']>): THREE.Vector3 {
  return roofTopAt(w, b) ?? new THREE.Vector3(w.ox + b.x + b.w / 2, b.level * STEP + buildingHeight(b), w.oz + b.z + b.d / 2);
}
