import * as THREE from 'three';
import { N, STEP, World, idx } from '../world/tiles';
import { MAP_PIX, TILES_PER_PIX, type Atlas } from '../world/atlas';
import { propsOn } from './props';

/** How far the cover stands over the tallest thing under it, and reaches under the lowest ground. */
const HEAD = 0.6, FOOT = 1.5;
/** Over the tallest tree or cactus (a big poplar or oak stands about 1.9), so no crown pokes through. */
const CROWN = 2.1;
/**
 * Room over a road, a railway or a deck for what drives on it (a Big Bertha, a train), and over water for a
 * ship's superstructure: a lorry or a rail line deep in the fog showed through it (the user, 7 Oct 2026).
 */
const VEHICLE = 1.2, SHIP = 2.4;
const COLOUR = 0x1f2730;

/**
 * The overview's fog (M): everywhere the atlas has no record of the player, or their fleet, having
 * been near is covered, as the world map and the region map leave it dark. One block per map pixel
 * (eight tiles square), standing just over the tallest ground, water or roof under it, so what lies
 * beneath is hidden from above and the blocks read as the world's own tiles rather than a wall.
 */
export class FogCover {
  readonly root = new THREE.Group();
  private geo = new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0);
  private mat = new THREE.MeshLambertMaterial({ color: COLOUR });
  private built = new Map<World, { mesh: THREE.InstancedMesh | null; version: number }>();

  constructor() {
    this.root.name = 'fog';
    this.root.visible = false;
  }

  /** Cover the unseen parts of these islands, or hide the cover (`on` false: not in the overview). */
  update(atlas: Atlas, worlds: World[], on: boolean): void {
    this.root.visible = on;
    if (!on) return;
    const live = new Set(worlds);
    for (const [w, b] of this.built) {
      if (live.has(w)) continue;
      if (b.mesh) { this.root.remove(b.mesh); b.mesh.dispose(); }
      this.built.delete(w);
    }
    for (const w of worlds) {
      const have = this.built.get(w);
      if (have && have.version === atlas.version) continue;
      if (have?.mesh) { this.root.remove(have.mesh); have.mesh.dispose(); }
      const mesh = this.build(atlas, w);
      if (mesh) this.root.add(mesh);
      this.built.set(w, { mesh, version: atlas.version });
    }
  }

  private build(atlas: Atlas, w: World): THREE.InstancedMesh | null {
    const seen = atlas.revealed(w.cx, w.cz);
    const fogged: number[] = [];
    for (let p = 0; p < MAP_PIX * MAP_PIX; p++) if (!seen || !seen[p]) fogged.push(p);
    if (!fogged.length) return null;
    const mesh = new THREE.InstancedMesh(this.geo, this.mat, fogged.length);
    mesh.frustumCulled = false;
    const m = new THREE.Matrix4();
    const c = w.corners;
    // the railways' tops, by map pixel: a line on a bank or a viaduct stands well over the ground beneath it
    const railTop = new Float32Array(MAP_PIX * MAP_PIX).fill(-Infinity);
    for (const r of w.rails) {
      for (let k = 0; k < r.y.length; k++) {
        const px = Math.floor(r.xz[k * 2] / TILES_PER_PIX), pz = Math.floor(r.xz[k * 2 + 1] / TILES_PER_PIX);
        if (px < 0 || pz < 0 || px >= MAP_PIX || pz >= MAP_PIX) continue;
        const q = pz * MAP_PIX + px;
        if (r.y[k] > railTop[q]) railTop[q] = r.y[k];
      }
    }
    fogged.forEach((p, k) => {
      const px = p % MAP_PIX, pz = (p - px) / MAP_PIX;
      const x0 = px * TILES_PER_PIX, z0 = pz * TILES_PER_PIX;
      let lo = Infinity, hi = -Infinity, room = 0;
      for (let z = z0; z < z0 + TILES_PER_PIX && z < N; z++) {
        for (let x = x0; x < x0 + TILES_PER_PIX && x < N; x++) {
          const i = idx(x, z);
          // a raised road's deck, and room over anything that moves: a road, a railway, the water
          if (w.deckAxis[i]) hi = Math.max(hi, w.deckLo[i], w.deckHi[i]);
          if (w.water[i] >= 0) room = Math.max(room, SHIP);
          else if (w.road[i] || w.rail[i] || w.deckAxis[i]) room = Math.max(room, VEHICLE);
          for (let q = 0; q < 4; q++) {
            const y = c[i * 4 + q] * STEP;
            if (y < lo) lo = y;
            if (y > hi) hi = y;
          }
          if (w.water[i] >= 0) hi = Math.max(hi, w.water[i] * STEP);
          if (w.roof[i] > hi) hi = w.roof[i];
          const pr = propsOn(w, x, z);
          if (pr.trees || pr.cacti) {
            let top = -Infinity;
            for (let q = 0; q < 4; q++) top = Math.max(top, c[i * 4 + q] * STEP);
            hi = Math.max(hi, top + CROWN - HEAD);
          }
        }
      }
      if (railTop[p] > -Infinity) { hi = Math.max(hi, railTop[p]); room = Math.max(room, VEHICLE); }
      const bottom = lo - FOOT, top = hi + HEAD + room;
      m.makeScale(TILES_PER_PIX, top - bottom, TILES_PER_PIX).setPosition(w.ox + x0 + TILES_PER_PIX / 2, bottom, w.oz + z0 + TILES_PER_PIX / 2);
      mesh.setMatrixAt(k, m);
    });
    mesh.instanceMatrix.needsUpdate = true;
    return mesh;
  }
}
