/**
 * The postcard every take is dressed as (docs/postcards.html): an airmail border of red and blue stripes, the
 * picture inset on white card, a perforated postage stamp in the top right for where it was taken (the town's
 * style, or the biome out in the country), and the TinyFleet postmark inked over the stamp, the way a post
 * office cancels it, with the game's wordmark among its cancel lines.
 *
 * Where it goes is chosen for how Reddit shows a video. Desktop and the app's player show the whole frame,
 * letterboxed. The app's feed shows a tall video cropped towards 4:5 round its middle, with the vote and
 * comment buttons over the right-hand side lower down. So on a tall frame the stamp, the postmark and the
 * corner marks stand inside the middle 4:5 band (they are still on the card when the whole frame shows), and the
 * stamp keeps to the top of that band, clear of the buttons. A wide or square frame shows whole everywhere:
 * the stamp goes in its corner.
 *
 * The border and everything on it is drawn once into an overlay with a hole for the picture, and laid over
 * each frame: a clip pays for one image draw a frame, not for the stripes.
 */

/** The stamp's look: what it shows, what it says, and its colour. */
export interface StampLook { icon: string; label: string; colour: string }

/** The card's proportions, as shares of the frame's shorter side. */
const BAND = 0.042, MARGIN = 0.02, STAMP_H = 0.2, STAMP_W = 0.16;
/** On a tall frame, the band the app's feed keeps (width / height). */
const FEED_ASPECT = 4 / 5;
const RED = '#d8312b', BLUE = '#2a4fb8', CARD = '#fbfaf5', INK = 'rgba(28, 34, 44, 0.8)';

/** The rectangle the picture goes in, in output pixels. */
export function photoRect(W: number, H: number): { x: number; y: number; w: number; h: number } {
  const s = Math.min(W, H), inset = Math.round(s * (BAND + MARGIN));
  return { x: inset, y: inset, w: W - inset * 2, h: H - inset * 2 };
}

/** The part of the frame Reddit's app feed shows: the whole of a wide or square one, the middle 4:5 of a tall one. */
function safeBand(W: number, H: number): { top: number; bottom: number } {
  if (W / H >= FEED_ASPECT) return { top: 0, bottom: H };
  const h = W / FEED_ASPECT;
  return { top: (H - h) / 2, bottom: (H + h) / 2 };
}

/**
 * The overlay for a W×H frame: the card and its border with a hole where the picture shows, the stamp and the
 * postmark, and the fleet's marks along the bottom (`marks` draws them, given the y of their row and the picture's rect).
 */
export function drawOverlay(W: number, H: number, stamp: StampLook, date: Date, marks: (g: CanvasRenderingContext2D, y: number, u: number, photo: { x: number; y: number; w: number; h: number }) => void): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const s = Math.min(W, H), u = s / 1080;
  const p = photoRect(W, H);
  const band = Math.round(s * BAND);

  // the card, with the picture's hole cut out
  g.fillStyle = CARD;
  g.fillRect(0, 0, W, H);
  // airmail stripes round the edge: red, card, blue, card, on the slant
  g.save();
  g.beginPath();
  g.rect(0, 0, W, H);
  g.rect(band, band, W - band * 2, H - band * 2);
  g.clip('evenodd');
  const sw = band * 0.95, period = sw * 4;
  for (let x = -H - period; x < W + H; x += period) {
    for (const [off, col] of [[0, RED], [sw * 2, BLUE]] as [number, string][]) {
      g.fillStyle = col;
      g.beginPath();
      g.moveTo(x + off, 0);
      g.lineTo(x + off + sw, 0);
      g.lineTo(x + off + sw - H, H);
      g.lineTo(x + off - H, H);
      g.closePath();
      g.fill();
    }
  }
  g.restore();
  // the picture's window, with a fine edge like a printed photo
  g.clearRect(p.x, p.y, p.w, p.h);
  g.strokeStyle = 'rgba(31, 43, 51, 0.35)';
  g.lineWidth = Math.max(1, 2 * u);
  g.strokeRect(p.x - g.lineWidth / 2, p.y - g.lineWidth / 2, p.w + g.lineWidth, p.h + g.lineWidth);

  // the stamp, top right, inside the feed's band on a tall frame
  const safe = safeBand(W, H);
  const sh = Math.round(s * STAMP_H), swd = Math.round(s * STAMP_W);
  const sx = W - band - Math.round(s * 0.035) - swd;
  const sy = Math.max(band + Math.round(s * 0.03), safe.top + Math.round(s * 0.05));
  drawStamp(g, sx, sy, swd, sh, stamp, u);
  // the postmark over its lower left corner, slightly askew
  drawPostmark(g, sx + swd * 0.12, sy + sh * 0.8, sh * 0.44, date, u);

  // the fleet's marks along the bottom of the picture, inside the feed's band
  const markY = Math.min(p.y + p.h, safe.bottom) - Math.round(24 * u) - Math.round(52 * u);
  marks(g, markY, u, p);
  return c;
}

/** A postage stamp: a white perforated edge, a coloured face with the picture, the place's name and the value. */
export function drawStamp(g: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, look: StampLook, u: number): void {
  const r = Math.max(2, 5.5 * u), step = r * 2.9;
  // the perforated paper: a rectangle with half-round bites along every edge
  g.save();
  g.shadowColor = 'rgba(0, 0, 0, 0.28)';
  g.shadowBlur = 10 * u;
  g.shadowOffsetY = 3 * u;
  g.beginPath();
  const edge = (x0: number, y0: number, x1: number, y1: number) => {
    const len = Math.hypot(x1 - x0, y1 - y0), n = Math.max(2, Math.round(len / step)), dx = (x1 - x0) / len, dy = (y1 - y0) / len;
    const gap = len / n;
    for (let k = 0; k < n; k++) {
      const cx = x0 + dx * (k + 0.5) * gap, cy = y0 + dy * (k + 0.5) * gap;
      const a = Math.atan2(dy, dx);
      g.lineTo(cx - dx * r, cy - dy * r);
      g.arc(cx, cy, r, a + Math.PI, a, true);
    }
    g.lineTo(x1, y1);
  };
  g.moveTo(x, y);
  edge(x, y, x + w, y);
  edge(x + w, y, x + w, y + h);
  edge(x + w, y + h, x, y + h);
  edge(x, y + h, x, y);
  g.closePath();
  g.fillStyle = '#fffdf6';
  g.fill();
  g.restore();
  // the face
  const m = Math.round(w * 0.1), fx = x + m, fy = y + m, fw = w - m * 2, fh = h - m * 2;
  const grad = g.createLinearGradient(fx, fy, fx, fy + fh);
  grad.addColorStop(0, look.colour);
  grad.addColorStop(1, shade(look.colour, -0.28));
  g.fillStyle = grad;
  g.fillRect(fx, fy, fw, fh);
  g.strokeStyle = 'rgba(255, 255, 255, 0.55)';
  g.lineWidth = Math.max(1, 2 * u);
  g.strokeRect(fx + 5 * u, fy + 5 * u, fw - 10 * u, fh - 10 * u);
  // its picture
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.font = `${Math.round(fh * 0.42)}px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif`;
  g.fillText(look.icon, fx + fw / 2, fy + fh * 0.44);
  // the value and the name
  g.fillStyle = '#fff';
  g.font = `800 ${Math.round(fh * 0.13)}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
  g.textAlign = 'left';
  g.fillText('25¢', fx + 9 * u, fy + fh * 0.12);
  g.textAlign = 'center';
  let size = Math.round(fh * 0.12);
  const label = look.label.toUpperCase();
  g.font = `800 ${size}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
  while (size > 8 && g.measureText(label).width > fw - 14 * u) { size--; g.font = `800 ${size}px "Fredoka", "Segoe UI", system-ui, sans-serif`; }
  g.fillText(label, fx + fw / 2, fy + fh * 0.86);
}

/**
 * The TinyFleet postmark, the way a post office cancels a stamp: a round date stamp over the stamp's corner, and
 * running off to its left the wavy cancel lines with the game's wordmark set among them like a slogan cancel —
 * "TinyFleet." in the title's own Fredoka, weight and tracking, period and all, in the postmark's ink.
 */
function drawPostmark(g: CanvasRenderingContext2D, cx: number, cy: number, R: number, date: Date, u: number): void {
  g.save();
  g.translate(cx, cy);
  g.rotate(-0.16);
  g.strokeStyle = INK;
  g.fillStyle = INK;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  // the wordmark, to the left of the ring, as tall as the cancel lines leave room for
  const f = Math.round(R * 0.5);
  g.font = `700 ${f}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
  const spaced = g as CanvasRenderingContext2D & { letterSpacing?: string };
  if ('letterSpacing' in spaced) spaced.letterSpacing = `${(-0.03 * f).toFixed(1)}px`;
  const word = 'TinyFleet.';
  const ww = g.measureText(word).width;
  const wx = -R * 1.12 - ww / 2;
  g.fillText(word, wx, R * 0.02);
  if ('letterSpacing' in spaced) spaced.letterSpacing = '0px';
  // the cancel lines: two above the wordmark and two below, from its far end to under the ring's edge
  g.lineWidth = Math.max(1.5, 3 * u);
  const x0 = wx - ww / 2 - R * 0.25, x1 = -R * 0.9;
  for (const y0 of [-R * 0.62, -R * 0.42, R * 0.44, R * 0.64]) {
    g.beginPath();
    for (let x = x0; x <= x1; x += 2) {
      const yy = y0 + Math.sin(x / (R * 0.2)) * R * 0.06;
      if (x === x0) g.moveTo(x, yy); else g.lineTo(x, yy);
    }
    g.stroke();
  }
  // the date stamp: two rings, the post's name over the top, the date along the bottom, a star in the middle
  g.lineWidth = Math.max(1.5, 3.4 * u);
  g.beginPath(); g.arc(0, 0, R, 0, Math.PI * 2); g.stroke();
  g.lineWidth = Math.max(1, 1.8 * u);
  g.beginPath(); g.arc(0, 0, R * 0.64, 0, Math.PI * 2); g.stroke();
  g.font = `700 ${Math.round(R * 0.19)}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
  // letters set round the ring between its two circles: clockwise across the top, anticlockwise (so upright) along the bottom
  const around = (text: string, mid: number, top: boolean) => {
    const rr = R * 0.82, chars = [...text], track = R * 0.03;
    const span = chars.reduce((s, ch) => s + g.measureText(ch).width + track, 0) / rr;
    let a = mid - (top ? span / 2 : -span / 2);
    for (const ch of chars) {
      const cw = (g.measureText(ch).width + track) / rr;
      a += top ? cw / 2 : -cw / 2;
      g.save();
      g.rotate(a);
      g.translate(0, -rr);
      if (!top) g.rotate(Math.PI);
      g.fillText(ch, 0, 0);
      g.restore();
      a += top ? cw / 2 : -cw / 2;
    }
  };
  around('AIR MAIL', 0, true);
  around(`${String(date.getDate()).padStart(2, '0')} ${date.toLocaleString('en-GB', { month: 'short' }).toUpperCase()} ${date.getFullYear()}`, Math.PI, false);
  g.font = `700 ${Math.round(R * 0.42)}px "Fredoka", "Segoe UI", system-ui, sans-serif`;
  g.fillText('★', 0, R * 0.03);
  g.restore();
}

/** A hex colour made lighter (amount > 0) or darker (< 0). */
function shade(hex: string, amount: number): string {
  const n = parseInt(hex.slice(1), 16);
  const f = (v: number) => Math.round(amount < 0 ? v * (1 + amount) : v + (255 - v) * amount);
  return `rgb(${f(n >> 16)}, ${f((n >> 8) & 255)}, ${f(n & 255)})`;
}
