import { esc } from './common';

/** One thing on the What's on calendar (docs/townregister.html): game hours it starts and ends; `here` for the town's own. */
export interface WhatsOn { at: number; end: number; icon: string; text: string; here: boolean }

/**
 * The next week as days: "Now", "Today", "Tomorrow", then the game day, each thing with its hour; the town's own
 * things (its stadium) marked, the county's said to be the county's.
 */
export function calendarHtml(list: WhatsOn[], hours: number, county: string): string {
  const head = `<h4>The week ahead <span>${county ? `here and in ${esc(county)}` : 'here and in its county'}</span></h4>`;
  const soon = list.filter((e) => e.end > hours).sort((a, b) => a.at - b.at);
  if (!soon.length) return `${head}<p class="note">Nothing on this week: no fixtures, events or markets.</p>`;
  const today = Math.floor(hours / 24);
  const dayOf = (e: WhatsOn) => (e.at <= hours ? -1 : Math.floor(e.at / 24) - today);
  const clockAt = (h: number) => { const m = Math.round((h % 24) * 60); return `${String(Math.floor(m / 60) % 24).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`; };
  let out = head + '<ul class="tc-cal">';
  let last = -2;
  for (const e of soon.slice(0, 14)) {
    const d = dayOf(e);
    if (d !== last) { last = d; out += `<li class="day">${d < 0 ? 'On now' : d === 0 ? 'Today' : d === 1 ? 'Tomorrow' : `Day ${today + d + 1}`}</li>`; }
    out += `<li class="${e.here ? 'here' : ''}"><span class="t">${d < 0 ? `till ${clockAt(e.end)}` : clockAt(e.at)}</span><span>${e.icon} ${esc(e.text)}</span>${e.here ? '' : '<small>county</small>'}</li>`;
  }
  return out + '</ul>';
}
