import { N, DIRS, idx, inB, heightOnTile, type World } from '../world/tiles';
import { ROAD_INFO, deckSurfaceAt } from '../world/roads';
import { findNear, roadReach } from './placement';
import { wallHits } from './traffic';
import type { VehicleState } from './vehicles';

/**
 * The wreckers (Traffic's tows): when a vehicle is stuck fast, a tow truck comes out along the roads,
 * hitches it and hauls it to a stretch of road it can drive on from. This file is the planning — where
 * the truck sets out from, where it hitches, where it lets go — and the gliding: a truck on a tow, and
 * whatever hangs off its hook, are carried along their line rather than driven, so nothing on the way
 * (a wall, a kerb, the queue) can stop them.
 */

type Pt = { x: number; z: number };

/** Each island's flood of the tiles a car can reach from a road, kept until its roads change. */
const REACH = new WeakMap<World, { stamp: number; reach: Uint8Array }>();
function reachOf(w: World): Uint8Array {
  const r = REACH.get(w);
  if (r && r.stamp === w.roadStamp) return r.reach;
  const reach = roadReach(w);
  REACH.set(w, { stamp: w.roadStamp, reach });
  return reach;
}

/** Road tiles this far along the roads from the hitch count as clear of the snag; the truck sets out from about this far. */
const DROP_MIN = 6, DROP_MAX = 14, CALL_MIN = 26, CALL_MAX = 44;
/** The furthest from a stuck vehicle a hitching spot may be. */
const HITCH_REACH = 10;

export interface TowPlan {
  /** Where the truck pulls up to hitch: the drivable road tile nearest the stuck vehicle. */
  hitch: Pt;
  /** Where it lets go: a clear stretch of road a little way on, toward where the vehicle was going if it can. */
  drop: Pt;
  /** Where it comes from, out along the roads; it leaves the same way. */
  call: Pt;
}

/**
 * Plan a tow for a vehicle stuck at (x, z) in w's frame, bound for `goal` (or nowhere). Null when there
 * is no road it can be hauled onto (a roadless islet): the caller falls back to the old ways.
 */
export function planTow(w: World, x: number, z: number, goal: Pt | null): TowPlan | null {
  const reach = reachOf(w);
  const cx = Math.floor(x), cz = Math.floor(z);
  const road = (tx: number, tz: number) => {
    const j = idx(tx, tz);
    return w.road[j] > 0 && !w.blocked[j] && reach[j] === 1 && Math.hypot(tx - cx, tz - cz) <= HITCH_REACH;
  };
  const h = findNear(x, z, road);
  if (!h) return null;
  // out along the roads from the hitch, breadth first: how far each road tile is by road
  const depth = new Map<number, number>([[idx(h[0], h[1]), 0]]);
  const queue = [idx(h[0], h[1])];
  for (let head = 0; head < queue.length; head++) {
    const i = queue[head], d0 = depth.get(i)!;
    if (d0 >= CALL_MAX) continue;
    const ix = i % N, iz = (i - ix) / N;
    for (let d = 0; d < 4; d++) {
      if (!((w.roadEdges[i] >> d) & 1)) continue;
      const nx = ix + DIRS[d][0], nz = iz + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (depth.has(j) || !w.road[j] || w.blocked[j]) continue;
      depth.set(j, d0 + 1);
      queue.push(j);
    }
  }
  const at = (i: number): Pt => ({ x: (i % N) + 0.5, z: Math.floor(i / N) + 0.5 });
  let drop = -1, dropScore = Infinity, call = -1, callD = -1, far = -1, farD = -1;
  for (const [i, d0] of depth) {
    if (d0 > farD) { farD = d0; far = i; }
    if (d0 >= DROP_MIN && d0 <= DROP_MAX && !wallHits(w, i)) {
      // plain road (not a junction), and the nearer to where it was going the better
      const p = at(i);
      const score = (goal ? Math.hypot(goal.x - p.x, goal.z - p.z) : d0) + (w.roadCover[i] > 1 ? 20 : 0);
      if (score < dropScore) { dropScore = score; drop = i; }
    }
    if (d0 >= CALL_MIN && d0 > callD) { callD = d0; call = i; }
  }
  if (drop < 0) drop = far;
  if (call < 0) call = far;
  if (drop < 0 || drop === idx(h[0], h[1])) return null;
  return { hitch: { x: h[0] + 0.5, z: h[1] + 0.5 }, drop: at(drop), call: at(call) };
}

// ---------------------------------------------------------------------------------------------
// gliding along a line

/** A line to glide along: its points and the distance to each from the first. */
export interface Glide { pts: Pt[]; cum: number[]; len: number }

export function glideOf(pts: Pt[]): Glide {
  const cum = [0];
  for (let k = 1; k < pts.length; k++) cum.push(cum[k - 1] + Math.hypot(pts[k].x - pts[k - 1].x, pts[k].z - pts[k - 1].z));
  return { pts, cum, len: cum[cum.length - 1] };
}

/** The point `d` along the line (clamped to its ends, and carried straight on past them), and which way the line runs there. */
export function glideAt(g: Glide, d: number): { x: number; z: number; heading: number } {
  const { pts, cum } = g;
  if (pts.length === 1) return { x: pts[0].x, z: pts[0].z, heading: 0 };
  let k = 0;
  while (k < pts.length - 2 && cum[k + 1] < d) k++;
  const a = pts[k], b = pts[k + 1], seg = Math.max(1e-6, cum[k + 1] - cum[k]);
  const t = (d - cum[k]) / seg;
  return { x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t, heading: Math.atan2(b.x - a.x, b.z - a.z) };
}

/** How sharply the line turns in the stretch ahead of `d`, 0 for straight: to ease through the bends. */
export function glideBend(g: Glide, d: number, ahead = 2.5): number {
  const h0 = glideAt(g, d).heading, h1 = glideAt(g, d + ahead).heading;
  return Math.abs(Math.atan2(Math.sin(h1 - h0), Math.cos(h1 - h0)));
}

/** The surface a glided vehicle sits on: a bridge deck when it is up there already, else the ground (and road). */
function surfaceY(w: World, x: number, z: number, was: number): number {
  const tx = Math.min(N - 1, Math.max(0, Math.floor(x))), tz = Math.min(N - 1, Math.max(0, Math.floor(z)));
  const i = idx(tx, tz);
  const ground = heightOnTile(w, tx, tz, x, z) + (w.road[i] ? ROAD_INFO[w.road[i]].lift : 0);
  if (w.deckAxis[i]) {
    const deck = deckSurfaceAt(w, i, x, z);
    if (Math.abs(deck - was) < Math.abs(ground - was)) return deck;
  }
  return ground;
}

/**
 * Put a vehicle at (x, z) facing `heading`, sitting on whatever is under it and tilted to the slope,
 * moving at v (for its wheels and beacons). `nose` lifts the front by that many radians: a car on the hook.
 */
export function poseGlide(st: VehicleState, w: World, x: number, z: number, heading: number, v: number, dt: number, halfLen: number, nose = 0): void {
  const y0 = Number.isFinite(st.y) ? st.y : surfaceY(w, x, z, 0);
  const fx = Math.sin(heading), fz = Math.cos(heading);
  const yF = surfaceY(w, x + fx * halfLen, z + fz * halfLen, y0), yR = surfaceY(w, x - fx * halfLen, z - fz * halfLen, y0);
  st.x = x; st.z = z; st.heading = heading; st.v = v;
  st.y = (yF + yR) / 2 + Math.sin(nose) * halfLen;
  const k = Math.min(1, dt * 8);
  st.pitch += (-Math.atan2(yF - yR, 2 * halfLen) - nose - st.pitch) * k;
  st.roll += (0 - st.roll) * k;
  st.trailerHeading = heading;
  st.wheelSpin += (v / 0.2) * dt;
  st.power = Math.min(1, Math.abs(v) / 2);
  st.blocked = 0;
}
