/**
 * The notification log: every card that comes down at the top middle (hud.announce, deeds among them)
 * is kept, up to LOG_MAX, and folds into a small pill there once it has had its few seconds. Clicking
 * the pill opens the log, the most recent first; a count on the pill says how many came since it was
 * last opened.
 */

/** How many notifications the log keeps. */
export const LOG_MAX = 50;

/** `group`: notifications from one source (a stadium, a circuit) stack together in the log. */
/** `img`: a stamp earned (a Passport stamp, an achievement's seal), shown in place of the icon, still. */
/** `open`: a notification that opens something when clicked (the annual newspaper, docs/newspaper.html). */
/** `tip`: shown on hover (an achievement's description, the same as the Passport's). */
interface Entry { id: number; title: string; body: string; icon: string; at: string; accent: string; group?: string; img?: string | (() => string); open?: () => void; tip?: string }

/** An entry's mark: its stamp if it earned one, else its icon. */
const mark = (e: Entry): string => {
  // a stamp is drawn the first time the history shows it, and kept
  if (typeof e.img === 'function') e.img = e.img();
  return e.img ? `<img class="nl-stamp" src="${e.img}" alt="">` : e.icon ? `<i>${esc(e.icon)}</i>` : '';
};
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));

export class NotifyLog {
  private list: Entry[] = [];
  /**
   * What came since the log was last opened, counted as the log shows it: a stack (a group's notifications,
   * the Passport stamps, a stadium's results) once however many it gained, and never more than the log keeps.
   * Every entry counted alone had the pill at 99+ within minutes of a new game (Oct 2026 playtest).
   */
  private unreadSingles = 0;
  private unreadGroups = new Set<string>();
  private get unread(): number { return Math.min(LOG_MAX, this.unreadSingles + this.unreadGroups.size); }
  private markRead(): void { this.unreadSingles = 0; this.unreadGroups.clear(); }
  private pill = document.createElement('button');
  private panel = document.createElement('div');
  private open = false;
  /** Groups opened out in the log (a click on a stack); the rest show their newest with a count. */
  private expanded = new Set<string>();
  private nextId = 1;

  constructor(host: HTMLElement) {
    this.pill.type = 'button';
    this.pill.id = 'n-pill';
    this.pill.hidden = true;
    this.pill.title = 'Recent notifications';
    this.panel.id = 'n-log';
    this.panel.hidden = true;
    host.prepend(this.pill);
    host.append(this.panel);
    this.pill.addEventListener('click', (e) => { e.stopPropagation(); this.toggle(); });
    this.panel.addEventListener('click', (e) => {
      e.stopPropagation();
      // a notification that opens something (the newspaper): opened, and the log put away
      const o = (e.target as HTMLElement).closest<HTMLElement>('[data-open]')?.dataset.open;
      if (o !== undefined) {
        const hit = this.list.find((q) => q.id === Number(o));
        if (hit?.open) { this.toggle(false); hit.open(); return; }
      }
      // a stack opens out on a click, and folds back on another
      const g = (e.target as HTMLElement).closest<HTMLElement>('[data-grp]')?.dataset.grp;
      if (g === undefined) return;
      if (this.expanded.has(g)) this.expanded.delete(g); else this.expanded.add(g);
      this.render();
    });
    // a click anywhere else, or Esc, puts it away
    addEventListener('pointerdown', (e) => { if (this.open && !this.panel.contains(e.target as Node) && e.target !== this.pill) this.toggle(false); });
    addEventListener('keydown', (e: KeyboardEvent) => { if (this.open && e.key === 'Escape') this.toggle(false); });
  }

  /**
   * A notification has gone up: into the log, the newest first. `open`: clicking it opens something; `quiet`: put
   * back in the history without counting as new (a saved newspaper, on load).
   */
  add(title: string, body: string, at: string, icon = '', accent = '', group?: string, img?: string | (() => string), open?: () => void, quiet = false, tip?: string): void {
    this.list.unshift({ id: this.nextId++, title, body, icon, at, accent, group, ...(img ? { img } : {}), ...(open ? { open } : {}), ...(tip ? { tip } : {}) });
    if (this.list.length > LOG_MAX) this.list.length = LOG_MAX;
    if (!this.open) { if (!quiet) { if (group) this.unreadGroups.add(group); else this.unreadSingles++; } }
    else this.render();
  }

  /** Open the log out, its pill up over it (a click on a card at the top that opens nothing of its own). */
  openShelf(): void {
    if (!this.list.length) return;
    if (this.pill.hidden) { this.pill.hidden = false; this.label(); }
    this.toggle(true);
  }

  /** Dress the newest entry: a deed's icon and its tier's colour. */
  tagLast(icon: string, accent: string): void {
    const e = this.list[0];
    if (!e) return;
    e.icon = icon;
    e.accent = accent;
    if (this.open) this.render();
  }

  /**
   * Whether the card is up now (the pill steps aside for it) — called as a card goes up and after it has folded away, so the
   * pill appears as the card folds away, with a little bump.
   */
  sync(cardUp: boolean): void {
    const show = !cardUp && this.list.length > 0;
    if (show === !this.pill.hidden) {
      if (show) this.label();
      return;
    }
    this.pill.hidden = !show;
    if (show) {
      this.label();
      this.pill.classList.remove('bump');
      void this.pill.offsetWidth; // restart the animation
      this.pill.classList.add('bump');
    } else if (this.open) this.toggle(false);
  }

  /** Clear everything (a new game, a load). */
  clear(): void {
    this.list = [];
    this.expanded.clear();
    this.markRead();
    this.toggle(false);
    this.pill.hidden = true;
  }

  private label(): void {
    const text = `<span class="np-ico">🔔</span>${this.unread ? `<b>${this.unread > 99 ? '99+' : this.unread}</b>` : ''}<span class="np-t">${esc(this.list[0]?.title ?? '')}</span>`;
    if (this.pill.dataset.k !== text) { this.pill.dataset.k = text; this.pill.innerHTML = text; }
  }

  private toggle(on = !this.open): void {
    this.open = on;
    this.panel.hidden = !on;
    this.pill.classList.toggle('on', on);
    if (on) { this.markRead(); this.render(); this.label(); }
  }

  /**
   * The log, newest first. Notifications from one source stack where the newest of them falls, as a
   * phone does: the newest shown, a count of the rest; clicked, the stack opens out under its name.
   */
  private render(): void {
    // an entry that opens something: the newspaper (dark-edged), or an achievement's page of the Passport (its own edge);
    // hovered, its tip (an achievement's description) or simply that it opens
    const item = (e: Entry, cls = '') =>
      `<li class="${cls}${e.open ? (e.tip ? ' nl-link' : ' nl-open') : ''}"${e.open ? ` data-open="${e.id}"` : ''}${e.tip || e.open ? ` title="${esc(e.tip ?? 'Click to open')}"` : ''} style="${e.accent ? `--accent:${e.accent}` : ''}">${mark(e)}<div><b>${esc(e.title)}</b>${e.body ? `<span>${esc(e.body)}</span>` : ''}</div><time>${esc(e.at)}</time></li>`;
    const done = new Set<string>();
    const out: string[] = [];
    for (const e of this.list) {
      if (!e.group) { out.push(item(e)); continue; }
      if (done.has(e.group)) continue;
      done.add(e.group);
      const all = this.list.filter((q) => q.group === e.group);
      if (all.length === 1) { out.push(item(e)); continue; }
      const g = esc(e.group);
      if (this.expanded.has(e.group)) {
        out.push(`<li class="nl-gh" data-grp="${g}"><div><b>${g}</b></div><em>${all.length} · show less</em></li>`);
        for (const q of all) out.push(item(q, 'in-grp'));
      } else {
        out.push(`<li class="nl-stack" data-grp="${g}"${e.tip ? ` title="${esc(e.tip)}"` : ''} style="${e.accent ? `--accent:${e.accent}` : ''}">${mark(e)}<div><b>${esc(e.title)}</b>${e.body ? `<span>${esc(e.body)}</span>` : ''}<small>${all.length - 1} more from ${g}</small></div><time>${esc(e.at)}</time></li>`);
      }
    }
    this.panel.innerHTML = `<div class="nl-h">Recent notifications<span>${this.list.length} of the last ${LOG_MAX}</span></div><ol>${out.join('')}</ol>`;
  }
}
