import * as THREE from 'three';
import type { World } from '../world/tiles';
import { countyName, eventsNear, type Happening } from './events/calendar';
import type { EventParticles } from '../render/eventParticles';
import { MeteorMarks, type Mark } from '../render/meteorMarks';
import { METEOR, fallsOf, type Fall } from './meteorites';
import type { Culture } from './culture';

/**
 * Meteorites on the ground (game/meteorites.ts): once a second, the meteor showers round the player that have
 * started and whose day is not over; each stone that has come down is put out as a Visitors good for the home
 * town (game/culture.ts), its crater drawn, and a stone coming down near the camera is seen falling.
 */

interface FindsHost {
  scene: THREE.Object3D;
  seed(): string;
  /** Game hours: days × 24 + hour. */
  hours(): number;
  worldAt(cx: number, cz: number): World | null;
  /** The county the player is in, or null off play. */
  county(): { cx: number; cz: number } | null;
  /** Where the shower was held (world tiles), or null when its county had nowhere for it. */
  where(e: Happening, w: World): { x: number; z: number } | null;
  /** Ground height at a tile of a county. */
  ground(w: World, lx: number, lz: number): number;
  night(): number;
  /** The events' particles, when quality allows them. */
  particles(): EventParticles | null;
  culture: Culture;
}

export class MeteorFinds {
  private marks: MeteorMarks;
  private falls = new Map<string, Fall[]>();
  private scanT = 0;
  private last = -1;
  private shown: Mark[] = [];

  constructor(private host: FindsHost) {
    this.marks = new MeteorMarks(host.scene);
  }

  /** The showers within a county of the player whose stones are down or coming. */
  showers(): Happening[] {
    const c = this.host.county();
    const seed = this.host.seed();
    if (!c || !seed) return [];
    const now = this.host.hours(), day = Math.floor(now / 24);
    return eventsNear(seed, c.cx, c.cz, 1, day - 2, day + 1).filter((e) => e.kind === 'meteorShower' && now >= e.start && now < e.end + METEOR.keep);
  }

  /** A shower's stones, worked out once its county is in memory; null until then. */
  stones(e: Happening): Fall[] | null {
    let f = this.falls.get(e.id);
    if (f) return f;
    const w = this.host.worldAt(e.cx, e.cz);
    if (!w) return null;
    const mid = this.host.where(e, w);
    f = mid ? fallsOf(e, w, mid) : [];
    if (this.falls.size > 40) this.falls.clear();
    this.falls.set(e.id, f);
    return f;
  }

  update(dt: number): void {
    this.scanT -= dt;
    if (this.scanT <= 0) { this.scanT = 1; this.scan(); }
    // the embers flicker between scans
    if (this.shown.length) this.marks.set(this.shown, this.host.night());
  }

  private scan(): void {
    const now = this.host.hours(), was = this.last;
    this.last = now;
    const out: Mark[] = [];
    const culture = this.host.culture;
    for (const e of this.showers()) {
      const list = this.stones(e);
      const w = this.host.worldAt(e.cx, e.cz);
      if (!list || !w) continue;
      for (const f of list) {
        if (now < f.t || now >= f.until) continue;
        const y = this.host.ground(w, f.x - w.ox, f.z - w.oz);
        culture.fall(f.id, f.n === 0, f.until, { cx: f.cx, cz: f.cz, x: f.x, z: f.z, y, name: `the meteor shower over ${countyName(this.host.seed(), e.cx, e.cz)}` });
        // seen coming down: only as it happens, not when the clock is moved past it
        if (was >= 0 && was < f.t && now - f.t < 0.25) this.streak(f.x, y, f.z);
        out.push({ x: f.x, y, z: f.z, heat: Math.max(0, 1 - (now - f.t) / (f.until - f.t)), stone: culture.waiting.some((c) => c.stone === f.id) });
      }
    }
    culture.prune();
    this.shown = out;
    this.marks.set(out, this.host.night());
  }

  /** A stone coming down: a bright streak in from the sky, and a burst of sparks where it hits. */
  private streak(x: number, y: number, z: number): void {
    const p = this.host.particles();
    if (!p) return;
    const head = Math.random() * Math.PI * 2, T = 0.55;
    const sx = x - Math.sin(head) * 14, sz = z - Math.cos(head) * 14, sy = y + 20;
    const vx = (x - sx) / T, vy = (y - sy) / T, vz = (z - sz) / T;
    for (let k = 0; k < 16; k++) p.spark({ x: sx - vx * k * 0.01, y: sy - vy * k * 0.01, z: sz - vz * k * 0.01, vx, vy, vz, life: T - k * 0.015, colour: k < 3 ? 0xffffff : k < 8 ? 0xffd27a : 0xff7a2a, size: 0.3 - k * 0.012, gravity: 0, drag: 0 });
    setTimeout(() => {
      for (let k = 0; k < 26; k++) {
        const a = Math.random() * Math.PI * 2, s = 2 + Math.random() * 4;
        p.spark({ x, y: y + 0.2, z, vx: Math.cos(a) * s, vy: 3 + Math.random() * 5, vz: Math.sin(a) * s, life: 0.5 + Math.random() * 0.6, colour: k % 3 ? 0xff9a3a : 0xfff0c0, size: 0.14, gravity: 14, drag: 0.6 });
      }
    }, T * 1000);
  }

  /** The console (pr.meteors): the showers round the player and their stones. */
  console() {
    return {
      list: () => this.showers().map((e) => ({ id: e.id, cx: e.cx, cz: e.cz, start: e.start, end: e.end, stones: (this.stones(e) ?? []).map((f) => ({ id: f.id, x: Math.round(f.x), z: Math.round(f.z), t: +f.t.toFixed(2), down: this.host.hours() >= f.t })) })),
      waiting: () => this.host.culture.waiting.filter((c) => c.stone).map((c) => ({ id: c.id, stone: c.stone, good: c.good.name, weight: c.weight, x: Math.round(c.x), z: Math.round(c.z), until: c.until })),
    };
  }
}
