import { hex, scale, type RGB } from '../../world/biomes';
import type { EnergyKind, SupplyKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import type { Sched } from '../nightLights';
import {
  BRICK, CARS, COOL_GLOW, DARK, GLASS, GLASS_LIGHT, METAL, RED_LIGHT, ROOF_GREY, TAU, TRUNK, WARM_GLOW, WATER, WHITE,
  pick, type Draw, type Kit, type P3 } from './kit';

/**
 * Heavy industry and power: a refinery, a steel mill, a cotton mill, a paper mill, a cement works, a
 * container yard and a car factory, and the four clean power stations (sun, offshore wind, tide and
 * pumped water). Each is told from the others by its outline long before its detail.
 */

const RUST = hex(0x8a4f32), STEEL = hex(0x9aa0a6), CONCRETE = hex(0xb9b3a8), YELLOW = hex(0xf2b33b);
const ORANGE = hex(0xff8a2a), FLAME = hex(0xff6a1a), RED_DAY = hex(0x882222), LAMP_DAY = hex(0xe8e4d4);
const ALL_NIGHT: Sched = [17, 30, 2.4];

/** A round pipe or drum from a to b: the kit's bar is square, and a tank on its side must not be. */
function tube(k: Kit, a: P3, b: P3, r: number, col: RGB, seg = 8, cap: RGB = col): void {
  const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
  const len = Math.hypot(dx, dy, dz);
  if (len < 1e-5) return;
  const ux = dx / len, uy = dy / len, uz = dz / len;
  let px = -uz, py = 0, pz = ux;
  let pl = Math.hypot(px, py, pz);
  if (pl < 1e-4) { px = 1; py = 0; pz = 0; pl = 1; }
  px /= pl; py /= pl; pz /= pl;
  const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px;
  const ring = (t: number, i: number): P3 => {
    const an = (i / seg) * TAU, c = Math.cos(an) * r, s = Math.sin(an) * r;
    return [a[0] + dx * t + px * c + qx * s, a[1] + dy * t + py * c + qy * s, a[2] + dz * t + pz * c + qz * s];
  };
  const mid: P3 = [a[0] + dx / 2, a[1] + dy / 2, a[2] + dz / 2];
  for (let i = 0; i < seg; i++) {
    k.quad(ring(0, i), ring(0, i + 1), ring(1, i + 1), ring(1, i), col, mid);
    k.tri(a, ring(0, i), ring(0, i + 1), cap, mid);
    k.tri(b, ring(1, i), ring(1, i + 1), cap, mid);
  }
}

/** A whole sphere centred on (x, y, z): a gas sphere, a lamp globe. */
function ball(k: Kit, x: number, y: number, z: number, R: number, col: RGB, seg = 8, rings = 3): void {
  k.dome(x, y, z, R, col, seg, rings);
  const I: P3 = [x, y, z], under = scale(col, 0.8);
  for (let j = 0; j < rings; j++) {
    const p0 = (j / rings) * Math.PI / 2, p1 = ((j + 1) / rings) * Math.PI / 2;
    const r0 = Math.cos(p0) * R, r1 = Math.cos(p1) * R, y0 = y - Math.sin(p0) * R, y1 = y - Math.sin(p1) * R;
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
      k.quad([x + Math.cos(a0) * r0, y0, z + Math.sin(a0) * r0], [x + Math.cos(a1) * r0, y0, z + Math.sin(a1) * r0],
        [x + Math.cos(a1) * r1, y1, z + Math.sin(a1) * r1], [x + Math.cos(a0) * r1, y1, z + Math.sin(a0) * r1], under, I);
    }
  }
}

/**
 * A sawtooth (north-light) roof over a w×d base: n teeth, each a long slope up to a glazed upright
 * face. The teeth march along z with the glass facing the front, or along x with it facing +x.
 */
function sawtooth(k: Kit, x: number, y: number, z: number, w: number, d: number, n: number, h: number, roof: RGB, end: RGB, alongX: boolean, s: Sched, g: RGB): void {
  const L = alongX ? w : d, Wd = alongX ? d : w, step = L / n;
  const at = (u: number, v: number, yy: number): P3 => alongX ? [x + u, yy, z + v] : [x + v, yy, z + u];
  for (let i = 0; i < n; i++) {
    const u0 = -L / 2 + i * step, u1 = u0 + step;
    const I = at(u0 + step * 0.7, 0, y + h * 0.2);
    k.quad(at(u0, -Wd / 2, y), at(u0, Wd / 2, y), at(u1, Wd / 2, y + h), at(u1, -Wd / 2, y + h), roof, I);
    k.quad(at(u1, -Wd / 2, y), at(u1, Wd / 2, y), at(u1, Wd / 2, y + h), at(u1, -Wd / 2, y + h), end, I);
    k.tri(at(u0, -Wd / 2, y), at(u1, -Wd / 2, y), at(u1, -Wd / 2, y + h), end, I);
    k.tri(at(u0, Wd / 2, y), at(u1, Wd / 2, y), at(u1, Wd / 2, y + h), end, I);
    const p = at(u1, 0, y + h * 0.18);
    k.pane(p[0], p[1], p[2], Wd * 0.92, h * 0.7, alongX ? 0 : 1, GLASS_LIGHT, s, g);
  }
}

/** A small warning or work light. */
function lamp(k: Kit, x: number, y: number, z: number, red = true, size = 0.05): void {
  k.glowBox(x, y, z, size, size, size, red ? RED_DAY : LAMP_DAY, ALL_NIGHT, red ? RED_LIGHT : COOL_GLOW);
}

/** Steam standing over a stack. */
function steam(k: Kit, x: number, y: number, z: number, R: number, dx = 0.12): void {
  for (let i = 0; i < 3; i++) ball(k, x + i * dx, y + R * 0.6 + i * R * 0.9, z, R * (1 - i * 0.16), WHITE, 7, 2);
}

/** A tapering round chimney with a corbelled rim. Returns its top. */
function chimney(k: Kit, x: number, z: number, r0: number, r1: number, H: number, col: RGB): number {
  k.band(x, z, 0, r0, H * 0.5, (r0 + r1) / 2, 10, col);
  k.band(x, z, H * 0.5, (r0 + r1) / 2, H - 0.12, r1, 10, scale(col, 0.96));
  k.band(x, z, H - 0.12, r1, H - 0.06, r1 + 0.035, 10, scale(col, 0.85));
  k.cyl(x, H - 0.06, z, r1 + 0.035, 0.06, scale(col, 0.85), 10, hex(0x2a2624));
  return H;
}

/** A lorry cab and its flat chassis, lying along x with the cab at the +x end. */
function lorryCab(k: Kit, x: number, z: number, len: number, col: RGB): void {
  k.box(x + len / 2 - 0.1, 0.03, z, 0.2, 0.2, 0.22, col, scale(col, 0.85));
  k.box(x + len / 2 - 0.05, 0.13, z, 0.11, 0.08, 0.225, GLASS_LIGHT);
  k.box(x - 0.1, 0.05, z, len - 0.2, 0.05, 0.2, DARK);
  for (const wx of [-len / 2 + 0.12, -len / 2 + 0.26, len / 2 - 0.12]) k.box(x + wx, 0, z, 0.1, 0.08, 0.24, hex(0x24262a));
}

// ---- refinery ----------------------------------------------------------------------------------

/**
 * An oil refinery: a stand of distillation columns ringed with platforms, pipe racks on trestles,
 * floating-roof tanks and gas spheres, and a flare stack burning day and night.
 */
const refinery: Draw = (k, W, D, b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const silver = hex(0xc4c9cc), deck = hex(0x5a5f66);
  // the distillation columns, each on a concrete skirt with platform rings and a ladder
  const cols: [number, number, number, number][] = [
    [bx + 0.55, bz + 0.6, 0.17, 3.0], [bx + 1.2, bz + 0.85, 0.2, 2.15], [bx + 1.85, bz + 0.55, 0.14, 2.6], [bx + 2.45, bz + 0.85, 0.18, 1.65],
  ];
  cols.forEach(([x, z, rr, h], i) => {
    const col = i % 2 ? scale(WHITE, 0.95) : silver;
    k.cyl(x, 0, z, rr + 0.05, 0.14, CONCRETE, 8);
    k.cyl(x, 0.14, z, rr, h - 0.14, col, 8);
    k.dome(x, h, z, rr, scale(col, 0.95), 8, 2);
    for (const f of h > 2.4 ? [0.34, 0.6, 0.86] : [0.45, 0.86]) k.cyl(x, h * f, z, rr + 0.09, 0.03, deck, 8);
    lamp(k, x, h * 0.86 + 0.04, z + rr + 0.07, false, 0.04);
    k.bar([x + rr + 0.02, 0.14, z + 0.04], [x + rr + 0.02, h * 0.86, z + 0.04], 0.014, YELLOW);
    // the overhead vapour line, off the top and down to the rack
    k.bar([x, h + rr * 0.5, z], [x - rr - 0.08, h + rr + 0.06, z], 0.03, STEEL);
    k.bar([x - rr - 0.08, h + rr + 0.06, z], [x - rr - 0.08, 0.5, z], 0.025, STEEL);
    lamp(k, x, h + rr + 0.1, z, true);
  });
  // the pipe racks: one along the columns, one across to the tanks, pipes two tiers deep
  const rz = bz + 1.5, rx = 0.05, pipes = [silver, RUST, WHITE, YELLOW];
  for (let x = bx + 0.3; x <= rx + 0.01; x += 0.9) {
    for (const s of [-1, 1]) k.box(x, 0, rz + s * 0.14, 0.04, 0.64, 0.04, deck);
    k.box(x, 0.44, rz, 0.04, 0.03, 0.32, deck);
  }
  pipes.forEach((c, i) => k.bar([bx + 0.2, 0.49, rz - 0.1 + i * 0.066], [rx + 0.1, 0.49, rz - 0.1 + i * 0.066], 0.02, c));
  for (const s of [-1, 1]) k.bar([bx + 0.2, 0.67, rz + s * 0.06], [rx + 0.1, 0.67, rz + s * 0.06], 0.025, s > 0 ? silver : hex(0x4f7a5a));
  for (let z = bz + 0.4; z <= 0.75; z += 0.7) {
    for (const s of [-1, 1]) k.box(rx + s * 0.14, 0, z, 0.04, 0.58, 0.04, deck);
    k.box(rx, 0.52, z, 0.32, 0.03, 0.04, deck);
  }
  pipes.forEach((c, i) => k.bar([rx - 0.1 + i * 0.066, 0.57, bz + 0.3], [rx - 0.1 + i * 0.066, 0.57, 0.8], 0.02, c));
  for (const [x, z, rr] of cols) k.bar([x, 0.45, z + rr], [x, 0.45, rz], 0.022, STEEL);
  // a fired heater with its stack, and two drums on saddles, in the crook of the racks
  k.box(bx + 1.0, 0, rz + 0.62, 0.5, 0.55, 0.45, RUST, scale(RUST, 0.8));
  k.cyl(bx + 1.0, 0.55, rz + 0.62, 0.07, 0.95, silver, 8, DARK);
  for (const x of [bx + 1.75, bx + 2.45]) {
    for (const s of [-1, 1]) k.box(x + s * 0.18, 0, rz + 0.6, 0.06, 0.12, 0.18, CONCRETE);
    tube(k, [x - 0.3, 0.22, rz + 0.6], [x + 0.3, 0.22, rz + 0.6], 0.11, silver, 8);
  }
  // two floating-roof tanks: the shell stands above the roof, which rides on the oil inside
  const tank = (x: number, z: number, R: number, h: number, stair: boolean) => {
    k.band(x, z, 0, R, h, R, 12, WHITE, scale(WHITE, 0.62));
    k.band(x, z, h * 0.42, R + 0.006, h * 0.54, R + 0.006, 12, hex(0x2f7fb5));
    k.cyl(x, h * 0.7, z, R * 0.98, h * 0.04, hex(0xa9aeb2), 12, hex(0xc3c7c9));
    k.cyl(x, h * 0.74, z, R * 0.18, 0.03, deck, 6);
    if (stair) {
      let prev: P3 = [x + R + 0.04, 0, z];
      for (let s = 1; s <= 4; s++) {
        const a = (s / 4) * TAU * 0.3, p: P3 = [x + Math.cos(a) * (R + 0.04), (h * s) / 4, z + Math.sin(a) * (R + 0.04)];
        k.bar(prev, p, 0.016, YELLOW);
        prev = p;
      }
    }
    lamp(k, x, h + 0.01, z + R, false, 0.04);
  };
  tank(W / 2 - 0.75, bz + 0.8, 0.6, 0.62, true);
  tank(W / 2 - 2.1, bz + 0.8, 0.6, 0.5, false);
  // gas spheres on their legs
  for (const x of [0.85, 1.6]) {
    const z = 0.0, R = 0.3, cy = 0.44;
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + 0.785;
      k.bar([x + Math.cos(a) * R * 0.9, 0, z + Math.sin(a) * R * 0.9], [x + Math.cos(a) * R * 0.9, cy, z + Math.sin(a) * R * 0.9], 0.025, deck);
    }
    ball(k, x, cy, z, R, WHITE, 8, 3);
    k.cyl(x, cy + R - 0.02, z, 0.07, 0.04, deck, 6);
    lamp(k, x, cy + R + 0.02, z, true, 0.04);
  }
  // the flare stack, guyed by three legs, burning off gas
  const fx = W / 2 - 0.4, fz = 0.15, fh = 3.2;
  k.bar([fx, 0, fz], [fx, fh, fz], 0.035, STEEL);
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * TAU + 0.5;
    k.bar([fx + Math.cos(a) * 0.3, 0, fz + Math.sin(a) * 0.3], [fx, fh * 0.55, fz], 0.018, STEEL);
  }
  k.cyl(fx, fh, fz, 0.06, 0.08, DARK, 6);
  k.cone(fx, fh + 0.06, fz, 0.1, 0.34, ORANGE, 6);
  k.glowBox(fx, fh + 0.08, fz, 0.09, 0.2, 0.09, ORANGE, [0, 30, 2.5], FLAME);
  // the control building, at the front corner by the gate
  const cx = bx + 1.0, cz = 0.55;
  k.box(cx, 0, cz, 1.3, 0.34, 0.6, hex(0xe6e2d6), hex(0x3f5a73));
  k.box(cx, 0.34, cz, 1.36, 0.04, 0.66, hex(0x3f5a73));
  for (let i = 0; i < 5; i++) k.pane(cx - 0.48 + i * 0.24, 0.12, cz + 0.3, 0.17, 0.14, 1, GLASS, [16.5 + r(), 30, 1.5], WARM_GLOW);
  k.box(cx + 0.5, 0, cz + 0.31, 0.12, 0.22, 0.02, DARK);
  void b;
};

// ---- steelworks --------------------------------------------------------------------------------

/**
 * A steel mill: the blast furnace with its skip incline and three domed stoves, a brick chimney, and
 * the long rolling-mill shed whose doorway glows with hot metal.
 */
const steelworks: Draw = (k, W, D, _b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const iron = hex(0x7a4632), soot = hex(0x4a4340), shed = hex(0x8f9a96), glowDay = hex(0xc8641e);
  const HOT: Sched = [0, 24, 2.2];
  // the cast house, and the furnace rising through its roof
  const fx = bx + 1.9, fz = bz + 1.45;
  k.box(fx, 0, fz, 1.25, 0.3, 1.2, hex(0x6b5a52), soot);
  k.glowBox(fx, 0.04, fz + 0.61, 0.4, 0.16, 0.02, glowDay, HOT, FLAME);
  const prof: [number, number][] = [[0.3, 0.4], [0.85, 0.5], [1.05, 0.5], [2.0, 0.32], [2.4, 0.2]];
  for (let i = 0; i < prof.length - 1; i++) k.band(fx, fz, prof[i][0], prof[i][1], prof[i + 1][0], prof[i + 1][1], 10, scale(iron, 1 - i * 0.05));
  k.cyl(fx, 2.4, fz, 0.2, 0.22, soot, 8);
  // the bustle pipe round the bosh, hoops up the stack, and the uptakes meeting over the top
  k.hoop(fx, 0.98, fz, 0.6, 0.045, soot, 10, 'xz');
  k.hoop(fx, 1.5, fz, 0.45, 0.025, soot, 10, 'xz');
  k.cyl(fx, 1.98, fz, 0.42, 0.03, soot, 10);
  for (const s of [-1, 1]) k.bar([fx + s * 0.16, 2.6, fz], [fx, 3.0, fz], 0.04, soot);
  const dcx = fx + 0.95, dcz = fz - 0.75;
  k.bar([fx, 3.0, fz], [dcx, 1.35, dcz], 0.05, soot);
  // the dust catcher the downcomer drops into
  k.cyl(dcx, 0.7, dcz, 0.2, 0.55, iron, 8);
  k.cone(dcx, 1.25, dcz, 0.2, 0.16, iron, 8);
  k.cone(dcx, 0.7, dcz, 0.2, -0.3, scale(iron, 0.85), 8);
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * TAU;
    k.bar([dcx + Math.cos(a) * 0.2, 0, dcz + Math.sin(a) * 0.2], [dcx + Math.cos(a) * 0.2, 0.75, dcz + Math.sin(a) * 0.2], 0.02, soot);
  }
  // the skip incline from the stock bins at the front up to the throat
  const sz = fz + 2.3;
  k.box(fx, 0, sz, 0.7, 0.26, 0.4, hex(0x6b5a52), soot);
  for (const s of [-1, 1]) k.bar([fx + s * 0.09, 0.2, sz], [fx + s * 0.09, 2.62, fz + 0.12], 0.028, soot);
  for (const t of [0.3, 0.62]) {
    const y = 0.2 + 2.42 * t, z = sz + (fz + 0.12 - sz) * t;
    if (t < 0.5) for (const s of [-1, 1]) k.bar([fx + s * 0.16, 0.3, z], [fx + s * 0.09, y, z], 0.022, soot);
    k.box(fx, y - 0.01, z, 0.26, 0.04, 0.05, soot);
  }
  k.box(fx, 0.2 + 2.42 * 0.45 + 0.03, sz + (fz + 0.12 - sz) * 0.45, 0.16, 0.12, 0.2, YELLOW);
  // three hot-blast stoves, domed, and the hot main back to the furnace
  for (let i = 0; i < 3; i++) {
    const x = bx + 0.4 + i * 0.54, z = bz + 0.38, R = 0.22, h = 1.75;
    k.cyl(x, 0, z, R, h, hex(0x8b8078), 10);
    k.dome(x, h, z, R, hex(0x766a62), 10, 3);
    k.cyl(x, h * 0.5, z, R + 0.012, 0.05, soot, 10);
    k.bar([x, 0.95, z + R], [x, 0.95, z + R + 0.12], 0.04, soot);
  }
  k.bar([bx + 0.3, 0.95, bz + 0.74], [fx - 0.2, 0.95, bz + 0.74], 0.045, soot);
  k.bar([fx - 0.2, 0.95, bz + 0.74], [fx - 0.3, 0.98, fz - 0.5], 0.045, soot);
  // the brick chimney
  const ct = chimney(k, bx + 0.42, bz + 1.5, 0.19, 0.1, 3.3, pick(r, BRICK));
  lamp(k, bx + 0.42, ct, bz + 1.5, true);
  lamp(k, fx, 3.04, fz, true);
  // the rolling mill: a long high shed with a monitor along its ridge
  const sw = W / 2 - 0.15, scx = sw / 2, sd = 2.1, scz = bz + 0.2 + sd / 2, sh = 0.8;
  k.box(scx, 0, scz, sw, sh, sd, shed, scale(shed, 0.8));
  k.gable(scx, sh, scz, sw, 0.3, sd, scale(shed, 0.72), shed);
  k.box(scx, sh + 0.14, scz, sw - 0.5, 0.26, 0.46, scale(shed, 0.95), scale(shed, 0.72));
  k.gable(scx, sh + 0.4, scz, sw - 0.5, 0.08, 0.5, scale(shed, 0.72), shed);
  for (let i = 0; i < 6; i++) {
    const x = scx - (sw - 0.9) / 2 + (i * (sw - 0.9)) / 5;
    for (const f of [1, 3]) k.pane(x, sh + 0.26, scz + (f === 1 ? 0.23 : -0.23), 0.3, 0.1, f, hex(0xa86a3a), [0, 24, 1.5], FLAME);
  }
  const fzF = scz + sd / 2;
  for (let i = 0; i < 5; i++) k.pane(scx - sw / 2 + 0.35 + i * 0.55, 0.52, fzF, 0.34, 0.14, 1, hex(0x8a7a5a), [0, 24, 1.2], ORANGE);
  // the great doorway, molten orange inside, and the rails running out of it
  const dx = scx - sw / 2 + 0.75;
  k.box(dx, 0, fzF + 0.015, 0.78, 0.5, 0.03, soot);
  k.glowBox(dx, 0.02, fzF + 0.03, 0.64, 0.42, 0.02, glowDay, HOT, FLAME);
  k.glowBox(scx - sw / 2 - 0.01, 0.02, scz, 0.02, 0.4, 0.6, glowDay, HOT, FLAME);
  const lz = fzF + 0.45;
  k.box(scx - 0.3, 0, lz, sw - 0.4, 0.02, 0.34, hex(0x6d6862));
  for (const s of [-1, 1]) k.bar([scx - sw / 2 - 0.1, 0.035, lz + s * 0.08], [scx + sw / 2 - 0.7, 0.035, lz + s * 0.08], 0.012, soot);
  // the ladle car, its ladle brim-full
  for (const x of [dx + 0.2, dx + 1.1]) {
    k.box(x, 0.04, lz, 0.42, 0.07, 0.26, soot);
    k.band(x, lz, 0.11, 0.1, 0.36, 0.15, 8, iron, scale(iron, 0.5));
    k.glowBox(x, 0.3, lz, 0.17, 0.02, 0.17, hex(0xe0782a), HOT, FLAME);
  }
  // the slag heap, off in the corner
  const hx = W / 2 - 0.65, hz = lz + 0.75;
  k.cone(hx, 0, hz, 0.5, 0.36, hex(0x55504d), 7);
  k.cone(hx - 0.45, 0, hz + 0.2, 0.3, 0.2, hex(0x625c58), 6);
  k.cone(hx + 0.1, 0, hz + 0.4, 0.26, 0.16, hex(0x4a4644), 6);
};

// ---- textile mill ------------------------------------------------------------------------------

/**
 * A Victorian cotton mill: four storeys of red brick and tall windows, a stair tower under a pyramid
 * cap, a round brick chimney, a north-light weaving shed and bales in the yard.
 */
const textileMill: Draw = (k, W, D, b, r) => {
  const bz = -D / 2;
  const brick = pick(r, BRICK), stone = hex(0xd8cfb8), slate = hex(0x5a5f6b);
  const floors = Math.max(4, Math.min(5, b.floors)), H = floors * FLOOR;
  const mw = W * 0.575, md = 0.95, mx = -W / 2 + 0.15 + mw / 2, mz = bz + 0.17 + md / 2;
  k.box(mx, 0, mz, mw, H, md, brick, ROOF_GREY);
  k.box(mx, H, mz, mw + 0.05, 0.05, md + 0.05, stone, ROOF_GREY);
  // long rows of tall windows, front and back, and up the gable end
  const n = Math.max(6, Math.round(mw / 0.26));
  for (let f = 0; f < floors; f++) {
    const y = f * FLOOR + 0.07, wh = FLOOR * 0.6;
    const s: Sched = [16.5 + r(), 21.5 + r() * 2, 1.4];
    for (let i = 0; i < n; i++) {
      const x = mx - mw / 2 + (mw * (i + 0.5)) / n;
      k.pane(x, y, mz + md / 2, (mw / n) * 0.6, wh, 1, GLASS, s, WARM_GLOW);
      k.pane(x, y, mz - md / 2, (mw / n) * 0.6, wh, 3, GLASS, s, WARM_GLOW);
    }
    for (let i = 0; i < 3; i++) k.pane(mx - mw / 2, y, mz - md / 2 + (md * (i + 0.5)) / 3, 0.16, wh, 2, GLASS, s, WARM_GLOW);
  }
  // the stair and water tower at the corner, under its pyramid cap
  const tx = mx + mw / 2 + 0.2, tz = mz + md / 2 - 0.17, th = H + 0.5;
  k.box(tx, 0, tz, 0.46, th, 0.46, scale(brick, 0.94));
  k.box(tx, th, tz, 0.54, 0.05, 0.54, stone);
  k.hip(tx, th + 0.05, tz, 0.54, 0.34, 0.54, slate);
  k.bar([tx, th + 0.36, tz], [tx, th + 0.56, tz], 0.012, DARK);
  for (let f = 0; f < floors; f++) k.pane(tx, f * FLOOR + 0.09, tz + 0.23, 0.12, FLOOR * 0.55, 1, GLASS, [17, 23, 1.3], WARM_GLOW);
  k.pane(tx, H + 0.16, tz + 0.23, 0.26, 0.2, 1, stone, [17, 30, 1.2], WARM_GLOW);
  k.box(tx, 0, tz + 0.24, 0.16, 0.2, 0.02, DARK);
  // the boiler house and the tall round chimney
  const hx = W / 2 - 0.75, hz = bz + 0.55;
  k.box(hx, 0, hz, 0.6, 0.4, 0.7, scale(brick, 0.9), slate);
  k.gable(hx, 0.4, hz, 0.6, 0.14, 0.7, slate, scale(brick, 0.9), true);
  const cx = W / 2 - 0.28, cz = bz + 0.42;
  k.box(cx, 0, cz, 0.4, 0.3, 0.4, scale(brick, 0.9), stone);
  chimney(k, cx, cz, 0.17, 0.095, 3.0, brick);
  // the weaving shed: low, under a sawtooth of north lights
  const sw = W / 2 - 0.15 - (mx + mw / 2) - 0.05, sx = W / 2 - 0.15 - sw / 2, sd = 1.05, szc = tz + 0.23 + 0.06 + sd / 2;
  k.box(sx, 0, szc, sw, 0.26, sd, brick, slate);
  sawtooth(k, sx, 0.26, szc, sw, sd, 4, 0.15, slate, scale(brick, 0.95), false, [16.5, 22.5, 1.5], WARM_GLOW);
  k.box(sx - sw / 4, 0, szc + sd / 2 + 0.01, 0.3, 0.2, 0.02, hex(0x3f5a4a));
  // the yard: cotton bales stacked for the carrier, and a name board over the door
  const bale = hex(0xe9e2cf), band = hex(0x8d6d48);
  for (let j = 0; j < 3; j++) {
    for (let i = 0; i < 4 - j; i++) {
      const x = -W / 2 + 0.45 + i * 0.28 + j * 0.14, z = szc - 0.1;
      k.box(x, j * 0.15, z, 0.24, 0.15, 0.36, bale, scale(bale, 0.95));
      k.box(x, j * 0.15 + 0.005, z, 0.245, 0.15, 0.04, band);
    }
  }
  for (let i = 0; i < 2; i++) k.box(-W / 2 + 0.5 + i * 0.3, 0, szc + 0.4, 0.24, 0.15, 0.3, bale, scale(bale, 0.95));
  k.box(mx, 0, mz + md / 2 + 0.012, 0.3, 0.22, 0.02, hex(0x3f5a4a));
  k.box(mx, H - 0.02, mz + md / 2 + 0.02, mw * 0.4, 0.09, 0.02, stone);
};

// ---- paper mill --------------------------------------------------------------------------------

/**
 * A pulp and paper mill: logs and a chip pile under a conveyor, the digester tower, the recovery
 * boiler and its steaming stack, the long machine hall, and white reels of paper on the dock.
 */
const paperMill: Draw = (k, W, D, _b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const wall = hex(0xcfd8d2), roof = hex(0x5f7a6e), chip = hex(0xd7b377), boiler = hex(0x9fb0b8);
  // the log deck along the back, and the chipper house it feeds
  for (let j = 0; j < 3; j++) {
    for (let i = 0; i < 4 - j; i++) {
      const z = bz + 0.3 + i * 0.13 + j * 0.065, y = 0.07 + j * 0.11;
      tube(k, [bx + 0.2 + j * 0.05, y, z], [bx + 1.25 - j * 0.05, y, z], 0.062, (i + j) % 2 ? TRUNK : scale(TRUNK, 1.1), 5, hex(0xd9b98a));
    }
  }
  const chx = bx + 1.6, chz = bz + 0.45;
  k.box(chx, 0, chz, 0.42, 0.36, 0.42, hex(0x8a7f6d), roof);
  // the chip pile, a tan cone, under the head of the inclined conveyor
  const px = bx + 0.8, pz = bz + 1.6;
  k.cone(px, 0, pz, 0.62, 0.6, chip, 10);
  k.cone(px + 0.5, 0, pz + 0.3, 0.3, 0.24, scale(chip, 0.94), 7);
  k.bar([chx, 0.34, chz + 0.1], [px, 0.86, pz], 0.05, hex(0x6b7076));
  k.box(px, 0.84, pz, 0.16, 0.12, 0.16, hex(0x6b7076));
  const mxc = (chx + px) / 2, mzc = (chz + 0.1 + pz) / 2;
  for (const s of [-1, 1]) k.bar([mxc + s * 0.12, 0, mzc + s * 0.08], [mxc, 0.58, mzc], 0.02, DARK);
  // the digester: a tall steel tower with platforms, and the blow tank beside it
  const dx = bx + 2.35, dz = bz + 0.55, dh = 2.2;
  k.cyl(dx, 0, dz, 0.22, dh, STEEL, 10);
  k.cone(dx, dh, dz, 0.22, 0.24, scale(STEEL, 0.9), 10);
  for (const f of [0.35, 0.65, 0.95]) k.cyl(dx, dh * f, dz, 0.3, 0.03, DARK, 10);
  k.bar([dx + 0.24, 0, dz + 0.05], [dx + 0.24, dh, dz + 0.05], 0.014, YELLOW);
  k.cyl(dx + 0.05, 0, dz + 0.55, 0.17, 0.8, scale(STEEL, 1.08), 8);
  k.cone(dx + 0.05, 0.8, dz + 0.55, 0.17, 0.12, STEEL, 8);
  k.bar([dx, dh * 0.6, dz + 0.2], [dx + 0.05, 0.9, dz + 0.55], 0.03, hex(0x6b7076));
  lamp(k, dx, dh + 0.24, dz, true);
  // the recovery boiler: the biggest block on the site, with its stack trailing white steam
  const rx = bx + 3.45, rzc = bz + 0.7;
  k.box(rx, 0, rzc, 1.0, 1.5, 1.0, boiler, scale(boiler, 0.75));
  k.box(rx, 1.5, rzc, 0.6, 0.16, 0.6, scale(boiler, 0.9), scale(boiler, 0.7));
  for (let i = 0; i < 3; i++) k.pane(rx - 0.3 + i * 0.3, 1.1, rzc + 0.5, 0.18, 0.2, 1, GLASS, [0, 30, 1.3], WARM_GLOW);
  k.box(rx, 0.55, rzc + 0.505, 1.0, 0.04, 0.02, scale(boiler, 0.7));
  const skx = W / 2 - 0.35, skz = bz + 0.4;
  k.band(skx, skz, 0, 0.13, 2.7, 0.09, 8, hex(0xd9dcd8));
  k.band(skx, skz, 2.3, 0.118, 2.5, 0.108, 8, hex(0xe2412f));
  k.cyl(skx, 2.69, skz, 0.088, 0.012, DARK, 8);
  k.bar([rx + 0.5, 0.5, rzc - 0.2], [skx, 0.5, skz], 0.06, hex(0x6b7076));
  steam(k, skx, 2.7, skz, 0.2, 0.14);
  lamp(k, skx, 2.6, skz + 0.11, true);
  // the machine hall: long and low, vents along the ridge
  const mw = 3.3, mcx = W / 2 - 0.2 - mw / 2, md = 0.8, mcz = bz + 1.75, mh = 0.45;
  k.box(mcx, 0, mcz, mw, mh, md, wall, roof);
  k.gable(mcx, mh, mcz, mw, 0.17, md, roof, wall);
  for (let i = 0; i < 4; i++) {
    const x = mcx - mw / 2 + 0.5 + i * ((mw - 1) / 3);
    k.box(x, mh + 0.1, mcz, 0.16, 0.12, 0.16, METAL, DARK);
  }
  for (let i = 0; i < 9; i++) k.pane(mcx - mw / 2 + 0.25 + i * ((mw - 0.5) / 8), 0.24, mcz + md / 2, 0.2, 0.12, 1, GLASS, [0, 30, 1.3], WARM_GLOW);
  for (let i = 0; i < 9; i++) k.pane(mcx - mw / 2 + 0.25 + i * ((mw - 0.5) / 8), 0.24, mcz - md / 2, 0.2, 0.12, 3, GLASS, [0, 30, 1.3], WARM_GLOW);
  // the loading dock along its front, stacked with reels
  const dkz = mcz + md / 2 + 0.26, dkw = mw - 0.5;
  k.box(mcx, 0, dkz, dkw, 0.08, 0.5, CONCRETE, scale(CONCRETE, 1.06));
  for (let i = 0; i < 3; i++) k.box(mcx - dkw / 2 + 0.5 + i * 0.9, 0, mcz + md / 2 + 0.012, 0.4, 0.34, 0.02, hex(0x4a5a54));
  const core = hex(0xb08a5a);
  const reel = (x: number, y: number, z: number, R: number) => {
    k.cyl(x, y, z, R, 0.2, WHITE, 8, scale(WHITE, 0.97));
    k.cyl(x, y + 0.2, z, R * 0.3, 0.008, core, 6);
  };
  for (let i = 0; i < 8; i++) {
    const x = mcx - dkw / 2 + 0.2 + i * ((dkw - 0.4) / 7), z = dkz + 0.06 + (i % 2) * 0.03;
    const R = 0.12 + (r() < 0.4 ? 0.02 : 0);
    reel(x, 0.08, z, R);
    if (i % 3 !== 1) reel(x, 0.288, z, R * 0.95);
  }
  // two lying on their sides at the end, ready to roll onto a lorry
  for (const s of [0, 1]) tube(k, [mcx + dkw / 2 + 0.06, 0.13, dkz - 0.12 + s * 0.29], [mcx + dkw / 2 + 0.3, 0.13, dkz - 0.12 + s * 0.29], 0.13, WHITE, 8, core);
};

// ---- cement plant ------------------------------------------------------------------------------

/**
 * A cement works: the open preheater tower of stacked cyclones, the long rotary kiln turning on its
 * piers, concrete silos, a domed clinker store and a bulk tanker under the spout, all under pale dust.
 */
const cementPlant: Draw = (k, W, D, _b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const dust = hex(0xcfcdc6), frame = hex(0x7d8790), kilnCol = hex(0x8a756a), cyc = hex(0xb7b2a8);
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, dust);
  // the preheater tower: an open steel frame, a cyclone on each deck, staggered, and the riser behind
  const px = bx + 0.65, pz = bz + 0.75, half = 0.33, PH = 3.2;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([px + sx * half, 0, pz + sz * half], [px + sx * half, PH, pz + sz * half], 0.03, frame);
  const decks = [0.7, 1.3, 1.9, 2.5, 3.1];
  decks.forEach((y, i) => {
    k.box(px, y, pz, half * 2 + 0.1, 0.04, half * 2 + 0.1, scale(frame, 0.8));
    if (i < decks.length - 1) {
      const ox = (i % 2 ? 1 : -1) * 0.12;
      k.cyl(px + ox, y + 0.3, pz + 0.06, 0.15, 0.24, cyc, 8);
      k.cone(px + ox, y + 0.3, pz + 0.06, 0.15, -0.24, scale(cyc, 0.88), 8);
      k.bar([px - half, y + 0.04, pz + half], [px + half, y + 0.56, pz + half], 0.012, frame);
    }
  });
  k.box(px, 0.7, pz - 0.2, 0.16, PH - 0.7, 0.16, scale(cyc, 0.92));
  k.box(px, PH + 0.04, pz, 0.3, 0.14, 0.3, cyc, scale(frame, 0.8));
  k.cyl(px, 0.3, pz, 0.2, 0.4, cyc, 8);
  lamp(k, px, PH + 0.18, pz, true);
  for (const y of [1.3, 2.5]) lamp(k, px + half, y + 0.06, pz + half, false, 0.04);
  // the kiln: a long drum on three piers, turning slowly, from the tower's foot to the firing hood
  const ky = 0.5, kx0 = px + 0.2, kx1 = W / 2 - 1.35, kmx = (kx0 + kx1) / 2, kl = kx1 - kx0;
  for (const f of [0.18, 0.5, 0.82]) {
    const x = kx0 + kl * f;
    k.box(x, 0, pz, 0.24, ky - 0.17, 0.4, CONCRETE);
    for (const s of [-1, 1]) k.box(x, ky - 0.17, pz + s * 0.12, 0.1, 0.06, 0.08, DARK);
  }
  k.spin(kmx, ky, pz, 'x', 0.5, (s) => {
    tube(s, [-kl / 2, 0, 0], [kl / 2, 0, 0], 0.13, kilnCol, 8);
    for (const f of [0.18, 0.5, 0.82]) tube(s, [-kl / 2 + kl * f - 0.04, 0, 0], [-kl / 2 + kl * f + 0.04, 0, 0], 0.16, hex(0xa9a49c), 8);
    // the girth gear, toothed, so the turning shows
    const gx = -kl / 2 + kl * 0.6;
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU;
      s.bar([gx, Math.cos(a) * 0.12, Math.sin(a) * 0.12], [gx, Math.cos(a) * 0.2, Math.sin(a) * 0.2], 0.03, DARK);
    }
    // patches of scale on the shell
    for (let i = 0; i < 4; i++) {
      const a = i * 1.9, x = -kl / 2 + kl * (0.1 + i * 0.22);
      s.bar([x, Math.cos(a) * 0.1, Math.sin(a) * 0.1], [x + 0.22, Math.cos(a) * 0.1, Math.sin(a) * 0.1], 0.04, scale(kilnCol, 0.8));
    }
  });
  // the firing hood and the clinker cooler, with its own short stack
  const hx = kx1 + 0.2;
  k.box(hx, 0, pz, 0.46, 0.8, 0.5, hex(0x8f8a84), scale(frame, 0.8));
  k.glowBox(hx - 0.235, 0.42, pz, 0.01, 0.16, 0.16, hex(0xc8641e), [0, 24, 2], FLAME);
  k.box(hx + 0.55, 0, pz, 0.64, 0.36, 0.5, hex(0x9d978f), scale(frame, 0.8));
  k.cyl(hx + 0.7, 0.36, pz - 0.1, 0.06, 1.1, cyc, 6, DARK);
  // the blending silo and main stack behind the kiln
  k.cyl(bx + 1.75, 0, bz + 0.33, 0.2, 1.3, CONCRETE, 8, scale(CONCRETE, 0.9));
  k.band(bx + 2.3, bz + 0.3, 0, 0.1, 2.4, 0.065, 8, hex(0xd8d6d0));
  k.cyl(bx + 2.3, 2.39, bz + 0.3, 0.064, 0.012, DARK, 8);
  lamp(k, bx + 2.3, 2.42, bz + 0.3, true, 0.04);
  // the clinker store: a low ring wall under a dome
  const cx = W / 2 - 0.75, cz = bz + 1.85, cr = 0.56;
  k.cyl(cx, 0, cz, cr, 0.14, CONCRETE, 12);
  k.dome(cx, 0.14, cz, cr, hex(0xc4c0b6), 12, 3);
  k.box(cx, 0.14 + cr - 0.03, cz, 0.16, 0.12, 0.16, frame);
  k.bar([hx + 0.55, 0.36, pz + 0.1], [cx, 0.14 + cr + 0.04, cz], 0.045, frame);
  // the cement silos in a row, a gallery across their heads, and the conveyor up from the clinker store
  const sz0 = bz + 1.8, sr = 0.24, sh = 1.5, sx0 = bx + 1.35;
  for (let i = 0; i < 4; i++) {
    k.cyl(sx0 + i * 0.49, 0, sz0, sr, sh, hex(0xbdb9b0), 10, scale(CONCRETE, 0.92));
    k.cyl(sx0 + i * 0.49, sh * 0.62, sz0, sr + 0.008, 0.035, hex(0xa6a198), 10);
  }
  k.box(sx0 + 0.735, sh, sz0, 1.9, 0.17, 0.3, scale(frame, 1.1), scale(frame, 0.8));
  for (let i = 0; i < 4; i++) k.pane(sx0 + i * 0.49, sh + 0.05, sz0 + 0.15, 0.2, 0.07, 1, GLASS, [17, 30, 1.4], WARM_GLOW);
  const gx1 = sx0 + 1.47 + 0.2;
  k.bar([cx, 0.14 + cr + 0.08, cz], [gx1, sh + 0.1, sz0], 0.07, scale(frame, 1.1));
  const tmx = (cx + gx1) / 2, tmy = (0.14 + cr + 0.08 + sh + 0.1) / 2;
  for (const s of [-1, 1]) k.bar([tmx + s * 0.12, 0, sz0 + 0.02], [tmx, tmy, (cz + sz0) / 2], 0.02, frame);
  // the loading bay out from the silos' feet, and a bulk tanker under its spout
  const lx = sx0 + 0.49, lz = sz0 + sr + 0.34;
  for (const sx of [-1, 1]) for (const s2 of [-1, 1]) k.box(lx + sx * 0.5, 0, lz + s2 * 0.2, 0.05, 0.52, 0.05, frame);
  k.box(lx, 0.52, lz - 0.08, 1.1, 0.3, 0.62, scale(frame, 1.1), scale(frame, 0.8));
  k.bar([lx - 0.12, 0.52, lz], [lx - 0.12, 0.36, lz], 0.03, DARK);
  lorryCab(k, lx, lz, 0.84, hex(0xe2412f));
  tube(k, [lx - 0.36, 0.22, lz], [lx + 0.2, 0.22, lz], 0.115, hex(0xe4e2dc), 8);
  k.glowBox(lx, 0.5, lz + 0.2, 0.5, 0.02, 0.06, LAMP_DAY, [17, 30, 1.8], COOL_GLOW);
  // limestone and dust about the yard
  k.cone(bx + 0.65, 0.02, bz + 2.05, 0.45, 0.4, hex(0xdcd9d0), 8);
  k.cone(bx + 1.05, 0.02, bz + 2.4, 0.26, 0.2, hex(0xd2cfc6), 7);
  for (let i = 0; i < 4; i++) k.cone(bx + 0.5 + r() * (W - 1), 0.02, bz + 0.3 + r() * 0.3, 0.12 + r() * 0.08, 0.07, hex(0xdedcd5), 6);
};

// ---- container terminal ------------------------------------------------------------------------

/**
 * A container yard: boxes stacked in coloured rows, two yellow gantry cranes straddling them, a reach
 * stacker, floodlight masts, and the gate lanes at the front.
 */
const containerTerminal: Draw = (k, W, D, b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const BOXES = [0xb8402f, 0x2f6fa5, 0x3f8a4a, 0xe08a2a, 0x8c9096, 0x7a2f2a, 0x2a4f7a, 0xd9d6cc];
  const CL = 0.95, CW = 0.2, CH = 0.2;
  const box40 = (x: number, y: number, z: number, col: RGB, alongZ = false) =>
    k.box(x, y, z, alongZ ? CW : CL, CH, alongZ ? CL : CW, col, scale(col, 0.88));
  // two blocks, three rows each, stacked one to four high
  const blocks = [bz + 0.75, bz + 2.15];
  const slots = Math.max(2, Math.floor((W - 1.6) / (CL + 0.05)));
  const x0 = bx + 0.3 + CL / 2;
  blocks.forEach((zc, bi) => {
    for (let row = -1; row <= 1; row++) {
      for (let i = 0; i < slots; i++) {
        const n = 2 + Math.floor(r() * 2.7);
        for (let j = 0; j < n; j++) box40(x0 + i * (CL + 0.05), j * CH, zc + row * (CW + 0.04), hex(BOXES[Math.floor(r() * BOXES.length)]));
      }
    }
    // the gantry crane over the block: a portal on rubber tyres with a trolley on its girders
    const gx = x0 + (bi === 0 ? 0.5 : slots - 1.5) * (CL + 0.05), gh = 1.2, leg = 0.5, base = 0.26;
    for (const sz of [-1, 1]) {
      const z = zc + sz * leg;
      for (const sx of [-1, 1]) {
        k.bar([gx + sx * base, 0.1, z], [gx + sx * base, gh, z], 0.04, YELLOW);
        k.box(gx + sx * base, 0, z, 0.2, 0.12, 0.09, hex(0x24262a));
      }
      k.bar([gx - base - 0.08, 0.14, z], [gx + base + 0.08, 0.14, z], 0.04, YELLOW);
      k.bar([gx - base, gh, z], [gx + base, gh, z], 0.03, YELLOW);
    }
    for (const sx of [-1, 1]) k.bar([gx + sx * base, gh, zc - leg - 0.06], [gx + sx * base, gh, zc + leg + 0.06], 0.05, YELLOW);
    const tz = zc + (bi === 0 ? 0.24 : -0.24);
    k.box(gx, gh + 0.04, tz, base * 2 + 0.1, 0.1, 0.22, hex(0xd99a2a), DARK);
    k.box(gx + base, gh - 0.16, tz, 0.14, 0.16, 0.16, WHITE, DARK);
    for (const sx of [-1, 1]) k.bar([gx + sx * 0.2, gh, tz], [gx + sx * 0.2, 1.02, tz], 0.008, DARK);
    k.box(gx, 1.0, tz, CL, 0.03, CW, DARK);
    box40(gx, 0.8, tz, hex(BOXES[(b.seed + bi) % BOXES.length]));
    lamp(k, gx, gh + 0.15, tz, true, 0.04);
    k.glowBox(gx, gh - 0.05, zc, 0.3, 0.03, 0.08, LAMP_DAY, ALL_NIGHT, COOL_GLOW);
  });
  // the side strip: a row of empties end-on, and the workshop
  const sxp = W / 2 - 0.55;
  for (let i = 0; i < 3; i++) {
    const n = 1 + Math.floor(r() * 3);
    for (let j = 0; j < n; j++) box40(sxp - 0.3 + i * (CW + 0.04), j * CH, bz + 0.75, hex(BOXES[Math.floor(r() * BOXES.length)]), true);
  }
  k.box(sxp, 0, bz + 2.0, 0.7, 0.4, 0.9, hex(0x9fb0b8), hex(0x5f6b73));
  k.box(sxp - 0.36, 0, bz + 2.0, 0.02, 0.3, 0.5, DARK);
  // the reach stacker, boom up, a box in its spreader
  const rx = sxp - 0.95, rzp = bz + 3.2;
  k.box(rx, 0.04, rzp, 0.5, 0.16, 0.26, YELLOW, DARK);
  for (const sx of [-1, 1]) k.box(rx + sx * 0.17, 0, rzp, 0.14, 0.13, 0.3, hex(0x24262a));
  k.box(rx + 0.12, 0.2, rzp, 0.16, 0.14, 0.2, GLASS_LIGHT, YELLOW);
  k.bar([rx + 0.22, 0.22, rzp], [rx - 0.5, 0.62, rzp], 0.04, YELLOW);
  k.bar([rx - 0.5, 0.62, rzp], [rx - 0.5, 0.5, rzp], 0.015, DARK);
  box40(rx - 0.5, 0.3, rzp, hex(BOXES[(b.seed + 3) % BOXES.length]), true);
  // floodlight masts at the corners of the stacking ground
  for (const [mx, mz] of [[bx + 0.18, bz + 0.2], [W / 2 - 0.18, bz + 0.2], [bx + 0.18, bz + 3.0], [W / 2 - 0.18, bz + 3.0]] as [number, number][]) {
    const mh = 2.1;
    k.bar([mx, 0, mz], [mx, mh, mz], 0.028, METAL);
    k.box(mx, mh, mz, 0.34, 0.05, 0.12, DARK);
    k.glowBox(mx, mh - 0.035, mz, 0.3, 0.035, 0.1, LAMP_DAY, [17, 30, 2.8], COOL_GLOW);
  }
  // the gate: a canopy over two booths, lane lines, the gatehouse, and a lorry coming through
  const gz = D / 2 - 1.15, gcx = bx + 1.9;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(gcx + sx * 1.1, 0, gz + sz * 0.28, 0.06, 0.6, 0.06, METAL);
  k.box(gcx, 0.6, gz, 2.4, 0.09, 0.76, WHITE, hex(0x2f5d8a));
  k.glowBox(gcx, 0.57, gz, 2.2, 0.03, 0.5, LAMP_DAY, [17, 30, 1.8], COOL_GLOW);
  for (const ox of [-0.38, 0.38]) {
    k.box(gcx + ox, 0, gz, 0.2, 0.34, 0.3, hex(0x2f5d8a), WHITE);
    k.pane(gcx + ox, 0.16, gz + 0.15, 0.14, 0.12, 1, GLASS, [0, 30, 1.6], WARM_GLOW);
  }
  for (let i = 0; i < 4; i++) k.box(gcx - 1.14 + i * 0.76, 0, gz + 0.75, 0.03, 0.022, 1.0, hex(0xe8e4d4));
  k.box(bx + 0.45, 0, gz - 0.05, 0.5, 0.4, 0.7, hex(0xe6e2d6), hex(0x5f6b73));
  k.pane(bx + 0.45, 0.14, gz + 0.3, 0.3, 0.14, 1, GLASS, [0, 30, 1.5], WARM_GLOW);
  const lx = gcx + 2.2;
  lorryCab(k, lx, gz - 0.05, 1.3, hex(0x2f7fb5));
  box40(lx - 0.13, 0.1, gz - 0.05, hex(BOXES[(b.seed + 5) % BOXES.length]));
};

// ---- auto plant --------------------------------------------------------------------------------

/**
 * A car factory: a very long assembly hall under a sawtooth roof, the paint shop with its stacks, a
 * glass-fronted office, a lot of new cars in coloured rows and a loaded transporter at the gate.
 */
const autoPlant: Draw = (k, W, D, b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const wall = hex(0xe4e6e4), roof = hex(0x8d979c), brand = hex(0x1f4f8f), paint = hex(0xa9b6bf);
  // the assembly hall
  const hw = W - 1.9, hcx = bx + 0.15 + hw / 2, hd = 1.8, hcz = bz + 0.15 + hd / 2, hh = 0.5;
  k.box(hcx, 0, hcz, hw, hh, hd, wall, roof);
  k.box(hcx, 0, hcz, hw + 0.01, 0.12, hd + 0.01, brand);
  sawtooth(k, hcx, hh, hcz, hw, hd, Math.max(6, Math.round(hw / 0.5)), 0.16, roof, wall, true, [0, 30, 1.4], COOL_GLOW);
  const fz = hcz + hd / 2;
  // the company sign across the front, lit, and the dock doors under it
  k.box(hcx, 0.26, fz + 0.02, 1.9, 0.2, 0.04, brand);
  k.glowBox(hcx, 0.31, fz + 0.045, 1.5, 0.1, 0.012, WHITE, [17, 30, 2], COOL_GLOW);
  for (const s of [-1, 1]) k.glowBox(hcx + s * 0.86, 0.3, fz + 0.045, 0.1, 0.12, 0.012, hex(0xe2412f), [17, 30, 2], RED_LIGHT);
  for (let i = 0; i < 6; i++) {
    const x = hcx - hw / 2 + 0.4 + i * ((hw - 0.8) / 5);
    if (Math.abs(x - hcx) < 1.05) continue;
    k.box(x, 0, fz + 0.012, 0.34, 0.3, 0.02, hex(0x5a646c));
  }
  // the paint shop: a taller block at the end, stacks and ducts on its roof
  const pw = 1.35, pcx = W / 2 - 0.15 - pw / 2, pd = 1.5, pcz = bz + 0.15 + pd / 2, ph = 0.8;
  k.box(pcx, 0, pcz, pw, ph, pd, paint, scale(paint, 0.75));
  k.box(pcx, ph * 0.55, pcz, pw + 0.012, 0.08, pd + 0.012, brand);
  for (let i = 0; i < 3; i++) {
    const x = pcx - 0.4 + i * 0.4;
    k.cyl(x, ph, pcz - 0.35, 0.065, 0.7, METAL, 8, DARK);
    k.band(x, pcz - 0.35, ph + 0.5, 0.07, ph + 0.6, 0.07, 8, hex(0xe2412f));
  }
  k.box(pcx, ph, pcz + 0.25, 0.9, 0.12, 0.4, scale(paint, 0.9), scale(paint, 0.7));
  lamp(k, pcx, ph + 0.72, pcz - 0.35, true, 0.04);
  // the office: two floors of glass on the front
  const ow = pw, ocz = pcz + pd / 2 + 0.3, oh = 0.62;
  k.box(pcx, 0, ocz, ow, oh, 0.6, WHITE, roof);
  k.box(pcx, oh, ocz, ow + 0.08, 0.04, 0.68, brand);
  for (let f = 0; f < 2; f++) {
    for (let i = 0; i < 5; i++) k.pane(pcx - ow / 2 + 0.15 + i * ((ow - 0.3) / 4), 0.06 + f * 0.29, ocz + 0.3, 0.2, 0.22, 1, GLASS, [16.5 + r(), 21 + r() * 3, 1.5], WARM_GLOW);
  }
  // the lot of finished cars: tight rows, a colour to each batch
  const lotZ = fz + 0.42, cols = Math.max(4, Math.floor((hw - 0.9) / 0.27));
  k.box(bx + 0.25 + (cols * 0.27) / 2, 0, lotZ + 0.47, cols * 0.27 + 0.2, 0.02, 1.4, hex(0x767a80));
  for (let j = 0; j < 3; j++) {
    for (let i = 0; i < cols; i++) {
      if (j === 2 && i > cols - 3) continue;
      const col = hex(CARS[(b.seed + Math.floor(i / 3) + j * 2) % CARS.length]);
      // a lot this size of full parked cars is thousands of triangles: two boxes a car at this distance
      k.box(bx + 0.4 + i * 0.27, 0.03, lotZ + j * 0.45, 0.19, 0.08, 0.34, col);
      k.box(bx + 0.4 + i * 0.27, 0.11, lotZ + j * 0.45 - 0.02, 0.16, 0.06, 0.18, GLASS_LIGHT, col);
    }
  }
  // the transporter at the gate: two decks, cars nose to tail on both
  const tx = W / 2 - 1.75, tz = D / 2 - 0.95, tl = 1.25;
  lorryCab(k, tx, tz, tl, hex(0xe2412f));
  k.box(tx - 0.12, 0.3, tz, tl - 0.3, 0.025, 0.22, DARK);
  for (const ox of [-0.58, -0.12, 0.34]) for (const s of [-1, 1]) k.box(tx + ox, 0.1, tz + s * 0.1, 0.025, 0.2, 0.025, DARK);
  const mini = (x: number, y: number, col: RGB) => {
    k.box(x, y, tz, 0.3, 0.07, 0.17, col);
    k.box(x, y + 0.07, tz, 0.16, 0.055, 0.15, GLASS_LIGHT, col);
  };
  for (let i = 0; i < 3; i++) {
    mini(tx - 0.57 + i * 0.33, 0.325, hex(CARS[(b.seed + i) % CARS.length]));
    if (i < 2) mini(tx - 0.57 + i * 0.33, 0.1, hex(CARS[(b.seed + i + 3) % CARS.length]));
  }
  // the gatehouse and barrier
  k.box(W / 2 - 0.4, 0, D / 2 - 0.45, 0.34, 0.3, 0.34, WHITE, brand);
  k.pane(W / 2 - 0.4, 0.12, D / 2 - 0.28, 0.2, 0.12, 1, GLASS, [0, 30, 1.6], WARM_GLOW);
  k.box(W / 2 - 0.95, 0.16, D / 2 - 0.45, 0.7, 0.04, 0.04, hex(0xe2412f));
};

// ---- solar farm --------------------------------------------------------------------------------

/**
 * A solar farm: long rows of dark-blue panels tilted to the front on low frames, gravel tracks
 * between them, and an inverter cabin and fenced transformer in the corner.
 */
const solarFarm: Draw = (k, W, D, _b, r) => {
  const panel = hex(0x182c62), edge = hex(0x9db3d6), under = hex(0x39424e), gravel = hex(0xcbc4b2);
  k.box(0, 0, 0, 0.36, 0.02, D - 0.2, gravel);
  k.box(0, 0, D / 2 - 0.28, W - 0.2, 0.021, 0.34, gravel);
  const yl = 0.08, yh = 0.26, pd = 0.3;
  const table = (x0: number, x1: number, z: number) => {
    const zf = z + pd / 2, zb = z - pd / 2, I: P3 = [(x0 + x1) / 2, -1, z + 0.4];
    // the frame shows as a pale rim round the dark glass, which sits a hair proud of it
    k.quad([x0, yl, zf], [x1, yl, zf], [x1, yh, zb], [x0, yh, zb], edge, I);
    const e = 0.022, lift = 0.012, t = e / pd;
    const a = yl + (yh - yl) * t + lift, c = yh - (yh - yl) * t + lift;
    const n = Math.max(1, Math.round((x1 - x0) / 0.62)), cw = (x1 - x0 - e) / n;
    for (let i = 0; i < n; i++) {
      const u0 = x0 + e + i * cw, u1 = u0 + cw - e;
      k.quad([u0, a, zf - e], [u1, a, zf - e], [u1, c, zb + e], [u0, c, zb + e], panel, I);
    }
    // the back of the table, seen from behind, and its posts
    k.quad([x0, yl - 0.004, zf], [x1, yl - 0.004, zf], [x1, yh - 0.004, zb], [x0, yh - 0.004, zb], under, [(x0 + x1) / 2, 2, z - 0.6]);
    const posts = Math.max(2, Math.round((x1 - x0) / 0.9));
    for (let i = 0; i < posts; i++) {
      const x = x0 + 0.12 + ((x1 - x0 - 0.24) * i) / (posts - 1);
      k.box(x, 0, z - 0.06, 0.03, yh - 0.07, 0.03, METAL);
    }
  };
  const cornerW = 1.25, cornerD = 1.3;
  for (let z = -D / 2 + 0.3; z < D / 2 - 0.62; z += 0.43) {
    table(-W / 2 + 0.2, -0.24, z);
    const inCorner = z + pd / 2 > D / 2 - 0.5 - cornerD;
    table(0.24, W / 2 - 0.2 - (inCorner ? cornerW : 0), z);
  }
  // the inverter cabin, and the transformer in its fenced pen
  const cx = W / 2 - 0.82, cz = D / 2 - 1.15;
  k.box(cx - 0.12, 0, cz - 0.2, 0.46, 0.3, 0.34, hex(0xe6e8e4), hex(0x5f6b73));
  k.box(cx - 0.12, 0, cz - 0.02, 0.12, 0.2, 0.02, hex(0x3f7d5a));
  k.glowBox(cx - 0.12, 0.23, cz - 0.02, 0.06, 0.03, 0.02, LAMP_DAY, ALL_NIGHT, COOL_GLOW);
  const tx = cx + 0.3, tz = cz + 0.3;
  k.box(tx, 0, tz, 0.26, 0.24, 0.2, hex(0x7d8790), hex(0x5f6b73));
  for (const s of [-1, 1]) k.box(tx, 0.03, tz + s * 0.13, 0.22, 0.17, 0.04, hex(0x6b7076));
  for (const s of [-1, 0, 1]) k.bar([tx + s * 0.08, 0.24, tz], [tx + s * 0.08, 0.36, tz], 0.012, WHITE);
  const fw = cornerW - 0.22, fd = cornerD - 0.32, fcx = W / 2 - 0.2 - fw / 2, fcz = D / 2 - 0.55 - fd / 2, fence = scale(METAL, 0.85);
  for (const s of [-1, 1]) {
    k.box(fcx, 0, fcz + s * fd / 2, fw, 0.17, 0.015, fence);
    k.box(fcx + s * fw / 2, 0, fcz, 0.015, 0.17, fd, fence);
  }
  void r;
};

// ---- offshore wind -----------------------------------------------------------------------------

/**
 * Three big offshore turbines: slender white towers on yellow transition pieces standing in the sea,
 * rotors turning, a red light on each nacelle.
 */
const offshoreWind: Draw = (k, W, D, b) => {
  const sea = hex(0x4f9bcb);
  k.box(0, 0, 0, W - 0.1, 0.03, D - 0.1, sea, scale(sea, 1.06));
  const spots: [number, number][] = [[-W / 2 + 0.6, -D / 2 + 0.75], [W / 2 - 0.6, -D / 2 + 0.75], [0, D / 2 - 0.7]];
  spots.forEach(([x, z], i) => {
    const H = 3.5 - (i === 2 ? 0.15 : 0), ty = 0.5;
    // foam round the pile, the yellow transition piece with its platform and boat ladder
    k.cyl(x, 0.03, z, 0.26, 0.012, hex(0xdcebf2), 10);
    k.cyl(x, 0.03, z, 0.15, ty - 0.03, YELLOW, 10);
    k.cyl(x, ty, z, 0.23, 0.035, hex(0xd99a2a), 10);
    k.hoop(x, ty + 0.11, z, 0.22, 0.01, YELLOW, 8, 'xz');
    k.bar([x, 0.03, z + 0.17], [x, ty, z + 0.17], 0.018, hex(0xd99a2a));
    // the tower, tapering, and the nacelle
    k.band(x, z, ty + 0.03, 0.115, H, 0.07, 10, WHITE);
    k.box(x, H - 0.04, z - 0.05, 0.17, 0.17, 0.44, WHITE, scale(WHITE, 0.92));
    k.glowBox(x, H + 0.13, z - 0.2, 0.05, 0.05, 0.05, RED_DAY, ALL_NIGHT, RED_LIGHT);
    // the rotor: three long blades, broad at the root
    const seed = b.seed + i * 5;
    k.spin(x, H + 0.045, z + 0.2, 'z', 1.0 + (seed % 5) * 0.07, (s) => {
      s.dome(0, 0, 0, 0.075, WHITE, 6, 2);
      s.cyl(0, -0.04, 0, 0.075, 0.04, WHITE, 6);
      for (let j = 0; j < 3; j++) {
        const a = (j / 3) * TAU + seed;
        const c = Math.cos(a), sn = Math.sin(a);
        s.bar([c * 0.04, sn * 0.04, 0.02], [c * 0.62, sn * 0.62, 0.02], 0.045, WHITE);
        s.bar([c * 0.6, sn * 0.6, 0.02], [c * 1.3, sn * 1.3, 0.02], 0.028, WHITE);
      }
    });
  });
};

// ---- tidal barrage -----------------------------------------------------------------------------

/**
 * A tidal barrage: a long low dam of arched sluice bays with a road along its crest, a control tower
 * at one end, still water behind it and white water boiling out in front.
 */
const tidalBarrage: Draw = (k, W, D, _b, r) => {
  const conc = hex(0xc2bdb2), dark = hex(0x243a4a), calm = hex(0x4f93c4), rough = hex(0x7fbfe0), foam = hex(0xf2f6f6);
  const dz = -0.12, dd = 0.5, dh = 0.5;
  // the water: calm upstream, broken downstream
  k.box(0, 0, 0, W - 0.04, 0.02, D - 0.04, calm);
  k.box(0, 0, (dz + dd / 2 + D / 2) / 2, W - 0.04, 0.03, D / 2 - dz - dd / 2 - 0.02, rough);
  // the dam, with the control tower's end left solid
  const x0 = -W / 2 + 0.1, x1 = W / 2 - 1.0, dw = x1 - x0, dcx = (x0 + x1) / 2;
  k.box(dcx, 0, dz, dw, dh, dd, conc);
  const n = Math.max(3, Math.round(dw / 0.85)), pitch = dw / n, ow = pitch * 0.56, oh = 0.17, orad = ow / 2;
  for (let i = 0; i <= n; i++) {
    // piers proud of the wall between the bays
    const x = x0 + i * pitch;
    k.box(Math.min(Math.max(x, x0 + 0.08), x1 - 0.08), 0, dz, 0.16, dh - 0.04, dd + 0.2, scale(conc, 0.93));
  }
  for (let i = 0; i < n; i++) {
    const x = x0 + (i + 0.5) * pitch;
    // each bay: a dark arched mouth on both faces, and the race pouring out of the front one
    k.box(x, 0.02, dz, ow, oh, dd + 0.02, dark);
    k.face(x, 0.02 + oh, dz + dd / 2 + 0.013, orad, dark, 10);
    k.turned(Math.PI, () => k.face(-x, 0.02 + oh, -(dz - dd / 2) + 0.013, orad, dark, 10));
    const fl = 0.34 + r() * 0.22;
    k.box(x, 0.03, dz + dd / 2 + fl / 2, ow * 0.9, 0.035, fl, foam);
    k.box(x + (r() - 0.5) * 0.2, 0.03, dz + dd / 2 + fl + 0.12 + r() * 0.1, ow * (0.4 + r() * 0.3), 0.025, 0.14, foam);
    k.box(x, 0.02, dz + dd / 2 + 0.04, ow, 0.1, 0.06, foam);
  }
  // the roadway along the crest, railed and lamped
  const rw = W - 0.2;
  k.box(0, dh, dz, rw, 0.035, dd + 0.12, hex(0x5a5d62));
  k.box(0, dh + 0.035, dz, rw, 0.006, 0.02, hex(0xe8e4d4));
  for (const s of [-1, 1]) k.box(0, dh + 0.035, dz + s * (dd / 2 + 0.05), rw, 0.07, 0.02, METAL);
  for (let i = 0; i <= n; i += 2) {
    const x = x0 + i * pitch, z = dz - dd / 2 - 0.05;
    k.bar([x, dh + 0.03, z], [x, dh + 0.42, z], 0.012, DARK);
    k.bar([x, dh + 0.42, z], [x, dh + 0.42, z + 0.12], 0.012, DARK);
    k.glowBox(x, dh + 0.385, z + 0.12, 0.05, 0.03, 0.05, LAMP_DAY, [17, 30, 2.4], WARM_GLOW);
  }
  // abutments at both ends, and the control tower over the last one
  k.box(-W / 2 + 0.1, 0, dz, 0.16, dh, dd + 0.3, conc);
  const tx = W / 2 - 0.55;
  k.box(tx, 0, dz, 0.9, dh, dd + 0.4, conc);
  k.box(tx + 0.05, dh + 0.035, dz - 0.32, 0.5, 0.75, 0.42, scale(conc, 1.05));
  const cy = dh + 0.78;
  k.box(tx + 0.05, cy, dz - 0.32, 0.66, 0.22, 0.58, hex(0x3f5a73));
  for (const f of [1, 3]) k.pane(tx + 0.05, cy + 0.04, dz - 0.32 + (f === 1 ? 0.29 : -0.29), 0.56, 0.14, f, GLASS_LIGHT, [0, 30, 1.5], WARM_GLOW);
  for (const f of [0, 2]) k.pane(tx + 0.05 + (f === 0 ? 0.33 : -0.33), cy + 0.04, dz - 0.32, 0.48, 0.14, f, GLASS_LIGHT, [0, 30, 1.5], WARM_GLOW);
  k.box(tx + 0.05, cy + 0.22, dz - 0.32, 0.72, 0.04, 0.64, WHITE);
  k.bar([tx + 0.05, cy + 0.26, dz - 0.32], [tx + 0.05, cy + 0.56, dz - 0.32], 0.012, DARK);
  lamp(k, tx + 0.05, cy + 0.56, dz - 0.32, true, 0.04);
};

// ---- pumped hydro ------------------------------------------------------------------------------

/**
 * A pumped-storage station: a raised oval reservoir inside its embankment, penstocks running down
 * the bank to the powerhouse, a switchyard of gantries and transformers, and the lower pond.
 */
const pumpedHydro: Draw = (k, W, D, _b, r) => {
  const bx = -W / 2, bz = -D / 2;
  const bank = hex(0x7d9458), crest = hex(0xc9c4b6), water = scale(WATER, 0.92), pipe = hex(0xe2e4e0), frame = hex(0x8b949c);
  // the upper reservoir: bank up, a flat crest, a lip down to the water
  const cx = 0, cz = bz + 1.05, RH = 0.8, seg = 20;
  const rxo = W / 2 - 0.12, rzo = 0.95, rxc = rxo - 0.34, rzc = rzo - 0.3;
  const ring = (y0: number, ax0: number, az0: number, y1: number, ax1: number, az1: number, col: RGB, inward: boolean) => {
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU, am = (a0 + a1) / 2;
      const I: P3 = inward ? [cx + Math.cos(am) * ax0 * 4, (y0 + y1) / 2, cz + Math.sin(am) * az0 * 4] : [cx, Math.min(y0, y1) - 0.5, cz];
      k.quad([cx + Math.cos(a0) * ax0, y0, cz + Math.sin(a0) * az0], [cx + Math.cos(a1) * ax0, y0, cz + Math.sin(a1) * az0],
        [cx + Math.cos(a1) * ax1, y1, cz + Math.sin(a1) * az1], [cx + Math.cos(a0) * ax1, y1, cz + Math.sin(a0) * az1], col, I);
    }
  };
  ring(0, rxo, rzo, RH * 0.5, (rxo + rxc) / 2, (rzo + rzc) / 2, bank, false);
  ring(RH * 0.5, (rxo + rxc) / 2, (rzo + rzc) / 2, RH, rxc, rzc, scale(bank, 1.06), false);
  ring(RH, rxc, rzc, RH, rxc - 0.1, rzc - 0.1, crest, false);
  ring(RH, rxc - 0.1, rzc - 0.1, RH - 0.13, rxc - 0.17, rzc - 0.17, scale(crest, 0.8), true);
  k.cyl(cx, RH - 0.2, cz, rxc - 0.16, 0.07, water, seg, water, rzc - 0.16);
  // the intake tower standing in the water, and its footbridge to the crest
  const ix = bx + 1.75, iz = cz + rzc - 0.32;
  k.cyl(ix, RH - 0.14, iz, 0.09, 0.34, crest, 8, hex(0x5f6b73));
  k.bar([ix, RH + 0.12, iz], [ix, RH + 0.03, cz + rzc - 0.04], 0.02, frame);
  // three penstocks down the bank on their anchor blocks
  const pz0 = cz + rzc - 0.02, pz1 = D / 2 - 1.22;
  for (let i = 0; i < 3; i++) {
    const x = bx + 1.3 + i * 0.45;
    tube(k, [x, RH - 0.02, pz0], [x, 0.14, pz1], 0.085, pipe, 8);
    for (const t of [0.3, 0.68]) {
      const y = RH - 0.02 + (0.14 - RH + 0.02) * t, z = pz0 + (pz1 - pz0) * t;
      k.box(x, 0, z, 0.26, y + 0.02, 0.14, CONCRETE);
    }
    k.box(x, RH - 0.06, pz0 - 0.04, 0.24, 0.14, 0.16, CONCRETE);
  }
  // the powerhouse at the foot
  const hw = 1.7, hx = bx + 1.75, hd = 0.58, hz = pz1 + hd / 2 - 0.02, hh = 0.52;
  k.box(hx, 0, hz, hw, hh, hd, hex(0xddd8cc), hex(0x5f6b73));
  k.box(hx, hh, hz, hw + 0.08, 0.05, hd + 0.08, hex(0x5f6b73));
  for (let i = 0; i < 5; i++) k.pane(hx - hw / 2 + 0.22 + i * ((hw - 0.44) / 4), 0.14, hz + hd / 2, 0.2, 0.26, 1, GLASS, [0, 30, 1.5], WARM_GLOW);
  k.box(hx + hw / 2 - 0.25, 0, hz + hd / 2 + 0.012, 0.22, 0.3, 0.02, DARK);
  // the tailrace out to the lower pond
  const pxp = bx + 0.52, pzp = D / 2 - 1.0;
  k.cyl(pxp, 0, pzp, 0.4, 0.035, hex(0xa9a394), 12, hex(0xa9a394), 0.62);
  k.cyl(pxp, 0.02, pzp, 0.33, 0.026, water, 12, water, 0.55);
  k.box((pxp + hx - hw / 2) / 2 + 0.1, 0, hz, hx - hw / 2 - pxp - 0.1, 0.04, 0.2, water);
  // the switchyard: two gantries strung together, transformers between them
  const sx0 = hx + hw / 2 + 0.3, sx1 = W / 2 - 0.2, scx = (sx0 + sx1) / 2, sw = sx1 - sx0;
  const sza = pz1 - 0.35, szb = D / 2 - 0.7;
  k.box(scx, 0, (sza + szb) / 2, sw + 0.2, 0.02, szb - sza + 0.3, hex(0xcbc4b2));
  for (const z of [sza, szb]) {
    for (const x of [sx0, sx1]) {
      k.bar([x - 0.06, 0, z], [x, 0.78, z], 0.02, frame);
      k.bar([x + 0.06, 0, z], [x, 0.78, z], 0.02, frame);
      k.bar([x - 0.04, 0.26, z], [x + 0.02, 0.52, z], 0.012, frame);
    }
    k.bar([sx0, 0.74, z], [sx1, 0.74, z], 0.03, frame);
    for (let i = 0; i < 3; i++) k.bar([sx0 + sw * (0.25 + i * 0.25), 0.74, z], [sx0 + sw * (0.25 + i * 0.25), 0.62, z], 0.014, WHITE);
  }
  for (let i = 0; i < 3; i++) {
    const x = sx0 + sw * (0.25 + i * 0.25);
    k.bar([x, 0.62, sza], [x, 0.62, szb], 0.007, DARK);
    if (i === 1 && sw < 1.2) continue;
    const tz = (sza + szb) / 2;
    k.box(x, 0.02, tz, 0.24, 0.26, 0.3, hex(0x7d8790), hex(0x5f6b73));
    for (const s of [-1, 1]) k.box(x + s * 0.14, 0.05, tz, 0.04, 0.18, 0.26, hex(0x6b7076));
    k.bar([x, 0.28, tz], [x, 0.62, tz], 0.012, WHITE);
  }
  lamp(k, sx1, 0.8, sza, true, 0.04);
  k.glowBox(hx, hh - 0.04, hz + hd / 2 + 0.02, 0.5, 0.03, 0.03, LAMP_DAY, [17, 30, 2], COOL_GLOW);
  void r;
};

