function heatOf(t: number): number {
  let k = 1;
  while (k < HEAT.length - 1 && t > HEAT[k][0]) k++;
  const [t0, c0] = HEAT[k - 1], [t1, c1] = HEAT[k], f = Math.min(1, Math.max(0, (t - t0) / (t1 - t0)));
  const mix = (sh: number) => Math.round(((c0 >> sh) & 255) + (((c1 >> sh) & 255) - ((c0 >> sh) & 255)) * f);
  return (mix(16) << 16) | (mix(8) << 8) | mix(0);
}
