/** A culture's colour on the map: the styles spread round the colour wheel a golden angle apart, so neighbours in the list differ. */
export function styleColour(style: string): number {
  if (style === 'visitor') return VISITOR_COLOUR;
  const i = ARCH_ORDER.indexOf(style);
  const c = new THREE.Color().setHSL((((i < 0 ? hashStr(style) : i) * 0.618034) % 1 + 1) % 1, 0.72, i % 2 ? 0.6 : 0.52);
  return c.getHex();
}
function hashStr(s: string): number { let h = 7; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 997; }
function ramp(stops: [number, number][], t: number): number {
  let k = 1;
  while (k < stops.length - 1 && t > stops[k][0]) k++;
  const [t0, c0] = stops[k - 1], [t1, c1] = stops[k], f = Math.min(1, Math.max(0, (t - t0) / (t1 - t0)));
  const mix = (sh: number) => Math.round(((c0 >> sh) & 255) + (((c1 >> sh) & 255) - ((c0 >> sh) & 255)) * f);
  return (mix(16) << 16) | (mix(8) << 8) | mix(0);
}
