/**
 * A route as the Fleet view draws it: from the vehicle on, with nothing it has already passed. The vehicle
 * stands somewhere along the first few legs of its own route (the waypoint it is heading for, or the tile it
 * was on when the route was last worked out, can be behind it): the leg nearest it is found, and the line
 * starts at the vehicle and runs on from the far end of that leg.
 */
function routeAhead(pts: { x: number; z: number }[]): { x: number; z: number }[] {
  if (pts.length < 3) return pts;
  const v = pts[0];
  let best = 1, bestT = 0, bd = Infinity;
  for (let k = 1; k + 1 < pts.length && k < 12; k++) {
    const a = pts[k], b = pts[k + 1], ex = b.x - a.x, ez = b.z - a.z, l2 = ex * ex + ez * ez;
    const t = l2 > 0 ? Math.max(0, Math.min(1, ((v.x - a.x) * ex + (v.z - a.z) * ez) / l2)) : 0;
    const d = Math.hypot(a.x + ex * t - v.x, a.z + ez * t - v.z);
    if (d < bd - 1e-6) { bd = d; best = k; bestT = t; }
  }
  // not yet onto that leg (still short of its start): its start is still ahead, and stays in
  return [v, ...pts.slice(bestT <= 0 ? best : best + 1)];
}
/** The grey a map colour becomes in the grey views: its brightness, pulled toward the dark. */
function greyOf(c: number): number {
  const r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
  const l = Math.round((0.299 * r + 0.587 * g + 0.114 * b) * 0.42 + 22);
  return (l << 16) | (l << 8) | l;
}

