/**
 * PvP Challenges (docs/challenges.html, 0.7.0): rare chequered start lines on the roads (land vehicles), across the
 * airports' runways (aircraft) and between two buoys on the water (boats). Two kinds:
 *
 * - **Sixty** (`far`): stop at the line, Space, the countdown holds the vehicle, then 60 seconds to get as far
 *   from the line as you can, any direction; the straight-line tiles at the 60th second are the score.
 * - **Dash** (`dash`): from the line to a destination shown by the route arrows, against the clock.
 *
 * Every board keeps each fleet's best only; the top line holds it, and the holder is paid ◆ 1 a game day while
 * they hold it, as a town held as territory pays. The parts here are the ones the game and the server share:
 * which cells may have a line (so nobody can make up a board), and `ChalRun`, the run as the server checks it
 * from the poses a game sends, so a teleport, a clock run slow or a jumped start can't post a distance or a time.
 */

/** Tiles to a cell's side (world/tiles.ts N). */
export const CHAL_N = 256;

/** The three classes a line is for: road (land vehicles), air (at an airport) and sea (between buoys). */
export type ChalClass = 'L' | 'A' | 'S';
export type ChalKind = 'far' | 'dash';
/** The vehicle kinds (game/vehicles.ts VehicleDef.kind) each class takes. */
export const CHAL_TAKES: Record<ChalClass, string> = { L: 'land', A: 'air', S: 'water' };
export const CHAL_CLASS_NAME: Record<ChalClass, string> = { L: 'Land vehicles only', A: 'Aircraft only', S: 'Boats only' };

/** How often a cell has a line of each class, of the cells that could hold one (a straight road, an airport, open water). */
export const CHAL_RATE: Record<ChalClass, number> = { L: 1 / 8, A: 1 / 3, S: 1 / 10 };

export const CHAL = {
  /** The countdown before the go, seconds; the Sixty's window. */
  count: 3, far: 60,
  /** How near the line's middle a vehicle must stop to be offered the start, tiles, and how slow counts as stopped. */
  startR: 3.2, stopped: 0.6,
  /** A vehicle that creeps further than this from where it stood during the countdown has jumped the start. */
  creep: 1.5,
  /** A dash is over at this many tiles from the destination (an aircraft's ring is wider), and void after this long. */
  finishR: 4.5, finishAirR: 10, dashMax: 900,
  /** A step may move this many times the model's top speed, never less than `floor` tiles a second, plus `slack` tiles (as range's chain). */
  speedSlack: 2.5, speedFloor: 8, stepSlack: 1.5,
  /** The sender's clock against ours over a run, ms: ahead of ours, or fallen behind ours (a slowed clock, or a stall). */
  ahead: 1500, behind: 2500,
  /** A gap in the poses longer than this (ms) voids the run: a tab hidden, a lost connection. */
  gap: 3000,
  /** A ghost's samples a second, and the most it holds (as marks' lap ghosts, whose encoding it is sent in: five minutes). */
  ghostHz: 5, ghostMax: 1500,
  /** Lines a board sends. */
  top: 10,
  /** ◆ a game day for holding a board. */
  perDay: 1,
} as const;

/** A small hash of the world seed, a cell and a salt into [0, 1): the same on both sides. */
export function chalHash(seed: number, cx: number, cz: number, salt: string): number {
  let h = (seed ^ 0x9e3779b9) >>> 0;
  const mix = (v: number) => { h = Math.imul(h ^ v, 2654435761) >>> 0; h = ((h << 13) | (h >>> 19)) >>> 0; };
  mix(cx | 0); mix(cz | 0);
  for (let i = 0; i < salt.length; i++) mix(salt.charCodeAt(i));
  h = Math.imul(h ^ (h >>> 16), 2246822507) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 3266489909) >>> 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Whether a cell may have a line of this class at all (the game still needs the road, the airport or the water to put it on). */
export const chalRolled = (seed: number, cx: number, cz: number, cls: ChalClass): boolean => chalHash(seed, cx, cz, `chal${cls}`) < CHAL_RATE[cls];
/** Which kind a cell's line of this class is. */
export const chalKindOf = (seed: number, cx: number, cz: number, cls: ChalClass): ChalKind => (chalHash(seed, cx, cz, `kind${cls}`) < 0.5 ? 'far' : 'dash');
/** A board's id: the cell and the class, "cx,cz:L". */
export const chalId = (cx: number, cz: number, cls: ChalClass): string => `${cx},${cz}:${cls}`;
export function parseChalId(id: string): { cx: number; cz: number; cls: ChalClass } | null {
  const m = /^(-?\d{1,5}),(-?\d{1,5}):([LAS])$/.exec(id);
  return m ? { cx: Number(m[1]), cz: Number(m[2]), cls: m[3] as ChalClass } : null;
}
/** A board's id is one the world can have, by the seed alone. */
export function chalValid(seed: number, id: string): boolean {
  const p = parseChalId(id);
  return !!p && chalRolled(seed, p.cx, p.cz, p.cls);
}

/** A line as laid in the world, world tiles: its middle, the heading it faces (x = sin h, z = cos h), its half-width, and a dash's destination. */
export interface ChalSite {
  id: string; cls: ChalClass; kind: ChalKind;
  /** Its name on the boards: "the Calder Distance", "Calder to Brookfield". */
  name: string;
  x: number; z: number; h: number; half: number;
  to?: { x: number; z: number; name: string };
}

/**
 * A "how far in sixty seconds" line's name, as it is called since 27 Oct 2026: "the Calder Distance" (it was "the
 * Calder Sixty"). Names an older game sends, and those the server already keeps, are put right with it.
 */
export function distanceName(name: string): string {
  return name.replace(/ Sixty$/, ' Distance');
}

/** Two sites are the same line: the middle and the destination within a couple of tiles. */
export function sameSite(a: ChalSite, b: ChalSite): boolean {
  if (a.id !== b.id || a.kind !== b.kind || Math.hypot(a.x - b.x, a.z - b.z) > 2) return false;
  if (!a.to || !b.to) return !a.to && !b.to;
  return Math.hypot(a.to.x - b.to.x, a.to.z - b.to.z) <= 3;
}

/** A site as a game sent it, checked for shape and for lying where its id says (the line in its cell; a dash's end not too near, not too far). */
export function cleanSite(s: unknown, seed: number): ChalSite | null {
  const x = s as Partial<ChalSite> | null;
  if (!x || typeof x !== 'object' || typeof x.id !== 'string' || !chalValid(seed, x.id)) return null;
  const p = parseChalId(x.id)!;
  const fin = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
  if (!fin(x.x) || !fin(x.z) || !fin(x.h) || !fin(x.half)) return null;
  if (Math.floor(x.x / CHAL_N) !== p.cx || Math.floor(x.z / CHAL_N) !== p.cz) return null;
  const kind = chalKindOf(seed, p.cx, p.cz, p.cls);
  if (x.kind !== kind || x.cls !== p.cls) return null;
  const site: ChalSite = { id: x.id, cls: p.cls, kind, name: distanceName(String(x.name ?? 'A challenge')).slice(0, 60), x: r1(x.x), z: r1(x.z), h: Math.round(x.h * 1000) / 1000, half: Math.min(6, Math.max(0.5, x.half)) };
  if (kind === 'dash') {
    const t = x.to;
    if (!t || !fin(t.x) || !fin(t.z)) return null;
    const d = Math.hypot(t.x - x.x, t.z - x.z);
    if (d < 60 || d > CHAL_N * 1.5) return null;
    site.to = { x: r1(t.x), z: r1(t.z), name: String(t.name ?? 'the finish').slice(0, 40) };
  }
  return site;
}
const r1 = (v: number) => Math.round(v * 10) / 10;

/** Scores: a Sixty's in tiles (more is better), a dash's in seconds (less is better). */
export const better = (kind: ChalKind, a: number, b: number): boolean => (kind === 'far' ? a > b : a < b);
export function scoreText(kind: ChalKind, s: number): string {
  if (kind === 'far') return `${Math.round(s).toLocaleString('en-US')} tiles`;
  const m = Math.floor(s / 60), r = s - m * 60;
  return m ? `${m}:${r.toFixed(1).padStart(4, '0')}` : `${r.toFixed(2)} s`;
}

/** One line of a board, as sent. */
export interface ChalRow {
  by: string; name: string; s: number; at: number;
  /** The model it was set in. */
  m: string;
  brand?: { primary: number; accent: number; logo: string };
  place?: number;
}

/** A board as sent: the site as the server keeps it, the top lines, mine, and how many have one. */
export interface ChalBoard { id: string; site: ChalSite; rows: ChalRow[]; you: ChalRow | null; n: number; ghost?: boolean }

/** News kept for the next sign-in: a board of mine taken. */
export interface ChalNews { id: string; name: string; kind: ChalKind; by: string; s: number; was: number; at: number }

/** Why a run was not counted. */
export type ChalVoid = 'start' | 'creep' | 'teleport' | 'clock' | 'gap' | 'vehicle' | 'slow' | 'stopped';
export const VOID_TEXT: Record<ChalVoid, string> = {
  start: 'not stopped on the line when the countdown began',
  creep: 'jumped the start: it moved before the go',
  teleport: 'moved faster than it could have (a teleport, the garage or a tow)',
  clock: 'the game’s clock ran out of step with the server’s',
  gap: 'the game stopped sending where it was (hidden, or the connection dropped)',
  vehicle: 'not the vehicle it started in, or not one this line takes',
  slow: 'took too long',
  stopped: 'stopped before the finish',
};

/** A pose as the run reads it: world tiles, the sender's clock (ms) and its speed. */
export interface RunPose { x: number; z: number; t: number; v: number }

/**
 * A run as the server checks it, fed the poses the game sends with the server's own clock beside each. It starts
 * when the game says go, at the latest pose (which must be stopped on the line); the go is `CHAL.count` seconds
 * later on the game's own clock. Every step is held to the model's top speed (as range's chain), the game's clock
 * to the server's both ways, and the countdown to standing still. A Sixty ends on the first pose past its 60th
 * second, scored where the vehicle was at that second exactly; a dash on the first pose inside the finish.
 */
export class ChalRun {
  phase: 'count' | 'run' | 'done' | 'void' = 'count';
  why: ChalVoid | null = null;
  /** The result: tiles (far) or seconds (dash). */
  score = 0;
  readonly go: number;
  /** The ghost: x, z (tiles from the line's middle) and heading, CHAL.ghostHz a second from the go. */
  ghost: [number, number, number][] = [];
  private last: RunPose;
  private lastS: number;
  private readonly from: RunPose;
  private readonly t0: number;
  private readonly s0: number;
  private readonly top: number;

  constructor(readonly site: ChalSite, top: number, start: RunPose, now: number) {
    this.top = Math.max(top * CHAL.speedSlack, CHAL.speedFloor);
    this.last = this.from = start;
    this.lastS = now;
    this.t0 = start.t;
    this.s0 = now;
    this.go = start.t + CHAL.count * 1000;
    if (Math.hypot(start.x - site.x, start.z - site.z) > CHAL.startR + 0.5 || Math.abs(start.v) > CHAL.stopped + 0.2) this.fail('start');
  }

  get over(): boolean { return this.phase === 'done' || this.phase === 'void'; }

  fail(why: ChalVoid): void { if (!this.over) { this.phase = 'void'; this.why = why; } }

  /** The server has gone `now` ms with nothing new: a run whose game went quiet is void. */
  idle(now: number): void { if (!this.over && now - this.lastS > CHAL.gap) this.fail('gap'); }

  /** One pose, at the server's `now`, with the heading for the ghost. */
  feed(p: RunPose, now: number, heading = 0): void {
    if (this.over) return;
    const prev = this.last;
    const dt = (p.t - prev.t) / 1000;
    if (!(dt > 0)) return;
    if (now - this.lastS > CHAL.gap || dt * 1000 > CHAL.gap) { this.fail('gap'); return; }
    // the game's clock against ours: neither ahead (a step look slower than it was) nor fallen behind (a Sixty run long, a dash short)
    const drift = (p.t - this.t0) - (now - this.s0);
    if (drift > CHAL.ahead || drift < -CHAL.behind) { this.fail('clock'); return; }
    const moved = Math.hypot(p.x - prev.x, p.z - prev.z);
    if (moved > this.top * Math.max(dt, 0.05) + CHAL.stepSlack) { this.fail('teleport'); return; }
    this.last = p;
    this.lastS = now;
    if (p.t < this.go) {
      if (Math.hypot(p.x - this.from.x, p.z - this.from.z) > CHAL.creep) this.fail('creep');
      return;
    }
    if (this.phase === 'count') this.phase = 'run';
    // the ghost, sampled on the game's clock from the go
    const want = Math.floor(((p.t - this.go) / 1000) * CHAL.ghostHz);
    while (this.ghost.length <= want && this.ghost.length < CHAL.ghostMax) {
      const k = this.ghost.length / CHAL.ghostHz * 1000 + this.go;
      const f = prev.t < this.go ? 1 : Math.min(1, Math.max(0, (k - prev.t) / (p.t - prev.t)));
      this.ghost.push([round(prev.x + (p.x - prev.x) * f - this.site.x), round(prev.z + (p.z - prev.z) * f - this.site.z), Math.round(heading * 1000) / 1000]);
    }
    const s = this.site;
    if (s.kind === 'far') {
      const end = this.go + CHAL.far * 1000;
      if (p.t < end) return;
      // where it was at the 60th second, between the two poses either side
      const f = prev.t >= end ? 0 : (end - prev.t) / (p.t - prev.t);
      const x = prev.x + (p.x - prev.x) * f, z = prev.z + (p.z - prev.z) * f;
      this.score = Math.round(Math.hypot(x - s.x, z - s.z) * 10) / 10;
      this.phase = 'done';
      return;
    }
    const to = s.to!;
    const r = s.cls === 'A' ? CHAL.finishAirR : CHAL.finishR;
    const d = Math.hypot(p.x - to.x, p.z - to.z);
    if (d <= r) {
      // over the ring: when it crossed, along the step (the step's start was outside)
      const d0 = Math.hypot(prev.x - to.x, prev.z - to.z);
      const f = d0 > d ? Math.min(1, Math.max(0, (d0 - r) / (d0 - d))) : 1;
      const t = Math.max(this.go, prev.t + (p.t - prev.t) * f);
      this.score = Math.round((t - this.go) / 10) / 100;
      this.phase = 'done';
      return;
    }
    if (p.t - this.go > CHAL.dashMax * 1000) this.fail('slow');
  }
}
const round = (v: number) => Math.round(v * 16) / 16;
