/**
 * Generated roads kept out of the water they run along (8 Nov 2026; GEN 54, held for 0.8.0 behind NEXT_080).
 *
 * A road squeezed along a shore (between the sea and a railway bank, say) could sit on tiles whose low corners lay
 * a step or two under the water: half the road drawn under the sea, and a car on it wading the whole way at a third
 * of its speed, nosing off into the sea at the first turn (the user, 8 Nov 2026: Ivoryhollow Island, online cell
 * 13,-12, three roads under a rail viaduct). raiseFords only lifts roads that cross water, on a deck; this lifts the
 * ground under roads that run along it: every corner of a paved road tile under its water is raised to the water's
 * surface, with the same corner of each tile that shares it, and a tile left with no corner under its water is drained.
 *
 * Dirt and gravel tracks ford on purpose and stream beds are left as they are; so are corners a railway, a building's
 * lot or a road bridge deck stands on (a viaduct pier in the water is fine: its tile only gets a shallower shore), and anything deeper than MAX_RAISE steps.
 */
import { Flag, N, RailBit, RoadType, inB, idx, minCorner, type World } from './tiles';

const MAX_RAISE = 2;
/** For the grid vertex (vx, vz): the tiles that share it (dx, dz from the vertex) and which of their corners it is. */
const SHARE: ReadonlyArray<readonly [number, number, number]> = [[0, 0, 0], [-1, 0, 1], [-1, -1, 2], [0, -1, 3]];
/** A tile's corner k as a vertex offset from the tile's own (x, z). */
const CORNER: ReadonlyArray<readonly [number, number]> = [[0, 0], [1, 0], [1, 1], [0, 1]];

function fixed(w: World, t: number): boolean {
  return (w.rail[t] & (RailBit.Track | RailBit.Pad | RailBit.Loop)) !== 0 || w.blocked[t] !== 0
    || w.deckAxis[t] !== 0 || (w.flags[t] & (Flag.River | Flag.Stream)) !== 0;
}

/** Raises the drowned corners of generated paved roads; returns how many road tiles were dried. */
export function dryRoads(w: World): number {
  const touched = new Set<number>();
  let dried = 0;
  for (let i = 0; i < N * N; i++) {
    const r = w.road[i], wl = w.water[i];
    if (!r || r === RoadType.Dirt || r === RoadType.Gravel || wl < 0 || minCorner(w, i) >= wl) continue;
    if (fixed(w, i) || wl - minCorner(w, i) > MAX_RAISE) continue;
    const x = i % N, z = (i - x) / N;
    for (let k = 0; k < 4; k++) {
      if (w.corners[i * 4 + k] >= wl) continue;
      const vx = x + CORNER[k][0], vz = z + CORNER[k][1];
      const share: [number, number][] = [];
      let ok = true;
      for (const [dx, dz, c] of SHARE) {
        const tx = vx + dx, tz = vz + dz;
        if (!inB(tx, tz)) continue;
        const t = idx(tx, tz);
        if (t !== i && fixed(w, t)) { ok = false; break; }
        share.push([t, c]);
      }
      if (!ok) continue;
      for (const [t, c] of share) {
        if (w.corners[t * 4 + c] < wl) w.corners[t * 4 + c] = wl;
        touched.add(t);
      }
    }
    if (minCorner(w, i) >= wl) dried++;
  }
  // a tile with no corner left under its water is dry ground now (its water would lie flush on it, fighting it)
  for (const t of touched) if (w.water[t] >= 0 && minCorner(w, t) >= w.water[t]) w.water[t] = -1;
  return dried;
}
