import { DIRS, N, RoadType, idx, inB, waterDepth, type World } from '../../world/tiles';
import { runwaysOf } from '../../world/runways';
import { chalHash, chalId, chalKindOf, chalRolled, type ChalClass, type ChalSite } from '../../../shared/challenges';

/**
 * Where a county's PvP Challenge lines lie (docs/challenges.html): worked out at run time from the county as
 * generated, never written into it, so GEN_VERSION stays and the online counties are the same to the tile.
 * The seed says which cells may have a line of each class (shared/challenges.ts chalRolled, as the server checks);
 * this finds the place for it:
 *
 * - **road** (land vehicles): a straight, level stretch of a paved road out of town, ten tiles or more with no
 *   junction, bridge, level crossing or boost pad on it; the line across it three tiles in;
 * - **air**: across an airport's runway, three tiles past its threshold, facing down the strip;
 * - **sea**: two buoys in open water near a shore, deep enough for anything that floats, facing the open water.
 *
 * A dash's destination is in the same county and reached the way its vehicles go: a road tile by road for a
 * land line (by a town's middle when one is far enough), deep water by water for a sea line, and for aircraft
 * a town's middle or a mark out over the country. Everything is picked by the seed's hash, so every game puts
 * a line in the same place; the server keeps the line most of them send.
 */

/** Roads a line may go across. */
const PAVED = new Set<number>([RoadType.Paved, RoadType.TwoLane, RoadType.FourLane, RoadType.Brick, RoadType.Cobble]);
/** A straight run at least this long, the line this far into it. */
const RUN = 10, IN = 3;
/** A dash's destination: at least this far, at most this far, straight-line tiles. */
const DASH_MIN = 110, DASH_MAX = 230;
/** Water deep enough for every boat (game/vehicles.ts minDepth is 3 steps at most). */
const DEEP = 3;

const cache = new WeakMap<World, ChalSite[]>();

/** A county's lines (none, one, two or three: one a class at most). Worked out once per county. */
export function sitesOf(w: World, seed: number): ChalSite[] {
  const hit = cache.get(w);
  if (hit) return hit;
  const out: ChalSite[] = [];
  for (const cls of ['L', 'A', 'S'] as ChalClass[]) {
    if (!chalRolled(seed, w.cx, w.cz, cls)) continue;
    const s = cls === 'L' ? roadSite(w, seed) : cls === 'A' ? airSite(w, seed) : seaSite(w, seed);
    if (s) out.push(s);
  }
  cache.set(w, out);
  return out;
}

const pick = <T>(list: T[], seed: number, w: World, salt: string): T | null => (list.length ? list[Math.floor(chalHash(seed, w.cx, w.cz, salt) * list.length) % list.length] : null);

/** The town nearest a local point, for a line's name. */
function placeNear(w: World, x: number, z: number): string {
  let best = w.name || 'the county', d = Infinity;
  for (const t of w.towns) {
    const e = Math.hypot(t.x0 + t.size / 2 - x, t.z0 + t.size / 2 - z);
    if (e < d) { d = e; best = t.name; }
  }
  return best;
}

function named(kind: 'far' | 'dash', cls: ChalClass, place: string, to?: string): string {
  if (kind === 'dash') return `${place} to ${to}`;
  return cls === 'A' ? `the ${place} Air Distance` : cls === 'S' ? `the ${place} Sea Distance` : `the ${place} Distance`;
}

// ---- roads ----

function roadSite(w: World, seed: number): ChalSite | null {
  const runs: { x: number; z: number; dx: number; dz: number }[] = [];
  const ok = (x: number, z: number, axis: number): boolean => {
    if (!inB(x, z)) return false;
    const i = idx(x, z);
    return PAVED.has(w.road[i]) && w.roadAxis[i] === axis && w.roadCover[i] === 1 && !w.deckAxis[i] && !w.rail[i] && !w.boost[i] && !w.blocked[i] && w.townId[i] < 0 && w.water[i] < 0 && !w.roadDiag[i];
  };
  const level = (x: number, z: number): boolean => {
    const b = idx(x, z) * 4, c = w.corners;
    return c[b] === c[b + 1] && c[b] === c[b + 2] && c[b] === c[b + 3];
  };
  for (const [axis, dx, dz] of [[1, 1, 0], [2, 0, 1]] as const) {
    for (let a = 0; a < N; a++) {
      let len = 0;
      for (let b = 0; b <= N; b++) {
        const x = dx ? b : a, z = dx ? a : b;
        if (b < N && ok(x, z, axis)) { len++; continue; }
        if (len >= RUN) {
          // the run ended at b-1: a line IN tiles in from either end, facing along it into the run
          const x0 = dx ? b - len : a, z0 = dx ? a : b - len;
          const lx = x0 + dx * IN, lz = z0 + dz * IN;
          if (level(lx, lz)) runs.push({ x: lx, z: lz, dx, dz });
          const ex = x0 + dx * (len - 1 - IN), ez = z0 + dz * (len - 1 - IN);
          if (level(ex, ez)) runs.push({ x: ex, z: ez, dx: -dx, dz: -dz });
        }
        len = 0;
      }
    }
  }
  const r = pick(runs, seed, w, 'road');
  if (!r) return null;
  const kind = chalKindOf(seed, w.cx, w.cz, 'L');
  const place = placeNear(w, r.x, r.z);
  const site: ChalSite = { id: chalId(w.cx, w.cz, 'L'), cls: 'L', kind, name: '', x: w.ox + r.x + 0.5, z: w.oz + r.z + 0.5, h: Math.atan2(r.dx, r.dz), half: 1.2 };
  if (kind === 'dash') {
    const to = roadDest(w, r.x, r.z, seed);
    if (!to) return null;
    site.to = to;
  }
  site.name = named(kind, 'L', place, site.to?.name);
  return site;
}

/** Every tile reached from (x, z) over the edges `step` allows, in this county. */
function flood(x: number, z: number, step: (i: number, d: number, j: number) => boolean): Uint8Array {
  const seen = new Uint8Array(N * N);
  const q = [idx(x, z)];
  seen[q[0]] = 1;
  for (let h = 0; h < q.length; h++) {
    const i = q[h], tx = i % N, tz = (i - tx) / N;
    for (let d = 0; d < 4; d++) {
      const nx = tx + DIRS[d][0], nz = tz + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (seen[j] || !step(i, d, j)) continue;
      seen[j] = 1;
      q.push(j);
    }
  }
  return seen;
}

/**
 * A land dash's finish: a town's middle reached by road when one is far enough (the road tile nearest its middle),
 * else a road tile picked from those far enough.
 */
function roadDest(w: World, x: number, z: number, seed: number): { x: number; z: number; name: string } | null {
  const seen = flood(x, z, (i, d, j) => !!(w.roadEdges[i] & (1 << d)) && w.road[j] > 0 && !w.blocked[j]);
  const far = (tx: number, tz: number) => { const d = Math.hypot(tx - x, tz - z); return d >= DASH_MIN && d <= DASH_MAX; };
  const towns = w.towns.filter((t) => far(t.x0 + t.size / 2, t.z0 + t.size / 2));
  const t = pick(towns, seed, w, 'dashTown');
  if (t) {
    const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
    let best = -1, bd = 14;
    for (let i = 0; i < N * N; i++) {
      if (!seen[i]) continue;
      const d = Math.hypot((i % N) - cx, Math.floor(i / N) - cz);
      if (d < bd) { bd = d; best = i; }
    }
    if (best >= 0) return { x: w.ox + (best % N) + 0.5, z: w.oz + Math.floor(best / N) + 0.5, name: t.name };
  }
  const ends: number[] = [];
  for (let i = 0; i < N * N; i += 3) if (seen[i] && PAVED.has(w.road[i]) && far(i % N, Math.floor(i / N))) ends.push(i);
  const e = pick(ends, seed, w, 'dashRoad');
  if (e === null) return null;
  const ex = e % N, ez = Math.floor(e / N);
  return { x: w.ox + ex + 0.5, z: w.oz + ez + 0.5, name: `the flag near ${placeNear(w, ex, ez)}` };
}

// ---- airports ----

function airSite(w: World, seed: number): ChalSite | null {
  const rws = runwaysOf(w).filter((r) => !r.deck);
  const r = pick(rws, seed, w, 'runway');
  if (!r) return null;
  const kind = chalKindOf(seed, w.cx, w.cz, 'A');
  const site: ChalSite = { id: chalId(w.cx, w.cz, 'A'), cls: 'A', kind, name: '', x: r.ax + r.ux * IN, z: r.az + r.uz * IN, h: r.heading, half: r.half };
  const place = r.name.replace(/( (International|Municipal|Regional|Airport|Airfield|Aerodrome|Field))+$/i, '') || placeNear(w, site.x - w.ox, site.z - w.oz);
  if (kind === 'dash') {
    const lx = site.x - w.ox, lz = site.z - w.oz;
    const towns = w.towns.filter((t) => { const d = Math.hypot(t.x0 + t.size / 2 - lx, t.z0 + t.size / 2 - lz); return d >= DASH_MIN && d <= DASH_MAX; });
    const t = pick(towns, seed, w, 'airTown');
    if (t) site.to = { x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2, name: t.name };
    else {
      // a mark out over the country, off the runway's heading by up to 60° either way
      const a = r.heading + (chalHash(seed, w.cx, w.cz, 'airMark') - 0.5) * (Math.PI * 2 / 3);
      site.to = { x: site.x + Math.sin(a) * 200, z: site.z + Math.cos(a) * 200, name: 'the marker beacon' };
    }
  }
  site.name = named(kind, 'A', place, site.to?.name);
  return site;
}

// ---- water ----

function seaSite(w: World, seed: number): ChalSite | null {
  const deep = (x: number, z: number) => inB(x, z) && w.water[idx(x, z)] >= 0 && waterDepth(w, idx(x, z)) >= DEEP;
  const cands: { x: number; z: number; h: number }[] = [];
  for (let z = 8; z < N - 8; z += 4) {
    for (let x = 8; x < N - 8; x += 4) {
      let open = true;
      for (let dz = -3; dz <= 3 && open; dz++) for (let dx = -3; dx <= 3 && open; dx++) if (!deep(x + dx, z + dz)) open = false;
      if (!open) continue;
      // near a shore, where boats are
      let shore = false;
      for (let r = 4; r <= 12 && !shore; r += 2) for (let a = 0; a < 8 && !shore; a++) {
        const sx = Math.round(x + Math.cos(a * Math.PI / 4) * r), sz = Math.round(z + Math.sin(a * Math.PI / 4) * r);
        if (inB(sx, sz) && w.water[idx(sx, sz)] < 0) shore = true;
      }
      if (!shore) continue;
      // facing the longest reach of deep water
      let bestH = 0, bestRun = 0;
      for (let a = 0; a < 8; a++) {
        const ux = Math.sin(a * Math.PI / 4), uz = Math.cos(a * Math.PI / 4);
        let run = 0;
        while (run < 60 && deep(Math.round(x + ux * run), Math.round(z + uz * run))) run++;
        if (run > bestRun) { bestRun = run; bestH = a * Math.PI / 4; }
      }
      if (bestRun >= 24) cands.push({ x, z, h: bestH });
    }
  }
  const c = pick(cands, seed, w, 'sea');
  if (!c) return null;
  const kind = chalKindOf(seed, w.cx, w.cz, 'S');
  const place = placeNear(w, c.x, c.z);
  const site: ChalSite = { id: chalId(w.cx, w.cz, 'S'), cls: 'S', kind, name: '', x: w.ox + c.x + 0.5, z: w.oz + c.z + 0.5, h: c.h, half: 2.5 };
  if (kind === 'dash') {
    const seen = flood(c.x, c.z, (_i, _d, j) => w.water[j] >= 0 && waterDepth(w, j) >= DEEP);
    const far = (tx: number, tz: number) => { const d = Math.hypot(tx - c.x, tz - c.z); return d >= DASH_MIN && d <= DASH_MAX; };
    // a harbour's mouth when one is far enough and on this water, else open water picked from far enough
    let to: { x: number; z: number; name: string } | null = null;
    for (const p of w.ports) {
      if (!far(p.x, p.z)) continue;
      let best = -1, bd = 16;
      for (let dz = -16; dz <= 16; dz++) for (let dx = -16; dx <= 16; dx++) {
        const tx = Math.round(p.x) + dx, tz = Math.round(p.z) + dz;
        if (!inB(tx, tz) || !seen[idx(tx, tz)]) continue;
        const d = Math.hypot(dx, dz);
        if (d < bd) { bd = d; best = idx(tx, tz); }
      }
      if (best >= 0) { to = { x: w.ox + (best % N) + 0.5, z: w.oz + Math.floor(best / N) + 0.5, name: p.name }; break; }
    }
    if (!to) {
      const ends: number[] = [];
      for (let i = 0; i < N * N; i += 5) if (seen[i] && far(i % N, Math.floor(i / N))) ends.push(i);
      const e = pick(ends, seed, w, 'seaEnd');
      if (e === null) return null;
      to = { x: w.ox + (e % N) + 0.5, z: w.oz + Math.floor(e / N) + 0.5, name: `the buoy off ${placeNear(w, e % N, Math.floor(e / N))}` };
    }
    site.to = to;
  }
  site.name = named(kind, 'S', place, site.to?.name);
  return site;
}
