/**
 * The journal (docs/missions.html, The journal): every mission in one place. The four threads across the
 * top — what the car, the fleet, the holdings and the towns stand at — then Offered, Underway and Done,
 * and the Passport. A list on the left, the one picked on the right with its hero turning, its steps,
 * what to do next, the arc it belongs to and what it gives.
 *
 * J opens and closes it (T too, for players who learned the old board); arrows move, Enter takes or
 * tracks, Backspace turns down or gives up.
 */
import { hero } from '../../render/heroStage';
import { REGIONS } from '../../world/regions';
import { THREAD_COLOUR, type Mission } from './model';
import { ARCS } from './templates';
import { story, type Chain } from '../story';
import { STANDING, clockText, isIntro, type Missions } from './missions';
import { MEDAL_ICON, MEDAL_NAME, medalled } from './medals';
import { detailsOf, requiredOf } from './text';
import { ARCHES, ARCH_LABEL, BIOMES } from './passport';
import { esc, objLine, rewardChips, threadChip } from './card';

type Tab = 'offered' | 'active' | 'done' | 'passport';
const TABS: Tab[] = ['offered', 'active', 'done', 'passport'];
const TAB_LABEL: Record<Tab, string> = { offered: 'Offered', active: 'Underway', done: 'Done', passport: 'Passport' };
const hex = (n: number) => `#${n.toString(16).padStart(6, '0')}`;

interface JournalHost {
  /** The four meters across the top. */
  meters(): { car: string; fleet: string; hold: string; town: string };
  far(m: Mission, o: Mission['objs'][number]): number | null;
  whyNot(m: Mission): string | null;
  accept(m: Mission): void;
  reject(m: Mission): void;
  abandon(m: Mission): void;
  showMe(m: Mission): void;
  /** Wonder kinds the world has, for the Passport's blanks: kind → name. */
  wonders(): Map<string, string>;
  /** A town's name from its key, for the standing list. */
  townName(key: string): string;
  hours(): number;
}

export class Journal {
  isOpen = false;
  private el = document.createElement('div');
  private tab: Tab = 'offered';
  /** Open the Passport book (docs/passport.html) at its sights; set by main. */
  openBook: (() => void) | null = null;
  private pick = new Map<Tab, number>();
  private thumbs = new Map<string, string>();
  private sig = '';
  /** "Skip the tutorial" pressed once: the detail asks to confirm. */
  private confirmSkip = false;

  constructor(private ms: Missions, private host: JournalHost) {
    this.el.id = 'journal';
    this.el.hidden = true;
    document.body.append(this.el);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    this.el.addEventListener('click', (e) => {
      const t = e.target as HTMLElement;
      const tab = t.closest<HTMLElement>('[data-tab]');
      if (tab) { this.tab = tab.dataset.tab as Tab; this.confirmSkip = false; this.render(true); return; }
      const it = t.closest<HTMLElement>('[data-id]');
      if (it) { this.pick.set(this.tab, Number(it.dataset.id)); this.confirmSkip = false; this.render(true); return; }
      const act = t.closest<HTMLElement>('[data-act]')?.dataset.act;
      if (act === 'book') { this.close(); this.openBook?.(); return; }
      if (act) this.act(act);
    });
    window.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      const list = this.items();
      const at = list.findIndex((m) => m.id === this.current()?.id);
      let used = true;
      switch (e.code) {
        case 'Escape': case 'KeyJ': this.close(); break;
        case 'ArrowDown': if (list.length) this.pick.set(this.tab, list[Math.min(list.length - 1, at + 1)].id); this.render(true); break;
        case 'ArrowUp': if (list.length) this.pick.set(this.tab, list[Math.max(0, at - 1)].id); this.render(true); break;
        case 'ArrowRight': this.tab = TABS[(TABS.indexOf(this.tab) + 1) % TABS.length]; this.render(true); break;
        case 'ArrowLeft': this.tab = TABS[(TABS.indexOf(this.tab) + TABS.length - 1) % TABS.length]; this.render(true); break;
        case 'Enter': case 'NumpadEnter': this.act(this.tab === 'offered' ? 'accept' : this.tab === 'active' ? 'track' : ''); break;
        case 'Backspace': case 'Delete': this.act(this.tab === 'offered' ? 'reject' : this.tab === 'active' ? 'abandon' : ''); break;
        default: used = false;
      }
      if (used) { e.preventDefault(); e.stopPropagation(); }
    }, true);
  }

  toggle(): void { if (this.isOpen) this.close(); else this.open(); }

  open(m?: Mission): void {
    if (m) {
      this.tab = m.state === 'offered' ? 'offered' : m.state === 'active' ? 'active' : 'done';
      this.pick.set(this.tab, m.id);
    } else if (!this.ms.offered.length && this.ms.active.length) this.tab = 'active';
    this.isOpen = true;
    this.el.hidden = false;
    this.render(true);
  }

  close(): void {
    this.confirmSkip = false;
    if (!this.isOpen) return;
    this.isOpen = false;
    this.el.hidden = true;
  }

  /** Called every frame: redraws only when something it shows has changed. */
  refresh(): void {
    if (!this.isOpen) return;
    this.render(false);
  }

  private items(): Mission[] {
    return this.tab === 'offered' ? this.ms.offered : this.tab === 'active' ? this.ms.active : this.tab === 'done' ? this.ms.finished : [];
  }

  private current(): Mission | null {
    const list = this.items();
    const id = this.pick.get(this.tab);
    return list.find((m) => m.id === id) ?? list[0] ?? null;
  }

  private act(a: string): void {
    const m = this.current();
    if (!m) return;
    // the tutorial's missions can't be turned down or given up one by one, but the whole tutorial can be skipped
    if (a === 'skip' || a === 'skipNo') { this.confirmSkip = a === 'skip' && isIntro(m.tpl); this.render(true); return; }
    if (a === 'skipYes') { this.confirmSkip = false; this.ms.skipTutorial(); this.tab = 'offered'; this.render(true); return; }
    this.confirmSkip = false;
    if (a === 'accept' && !this.host.whyNot(m)) { this.host.accept(m); this.tab = 'active'; this.pick.set('active', m.id); }
    else if (a === 'reject' && !isIntro(m.tpl)) this.host.reject(m);
    else if (a === 'abandon' && !isIntro(m.tpl)) this.host.abandon(m);
    else if (a === 'track') this.ms.track(m);
    else if (a === 'show') { this.close(); this.host.showMe(m); return; }
    this.render(true);
  }

  private thumb(m: Mission): string {
    const key = JSON.stringify(m.hero);
    let src = this.thumbs.get(key);
    if (!src) {
      try { src = hero.still(m.hero, THREAD_COLOUR[m.thread]); } catch { src = ''; }
      this.thumbs.set(key, src);
    }
    return src;
  }

  private render(force: boolean): void {
    const m = this.current();
    const sig = `${this.tab}|${m?.id}|${m?.step}|${m?.count}|${m?.state}|${this.ms.offered.length}|${this.ms.active.length}|${this.ms.finished.length}|${m?.tracked}|${this.confirmSkip}|${this.ms.learning()}`;
    if (!force && sig === this.sig) return;
    this.sig = sig;
    const meters = this.host.meters();
    const count = (t: Tab) => (t === 'passport' ? '' : ` <b>${t === 'offered' ? this.ms.offered.length : t === 'active' ? this.ms.active.length : this.ms.finished.length}</b>`);
    const bar = `<header class="jr-bar"><b class="jr-title">Journal</b>
      <span class="jr-m" style="--c:${hex(THREAD_COLOUR.car)}">Car <i>${esc(meters.car)}</i></span>
      <span class="jr-m" style="--c:${hex(THREAD_COLOUR.fleet)}">Fleet <i>${esc(meters.fleet)}</i></span>
      <span class="jr-m" style="--c:${hex(THREAD_COLOUR.hold)}">Holdings <i>${esc(meters.hold)}</i></span>
      <span class="jr-m" style="--c:${hex(THREAD_COLOUR.town)}">Towns <i>${esc(meters.town)}</i></span>
      <button type="button" class="jr-x" data-act="close" aria-label="Close">×</button></header>`;
    const tabs = `<nav class="jr-tabs">${TABS.map((t) => `<button type="button" data-tab="${t}" class="${t === this.tab ? 'on' : ''}">${TAB_LABEL[t]}${count(t)}</button>`).join('')}</nav>`;
    let cols: string;
    if (this.tab === 'passport') cols = this.passport();
    else {
      const list = this.items();
      const rows = list.length ? list.map((q) => {
        const sub = q.state === 'active' ? `${q.objs[q.step]?.label ?? ''}` : q.state === 'offered' ? (this.host.whyNot(q) ?? q.giver.name) : (q.outcome ?? '');
        return `<button type="button" class="jr-it ${q.id === m?.id ? 'on' : ''} ${q.state === 'failed' ? 'failed' : ''}" data-id="${q.id}">
          <img alt="" src="${this.thumb(q)}"><span><b>${esc(q.title)}${q.tracked ? ' <em>●</em>' : ''}</b><small>${threadChip(q)} ${esc(sub)}</small></span></button>`;
      }).join('') : `<p class="jr-none">${this.tab === 'offered' ? (this.ms.learning() ? 'Other work opens once the tutorial is done. To skip it, pick a tutorial mission under Underway.' : 'Nothing on offer here. Drive to a town: mayors, rivals and the mechanic all have work.') : this.tab === 'active' ? 'Nothing under way. Pick something from Offered.' : 'Nothing finished yet.'}</p>`;
      cols = `<div class="jr-cols"><div class="jr-list">${rows}</div><div class="jr-det">${m ? this.detail(m) : ''}</div></div>`;
    }
    this.el.innerHTML = `<div class="jr-panel">${bar}${tabs}${cols}<footer class="jr-keys"><kbd>←</kbd><kbd>→</kbd> tabs · <kbd>↑</kbd><kbd>↓</kbd> pick · <kbd>⏎</kbd> ${this.tab === 'offered' ? 'accept' : 'track'} · <kbd>⌫</kbd> ${this.tab === 'offered' ? 'reject' : 'give up'} · <kbd>J</kbd> close</footer></div>`;
    const slot = this.el.querySelector<HTMLElement>('.jr-hero');
    if (slot && m) { hero.mount(slot); hero.show(m.hero, THREAD_COLOUR[m.thread]); }
    this.el.querySelector('[data-act="close"]')?.addEventListener('click', () => this.close());
  }

  private detail(m: Mission): string {
    const objs = m.objs.map((o, k) => {
      const state = m.state === 'done' ? 'done' : m.state === 'offered' ? 'plain' : k < m.step ? 'done' : k === m.step ? 'now' : 'todo';
      const n = (o.t === 'deliver' || o.t === 'loads') && o.n > 1 && k === m.step && m.state === 'active' ? `${m.count}/${o.n}` : undefined;
      return objLine(o, state === 'done' ? null : this.host.far(m, o), state, n);
    }).join('');
    const arc = m.arc ? ARCS.find((a) => a.id === m.arc!.id) : null;
    const done = arc ? this.ms.arcs.get(arc.id) ?? 0 : 0;
    // a long story (docs/storychains.html) shows the act it is in, four dots and a faint fifth for what comes after
    const act = arc?.acts ? Math.floor(m.arc!.i / 4) : -1;
    const dots = arc ? (act >= 0 ? arc.tpls.slice(act * 4, act * 4 + 4).map((_, j) => act * 4 + j) : arc.tpls.map((_, k) => k)) : [];
    const strip = arc ? `<div class="jr-arc"><span>${esc(act >= 0 ? `${arc.title} · ${arc.acts![act]}` : arc.title)}</span>${dots.map((k) => `<i class="${k < done ? 'd' : k === m.arc!.i ? 'n' : ''}"></i>`).join('')}${act >= 0 && act < arc.acts!.length - 1 ? '<i class="f"></i>' : ''}</div>` : '';
    const sofar = act >= 0 ? story.soFar(arc!.id as Chain, 4) : [];
    const so = sofar.length ? `<div class="jr-sofar"><b>So far</b>${sofar.map((l) => `<p>${esc(l)}</p>`).join('')}</div>` : '';
    const why = m.state === 'offered' ? this.host.whyNot(m) : null;
    const next = m.state === 'active' ? `<p class="jr-next"><b>Next:</b> ${esc(this.ms.nextLine(m))}</p>` : '';
    const left = m.state === 'active' && m.due !== null ? ` · ⏱ ${Math.max(0, Math.round(m.due - this.host.hours()))} h` : '';
    const skip = isIntro(m.tpl) && (m.state === 'offered' || m.state === 'active') && this.ms.learning();
    const acts = skip && this.confirmSkip
      ? `<p class="mc-no">Skip the whole tutorial? Its missions end here, and other missions open up.</p><button type="button" class="yes" data-act="skipYes">Yes, skip it</button><button type="button" data-act="skipNo">Keep going</button>`
      : m.state === 'offered'
      ? `<button type="button" class="yes" data-act="accept" ${why ? 'disabled' : ''}>Accept <kbd>⏎</kbd></button>${isIntro(m.tpl) ? (skip ? '<button type="button" data-act="skip">Skip the tutorial</button>' : '') : '<button type="button" data-act="reject">Reject <kbd>⌫</kbd></button>'}`
      : m.state === 'active'
        ? `<button type="button" class="yes" data-act="track">${m.tracked ? 'Untrack' : 'Track'}</button><button type="button" data-act="show">Show me</button>${isIntro(m.tpl) ? (skip ? '<button type="button" data-act="skip">Skip the tutorial</button>' : '') : '<button type="button" data-act="abandon">Give up</button>'}`
        : '';
    return `<div class="jr-hero"><span class="mc-cap">${esc(m.caption)}</span></div>
      <div class="jr-info">
        <div class="mc-top">${threadChip(m)}<span class="mc-where">${esc(m.giver.name)}${m.giver.town && m.giver.town.name !== m.giver.name ? ` · ${esc(m.giver.town.name)}` : ''}${left}</span></div>
        <h3>${esc(m.title)}</h3><p class="mc-why">${esc(m.why)}</p>
        <details class="jr-more"><summary>More details</summary><p>${esc(detailsOf(m))}</p></details>
        ${requiredOf(m) ? `<p class="mc-need"><b>Required:</b> ${esc(requiredOf(m)!)}</p>` : ''}
        <ol class="mc-objs">${objs}</ol>${next}
        <div class="mc-rew">${rewardChips(m)}</div>${strip}${so}
        ${why ? `<p class="mc-no">${esc(why)}</p>` : ''}
        ${m.outcome && m.state !== 'active' ? `<p class="jr-out">${esc(m.outcome)}</p>` : ''}${this.medalLine(m)}
        <div class="mc-acts">${acts}</div>
      </div>`;
  }

  /** A delivery mission's medal times (missions/medals.ts): set at pickup, and the best won on this job. */
  private medalLine(m: Mission): string {
    if (!medalled(m)) return '';
    const n = m.notes, best = this.ms.medals.get(m.tpl);
    const bestText = best ? `Your best on this job: ${MEDAL_ICON[best]} ${MEDAL_NAME[best]}` : '';
    if (n?.mT !== undefined && n.mB !== undefined) {
      const so = m.state === 'active' ? (n.mX ? ' · no medal: airlifted' : ` · ${clockText(n.mT)} so far`) : '';
      return `<p class="mc-need"><b>Medal times:</b> 🥇 ${clockText(n.mG)} · 🥈 ${clockText(n.mS)} · 🥉 ${clockText(n.mB)}${so}${bestText ? `<br>${bestText}` : ''}</p>`;
    }
    return `<p class="mc-need"><b>Medal times</b> are set once the first load is aboard: beat them for a bonus.${bestText ? `<br>${bestText}` : ''}</p>`;
  }

  private passport(): string {
    const p = this.ms.passport;
    const stamp = (on: boolean, label: string, icon: string) => `<span class="pp-s ${on ? 'on' : ''}"><i>${on ? icon : '·'}</i>${esc(label)}</span>`;
    const biomes = BIOMES.map((b) => stamp(p.has('biome', b), REGIONS[b].title.replace(/^the /, ''), '🧭')).join('');
    const styles = ARCHES.map((a) => stamp(p.has('arch', a), ARCH_LABEL[a], '🏘️')).join('');
    const wonders = [...this.host.wonders()].map(([k, name]) => stamp(p.has('wonder', k), name, '🗿')).join('');
    const known = this.ms.rungsAll();
    const towns = known.length;
    return `<div class="pp">
      ${this.openBook ? '<p class="pp-sum"><button type="button" class="jr-book" data-act="book">Open the Passport ›</button> every stamp, where you first saw it, your bookmarks and your home town’s imports</p>' : ''}
      <p class="pp-sum"><b>${p.total()}</b> stamps · ${p.count('town')} towns visited · ${towns} know your name · ${p.count('ferry')} ferry crossings</p>
      <h4>Biomes</h4><div class="pp-grid">${biomes}</div>
      <h4>Styles</h4><div class="pp-grid">${styles}</div>
      <h4>Wonders</h4><div class="pp-grid">${wonders || '<span class="pp-none">None seen yet</span>'}</div>
      <h4>Standing</h4><div class="pp-grid">${known.map(({ key, rung }) => `<span class="pp-s on"><i>🤝</i>${esc(this.host.townName(key))} · ${STANDING[rung]}</span>`).join('') || '<span class="pp-none">No town knows you yet</span>'}</div>
    </div>`;
  }
}
