import { N, idx, inB, heightAt, DIRS, type Building, type World } from '../world/tiles';
import { hashString, mulberry32 } from '../world/rng';
import { runwaysOf } from '../world/runways';
import { padOf } from '../world/helipads';
import { storefronts } from '../world/storefronts';
import { VEHICLES, isHelicopter, isJet, type VehicleDef } from './vehicles';
import { priceOf } from './economy';

/**
 * Hidden vehicles: one county in four has a vehicle nobody has claimed, parked somewhere worth finding,
 * a soft glow on the ground under it. Drive up, press Tab, and it is the fleet's for good.
 *
 * Where it stands suits it when it can: a helicopter on a rooftop pad, a sports car in a circuit's
 * paddock, a tow truck round the back of the Auto Shop, a biplane at the end of an airstrip, a boat
 * tied up in a harbour. Otherwise it waits somewhere a traveller would go anyway: a wonder, a
 * lighthouse, a named peak, the highest ground in the county. Cheap models turn up far more often
 * than dear ones, but every one turns up somewhere. Pure: the same seed and cell always hide the same
 * thing in the same place; what has been claimed is saved.
 */

/** One county in this many has a vehicle hidden in it. */
export const STASH_ONE_IN = 4;
/** Cheap is common: a model's chance goes as its price to this power, negated. */
const RARITY = 0.7;
/**
 * Never hidden: the starter, the police's own car, and anything on rails. The military surplus models
 * (added later) stay out too, so adding them moved no existing world's hidden vehicle.
 */
// (the submarines were added after the hidden vehicles were placed: kept out so old worlds keep theirs)
// (and the hot air balloon, added 23 Oct 2026, for the same reason)
const NEVER = new Set(['tomato', 'patrol', 'humvee', 'tank', 'chinook', 'fighter', 'carrier', 'minisub', 'submarine', 'balloon',
  // the factions' own (docs/factions.html): earned, never found
  'interceptor', 'getaway', 'undertaker', 'statesman', 'saucerScout', 'mixer', 'bigHook', 'mailTruck', 'deuce', 'starTours', 'marquee', 'liveTruck', 'pelican', 'greyGull', 'northernLight', 'saucer', 'nightflyer', 'eyeInSky']);

/** The sort of place a hidden vehicle waits at. */
type SpotKind = 'pad' | 'circuit' | 'shop' | 'airfield' | 'mast' | 'harbour' | 'quarry' | 'beach' | 'wonder' | 'lighthouse'
  | 'cabin' | 'landmark' | 'summit' | 'hospital' | 'busStation';

export interface Stash {
  /** "cx,cz": one per county at most. */
  key: string;
  model: string;
  cx: number; cz: number;
  /** Where it stands, in the cell's own tiles, which way it faces, and the height to stand it at (a roof). */
  x: number; z: number; heading: number; y: number | null;
  spot: SpotKind;
  /** The place, plainly ("Mount Ashby", "the Harwick Auto Shop"): for the claim, never for a clue. */
  place: string;
  /** What a rumour says of where it is, without saying where ("up where the air gets thin in Dunmore"). */
  hint: string;
}

/** What people call it in a rumour: never its name. */
export function vehicleNoun(d: VehicleDef): string {
  switch (d.id) {
    case 'wrecker': return 'a tow truck';
    case 'postal': return 'a mail van';
    case 'bulldozer': return 'a bulldozer';
    case 'wasabi': return 'a sports car';
    case 'sunny': return 'a convertible';
    case 'limo': return 'a long black limousine';
    case 'cab': return 'a taxi';
    case 'bus': return 'a bus';
    case 'ambulance': return 'an ambulance';
    case 'dump': return 'a tipper truck';
    case 'atv': return 'a quad bike';
    case 'tank': return 'a tank';
    case 'humvee': return 'an army truck';
    case 'chinook': return 'an army helicopter';
    case 'fighter': return 'a fighter jet';
    case 'carrier': return 'an aircraft carrier';
    case 'hover': return 'a hovercraft';
    case 'duck': return 'an amphibious car';
    case 'bertha': case 'stomper': return 'a big truck';
    case 'mule': return 'a pickup';
    case 'marshmallow': return 'an airship';
    case 'barnstormer': return 'a biplane';
    case 'swift': case 'jumbo': return 'a jet';
    case 'bigblue': return 'a whole ship';
    case 'yacht': return 'a yacht';
    case 'riverboat': return 'a paddle steamer';
    case 'galleon': return 'a galleon';
    case 'jetski': return 'a jet ski';
    case 'rowboat': return 'a rowing boat';
    case 'airboat': return 'an airboat';
    case 'minisub': return 'a little submarine';
    case 'submarine': return 'a submarine';
    default:
      if (isHelicopter(d)) return 'a helicopter';
      if (d.kind === 'water') return 'a boat';
      if (d.kind === 'air') return 'an aircraft';
      return 'a car';
  }
}

/** Where each model likes to be found, best first; everything falls back to the traveller's places. */
function liking(d: VehicleDef): SpotKind[] {
  if (d.kind === 'water') return d.id === 'bigblue' || d.id === 'yacht' || d.id === 'riverboat' || d.id === 'galleon' || d.id === 'submarine' ? ['harbour'] : ['harbour', 'beach'];
  if (isJet(d)) return ['airfield'];
  if (isHelicopter(d)) return ['pad', 'hospital', 'summit'];
  if (d.id === 'marshmallow') return ['mast', 'airfield', 'summit'];
  if (d.kind === 'air') return ['airfield', 'summit'];
  switch (d.id) {
    case 'wrecker': return ['shop'];
    case 'postal': return ['shop', 'busStation'];
    case 'bulldozer': return ['quarry'];
    case 'wasabi': case 'sunny': return ['circuit', 'landmark'];
    case 'ambulance': return ['hospital'];
    case 'bus': return ['busStation'];
    case 'dump': case 'clod': case 'stomper': return ['quarry', 'summit'];
    case 'atv': case 'mule': return ['summit', 'landmark'];
    case 'hover': case 'duck': case 'sandy': return ['beach', 'harbour'];
    default: return [];
  }
}
const TRAVELLERS: SpotKind[] = ['wonder', 'lighthouse', 'landmark', 'cabin', 'summit'];

/** A spot found: where, facing which way, at what height (a roof), and what the place is called and hinted as. */
interface Found { x: number; z: number; heading: number; y: number | null; place: string; hint: string }

const land = (w: World, x: number, z: number): boolean => inB(x, z) && w.water[idx(x, z)] < 0;
const standable = (w: World, x: number, z: number): boolean => land(w, x, z) && !!w.edges[idx(x, z)] && !w.blocked[idx(x, z)];

/** The nearest tile a land vehicle can stand on within `r` of (px, pz), preferring off the road. */
export function standNear(w: World, px: number, pz: number, r: number, offRoad = true): { x: number; z: number } | null {
  let best: { x: number; z: number } | null = null, bestD = Infinity;
  const x0 = Math.floor(px), z0 = Math.floor(pz), R = Math.ceil(r);
  for (let z = z0 - R; z <= z0 + R; z++) {
    for (let x = x0 - R; x <= x0 + R; x++) {
      if (!standable(w, x, z)) continue;
      const d = Math.hypot(x + 0.5 - px, z + 0.5 - pz) + (offRoad && w.road[idx(x, z)] > 0 ? 1.5 : 0);
      if (d <= r + 1.5 && d < bestD) { bestD = d; best = { x: x + 0.5, z: z + 0.5 }; }
    }
  }
  return best;
}

/** Open water beside the shore within `r` of (px, pz), with room round it for a hull `size` tiles long. */
function mooringNear(w: World, px: number, pz: number, r: number, size: number): { x: number; z: number; heading: number } | null {
  let best: { x: number; z: number; heading: number } | null = null, bestD = Infinity;
  const x0 = Math.floor(px), z0 = Math.floor(pz), R = Math.ceil(r), room = Math.ceil(size);
  for (let z = z0 - R; z <= z0 + R; z++) {
    for (let x = x0 - R; x <= x0 + R; x++) {
      if (!inB(x, z) || w.water[idx(x, z)] < 0) continue;
      let clear = true;
      for (let dz = -room; dz <= room && clear; dz++) for (let dx = -room; dx <= room && clear; dx++) if (!inB(x + dx, z + dz) || w.water[idx(x + dx, z + dz)] < 0 || w.blocked[idx(x + dx, z + dz)]) clear = Math.hypot(dx, dz) > room;
      if (!clear) continue;
      // lying alongside the shore: bow along the nearest land's edge
      let shore = -1;
      for (let k = 0; k < 4; k++) {
        const [dx, dz] = DIRS[k];
        if (land(w, x + dx * (room + 1), z + dz * (room + 1))) { shore = k; break; }
      }
      if (shore < 0) continue;
      const d = Math.hypot(x + 0.5 - px, z + 0.5 - pz);
      if (d < bestD) { bestD = d; const [sx, sz] = DIRS[(shore + 1) % 4]; best = { x: x + 0.5, z: z + 0.5, heading: Math.atan2(sx, sz) }; }
    }
  }
  return best;
}

function allBuildings(w: World): Building[] {
  return [...w.allBuildings, ...w.countryside, ...w.works.flatMap((k) => k.buildings)].filter((b) => !b.gone);
}

const townOfB = (w: World, b: Building): string => {
  const t = w.towns.find((q) => q.buildings.includes(b));
  return t?.name ?? w.name;
};

/** Find a spot of a kind for this model in this cell, or null. */
function spotFor(w: World, d: VehicleDef, kind: SpotKind, rnd: () => number): Found | null {
  const air = d.kind === 'air', water = d.kind === 'water';
  const heading = rnd() * Math.PI * 2;
  const onLand = (px: number, pz: number, r: number, place: string, hint: string): Found | null => {
    const at = standNear(w, px, pz, r);
    return at ? { ...at, heading, y: null, place, hint } : null;
  };
  const county = w.name || 'these parts';
  switch (kind) {
    case 'pad': {
      if (!isHelicopter(d)) return null;
      const pads = allBuildings(w).map((b) => padOf(b)).filter((p): p is NonNullable<typeof p> => !!p);
      if (!pads.length) return null;
      const p = pads[Math.floor(rnd() * pads.length)];
      return { x: p.x, z: p.z, heading, y: p.y, place: `the roof of the ${p.b.kind === 'hospital' ? 'hospital' : 'tower'} in ${townOfB(w, p.b)}`, hint: `up on a rooftop pad in ${townOfB(w, p.b)}` };
    }
    case 'hospital': case 'busStation': {
      const bs = allBuildings(w).filter((b) => b.kind === (kind === 'hospital' ? 'hospital' : 'busStation'));
      if (!bs.length || air && !isHelicopter(d) || water) return null;
      const b = bs[Math.floor(rnd() * bs.length)];
      const what = kind === 'hospital' ? 'hospital' : 'bus station';
      return onLand(b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) / 2 + 3, `the ${what} in ${townOfB(w, b)}`, `round the back of the ${what} in ${townOfB(w, b)}`);
    }
    case 'circuit': {
      const b = allBuildings(w).find((q) => q.kind === 'raceCircuit' || q.kind === 'racetrack');
      if (!b || water || air) return null;
      return onLand(b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) / 2 + 2, 'the circuit', 'in the paddock, where the racing folk leave things');
    }
    case 'shop': {
      const s = storefronts(w, 'shop')[0];
      if (!s || water || air) return null;
      // round the back: the far side from its kerb
      const bx = s.b.x + s.b.w / 2, bz = s.b.z + s.b.d / 2;
      const [dx, dz] = DIRS[s.b.facing];
      return onLand(bx - dx * (s.b.w / 2 + 1), bz - dz * (s.b.d / 2 + 1), 2.5, `behind the ${s.t.name} Auto Shop`, `round the back of the Auto Shop in ${s.t.name}`);
    }
    case 'airfield': {
      if (water) return null;
      const rws = runwaysOf(w).filter((r) => !isJet(d) || (d.kind === 'air' && d.jet && r.len >= d.jet.runway));
      if (!rws.length) return null;
      const r = rws[Math.floor(rnd() * rws.length)];
      const st = r.stands[0];
      if (isJet(d)) return { x: st.x - w.ox, z: st.z - w.oz, heading: st.heading, y: null, place: r.name, hint: `on the apron at an airfield in ${county}` };
      // a light aircraft at the far end, off the strip
      const ex = r.bx - w.ox + r.sx * (r.half + 1.5), ez = r.bz - w.oz + r.sz * (r.half + 1.5);
      const at = standNear(w, ex, ez, 4);
      return at ? { ...at, heading: r.heading, y: null, place: r.name, hint: `at the far end of an airstrip in ${county}, past where anyone looks` } : null;
    }
    case 'mast': {
      const b = allBuildings(w).find((q) => q.kind === 'airshipMast');
      if (!b || water) return null;
      return onLand(b.x + b.w / 2, b.z + b.d / 2, 4, 'the airship mast', 'by the old mooring mast, where the airships used to tie up');
    }
    case 'harbour': {
      if (!water && !(d.kind === 'land' && (d.id === 'hover' || d.id === 'duck' || d.id === 'sandy'))) return null;
      const ports = [...w.ports].sort((a, b) => Number(b.major) - Number(a.major));
      for (const p of ports) {
        if (water && (d.halfLen ?? 0) > 1.2 && !p.major) continue;
        const rx = p.root % N, rz = (p.root - rx) / N;
        const [dx, dz] = DIRS[p.dir];
        if (water) {
          const m = mooringNear(w, rx + 0.5 + dx * 6, rz + 0.5 + dz * 6, 10, Math.max(1, d.halfLen ?? 1));
          if (m) return { ...m, y: null, place: p.name, hint: `tied up at the far end of the harbour at ${p.name.replace(/ (Harbour|Port|Docks)$/, '')}` };
        } else {
          const f = onLand(rx + 0.5, rz + 0.5, 6, p.name, `down on the quay at ${p.name}`);
          if (f) return f;
        }
      }
      return null;
    }
    case 'quarry': case 'beach': {
      if (air) return null;
      const s = w.spots.filter((q) => q.kind === kind);
      if (!s.length) return null;
      const q = s[Math.floor(rnd() * s.length)];
      if (water) {
        const m = mooringNear(w, q.x, q.z, q.r + 6, Math.max(1, d.halfLen ?? 1));
        return m ? { ...m, y: null, place: q.name, hint: `pulled up off the sands at ${q.name}` } : null;
      }
      return onLand(q.x, q.z, q.r + 2, q.name, kind === 'quarry' ? `down in the quarry pit at ${q.name}` : `on the sand at ${q.name}`);
    }
    case 'wonder': {
      const ws = w.works.filter((k) => k.kind === 'wonder');
      if (!ws.length || water) return null;
      const k = ws[Math.floor(rnd() * ws.length)];
      return onLand(k.x, k.z, 10, k.name, `in the shadow of ${k.name}`);
    }
    case 'lighthouse': case 'cabin': {
      const ps = w.pois.filter((p) => p.type === kind);
      if (!ps.length) return null;
      const p = ps[Math.floor(rnd() * ps.length)];
      if (water) {
        const m = kind === 'lighthouse' ? mooringNear(w, p.x, p.z, 8, Math.max(1, d.halfLen ?? 1)) : null;
        return m ? { ...m, y: null, place: 'the lighthouse', hint: 'moored under the old lighthouse' } : null;
      }
      return onLand(p.x, p.z, 4, kind === 'lighthouse' ? 'the lighthouse' : 'a cabin in the hills',
        kind === 'lighthouse' ? 'where the old lighthouse keeps watch' : `beside a lonely cabin somewhere out in ${county}`);
    }
    case 'landmark': {
      const ls = w.landmarks.filter((l) => l.name && land(w, Math.floor(l.x), Math.floor(l.z)));
      if (!ls.length || water) return null;
      const l = ls[Math.floor(rnd() * ls.length)];
      return onLand(l.x, l.z, Math.max(4, l.r * 0.5), l.name, `out by ${l.name}`);
    }
    case 'summit': {
      if (water) return null;
      let best: { x: number; z: number } | null = null, top = -Infinity;
      for (let z = 4; z < N - 4; z++) for (let x = 4; x < N - 4; x++) {
        if (!(air ? land(w, x, z) && !w.blocked[idx(x, z)] : standable(w, x, z))) continue;
        const h = heightAt(w, x + 0.5, z + 0.5);
        if (h > top) { top = h; best = { x: x + 0.5, z: z + 0.5 }; }
      }
      return best ? { ...best, heading, y: null, place: `the highest ground in ${county}`, hint: `up where the air gets thin, the highest ground in ${county}` } : null;
    }
  }
}

/** The hidden vehicle of a county, if it has one. */
export function placeStash(w: World): Stash | null {
  const key = `${w.cx},${w.cz}`;
  const h = hashString(`stash|${w.seed}|${key}`);
  if (h % STASH_ONE_IN !== 0) return null;
  const rnd = mulberry32(h ^ 0x5eed);
  const pool = VEHICLES.filter((d) => !NEVER.has(d.id));
  const weight = (d: VehicleDef) => Math.max(300, priceOf(d.id)) ** -RARITY;
  // a few tries: a model that has nowhere to stand here gives way to another
  const tried = new Set<string>();
  for (let k = 0; k < 8; k++) {
    const left = pool.filter((d) => !tried.has(d.id));
    if (!left.length) break;
    let r = rnd() * left.reduce((s, d) => s + weight(d), 0);
    let d = left[0];
    for (const q of left) { if ((r -= weight(q)) < 0) { d = q; break; } }
    tried.add(d.id);
    for (const kind of [...liking(d), ...(d.kind === 'water' || isJet(d) ? [] : TRAVELLERS)]) {
      const f = spotFor(w, d, kind, rnd);
      if (f) return { key, model: d.id, cx: w.cx, cz: w.cz, ...f, spot: kind };
    }
  }
  return null;
}
