import * as THREE from 'three';

/**
 * Eight little looping cartoons for the world's screens (game/screens.ts): the drive-in's feature and the
 * video billboards at a megalopolis's busiest crossings. Each is drawn on a small canvas of its own and
 * shared by every screen showing it; only the ones on screen are drawn, about a dozen times a second.
 */

const W = 128, H = 72;
const FPS = 12;

type Draw = (g: CanvasRenderingContext2D, t: number) => void;

const sky = (g: CanvasRenderingContext2D, top: string, bottom: string, h = H) => {
  const s = g.createLinearGradient(0, 0, 0, h);
  s.addColorStop(0, top);
  s.addColorStop(1, bottom);
  g.fillStyle = s;
  g.fillRect(0, 0, W, h);
};
const circle = (g: CanvasRenderingContext2D, x: number, y: number, r: number, c: string) => { g.fillStyle = c; g.beginPath(); g.arc(x, y, r, 0, Math.PI * 2); g.fill(); };

/** A car down a country road, the dashes rushing at the camera. */
const road: Draw = (g, t) => {
  sky(g, '#7fc4f0', '#cfeaf7', 34);
  g.fillStyle = '#6fb55a'; g.fillRect(0, 34, W, H - 34);
  g.fillStyle = '#9aa0a6';
  g.beginPath(); g.moveTo(W / 2 - 4, 34); g.lineTo(W / 2 + 4, 34); g.lineTo(W / 2 + 60, H); g.lineTo(W / 2 - 60, H); g.fill();
  g.fillStyle = '#fff6c8';
  for (let k = 0; k < 6; k++) {
    const p = ((k / 6 + t * 0.9) % 1), y = 34 + p * p * (H - 34), w = 1 + p * 4, h = 1 + p * 7;
    g.fillRect(W / 2 - w / 2, y, w, h);
  }
  for (let k = 0; k < 4; k++) {                                // trees going by
    const p = ((k / 4 + t * 0.6) % 1), y = 34 + p * p * (H - 34), x = W / 2 + (k % 2 ? 1 : -1) * (14 + p * 70), s = 2 + p * 12;
    g.fillStyle = '#2f7a3e'; g.beginPath(); g.moveTo(x, y - s * 1.6); g.lineTo(x + s * 0.6, y); g.lineTo(x - s * 0.6, y); g.fill();
  }
  const bob = Math.sin(t * 9) * 0.6;                           // the car, from behind
  g.fillStyle = '#e2412f'; g.fillRect(W / 2 - 13, 50 + bob, 26, 11);
  g.fillStyle = '#b8322a'; g.fillRect(W / 2 - 9, 44 + bob, 18, 7);
  g.fillStyle = '#1f2b33'; g.fillRect(W / 2 - 12, 60 + bob, 6, 4); g.fillRect(W / 2 + 6, 60 + bob, 6, 4);
  g.fillStyle = '#ffd24a'; g.fillRect(W / 2 - 12, 53 + bob, 3, 2); g.fillRect(W / 2 + 9, 53 + bob, 3, 2);
};

/** Windmills turning over a field of tulips. */
const windmills: Draw = (g, t) => {
  sky(g, '#8fd0f5', '#e8f6fb', 46);
  g.fillStyle = '#7cc061'; g.fillRect(0, 46, W, H - 46);
  for (let x = 0; x < W; x += 6) { g.fillStyle = ['#e2412f', '#f2c14e', '#e86aa8'][(x / 6) % 3]; g.fillRect(x, 54 + ((x / 6) % 2) * 6, 4, 3); }
  circle(g, 104, 14, 7, '#fff3b0');
  for (const [x, s, ph] of [[34, 1, 0], [84, 0.75, 1.3]] as const) {
    g.fillStyle = '#b06a3a';
    g.beginPath(); g.moveTo(x - 7 * s, 50); g.lineTo(x + 7 * s, 50); g.lineTo(x + 4 * s, 24 * s + (1 - s) * 30); g.lineTo(x - 4 * s, 24 * s + (1 - s) * 30); g.fill();
    const hx = x, hy = 24 * s + (1 - s) * 30;
    g.strokeStyle = '#f4f2ec'; g.lineWidth = 3 * s;
    for (let k = 0; k < 4; k++) {
      const a = t * 2.2 + ph + k * Math.PI / 2;
      g.beginPath(); g.moveTo(hx, hy); g.lineTo(hx + Math.cos(a) * 20 * s, hy + Math.sin(a) * 20 * s); g.stroke();
    }
    circle(g, hx, hy, 2 * s, '#5d3a22');
  }
};

/** A goal: the ball passed up the pitch and into the net, the crowd's flags going up. */
const soccer: Draw = (g, t) => {
  g.fillStyle = '#3f9b4a'; g.fillRect(0, 0, W, H);
  for (let x = 0; x < W; x += 16) { g.fillStyle = '#48a854'; g.fillRect(x, 0, 8, H); }
  g.strokeStyle = '#f4f2ec'; g.lineWidth = 1.5; g.strokeRect(4, 6, W - 8, H - 12); g.strokeRect(W - 22, 22, 18, 28);
  const p = (t % 4) / 4;
  const players: [number, number][] = [[20, 40], [48, 26], [76, 46], [100, 34]];
  const leg = Math.min(2.999, p * 4), i = Math.floor(leg), f = leg - i;
  const a = players[i], b = i < 3 ? players[i + 1] : [W - 8, 36] as [number, number];
  for (const [k, [x, y]] of players.entries()) {
    circle(g, x, y - 6, 3, '#f2c9a0');
    g.fillStyle = k % 2 ? '#2f5fb5' : '#e2412f'; g.fillRect(x - 3, y - 3, 6, 8);
  }
  const bx = a[0] + (b[0] - a[0]) * f, by = a[1] + (b[1] - a[1]) * f - Math.sin(f * Math.PI) * 8;
  circle(g, bx, by, 2.5, '#ffffff');
  if (p > 0.92) { g.fillStyle = '#ffd24a'; g.font = 'bold 18px sans-serif'; g.fillText('GOAL!', 34, 24); }
};

/** Cars lapping an oval, nose to tail. */
const racing: Draw = (g, t) => {
  g.fillStyle = '#5fa04a'; g.fillRect(0, 0, W, H);
  g.strokeStyle = '#4a4f55'; g.lineWidth = 12;
  g.beginPath(); g.ellipse(W / 2, H / 2, 48, 22, 0, 0, Math.PI * 2); g.stroke();
  g.strokeStyle = '#f4f2ec'; g.lineWidth = 1; g.setLineDash([3, 3]);
  g.beginPath(); g.ellipse(W / 2, H / 2, 48, 22, 0, 0, Math.PI * 2); g.stroke(); g.setLineDash([]);
  ['#e2412f', '#2f5fb5', '#f2c14e', '#2bb3a3'].forEach((c, k) => {
    const a = t * (1.6 + k * 0.07) - k * 0.45;
    const x = W / 2 + Math.cos(a) * 48, y = H / 2 + Math.sin(a) * 22;
    g.save(); g.translate(x, y); g.rotate(Math.atan2(Math.cos(a) * 22, -Math.sin(a) * 48));
    g.fillStyle = c; g.fillRect(-4, -2.5, 8, 5); g.restore();
  });
};

/** The sun going down over the sea, the waves rolling in. */
const sunset: Draw = (g, t) => {
  sky(g, '#f2794e', '#ffd28a', 40);
  const sy = 26 + ((t * 2) % 30) * 0.2;
  circle(g, W / 2, sy, 11, '#fff1b0');
  g.fillStyle = '#2f6f9c'; g.fillRect(0, 40, W, H - 40);
  g.fillStyle = 'rgba(255,240,180,0.6)';
  for (let k = 0; k < 6; k++) g.fillRect(W / 2 - 14 + Math.sin(t * 2 + k) * 4, 42 + k * 4, 28 - k * 3, 1.5);
  g.fillStyle = '#e6cf93';
  g.beginPath(); g.moveTo(0, H); g.lineTo(0, 62); for (let x = 0; x <= W; x += 8) g.lineTo(x, 62 + Math.sin(x * 0.2 + t * 3) * 2); g.lineTo(W, H); g.fill();
};

/** Fireworks bursting over a night skyline. */
const fireworks: Draw = (g, t) => {
  sky(g, '#0b1430', '#26325c');
  for (let k = 0; k < 3; k++) {
    const cyc = (t * 0.6 + k / 3) % 1, x = 24 + k * 40, y = 18 + (k % 2) * 8;
    const col = ['#ffd24a', '#e86aa8', '#6fd3ee'][k];
    if (cyc < 0.25) circle(g, x, H - cyc * 4 * (H - y), 1.2, '#fff');
    else {
      const r = (cyc - 0.25) * 34, a = 1 - (cyc - 0.25) / 0.75;
      g.globalAlpha = Math.max(0, a);
      for (let s = 0; s < 12; s++) circle(g, x + Math.cos(s * 0.52) * r, y + Math.sin(s * 0.52) * r + (cyc - 0.25) * 6, 1.3, col);
      g.globalAlpha = 1;
    }
  }
  g.fillStyle = '#05080f';
  [[0, 44, 14], [14, 36, 10], [24, 50, 16], [40, 30, 9], [49, 42, 18], [67, 34, 12], [79, 48, 14], [93, 28, 11], [104, 40, 24]]
    .forEach(([x, y, w]) => g.fillRect(x, y, w, H - y));
  g.fillStyle = '#ffd98a';
  for (let k = 0; k < 40; k++) { const x = (k * 37) % W, y = 34 + ((k * 53) % 34); if (((k * 7 + Math.floor(t)) % 5) > 1) g.fillRect(x, y, 1.5, 1.5); }
};

/** Fish swimming through the weed, bubbles going up. */
const fish: Draw = (g, t) => {
  sky(g, '#3fb3d8', '#105d86');
  g.strokeStyle = '#3f9b4a'; g.lineWidth = 3;
  for (let x = 8; x < W; x += 22) { g.beginPath(); g.moveTo(x, H); for (let y = H; y > 34; y -= 6) g.lineTo(x + Math.sin(y * 0.2 + t * 2) * 3, y); g.stroke(); }
  ([[0.5, 24, '#f2a93b', 1], [0.35, 42, '#e86aa8', 0.8], [0.6, 56, '#ffd24a', 0.7]] as const).forEach(([sp, y, c, s], k) => {
    const x = ((t * sp * 40 + k * 50) % (W + 30)) - 15;
    g.fillStyle = c;
    g.beginPath(); g.ellipse(x, y, 8 * s, 5 * s, 0, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.moveTo(x - 7 * s, y); g.lineTo(x - 13 * s, y - 5 * s); g.lineTo(x - 13 * s, y + 5 * s); g.fill();
    circle(g, x + 4 * s, y - 1, 1.2, '#1f2b33');
  });
  for (let k = 0; k < 6; k++) circle(g, 20 + k * 19, H - ((t * 18 + k * 13) % H), 1.4, 'rgba(255,255,255,0.7)');
};

/** A rocket off the pad, the smoke billowing. */
const rocket: Draw = (g, t) => {
  const p = (t % 6) / 6;
  sky(g, '#1d2a58', '#7fb6e8');
  g.fillStyle = '#8a8f96'; g.fillRect(0, 60, W, H - 60);
  const y = 44 - Math.max(0, p - 0.15) ** 2 * 120;
  for (let k = 0; k < 7; k++) circle(g, W / 2 + Math.sin(k * 2.1 + t * 3) * (4 + k * 2), y + 18 + k * 4, 4 + k * 1.2, `rgba(240,240,240,${0.85 - k * 0.1})`);
  circle(g, W / 2, y + 14, 3.5, '#ffb43a');
  g.fillStyle = '#f4f2ec'; g.fillRect(W / 2 - 4, y - 6, 8, 18);
  g.fillStyle = '#e2412f'; g.beginPath(); g.moveTo(W / 2 - 4, y - 6); g.lineTo(W / 2, y - 14); g.lineTo(W / 2 + 4, y - 6); g.fill();
  g.fillRect(W / 2 - 7, y + 7, 3, 5); g.fillRect(W / 2 + 4, y + 7, 3, 5);
};

/** The eight, in the order the billboards cycle them. */
export const REELS: { id: string; draw: Draw }[] = [
  { id: 'road', draw: road }, { id: 'windmills', draw: windmills }, { id: 'soccer', draw: soccer }, { id: 'racing', draw: racing },
  { id: 'sunset', draw: sunset }, { id: 'fireworks', draw: fireworks }, { id: 'fish', draw: fish }, { id: 'rocket', draw: rocket },
];

interface Reel { canvas: HTMLCanvasElement; g: CanvasRenderingContext2D; tex: THREE.CanvasTexture; wanted: boolean; t: number }

/** The canvases and textures, one per cartoon, made the first time each is shown. */
export class Reels {
  private reels = new Map<number, Reel>();
  private time = 0;
  private acc = 0;

  /** The texture showing cartoon `i` (0–7), to put on a screen. */
  texture(i: number): THREE.Texture {
    let r = this.reels.get(i);
    if (!r) {
      const canvas = document.createElement('canvas');
      canvas.width = W; canvas.height = H;
      const g = canvas.getContext('2d')!;
      const tex = new THREE.CanvasTexture(canvas);
      tex.colorSpace = THREE.SRGBColorSpace;
      r = { canvas, g, tex, wanted: true, t: 0 };
      REELS[i].draw(g, 0);
      tex.needsUpdate = true;
      this.reels.set(i, r);
    }
    return r.tex;
  }

  /** Cartoon `i` is on a screen somebody could see this frame. */
  want(i: number): void { const r = this.reels.get(i); if (r) r.wanted = true; }

  /** Draw the next frame of every cartoon wanted since the last one. */
  update(dt: number): void {
    this.time += dt;
    this.acc += dt;
    if (this.acc < 1 / FPS) return;
    this.acc = 0;
    for (const [i, r] of this.reels) {
      if (!r.wanted) continue;
      r.wanted = false;
      REELS[i].draw(r.g, this.time);
      r.tex.needsUpdate = true;
    }
  }

  dispose(): void {
    for (const r of this.reels.values()) r.tex.dispose();
    this.reels.clear();
  }
}
