import * as THREE from 'three';
import { N, SEA, STEP } from '../world/tiles';
import { geologyFor } from '../world/geology';
import { hex, mix, type RGB } from '../world/biomes';

/** Tiles between the samples of a distant county's silhouette. */
const S = 16;
/** Counties either way of the focus the ring reaches. */
const REACH = 4;

/** Distant ground wears the air's colour: everything on the skyline is pulled this far toward it. */
const HAZE = hex(0xa9bccb), HAZE_SHARE = 0.45;
const LOW = hex(0x8e9a7c), ROCK = hex(0x8a8580), SNOW = hex(0xeef2f5), TABLE = hex(0xc4a878);

/**
 * Big country on the horizon: only the counties round the camera are in memory, so a great range or a
 * tableland two or three counties off would not exist until you were nearly on it. This draws the high
 * country beyond them as a coarse, fogged silhouette straight from the geology's own fields, so a range
 * is on the skyline long before you reach it. Lowland is left out: at that distance it is fog.
 */
export class Horizon {
  readonly root = new THREE.Group();
  private built = new Map<string, THREE.Mesh | null>();
  private queue: [number, number][] = [];
  private seed = -1;
  private material = new THREE.MeshLambertMaterial({ vertexColors: true });

  constructor() { this.root.name = 'horizon'; }

  /** A new world: forget every silhouette. */
  reset(seedHash: number): void {
    if (seedHash === this.seed) return;
    this.seed = seedHash;
    for (const m of this.built.values()) if (m) { this.root.remove(m); m.geometry.dispose(); }
    this.built.clear();
    this.queue = [];
  }

  /**
   * Keep the ring round county (cx, cz): silhouettes for counties within REACH, none for the ones in
   * memory (`resident` says which), and build a county's silhouette a frame at a time.
   */
  update(cx: number, cz: number, resident: (x: number, z: number) => boolean): void {
    if (this.seed < 0) return;
    this.queue = [];
    for (const [key, m] of this.built) {
      const [x, z] = key.split(',').map(Number);
      const keep = Math.max(Math.abs(x - cx), Math.abs(z - cz)) <= REACH + 1;
      if (m) m.visible = keep && !resident(x, z);
      if (!keep) { if (m) { this.root.remove(m); m.geometry.dispose(); } this.built.delete(key); }
    }
    for (let dz = -REACH; dz <= REACH; dz++) {
      for (let dx = -REACH; dx <= REACH; dx++) {
        const x = cx + dx, z = cz + dz;
        if (!this.built.has(`${x},${z}`) && !resident(x, z)) this.queue.push([x, z]);
      }
    }
    this.queue.sort((a, b) => Math.hypot(a[0] - cx, a[1] - cz) - Math.hypot(b[0] - cx, b[1] - cz));
    const next = this.queue.shift();
    if (next) this.build(next[0], next[1]);
  }

  private build(cx: number, cz: number): void {
    const geo = geologyFor(this.seed);
    const key = `${cx},${cz}`;
    // a quick look first: most counties have no high country to show
    let any = false;
    for (let k = 0; k < 9 && !any; k++) any = geo.uplift((cx + 0.1 + 0.4 * (k % 3)) * N, (cz + 0.1 + 0.4 * Math.floor(k / 3)) * N) > 0.04;
    if (!any || !geo.on) { this.built.set(key, null); return; }
    const M = N / S + 1;
    const h = new Float32Array(M * M), col: RGB[] = [];
    const ranges = geo.rangesNear(cx * N, cz * N, cx * N + N, cz * N + N);
    let high = false;
    for (let j = 0; j < M; j++) {
      for (let i = 0; i < M; i++) {
        const gx = cx * N + i * S, gz = cz * N + j * S;
        const U = geo.uplift(gx, gz);
        let e = 1.1 + geo.lift(gx, gz, U), c = LOW;
        const r = geo.rangeAt(ranges, gx, gz);
        if (r.m > e) { e = r.m; c = ROCK; }
        if (U > 0.1) {
          const p = geo.plateauAt(gx, gz);
          if (p.m > e) { e = p.m; c = TABLE; }
        }
        const y = SEA + e;
        if (e > 30 && c === ROCK) c = mix(ROCK, SNOW, Math.min(1, (y - (19 + 14 * U + 22 * U)) / 6));
        if (y > SEA + 12) high = true;
        h[j * M + i] = y;
        col.push(c);
      }
    }
    if (!high) { this.built.set(key, null); return; }
    const pos: number[] = [], cols: number[] = [];
    // one vertex per sample, coloured by its own ground and hazed, so the skyline shades smoothly
    for (let j = 0; j < M; j++) {
      for (let i = 0; i < M; i++) {
        pos.push(cx * N + i * S, h[j * M + i] * STEP - 0.4, cz * N + j * S);
        const c = mix(col[j * M + i], HAZE, HAZE_SHARE);
        cols.push(c[0], c[1], c[2]);
      }
    }
    const index: number[] = [];
    for (let j = 0; j < M - 1; j++) {
      for (let i = 0; i < M - 1; i++) {
        const a = j * M + i, b = a + 1, c = a + M, d = c + 1;
        index.push(a, c, b, b, c, d);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
    g.setIndex(index);
    g.computeVertexNormals();
    const mesh = new THREE.Mesh(g, this.material);
    mesh.receiveShadow = false;
    mesh.castShadow = false;
    this.root.add(mesh);
    this.built.set(key, mesh);
  }
}
