import * as THREE from 'three';
import { N, STEP, World, heightAt, type Building, type Town } from '../world/tiles';
import { buildTownChunk } from './townMesh';

/**
 * One building drawn alone, and where its own model tops out: the pennants on owned and rival-held roofs
 * stand there. They had stood on the lot's corner at the building's nominal height, which floats in the air
 * beside anything that is not a box filling its lot (Coit Tower, a domed hall, a pitched roof; the user,
 * 22 Oct 2026).
 */

let scratch: World | null = null;
/** Where the building stands on the scratch island, in tiles, and the level of its flat ground. */
export const ALONE_AT = 4;
const ALONE_LEVEL = 4;

/**
 * The building's model as the mesher draws it, alone on a flat scratch island at (ALONE_AT, ALONE_AT) and level
 * ALONE_LEVEL, in its own town's kind and style (or as countryside), or null when nothing could be drawn. The
 * caller lets the group go with `letGo`.
 */
export function drawAlone(w: World, b: Building): THREE.Group | null {
  if (!scratch) {
    scratch = new World();
    scratch.corners.fill(ALONE_LEVEL);
  }
  const home = w.towns.find((t) => t.buildings.includes(b)) ?? null;
  // drawn finished: the mesher leaves out a building still going up (townMesh.ts builtShare < 1), so a copy of a site
  // drew nothing and every construction site stood as a low box with no cranes (the user, 6 Nov 2026)
  const lone: Building = { ...b, x: ALONE_AT, z: ALONE_AT, level: ALONE_LEVEL, uid: 0, gone: false, grownAt: undefined, buildHours: undefined };
  const size = ALONE_AT + Math.max(b.w, b.d) + 2;
  const t: Town = home
    ? { ...home, x0: 0, z0: 0, size, level: ALONE_LEVEL, buildings: [lone], claims: undefined }
    : { id: 0, kind: 'suburb', name: 'Site', x0: 0, z0: 0, size, level: ALONE_LEVEL, style: b.style ?? 'classic', buildings: [lone], roads: 0, entry: [] };
  // a building of no town (the country, a port, the works) is drawn as the country draws it
  if (home) { scratch.towns = [t]; scratch.countryside = []; }
  else { scratch.towns = []; scratch.countryside = [lone]; }
  scratch.allBuildings = [lone];
  let g: THREE.Group | null = null;
  try { g = buildTownChunk(scratch, 0, 0); } catch { g = null; }
  scratch.towns = [];
  scratch.countryside = [];
  scratch.allBuildings = [];
  g?.updateMatrixWorld(true);
  return g;
}

/** Fresh geometry dropped, and a windmill's sails out of the spinners' list. */
export function letGo(g: THREE.Group): void {
  const all: THREE.Object3D[] = [];
  g.traverse((o) => { all.push(o); });
  for (const o of all) {
    if ((o as THREE.Mesh).isMesh) (o as THREE.Mesh).geometry.dispose();
    o.removeFromParent();
  }
}

/** The ground height under the lone building's pad, in world units. */
export const ALONE_BASE = ALONE_LEVEL * STEP;

/** A point on a building's own roof: tiles from the lot's corner (x, z), and world units above its pad (y). */
interface RoofTop { x: number; z: number; y: number }

/** Highest points within this of the very top count as the top (a flat roof, a ridge), the most central of them chosen. */
const TIE = 0.03;

/**
 * The highest point of the building's standing model (its moving parts left out: a sail turns away), the one
 * nearest the middle of the lot when several are about as high, so a flat roof gets its middle and a pitched
 * one its ridge. Null when the model has nothing on its lot.
 */
function measure(w: World, b: Building): RoofTop | null {
  const g = drawAlone(w, b);
  if (!g) return null;
  const x0 = ALONE_AT, z0 = ALONE_AT, x1 = x0 + b.w, z1 = z0 + b.d, mx = (x0 + x1) / 2, mz = (z0 + z1) / 2;
  const pts: number[] = [];
  let top = -Infinity;
  const a = new THREE.Vector3(), c = new THREE.Vector3(), d = new THREE.Vector3(), p = new THREE.Vector3();
  const take = (v: THREE.Vector3) => {
    if (v.x < x0 || v.x > x1 || v.z < z0 || v.z > z1) return;
    pts.push(v.x, v.y, v.z);
    if (v.y > top) top = v.y;
  };
  // the standing model only: the moving parts are groups of their own under the kit's group
  for (const o of g.children) {
    const m = o as THREE.Mesh;
    if (!m.isMesh || (m as unknown as THREE.InstancedMesh).isInstancedMesh) continue;
    const pos = m.geometry.getAttribute('position');
    if (!pos) continue;
    const index = m.geometry.index;
    const n = index ? index.count : pos.count;
    for (let i = 0; i + 2 < n; i += 3) {
      a.fromBufferAttribute(pos, index ? index.getX(i) : i).applyMatrix4(m.matrixWorld);
      c.fromBufferAttribute(pos, index ? index.getX(i + 1) : i + 1).applyMatrix4(m.matrixWorld);
      d.fromBufferAttribute(pos, index ? index.getX(i + 2) : i + 2).applyMatrix4(m.matrixWorld);
      // the corners, the edges' middles and the middle: a ridge or a flat roof has a point near its centre
      take(a); take(c); take(d);
      take(p.copy(a).add(c).multiplyScalar(0.5));
      take(p.copy(c).add(d).multiplyScalar(0.5));
      take(p.copy(d).add(a).multiplyScalar(0.5));
      take(p.copy(a).add(c).add(d).divideScalar(3));
    }
  }
  letGo(g);
  if (!pts.length || top - ALONE_BASE < 0.02) return null;
  let best = -1, bestD = Infinity;
  for (let i = 0; i < pts.length; i += 3) {
    if (pts[i + 1] < top - TIE) continue;
    const dd = (pts[i] - mx) ** 2 + (pts[i + 2] - mz) ** 2;
    if (dd < bestD) { bestD = dd; best = i; }
  }
  return { x: pts[best] - x0, z: pts[best + 2] - z0, y: pts[best + 1] - ALONE_BASE };
}

/** Measured tops, by everything that shapes the model. */
const tops = new Map<string, RoofTop | null>();
const TOPS_KEEP = 600;

function sig(w: World, b: Building): string {
  const t = w.towns.find((q) => q.buildings.includes(b));
  return `${b.kind}|${b.w}x${b.d}|${b.facing}|${b.floors}|${b.seed}|${b.style ?? ''}|${t ? `${t.kind}/${t.style ?? ''}` : '-'}|${b.solid ? 1 : 0}`;
}

/** Milliseconds of measuring left in this pass (roofBudget): a town of new pennants is measured over a few seconds. */
let budget = Infinity;
/** Start a pass of pennants with this many milliseconds to measure new roofs in. */
export function roofBudget(ms: number): void { budget = ms; }

/**
 * Where a pennant's pole stands on this building, in world units (into `out`); a lot with nothing standing on
 * it, its ground at the corner. False when the roof is still to be measured and this pass has no time left.
 */
/**
 * The very top of a building's own model in world units, measured now whatever this pass's budget (an event's
 * tower: its ball's mast and its fireworks go up from here, game/events/stage.ts); null for nothing standing.
 */
export function roofTopAt(w: World, b: Building): THREE.Vector3 | null {
  if (!b.solid) return null;
  const k = sig(w, b);
  let r = tops.get(k);
  if (r === undefined) {
    r = measure(w, b);
    if (tops.size >= TOPS_KEEP) tops.delete(tops.keys().next().value!);
    tops.set(k, r);
  }
  return r ? new THREE.Vector3(w.ox + b.x + r.x, b.level * STEP + r.y, w.oz + b.z + r.z) : null;
}

export function pennantAt(w: World, b: Building, corner: 'nw' | 'ne', out: { set(x: number, y: number, z: number): unknown }): boolean {
  if (b.solid) {
    const k = sig(w, b);
    let r = tops.get(k);
    if (r === undefined) {
      if (budget <= 0) return false;
      const t0 = performance.now();
      r = measure(w, b);
      budget -= performance.now() - t0;
      if (tops.size >= TOPS_KEEP) tops.delete(tops.keys().next().value!);
      tops.set(k, r);
    }
    if (r) { out.set(w.ox + b.x + r.x, b.level * STEP + r.y, w.oz + b.z + r.z); return true; }
  }
  const gx = Math.min(N - 0.01, corner === 'nw' ? b.x + 0.2 : b.x + b.w - 0.2), gz = Math.min(N - 0.01, b.z + 0.2);
  out.set(w.ox + gx, Math.max(b.level * STEP, heightAt(w, gx, gz)) + 0.02, w.oz + gz);
  return true;
}
