import * as THREE from 'three';

/**
 * Routes (docs/supplychains.html, "Routes"): a fleet vehicle told to run a fixed line or loop of doors. The expert's
 * tool for a supply chain: a Big Bertha circling cabin, sawmill and paper mill, a Sundae between the creamery and the
 * beach. Jets never run one (the user, 7 Nov 2026: they take no part in chains).
 *
 * How it drives: a route vehicle's base is its next stop (Fleet.base), and it goes there as soon as it has nothing to
 * do (Fleet.idleLimit 0). At a stop it takes the loads waiting there that are bound for one of its other stops (the
 * fleet's own made loads first), packs them with the manifest solver, and the run drops each where it goes; then on to
 * the next stop. With nothing to take it moves on, unless Hold is on and the plant there finishes a run within a
 * minute. A loop goes round; a line runs out and back.
 */

export interface RouteStop {
  /** The door's deed key (cx,cz#b<uid>), its name, and where its goods are picked up, in world tiles. */
  key: string; name: string;
  x: number; z: number; y: number;
  cx: number; cz: number;
}

export interface RouteOrder {
  stops: RouteStop[];
  /** Round and round (true) or out and back (false). */
  loop: boolean;
  /** The stop it is making for, and which way along a line it is going. */
  i: number; dir: 1 | -1;
  /** Wait at a plant whose run finishes within a minute, rather than leave with nothing. */
  hold: boolean;
  /** Laps (a loop round, or a line out and back) since it was set. */
  laps: number;
}

export const ROUTE = {
  /** Tiles from a stop's kerb a vehicle counts as there. */
  arrive: 8,
  /** Tiles from a stop a waiting load is taken from. */
  pick: 7,
  /** A load bound within this many tiles of another stop counts as bound for that stop. */
  near: 12,
  /** Stops at most, and the widest a route may spread (tiles between any two stops). */
  most: 8,
  span: 600,
  /** Most loads one stop's run packs. */
  loads: 6,
};

/** The stop a route is making for. */
export const targetOf = (r: RouteOrder): RouteStop | null => r.stops[Math.max(0, Math.min(r.stops.length - 1, r.i))] ?? null;

/** On to the next stop: round a loop, or out and back along a line. Counts a lap at the turn. */
export function advance(r: RouteOrder): void {
  const n = r.stops.length;
  if (n < 2) return;
  if (r.loop) {
    r.i = (r.i + 1) % n;
    if (r.i === 0) r.laps++;
    return;
  }
  let next = r.i + r.dir;
  if (next >= n || next < 0) { r.dir = r.dir === 1 ? -1 : 1; next = r.i + r.dir; if (r.dir === 1) r.laps++; }
  r.i = next;
}

/** A saved route back, checked: null when it makes no sense. */
export function readRoute(v: unknown): RouteOrder | null {
  if (!v || typeof v !== 'object') return null;
  const r = v as Partial<RouteOrder>;
  const num = (n: unknown) => typeof n === 'number' && Number.isFinite(n);
  const stops = (Array.isArray(r.stops) ? r.stops : []).filter((s): s is RouteStop => !!s && typeof s.key === 'string' && num(s.x) && num(s.z) && num(s.cx) && num(s.cz)).slice(0, ROUTE.most);
  if (stops.length < 2) return null;
  return { stops: stops.map((s) => ({ ...s, name: String(s.name ?? ''), y: num(s.y) ? s.y : 0 })), loop: !!r.loop, i: num(r.i) ? Math.max(0, Math.min(stops.length - 1, r.i!)) : 0, dir: r.dir === -1 ? -1 : 1, hold: !!r.hold, laps: num(r.laps) ? r.laps! : 0 };
}

/** A route as a line on a card: "Loop of 4 · next Pinewood Sawmill · 3 laps". */
export function routeLine(r: RouteOrder): string {
  const t = targetOf(r);
  return `${r.loop ? 'Loop' : 'Line'} of ${r.stops.length} · next ${t?.name.split(' · ')[0] ?? '—'} · ${r.laps} lap${r.laps === 1 ? '' : 's'}${r.hold ? ' · holds for a load' : ''}`;
}

/**
 * The route on the ground (render): a line in the fleet's colour through the stops, a post at each, the one it is
 * making for taller. Drawn while the route tool is open, or while one of the fleet's route vehicles is selected.
 */
export class RouteView {
  readonly group = new THREE.Group();
  private key = '';
  private mat = new THREE.LineDashedMaterial({ color: 0xe2412f, dashSize: 0.5, gapSize: 0.3, transparent: true, opacity: 0.9, depthTest: false });
  private postMat = new THREE.MeshBasicMaterial({ color: 0xe2412f, transparent: true, opacity: 0.85, depthTest: false });
  private post = new THREE.CylinderGeometry(0.08, 0.08, 1, 6).translate(0, 0.5, 0);

  constructor(scene: THREE.Scene) {
    this.group.renderOrder = 6;
    scene.add(this.group);
  }

  show(stops: { x: number; y: number; z: number }[], loop: boolean, target: number, colour: number): void {
    const key = `${stops.map((s) => `${s.x.toFixed(1)},${s.z.toFixed(1)}`).join('|')}|${loop}|${target}|${colour}`;
    if (key === this.key) return;
    this.clear();
    this.key = key;
    if (!stops.length) return;
    this.mat.color.setHex(colour);
    this.postMat.color.setHex(colour);
    const pts = stops.map((s) => new THREE.Vector3(s.x, s.y + 0.15, s.z));
    if (loop && pts.length > 2) pts.push(pts[0].clone());
    if (pts.length > 1) {
      const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), this.mat);
      line.computeLineDistances();
      line.renderOrder = 6;
      this.group.add(line);
    }
    stops.forEach((s, k) => {
      const m = new THREE.Mesh(this.post, this.postMat);
      m.position.set(s.x, s.y, s.z);
      m.scale.y = k === target ? 1.6 : 0.9;
      m.renderOrder = 6;
      this.group.add(m);
    });
  }

  clear(): void {
    for (const c of [...this.group.children]) {
      this.group.remove(c);
      if (c instanceof THREE.Line) c.geometry.dispose();
    }
    this.key = '';
  }
}
