/**
 * The first road (docs/firstroad.html): a brand-new player's loading screen. While their world is made they
 * drive a red Tomato along one road in a black void, lit for ten tiles either way of the car and gone to
 * black beyond. The road teaches the keys in order: W down a straight, A or D round a country bend, S at a
 * stop sign where the road ends; then, parked, Q/E, the zoom (wheel or + −), P and R while the load still runs.
 * Once all of them are done the road fades in on past the sign, bends the other way about ten tiles on, and
 * runs straight for as long as the load takes (the user, 8 Nov 2026). The finished load doesn't end the screen:
 * it puts a Skip controls tutorial button where the bar was (loadingShow.ts), and once every lesson is done a
 * chequered finish line comes out of the dark a few tiles ahead; driving over it ends the screen too.
 *
 * Everything here is the game's own, so what is learned in the dark is what the world asks for: the road is
 * laid into a scratch World and drawn by the road mesher, the car is a CarState stepping on that world from
 * the game's Input, the camera is a FollowCamera with the game's 18° lens on the standard pitch, locked
 * behind. Every tile that is not road is `blocked`, so the car's own wall code is the kerb: a player who
 * misses the bend scrapes round it and stays in the light.
 */
import * as THREE from 'three';
import { CHUNK, N, World, RoadType, idx } from '../world/tiles';
import { layRoad, rebuildRoadTables } from '../world/roads';
import { buildRoadChunk, roadMaterial } from './roadMesh';
import { CarState } from '../game/car';
import { DEFAULT_PITCH, FIRST_DRIVE_ZOOM, FollowCamera, PITCHES } from '../game/camera';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from './vehicleMeshes';
import { defOf } from '../game/fleet';
import type { Controls, LandDef } from '../game/vehicles';
import { RouteArrows } from './routeArrows';
import type { Input } from '../game/input';

/** The seven lessons, in the order the road teaches them (the zoom just before the camera angles, the user 8 Nov 2026). */
export type Lesson = 'W' | 'turn' | 'S' | 'QE' | 'zoom' | 'P' | 'R';
export const LESSONS: Lesson[] = ['W', 'turn', 'S', 'QE', 'zoom', 'P', 'R'];
/** What the void taught, for the first drive (game/tutorial.ts) and the play reports (net/journey.ts). */
export interface RoadLessons { done: Lesson[]; secs: Partial<Record<Lesson, number>>; load: number; side: 'left' | 'right' }

/** Tiles of road behind the car at the start, from the car to the bend, and from the bend to the end. */
const BEHIND = 14, TO_BEND = 13, TO_END = 9;
/**
 * The road on past the sign, once every lesson is done: tiles from the old end to the second bend (which turns
 * the other way), the last tile of the endless straight after it, and where the car is carried back along that
 * straight, by WRAP_BY, so it never reaches the edge of the scratch world. Past LIT + FADE everything is black,
 * so the jump can't be seen.
 */
const TO_BEND2 = 10, Z_LAST = N - 4, WRAP_AT = N - 26, WRAP_BY = 64;
/** Seconds the road past the sign takes to fade in. */
const SHOW_SECS = 1.6;
/** How far ahead (tiles to its mouth) the second bend asks for its key. */
const ASK_AHEAD = 5;
/** Wheel travel (pixels, a line counted as 33) one way that counts as having zoomed that way. */
const ZOOM_WHEEL = 40;
/** Spacing of the sampled centre line, in tiles. */
const STEP_S = 0.1;
/** The road: a two-lane country road, the one outside a new player's first town. */
const ROAD = RoadType.TwoLane;
/** Full-bright radius round the car, and how many tiles further the road fades to black. */
const LIT = 7, FADE = 4;
/** Tiles of throttle that count as having learned W. */
const W_TILES = 3;
/** How close (radians) the heading must come to the new straight for the bend to count. */
const TURN_OK = 0.35;
/** Within this many tiles of the end, a stop is the S lesson done. */
const STOP_NEAR = 3;
/** Radians of camera turn by Q, E or a right-drag that count as a look round. */
const LOOK = 0.6;
/**
 * The finish line (the user, 8 Nov 2026): tiles ahead of the car it is laid (pushed on past a bend it would land in, by
 * FLAG_CLEAR either side), and the seconds it takes to come out of the dark.
 */
const FLAG_AHEAD = 6, FLAG_CLEAR = 1, FLAG_SECS = 1;
/** The finish line's own fade, always on (its uCut test passes everywhere). */
const ALWAYS = { value: new THREE.Vector2(1, -1e6) };
/** The ground's height in steps: the scratch world is flat at this. */
const GROUND = 4;
/** The longest step the car's physics takes, in seconds (a frame at 60 Hz); a longer frame is cut into these. */
const SUBSTEP = 1 / 60;
/**
 * The car is kept to the road's centre line: how quickly (1/s) its heading is pulled to the line's direction and its position
 * onto the line, at speed. The world being made holds the page for whole seconds at a time (a frame a second was measured
 * on a new fleet's load, 8 Nov 2026), and no one can steer a bend by hand at that rate: the straights hold themselves, and
 * the bend is taken only while the key it asks for is held, else the car rolls to a stop at its mouth.
 */
const ASSIST_TURN = 6, ASSIST_PULL = 3;
/** The sweep's radius (world/curves.ts CURVE_R for size 2), and how far before it the bend asks for its key. */
const BEND_R = 1.5, BEND_AHEAD = 1.2;
/** How hard (tiles/s²) the car is slowed at the bend's mouth without its key, and at the road's end. */
const HOLD_BRAKE = 4;
/** Seconds S must be held, after the bend, for the stop to count as the player's. */
const S_HELD = 0.2;

/** The two-lane road's width (world/roads.ts ROAD_INFO). */
const WIDTH = 0.96;

interface Line { key: string; text: string; sub: string }
/** A point of the road's centre line: where, the way it runs, and how far along from the start. */
interface Pt { x: number; z: number; tx: number; tz: number; s: number }
/** A bend of the centre line: where along it its arc starts and ends, and which key takes it. */
interface Bend { s0: number; s1: number; side: 'left' | 'right' }

/** The A or D a bend asks for, keyboard and pad. */
function turnLine(side: 'left' | 'right', pad: boolean): Line {
  return pad ? { key: '◀▶', text: `Steer ${side} with the left stick`, sub: 'keep the trigger in' }
    : { key: side === 'left' ? 'A' : 'D', text: `Turn ${side}: hold ${side === 'left' ? 'A' : 'D'}`, sub: 'keep W down' };
}

/** What the one line says for each lesson, keyboard and pad. `zoomed` is which ways the zoom has gone so far. */
function lineFor(l: Lesson | 'free', side: 'left' | 'right', pad: boolean, pitch: number, locked: boolean, zoomed: { in: boolean; out: boolean }): Line {
  switch (l) {
    case 'W': return pad ? { key: 'RT', text: 'Pull the right trigger to drive forward', sub: 'the left stick steers' }
      : { key: 'W', text: 'Hold W to drive forward', sub: 'or ↑' };
    case 'turn': return turnLine(side, pad);
    case 'S': return pad ? { key: 'LT', text: 'Left trigger to stop at the sign', sub: 'hold it to reverse' }
      : { key: 'S', text: 'Press S to stop at the sign', sub: 'hold S to reverse' };
    case 'QE': return pad ? { key: '◉', text: 'Look round: the right stick turns the camera', sub: '' }
      : { key: 'Q E', text: 'Look round: Q and E turn the camera', sub: 'or right-click and drag' };
    case 'zoom': return { key: '+ −', text: 'Zoom in and out with the scroll wheel',
      sub: zoomed.in ? 'now zoom back out' : zoomed.out ? 'now zoom back in' : 'or the + and − keys' };
    case 'P': return { key: 'P', text: 'P changes the camera angle', sub: `${PITCHES[pitch].label} · ${pitch + 1} of ${PITCHES.length}` };
    case 'R': return { key: 'R', text: locked ? 'The camera is locked behind your car: R frees it' : 'R locks the camera behind your car again', sub: 'your world starts with it locked' };
    case 'free': return { key: '✓', text: 'Your world is nearly ready', sub: pad ? 'triggers drive · sticks steer and look' : 'W A S D drive · Q E P R camera · wheel zoom' };
  }
}

export class FirstRoad {
  readonly scene = new THREE.Scene();
  readonly cam = new THREE.PerspectiveCamera(18, 1, 2, 1600);
  private follow = new FollowCamera(this.cam);
  private w = new World();
  private def: LandDef;
  private car: CarState;
  private mesh: VehicleMesh;
  private arrows: RouteArrows;
  private roadMeshes: THREE.Mesh[] = [];
  private mat: THREE.MeshStandardMaterial;
  /** The road's tiles in order (the road on past the sign too, once it is laid), the index of the corner tile, and where the first road ends. */
  private tiles: number[] = [];
  private cornerAt = 0;
  private outDir: [number, number];
  private end: { x: number; z: number };
  /** The whole road's centre line, the first part and the part past the sign alike, sampled every STEP_S; and its two bends. */
  private path: Pt[] = [];
  private bends: Bend[] = [];
  /** The road past the sign: its tiles, the second bend's inner tile, and the endless straight's x (tile middle). */
  private extTiles: number[] = [];
  private inner2 = 0;
  private x2 = 0;
  /** The road past the sign has been laid; seconds it has been fading in; and the car has come round its bend. */
  private extended = false;
  private showT = 0;
  private passed2 = false;
  /** Shared by every faded material: how much of the road past the sign shows (0..1), and the line it starts at (dir, x). */
  private uShow = { value: 1 };
  private uCut = { value: new THREE.Vector2(0, 0) };
  /** The world is made (loadingShow.ts sets it): with every lesson done, the finish line is laid. */
  ready = false;
  /** The car has driven over the finish line: loadingShow.ts ends the screen. */
  crossed = false;
  /** The finish line once laid, how far along the centre line it stands, its fade-in, and the car's distance along at the last frame. */
  private flag: THREE.Group | null = null;
  private flagS = 0;
  private flagShow = { value: 0 };
  private prevS = 0;
  private sHeld = 0;
  /** S has brought the car to rest by the sign, seen at any physics step. */
  private sStopped = false;
  /** The side the first bend turns; the second turns the other way. */
  readonly side: 'left' | 'right';
  /** Which ways the zoom lesson has seen the camera go. */
  private zoomed = { in: false, out: false };
  private t = 0;
  private done = new Set<Lesson>();
  private at: Partial<Record<Lesson, number>> = {};
  private driven = 0;
  private looked = 0;
  private lastX: number;
  private lastZ: number;
  private line: Line | null = null;
  private dragDX = 0;
  private wheel = 0;
  /** Wheel travel toward (in) and away (out) since the void came up, in pixels: the zoom lesson's. */
  private wheelIn = 0;
  private wheelOut = 0;
  private rdown = false;
  /**
   * The keys pressed since the last frame, caught here: once the world is in, the game's own frame runs too and spends
   * Input's one-shots (endFrame) as often as not before the void's frame reads them.
   */
  private taps = new Set<string>();
  private sign: THREE.Group;
  private pool: THREE.Vector2;
  private unlisten: () => void;

  constructor(private capEl: HTMLElement, private el: HTMLElement) {
    const w = this.w;
    w.corners.fill(GROUND);
    w.blocked.fill(1);
    // the bend turns either way at random; ?road=left / ?road=right picks, for a look at each
    const forced = new URLSearchParams(location.search).get('road');
    this.side = forced === 'left' || forced === 'right' ? forced : Math.random() < 0.5 ? 'left' : 'right';
    // the road: up +z from well behind the car, a 90° corner, then along x to the end
    const x0 = 128, z0 = 100;
    const nodes: number[] = [];
    for (let k = 0; k <= BEHIND + TO_BEND; k++) nodes.push(idx(x0, z0 + k));
    this.cornerAt = nodes.length - 1;
    // heading 0 looks along +z, and its left is +x (a positive swing of the heading is a turn to the left, render/routeArrows.ts)
    const dx = this.side === 'left' ? 1 : -1;
    this.outDir = [dx, 0];
    const zc = z0 + BEHIND + TO_BEND;
    for (let k = 1; k <= TO_END; k++) nodes.push(idx(x0 + dx * k, zc));
    for (const n of nodes) w.blocked[n] = 0;
    // the tile on the inside of the bend is left open, as a sweep needs (world/curves.ts sweepInner)
    w.blocked[idx(x0 + dx, zc - 1)] = 0;
    layRoad(w, ROAD, nodes);
    this.tiles = nodes;
    this.end = { x: x0 + dx * TO_END + 0.5 + dx * 0.5, z: zc + 0.5 };
    // the road on past the sign, laid only once every lesson is done (extend): on along dx, then the other way round to +z
    const xb = x0 + dx * (TO_END + TO_BEND2);
    for (let k = TO_END + 1; k <= TO_END + TO_BEND2; k++) this.extTiles.push(idx(x0 + dx * k, zc));
    for (let z = zc + 1; z <= Z_LAST; z++) this.extTiles.push(idx(xb, z));
    this.inner2 = idx(xb - dx, zc + 1);
    this.x2 = xb + 0.5;
    // the centre line through it all: tile middles, each corner rounded by a sweep of BEND_R (world/curves.ts, size 2)
    const cx0 = x0 + 0.5, cz0 = z0 + 0.5, czc = zc + 0.5;
    this.centreLine([
      { seg: [cx0, cz0, cx0, czc - BEND_R] },
      { arc: [cx0, czc - BEND_R, cx0 + dx * BEND_R, czc, cx0 + dx * BEND_R, czc - BEND_R], side: this.side },
      { seg: [cx0 + dx * BEND_R, czc, this.x2 - dx * BEND_R, czc] },
      { arc: [this.x2 - dx * BEND_R, czc, this.x2, czc + BEND_R, this.x2 - dx * BEND_R, czc + BEND_R], side: this.side === 'left' ? 'right' : 'left' },
      { seg: [this.x2, czc + BEND_R, this.x2, Z_LAST + 0.5] },
    ]);
    // the car on the road, BEHIND tiles up it, facing the bend
    this.def = defOf('tomato') as LandDef;
    this.car = new CarState(this.def, x0 + 0.5, z0 + BEHIND + 0.5, 0, w);
    this.lastX = this.car.x;
    this.lastZ = this.car.z;
    this.pool = new THREE.Vector2(this.car.x, this.car.z);
    // the lights: a soft sky and one warm key from ahead and above, the turntable's
    const sky = new THREE.HemisphereLight(0xffffff, 0x6a6f74, 1.6);
    const key = new THREE.DirectionalLight(0xfff3dc, 2.8);
    key.position.set(3, 8, 5);
    const fill = new THREE.DirectionalLight(0xffffff, 0.7);
    fill.position.set(-6, 4, -3);
    this.scene.add(sky, key, fill);
    // the road, drawn by the game's mesher in the chunks it crosses, in a material that fades with distance from the car
    this.mat = roadMaterial.clone();
    this.fade(this.mat);
    this.drawRoad(nodes);
    // the car
    this.mesh = buildVehicleMesh(this.def);
    this.scene.add(this.mesh.holder);
    // the stop sign, on the right-hand verge two tiles before the end, facing the car
    this.sign = this.stopSign();
    const sx = x0 + dx * (TO_END - 1.5) + 0.5, sz = zc + 0.5;
    // the right-hand side of a car heading along dx·x is dx·z (the right of +z is -x); the face looks back at the car
    this.sign.position.set(sx, GROUND * 0.5, sz + dx * (WIDTH / 2 + 0.16));
    this.sign.rotation.y = Math.atan2(-dx, 0);
    this.scene.add(this.sign);
    // the camera: the game's standard view, locked behind the car
    this.follow.setPitchLevel(DEFAULT_PITCH);
    this.follow.zoomTo(FIRST_DRIVE_ZOOM); // 80% of the way in (the user, 8 Nov 2026)
    this.follow.groundAt = () => GROUND * 0.5;
    this.follow.reset(this.car.heading);
    this.follow.locked = true;
    // the bend's arrows, along the road's own tiles
    this.arrows = new RouteArrows(this.scene, (_w, x, z) => this.routeFrom(x, z));
    // a right-drag and the wheel on the loading screen, which sits over the game's canvas
    const down = (e: MouseEvent) => { if (e.button === 2) this.rdown = true; };
    const up = (e: MouseEvent) => { if (e.button === 2) this.rdown = false; };
    const move = (e: MouseEvent) => { if (this.rdown) this.dragDX += e.movementX; };
    const wheel = (e: WheelEvent) => {
      this.wheel += e.deltaY;
      e.preventDefault();
      const px = e.deltaY * (e.deltaMode === 1 ? 33 : e.deltaMode === 2 ? 400 : 1);
      if (px < 0) this.wheelIn -= px; else this.wheelOut += px;
    };
    const menu = (e: Event) => e.preventDefault();
    const onKey = (e: KeyboardEvent) => { if (!e.repeat) this.taps.add(e.code); };
    window.addEventListener('keydown', onKey);
    el.addEventListener('mousedown', down);
    window.addEventListener('mouseup', up);
    window.addEventListener('mousemove', move);
    el.addEventListener('wheel', wheel, { passive: false });
    el.addEventListener('contextmenu', menu);
    this.unlisten = () => {
      el.removeEventListener('mousedown', down);
      window.removeEventListener('mouseup', up);
      window.removeEventListener('mousemove', move);
      el.removeEventListener('wheel', wheel);
      el.removeEventListener('contextmenu', menu);
      window.removeEventListener('keydown', onKey);
    };
    this.say();
  }

  /** The lesson the line is on: the first not yet done, or 'free' once all seven are. */
  get lesson(): Lesson | 'free' { return LESSONS.find((l) => !this.done.has(l)) ?? 'free'; }

  /** What was learned, for the handover. */
  lessons(): RoadLessons { return { done: LESSONS.filter((l) => this.done.has(l)), secs: { ...this.at }, load: Math.round(this.t), side: this.side }; }

  /** For the console (pr.firstRoad). */
  get state(): { lesson: string; done: string; v: number; t: number; tile: number; side: string; steer: number; x: number; z: number; heading: number; extended: boolean; passed2: boolean; show: number; dist: number; ready: boolean; flag: number | null; s: number; crossed: boolean } {
    return { lesson: this.lesson, done: [...this.done].join(','), v: +this.car.v.toFixed(2), t: +this.t.toFixed(1), tile: this.tileIndex(), side: this.side, steer: this.lastSteer, x: +this.car.x.toFixed(2), z: +this.car.z.toFixed(2), heading: +this.car.heading.toFixed(2), extended: this.extended, passed2: this.passed2, show: +this.uShow.value.toFixed(2), dist: Math.round(this.follow.dist), ready: this.ready, flag: this.flag ? +this.flagS.toFixed(1) : null, s: +this.prevS.toFixed(1), crossed: this.crossed };
  }
  private lastSteer = 0;

  /**
   * One frame: the keys drive the car, the camera follows, the lessons watch. `dt` is the whole of the time since the
   * last frame (up to a second): the world being made holds the page for long moments, and the car is stepped through
   * them in SUBSTEP pieces so a held W still covers the road at the Tomato's pace, in jumps rather than not at all.
   */
  frame(dt: number, input: Input | null, aspect: number): void {
    this.t += dt;
    let pad = false;
    try { pad = [...(navigator.getGamepads?.() ?? [])].some((g) => !!g && g.connected); } catch { /* no pads */ }
    const c: Controls = { throttle: input?.throttle ?? 0, steer: input?.steer ?? 0, lift: 0 };
    this.lastSteer = c.steer;
    const steps = Math.max(1, Math.ceil(dt / SUBSTEP));
    const h = dt / steps;
    for (let k = 0; k < steps; k++) {
      this.car.step(this.w, c, h);
      this.assist(c, h);
      // S brought the car to rest by the sign at some step of the frame (a long frame can carry it from forward to
      // reverse between two looks at its speed)
      if (this.done.has('turn') && c.throttle < -0.1 && this.car.v <= 0.1 && this.toEnd() < STOP_NEAR + 1.5) this.sStopped = true;
    }
    // over the finish line, going forward (a frame carries the car a few tiles at most, so a jump of more is a wrap, not a crossing)
    const sNow = this.onLine(this.car.x, this.car.z).s;
    if (this.flag && this.prevS < this.flagS && sNow >= this.flagS && sNow - this.prevS < 12) this.crossed = true;
    this.prevS = sNow;
    // far up the endless straight: carried back along it, the camera with it (and a finish line ahead), before the scratch world's edge
    if (this.extended && this.car.z > WRAP_AT && Math.abs(this.car.x - this.x2) < 2) {
      this.car.z -= WRAP_BY;
      this.lastZ -= WRAP_BY;
      this.follow.target.z -= WRAP_BY;
      this.prevS -= WRAP_BY;
      if (this.flag) { this.flag.position.z -= WRAP_BY; this.flagS -= WRAP_BY; }
    }
    // the one-shots: read here, and spent, so none is still waiting for the game's first frame
    const tap = (k: string) => this.taps.has(k) || !!input?.justPressed(k);
    const pP = tap('KeyP');
    const pR = tap('KeyR');
    const zIn = tap('Equal') || tap('NumpadAdd');
    const zOut = tap('Minus') || tap('NumpadSubtract');
    this.taps.clear();
    const orbit = input?.orbit ?? 0;
    const drag = this.dragDX + (input?.takeDrag() ?? 0);
    this.dragDX = 0;
    const wheel = this.wheel + (input?.takeWheel() ?? 0);
    this.wheel = 0;
    input?.endFrame();
    if (pP) this.follow.setPitchLevel(this.follow.pitchLevel + 1);
    if (pR) this.follow.locked = !this.follow.locked;
    // the zoom keys (main.ts holds its own while the road is up); the wheel toward you zooms in (game/camera.ts)
    if (zIn) this.follow.zoomStep(-1);
    if (zOut) this.follow.zoomStep(1);
    if (zIn || this.wheelIn >= ZOOM_WHEEL) this.zoomed.in = true;
    if (zOut || this.wheelOut >= ZOOM_WHEEL) this.zoomed.out = true;
    this.follow.update(dt, new THREE.Vector3(this.car.x, this.car.y, this.car.z), orbit, drag, wheel, this.car.heading);
    this.cam.aspect = aspect;
    this.cam.updateProjectionMatrix();
    // the lessons
    const moved = Math.hypot(this.car.x - this.lastX, this.car.z - this.lastZ);
    this.lastX = this.car.x;
    this.lastZ = this.car.z;
    if (c.throttle > 0.1 && this.car.v > 0) this.driven += moved;
    this.looked += Math.abs(orbit) * dt * Math.PI / 2 + Math.abs(drag) * 0.005;
    const k = this.tileIndex();
    if (!this.done.has('W') && this.driven >= W_TILES) this.learned('W');
    if (this.done.has('W') && !this.done.has('turn') && k > this.cornerAt) {
      const want = Math.atan2(this.outDir[0], this.outDir[1]);
      const diff = Math.atan2(Math.sin(this.car.heading - want), Math.cos(this.car.heading - want));
      if (Math.abs(diff) < TURN_OK) this.learned('turn');
    }
    if (this.done.has('turn') && c.throttle < -0.1) this.sHeld += dt;
    if (this.done.has('turn') && !this.done.has('S') && this.sHeld >= S_HELD && (this.sStopped || (this.toEnd() < STOP_NEAR + 1.5 && Math.abs(this.car.v) < 0.1))) this.learned('S');
    if (this.looked >= LOOK) this.learned('QE');
    if (this.zoomed.in && this.zoomed.out) this.learned('zoom');
    if (pP) this.learned('P');
    if (pR) this.learned('R');
    // the car, the arrows and the light
    poseVehicleMesh(this.mesh, this.car, this.def, this.w);
    // every lesson done: the road goes on past the sign, fading in
    if (this.lesson === 'free' && !this.extended) this.extend();
    if (this.extended && this.showT < SHOW_SECS) { this.showT += dt; this.uShow.value = Math.min(1, this.showT / SHOW_SECS); }
    const me = { x: this.car.x, z: this.car.z };
    const L = this.onLine(this.car.x, this.car.z);
    if (this.extended && !this.passed2 && L.s > this.bends[1].s1) this.passed2 = true;
    const ask2 = this.extended && !this.passed2 && this.bends[1].s0 - L.s < ASK_AHEAD;
    // the world made and every lesson done: the finish line comes out of the dark ahead
    if (this.ready && this.extended && !this.flag) this.layFlag(L.s);
    if (this.flag && this.flagShow.value < 1) this.flagShow.value = Math.min(1, this.flagShow.value + dt / FLAG_SECS);
    this.arrows.update(dt, this.w, me, this.end, this.lesson === 'turn' || ask2);
    this.pool.set(this.car.x, this.car.z); // the fading materials' uniform is this very vector
    this.say(pad, ask2);
  }

  /** Put everything away. */
  dispose(): void {
    this.unlisten();
    this.arrows.clear();
    disposeVehicleMesh(this.mesh);
    for (const m of this.roadMeshes) m.geometry.dispose();
    this.mat.dispose();
    for (const g of [this.sign, this.flag]) g?.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.geometry.dispose();
      const mat = m.material as THREE.MeshStandardMaterial;
      mat.map?.dispose();
      mat.dispose();
    });
  }

  private learned(l: Lesson): void {
    if (this.done.has(l)) return;
    this.done.add(l);
    this.at[l] = Math.round(this.t * 10) / 10;
  }

  /** The line under the wordmark: a key cap and a sentence, swapped in place; the cap goes green once the lesson is done. */
  private say(pad = false, ask2 = false): void {
    const l = this.lesson;
    // past the sign: drive on, then the second bend's key, then the line is green for good; once the finish line is
    // down, it's that (but a bend between the car and the line still asks for its key first)
    const on = l === 'free' && this.extended && !this.passed2;
    const flagFirst = !!this.flag && !(ask2 && this.flagS > this.bends[1].s0);
    const line = l !== 'free' ? lineFor(l, this.side, pad, this.follow.pitchLevel, this.follow.locked, this.zoomed)
      : flagFirst ? { key: '✓', text: 'Your world is ready: drive over the finish line', sub: pad ? 'pull the right trigger' : 'hold W' }
      : ask2 ? turnLine(this.bends[1].side, pad)
      : on ? { key: pad ? 'RT' : 'W', text: 'The road goes on: keep driving', sub: pad ? 'pull the right trigger' : 'hold W' }
      : lineFor(l, this.side, pad, this.follow.pitchLevel, this.follow.locked, this.zoomed);
    if (this.line && this.line.key === line.key && this.line.text === line.text && this.line.sub === line.sub) return;
    this.line = line;
    this.capEl.classList.add('in');
    this.capEl.innerHTML = `<kbd class="ld-key${line.key === '✓' ? ' ok' : ''}">${line.key}</kbd><span class="ld-line"><b>${line.text}</b>${line.sub ? `<small>${line.sub}</small>` : ''}</span>`;
  }

  /**
   * The finish line, FLAG_AHEAD tiles on from the car along the road (or just past a bend it would land in): a chequered
   * strip across the road under a chequered banner on two posts, faded with the rest and fading in by flagShow.
   */
  private layFlag(s: number): void {
    let at = s + FLAG_AHEAD;
    for (const b of this.bends) if (at > b.s0 - FLAG_CLEAR && at < b.s1 + FLAG_CLEAR) at = b.s1 + FLAG_CLEAR;
    const P = this.path;
    const p = P.find((q) => q.s >= at) ?? P[P.length - 1];
    this.flagS = p.s;
    this.flagShow.value = 0;
    const g = new THREE.Group();
    const strip = new THREE.Mesh(new THREE.PlaneGeometry(WIDTH, 0.24), this.checkerMat(8, 2));
    strip.rotation.x = -Math.PI / 2;
    strip.position.y = 0.06;
    const postMat = new THREE.MeshStandardMaterial({ color: 0xe8e6e0, roughness: 0.5 });
    this.fade(postMat, this.flagShow);
    const banner = new THREE.Mesh(new THREE.BoxGeometry(WIDTH + 0.26, 0.13, 0.025), this.checkerMat(10, 1));
    banner.position.y = 0.68;
    g.add(strip, banner);
    for (const side of [-1, 1]) {
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 0.74, 8), postMat);
      post.position.set(side * (WIDTH / 2 + 0.11), 0.37, 0);
      g.add(post);
    }
    g.position.set(p.x, GROUND * 0.5, p.z);
    g.rotation.y = Math.atan2(p.tx, p.tz);
    this.flag = g;
    this.scene.add(g);
  }

  /** Black and white squares, `cols` by `rows`, in a material faded like the road and by the finish line's own fade-in. */
  private checkerMat(cols: number, rows: number): THREE.MeshStandardMaterial {
    const c = document.createElement('canvas');
    const px = 16;
    c.width = cols * px; c.height = rows * px;
    const ctx = c.getContext('2d')!;
    for (let i = 0; i < cols; i++) for (let j = 0; j < rows; j++) {
      ctx.fillStyle = (i + j) % 2 ? '#141414' : '#f6f6f2';
      ctx.fillRect(i * px, j * px, px, px);
    }
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.magFilter = THREE.NearestFilter;
    const m = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.6, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
    this.fade(m, this.flagShow);
    return m;
  }

  /**
   * The road on past the sign: the old road is taken up and the whole of it laid again as one road (so the mesher
   * runs it on with no end cap, and the second corner gets its sweep), and drawn afresh. Everything past the old
   * end shows by uShow, which fades from 0, so the old road looks the same through the swap and the new comes in.
   */
  private extend(): void {
    const w = this.w;
    this.extended = true;
    this.showT = 0;
    this.uShow.value = 0;
    this.uCut.value.set(this.outDir[0], this.end.x);
    for (const n of this.extTiles) w.blocked[n] = 0;
    w.blocked[this.inner2] = 0;
    const all = [...this.tiles, ...this.extTiles];
    w.roads = [];
    rebuildRoadTables(w);
    layRoad(w, ROAD, all);
    this.tiles = all;
    for (const m of this.roadMeshes) { this.scene.remove(m); m.geometry.dispose(); }
    this.roadMeshes = [];
    this.drawRoad(all);
  }

  /** The road's chunks drawn by the game's mesher, in the material that fades with distance from the car. */
  private drawRoad(nodes: number[]): void {
    const cxs = new Set<string>();
    for (const n of nodes) cxs.add(`${Math.floor((n % N) / CHUNK)},${Math.floor(Math.floor(n / N) / CHUNK)}`);
    for (const k of cxs) {
      const [cx, cz] = k.split(',').map(Number);
      const m = buildRoadChunk(this.w, cx, cz);
      if (!m) continue;
      m.material = this.mat;
      this.roadMeshes.push(m);
      this.scene.add(m);
    }
  }

  /** Sample the centre line: straights (ax, az, bx, bz) and quarter arcs (from, to, about the centre), in order. */
  private centreLine(parts: ({ seg: number[] } | { arc: number[]; side: 'left' | 'right' })[]): void {
    const pts: { x: number; z: number }[] = [];
    const bendAt: { i0: number; i1: number; side: 'left' | 'right' }[] = [];
    for (const p of parts) {
      if ('seg' in p) {
        const [ax, az, bx, bz] = p.seg;
        const n = Math.max(1, Math.round(Math.hypot(bx - ax, bz - az) / STEP_S));
        for (let k = 0; k < n; k++) pts.push({ x: ax + (bx - ax) * k / n, z: az + (bz - az) * k / n });
      } else {
        const [px, pz, qx, qz, ox, oz] = p.arc;
        const a0 = Math.atan2(pz - oz, px - ox);
        let da = Math.atan2(qz - oz, qx - ox) - a0;
        da = Math.atan2(Math.sin(da), Math.cos(da));
        const r = Math.hypot(px - ox, pz - oz);
        const n = Math.max(2, Math.round(Math.abs(da) * r / STEP_S));
        const i0 = pts.length;
        for (let k = 0; k < n; k++) { const a = a0 + da * k / n; pts.push({ x: ox + Math.cos(a) * r, z: oz + Math.sin(a) * r }); }
        bendAt.push({ i0, i1: pts.length, side: p.side });
      }
    }
    const last = parts[parts.length - 1];
    if ('seg' in last) pts.push({ x: last.seg[2], z: last.seg[3] });
    let s = 0;
    this.path = pts.map((p, i) => {
      if (i > 0) s += Math.hypot(p.x - pts[i - 1].x, p.z - pts[i - 1].z);
      const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
      const l = Math.hypot(b.x - a.x, b.z - a.z) || 1;
      return { x: p.x, z: p.z, tx: (b.x - a.x) / l, tz: (b.z - a.z) / l, s };
    });
    this.bends = bendAt.map((b) => ({ s0: this.path[b.i0].s, s1: this.path[Math.min(this.path.length - 1, b.i1)].s, side: b.side }));
  }

  /**
   * The road's centre line at (x, z): the nearest point on it, the way it runs there, how far along it that is, which bend
   * it is in (from BEND_AHEAD before an arc to the arc's end; -1 for none) and how far that bend's mouth is ahead.
   */
  private onLine(x: number, z: number): { px: number; pz: number; tx: number; tz: number; s: number; bend: number; mouth: number } {
    const P = this.path;
    let best = 0, bd = Infinity;
    for (let i = 0; i < P.length; i++) { const d = (P[i].x - x) ** 2 + (P[i].z - z) ** 2; if (d < bd) { bd = d; best = i; } }
    // onto the segment either side of the nearest sample, for a line with no steps in it
    let px = P[best].x, pz = P[best].z, s = P[best].s;
    for (const j of [best - 1, best]) {
      if (j < 0 || j + 1 >= P.length) continue;
      const a = P[j], b = P[j + 1], ex = b.x - a.x, ez = b.z - a.z, l2 = ex * ex + ez * ez || 1;
      const u = Math.max(0, Math.min(1, ((x - a.x) * ex + (z - a.z) * ez) / l2));
      const qx = a.x + ex * u, qz = a.z + ez * u, d = (qx - x) ** 2 + (qz - z) ** 2;
      if (d < bd) { bd = d; px = qx; pz = qz; s = a.s + (b.s - a.s) * u; }
    }
    const t = P[best];
    let bend = -1, mouth = 0;
    this.bends.forEach((b, k) => { if (s >= b.s0 - BEND_AHEAD && s <= b.s1) { bend = k; mouth = b.s0 - s; } });
    return { px, pz, tx: t.tx, tz: t.tz, s, bend, mouth };
  }

  /**
   * After each physics step: the car is drawn to the centre line and its direction (see ASSIST_TURN). In the bend the
   * key it asks for must be down, or the car is slowed to a stop at the mouth; the road's end stops it the same way.
   */
  private assist(c: Controls, dt: number): void {
    const car = this.car;
    const L = this.onLine(car.x, car.z);
    const speed = Math.abs(car.v);
    const b = L.bend >= 0 ? this.bends[L.bend] : null;
    const keyed = !!b && (b.side === 'left' ? c.steer > 0.12 : c.steer < -0.12);
    // the first bend waits for its key until it has been learned; the one past the sign until it has been come round
    const gated = L.bend === 0 ? !this.done.has('turn') : L.bend === 1 ? !this.passed2 : false;
    if (b && !keyed && gated && car.v > 0) {
      // rolling to the mouth: no faster than would stop there, and never through it
      const room = Math.max(0, L.mouth);
      car.v = Math.min(car.v, Math.max(0, Math.sqrt(2 * HOLD_BRAKE * room)), Math.max(0, car.v - HOLD_BRAKE * dt));
      if (room <= 0.02 && L.mouth >= 0) car.v = 0;
    }
    // the end (until the road goes on past it): the car is stopped short of the dark, as a wall would, a little more gently
    const over = Math.hypot(this.end.x - car.x, this.end.z - car.z);
    if (!this.extended && over < 0.6 && car.v > 0) car.v = Math.min(car.v, Math.max(0, car.v - HOLD_BRAKE * 2 * dt));
    if (speed < 0.05) return;
    const want = Math.atan2(L.tx, L.tz);
    const diff = Math.atan2(Math.sin(want - car.heading), Math.cos(want - car.heading));
    const gain = Math.min(1, speed);
    car.heading += diff * Math.min(1, dt * ASSIST_TURN * gain * (b ? 1.6 : 1));
    car.course = car.heading;
    const pull = Math.min(1, dt * ASSIST_PULL * gain);
    car.x += (L.px - car.x) * pull;
    car.z += (L.pz - car.z) * pull;
  }

  /** Which of the road's tiles the car is on, or the nearest before it; -1 off the road's start. */
  private tileIndex(): number {
    const i = idx(Math.floor(this.car.x), Math.floor(this.car.z));
    const k = this.tiles.indexOf(i);
    if (k >= 0) return k;
    // on the inside tile of the bend: the corner
    return this.cornerAt;
  }

  private toEnd(): number { return Math.hypot(this.end.x - this.car.x, this.end.z - this.car.z); }

  /** The road's tiles from the one nearest (x, z) on, for the arrows. */
  private routeFrom(x: number, z: number): number[] | null {
    const i = idx(Math.floor(x), Math.floor(z));
    let k = this.tiles.indexOf(i);
    if (k < 0) k = this.cornerAt;
    // only as far as the light reaches: an arrow in the dark would float in nothing
    return this.tiles.slice(k, k + LIT + 2);
  }

  /**
   * A material darkened by its distance from the car: full within LIT tiles, black FADE tiles further out. With `show`, the
   * whole of it also fades in by that (the finish line); without, only what is past the old end, by uShow.
   */
  private fade(m: THREE.Material, show?: { value: number }): void {
    const self = this;
    m.onBeforeCompile = (shader) => {
      shader.uniforms.uCar = { value: self.pool };
      shader.uniforms.uLit = { value: LIT };
      shader.uniforms.uFade = { value: FADE };
      shader.uniforms.uShow = show ?? self.uShow;
      shader.uniforms.uCut = show ? ALWAYS : self.uCut;
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', '#include <common>\nvarying vec2 vFR;')
        .replace('#include <begin_vertex>', '#include <begin_vertex>\nvFR = (modelMatrix * vec4(transformed, 1.0)).xz;');
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', '#include <common>\nvarying vec2 vFR;\nuniform vec2 uCar;\nuniform float uLit;\nuniform float uFade;\nuniform float uShow;\nuniform vec2 uCut;')
        // past the old end (uCut: its direction along x and its x), the road on shows by uShow as it fades in
        .replace('#include <dithering_fragment>', '#include <dithering_fragment>\n{ float d = distance(vFR, uCar); float k = 1.0 - smoothstep(uLit, uLit + uFade, d); if (uCut.x * (vFR.x - uCut.y) > 0.0) k *= uShow; gl_FragColor.rgb *= k * k; }');
    };
    m.customProgramCacheKey = () => 'firstRoad-fade';
    m.needsUpdate = true;
  }

  /** A stop sign: a red octagon with a white rim and the word on it, on a grey post, facing +z before rotation. */
  private stopSign(): THREE.Group {
    const g = new THREE.Group();
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.5, 8), new THREE.MeshStandardMaterial({ color: 0x8c9196, roughness: 0.6 }));
    post.position.y = 0.25;
    const face = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 0.012, 8), new THREE.MeshStandardMaterial({ color: 0xd63a2a, roughness: 0.5 }));
    face.rotation.x = Math.PI / 2;
    face.rotation.y = Math.PI / 8;
    face.position.y = 0.56;
    const rim = new THREE.Mesh(new THREE.CylinderGeometry(0.165, 0.165, 0.008, 8), new THREE.MeshStandardMaterial({ color: 0xf4f1ea, roughness: 0.5 }));
    rim.rotation.copy(face.rotation);
    rim.position.y = 0.56;
    rim.position.z = -0.003;
    // the word, drawn on a canvas
    const c = document.createElement('canvas');
    c.width = 256; c.height = 128;
    const ctx = c.getContext('2d')!;
    ctx.clearRect(0, 0, 256, 128);
    ctx.fillStyle = '#ffffff';
    ctx.font = '700 86px "IBM Plex Sans", "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('STOP', 128, 66);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const word = new THREE.Mesh(new THREE.PlaneGeometry(0.24, 0.12), new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false }));
    word.position.set(0, 0.56, 0.008);
    g.add(post, rim, face, word);
    for (const o of [post, face, rim]) this.fade((o as THREE.Mesh).material as THREE.Material);
    return g;
  }
}
