import * as THREE from 'three';
import { N, STEP, idx, type World } from '../../world/tiles';
import { VEHICLES, type WaterDef } from '../vehicles';
import { waterRoute } from '../traffic';
import { KIND_OF } from './kinds';
import type { Happening } from './calendar';
import { mid, type Place, type Pt } from './venues';
import { Bulbs, Crowd, Rig, Way, block, dressed, flat, waterY } from './props';
import { HOUR_S, Show, clamp01, toWorld, u01, type ShowCtx } from './shows';

/**
 * Phase 4 (docs/events.html), the water, the sky and the dark: a fireboat salute for a newcomer, the blessing of a
 * fishing fleet, whales off the shore, a launch watched from the hills, a city's blackout, and the sky's own
 * events: meteors, an eclipse, the aurora, a murmuration of starlings, the desert in flower. Each from the clock.
 */

// ---- the harbour: a salute, a blessing ---------------------------------------------------------------------------------------------------

/**
 * A harbour's morning: a newcomer (a ferry) brought in from the offing between two fireboats throwing arcs of water
 * over it; or the fishing fleet out at first light and home at noon to a feast laid out on the quay.
 */
class HarbourShow extends Show {
  private boats: { rig: Rig; way: Way | null; delay: number }[] = [];
  private fire: Rig[] = [];
  private crowd: Crowd;
  private tables = new THREE.Group();

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const off = place.offing!;
    const salute = e.kind === 'fireboatSalute';
    const ids = salute ? ['bigblue'] : ['breeze', 'rowboat', 'splash', 'breeze', 'rowboat', 'splash'];
    ids.forEach((id, i) => {
      const def = VEHICLES.find((v) => v.id === id) as WaterDef;
      const b = place.berths![i % place.berths!.length];
      const pts = waterRoute(w, def, off.x + (i % 3) * 1.2, off.z + Math.floor(i / 3) * 1.2, b.x, b.z, new Set());
      this.boats.push({ rig: new Rig(this.g, dressed(id, salute ? undefined : [0x2f7fb5, 0xc9463d, 0xf2c14e][i % 3])), way: pts && pts.length > 1 ? new Way(pts.map((p) => toWorld(w, p))) : null, delay: i * 0.12 });
    });
    if (salute) for (let k = 0; k < 2; k++) this.fire.push(new Rig(this.g, dressed('breeze', 0xc8102e)));
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
    if (!salute) {
      // the feast: trestle tables on the quay
      for (const p of (place.shore ?? []).slice(0, 5)) block(this.tables, w.ox + p.x, ctx.ground(w.ox + p.x, w.oz + p.z), w.oz + p.z, 0.4, 0.08, 0.14, 0xd9c7a0, u01(e.h, p.x));
      this.g.add(this.tables);
    }
  }

  centre(): Pt | null { return toWorld(this.w, this.place.berths![0]); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF[e.kind];
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = now - e.start, salute = e.kind === 'fireboatSalute';
    for (const b of this.boats) {
      if (!b.way) { b.rig.hide(); continue; }
      const L = b.way.length;
      let d: number, v = 0, back = false;
      if (salute) {
        // in from the offing over the first hour, then made fast at the berth
        const f = clamp01(t / 1.0);
        d = f * L; v = f < 1 ? L / HOUR_S : 0;
      } else {
        // out at first light (the way read backwards), the morning at sea, home at noon
        const outF = clamp01((t - b.delay) / 0.8), homeF = clamp01((t - 4.9 - b.delay) / 0.9);
        if (homeF > 0) { d = homeF * L; v = homeF < 1 ? L / (0.9 * HOUR_S) : 0; }
        else { d = (1 - outF) * L; v = outF < 1 ? L / (0.8 * HOUR_S) : 0.1; back = true; }
      }
      const p = b.way.at(d);
      b.rig.float(this.ctx.worldAt, p.x, p.z, back ? p.heading + Math.PI : p.heading, v, dt, 0.3);
    }
    if (salute) {
      const lead = this.boats[0].rig.state;
      const moving = t > 0 && t < 1.05;
      this.fire.forEach((f, k) => {
        const s = k ? 1 : -1, h = lead.heading, nx = Math.cos(h) * s, nz = -Math.sin(h) * s;
        f.float(this.ctx.worldAt, lead.x + nx * 2.2 + Math.sin(h) * 0.5, lead.z + nz * 2.2 + Math.cos(h) * 0.5, h, moving ? 1 : 0, dt);
        if (moving && Math.random() < dt * 35) this.ctx.particles.spark({ x: f.state.x, y: f.state.y + 0.3, z: f.state.z, vx: -nx * 1.5, vy: 2.8, vz: -nz * 1.5, life: 1.3, colour: 0x9fc8e8, size: 0.07, gravity: 3.6, drag: 0.3 });
      });
      this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / 0.3) * (1 - clamp01((now - (e.end - 0.2)) / 0.2));
      this.crowd.cheer = moving ? 0.6 : 0;
    } else {
      // the quay fills for the boats coming home and the feast
      this.tables.visible = t > 4.5;
      this.crowd.shown = this.crowd.size * clamp01((t - 4.5) / 0.5) + (t < 0.6 ? this.crowd.size * 0.3 : 0);
      this.crowd.cheer = t > 5.4 && t < 6 ? 0.8 : 0.1;
    }
    this.crowd.update(dt);
  }

  dispose(): void { for (const b of this.boats) b.rig.dispose(); for (const f of this.fire) f.dispose(); this.crowd.dispose(); super.dispose(); }
}

// ---- whales ---------------------------------------------------------------------------------------------------

/** A whale pod off the shore for an afternoon: backs rolling up through the water, blowing, flukes up as they dive. */
class WhaleShow extends Show {
  private whales: { g: THREE.Group; fluke: THREE.Mesh; ph: number; sp: number; a: number }[] = [];
  private crowd: Crowd;
  private r: NonNullable<Place['water']>;

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    this.r = place.water!;
    for (let i = 0; i < 5; i++) {
      const g = new THREE.Group();
      const body = new THREE.Mesh(new THREE.SphereGeometry(0.5, 10, 6), flat(0x3b4752));
      body.scale.set(0.42, 0.32, 1.4);
      const belly = new THREE.Mesh(new THREE.SphereGeometry(0.48, 8, 5), flat(0xb8c2c8));
      belly.scale.set(0.38, 0.2, 1.2);
      belly.position.y = -0.06;
      const fluke = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.03, 0.22), flat(0x3b4752));
      fluke.position.z = -0.8;
      g.add(body, belly, fluke);
      this.g.add(g);
      this.whales.push({ g, fluke, ph: u01(e.h, i) * 6.28, sp: 0.6 + u01(e.h, i + 9) * 0.3, a: u01(e.h, i + 20) * 6.28 });
    }
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { return { x: this.w.ox + (this.r.x0 + this.r.x1) / 2, z: this.w.oz + (this.r.z0 + this.r.z1) / 2 }; }

  update(now: number, dt: number): void {
    const e = this.e, out = now >= e.start && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const t = (now - e.start) * HOUR_S, r = this.r;
    const cx = this.w.ox + (r.x0 + r.x1) / 2, cz = this.w.oz + (r.z0 + r.z1) / 2, rx = (r.x1 - r.x0) / 2 - 2, rz = (r.z1 - r.z0) / 2 - 2;
    this.whales.forEach((q, i) => {
      // a slow loop through the bay, all of them together, rolling up to breathe every so often
      const a = q.a + t * 0.02 * q.sp, x = cx + Math.cos(a) * rx * (0.6 + 0.08 * i), z = cz + Math.sin(a * 1.3) * rz * 0.7;
      const head = Math.atan2(-Math.sin(a) * rx, Math.cos(a * 1.3) * 1.3 * rz * 0.7);
      const roll = Math.sin(t * 0.35 * q.sp + q.ph);
      const wy = waterY(this.ctx, x, z);
      q.g.position.set(x, wy - 0.22 + Math.max(0, roll) * 0.22, z);
      q.g.rotation.set(-roll * 0.18, head, 0, 'YXZ');
      q.fluke.rotation.x = roll < -0.7 ? -0.9 : 0;
      if (roll > 0.92 && Math.random() < dt * 12) this.ctx.particles.puff({ x: x + Math.sin(head) * 0.45, y: wy + 0.1, z: z + Math.cos(head) * 0.45, vx: 0, vy: 1.4, vz: 0, life: 1.4, colour: 0xeef4f8, size: 0.18, drag: 1.6, alpha: 0.75 });
    });
    this.crowd.shown = this.crowd.size;
    this.crowd.update(dt);
  }
}

// ---- the launch ---------------------------------------------------------------------------------------------------

/** Crowds on every hill round the launch pad; at the hour, the rocket climbs on a pillar of flame and smoke. */
class LaunchShow extends Show {
  private crowd: Crowd;
  private rocket = new THREE.Group();
  private pad: Pt & { y: number };

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    const b = place.tower!;
    const c = toWorld(w, mid(b));
    this.pad = { ...c, y: b.level * STEP + 0.25 };
    const body = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.15, 1.3, 10), flat(0xf4f2ec));
    body.position.y = 0.65;
    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.35, 10), flat(0xd52b1e));
    nose.position.y = 1.47;
    this.rocket.add(body, nose);
    for (let k = 0; k < 4; k++) { const fin = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.22, 0.14), flat(0x3a3f45)); const a = (k / 4) * Math.PI * 2; fin.position.set(Math.cos(a) * 0.15, 0.1, Math.sin(a) * 0.15); fin.rotation.y = -a; this.rocket.add(fin); }
    this.rocket.position.set(c.x, this.pad.y, c.z);
    this.g.add(this.rocket);
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    for (const p of place.shore ?? []) this.crowd.add(w.ox + p.x, w.oz + p.z);
  }

  centre(): Pt | null { return this.pad; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.launchWatch;
    const out = now >= e.start - spec.lead && now < e.end;
    this.g.visible = out;
    if (!out) return;
    const lift = (now - (e.start + spec.dur * 0.4)) * HOUR_S;
    this.crowd.shown = this.crowd.size * clamp01((now - (e.start - spec.lead)) / spec.lead) * (1 - clamp01((now - (e.end - 0.3)) / 0.3));
    this.crowd.cheer = lift > -3 && lift < 25 ? 1 : 0.1;
    this.crowd.update(dt);
    // the climb: slow off the pad, then faster and faster, gone in the clouds after half a minute
    const y = lift > 0 ? this.pad.y + 0.5 * lift * lift * 0.12 : this.pad.y;
    this.rocket.visible = lift < 32;
    this.rocket.position.y = y;
    if (lift > -1.5 && lift < 32) {
      for (let k = 0; k < 4; k++) this.ctx.particles.spark({ x: this.pad.x + (Math.random() - 0.5) * 0.1, y: y - 0.05, z: this.pad.z + (Math.random() - 0.5) * 0.1, vx: (Math.random() - 0.5) * 0.6, vy: -2 - Math.random(), vz: (Math.random() - 0.5) * 0.6, life: 0.35, colour: k % 2 ? 0xffd166 : 0xff7a1a, size: 0.14, gravity: 0, drag: 2 });
      if (Math.random() < dt * 25) this.ctx.particles.puff({ x: this.pad.x + (Math.random() - 0.5) * 0.3, y: Math.max(this.pad.y, y - 0.3), z: this.pad.z + (Math.random() - 0.5) * 0.3, vx: (Math.random() - 0.5) * 0.5, vy: 0.1, vz: (Math.random() - 0.5) * 0.5, life: 6, colour: 0xf0f0f0, size: 0.6, drag: 0.4, alpha: 0.85 });
    }
  }
}

// ---- the blackout ---------------------------------------------------------------------------------------------------

/** A city going dark a street at a time across the town, candles in windows, and the lights coming back on all at once. */
class BlackoutShow extends Show {
  private box: { x0: number; z0: number; x1: number; z1: number };
  private candles: Bulbs;
  private spots: Pt[] = [];
  private fromX: boolean;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const t = place.town!;
    this.box = { x0: w.ox + t.x0 - 2, z0: w.oz + t.z0 - 2, x1: w.ox + t.x0 + t.size + 2, z1: w.oz + t.z0 + t.size + 2 };
    this.fromX = (e.h & 1) === 1;
    this.candles = new Bulbs(this.g, 40, [0xffb347, 0xffd166], 0.025);
    for (const b of t.buildings) if (!b.gone && b.solid && this.spots.length < 40 && u01(e.h, b.uid) < 0.3) { const c = mid(b); this.spots.push({ x: w.ox + c.x + (b.w / 2 + 0.03) * Math.sign(u01(e.h, b.uid + 1) - 0.5), z: w.oz + c.z }); }
  }

  centre(): Pt | null { return { x: (this.box.x0 + this.box.x1) / 2, z: (this.box.z0 + this.box.z1) / 2 }; }

  update(now: number, dt: number): void {
    void dt;
    const e = this.e, t = (now - e.start) / KIND_OF.blackout.dur;
    const on = t >= 0 && t < 1;
    if (!on) { this.light(0, null); this.candles.mesh.visible = false; return; }
    // the dark spreads across the town over the first quarter, holds, and the power comes back at a stroke
    const spread = clamp01(t / 0.25), b = this.box;
    const box = this.fromX ? { ...b, x1: b.x0 + (b.x1 - b.x0) * spread } : { ...b, z1: b.z0 + (b.z1 - b.z0) * spread };
    this.light(0, { ...box, uid: -1, mode: 'dark', a: 0, strength: t < 0.9 ? 1 : 0 });
    this.candles.mesh.visible = t > 0.2 && t < 0.9;
    this.candles.begin();
    for (const p of this.spots) this.candles.at(p.x, this.ctx.ground(p.x, p.z) + 0.15, p.z);
    this.candles.end();
  }
}

// ---- the sky ---------------------------------------------------------------------------------------------------

/** Aurora curtains: a long ribbon of light, green at the hem to violet above, rippling. */
function curtain(parent: THREE.Object3D, len: number): THREE.Mesh {
  const geo = new THREE.PlaneGeometry(len, 9, 64, 1).translate(0, 4.5, 0);
  const mat = new THREE.ShaderMaterial({
    uniforms: { uT: { value: 0 }, uA: { value: 0 } },
    vertexShader: /* glsl */ `
      uniform float uT; varying vec2 vUv; varying float vX;
      void main() {
        vUv = uv; vX = position.x;
        vec3 p = position;
        p.z += sin(p.x * 0.12 + uT * 0.4) * 3.0 + sin(p.x * 0.31 - uT * 0.7) * 1.2;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
      }`,
    fragmentShader: /* glsl */ `
      uniform float uT; uniform float uA; varying vec2 vUv; varying float vX;
      void main() {
        float rays = 0.55 + 0.45 * sin(vX * 0.9 + uT * 1.6) * sin(vX * 0.37 - uT * 0.5);
        float fade = smoothstep(0.0, 0.12, vUv.y) * (1.0 - vUv.y) * (1.0 - vUv.y);
        float ends = smoothstep(0.0, 0.15, vUv.x) * smoothstep(1.0, 0.85, vUv.x);
        vec3 c = mix(vec3(0.2, 1.0, 0.55), vec3(0.62, 0.3, 1.0), smoothstep(0.25, 0.9, vUv.y));
        gl_FragColor = vec4(c * rays * fade * ends * uA, 1.0);
      }`,
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
  });
  const m = new THREE.Mesh(geo, mat);
  m.renderOrder = 5;
  m.frustumCulled = false;
  parent.add(m);
  return m;
}

/**
 * The sky's events over a county: a meteor shower's streaks, an eclipse dimming the day, the aurora's curtains, a
 * murmuration of starlings over the fields at dusk, the desert carpeted in flowers.
 */
class SkyShow extends Show {
  private c: Pt & { y: number };
  private meteorT = 0;
  private curtains: THREE.Mesh[] = [];
  private birds: THREE.Points | null = null;
  private flowers: THREE.InstancedMesh | null = null;
  private flowerAt: { x: number; y: number; z: number }[] = [];
  private m = new THREE.Matrix4();

  constructor(e: Happening, ctx: ShowCtx, private w: World, place: Place) {
    super(e, ctx);
    const p = toWorld(w, place.from!);
    this.c = { ...p, y: ctx.ground(p.x, p.z) };
    if (e.kind === 'aurora') {
      for (let k = 0; k < 3; k++) {
        const m = curtain(this.g, 70 - k * 12);
        m.position.set(this.c.x + (k - 1) * 6, this.c.y + 12 + k * 3, this.c.z - 10 + k * 8);
        m.rotation.y = 0.3 * (k - 1);
        this.curtains.push(m);
      }
    }
    if (e.kind === 'murmuration') {
      const n = 320;
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3).setUsage(THREE.DynamicDrawUsage));
      this.birds = new THREE.Points(g, new THREE.PointsMaterial({ color: 0x17181c, size: 0.09, sizeAttenuation: true }));
      this.birds.frustumCulled = false;
      this.g.add(this.birds);
    }
    if (e.kind === 'superbloom') {
      // flowers on the open ground round about: dry, unbuilt, off the roads
      // in drifts: a clump's middle, and a dozen flowers round it
      for (let k = 0; k < 4000 && this.flowerAt.length < 1400; k++) {
        const clump = Math.floor(k / 12), a0 = u01(e.h, clump * 2) * Math.PI * 2, r0 = Math.sqrt(u01(e.h, clump * 2 + 1)) * 22;
        const a = u01(e.h, 9000 + k) * Math.PI * 2, r1 = u01(e.h, 12000 + k) * 0.9;
        const x = p.x + Math.cos(a0) * r0 + Math.cos(a) * r1, z = p.z + Math.sin(a0) * r0 + Math.sin(a) * r1;
        const lx = Math.floor(x - w.ox), lz = Math.floor(z - w.oz);
        if (lx < 0 || lz < 0 || lx >= N || lz >= N) continue;
        const i = idx(lx, lz);
        if (w.water[i] >= 0 || w.blocked[i] || w.road[i]) continue;
        this.flowerAt.push({ x, y: ctx.ground(x, z) + 0.02, z });
      }
      this.flowers = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.075, 0).scale(1, 0.55, 1), new THREE.MeshStandardMaterial({ roughness: 0.8, flatShading: true }), Math.max(1, this.flowerAt.length));
      const col = new THREE.Color(), pal = [0xf2c14e, 0xf28c38, 0x8e5cc7, 0xf4f2ec, 0xf49ab5, 0xe2412f];
      this.flowerAt.forEach((_, i) => this.flowers!.setColorAt(i, col.setHex(pal[i % pal.length])));
      this.flowers.count = this.flowerAt.length;
      this.flowers.frustumCulled = false;
      this.g.add(this.flowers);
    }
  }

  centre(): Pt | null { return this.c; }

  update(now: number, dt: number): void {
    const e = this.e, t = now - e.start, on = now >= e.start && now < e.end, clock = performance.now() / 1000;
    this.g.visible = on;
    if (!on) return;
    const d = KIND_OF[e.kind].dur;
    switch (e.kind) {
      case 'meteorShower': {
        // a streak every second or two from one radiant, high over the county
        this.meteorT -= dt;
        if (this.meteorT <= 0 && this.ctx.night() > 0.5) {
          this.meteorT = 0.6 + Math.random() * 1.6;
          const head = u01(e.h, 3) * Math.PI * 2 + (Math.random() - 0.5) * 0.6;
          const sx = this.c.x + (Math.random() - 0.5) * 70, sz = this.c.z + (Math.random() - 0.5) * 70, sy = this.c.y + 16 + Math.random() * 6;
          const vx = Math.sin(head) * 22, vz = Math.cos(head) * 22, vy = -6;
          for (let k = 0; k < 14; k++) this.ctx.particles.spark({ x: sx - vx * k * 0.012, y: sy - vy * k * 0.012, z: sz - vz * k * 0.012, vx, vy, vz, life: 0.45 - k * 0.02, colour: k < 3 ? 0xffffff : 0xbfe0ff, size: 0.16 - k * 0.008, gravity: 0, drag: 0 });
        }
        break;
      }
      case 'eclipse': {
        // the dark comes over in a quarter of an hour, totality, and the sun back as fast
        const k = clamp01(t / (d * 0.3)) * (1 - clamp01((t - d * 0.7) / (d * 0.3)));
        this.ctx.dim(k);
        break;
      }
      case 'aurora': {
        const a = clamp01(t / 0.6) * (1 - clamp01((t - d + 0.6) / 0.6)) * this.ctx.night();
        for (const m of this.curtains) { const u = (m.material as THREE.ShaderMaterial).uniforms; u.uT.value = clock; u.uA.value = a * 0.55; }
        break;
      }
      case 'murmuration': {
        // the flock's middle wanders over the fields; the birds round it fold, stretch and turn as one
        const pos = this.birds!.geometry.getAttribute('position') as THREE.BufferAttribute;
        const cx = this.c.x + Math.sin(clock * 0.21) * 9, cy = this.c.y + 5 + Math.sin(clock * 0.33) * 1.2, cz = this.c.z + Math.cos(clock * 0.17) * 7;
        const sx = 3.2 + Math.sin(clock * 0.4) * 1.8, sy = 0.9 + Math.sin(clock * 0.55 + 1) * 0.5, sz = 1.8 + Math.cos(clock * 0.47) * 1.0;
        const rot = clock * 0.3, cr = Math.cos(rot), sr = Math.sin(rot), fade = clamp01(t / 0.15) * (1 - clamp01((t - d + 0.15) / 0.15));
        for (let i = 0; i < pos.count; i++) {
          // each bird's own place in the flock: a point in a ball, bent by a slow wave through it
          const u = u01(e.h, i * 3) * 2 - 1, th = u01(e.h, i * 3 + 1) * Math.PI * 2, rr = Math.cbrt(u01(e.h, i * 3 + 2));
          const q = Math.sqrt(1 - u * u);
          let x = Math.cos(th) * q * rr * sx, y = u * rr * sy, z = Math.sin(th) * q * rr * sz;
          y += Math.sin(x * 0.8 + clock * 1.3) * 0.5;
          z += Math.sin(y * 1.5 + clock) * 0.3;
          const X = x * cr - z * sr, Z = x * sr + z * cr;
          pos.setXYZ(i, cx + X * fade, fade > 0.01 ? cy + y : -100, cz + Z * fade);
        }
        pos.needsUpdate = true;
        break;
      }
      case 'superbloom': {
        // in flower over the first hours of the day, and closed again by evening
        const s = clamp01(t / 1.5) * (1 - clamp01((t - d + 1.5) / 1.5));
        const f = this.flowers!;
        this.flowerAt.forEach((p, i) => { const k = s * (0.6 + 0.4 * ((i * 7) % 5) / 4); this.m.makeScale(k, k, k).setPosition(p.x, p.y, p.z); f.setMatrixAt(i, this.m); });
        f.instanceMatrix.needsUpdate = true;
        break;
      }
    }
  }
}

/** Which of these shows a kind is put on as. */
export function phase4bShow(e: Happening, ctx: ShowCtx, w: World, p: Place): Show | null {
  switch (e.kind) {
    case 'fireboatSalute': case 'blessingFleet': return new HarbourShow(e, ctx, w, p);
    case 'whalePod': return new WhaleShow(e, ctx, w, p);
    case 'launchWatch': return new LaunchShow(e, ctx, w, p);
    case 'blackout': return new BlackoutShow(e, ctx, w, p);
    case 'meteorShower': case 'eclipse': case 'aurora': case 'murmuration': case 'superbloom': return new SkyShow(e, ctx, w, p);
    default: return null;
  }
}

