import * as THREE from 'three';
import type { PropGeometries } from './props';

/**
 * The Scenery side's pictures and ghosts (world/scenery.ts): each piece drawn from its own model. An icon is
 * the model's faces flat-shaded in their own colours onto a small canvas, from the south-east and a little
 * above, like the Passport's stamps; a ghost is the model in a see-through white the builder tints red
 * where the piece can't go.
 */

const icons = new Map<string, string>();
const ICON = 116;

export function sceneryIcon(geos: PropGeometries, id: string): string {
  const have = icons.get(id);
  if (have !== undefined) return have;
  const geom = (geos as unknown as Record<string, THREE.BufferGeometry | undefined>)[id];
  const url = geom ? drawIcon(geom) : '';
  icons.set(id, url);
  return url;
}

function drawIcon(geom: THREE.BufferGeometry): string {
  const g = geom.index ? geom.toNonIndexed() : geom;
  const pos = g.getAttribute('position'), col = g.getAttribute('color');
  if (!pos) return '';
  const yaw = Math.PI * 0.25, cy = Math.cos(yaw), sy = Math.sin(yaw), pitch = 0.5, cp = Math.cos(pitch), sp = Math.sin(pitch);
  const tris: { p: number[]; c: [number, number, number]; d: number }[] = [];
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (let i = 0; i + 2 < pos.count; i += 3) {
    const p: number[] = [];
    let depth = 0;
    const v: [number, number, number][] = [];
    for (let k = 0; k < 3; k++) {
      const x = pos.getX(i + k), y = pos.getY(i + k), z = pos.getZ(i + k);
      v.push([x, y, z]);
      const rx = x * cy - z * sy, rz = x * sy + z * cy;
      const px = rx, py = -(y * cp) + rz * sp;
      p.push(px, py);
      depth += rz * cp + y * sp;
      x0 = Math.min(x0, px); x1 = Math.max(x1, px); y0 = Math.min(y0, py); y1 = Math.max(y1, py);
    }
    const ax = p[2] - p[0], ay = p[3] - p[1], bx = p[4] - p[0], by = p[5] - p[1];
    if (ax * by - ay * bx >= 0) continue;
    // lit by a sun from the upper left, as the game's is
    const ux = v[1][0] - v[0][0], uy = v[1][1] - v[0][1], uz = v[1][2] - v[0][2];
    const wx = v[2][0] - v[0][0], wy = v[2][1] - v[0][1], wz = v[2][2] - v[0][2];
    const nx = uy * wz - uz * wy, ny = uz * wx - ux * wz, nz = ux * wy - uy * wx, nl = Math.hypot(nx, ny, nz) || 1;
    const lit = 0.62 + 0.38 * Math.max(0, (nx * -0.4 + ny * 0.8 + nz * 0.45) / nl);
    const c: [number, number, number] = col ? [col.getX(i) * lit, col.getY(i) * lit, col.getZ(i) * lit] : [lit * 0.6, lit * 0.6, lit * 0.6];
    tris.push({ p, c, d: depth / 3 });
  }
  if (!tris.length) return '';
  tris.sort((a, b) => b.d - a.d);
  const cv = document.createElement('canvas');
  cv.width = cv.height = ICON;
  const ctx = cv.getContext('2d');
  if (!ctx) return '';
  const span = Math.max(x1 - x0, y1 - y0) || 1, k = (ICON * 0.82) / span;
  const ox = ICON / 2 - ((x0 + x1) / 2) * k, oy = ICON / 2 - ((y0 + y1) / 2) * k;
  for (const t of tris) {
    const s = (v: number) => Math.round(Math.min(1, Math.max(0, v)) * 255);
    ctx.fillStyle = ctx.strokeStyle = `rgb(${s(t.c[0])},${s(t.c[1])},${s(t.c[2])})`;
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.moveTo(ox + t.p[0] * k, oy + t.p[1] * k);
    ctx.lineTo(ox + t.p[2] * k, oy + t.p[3] * k);
    ctx.lineTo(ox + t.p[4] * k, oy + t.p[5] * k);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }
  return cv.toDataURL('image/png');
}

/** The piece's model as a ghost: see-through, in a material of its own so the builder can tint it. */
export function sceneryGhost(geos: PropGeometries, id: string): THREE.Object3D | null {
  const geom = (geos as unknown as Record<string, THREE.BufferGeometry | undefined>)[id];
  if (!geom) return null;
  const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.55, depthWrite: false, vertexColors: true });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 8;
  return mesh;
}
