import { Desk, type LogIn } from './desk';
import { PRESS_HOUR, YEAR_H, type Issue, type Layout } from './types';

/**
 * A sample year for the console (pr.press.sample()) and for checking the layouts without playing forty
 * minutes: the kind of year a two-hour player has, run through a desk of its own and printed dry. `layout`
 * picks the front page (B needs `photo`, a still to lead with; D is a thin year); `rung` the Press's standing
 * for its tone. Nothing here touches the game's own desk. The names in it are the sample's own, not the world's.
 */
export function sampleIssue(fleet: string, opt: { layout?: Layout; photo?: string | null; rung?: number; n?: number } = {}): Issue | null {
  const quiet = opt.layout === 'D';
  const d = new Desk();
  const year = 3;
  let hours = (year - 1) * YEAR_H + 10;
  const towns: Record<string, { name: string; kind: string; style: string; news: boolean; x: number; z: number }> = {
    '0,0#0': { name: 'Harwick', kind: 'metro', style: 'victorian', news: true, x: 120, z: 140 },
    '0,0#1': { name: 'Ferrow', kind: 'city', style: 'tudor', news: false, x: 60, z: 90 },
    '0,0#2': { name: 'Nettleby', kind: 'rural', style: 'tudor', news: false, x: 150, z: 40 },
  };
  const grownAt = (year - 1) * YEAR_H + 20;
  d.host = {
    hours: () => hours, player: () => ({ x: 100, z: 100 }),
    townPos: (k) => towns[k] ? { x: towns[k].x, z: towns[k].z } : null,
    townInfo: (k) => towns[k] ? { key: k, ...towns[k], county: 'Harrow Riding' } : null,
    snapshot: () => {
      const grown = !quiet && hours > grownAt;
      return {
        units: grown ? 7 : 2, worth: grown ? 58900 : 6200, roads: [grown ? 1200 : 0, 3, 0], firms: {},
        book: grown ? { deliveries: 348, takings: 41600, units: 7, doors: 4, held: 1, worth: 58900 } : { deliveries: 112, takings: 9100, units: 2, doors: 1, held: 0, worth: 6200 },
        rival: { name: 'Harwick Cabs', units: 9, worth: 71200 },
      };
    },
    fleet: () => fleet, newsTowns: () => [], county: () => 'Harrow Riding', founded: () => 8, printed: () => {},
    sport: () => (quiet ? null : {
      league: 'Harrow Riding Football League', season: 14, ended: (year - 1) * YEAR_H + 60, homeWon: true, margin: 2,
      rows: [{ name: 'Harwick Athletic', rec: '7–1–2', pts: 22 }, { name: 'Ferrow Rovers', rec: '6–2–2', pts: 20 }, { name: 'Stanlow Town', rec: '4–3–3', pts: 15 }],
      home: { name: 'Nettleby United', pos: 6, of: 9 },
    }),
    rung: () => opt.rung ?? 3,
  };
  d.update(hours);
  // the layout turns with the issue number: start the sample's desk where the wanted one comes next
  const turn = opt.layout === 'B' ? 1 : opt.layout === 'C' ? 2 : 0;
  if (turn) d.issues.push({ n: turn, t: 0 } as Issue);
  d.seen.add('founded');
  for (const k of Object.keys(towns)) d.dealt(k, k === '0,0#0' ? 6 : 3);
  const log: LogIn[] = quiet ? [
    { k: 'vehicleBought', who: 'you', f: { model: 'Wasabi', price: 4200 }, pic: { kind: 'vehicle', model: 'wasabi' } },
    { k: 'weather', v: 'mist', f: { wx: 'fog', county: 'Harrow Riding' } },
    { k: 'rumour', town: '0,0#2', f: { town: 'Nettleby', line: 'The night freight is running late again.' } },
  ] : [
    { k: 'deedBought', who: 'you', town: '0,0#1', w: 5, f: { building: 'Grand Hotel', town: 'Ferrow', price: 18400 }, pic: { kind: 'building', b: 'hotel', arch: 'tudor', w: 2, d: 2, floors: 7 } },
    { k: 'firmCeased', who: 'Cardew & Sons', town: '0,0#1', f: { firm: 'Cardew & Sons', town: 'Ferrow' } },
    { k: 'weather', v: 'blizzard', f: { wx: 'a blizzard', county: 'Harrow Riding' } },
    { k: 'graduated', town: '0,0#1', f: { town: 'Ferrow', size: 'small city' } },
    { k: 'sealed', who: 'you', f: { page: 'wonders', treat: 'The Wonder Ball' } },
    { k: 'sealed', who: 'you', v: 'book', w: 5, f: { page: 'the whole passport', treat: 'The Gilded Fleet' } },
    { k: 'territoryWon', who: 'you', town: '0,0#1', f: { town: 'Ferrow', from: 'Cardew & Sons' } },
    { k: 'driverAce', who: 'you', f: { driver: 'Ines Marr' } },
    { k: 'vehicleBought', who: 'you', v: 'first', w: 4, f: { model: 'Jumbo', price: 52000, first: 'flyer', town: 'Harwick' }, pic: { kind: 'vehicle', model: 'jumbo' } },
    { k: 'protest', town: '0,0#2', f: { town: 'Nettleby', n: 23, to: 'city hall', cause: 'the levy of 10%' } },
    { k: 'event', v: 'parade', town: '0,0#1', w: 4, f: { event: 'ticker-tape parade', Event: 'Ticker-tape parade', blurb: 'A league champion’s open-top bus through its home town', blurbL: 'a league champion’s open-top bus through its home town', town: 'Ferrow', champion: 'Ferrow Otters', league: 'Harrow Soccer League' } },
    { k: 'event', v: 'regatta', town: '0,0#2', w: 3, f: { event: 'sailboat regatta', Event: 'Sailboat regatta', blurb: 'Dinghies racing a triangle of buoys in a bay', blurbL: 'dinghies racing a triangle of buoys in a bay', town: 'Nettleby', place: 'out in the bay' } },
    { k: 'built', town: '0,0#0', f: { town: 'Harwick', building: 'opera house' } },
    { k: 'rumour', town: '0,0#0', f: { town: 'Harwick', line: 'The night freight through Harwick is running late again.' } },
    { k: 'rumour', town: '0,0#2', f: { town: 'Nettleby', line: 'Somebody has left a boat under the viaduct.' } },
    { k: 'nightRun', who: 'you', f: { cargo: 'Moonshine', pay: 1400, place: 'Nettleby Distillery' } },
    { k: 'requestDone', who: 'you', town: '0,0#2', f: { title: 'Market day', job: 'market day', town: 'Nettleby' } },
  ];
  for (const e of log) { hours += 4; d.write(e); }
  // with a still: the headline's, and three more for the year in pictures
  if (opt.photo) for (const k of ['deedBought', 'built', 'protest', 'vehicleBought']) { const e = d.log.find((q) => q.k === k && !q.jpg); if (e) e.jpg = opt.photo; }
  d.weather('storm', 3.4); d.weather('mist', 9.2); if (!quiet) d.weather('blizzard', 5.1);
  hours = year * YEAR_H + PRESS_HOUR;
  const p = d.press(hours, true);
  if (!p) return null;
  return { ...p.issue, n: opt.n ?? p.issue.n };
}
