/**
 * A fee asked before it is paid (the user, 4 Nov 2026: bringing a vehicle out of the garage far from where it went
 * in is a tow, and the player says yes to the price first). A centred card over everything, the HQ window
 * included: a title, a line saying why, the price, and Decline / Accept. Enter accepts, Esc or Backspace declines;
 * while it is up the game's own keys wait (main.ts counts it as a menu).
 */
import { esc, money } from './cargoHud';

export interface FeeAsk {
  title: string;
  /** Why there is a fee, in a sentence or two. */
  line: string;
  fee: number;
  /** The accept button's words, before the price ("Bring it out"). */
  act: string;
  accept: () => void;
  decline?: () => void;
}

export class FeeCard {
  private el: HTMLElement | null = null;
  private now: FeeAsk | null = null;
  private keys = (e: KeyboardEvent) => {
    if (!this.now) return;
    if (e.code === 'Enter' || e.code === 'NumpadEnter') { e.preventDefault(); e.stopPropagation(); this.answer(true); }
    else if (e.code === 'Escape' || e.code === 'Backspace') { e.preventDefault(); e.stopPropagation(); this.answer(false); }
  };

  get isOpen(): boolean { return !!this.now; }

  ask(a: FeeAsk): void {
    if (this.now) this.answer(false);
    this.now = a;
    const el = this.el ??= (() => {
      const d = document.createElement('div');
      d.id = 'fee-card';
      d.setAttribute('role', 'dialog');
      d.setAttribute('aria-modal', 'true');
      d.addEventListener('mousedown', (e) => { if (e.target === d) this.answer(false); });
      d.addEventListener('click', (e) => {
        const b = (e.target as HTMLElement).closest<HTMLElement>('[data-fee]');
        if (b) this.answer(b.dataset.fee === 'yes');
      });
      document.body.append(d);
      return d;
    })();
    el.innerHTML = `<div class="fc-card"><h3>${esc(a.title)}</h3><p>${esc(a.line)}</p>`
      + `<div class="fc-fee"><span>Tow fee</span><b>${money(a.fee)}</b></div>`
      + `<div class="fc-row"><button type="button" data-fee="no">Decline <kbd>Esc</kbd></button>`
      + `<button type="button" class="go" data-fee="yes">${esc(a.act)} · ${money(a.fee)} <kbd>Enter</kbd></button></div></div>`;
    el.hidden = false;
    window.addEventListener('keydown', this.keys, true);
    el.querySelector<HTMLElement>('.go')?.focus({ preventScroll: true });
  }

  private answer(yes: boolean): void {
    const a = this.now;
    if (!a) return;
    this.now = null;
    if (this.el) this.el.hidden = true;
    window.removeEventListener('keydown', this.keys, true);
    if (yes) a.accept(); else a.decline?.();
  }
}
