import type { LocalWire, Pick } from '../../../shared/marks';
import { press } from './desk';

/**
 * The news wire into the annual paper (server/news.ts, the user, 5 Nov 2026): the stories the online server tells,
 * written down once each as the desk's `wire` events, by whose news they are to this player. Their own fleet's,
 * their circle's and their county's come from /wire.json; the rest of the world's from online.json, the big ones
 * only (the paper prints one of those at most, and a box of the rest). At press time the desk scores them with
 * everything else that happened near the player (game/press/desk.ts), and names the year's Fleet of the Year from them.
 *
 * Every event's words are the story's own (its headline, its line, its desk, its county, its fleet), so the copy
 * stays inside what happened. Each is written with the hour it came in, so no still of the moment is taken for news
 * that happened somewhere else.
 */

/** The least weight a story from beyond the player's county, circle and fleet needs to be written down. */
export const WORLD_MIN = 3;

/** Write the wire's stories down, each once: how many were new. */
export function wireToPress(world: readonly Pick[], local: LocalWire | null, hours: number): number {
  let n = 0;
  const seen = new Set<string>();
  const one = (s: Pick, scope: string) => {
    if (!s.id || seen.has(s.id)) return;
    seen.add(s.id);
    if (scope === 'world' && (s.w ?? 0) < WORLD_MIN) return;
    const at = s.x !== undefined && s.z !== undefined ? { x: s.x, z: s.z } : undefined;
    const e = press.once(`wire|${s.id}`, {
      k: 'wire', v: scope, who: scope === 'you' ? 'you' : s.who || '', t: hours, w: Math.max(1, Math.min(5, s.w ?? 2)),
      ...(at ? { at } : {}),
      f: { title: s.title, detail: s.detail, desk: s.tag ?? '', county: s.county ?? '', by: s.who },
    });
    if (e) n++;
  };
  // the reader's own first, so a story that is both theirs and the world's is told as theirs
  for (const s of local?.stories ?? []) one(s, s.scope ?? 'county');
  for (const s of world) one(s, 'world');
  return n;
}
