import { httpUrl } from './online';
import { setTaglines } from '../title/menu';

/**
 * The title's taglines as the developer last set them on /dev (server/admin.ts, shared/taglines.ts): asked
 * for once at start and kept, so the next start shows them at once even before the server answers. No
 * server, or no list set there: the defaults in shared/taglines.ts.
 */
const KEY = 'tf-taglines';

export function loadTaglines(server: string): void {
  try {
    const kept = JSON.parse(localStorage.getItem(KEY) ?? 'null') as string[] | null;
    if (Array.isArray(kept) && kept.length) setTaglines(kept);
  } catch { /* nothing kept */ }
  const base = httpUrl(server);
  if (!base) return;
  fetch(`${base}/api/taglines`, { cache: 'no-store' })
    .then((r) => (r.ok ? r.json() : null))
    .then((j: { list?: string[] | null } | null) => {
      if (!j) return;
      const list = Array.isArray(j.list) ? j.list.filter((t) => typeof t === 'string' && t.trim()) : null;
      // a list set on the server, or none (the defaults again)
      setTaglines(list && list.length ? list : null);
      try { if (list && list.length) localStorage.setItem(KEY, JSON.stringify(list)); else localStorage.removeItem(KEY); } catch { /* not kept */ }
    })
    .catch(() => { /* offline: what was kept stands */ });
}
