import type { Arch, TownKind } from '../world/tiles';
import type { TownDigest } from '../world/townDigest';

/**
 * The town register's measures and filters (docs/townregister.html): each sort a function from a row to a number,
 * kept in one table so a new measure is one line. A row is a town's digest with its books joined, gathered once
 * per redraw by the register. Nothing here imports the game, so the server ranks the World scope with it too
 * (server/gazetteer.ts).
 */

/** A town in the register: its digest, and what the books say of it now. */
export interface RegisterRow {
  d: TownDigest;
  /** On an island in memory. */
  near: boolean;
  /** Trade, $/h, and the same against the norm for its size. */
  rate: number;
  prosperity: number;
  /** Buildings grown over its last 30 days of history. */
  grown30: number;
  /** Boarded up, by its books (or its digest when it has none). */
  blight: number;
  /** Culture points summed over every style it imported; styles at Influenced or above; points by style. */
  culture: number;
  cultures: number;
  styles: Record<string, { pts: number; rung: number; label: string }>;
  /** Its property's worth. */
  value: number;
  /** Your earnings there, and your share of its carriage. */
  mine: number;
  share: number;
  /** Whose territory: '' nobody; YOU for yours. Contested by someone. Your rung of its ladder. */
  holder: string;
  contested: boolean;
  rung: number;
  starred: boolean;
  /** Any delivery or pickup of yours ever made there. */
  visited: boolean;
  /** World tiles from your vehicle, or null. */
  dist: number | null;
}

export type SortId = 'built' | 'area' | 'growing' | 'cultured' | 'cultures' | 'oneCulture' | 'works' | 'hearts' | 'busy' | 'playerBuilt' | 'trade' | 'prosperous'
  | 'valuable' | 'need' | 'sights' | 'connected' | 'mine' | 'share' | 'near' | 'name';

export interface SortSpec {
  id: SortId;
  group: string;
  label: string;
  /** Bigger is better, unless `low` (nearest first, A–Z). */
  of(r: RegisterRow, style: string): number;
  /** The measure as the row shows it. */
  show(r: RegisterRow, style: string): string;
  low?: boolean;
}

const money = (n: number): string => `$${Math.round(n).toLocaleString('en-US')}`;
const n0 = (n: number): string => Math.round(n).toLocaleString('en-US');
/** Players' works in its lines, as last counted: [count, hearts, crossings]. */
const worksOf = (d: TownDigest): [number, number, number] => d.works ?? [0, 0, 0];
const sightsOf = (d: TownDigest): number => d.notable.reduce((s, [, n]) => s + n, 0);
const linksOf = (d: TownDigest): number => d.roadsTo + d.stations + d.ports * 2 + d.airports * 3;

export const SORTS: SortSpec[] = [
  { id: 'built', group: 'Size', label: 'Most buildings', of: (r) => r.d.built, show: (r) => `${n0(r.d.built)} buildings` },
  { id: 'area', group: 'Size', label: 'Largest', of: (r) => r.d.area, show: (r) => `${n0(r.d.area)} tiles` },
  { id: 'growing', group: 'Size', label: 'Fastest growing', of: (r) => r.grown30, show: (r) => `+${r.grown30} in 30 days` },
  { id: 'cultured', group: 'Culture', label: 'Most cultured', of: (r) => r.culture, show: (r) => `${n0(r.culture)} culture points` },
  { id: 'cultures', group: 'Culture', label: 'Most cultures', of: (r) => r.cultures * 1e6 + r.culture, show: (r) => `${r.cultures} influenced` },
  { id: 'oneCulture', group: 'Culture', label: 'Most of one culture', of: (r, s) => r.styles[s]?.pts ?? 0, show: (r, s) => (r.styles[s] ? `${n0(r.styles[s].pts)} ${r.styles[s].label}` : '—') },
  { id: 'works', group: 'Community', label: 'Most works', of: (r) => worksOf(r.d)[0], show: (r) => `${worksOf(r.d)[0]} works` },
  { id: 'hearts', group: 'Community', label: 'Most hearts', of: (r) => worksOf(r.d)[1] * 1e4 + worksOf(r.d)[0], show: (r) => `♥ ${worksOf(r.d)[1]}` },
  { id: 'busy', group: 'Community', label: 'Busiest works', of: (r) => worksOf(r.d)[2], show: (r) => `${n0(worksOf(r.d)[2])} crossings` },
  { id: 'playerBuilt', group: 'Community', label: 'Most fleet-built', of: (r) => r.d.playerBuilt, show: (r) => `${r.d.playerBuilt} fleet-built` },
  { id: 'trade', group: 'Economy', label: 'Biggest trade', of: (r) => r.rate, show: (r) => `${money(r.rate)}/h` },
  { id: 'prosperous', group: 'Economy', label: 'Most prosperous', of: (r) => r.prosperity, show: (r) => `${r.prosperity.toFixed(2)}×` },
  { id: 'valuable', group: 'Economy', label: 'Most valuable', of: (r) => r.value, show: (r) => (r.value ? money(r.value) : '—') },
  { id: 'need', group: 'Economy', label: 'Most in need', of: (r) => r.blight * 100 + (2 - Math.min(2, r.prosperity)), show: (r) => (r.blight ? `${r.blight} boarded up` : `${r.prosperity.toFixed(2)}×`) },
  { id: 'sights', group: 'Places', label: 'Most to see', of: (r) => sightsOf(r.d), show: (r) => `${sightsOf(r.d)} sights` },
  { id: 'connected', group: 'Places', label: 'Best connected', of: (r) => linksOf(r.d), show: (r) => [r.d.roadsTo ? `${r.d.roadsTo} roads` : '', r.d.stations ? `${r.d.stations} stn` : '', r.d.ports ? `${r.d.ports} port` : '', r.d.airports ? `${r.d.airports} air` : ''].filter(Boolean).join(' · ') || 'roads only' },
  { id: 'mine', group: 'You', label: 'Your trade', of: (r) => r.mine, show: (r) => (r.mine ? money(r.mine) : '—') },
  { id: 'share', group: 'You', label: 'Your share', of: (r) => r.share, show: (r) => `${Math.round(r.share * 100)}%` },
  { id: 'near', group: 'Other', label: 'Nearest', of: (r) => r.dist ?? Infinity, show: (r) => (r.dist === null ? '—' : r.dist < 24 ? 'here' : r.dist < 192 ? `${Math.round(r.dist)} tiles` : `${(r.dist / 256).toFixed(1)} counties`), low: true },
  { id: 'name', group: 'Other', label: 'A–Z', of: () => 0, show: (r) => r.d.county, low: true },
];

export const SORT_BY: Record<SortId, SortSpec> = Object.fromEntries(SORTS.map((s) => [s.id, s])) as Record<SortId, SortSpec>;

/** What the filter chips have picked. Within a group any may match; across groups all must. */
export interface Filters {
  kinds: TownKind[];
  /** Its own style. */
  style: Arch | '';
  /** A culture it has imported, and the least rung (1 Curiosity, 2 Influenced, 3 Infatuated). */
  culture: string;
  rung: number;
  /** 0 any; else within this many counties of you. */
  within: number;
  county: string;
  ports: boolean; stations: boolean; airports: boolean;
  /** '' any; 'you' yours; 'rival' someone else's; 'none' nobody's; 'contested'. */
  holder: '' | 'you' | 'rival' | 'none' | 'contested';
  specials: ('plan' | 'onsen' | 'lake' | 'canals' | 'strip' | 'perch' | 'wonder' | 'stadium')[];
  starred: boolean;
  visited: '' | 'yes' | 'no';
  satellites: boolean;
}

export const NO_FILTERS = (): Filters => ({
  kinds: [], style: '', culture: '', rung: 1, within: 0, county: '', ports: false, stations: false, airports: false,
  holder: '', specials: [], starred: false, visited: '', satellites: true,
});

/** Does a row pass every picked filter? `you` is the player's own carrier id. */
export function passes(r: RegisterRow, f: Filters, you: string): boolean {
  const d = r.d;
  if (f.kinds.length && !f.kinds.includes(d.kind)) return false;
  if (!f.satellites && d.parent) return false;
  if (f.style && d.style !== f.style) return false;
  if (f.culture && (r.styles[f.culture]?.rung ?? 0) < f.rung) return false;
  if (f.within && (r.dist === null || r.dist > f.within * 256 + 128)) return false;
  if (f.county && d.county !== f.county) return false;
  if (f.ports && !d.ports) return false;
  if (f.stations && !d.stations) return false;
  if (f.airports && !d.airports) return false;
  if (f.holder === 'you' && r.holder !== you) return false;
  if (f.holder === 'rival' && (!r.holder || r.holder === you)) return false;
  if (f.holder === 'none' && r.holder) return false;
  if (f.holder === 'contested' && !r.contested) return false;
  for (const s of f.specials) {
    if (s === 'wonder' ? !d.cats.wonder : s === 'stadium' ? !d.notable.some(([k]) => k === 'stadium') : !d[s]) return false;
  }
  if (f.starred && !r.starred) return false;
  if (f.visited === 'yes' && !r.visited) return false;
  if (f.visited === 'no' && r.visited) return false;
  return true;
}

/** Rows that pass, sorted by a measure (best first; ties by name), flipped if asked. */
export function ranked(rows: RegisterRow[], sort: SortId, style: string, flip = false): RegisterRow[] {
  const s = SORT_BY[sort];
  const dir = (s.low ? 1 : -1) * (flip ? -1 : 1);
  return rows.map((r) => ({ r, v: s.of(r, style) }))
    .sort((a, b) => (a.v === b.v ? a.r.d.name.localeCompare(b.r.d.name) : (a.v < b.v ? -1 : 1) * dir))
    .map((x) => x.r);
}

/** The filters as a sentence: "cities and up, Influenced by Tokyo, with a harbour". Empty when none are picked. */
export function filterWords(f: Filters, kindLabel: (k: TownKind) => string, styleLabel: (s: string) => string, cultureLabel: (s: string) => string): string {
  const out: string[] = [];
  if (f.kinds.length) out.push(f.kinds.map(kindLabel).join(' or '));
  if (!f.satellites) out.push('no satellites');
  if (f.style) out.push(`${styleLabel(f.style)} style`);
  if (f.culture) out.push(`${['', 'curious about', 'Influenced by', 'Infatuated with'][f.rung]} ${cultureLabel(f.culture)}`);
  if (f.within) out.push(`within ${f.within} ${f.within === 1 ? 'county' : 'counties'}`);
  if (f.county) out.push(`in ${f.county}`);
  const by = [f.ports ? 'a harbour' : '', f.stations ? 'a station' : '', f.airports ? 'an airport' : ''].filter(Boolean);
  if (by.length) out.push(`with ${by.join(' and ')}`);
  if (f.holder) out.push({ you: 'yours', rival: 'held by another fleet', none: 'held by nobody', contested: 'contested' }[f.holder]);
  if (f.specials.length) out.push(f.specials.map((s) => SPECIAL_LABEL[s]).join(', '));
  if (f.starred) out.push('bookmarked');
  if (f.visited) out.push(f.visited === 'yes' ? 'visited' : 'never visited');
  return out.join(' · ');
}

export const SPECIAL_LABEL: Record<Filters['specials'][number], string> = {
  plan: 'a city plan', onsen: 'onsen town', lake: 'lake town', canals: 'canals', strip: 'a Strip', perch: 'perched', wonder: 'a wonder', stadium: 'a stadium',
};
