import { hex, mix, scale, type RGB } from '../../world/biomes';
import type { ThemeKind } from '../../world/tiles';
import type { Sched } from '../nightLights';
import { GLASS_LIGHT, LEAF, TAU, WARM_GLOW, WHITE, row, tree, type Draw, type Kit, type P3 } from './kit';
import { BULB, ENAMEL_RED, bladeName, bulbRow, frontText, marquee, marqueeBoards, type BoardSpot } from './neon';

/**
 * Chicago's landmarks, swapped in by its town style (STYLE_SWAPS in world/towns.ts). Each stands on its lot
 * centred on the origin, its front to +z.
 *
 * - **Willis Tower** (skyscraper, office): nine black square tubes bundled three by three, stopping at four
 *   heights, two white masts on the tallest pair, and the glass Ledge out of its west face.
 * - **John Hancock Center** (glass spire, condo tower): a tapering black tower crossed by its giant X braces.
 * - **Marina City** (tower block): the two corn cobs by the river, a spiral car park under scalloped balconies.
 * - **Wrigley Building** (hotel): white terracotta and a clock tower, floodlit white all night.
 * - **Tribune Tower** (courthouse, ministry): the Gothic newspaper tower and its crown of flying buttresses.
 * - **Chicago Theatre** (theatre): the triumphal-arch front, C-H-I-C-A-G-O down the great red sign in bulbs,
 *   the marquee under it with the day's shows (game/screens.ts).
 * - **Cloud Gate** (fountain square, sculpture park): the Bean, a mirror of the sky on its plaza.
 */

const BLACK = hex(0x26282c), BLACK_GLASS = hex(0x34383e), BRONZE_GLASS = hex(0x4a4640), MAST = hex(0xe8e8e4);
const TERRA = hex(0xf2efe6), TERRA_SHADE = hex(0xdcd6c8), CONCRETE = hex(0xd8d4cc), LIME = hex(0xe2dccb);
const STEEL_SKY = hex(0xc8d6e2), STEEL_MID = hex(0xaab4bc), STEEL_LOW = hex(0x7e8890);
/** Office windows lit after dark, floodlights from dusk to the small hours, beacons all night. */
const OFFICE: Sched = [17, 23, 1.2], FLOOD: Sched = [18, 26, 1.3], BEACON: Sched = [0, 36, 2.8];

/** Light strips up every face of a block: a tower's mullions. */
function mullions(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB, gap: number): void {
  for (let o = -w / 2 + gap / 2; o < w / 2 - 0.01; o += gap) {
    k.box(x + o, y, z + d / 2 + 0.004, 0.018, h, 0.008, col);
    k.box(x + o, y, z - d / 2 - 0.004, 0.018, h, 0.008, col);
  }
  for (let o = -d / 2 + gap / 2; o < d / 2 - 0.01; o += gap) {
    k.box(x + w / 2 + 0.004, y, z + o, 0.008, h, 0.018, col);
    k.box(x - w / 2 - 0.004, y, z + o, 0.008, h, 0.018, col);
  }
}

// ---- Willis Tower ---------------------------------------------------------------------------------

const willisTower: Draw = (k, W, D) => {
  const s = (Math.min(W, D) - 0.24) / 3;
  // tube tops in world units, laid out with -z north: the two tallest down the west side of the middle
  const tops = [
    [5.2, 9.3, 6.9],
    [11.2, 11.2, 9.3],
    [6.9, 9.3, 5.2],
  ];
  for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) {
    const x = (i - 1) * s, z = (j - 1) * s, top = tops[j][i];
    k.box(x, 0, z, s, top, s, BLACK_GLASS, BLACK);
    // the bronze-tinted glass between black mullions, and the white mechanical floors
    mullions(k, x, 0.15, z, s, s, top - 0.2, hex(0x1e2024), 0.1);
    for (let y = 2.2; y < top - 0.3; y += 2.2) k.box(x, y, z, s + 0.012, 0.06, s + 0.012, hex(0x5a5a5c));
    // a few floors lit after dark, at heights of the tube's own
    for (let n = 0; n < 3; n++) {
      const y = 0.6 + ((i * 7 + j * 5 + n * 11) % 9) * (top - 1.0) / 9;
      k.glowBox(x, y, z, s + 0.008, 0.07, s + 0.008, BRONZE_GLASS, OFFICE, WARM_GLOW);
    }
  }
  // the masts on the two tallest tubes, beacons on their tips
  for (const [x, z, h] of [[-s, 0, 2.2], [0, 0, 1.8]] as const) {
    k.box(x, 11.2, z, 0.05, h, 0.05, MAST);
    k.glowBox(x, 11.2 + h, z, 0.06, 0.06, 0.06, hex(0xe2412f), BEACON, hex(0xff4a3a));
  }
  // the Ledge: a glass box out of the west face near the top, lit at night
  k.glowBox(-1.5 * s - 0.06, 10.5, 0, 0.12, 0.12, 0.14, GLASS_LIGHT, FLOOD, hex(0xe8f4ff));
  // the lobby at the foot
  k.glowBox(0, 0, 1.5 * s + 0.02, s * 1.6, 0.24, 0.03, GLASS_LIGHT, [6, 30, 1.2], WARM_GLOW);
};

// ---- John Hancock Center --------------------------------------------------------------------------

const hancockCenter: Draw = (k, W, D) => {
  const a0 = (W - 0.3) / 2, b0 = (D - 0.6) / 2, a1 = a0 * 0.62, b1 = b0 * 0.62, H = 9.2;
  const at = (sx: number, sz: number, t: number): P3 => [sx * (a0 + (a1 - a0) * t), H * t, sz * (b0 + (b1 - b0) * t)];
  const I: P3 = [0, H / 2, 0];
  // the four tapering faces in black, the roof
  const C: [number, number][] = [[-1, 1], [1, 1], [1, -1], [-1, -1]];
  for (let f = 0; f < 4; f++) {
    const [ax, az] = C[f], [bx, bz] = C[(f + 1) % 4];
    k.quad(at(ax, az, 0), at(bx, bz, 0), at(bx, bz, 1), at(ax, az, 1), BLACK_GLASS, I);
  }
  k.quad(at(-1, 1, 1), at(1, 1, 1), at(1, -1, 1), at(-1, -1, 1), BLACK, [0, 0, 0]);
  // the corner columns and the giant X braces, five storeys of them up every face
  for (const [sx, sz] of C) k.bar(at(sx, sz, 0), at(sx, sz, 1), 0.035, BLACK);
  const X = 5;
  for (let f = 0; f < 4; f++) {
    const [ax, az] = C[f], [bx, bz] = C[(f + 1) % 4];
    const out = (p: P3): P3 => [p[0] * 1.01, p[1], p[2] * 1.01];
    for (let i = 0; i < X; i++) {
      const t0 = i / X, t1 = (i + 1) / X;
      k.bar(out(at(ax, az, t0)), out(at(bx, bz, t1)), 0.022, BLACK);
      k.bar(out(at(bx, bz, t0)), out(at(ax, az, t1)), 0.022, BLACK);
      // the tie at each X's top
      k.bar(out(at(ax, az, t1)), out(at(bx, bz, t1)), 0.018, BLACK);
    }
  }
  // the lit observatory band near the top, the white crown band, and the two masts
  k.glowBox(0, H - 0.5, 0, a1 * 2 + 0.04, 0.12, b1 * 2 + 0.04, BLACK_GLASS, FLOOD, hex(0xf4f6ff));
  k.box(0, H, 0, a1 * 2, 0.08, b1 * 2, MAST);
  for (const sx of [-1, 1]) {
    k.box(sx * a1 * 0.5, H + 0.08, 0, 0.05, 2.0, 0.05, MAST);
    k.glowBox(sx * a1 * 0.5, H + 2.08, 0, 0.06, 0.06, 0.06, hex(0xe2412f), BEACON, hex(0xff4a3a));
  }
  // the sunken plaza in front
  k.box(0, 0, D / 2 - 0.15, W - 0.4, 0.02, 0.2, CONCRETE);
};

// ---- Marina City ----------------------------------------------------------------------------------

/** One corn cob: the spiral car park, then the glass drum under its scalloped balconies, then the roof. */
function cob(k: Kit, x: number, z: number, R: number, H: number): void {
  const park = H * 0.3, seg = 12;
  k.cyl(x, 0, z, R * 0.7, H, CONCRETE, seg);
  // the car park: open floors spiralling round the core, a car's colour now and then
  for (let y = 0.02; y < park; y += 0.18) {
    k.cyl(x, y, z, R, 0.025, CONCRETE, seg);
    k.cyl(x, y + 0.025, z, R * 0.92, 0.155, hex(0x3a3c40), seg);
  }
  // the flats: a glass drum, a balcony ring every floor whose rim scallops round the cob
  k.cyl(x, park, z, R * 0.84, H - park, hex(0x6a7a86), seg);
  for (let y = park + 0.05; y < H - 0.08; y += 0.17) {
    k.cyl(x, y, z, R, 0.022, CONCRETE, seg);
  }
  for (let n = 0; n < 4; n++) {
    const y = park + 0.3 + ((n * 7 + Math.round(x * 10)) % 9) * (H - park - 0.6) / 9;
    k.glowBox(x, y, z, R * 1.5, 0.1, R * 1.5, hex(0x6a7a86), [17.5, 24, 1.2], WARM_GLOW);
  }
  k.cyl(x, H, z, R * 1.02, 0.05, CONCRETE, seg);
  k.cyl(x, H + 0.05, z, R * 0.4, 0.14, CONCRETE, 8);
}

const marinaCity: Draw = (k, W, D) => {
  const R = Math.min((W - 0.3) / 4, (D - 0.4) / 2) * 0.95, H = 5.4;
  // the low podium (the theatre and the marina), then the two cobs side by side
  k.box(0, 0, -D / 2 + 0.35, W - 0.3, 0.3, 0.5, CONCRETE);
  for (const sx of [-1, 1]) cob(k, sx * (W - 0.3) / 4, 0.05, R, H);
};

// ---- Wrigley Building -----------------------------------------------------------------------------

const wrigleyBuilding: Draw = (k, W, D, b, r) => {
  const bw = W - 0.3, bd = D - 0.5, H = 2.0, z = -0.1, front = z + bd / 2;
  k.box(0, 0, z, bw, H, bd, TERRA, TERRA_SHADE);
  // the bands, the windows, the cornice
  for (let f = 1; f < 7; f++) k.box(0, f * 0.28, z, bw + 0.02, 0.02, bd + 0.02, TERRA_SHADE);
  for (let f = 0; f < 6; f++) row(k, b, r, 0, 0.1 + f * 0.28, front, bw - 0.1, 0.13, 7, 1, GLASS_LIGHT);
  k.box(0, H, z, bw + 0.06, 0.08, bd + 0.06, TERRA_SHADE);
  // the clock tower over the front corner: shaft, the clock stage, the lantern and its spire
  const tx = bw / 2 - 0.32, tz = front - 0.3, tw = 0.5;
  k.box(tx, H, tz, tw, 0.7, tw, TERRA);
  k.box(tx, H + 0.7, tz, tw + 0.06, 0.04, tw + 0.06, TERRA_SHADE);
  k.box(tx, H + 0.74, tz, tw * 0.86, 0.34, tw * 0.86, TERRA);
  // four clock faces (gold on white) on the clock stage
  const cy = H + 0.91, half = tw * 0.43 + 0.006;
  k.face(tx, cy, tz + half, 0.11, hex(0xf6f2e2), 12);
  k.face(tx, cy, tz + half + 0.003, 0.02, hex(0xc8a040), 6);
  k.turned(Math.PI / 2, () => { k.face(-tz, cy, tx + half, 0.11, hex(0xf6f2e2), 12); });
  k.turned(-Math.PI / 2, () => { k.face(tz, cy, -tx + half, 0.11, hex(0xf6f2e2), 12); });
  k.turned(Math.PI, () => { k.face(-tx, cy, -tz + half, 0.11, hex(0xf6f2e2), 12); });
  k.cyl(tx, H + 1.08, tz, tw * 0.3, 0.3, TERRA, 8);
  k.cone(tx, H + 1.38, tz, tw * 0.22, 0.4, TERRA_SHADE, 8);
  // floodlit white all night, as it has been since 1921
  k.glowBox(0, 0.02, z, bw + 0.01, H - 0.04, bd + 0.01, TERRA, FLOOD, hex(0xfff8ec));
  k.glowBox(tx, H + 0.02, tz, tw + 0.01, 0.66, tw + 0.01, TERRA, FLOOD, hex(0xfff8ec));
};

// ---- Tribune Tower --------------------------------------------------------------------------------

const tribuneTower: Draw = (k, W, D, b, r) => {
  const stone = hex(0xd8d0bc), shade = scale(stone, 0.84);
  const base = Math.min(W, D) - 0.5, sw = Math.min(0.9, base * 0.62), H = 3.4;
  // the base block, the shaft with its piers running up, the crown
  k.box(0, 0, 0, base, 0.6, base, stone);
  k.box(0, 0.6, 0, base + 0.04, 0.04, base + 0.04, shade);
  k.box(0, 0.64, 0, sw, H - 0.64, sw, stone);
  for (let o = -sw / 2; o <= sw / 2 + 1e-6; o += sw / 5) {
    k.box(o, 0.64, sw / 2 + 0.01, 0.03, H - 0.64, 0.03, shade);
    k.box(o, 0.64, -sw / 2 - 0.01, 0.03, H - 0.64, 0.03, shade);
    k.box(sw / 2 + 0.01, 0.64, o, 0.03, H - 0.64, 0.03, shade);
    k.box(-sw / 2 - 0.01, 0.64, o, 0.03, H - 0.64, 0.03, shade);
  }
  for (let f = 0; f < 3; f++) row(k, b, r, 0, 0.12 + f * 0.16, base / 2, base - 0.2, 0.1, 6, 1, GLASS_LIGHT);
  // the octagonal lantern and the eight flying buttresses leaning in to it, a pinnacle on each
  const lr = sw * 0.32, ly = H;
  for (let i = 0; i < 8; i++) {
    // its eight faces floodlit after dark
    const a0 = (i / 8) * TAU, a1 = ((i + 1) / 8) * TAU;
    k.glowQuad([Math.cos(a0) * lr, ly, Math.sin(a0) * lr], [Math.cos(a1) * lr, ly, Math.sin(a1) * lr], [Math.cos(a1) * lr, ly + 0.55, Math.sin(a1) * lr],
      [Math.cos(a0) * lr, ly + 0.55, Math.sin(a0) * lr], [0, ly + 0.27, 0], stone, FLOOD, hex(0xfff0d0));
  }
  k.cone(0, ly + 0.55, 0, lr * 0.9, 0.32, shade, 8);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + TAU / 16, ox = Math.cos(a) * sw * 0.55, oz = Math.sin(a) * sw * 0.55;
    k.bar([ox, ly - 0.05, oz], [Math.cos(a) * lr, ly + 0.45, Math.sin(a) * lr], 0.025, stone);
    k.box(ox, ly - 0.1, oz, 0.05, 0.3, 0.05, stone);
    k.cone(ox, ly + 0.2, oz, 0.035, 0.14, shade, 4);
  }
  // the entrance arch
  k.box(0, 0, base / 2 + 0.006, 0.26, 0.4, 0.01, hex(0x3a3028));
};

// ---- the Chicago Theatre ---------------------------------------------------------------------------

/** The Chicago's marquee across its front: the boards game/screens.ts writes the day's shows on. */
export const chicagoBoards = (W: number, D: number): BoardSpot[] => marqueeBoards(0, 0.34, D / 2 - 0.45, Math.min(1.7, W * 0.85), 0.24, 0.42);

const chicagoTheatre: Draw = (k, W, D, b, r) => {
  const fz = D / 2 - 0.45, fw = W - 0.2, fh = 1.66, brick = hex(0x8a4a36);
  // the house behind, in brick
  k.box(0, 0, -0.35, W - 0.3, 1.2, D - 1.1, brick);
  k.box(0, 0, -D / 2 + 0.3, W * 0.6, 1.6, 0.4, scale(brick, 0.9));
  // the front: cream terracotta, a triumphal arch round the great window, a cornice and a crested parapet
  k.box(0, 0, fz - 0.2, fw, fh, 0.4, TERRA, TERRA_SHADE);
  for (const s of [-1, 1]) {
    k.box(s * (fw / 2 - 0.12), 0, fz + 0.006, 0.18, fh, 0.02, TERRA_SHADE);
    row(k, b, r, s * (fw / 2 - 0.45), 0.7, fz, 0.36, 0.16, 2, 1, GLASS_LIGHT);
    row(k, b, r, s * (fw / 2 - 0.45), 1.05, fz, 0.36, 0.16, 2, 1, GLASS_LIGHT);
  }
  // the arch: its frame, its glass lit warm behind, its round head
  const aw = 0.62, ay = 0.66, ah = 0.62;
  k.box(0, ay - 0.04, fz + 0.008, aw + 0.1, ah + 0.06, 0.012, TERRA_SHADE);
  k.glowBox(0, ay, fz + 0.016, aw, ah, 0.006, hex(0x6a5a46), [17, 24, 1.4], WARM_GLOW);
  k.face(0, ay + ah, fz + 0.016, aw / 2, hex(0x6a5a46), 12);
  k.box(0, fh - 0.08, fz - 0.2, fw + 0.06, 0.08, 0.46, TERRA_SHADE);
  k.box(0, fh, fz - 0.15, fw * 0.6, 0.12, 0.2, TERRA);
  k.box(0, fh + 0.12, fz - 0.15, fw * 0.24, 0.12, 0.16, TERRA);
  // the marquee, and the name in bulbs along its top
  const mw = Math.min(1.7, W * 0.85);
  marquee(k, 0, 0.34, fz, mw, 0.24, 0.42, ENAMEL_RED);
  k.box(0, 0.6, fz + 0.36, mw * 0.6, 0.12, 0.04, ENAMEL_RED);
  frontText(k, 'CHICAGO', 0, 0.615, fz + 0.38, 0.09, BULB);
  bulbRow(k, [-mw * 0.3, 0.73, fz + 0.385], [mw * 0.3, 0.73, fz + 0.385], 10);
  // and the great sign: C-H-I-C-A-G-O down it in bulbs on red, a bulb border, a crown on top
  bladeName(k, 'CHICAGO', 0, 0.78, fz, 0.36, 0.17, ENAMEL_RED, BULB, hex(0xffd23a), { bulbs: true, crown: 'fan', thick: 0.07 });
};

// ---- Cloud Gate ------------------------------------------------------------------------------------

const cloudGate: Draw = (k, W, D) => {
  // the plaza's edge: planters with honey locusts, benches
  for (const [x, z] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) {
    const px = x * (W / 2 - 0.3), pz = z * (D / 2 - 0.3);
    k.box(px, 0, pz, 0.32, 0.06, 0.32, LIME);
    tree(k, px, 0.06, pz, 0.7, false);
  }
  for (const s of [-1, 1]) k.box(s * (W / 2 - 0.3), 0.04, 0, 0.08, 0.03, 0.5, hex(0x8a6a48));
  // the Bean: a mirror-steel bean, the sky in its top, the plaza in its sides, the omphalos under it dark
  const rx = Math.min(0.62, W * 0.22), ry = 0.3, rz = rx * 0.55, cy = 0.31, U = 16, V = 8;
  const P = (u: number, v: number): P3 => {
    const a = (u / U) * TAU, p = -Math.PI / 2 + (v / V) * Math.PI;
    return [Math.cos(p) * Math.cos(a) * rx, cy + Math.sin(p) * ry, Math.cos(p) * Math.sin(a) * rz];
  };
  for (let v = 1; v < V; v++) for (let u = 0; u < U; u++) {
    // reflections: the sky up top, the city round the middle, the ground below
    const t = v / V, col = t > 0.62 ? mix(STEEL_SKY, WHITE, (t - 0.62) * 0.8) : t > 0.38 ? STEEL_MID : STEEL_LOW;
    const c2 = (u % 3 === 0 && t > 0.38 && t <= 0.62) ? scale(col, 0.9) : col;
    k.quad(P(u, v), P(u + 1, v), P(u + 1, v + 1), P(u, v + 1), c2, [0, cy, 0]);
  }
  // the underside: the omphalos arch, lifted off the ground
  k.disc(0, 0.005, 0, rx * 0.5, hex(0x5a6066), 10, rz * 0.5);
  void LEAF;
};

export const CHICAGO_DRAW = {
  willisTower, hancockCenter, marinaCity, wrigleyBuilding, tribuneTower, chicagoTheatre, cloudGate,
} satisfies Partial<Record<ThemeKind, Draw>>;
