import { esc } from '../cargoHud';
import { CARGO } from '../cargoTypes';
import { speedText } from '../units';
import type { Agent } from '../traffic';
import { CARGO_OF, FACTIONS, OWNED_OUTRIGHT, RUNGS, buildingFactions, type FactionId } from './factions';
import { factionDoing } from './factionTraffic';
import { reputation } from './reputation';
import { barHtml, crestUrl } from './factionsTab';

/**
 * The inspector's word on the factions (docs/factions.html): a faction building's card says whose it is,
 * where the player stands with them and what they want at this door; a faction vehicle's card says whose
 * it is and what it is about. Both have a button to the Factions tab.
 */

/** The Faction block under a building's card, or '' for a building no faction has. */
export function factionBlockHtml(kind: string): string {
  const fs = buildingFactions(kind);
  if (!fs.length) return '';
  return fs.map((f) => {
    const d = FACTIONS[f], v = reputation.points(f), r = reputation.rung(f);
    const mine = new Set(CARGO_OF[f]);
    const here = CARGO.filter((c) => mine.has(c.id) && ((c.to as string[]).includes(kind) || (c.from as string[]).includes(kind)));
    const wants = (here.length ? here : CARGO.filter((c) => mine.has(c.id)).slice(0, 4)).map((c) => `${c.icon} ${esc(c.name)}`).join(' · ');
    const shut = r <= 1 ? '<p class="fac-shut">Their doors are shut to you: no loads in or out here.</p>' : '';
    return `<div class="insp-fac"><div class="fh"><img alt="" src="${crestUrl(f)}"><div><b>${esc(d.name)}</b><small>${esc(d.common)} · <span style="color:${RUNGS[r].colour}">${RUNGS[r].name}</span> ${Math.round(v).toLocaleString()}</small></div></div>`
      + barHtml(f, v, true)
      + `<p><b>${here.length ? 'Wanted here' : 'They want'}</b> ${wants}</p>${shut}`
      + `${OWNED_OUTRIGHT.has(kind) ? '<p class="fac-note">Theirs outright: not for sale.</p>' : ''}`
      + `<button type="button" data-fac="${f}">Factions · ${esc(d.short)}</button></div>`;
  }).join('');
}

/** A faction vehicle's card, or null for anything else. */
export function factionAgentCard(a: Agent): [string, string] | null {
  const f = a.faction as FactionId | undefined;
  if (!f) return null;
  const d = FACTIONS[f], r = reputation.rung(f), v = reputation.points(f);
  const head = `<span class="ic">${d.icon}</span><b>${esc(d.name)}</b><small>${esc(a.def.name)} · ${esc(d.common)}</small>`;
  const rows: [string, string][] = [
    ['Whose', `<img class="insp-crest" alt="" src="${crestUrl(f)}"> ${esc(d.name)}`],
    ['You', `<span style="color:${RUNGS[r].colour}">${RUNGS[r].name}</span> · ${Math.round(v).toLocaleString()}`],
    ['Doing', esc(factionDoing(a) ?? 'about their business')],
    ['Speed', speedText(Math.abs(a.state.v) * 12)],
  ];
  return [head, `<dl>${rows.map(([k, x]) => `<dt>${k}</dt><dd>${x}</dd>`).join('')}</dl><div class="insp-fac"><button type="button" data-fac="${f}">Factions · ${esc(d.short)}</button></div>`];
}
