import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, GLASS_LIGHT, METAL, TAU, WARM_GLOW, WHITE, WOOD, win, type Draw, type Kit, type P3 } from '../kit';
import { palm } from '../venues';
import { flag } from '../civic';

/**
 * The Shallows: pastel and thatch by turquoise water — a beach club, a marina, a golf course, the
 * boardwalk, resort villas, a tiki bar, and the pleasure pier with its wheel.
 */

const PASTEL = [0xf2a4b6, 0x98d8b4, 0xf0d878, 0x9cc4ec, 0xf4bc90];
const POOL = hex(0x4fc8e0), COPING = hex(0xf6f2e8), DECK = hex(0xc49a68), DECK2 = hex(0xb08858);
const THATCH = hex(0xc8a060), THATCH_D = hex(0xa8844a), FAIRWAY = hex(0x5fb044), ROUGH = hex(0x46913a), GREEN = hex(0x78cc52);
const BUNKER = hex(0xeedcaa), LAKE = hex(0x3fa0c8), RED = hex(0xe2412f), NAVY = hex(0x2f4d7a);
const BULBS = [0xffe8a0, 0xff9ac0, 0x9ae0ff, 0xb8ff9a];
const EVE: Sched = [17.5, 24.5, 2.4];
const pastel = (i: number): RGB => hex(PASTEL[((i % PASTEL.length) + PASTEL.length) % PASTEL.length]);

/** A striped parasol on its pole. */
function parasol(k: Kit, x: number, z: number, col: RGB, h = 0.34, R = 0.18): void {
  k.cyl(x, 0, z, 0.008, h, WHITE, 4);
  for (let i = 0; i < 8; i++) {
    const a0 = (i / 8) * TAU, a1 = ((i + 1) / 8) * TAU;
    k.tri([x, h + 0.06, z], [x + Math.cos(a0) * R, h - 0.02, z + Math.sin(a0) * R], [x + Math.cos(a1) * R, h - 0.02, z + Math.sin(a1) * R], i % 2 ? WHITE : col, [x, h - 0.2, z]);
  }
}

/** A sun lounger with its back raised, head toward -z. */
function lounger(k: Kit, x: number, z: number, col = WHITE): void {
  k.box(x, 0.02, z + 0.04, 0.1, 0.025, 0.18, col);
  k.bar([x - 0.04, 0.045, z - 0.05], [x - 0.04, 0.11, z - 0.12], 0.012, col);
  k.bar([x + 0.04, 0.045, z - 0.05], [x + 0.04, 0.11, z - 0.12], 0.012, col);
  k.bar([x - 0.035, 0.08, z - 0.09], [x + 0.035, 0.08, z - 0.09], 0.03, col);
}

/** A rectangular pool with its coping. */
function pool(k: Kit, x: number, z: number, w: number, d: number): void {
  k.box(x, 0, z, w + 0.1, 0.04, d + 0.1, COPING);
  k.box(x, 0, z, w, 0.045, d, POOL);
}

/** A small boat afloat, bow toward +z (or +x): a pointed hull, a cabin, and a mast if she sails. */
function boat(k: Kit, x: number, y: number, z: number, L: number, w: number, col: RGB, alongX: boolean, sail: boolean): void {
  const pt = (a: number, up: number, s: number): P3 => alongX ? [x + a, y + up, z + s] : [x + s, y + up, z + a];
  const hh = 0.08, sh = L * 0.15, I: P3 = pt(0, hh / 2, 0);
  const top: [number, number][] = [[-L / 2, -w / 2], [sh, -w / 2], [L / 2, 0], [sh, w / 2], [-L / 2, w / 2]];
  for (let i = 0; i < 5; i++) {
    const [a0, s0] = top[i], [a1, s1] = top[(i + 1) % 5];
    k.quad(pt(a0 * 0.92, 0, s0 * 0.7), pt(a1 * 0.92, 0, s1 * 0.7), pt(a1, hh, s1), pt(a0, hh, s0), i === 4 ? scale(col, 0.85) : col, I);
  }
  k.tri(pt(-L / 2, hh, -w / 2), pt(sh, hh, -w / 2), pt(L / 2, hh, 0), WHITE, pt(0, 0, 0));
  k.tri(pt(-L / 2, hh, -w / 2), pt(L / 2, hh, 0), pt(-L / 2, hh, w / 2), WHITE, pt(0, 0, 0));
  k.tri(pt(sh, hh, w / 2), pt(-L / 2, hh, w / 2), pt(L / 2, hh, 0), WHITE, pt(0, 0, 0));
  const [cx, , cz] = pt(-L * 0.08, 0, 0);
  if (alongX) k.box(cx, y + hh, cz, L * 0.35, 0.06, w * 0.6, WHITE, scale(WHITE, 0.95));
  else k.box(cx, y + hh, cz, w * 0.6, 0.06, L * 0.35, WHITE, scale(WHITE, 0.95));
  if (sail) {
    k.bar(pt(L * 0.12, hh, 0), pt(L * 0.12, hh + L * 1.1, 0), 0.006, METAL);
    k.tri(pt(L * 0.1, hh + 0.08, 0.004), pt(L * 0.1, hh + L * 1.0, 0.004), pt(-L * 0.35, hh + 0.08, 0.004), hex(0xf8f6f0), pt(0, hh + 0.2, -0.3));
    k.tri(pt(L * 0.1, hh + 0.08, -0.004), pt(L * 0.1, hh + L * 1.0, -0.004), pt(-L * 0.35, hh + 0.08, -0.004), hex(0xf8f6f0), pt(0, hh + 0.2, 0.3));
  }
}

/** A thatched roof with a second, shaggier layer under its eaves. */
function thatch(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number): void {
  k.hip(x, y, z, w, h, d, THATCH);
  k.hip(x, y, z, w, -0.03, d, THATCH_D);
}

/** A tiki torch that burns after dark. */
function tikiTorch(k: Kit, x: number, z: number, h = 0.36): void {
  k.box(x, 0, z, 0.02, h, 0.02, hex(0x6a4a2a));
  k.cyl(x, h, z, 0.022, 0.04, THATCH_D, 5);
  k.glowBox(x, h + 0.04, z, 0.026, 0.045, 0.026, hex(0xf2b04a), [17.5, 30, 2.8], hex(0xff9a40));
}

/** Bulbs hanging in a sagging string from a to b. */
function festoon(k: Kit, a: P3, b: P3, n: number, sag: number, s: Sched = EVE): void {
  for (let i = 1; i < n; i++) {
    const t = i / n, c = hex(BULBS[i % BULBS.length]);
    k.glowBox(a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t - sag * 4 * t * (1 - t), a[2] + (b[2] - a[2]) * t, 0.03, 0.03, 0.03, WHITE, s, c);
  }
}

// ---- 1. beach club -----------------------------------------------------------------------------

const beachClub: Draw = (k, W, D, b, r) => {
  // the deck and the pool
  k.box(0.45, 0, -0.2, 1.95, 0.025, 1.45, DECK);
  pool(k, 0.5, -0.3, 1.2, 0.6);
  for (let i = 0; i < 3; i++) lounger(k, 0.05 + i * 0.4, 0.3, i % 2 ? pastel(0) : WHITE);
  // the bar: thatch on posts over a counter
  const bx = -W / 2 + 0.55, bz = -D / 2 + 0.5;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(bx + sx * 0.36, 0, bz + sz * 0.3, 0.035, 0.42, 0.035, WOOD);
  k.box(bx, 0, bz - 0.26, 0.72, 0.36, 0.06, DECK2);
  k.box(bx, 0, bz + 0.12, 0.66, 0.16, 0.12, hex(0x8a6a44), hex(0xe8e0d0));
  thatch(k, bx, 0.42, bz, 0.98, 0.3, 0.86);
  for (let i = 0; i < 5; i++) k.glowBox(bx - 0.24 + i * 0.12, 0.2, bz - 0.22, 0.03, 0.08, 0.03, hex([0x3f9b4a, 0xf2a93b, 0x2f7fb5, 0xe2412f, 0xf4f2ec][i]), [17, 24, 1.6], WARM_GLOW);
  for (let i = 0; i < 3; i++) k.cyl(bx - 0.2 + i * 0.2, 0, bz + 0.3, 0.03, 0.12, pastel(i + 1), 6);
  k.glowBox(bx, 0.37, bz + 0.31, 0.4, 0.07, 0.01, pastel(3), [17, 24, 2.2], hex(0xff6fb0));
  win(k, b, r, bx, 0.18, bz - 0.23, 0.2, 0.08, 1, GLASS_LIGHT);
  // loungers and parasols on the sand in front
  for (let i = 0; i < 4; i++) {
    const x = -W / 2 + 0.3 + i * 0.36, z = D / 2 - 0.3;
    lounger(k, x, z, WHITE);
    if (i % 2 === 0) parasol(k, x + 0.18, z - 0.05, pastel(i));
  }
  palm(k, W / 2 - 0.2, D / 2 - 0.25, 0.7);
  palm(k, -W / 2 + 0.15, 0.25, 0.6);
  festoon(k, [bx + 0.45, 0.4, bz + 0.35], [W / 2 - 0.2, 0.55, D / 2 - 0.25], 8, 0.08);
};

// ---- 2. marina ---------------------------------------------------------------------------------

/** The pontoons' height: a hand's width above the water, a step below the quay. */
const PY = -0.35;

const marina: Draw = (k, W, D, b, r) => {
  // the quay along the front, and its kerb
  const qz = D / 2 - 0.7;
  k.box(0, 0, qz, W, 0.05, 0.05, hex(0xd8d4c8));
  for (let i = 0; i < 5; i++) k.cyl(-W / 2 + 0.3 + i * 0.85, 0, qz + 0.1, 0.03, 0.06, DARK, 6);
  // the harbour master's hut
  const hx = W / 2 - 0.5, hz = D / 2 - 0.35;
  k.box(hx, 0, hz, 0.56, 0.32, 0.4, WHITE);
  k.hip(hx, 0.32, hz, 0.66, 0.16, 0.5, NAVY);
  win(k, b, r, hx, 0.14, hz - 0.2, 0.36, 0.12, 3, GLASS_LIGHT);
  win(k, b, r, hx - 0.28, 0.14, hz, 0.2, 0.12, 2, GLASS_LIGHT);
  k.box(hx + 0.1, 0, hz + 0.204, 0.1, 0.22, 0.004, NAVY);
  flag(k, hx + 0.36, 0, hz + 0.12, 0.7, RED);
  k.glowBox(hx - 0.3, 0.26, hz + 0.21, 0.04, 0.04, 0.04, WHITE, [17, 30, 2], WARM_GLOW);
  // the gangway down, then the spine and its fingers
  const gx = -0.5, sz = -0.15;
  k.bar([gx, 0.02, qz - 0.03], [gx, PY + 0.05, qz - 0.55], 0.05, hex(0xa8a8a0));
  k.box(gx, PY, (qz - 0.55 + sz) / 2, 0.22, 0.05, qz - 0.55 - sz, DECK);
  k.box(0, PY, sz, W - 0.2, 0.05, 0.22, DECK);
  const fingers = Math.max(3, Math.round((W - 0.4) / 0.8));
  for (let i = 0; i <= fingers; i++) {
    const x = -W / 2 + 0.2 + ((W - 0.4) * i) / fingers;
    k.box(x, PY, sz - 0.62, 0.12, 0.05, 1.05, DECK2);
    for (const pz of [sz - 1.1, sz - 0.4]) k.cyl(x, PY - 0.7, pz, 0.03, 0.85, hex(0x6a6058), 5);
    if (i % 2 === 0) k.glowBox(x, PY + 0.05, sz - 1.12, 0.03, 0.12, 0.03, WHITE, [17, 30, 1.8], WARM_GLOW);
    if (i < fingers) {
      const bx = x + (W - 0.4) / fingers / 2, c = pastel(Math.floor(r() * 5));
      if (r() < 0.85) boat(k, bx, PY - 0.08, sz - 0.62, 0.8, 0.26, r() < 0.5 ? WHITE : c, false, r() < 0.5);
    }
  }
  // boats along the outside of the spine, a lifebuoy and a fuel pump
  for (let i = 0; i < 2; i++) boat(k, -W / 2 + 1.0 + i * 1.6, PY - 0.08, sz + 0.3, 0.9, 0.28, i ? hex(0x2f7fb5) : WHITE, true, i === 0);
  k.hoop(W / 2 - 0.2, PY + 0.15, sz + 0.115, 0.05, 0.012, RED, 8);
  k.box(W / 2 - 0.2, PY, sz + 0.1, 0.02, 0.15, 0.02, WHITE);
  k.box(-W / 2 + 0.3, PY + 0.05, sz, 0.08, 0.16, 0.06, RED);
};

// ---- 3. golf course ----------------------------------------------------------------------------

const golfCourse: Draw = (k, W, D, b, r) => {
  // mown stripes over the whole lot
  const n = Math.round(D / 0.5), I: P3 = [0, -1, 0];
  for (let i = 0; i < n; i++) {
    const z0 = -D / 2 + (D * i) / n, z1 = -D / 2 + (D * (i + 1)) / n;
    k.quad([-W / 2, 0.004, z0], [W / 2, 0.004, z0], [W / 2, 0.004, z1], [-W / 2, 0.004, z1], i % 2 ? ROUGH : scale(ROUGH, 1.06), I);
  }
  // the lake
  k.disc(0.1 * W / 2, 0.006, -0.05 * D / 2, 0.55, LAKE, 14, 0.4);
  // four holes: a tee, a fairway of overlapping discs, bunkers, the green and its flag
  const holes: [number, number, number, number][] = [[-0.55, 0.45, -0.72, -0.6], [-0.35, -0.82, 0.38, -0.62], [0.62, -0.3, 0.72, 0.62], [0.32, 0.8, -0.1, 0.18]];
  holes.forEach(([tx, tz, gx, gz], h) => {
    const ax = (tx * W) / 2, az = (tz * D) / 2, ex = (gx * W) / 2, ez = (gz * D) / 2;
    const len = Math.hypot(ex - ax, ez - az), m = Math.max(2, Math.ceil(len / 0.4));
    for (let i = 0; i <= m; i++) k.disc(ax + ((ex - ax) * i) / m, 0.008, az + ((ez - az) * i) / m, 0.3, FAIRWAY, 10);
    k.box(ax, 0, az, 0.26, 0.03, 0.26, GREEN);
    k.disc(ex, 0.012, ez, 0.36, GREEN, 12);
    const ux = (ex - ax) / len, uz = (ez - az) / len;
    k.disc(ex - ux * 0.3 + uz * 0.36, 0.013, ez - uz * 0.3 - ux * 0.36, 0.14, BUNKER, 9, 0.1);
    if (h % 2 === 0) k.disc(ex + uz * -0.4, 0.013, ez + ux * 0.4, 0.12, BUNKER, 9);
    k.disc(ex, 0.018, ez, 0.03, DARK, 6);
    k.cyl(ex, 0, ez, 0.007, 0.4, WHITE, 4);
    k.box(ex + 0.06, 0.3, ez, 0.12, 0.08, 0.006, RED);
  });
  // the clubhouse by the gate, carts and palms
  const cx = -W / 2 + 0.9, cz = D / 2 - 0.55;
  k.box(cx, 0, cz, 0.9, 0.3, 0.5, WHITE);
  k.hip(cx, 0.3, cz, 1.0, 0.2, 0.6, hex(0x3f7a5a));
  k.box(cx, 0, cz + 0.32, 0.9, 0.02, 0.14, DECK);
  for (const sx of [-1, 0, 1]) k.box(cx + sx * 0.42, 0, cz + 0.38, 0.025, 0.28, 0.025, WHITE);
  for (let i = 0; i < 3; i++) win(k, b, r, cx - 0.3 + i * 0.3, 0.1, cz + 0.25, 0.16, 0.12, 1, GLASS_LIGHT);
  for (let i = 0; i < 2; i++) {
    const x = cx + 0.8 + i * 0.26, z = cz + 0.1;
    k.box(x, 0.02, z, 0.13, 0.08, 0.2, WHITE);
    k.box(x, 0.2, z, 0.14, 0.015, 0.16, WHITE);
    for (const sz of [-1, 1]) k.box(x + 0.05, 0.1, z + sz * 0.06, 0.01, 0.1, 0.01, METAL);
  }
  for (let i = 0; i < 6; i++) palm(k, W / 2 - 0.25, -D / 2 + 0.4 + (i * (D - 0.8)) / 5, 0.6 + r() * 0.2);
};

// ---- 4. boardwalk ------------------------------------------------------------------------------

const boardwalk: Draw = (k, W, D, _b, r) => {
  // the planks, a hair above the lot
  const n = Math.round(W / 0.12), I: P3 = [0, -1, 0];
  k.box(0, -0.12, 0, W, 0.16, D, DECK2);
  for (let i = 0; i < n; i++) {
    const x0 = -W / 2 + (W * i) / n, x1 = -W / 2 + (W * (i + 1)) / n;
    k.quad([x0, 0.042, -D / 2], [x1, 0.042, -D / 2], [x1, 0.042, D / 2], [x0, 0.042, D / 2], i % 3 ? DECK : scale(DECK, 0.92), I);
  }
  // stilts down to the sand, braced
  const bays = Math.round(W);
  for (let i = 0; i <= bays; i++) {
    const x = -W / 2 + 0.06 + ((W - 0.12) * i) / bays;
    for (const z of [-D / 2 + 0.06, D / 2 - 0.06]) k.box(x, -1.0, z, 0.06, 1.0, 0.06, hex(0x7a5a3a));
    if (i < bays) k.bar([x, -0.9, -D / 2 + 0.04], [x + (W - 0.12) / bays, -0.15, -D / 2 + 0.04], 0.015, hex(0x7a5a3a));
  }
  // the rail along the seaward side, lamps and benches
  const rz = -D / 2 + 0.04, posts = Math.round(W / 0.5);
  for (let i = 0; i <= posts; i++) k.box(-W / 2 + 0.03 + ((W - 0.06) * i) / posts, 0.04, rz, 0.03, 0.22, 0.03, WHITE);
  k.box(0, 0.25, rz, W, 0.03, 0.05, WHITE);
  k.box(0, 0.15, rz, W, 0.015, 0.02, WHITE);
  const lamps = Math.max(2, Math.round(W / 1.6));
  for (let i = 0; i < lamps; i++) {
    const x = -W / 2 + (W * (i + 0.5)) / lamps;
    k.cyl(x, 0.04, rz + 0.05, 0.015, 0.55, NAVY, 5);
    k.box(x, 0.58, rz + 0.05, 0.1, 0.02, 0.02, NAVY);
    k.glowBox(x, 0.5, rz + 0.05, 0.06, 0.08, 0.06, hex(0xfff4d8), [17, 30, 2.4], WARM_GLOW);
    if (i < lamps - 1) {
      const bx = x + W / lamps / 2;
      k.box(bx, 0.04, rz + 0.14, 0.34, 0.07, 0.1, pastel(Math.floor(r() * 5)));
      k.box(bx, 0.11, rz + 0.1, 0.34, 0.08, 0.02, pastel(Math.floor(r() * 5)));
    }
  }
};

// ---- 5. resort villas --------------------------------------------------------------------------

/** Where the villas stand round the pool: centres and sizes (regionShapesA.ts keeps a copy). */
const VILLAS: [number, number, number, number][] = [[-0.85, -0.85, 0.8, 0.62], [0.85, -0.85, 0.8, 0.62], [-0.95, 0.72, 0.62, 0.7], [0.95, 0.72, 0.62, 0.7]];

const resortVillas: Draw = (k, _W, _D, b, r) => {
  // the pool terrace in the middle
  k.box(0, 0, -0.05, 1.1, 0.02, 1.9, hex(0xf2ead8));
  pool(k, 0, -0.1, 0.5, 1.1);
  for (let i = 0; i < 3; i++) lounger(k, 0.42, -0.45 + i * 0.35, WHITE);
  parasol(k, -0.42, 0.25, pastel(0));
  parasol(k, -0.42, -0.5, pastel(3));
  VILLAS.forEach(([x, z, w, d], i) => {
    const wall = pastel(i + Math.floor(r() * 5)), two = (i + b.seed) % 3 === 0, h = two ? 0.5 : 0.28;
    k.box(x, 0, z, w, h, d, wall);
    // white trim, and either a hipped roof or a flat one with a parapet and a pergola
    k.box(x, h - 0.03, z, w + 0.02, 0.03, d + 0.02, WHITE);
    if (i % 2) k.hip(x, h, z, w + 0.1, 0.18, d + 0.1, hex(0x7ab8d0));
    else {
      k.box(x, h, z, w, 0.05, d, WHITE);
      for (let j = 0; j < 4; j++) k.box(x - w / 4 + (j * w) / 6, h + 0.14, z, 0.02, 0.02, d * 0.5, WOOD);
      for (const sx of [-1, 1]) k.box(x + sx * w * 0.25, h + 0.05, z + d * 0.22, 0.02, 0.1, 0.02, WOOD);
    }
    // windows and a door on the side that faces the pool, a balcony when there are two storeys
    const face = x < 0 ? 0 : 2, fx = x + (x < 0 ? w / 2 : -w / 2);
    for (let f = 0; f < (two ? 2 : 1); f++) {
      win(k, b, r, fx, 0.08 + f * 0.24, z - d * 0.2, d * 0.28, 0.13, face, GLASS_LIGHT);
      win(k, b, r, fx, 0.08 + f * 0.24, z + d * 0.22, d * 0.2, 0.13, face, GLASS_LIGHT);
    }
    if (two) k.box(fx + (x < 0 ? 0.06 : -0.06), 0.24, z, 0.12, 0.02, d * 0.7, WHITE);
    win(k, b, r, x, 0.08, z + (z < 0 ? d / 2 : -d / 2), w * 0.5, 0.12, z < 0 ? 1 : 3, GLASS_LIGHT);
    k.box(x - w * 0.3, 0, z + d / 2 + 0.003, 0.1, 0.2, 0.006, WHITE);
  });
  palm(k, 0, 1.2, 0.65);
  palm(k, -1.3, -0.05, 0.55);
  palm(k, 1.3, -0.1, 0.6);
};

// ---- 6. tiki bar -------------------------------------------------------------------------------

const tikiBar: Draw = (k) => {
  const z = -0.08;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.26, 0, z + sz * 0.2, 0.035, 0.36, 0.035, hex(0x6a4a2a));
  k.box(0, 0, z - 0.2, 0.52, 0.3, 0.04, THATCH_D);
  k.box(0, 0, z + 0.12, 0.5, 0.15, 0.1, hex(0x7a5a3a), hex(0xd8c090));
  for (let i = 0; i < 4; i++) k.box(-0.18 + i * 0.12, 0.155, z + 0.12, 0.02, 0.004, 0.08, i % 2 ? hex(0xe2412f) : hex(0xf2a93b));
  thatch(k, 0, 0.36, z, 0.78, 0.3, 0.68);
  k.glowBox(0, 0.16, z - 0.17, 0.36, 0.1, 0.02, hex(0x8a6a44), [17, 25, 1.8], WARM_GLOW);
  for (let i = 0; i < 3; i++) {
    const x = -0.18 + i * 0.18;
    k.cyl(x, 0, z + 0.27, 0.035, 0.1, hex(0x6a4a2a), 6);
  }
  // the carved pole and the torches
  k.box(0.38, 0, 0.32, 0.08, 0.34, 0.08, hex(0x8a6a44));
  k.box(0.38, 0.2, 0.364, 0.05, 0.03, 0.004, DARK);
  k.box(0.38, 0.1, 0.364, 0.05, 0.02, 0.004, RED);
  tikiTorch(k, -0.4, 0.38);
  tikiTorch(k, 0.4, -0.38);
  tikiTorch(k, -0.4, -0.38, 0.3);
};

// ---- 7. pleasure pier (wonder) -----------------------------------------------------------------

const pleasurePier: Draw = (k, W, D, _b, r) => {
  const E = W / 2 - 0.06, L = -D / 2, S = D / 2, IP: P3 = [0, -1, 0];
  // the deck: planks across its width, a fascia and piles under the seaward half
  const n = Math.round(D / 0.25);
  for (let i = 0; i < n; i++) {
    const z0 = L + (D * i) / n, z1 = L + (D * (i + 1)) / n;
    k.quad([-E - 0.06, 0.02, z0], [E + 0.06, 0.02, z0], [E + 0.06, 0.02, z1], [-E - 0.06, 0.02, z1], i % 4 === 0 ? DECK2 : DECK, IP);
  }
  k.box(0, -0.16, S / 2, W, 0.17, S, hex(0x8a6a48));
  for (let z = 0.6; z < S; z += 1.3) {
    for (const x of [-E + 0.05, -0.8, 0.8, E - 0.05]) k.cyl(x, -1.5, z, 0.07, 1.36, hex(0x5a4a3a), 6);
    k.bar([-E + 0.05, -1.3, z], [E - 0.05, -0.3, z], 0.03, hex(0x5a4a3a));
    if (z + 1.3 < S) for (const x of [-E + 0.05, E - 0.05]) k.bar([x, -1.3, z], [x, -0.3, z + 1.3], 0.025, hex(0x5a4a3a));
  }
  // rails both sides, lamp posts, and strings of bulbs swung between them
  const posts = Math.round(D / 0.6);
  for (const sx of [-1, 1]) {
    for (let i = 0; i <= posts; i++) k.box(sx * E, 0.02, L + 0.4 + ((D - 0.8) * i) / posts, 0.04, 0.26, 0.04, WHITE);
    k.box(sx * E, 0.28, 0, 0.06, 0.035, D - 0.8, WHITE);
    k.box(sx * E, 0.15, 0, 0.02, 0.02, D - 0.8, WHITE);
    const lamps = 10;
    for (let i = 0; i <= lamps; i++) {
      const z = L + 0.8 + ((D - 1.6) * i) / lamps;
      k.cyl(sx * E, 0.02, z, 0.025, 0.85, hex(0x2f5a4a), 6);
      k.glowBox(sx * E, 0.87, z, 0.1, 0.1, 0.1, hex(0xfff4d8), [17, 30, 2.6], WARM_GLOW);
      if (i < lamps) festoon(k, [sx * E, 0.84, z], [sx * E, 0.84, z + (D - 1.6) / lamps], 7, 0.16);
    }
  }
  // the entrance arch: two turrets with domes and a lit sign across
  const az = L + 0.35;
  for (const sx of [-1, 1]) {
    k.cyl(sx * (E - 0.1), 0, az, 0.26, 1.25, WHITE, 8);
    k.cyl(sx * (E - 0.1), 1.25, az, 0.3, 0.06, hex(0x3f8a8a), 8);
    k.dome(sx * (E - 0.1), 1.31, az, 0.24, hex(0x3f8a8a), 8, 3);
    k.cyl(sx * (E - 0.1), 1.55, az, 0.015, 0.2, hex(0xd9a441), 4);
    k.box(sx * (E - 0.1), 0.2, az + 0.26, 0.2, 0.36, 0.01, hex(0x3f8a8a));
  }
  k.box(0, 1.15, az, 2 * E - 0.5, 0.36, 0.08, hex(0x2f4d7a));
  k.glowBox(0, 1.22, az - 0.05, 2 * E - 0.8, 0.22, 0.02, hex(0xf6ecac), [16.5, 30, 2.4], hex(0xffe08a));
  for (let i = 0; i < 9; i++) {
    const a0 = (Math.PI * i) / 9, a1 = (Math.PI * (i + 1)) / 9, ra = E - 0.25;
    k.bar([Math.cos(a0) * ra, 1.5 + Math.sin(a0) * 0.5, az], [Math.cos(a1) * ra, 1.5 + Math.sin(a1) * 0.5, az], 0.025, WHITE);
  }
  for (let i = 0; i < 9; i++) {
    const a = (Math.PI * (i + 0.5)) / 9;
    k.glowBox(Math.cos(a) * (E - 0.25), 1.5 + Math.sin(a) * 0.5, az, 0.05, 0.05, 0.05, WHITE, EVE, hex(BULBS[i % 4]));
  }
  // kiosks along the landward half
  for (let i = 0; i < 3; i++) {
    const x = -E + 0.35, z = L + 2.4 + i * 2.2, c = pastel(i);
    k.box(x, 0.02, z, 0.4, 0.32, 0.4, c);
    k.gable(x, 0.34, z, 0.48, 0.12, 0.48, i % 2 ? WHITE : RED, c, true);
    k.glowBox(x + 0.201, 0.12, z, 0.01, 0.14, 0.28, GLASS_LIGHT, [16.5, 23.5, 1.8], WARM_GLOW);
  }
  // the ferris wheel, turning in the plane of the pier
  const wx = 1.2, wz = -1.2, R = 1.9, hub = R + 0.3;
  k.box(wx, 0.02, wz, 0.9, 0.08, 2.0, hex(0xd8d4c8));
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([wx + sx * 0.2, 0.1, wz + sz * 0.9], [wx + sx * 0.2, hub, wz], 0.035, WHITE);
  k.box(wx, 0.1, wz + 0.8, 0.3, 0.24, 0.26, RED);
  k.spin(wx, hub, wz, 'x', 0.18, (s) => {
    for (const sx of [-0.12, 0.12]) s.hoop(sx, 0, 0, R, 0.02, WHITE, 18, 'zy');
    const cols = [0xe2412f, 0xf2c14e, 0x2f7fb5, 0x3f9b4a, 0xf4c6d0, 0x4fc8e0].map(hex);
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU, cz = Math.cos(a) * R, cy = Math.sin(a) * R;
      s.bar([0, 0, 0], [0, cy, cz], 0.01, WHITE);
      s.box(0, cy - 0.14, cz, 0.16, 0.12, 0.12, cols[i % cols.length]);
      s.glowBox(0.14, cy, cz, 0.03, 0.03, 0.03, WHITE, EVE, hex(BULBS[i % 4]));
      s.glowBox(-0.14, cy, cz, 0.03, 0.03, 0.03, WHITE, EVE, hex(BULBS[(i + 2) % 4]));
    }
    s.cyl(0, -0.08, 0, 0.1, 0.16, METAL, 8);
  });
  // the helter-skelter, striped, its slide winding down
  const hx = -1.3, hz = 4.6, hh = 1.9;
  for (let i = 0; i < 6; i++) k.cyl(hx, 0.02 + (i * hh) / 6, hz, 0.28 - i * 0.012, hh / 6, i % 2 ? WHITE : RED, 10);
  k.cone(hx, hh + 0.02, hz, 0.36, 0.4, hex(0x2f7fb5), 10);
  k.cyl(hx, hh + 0.42, hz, 0.01, 0.18, METAL, 4);
  k.box(hx + 0.07, hh + 0.52, hz, 0.14, 0.08, 0.006, hex(0xf2c14e));
  let prev: P3 = [hx + 0.48, hh - 0.05, hz];
  for (let i = 1; i <= 26; i++) {
    const a = (i / 26) * TAU * 3, y = (hh - 0.05) * (1 - i / 26) + 0.06;
    const p: P3 = [hx + Math.cos(a) * 0.48, y, hz + Math.sin(a) * 0.48];
    k.bar(prev, p, 0.05, hex(0xf2c14e));
    prev = p;
  }
  // the pavilion at the far end: a domed hall with turrets and lit arched windows
  const pz = S - 1.95, pw = 2 * E - 0.1, pd = 3.3;
  k.box(0, 0.02, pz, pw, 0.72, pd, WHITE, hex(0xe8e4dc));
  k.box(0, 0.74, pz, pw + 0.08, 0.06, pd + 0.08, hex(0x3f8a8a));
  k.box(0, 0.8, pz, pw - 0.6, 0.35, pd - 0.8, pastel(2));
  k.cyl(0, 1.15, pz, 0.8, 0.12, WHITE, 14);
  k.dome(0, 1.27, pz, 0.8, hex(0x3f8a8a), 14, 5);
  k.cone(0, 2.0, pz, 0.12, 0.45, hex(0xd9a441), 8);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * (pw / 2 - 0.05), z = pz + sz * (pd / 2 - 0.05);
    k.cyl(x, 0.02, z, 0.18, 1.1, WHITE, 8);
    k.dome(x, 1.12, z, 0.18, hex(0x3f8a8a), 8, 3);
    k.cone(x, 1.28, z, 0.04, 0.2, hex(0xd9a441), 5);
  }
  const lit: Sched = [16.5, 24.5, 2.2];
  for (let i = 0; i < 6; i++) {
    const x = -pw / 2 + 0.45 + (i * (pw - 0.9)) / 5;
    if (Math.abs(x) > 0.3) k.glowBox(x, 0.16, pz - pd / 2 - 0.005, 0.26, 0.42, 0.01, GLASS_LIGHT, lit, WARM_GLOW);
    k.glowBox(x, 0.16, pz + pd / 2 + 0.005, 0.26, 0.42, 0.01, GLASS_LIGHT, lit, WARM_GLOW);
    k.face(x, 0.58, pz - pd / 2 - 0.006, 0.13, hex(0x3f8a8a), 6);
  }
  for (const sx of [-1, 1]) for (let i = 0; i < 5; i++) k.glowBox(sx * (pw / 2 + 0.005), 0.16, pz - pd / 2 + 0.5 + (i * (pd - 1)) / 4, 0.01, 0.42, 0.26, GLASS_LIGHT, lit, WARM_GLOW);
  k.box(0, 0.02, pz - pd / 2 - 0.02, 0.5, 0.5, 0.04, hex(0x2f4d7a));
  k.glowBox(0, 0.9, pz - pd / 2 + 0.38, 1.4, 0.2, 0.02, pastel(0), [16.5, 30, 2.4], hex(0xff8ac0));
  festoon(k, [-pw / 2, 0.8, pz - pd / 2], [0, 1.3, pz - 0.8], 8, 0.05);
  festoon(k, [pw / 2, 0.8, pz - pd / 2], [0, 1.3, pz - 0.8], 8, 0.05);
  // benches facing the sea, a few gulls on the rail
  for (let i = 0; i < 4; i++) {
    const z = L + 1.4 + i * 3.1;
    k.box(E - 0.2, 0.02, z, 0.12, 0.08, 0.36, pastel(i + 1));
    k.box(E - 0.13, 0.1, z, 0.02, 0.1, 0.36, pastel(i + 1));
  }
  for (let i = 0; i < 4; i++) k.box(-E, 0.31, L + 8 + i * 1.7 + r() * 0.5, 0.03, 0.04, 0.07, WHITE);
};

