/**
 * The right-hand pane of the HQ window's Fleet tab (docs/hqwindow.html, "The pane"): whatever is picked on
 * the depot board, spelled out with every button it has. A vehicle shows four sections (Vehicle with the
 * inspector of its parts, Crew, Orders, Actions); a driver on the bench or in a seat shows who they are
 * and where they can go; the Hire chip shows today's candidates. Moved here from the old G menu's garage
 * and drivers tabs, with the same functions behind every button, so the board's drags and these buttons
 * always agree (npm run hqwin checks it).
 */
import { FACTIONS, UNLOCKS } from './factions/factions';
import { unlocks } from './factions/unlocks';
import { canLoad, type CargoClass } from './vehicles';
import { esc, money } from './cargoHud';
import type { Wallet } from './economy';
import { CARGO, CLASS_LABEL, URGENCY, type Urgency } from './cargoTypes';
import { defOf, type Fleet, type Unit } from './fleet';
import { stacked } from './charts';
import {
  CUT_MAX, CUT_MIN, MODE_LABEL, feeOf, licenceFor, mayDrive, modeOf, rankOf, type Driver,
} from './drivers';
import { crewCard } from './crewCard';
import { CROSS_LABEL, LADDER, PACK_LABEL, PRESET_LABEL, RANGE_LABEL, packOf, preset, presetOf, type Cross, type Order, type Pack, type PresetId, type Range } from './orders';
import { applyParts, colourName, effectLine, fitted, headline, topperOf, owned, partsLine, slotName, slotsFor, tierName, tierPrice, type HornTune, type SlotId } from './parts';
import { rewards, TREATS } from './passportRewards';
import { TOPPER_BY_ID, toppers } from './toppers';

/** The Passport's paintjobs (game/passportRewards.ts), for any model once their page is sealed. */
const TREAT_JOBS: { id: string; name: string; icon: string; seal: 'biome' | 'size' }[] = [
  { id: 'job:expedition', name: 'Expedition', icon: '🧭', seal: 'biome' },
  { id: 'job:skyline', name: 'Skyline', icon: '🏙️', seal: 'size' },
];
/** The Passport's toggles in the workshop: what each is, the seal that gives it, and the parts field it sets. */
const TREAT_TOGGLES: { key: string; label: string; icon: string; seal: 'landform' | 'sig' | 'event'; set: { l?: 1; h?: HornTune } }[] = [
  { key: 'l', label: 'Lantern', icon: '🔦', seal: 'landform', set: { l: 1 } },
  { key: 'h:fanfare', label: 'Fanfare horn', icon: '🎺', seal: 'sig', set: { h: 'fanfare' } },
  { key: 'h:confetti', label: 'Confetti horn', icon: '🎉', seal: 'event', set: { h: 'confetti' } },
];
import { wayTo, type Outlets } from './outlets';
import { hero } from '../render/heroStage';

/** What the pane asks of the game: the old G menu's host, less the buying. */
interface UnitPaneHost {
  where(): { x: number; z: number };
  ride(u: Unit): string | null;
  day(): number;
  watchable(u: Unit): string | null;
  watch(u: Unit): void;
  towOver(u: Unit): number | null;
  bringOver(u: Unit): string | null;
  deploy(u: Unit): string | null;
  swapIn(u: Unit): string | null;
  unlocked?(id: string): boolean;
  /** The cheats menu's full roster is open: every licence at every rank, always there. */
  roster(): boolean;
  /** A line under the board. */
  say(text: string): void;
  /** Close the HQ window (riding, watching). */
  close(): void;
  /** Open the Tech tab at a model. */
  tech(id: string): void;
  /** Something changed: redraw the board. */
  changed(): void;
  /** Work or Follow for one vehicle (game/formation.ts), and why it can't follow what the player drives now. */
  setMode?(u: Unit, mode: 'work' | 'follow'): void;
  followWhy?(u: Unit): string | null;
}

export type Pick = { k: 'unit'; uid: number } | { k: 'driver'; id: number } | { k: 'hire' } | null;

/** A small film camera: the one icon that means "show me it". */
const CAMERA_SVG = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M3 7.5A1.5 1.5 0 0 1 4.5 6h9A1.5 1.5 0 0 1 15 7.5v9a1.5 1.5 0 0 1-1.5 1.5h-9A1.5 1.5 0 0 1 3 16.5z" fill="currentColor"/><path d="M16 10.2 21 7v10l-5-3.2z" fill="currentColor"/></svg>';

export class UnitPane {
  readonly el = document.createElement('div');
  /** The model turning: kept outside the redrawn body, so the hero canvas isn't thrown away with it. */
  private stage = document.createElement('div');
  private body = document.createElement('div');
  pick: Pick = null;
  private renaming = false;
  private shown = false;

  constructor(private fleet: Fleet, private wallet: Wallet, private outlets: Outlets, private host: UnitPaneHost) {
    this.el.className = 'hq-pane';
    this.stage.className = 'hq-stage veh';
    this.body.className = 'hq-pbody';
    this.el.append(this.stage, this.body);
    this.el.addEventListener('click', (e) => this.onClick(e));
    this.el.addEventListener('change', (e) => this.onChange(e));
    this.el.addEventListener('input', (e) => this.onInput(e));
    // the record's chart (recordHtml): the hovered day's takings, as the Books' charts show theirs
    const tip = document.createElement('div');
    tip.className = 'hq-tip';
    tip.hidden = true;
    this.el.append(tip);
    this.el.addEventListener('pointermove', (e) => {
      const hit = (e.target as Element).closest?.('.hq-rec [data-tip]');
      if (!hit) { tip.hidden = true; return; }
      tip.innerHTML = hit.getAttribute('data-tip') ?? '';
      tip.hidden = false;
      const r = this.el.getBoundingClientRect();
      tip.style.left = `${Math.max(4, Math.min(e.clientX - r.left + 14, r.width - tip.offsetWidth - 4))}px`;
      tip.style.top = `${e.clientY - r.top + this.el.scrollTop + 14}px`;
    });
    this.el.addEventListener('pointerleave', () => { tip.hidden = true; });
    this.el.addEventListener('scroll', () => { tip.hidden = true; }, { passive: true });
    // typing a name: the keys are the name's, not the game's
    this.el.addEventListener('keydown', (e) => {
      const t = e.target as HTMLInputElement;
      if (t.tagName !== 'INPUT' || t.type !== 'text') return;
      if (e.code === 'Enter' || e.code === 'Escape') { this.finishRename(e.code === 'Enter'); e.preventDefault(); }
      e.stopPropagation();
    });
  }

  get unit(): Unit | null { return this.pick?.k === 'unit' ? this.fleet.unit(this.pick.uid) ?? null : null; }

  set(p: Pick): void {
    const same = JSON.stringify(p) === JSON.stringify(this.pick);
    this.pick = p;
    if (!same) { this.renaming = false; }
    this.render();
  }

  /** The tab is up (true) or not: the hero canvas goes where it is needed. */
  setVisible(on: boolean): void {
    this.shown = on;
    if (on) this.render();
  }

  render(): void {
    if (this.renaming) return;
    const u = this.unit;
    this.stage.hidden = !u;
    if (u && this.shown) {
      hero.mount(this.stage);
      hero.show({ kind: 'vehicle', model: u.model, parts: u.parts }, 0xffffff);
    }
    if (u) this.body.innerHTML = this.unitHtml(u);
    else if (this.pick?.k === 'driver') {
      const d = this.fleet.driver(this.pick.id);
      this.body.innerHTML = d ? this.driverHtml(d) : '<p class="none">Gone.</p>';
    } else if (this.pick?.k === 'hire') this.body.innerHTML = this.hireHtml();
    else this.body.innerHTML = '<p class="none">Pick a vehicle, a driver, or Hire… on the board to see it here.</p>';
    if (this.renaming) {
      const input = this.body.querySelector<HTMLInputElement>('[data-rename]');
      input?.focus();
      input?.select();
    }
  }

  /** Only the lines that move, twice a second. */
  refresh(): void {
    const u = this.unit;
    const live = this.body.querySelector<HTMLElement>('[data-live]');
    if (u && live) {
      const t = this.fleet.stateLine(u);
      if (live.textContent !== t) live.textContent = t;
    }
    for (const b of Array.from(this.body.querySelectorAll<HTMLButtonElement>('[data-watch]'))) {
      const w = this.fleet.unit(Number(b.dataset.watch));
      const why = w ? this.host.watchable(w) : 'Gone';
      if (b.disabled !== !!why) { b.disabled = !!why; b.title = why ?? `Watch ${w!.name} · Esc to come back`; }
    }
  }

  camButton(u: Unit, label = false): string {
    if (u.where === 'ridden' || u.where === 'garaged') return '';
    const why = this.host.watchable(u);
    return `<button type="button" class="gcam" data-watch="${u.uid}"${why ? ` disabled title="${esc(why)}"` : ` title="Watch ${esc(u.name)} · Esc to come back"`}>${CAMERA_SVG}${label ? '<span>Watch</span>' : ''}</button>`;
  }

  // ---- a vehicle ----

  private unitHtml(u: Unit): string {
    const def = defOf(u.model);
    const d = this.fleet.driverOf(u);
    const log = u.log;
    const head = this.renaming
      ? `<div class="gname"><input type="text" data-rename value="${esc(u.name)}" maxlength="24" aria-label="Name"><button type="button" data-act="rename-ok">Save</button></div>`
      : `<div class="gname"><h4>${esc(u.name)}</h4>${u.name !== def.name ? `<span>${esc(def.name)}</span>` : ''}${this.camButton(u, true)}</div>`;
    const stats = `<p class="gstat" data-live>${esc(this.fleet.stateLine(u))}</p>
      <p class="gsub">holds ${def.capacity} · ${def.holds.map((c) => CLASS_LABEL[c]).join(' ')} · ${Math.round(log.tiles).toLocaleString()} tiles · ${log.deliveries} deliver${log.deliveries === 1 ? 'y' : 'ies'} · ${money(log.earned)} to you${log.incidents ? ` · ${log.incidents} incident${log.incidents === 1 ? '' : 's'}` : ''}</p>`;
    // who drives it and how it works first, then what it has earned and what it is (the user, 6 Nov 2026)
    return head + stats + this.crewHtml(u, d) + this.recordHtml(u) + this.vehicleHtml(u) + this.actsHtml(u, d);
  }

  /**
   * Its record (the user, 5 Nov 2026): what it paid you each of the last 30 game days, its rate a day over its
   * last 30 days of work (Fleet.dayRate, DAY_LOG), and the cargo it has carried most, by loads.
   */
  private recordHtml(u: Unit): string {
    const today = this.host.day(), span = 30;
    const byDay = new Map((u.days ?? []).map(([day, e]) => [day, e]));
    const cats = Array.from({ length: span }, (_, i) => (i === span - 1 ? 'today' : `−${span - 1 - i}`));
    const values = Array.from({ length: span }, (_, i) => Math.round(byDay.get(today - (span - 1 - i)) ?? 0));
    const month = values.reduce((s, v) => s + v, 0);
    const rate = this.fleet.dayRate(u), worked = this.fleet.dayRateDays(u);
    const rateLine = rate > 0
      ? `≈ <b>${money(Math.round(rate))}</b> a day at work${worked > 1 ? `, over its last ${worked} days of work` : ' so far'}`
      : 'no rate yet: it hasn’t worked long enough to measure';
    const chart = month > 0
      ? `<div class="hq-rec-chart">${stacked(cats, [{ label: 'To you', colour: 1, values }], 150)}</div>`
      : '<p class="gnone">Nothing earned in the last 30 days.</p>';
    const kinds = Object.entries(u.kinds ?? {}).sort((a, b) => b[1][0] - a[1][0] || b[1][1] - a[1][1]);
    const top = kinds.slice(0, 6), most = top[0]?.[1][0] ?? 1;
    const rest = kinds.slice(6).reduce((s, [, [n]]) => s + n, 0);
    const kindRows = top.map(([id, [n, e]]) => {
      const c = CARGO.find((x) => x.id === id);
      return `<li><span class="ki">${c?.icon ?? '📦'}</span><span class="kn">${esc(c?.name ?? id)}</span><span class="kb"><i style="width:${Math.max(4, Math.round((n / most) * 100))}%"></i></span><span class="kv">${n} load${n === 1 ? '' : 's'}<small>${money(Math.round(e))}</small></span></li>`;
    }).join('');
    const counted = kinds.reduce((s, [, [n]]) => s + n, 0), early = u.log.deliveries - counted;
    const others = kinds.length - top.length;
    const cargo = top.length
      ? `<ul class="hq-rec-kinds">${kindRows}</ul>${rest ? `<p class="gsub">and ${rest} load${rest === 1 ? '' : 's'} of ${others} other kind${others === 1 ? '' : 's'}</p>` : ''}${early > 0 ? `<p class="gsub">${early} earlier load${early === 1 ? ' isn’t' : 's aren’t'} sorted by kind: kinds are counted from this update on.</p>` : ''}`
      : '<p class="gnone">No loads sorted by kind yet: they are counted from its next delivery.</p>';
    return `<section class="hq-sec hq-rec"><h5>Earnings · last 30 days</h5>
      <p class="gsub"><b>${money(month)}</b> to you in the last 30 game days · ${rateLine}</p>${chart}
      <h5 class="hq-rec-h">Cargo carried most</h5>${cargo}</section>`;
  }

  /** The inspector: what it has fitted and owns in each slot, what each does, and where to buy more. */
  private vehicleHtml(u: Unit): string {
    const def = defOf(u.model), p = u.parts;
    const tuned = this.fleet.defFor(u);
    const locked = this.host.unlocked && !this.host.unlocked(u.model)
      ? `<p class="gnone">The ${esc(def.name)} is still locked in the tech tree: you own this one, but a dealer won't sell you another. <button type="button" class="link" data-act="tech">Tech tab</button></p>` : '';
    const rows = slotsFor(def).map((s) => {
      const have = owned(p, s.id), on = fitted(p, s.id);
      const pips = [0, 1, 2, 3].map((t) => {
        const own = t <= have;
        const label = t === 0 ? 'Stock' : tierName(s, def, t);
        const title = own ? `${label}${t === on ? ' · fitted' : ' · owned: fit it free'}` : `${label} · ${money(tierPrice(def, s.id, t))} at a Vehicle Shop`;
        return `<button type="button" class="pip t${t}${t === on ? ' on' : ''}${own ? ' own' : ''}" data-fit="${s.id}:${t}"${own ? '' : ' disabled'} title="${esc(title)}" aria-label="${esc(title)}"></button>`;
      }).join('');
      const paint = s.id === 'paint' && have ? ` <i class="sw" style="background:#${(p?.c ?? def.color).toString(16).padStart(6, '0')}"></i>${esc(colourName(p?.c ?? def.color))}` : '';
      const what = on ? effectLine(s.id, def, applyParts(def, { t: { [s.id]: [on, on] }, spent: 0 }), on) : have ? 'Owned, not fitted' : '';
      const nos = s.id === 'nitrous' && on && p?.nos?.some((x) => x > 0) ? ' · refilling' : '';
      return `<li><span class="si">${s.icon}</span><span class="sn"><b>${esc(slotName(s, def))}</b><small>${esc(on ? tierName(s, def, on) : have ? `${tierName(s, def, have)} owned` : 'stock')}${paint}${nos}</small></span><span class="pips">${pips}</span>${what ? `<small class="fx">${esc(what)}</small>` : ''}</li>`;
    }).join('');
    const me = this.host.where();
    const shop = this.outlets.nearest('shop', me.x, me.z);
    const more = shop ? `Nearest Vehicle Shop: ${esc(shop.o.name)}, ${esc(wayTo(me.x, me.z, shop.o))}` : 'Parts are bought at a Vehicle Shop: drive into its striped ring and press Space';
    // the faction paintjobs earned for this model (docs/factions.html)
    const jobs = [...UNLOCKS.values()].filter((x) => x.u.kind === 'job' && x.u.model === u.model && unlocks.has(x.u.id));
    // and the Passport's, on anything (game/passportRewards.ts)
    const treatJobs = TREAT_JOBS.filter((t) => rewards.has(t.seal));
    const jobRow = jobs.length || treatJobs.length
      ? `<div class="hq-jobs"><b>Paintjob</b> <button type="button" class="${p?.j ? '' : 'on'}" data-job="">Own paint</button>${jobs.map((x) => `<button type="button" class="${p?.j === x.u.id ? 'on' : ''}" data-job="${x.u.id}" title="${esc(x.u.blurb)}">${FACTIONS[x.f].icon} ${esc(x.u.name)}</button>`).join('')}${
        treatJobs.map((t) => `<button type="button" class="${p?.j === t.id ? 'on' : ''}" data-job="${t.id}" title="${esc(`${TREATS[t.seal].name}, from the Passport`)}">${t.icon} ${esc(t.name)}</button>`).join('')}</div>`
      : '';
    // the Passport's treats that go on one vehicle at a time: free, on or off
    const toggles = TREAT_TOGGLES.filter((t) => rewards.has(t.seal));
    const isOn = (t: (typeof TREAT_TOGGLES)[number]): boolean => (t.set.l ? !!p?.l : p?.h === t.set.h);
    const treatRow = toggles.length
      ? `<div class="hq-jobs"><b>Treats</b> ${toggles.map((t) => `<button type="button" class="${isOn(t) ? 'on' : ''}" data-treat="${t.key}" title="${esc(TREATS[t.seal].blurb)}">${t.icon} ${esc(t.label)}</button>`).join('')}</div>`
      : '';
    // the toppers earned (docs/toppers.html, game/toppers.ts): one on the roof, the Wonder Ball among them
    const mine = toppers.owned(), worn = topperOf(p);
    const topRow = mine.length
      ? `<div class="hq-jobs"><b>Topper</b> <select data-topper="1" title="Toppers are earned over a long career: HQ window → Toppers"><option value="">None</option>${mine.map((t) => `<option value="${t.id}"${worn === t.id ? ' selected' : ''}>${t.icon} ${esc(t.name)}</option>`).join('')}</select></div>`
      : '';
    return `<section class="hq-sec"><h5>Vehicle</h5>
      <p class="gsub">${esc(headline(tuned))}</p>${jobRow}${treatRow}${topRow}
      <p class="gsub">${esc(partsLine(def, p))} · ${money(p?.spent ?? 0)} on parts · sells for ${money(this.fleet.resale(u))}</p>${locked}
      <ul class="hq-parts">${rows}</ul>
      <p class="gsub more">Owned tiers fit here for nothing. ${more}.</p></section>`;
  }

  private crewHtml(u: Unit, d: Driver | null): string {
    const def = defOf(u.model);
    const lic = licenceFor(def);
    let crew = '';
    if (u.where === 'garaged') {
      crew = `<p class="gnone">In the garage, off the map: it follows nobody and nobody can crew it. Out near where it went in is free; anywhere further it comes on a tow truck, and the fee is asked first. ${this.fleet.free ? 'Drag it onto a free slot, or Bring it out below.' : `Every slot is taken (${this.fleet.slots}): drive it from here, or put something else away first.`}</p>`;
    } else if (d) {
      const mode = modeOf(d.cut);
      const rate = this.fleet.dayRate(u);
      const isRail = def.kind === 'rail';
      // Mode first, then the cut it pays (the user, 8 Nov 2026); a train has no Mode, its beat follows the cut
      crew = `<div class="gdriver">${crewCard(d, { hired: true, day: this.host.day(), note: rate ? `In this vehicle ≈ <b>${money(Math.round(rate))}</b> a day for you` : undefined })}</div>
        ${isRail ? '' : this.followHtml(u)}<label class="gcut"><span>Your cut <b data-cutlabel>${Math.round(d.cut * 100)}% · ${MODE_LABEL[mode]}</b></span>
          <input type="range" data-cut min="${CUT_MIN * 100}" max="${CUT_MAX * 100}" step="5" value="${Math.round(d.cut * 100)}"></label>
        <p class="gmode" data-modeline>${modeBlurb(mode)}</p>`;
      // a train keeps to its line: no Follow, and its order is its beat (docs/crewtrains.html)
      crew += isRail ? this.beatHtml(u) : this.orderHtml(u);
    } else if (!lic) {
      crew = '<p class="gnone">Nobody can be licensed to drive this.</p>';
    } else if (!canLoad(def)) {
      crew = def.kind === 'air' && def.jet
        ? `<p class="gnone">Nobody holds a jet rating yet: you fly the ${esc(def.name)} yourself.</p>`
        : `<p class="gnone">The ${esc(def.name)} never stops, so it can never load: no driver can work it.</p>`;
    } else {
      const day = this.host.day();
      const cands = this.host.roster()
        ? this.fleet.roster().map((c, k) => ({ d: c, taken: false, k: -1 - k })).filter((c) => mayDrive(c.d, def))
        : this.fleet.today(day).filter((c) => !c.taken && mayDrive(c.d, def));
      const bench = this.fleet.bench.filter((b) => mayDrive(b, def));
      const why = u.where === 'parked' ? this.fleet.cantPut({ ...(cands[0]?.d ?? bench[0] ?? { licences: [lic] }) } as Driver, u) : null;
      const rows = [
        ...bench.map((b) => `<li>${crewCard(b, { compact: true, hired: true, day, note: 'On the bench',
          extra: `<button type="button" data-put="${b.id}"${u.where !== 'parked' ? ' disabled' : ''}>Put in</button>` })}</li>`),
        ...cands.map((c) => `<li>${crewCard(c.d, { compact: true,
          extra: `<button type="button" data-hire="${c.k}"${u.where !== 'parked' || !this.wallet.canAfford(feeOf(c.d)) ? ' disabled' : ''}>Hire · ${money(feeOf(c.d))}</button>` })}</li>`),
      ];
      crew = `<div class="ghire"><b>Hire a driver</b>${def.id === 'bigblue' ? '<small>A Big Blue driver works the harbours of its own cell only: a port-to-port shuttle.</small>' : ''}
        ${u.where === 'ridden' ? '<small>Step out of it first: a driver can only take a parked unit.</small>' : why && u.where === 'parked' && !why.includes('licence') ? `<small>${esc(why)}</small>` : ''}
        ${rows.length ? `<ul>${rows.join('')}</ul>` : `<small>Nobody with a ${lic} licence today. New candidates every game day.</small>`}</div>`;
    }
    const lay = u.where !== 'garaged' && (u.where === 'parked' || u.laidUp)
      ? `<label class="glay"><input type="checkbox" data-lay${u.laidUp ? ' checked' : ''}> Leave it here<small>${u.laidUp ? 'Nobody comes for it.' : 'With Bring them along on in Settings, a delivery driver brings it over when you move county.'}</small></label>`
      : '';
    return `<section class="hq-sec"><h5>Crew</h5>${crew}${lay}</section>`;
  }

  private actsHtml(u: Unit, d: Driver | null): string {
    const shed = u.where === 'garaged';
    const tow = u.where === 'parked' ? this.fleet.towFee(u) : null;
    const over = this.host.towOver(u);
    const canRide = u.where !== 'ridden' && u.where !== 'towing' && u.where !== 'enroute';
    const free = this.fleet.free > 0;
    const store = shed ? null : this.fleet.cantStore(u);
    const acts = shed ? `<button type="button" class="primary" data-act="ride">Drive it from here</button>
      <button type="button" data-act="deploy"${free ? '' : ` disabled title="No free slot: ${this.fleet.slots} out of ${this.fleet.slots} are taken"`}>Bring it out</button>
      <button type="button" data-act="rename">Rename</button>
      <button type="button" data-act="sell">Sell ${money(this.fleet.resale(u))}</button>`
      : `<button type="button" class="primary" data-act="ride"${canRide ? '' : ' disabled'}>${d ? 'Take the wheel' : 'Ride'}</button>
      ${store ? '' : `<button type="button" data-act="store" title="Off the map: frees a fleet slot${d ? `; ${esc(d.name)} goes on the bench` : ''}">To the garage</button>`}
      ${tow ? `<button type="button" data-act="tow"${this.wallet.canAfford(tow.fee) ? '' : ' disabled'} title="$40 + $1 a tile${tow.gaps ? ` + $150 × ${tow.gaps} crossing${tow.gaps === 1 ? '' : 's'}` : ''}">Tow ${money(tow.fee)}</button>` : ''}
      ${over !== null ? `<button type="button" data-act="over"${this.wallet.canAfford(over) ? '' : ' disabled'} title="A delivery driver brings it, billed when it arrives">Bring over ${money(over)}</button>` : ''}
      ${d ? '<button type="button" data-act="dismiss">Dismiss driver</button>' : ''}
      <button type="button" data-act="rename">Rename</button>
      <button type="button" data-act="sell"${u.where === 'ridden' ? ' disabled title="You are in it"' : ''}>Sell ${money(this.fleet.resale(u))}</button>`;
    return `<section class="hq-sec"><h5>Actions</h5><div class="gacts">${acts}</div></section>`;
  }

  /**
   * Work or Follow for this one vehicle (the same pair as the dock's tray, game/fleetPanel.ts): Work finds its own
   * loads and pays you a cut; Follow drives in formation behind you and lends you its hold. The first drive's tour
   * points at it (fleetBoard.ts tour).
   */
  /** A crewed train's beat (docs/crewtrains.html): the stations it runs between. Whole line only until phase 2's Custom. */
  private beatHtml(u: Unit): string {
    const rail = this.fleet.rail;
    const b = rail?.beat(u) ?? null;
    const custom = !!u.order.beat?.custom;
    const picking = this.beatPick?.uid === u.uid;
    const stops = b ? b.stops.map((s) => (s === b.ends[0] || s === b.ends[1] ? `<b>${esc(s.name)}</b>` : esc(s.name))).join(' — ') : '';
    const line = picking ? (this.beatPick!.first ? `Now the other end: ${esc(this.beatPick!.first.name)} and…` : 'Click the station at one end of its beat, then the other.')
      : b ? esc(rail?.idleWhy(u) ?? (custom ? 'Runs between the two ends you chose, calling at the stops between and turning round at each.' : 'Runs the whole line within reach, calling at every stop and turning round at each end.'))
      : u.held ? esc(u.held) : 'Put on the line, it works the whole line within reach of where it stands.';
    const ends = u.order.beat?.custom;
    const isEnd = (e: { cx: number; cz: number; name: string }) => !!ends && [ends.a, ends.b].some((q) => q.cx === e.cx && q.cz === e.cz && q.name === e.name);
    const first = this.beatPick?.uid === u.uid ? this.beatPick.first : null;
    // long haul (docs/crewtrains.html): only where the line runs on past an end of the beat to a far station
    const longOn = !!u.order.beat?.long;
    const longPill = rail?.longOk(u) || longOn
      ? `<button type="button" class="chip${longOn ? ' on' : ''}" data-beatlong="1" title="Take long-haul loads at the ends, 5–14 counties on along the line, and run them there and back out of sight">Long haul</button>` : '';
    const away = rail?.farLine(u) ?? null;
    const chips = picking && rail ? rail.reachable(u).map((e) => {
      const on = isEnd(e) || (!!first && first.cx === e.cx && first.cz === e.cz && first.name === e.name);
      return `<button type="button" class="chip${on ? ' on' : ''}" data-bend="${e.cx}|${e.cz}|${esc(e.name)}">${esc(e.name)}</button>`;
    }).join('') : '';
    return `<div class="gmodes"><div class="glbl">Beat</div><div class="chips">
      <button type="button" class="chip${!custom && !picking ? ' on' : ''}" data-beatmode="whole" title="The whole line within reach of where it works">Whole line</button>
      <button type="button" class="chip${custom || picking ? ' on' : ''}" data-beatmode="custom" title="Two stations of your own as its ends">Custom</button>${longPill}</div>
      ${chips ? `<div class="chips">${chips}</div>` : ''}${stops ? `<p class="gsub">${stops}</p>` : ''}<p class="gsub">${away ? `${esc(away[0].toUpperCase() + away.slice(1))} · Watch goes to where it is now` : line}</p></div>`;
  }

  /** Custom ends being chosen in the Beat block: which unit, and the first end clicked. */
  private beatPick: { uid: number; first: { cx: number; cz: number; name: string } | null } | null = null;

  private followHtml(u: Unit): string {
    if (!this.host.setMode) return '';
    const now = u.mode ?? 'work';
    const why = this.host.followWhy?.(u) ?? null;
    const line = now === 'follow'
      ? 'Following you in formation: while in line, its hold counts as yours. It earns nothing on its own.'
      : 'Out working: it finds its own loads and pays you your cut of each.';
    return `<div class="gmodes"><div class="glbl">Mode</div><div class="chips">
      <button type="button" class="chip${now === 'work' ? ' on' : ''}" data-umode="work" title="Take loads and earn, wherever you go">Work</button>
      <button type="button" class="chip${now === 'follow' ? ' on' : ''}" data-umode="follow"${why && now !== 'follow' ? ` disabled title="${esc(why)}"` : ' title="Drive in formation behind you, lending its hold"'}>Follow</button></div>
      <p class="gsub">${esc(line)}</p></div>`;
  }

  private orderHtml(u: Unit): string {
    const def = defOf(u.model);
    const o = u.order;
    // the pill lit is the preset the order still matches; edited away from every one, it is Custom
    const is = presetOf(o, def);
    const chips = (Object.keys(PRESET_LABEL) as PresetId[]).map((p) => `<button type="button" class="chip${is === p ? ' on' : ''}" data-preset="${p}">${PRESET_LABEL[p]}</button>`).join('')
      + `<button type="button" class="chip${is === 'custom' ? ' on' : ''}" data-custom title="${is === 'custom' ? 'Edited from the presets: change any line below' : 'Change any line below to make your own'}">Custom</button>`;
    const bases = this.fleet.basesFor(u);
    // the first choice leaves the base to the fleet (nearest the HQ, moved as the fleet moves); any town picked stays
    const auto = this.fleet.hq ? 'Nearest the HQ' : 'Nearest';
    const baseSel = `<select data-field="base"><option value="auto"${o.chosen ? '' : ' selected'}>${auto}${!o.chosen && o.base ? ` · ${esc(o.base.name)}` : ''}</option>${bases.map((b, k) => `<option value="${k}"${o.chosen && o.base && b.kind === o.base.kind && b.id === o.base.id && b.cx === o.base.cx && b.cz === o.base.cz ? ' selected' : ''}>${esc(b.name)}</option>`).join('')}</select>`;
    const types = CARGO.filter((t) => def.holds.includes(t.cls) && t.units <= def.capacity);
    const seen = new Set<string>();
    const typeChips = types.filter((t) => !seen.has(t.id) && seen.add(t.id)).map((t) => `<button type="button" class="chip small${o.prefers.includes(t.id) ? ' on' : ''}" data-prefer="${t.id}" title="${esc(t.name)}">${t.icon} ${esc(t.name)}</button>`).join('');
    // every line of the order always shown, under the presets that set them (the user, 6 Nov 2026: no fold, and one
    // card, so it is plain that a pill on top changes everything below it)
    const editor = `<div class="go-rows">
      <div class="grow2"><span>Takes</span><span>${def.holds.map((c) => `<label class="tick"><input type="checkbox" data-take="${c}"${o.takes.length === 0 || o.takes.includes(c) ? ' checked' : ''}> ${CLASS_LABEL[c]}</label>`).join('')}</span></div>
      <div class="grow2"><span>At least</span><select data-field="floor">${LADDER.map((l) => `<option value="${l}"${o.floor === l ? ' selected' : ''}>${l === 'none' ? 'No limit (anything)' : URGENCY[l].label}</option>`).join('')}</select></div>
      <div class="grow2"><span>Range</span><select data-field="range">${(Object.keys(RANGE_LABEL) as Range[]).map((r) => `<option value="${r}"${o.range === r ? ' selected' : ''}>${RANGE_LABEL[r]}</option>`).join('')}</select></div>
      <div class="grow2"><span>Borders</span><select data-field="cross">${(Object.keys(CROSS_LABEL) as Cross[]).map((r) => `<option value="${r}"${o.cross === r ? ' selected' : ''}>${CROSS_LABEL[r]}</option>`).join('')}</select></div>
      <div class="grow2"><span>Packing</span><select data-field="pack">${(Object.keys(PACK_LABEL) as Pack[]).map((r) => `<option value="${r}"${(o.pack ?? 'some') === r ? ' selected' : ''}>${PACK_LABEL[r]}</option>`).join('')}</select></div>
      <div class="grow2"><span>Base</span>${baseSel}</div>
      <div class="grow2"><span>Prefers <small>up to 4</small></span><span class="types">${typeChips}</span></div>
    </div>`;
    const caption = o.wait ? 'Waiting where it stands: it takes no work until Wait is off.'
      : is === 'custom' ? 'Your own order: pick a preset to set every line below at once.'
      : `${PRESET_LABEL[is as PresetId]} sets every line below · change any line to make it your own (Custom).`;
    return `<div class="gorders"><div class="go-top"><div class="glbl">Orders</div>
      <div class="chips">${chips}<span class="go-sep"></span><button type="button" class="chip wait${o.wait ? ' on' : ''}" data-wait title="Stop where it is and take no work">Wait</button></div>
      <p class="go-cap">${esc(caption)}</p></div>
      ${editor}<p class="gsub go-sum">${esc(packLine(o.pack ?? 'some', this.fleet.driverOf(u), o, def.capacity))}</p></div>`;
  }

  // ---- a driver ----

  /** Units this driver could be put in now: parked, a licence they hold, one that can load. */
  seatsFor(d: Driver): Unit[] {
    return this.fleet.units.filter((u) => u.where === 'parked' && !u.driver && mayDrive(d, defOf(u.model)) && canLoad(defOf(u.model)));
  }

  private driverHtml(d: Driver): string {
    const u = d.unit ? this.fleet.unit(d.unit) : null;
    const fits = this.seatsFor(d);
    const mode = modeOf(d.cut);
    const where = u ? `in <b>${esc(u.name)}</b> · ${esc(this.fleet.stateLine(u))}` : 'on the bench · a bench is not a store: their mood slides while they wait';
    const put = fits.length
      ? `<span class="dput"><select data-into="${d.id}">${fits.map((q) => `<option value="${q.uid}">${esc(q.name)}${q.place ? ` · ${esc(q.place)}` : ''}</option>`).join('')}</select><button type="button" data-putd="${d.id}">Put in</button></span>`
      : '<small>No parked vehicle without a driver that they are licensed for.</small>';
    return `<div class="gname"><h4>${esc(d.name)}</h4><span>${rankOf(d)}</span>${u ? this.camButton(u, true) : ''}</div>
      <p class="gstat">${where}</p>
      <section class="hq-sec"><h5>Driver</h5>
        <div class="gdriver">${crewCard(d, { hired: true, day: this.host.day(), note: `Your cut <b>${Math.round(d.cut * 100)}%</b> · ${MODE_LABEL[mode]}` })}</div>
      </section>
      <section class="hq-sec"><h5>Seat</h5>${u ? '' : put}</section>
      <section class="hq-sec"><h5>Actions</h5><div class="gacts">
        ${u ? `<button type="button" data-unseat="${d.id}">To the bench</button>` : ''}
        <button type="button" data-fire="${d.id}">Let go</button>
      </div></section>`;
  }

  // ---- hiring ----

  private hireHtml(): string {
    const day = this.host.day();
    const full = this.fleet.drivers.length >= this.fleet.slots;
    const cands = this.host.roster() ? this.fleet.roster().map((d, k) => ({ d, taken: false, k: -1 - k })) : this.fleet.today(day);
    const card = (d: Driver, extra: string) => `<div class="dcard">${crewCard(d, { extra })}</div>`;
    const rows = cands.map((c) => card(c.d, c.taken ? '<button type="button" disabled>Hired</button>'
      : `<button type="button" data-hire-bench="${c.k}"${!full && this.wallet.canAfford(feeOf(c.d)) ? '' : ' disabled'}>Hire · ${money(feeOf(c.d))}</button>`)).join('');
    return `<div class="gname"><h4>${this.host.roster() ? 'Full roster' : 'Today’s candidates'}</h4></div>
      <p class="gsub">${this.host.roster() ? 'Cheats · a road, sea and air driver at every rank, and an ace who holds all three.' : 'Three a game day. Signing fee: $300 a road licence, $900 sea, $2,500 air; a regular costs 1.5×, a veteran 2.5×. A driver’s only pay is their share.'}</p>
      ${!this.fleet.hq ? '<p class="gnone hq-nohire"><b>🔒 You can’t hire anyone until you have an HQ.</b> Every driver needs a fleet slot, and slots come only from your HQ: buy a building (a house will do), make it your HQ, then come back to sign a driver.</p>'
        : full ? `<p class="gnone">Your crew is full: ${this.fleet.drivers.length} of ${this.fleet.slots}, one driver to each fleet slot. A grander HQ opens more.</p>` : ''}
      <div class="dgrid">${rows}</div>`;
  }

  // ---- buttons ----

  private ride(u: Unit): void {
    if (u.where === 'ridden' || u.where === 'towing') return;
    const why = u.where === 'garaged' ? this.host.swapIn(u) : this.host.ride(u);
    if (why) { this.host.say(why); return; }
    this.host.close();
  }

  watch(uid: number): void {
    const u = this.fleet.unit(uid);
    if (!u || this.host.watchable(u)) return;
    this.host.close();
    this.host.watch(u);
  }

  private onClick(e: Event): void {
    const t = e.target as HTMLElement;
    const b = t.closest<HTMLElement>('button');
    if (!b || (b as HTMLButtonElement).disabled) return;
    if (b.dataset.watch) { this.watch(Number(b.dataset.watch)); return; }
    const say = (s: string) => this.host.say(s);
    // Work or Follow, for the vehicle picked
    if (b.dataset.umode && this.pick?.k === 'unit') {
      const u = this.fleet.unit(this.pick.uid);
      if (u) {
        this.host.setMode?.(u, b.dataset.umode as 'work' | 'follow');
        say(b.dataset.umode === 'work' ? `${u.name} is off to find work` : `${u.name} is falling in behind you`);
      }
      this.after();
      return;
    }
    // a crewed train's beat: Whole line, or Custom's two ends clicked in turn (docs/crewtrains.html)
    if ((b.dataset.beatmode || b.dataset.bend || b.dataset.beatlong) && this.pick?.k === 'unit') {
      const u = this.fleet.unit(this.pick.uid);
      const rail = this.fleet.rail;
      if (u && rail) {
        if (b.dataset.beatlong) {
          const order = u.order.beat ?? (u.order.beat = { home: [u.cx, u.cz] });
          order.long = !order.long || undefined;
          say(order.long ? `${u.name} takes long hauls at the ends of its beat` : `${u.name} keeps to its beat`);
        } else if (b.dataset.beatmode === 'whole') { this.beatPick = null; rail.setEnds(u, null); say(`${u.name} works the whole line`); }
        else if (b.dataset.beatmode === 'custom') this.beatPick = { uid: u.uid, first: null };
        else if (b.dataset.bend) {
          const [cx, cz, ...name] = b.dataset.bend.split('|');
          const e = { cx: Number(cx), cz: Number(cz), name: name.join('|') };
          const first = this.beatPick?.uid === u.uid ? this.beatPick.first : null;
          if (!first) this.beatPick = { uid: u.uid, first: e };
          else {
            const why = rail.setEnds(u, { a: first, b: e });
            this.beatPick = null;
            say(why ?? `${u.name} runs ${first.name} — ${e.name}`);
          }
        }
      }
      this.after();
      return;
    }
    // the driver and hire panes
    if (b.dataset.putd) {
      const d = this.fleet.driver(Number(b.dataset.putd));
      const sel = this.body.querySelector<HTMLSelectElement>(`[data-into="${b.dataset.putd}"]`);
      const u = sel ? this.fleet.unit(Number(sel.value)) : null;
      const why = d && u ? this.fleet.put(d, u) : 'Choose a vehicle';
      say(why ?? `${d!.name} is out in ${u!.name}`);
      if (!why && u) this.pick = { k: 'unit', uid: u.uid };
      this.after();
      return;
    }
    if (b.dataset.unseat) {
      const d = this.fleet.driver(Number(b.dataset.unseat));
      const u = d?.unit ? this.fleet.unit(d.unit) : null;
      if (u) { this.fleet.dismiss(u); say(`${d!.name} is on the bench`); }
      this.after();
      return;
    }
    if (b.dataset.fire) {
      const d = this.fleet.driver(Number(b.dataset.fire));
      if (b.dataset.armed && d) { this.fleet.fire(d); say(`${d.name} has gone`); this.pick = null; this.after(); return; }
      b.dataset.armed = '1';
      b.textContent = 'Sure? They leave for good';
      b.classList.add('armed');
      return;
    }
    if (b.dataset.hireBench) {
      const k = Number(b.dataset.hireBench);
      const why = k < 0 ? this.fleet.hireRoster(-1 - k, null) : this.fleet.hire(this.host.day(), k, null);
      say(why ?? 'Signed · they are on the bench');
      this.after();
      return;
    }
    if (b.dataset.act === 'tech') { const u = this.unit; if (u) this.host.tech(u.model); return; }
    const u = this.unit;
    if (!u) return;
    if (b.dataset.job !== undefined) {
      const why = this.fleet.wearJob(u, b.dataset.job || null);
      const name = UNLOCKS.get(b.dataset.job)?.u.name ?? TREAT_JOBS.find((t) => t.id === b.dataset.job)?.name ?? 'Paintjob';
      if (why) say(why); else say(b.dataset.job ? `${name} on ${u.name}` : `${u.name} back in its own paint`);
    } else if (b.dataset.treat) {
      const t = TREAT_TOGGLES.find((x) => x.key === b.dataset.treat);
      if (!t || !rewards.has(t.seal)) return;
      const on = t.set.l ? !!u.parts?.l : u.parts?.h === t.set.h;
      this.fleet.wearTreat(u, t.set.l ? { l: on ? undefined : 1 } : { h: on ? undefined : t.set.h });
      say(`${t.label} ${on ? 'off' : 'on'} ${u.name}`);
    } else if (b.dataset.fit) {
      const [slot, tier] = b.dataset.fit.split(':');
      const why = this.fleet.refit(u, slot as SlotId, Number(tier));
      if (why) say(why);
    } else if (b.dataset.act === 'ride') { this.ride(u); return; }
    else if (b.dataset.act === 'store') {
      const d = this.fleet.driverOf(u);
      const why = this.fleet.store(u);
      say(why ?? `${u.name} is in the garage${d ? ` · ${d.name} is on the bench` : ''}`);
    } else if (b.dataset.act === 'deploy') {
      const why = this.host.deploy(u);
      say(why ?? `${u.name} is out of the garage, beside you`);
    } else if (b.dataset.act === 'tow') {
      const fee = this.fleet.towFee(u)?.fee ?? 0;
      const why = this.fleet.startTow(u);
      say(why ?? `${u.name} is on its way to you · −${money(fee)}`);
    } else if (b.dataset.act === 'over') {
      const fee = this.host.towOver(u) ?? 0;
      const why = this.host.bringOver(u);
      say(why ?? `${u.name} is being brought over · ${money(fee)} on arrival`);
    } else if (b.dataset.act === 'sell') {
      const price = this.fleet.resale(u);
      if (b.dataset.armed) {
        if (this.fleet.sell(u)) { say(`Sold ${u.name} · +${money(price)}`); this.pick = null; }
      } else {
        b.dataset.armed = '1';
        b.textContent = `Sure? +${money(price)}`;
        b.classList.add('armed');
        return;
      }
    } else if (b.dataset.act === 'dismiss') {
      const d = this.fleet.driverOf(u);
      this.fleet.dismiss(u);
      if (d) say(`${d.name} is on the bench`);
    } else if (b.dataset.act === 'rename') {
      this.render();
      this.renaming = true;
      this.body.innerHTML = this.unitHtml(u);
      const input = this.body.querySelector<HTMLInputElement>('[data-rename]');
      input?.focus();
      input?.select();
      return;
    } else if (b.dataset.act === 'rename-ok') {
      this.finishRename(true);
      return;
    } else if (b.dataset.preset) {
      this.fleet.setOrder(u, { ...preset(b.dataset.preset as PresetId, u.order.base), wait: u.order.wait, pack: u.order.pack ?? 'some' });
    } else if (b.dataset.custom !== undefined) {
      // Custom is what the order becomes once edited: every line is right there under the pills
      say('Change any line of the order below and it becomes your own');
      this.body.querySelector<HTMLElement>('.go-rows select')?.focus();
      return;
    } else if (b.dataset.wait !== undefined) {
      this.fleet.setOrder(u, { ...u.order, wait: !u.order.wait });
    } else if (b.dataset.prefer) {
      const id = b.dataset.prefer;
      const prefers = u.order.prefers.includes(id) ? u.order.prefers.filter((p) => p !== id) : [...u.order.prefers, id].slice(-4);
      this.fleet.setOrder(u, { ...u.order, prefers, preset: 'custom' });
    } else if (b.dataset.hire) {
      const k = Number(b.dataset.hire);
      const why = k < 0 ? this.fleet.hireRoster(-1 - k, u) : this.fleet.hire(this.host.day(), k, u);
      say(why ?? `${this.fleet.driverOf(u)?.name ?? 'The driver'} is out in ${u.name}`);
    } else if (b.dataset.put) {
      const d = this.fleet.driver(Number(b.dataset.put));
      const why = d ? this.fleet.put(d, u) : 'No such driver';
      say(why ?? `${d!.name} is out in ${u.name}`);
    } else return;
    this.after();
  }

  private after(): void {
    this.host.changed();
    this.render();
  }

  private onChange(e: Event): void {
    const t = e.target as HTMLInputElement | HTMLSelectElement;
    const u = this.unit;
    if (!u) return;
    if (t.dataset.lay !== undefined) {
      u.laidUp = (t as HTMLInputElement).checked || undefined;
      this.fleet.onChange();
      this.render();
      return;
    }
    if (t.dataset.topper !== undefined) {
      const id = t.value || null;
      if (id && !toppers.has(id)) return;
      this.fleet.wearTopper(u, id);
      const tp = id ? TOPPER_BY_ID.get(id) : undefined;
      this.host.say(tp ? `${tp.icon} ${tp.name} on ${u.name}` : `${u.name}’s roof is bare again`);
      this.render();
      return;
    }
    if (t.dataset.cut !== undefined) {
      const d = this.fleet.driverOf(u);
      if (d) d.cut = Number(t.value) / 100;
      this.fleet.onChange();
      return;
    }
    if (t.dataset.take) {
      const boxes = Array.from(this.body.querySelectorAll<HTMLInputElement>('[data-take]'));
      const on = boxes.filter((x) => x.checked).map((x) => x.dataset.take as CargoClass);
      this.fleet.setOrder(u, { ...u.order, takes: on.length === boxes.length ? [] : on, preset: 'custom' });
    } else if (t.dataset.field === 'floor') this.fleet.setOrder(u, { ...u.order, floor: t.value as Urgency, preset: 'custom' });
    else if (t.dataset.field === 'range') this.fleet.setOrder(u, { ...u.order, range: t.value as Range, preset: 'custom' });
    else if (t.dataset.field === 'cross') this.fleet.setOrder(u, { ...u.order, cross: t.value as Cross, preset: 'custom' });
    else if (t.dataset.field === 'pack') this.fleet.setOrder(u, { ...u.order, pack: t.value as Pack });
    else if (t.dataset.field === 'base') {
      if (t.value === 'auto') this.fleet.chooseBase(u, null);
      else {
        const b = this.fleet.basesFor(u)[Number(t.value)];
        if (b) this.fleet.chooseBase(u, b);
      }
    } else return;
    this.render();
  }

  private onInput(e: Event): void {
    const t = e.target as HTMLInputElement;
    if (t.dataset.cut === undefined) return;
    const u = this.unit;
    const d = u ? this.fleet.driverOf(u) : null;
    if (!d) return;
    d.cut = Number(t.value) / 100;
    const mode = modeOf(d.cut);
    const label = this.body.querySelector('[data-cutlabel]');
    if (label) label.textContent = `${Math.round(d.cut * 100)}% · ${MODE_LABEL[mode]}`;
    const line = this.body.querySelector('[data-modeline]');
    if (line) line.textContent = modeBlurb(mode);
  }

  private finishRename(save: boolean): void {
    const u = this.unit;
    const input = this.body.querySelector<HTMLInputElement>('[data-rename]');
    this.renaming = false;
    if (u && input && save) this.fleet.rename(u, input.value);
    this.after();
  }

  /** Esc inside the pane: stop renaming. True when it did something. */
  escape(): boolean {
    if (!this.renaming) return false;
    this.finishRename(false);
    return true;
  }
}

/** The packing dial in words, with what it comes to for the driver in the seat: "packs the hold · up to 3 loads". */
function packLine(pack: Pack, d: Driver | null, o: Order, capacity: number): string {
  if (!d) return PACK_LABEL[pack];
  const n = packOf(d, o, capacity);
  return `${PACK_LABEL[pack]} · up to ${n} load${n === 1 ? '' : 's'}`;
}

function modeBlurb(mode: ReturnType<typeof modeOf>): string {
  return mode === 'hustle' ? 'Hustle: takes urgent loads first, drives quicker, never waits long, and stays happy.'
    : mode === 'steady' ? 'Steady: takes the best-paying load in reach, waits up to two hours for work, then goes back to base.'
      : 'Coasting: takes relaxed and no-limit loads only, drives slower, waits at base, and slides toward quitting.';
}
