import type { Building, World } from '../world/tiles';

/**
 * Buildings painted in a fleet's livery: every building the player owns, and each rival firm's depot,
 * wears its fleet's two colours, the walls in the body colour and the roof in the accent. The game
 * says which buildings (`setLiveryPaints`, keyed by cell and uid); the town mesher asks `liveryOf` as
 * it draws each one and `repaint`s what it drew. Doors, windows, signs and trim keep their own colours:
 * only the building's main wall colour and its main roof colour change.
 */

const paints = new Map<string, [number, number]>();
const keyOf = (cx: number, cz: number, uid: number): string => `${cx},${cz}#${uid}`;

/** The livery a building should be drawn in, or null. */
export function liveryOf(w: World, b: Building): [number, number] | null {
  return paints.get(keyOf(w.cx, w.cz, b.uid)) ?? null;
}

/** Set every painted building at once; the buildings whose paint changed, as [cx, cz, uid], to be drawn again. */
export function setLiveryPaints(next: Map<string, [number, number]>): [number, number, number][] {
  const changed: string[] = [];
  for (const [k, v] of next) { const was = paints.get(k); if (!was || was[0] !== v[0] || was[1] !== v[1]) changed.push(k); }
  for (const k of paints.keys()) if (!next.has(k)) changed.push(k);
  paints.clear();
  for (const [k, v] of next) paints.set(k, v);
  return changed.map((k) => {
    const m = /^(-?\d+),(-?\d+)#(\d+)$/.exec(k)!;
    return [Number(m[1]), Number(m[2]), Number(m[3])];
  });
}

/** A new world: nothing painted yet (the same cell and uid in another seed is another building). */
export function clearLiveryPaints(): void { paints.clear(); }

const rgb = (h: number): [number, number, number] => [((h >> 16) & 255) / 255, ((h >> 8) & 255) / 255, (h & 255) / 255];
const lum = (r: number, g: number, b: number): number => 0.299 * r + 0.587 * g + 0.114 * b;
/** Colours this close (per channel, 0–1) count as the same paint: a box's shaded top and its sides. */
const NEAR = 0.07;

/**
 * Repaint one building's triangles, `from` onward in the kit's buffers (9 floats a triangle), in a
 * livery: the colour covering most wall area becomes the body colour, the colour covering most roof
 * area the accent, each keeping its own light and shade.
 */
export function repaint(pos: number[], col: number[], from: number, livery: [number, number]): void {
  const n = Math.floor(pos.length / 9);
  if (n <= from) return;
  let y0 = Infinity, y1 = -Infinity;
  for (let t = from; t < n; t++) for (let v = 0; v < 3; v++) { const y = pos[t * 9 + v * 3 + 1]; if (y < y0) y0 = y; if (y > y1) y1 = y; }
  const up = new Uint8Array(n - from);
  const walls = new Map<string, number>(), roofs = new Map<string, number>();
  const q = (t: number) => `${Math.round(col[t * 9] * 24)},${Math.round(col[t * 9 + 1] * 24)},${Math.round(col[t * 9 + 2] * 24)}`;
  for (let t = from; t < n; t++) {
    const o = t * 9;
    const ux = pos[o + 3] - pos[o], uy = pos[o + 4] - pos[o + 1], uz = pos[o + 5] - pos[o + 2];
    const vx = pos[o + 6] - pos[o], vy = pos[o + 7] - pos[o + 1], vz = pos[o + 8] - pos[o + 2];
    const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    const len = Math.hypot(nx, ny, nz);
    if (len < 1e-9) continue;
    const area = len / 2, cy = Math.abs(ny) / len;
    const my = (pos[o + 1] + pos[o + 4] + pos[o + 7]) / 3;
    if (cy > 0.5) {
      up[t - from] = 1;
      // a roof is up top: the forecourt and the kerb round the foot are not
      if (my > y0 + (y1 - y0) * 0.3) roofs.set(q(t), (roofs.get(q(t)) ?? 0) + area);
    } else if (cy < 0.3) walls.set(q(t), (walls.get(q(t)) ?? 0) + area);
  }
  const top = (m: Map<string, number>): string | null => { let b: string | null = null, a = 0; for (const [k, v] of m) if (v > a) { a = v; b = k; } return b; };
  const wallK = top(walls), roofK = top(roofs);
  if (!wallK && !roofK) return;
  const sample = (k: string | null): [number, number, number] | null => {
    if (!k) return null;
    for (let t = from; t < n; t++) if (q(t) === k) return [col[t * 9], col[t * 9 + 1], col[t * 9 + 2]];
    return null;
  };
  const wall = sample(wallK), roof = sample(roofK);
  const body = rgb(livery[0]), accent = rgb(livery[1]);
  const near = (t: number, c: [number, number, number] | null) =>
    !!c && Math.abs(col[t * 9] - c[0]) < NEAR && Math.abs(col[t * 9 + 1] - c[1]) < NEAR && Math.abs(col[t * 9 + 2] - c[2]) < NEAR;
  for (let t = from; t < n; t++) {
    const isWall = near(t, wall), isRoof = near(t, roof);
    if (!isWall && !isRoof) continue;
    // anything of either colour looking up is roof, and the roof colour on a gable end is still roof
    const asBody = isWall && !up[t - from];
    const paint = asBody ? body : accent;
    const was = asBody || !isRoof ? wall! : roof!;
    const L = lum(was[0], was[1], was[2]) || 1;
    for (let v = 0; v < 3; v++) {
      const o = t * 9 + v * 3;
      const r = Math.min(1.25, Math.max(0.75, lum(col[o], col[o + 1], col[o + 2]) / L));
      col[o] = Math.min(1, paint[0] * r); col[o + 1] = Math.min(1, paint[1] * r); col[o + 2] = Math.min(1, paint[2] * r);
    }
  }
}
