import { hex, scale, type RGB } from '../../world/biomes';
import type { ThemeKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import type { Sched } from '../nightLights';
import { DARK, GABLES, GLASS_LIGHT, TAU, WARM_GLOW, WHITE, WOOD, gableFace, hoist, pick, win, type Draw, type Kit, type P3 } from './kit';

/**
 * Amsterdam's landmarks, swapped in by the Dutch town style (STYLE_SWAPS in world/towns.ts), which is drawn
 * as Amsterdam's canal houses already (kit.ts STYLES.dutch: brick fronts, white sashes, step, neck and
 * bell gables with their hoist beams). Each stands on its lot centred on the origin, its front to +z.
 *
 * - **Rijksmuseum** (museum): the red-brick palace of art, its two spired towers over the cycle passage
 *   through its middle.
 * - **Centraal Station** (bus station): the long brick front on the water, its two towers, the clock and
 *   the wind vane, the iron and glass train shed behind.
 * - **Westerkerk** (church, cathedral): the brick nave and the tower under the blue and gold imperial crown.
 * - **De Gooyer** (clock tower, observation tower): the tall smock mill on its brick base, sails turning.
 * - **Canal houses** (terrace row): a row of narrow canal houses, every one its own height, colour and
 *   gable, hoist beams under the peaks and bicycles chained along the front.
 */

const BRICK_RED = hex(0x9c4a34), BRICK_DARK = hex(0x7a3628), STONE = hex(0xe8dcc0), SLATE = hex(0x3e4650);
const COPPER = hex(0x5e9e86), GOLD = hex(0xe0b040), CROWN_BLUE = hex(0x2a4a8a), CROWN_RED = hex(0xb8262e);
const FLOOD: Sched = [18, 25.5, 1.2];
/** The colours a canal house is painted when it is not left in brick. */
const PAINTED = [0xf2efe6, 0x3a4a3e, 0x5a6670, 0xe8dcc0, 0x2e3438, 0x8a3a2a];

/** A bicycle standing on the ground at (x, z), along x: two wheels, a frame, a handlebar. */
export function bike(k: Kit, x: number, z: number, col: RGB): void {
  k.face(x - 0.045, 0.035, z, 0.033, DARK, 6);
  k.face(x + 0.045, 0.035, z, 0.033, DARK, 6);
  k.bar([x - 0.045, 0.035, z + 0.002], [x + 0.03, 0.065, z + 0.002], 0.006, col);
  k.bar([x + 0.045, 0.035, z + 0.002], [x + 0.03, 0.075, z + 0.002], 0.005, col);
}

/** A steep slate roof along x over a block, with a row of little dormers on its front slope. */
function slateRoof(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, dormers: number): void {
  k.gable(x, y, z, w, h, d, SLATE, BRICK_RED, false);
  for (let i = 0; i < dormers; i++) {
    const dx = x - w / 2 + (w * (i + 0.5)) / dormers;
    k.box(dx, y + h * 0.18, z + d * 0.22, 0.08, 0.1, 0.08, BRICK_RED);
    k.gable(dx, y + h * 0.18 + 0.1, z + d * 0.22, 0.1, 0.05, 0.1, SLATE, BRICK_RED, true);
  }
}

// ---- the Rijksmuseum ----------------------------------------------------------------------------

const rijksmuseum: Draw = (k, W, D, b, r) => {
  const bw = W - 0.24, bd = D - 0.5, z = -0.05, front = z + bd / 2, H = 0.92;
  k.box(0, 0, z, bw, H, bd, BRICK_RED);
  // stone bands and the windows of the galleries, two rows
  for (const y of [0.3, 0.62]) k.box(0, y, z, bw + 0.02, 0.03, bd + 0.02, STONE);
  for (let i = 0; i < 12; i++) {
    const x = -bw / 2 + 0.15 + ((bw - 0.3) * i) / 11;
    if (Math.abs(x) < 0.32) continue;
    win(k, b, r, x, 0.06, front, 0.09, 0.18, 1, GLASS_LIGHT);
    win(k, b, r, x, 0.38, front, 0.09, 0.2, 1, GLASS_LIGHT);
  }
  slateRoof(k, 0, H, z, bw + 0.04, bd + 0.04, 0.42, 8);
  // the end pavilions, a little taller under their own hips
  for (const s of [-1, 1]) {
    k.box(s * (bw / 2 - 0.22), 0, z + 0.02, 0.44, H + 0.2, bd + 0.06, BRICK_RED);
    k.hip(s * (bw / 2 - 0.22), H + 0.2, z + 0.02, 0.48, 0.34, bd + 0.1, SLATE);
  }
  // the cycle passage through the middle, and the two towers over it with their spires
  k.box(0, 0, front + 0.006, 0.42, 0.3, 0.012, hex(0x2a2420));
  k.box(0, 0.3, front + 0.008, 0.46, 0.04, 0.012, STONE);
  for (const s of [-1, 1]) {
    const tx = s * 0.26, tz = front - 0.14;
    k.box(tx, 0, tz, 0.26, 1.55, 0.26, BRICK_RED);
    k.box(tx, 1.55, tz, 0.3, 0.04, 0.3, STONE);
    win(k, b, r, tx, 1.2, tz + 0.13, 0.08, 0.22, 1, GLASS_LIGHT);
    k.cone(tx, 1.59, tz, 0.19, 0.62, SLATE, 4);
    k.box(tx, 2.21, tz, 0.012, 0.1, 0.012, GOLD);
  }
  k.box(0, H, front - 0.14, 0.3, 0.4, 0.26, BRICK_RED);
  k.gable(0, H + 0.4, front - 0.14, 0.3, 0.2, 0.26, SLATE, BRICK_RED, true);
  // floodlit after dark, and bicycles waiting in front
  k.glowBox(0, 0.02, front + 0.02, bw - 0.1, 0.02, 0.02, STONE, FLOOD, hex(0xffe8c0));
  for (let i = 0; i < 5; i++) bike(k, -0.9 + i * 0.12 + (i > 2 ? 1.3 : 0), D / 2 - 0.12, pick(r, [0x2e2e32, 0x7a2a2a, 0x2a4a6a, 0xe8e4dc]));
};

// ---- Centraal Station ---------------------------------------------------------------------------

const centraalStation: Draw = (k, W, D, b, r) => {
  const bw = W - 0.24, fd = 0.6, fz = D / 2 - 0.15 - fd / 2, front = fz + fd / 2, H = 0.7;
  // the iron and glass train shed behind: arched ribs and a glazed barrel between them
  const sz = fz - fd / 2 - (D - fd - 0.3) / 2, sd = D - fd - 0.3, R = sd / 2;
  const seg = 8, I: P3 = [0, 0, sz];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
    const p = (a: number, x: number): P3 => [x, 0.12 + Math.sin(a) * R * 0.75, sz - Math.cos(a) * R];
    k.quad(p(a0, -bw / 2 + 0.1), p(a0, bw / 2 - 0.1), p(a1, bw / 2 - 0.1), p(a1, -bw / 2 + 0.1), s % 2 ? hex(0x9cb4c0) : hex(0x8aa4b2), I);
  }
  for (let i = 0; i <= 6; i++) {
    const x = -bw / 2 + 0.1 + ((bw - 0.2) * i) / 6;
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
      k.bar([x, 0.12 + Math.sin(a0) * R * 0.75, sz - Math.cos(a0) * R], [x, 0.12 + Math.sin(a1) * R * 0.75, sz - Math.cos(a1) * R], 0.012, hex(0x3a4a44));
    }
  }
  // the brick palace front: two storeys, stone bands, a gabled centre pavilion
  k.box(0, 0, fz, bw, H, fd, BRICK_RED);
  for (const y of [0.24, 0.48]) k.box(0, y, fz, bw + 0.02, 0.025, fd + 0.02, STONE);
  for (let i = 0; i < 18; i++) {
    const x = -bw / 2 + 0.12 + ((bw - 0.24) * i) / 17;
    if (Math.abs(x) < 0.3) continue;
    win(k, b, r, x, 0.05, front, 0.08, 0.16, 1, GLASS_LIGHT);
    win(k, b, r, x, 0.29, front, 0.08, 0.16, 1, GLASS_LIGHT);
  }
  k.gable(0, H, fz, bw, 0.22, fd, SLATE, BRICK_RED, false);
  k.box(0, 0, fz + 0.04, 0.5, H + 0.16, fd + 0.04, BRICK_RED);
  k.gable(0, H + 0.16, fz + 0.04, 0.5, 0.3, fd + 0.04, SLATE, BRICK_RED, true);
  k.glowBox(0, 0.05, front + 0.03, 0.3, 0.3, 0.008, hex(0x6a5a46), [6, 30, 1.3], WARM_GLOW);
  // the two towers: the west one's clock, the east one's wind dial, both under copper lanterns
  for (const s of [-1, 1]) {
    const tx = s * 0.62, tz = fz + 0.02;
    k.box(tx, 0, tz, 0.26, 1.35, 0.26, BRICK_RED);
    k.box(tx, 1.35, tz, 0.3, 0.04, 0.3, STONE);
    k.face(tx, 1.15, tz + 0.135, 0.09, s < 0 ? hex(0xf6f2e2) : hex(0x2a4a6a), 12);
    k.face(tx, 1.15, tz + 0.138, 0.02, GOLD, 6);
    k.cyl(tx, 1.39, tz, 0.1, 0.16, COPPER, 8);
    k.dome(tx, 1.55, tz, 0.1, COPPER, 8, 2);
    k.box(tx, 1.65, tz, 0.012, 0.12, 0.012, GOLD);
  }
  // the forecourt: a tram stop's shelter and racks of bicycles
  for (let i = 0; i < 8; i++) bike(k, -1.4 + i * 0.11, D / 2 - 0.08, pick(r, [0x2e2e32, 0x7a2a2a, 0x2a4a6a, 0xe8e4dc]));
  k.box(1.1, 0.18, D / 2 - 0.08, 0.5, 0.02, 0.1, hex(0x3a4a44));
  for (const sx of [0.88, 1.32]) k.box(sx, 0, D / 2 - 0.08, 0.02, 0.18, 0.02, hex(0x3a4a44));
};

// ---- the Westerkerk -----------------------------------------------------------------------------

const westerkerk: Draw = (k, W, D, b, r) => {
  const nw = Math.min(W - 0.5, 1.2), nd = D - 1.0, nz = -0.35, H = 0.75;
  // the nave and its transepts, tall round-headed windows, steep slate roofs
  k.box(0, 0, nz, nw, H, nd, BRICK_RED);
  k.gable(0, H, nz, nw + 0.04, 0.5, nd + 0.04, SLATE, BRICK_RED, true);
  k.box(0, 0, nz - 0.1, W - 0.3, H, 0.5, BRICK_RED);
  k.gable(0, H, nz - 0.1, W - 0.26, 0.45, 0.54, SLATE, BRICK_RED, false);
  for (let i = 0; i < 4; i++) for (const s of [-1, 1]) win(k, b, r, s * nw / 2, 0.14, nz - nd / 2 + 0.25 + i * (nd - 0.5) / 3, 0.12, 0.4, s > 0 ? 0 : 2, GLASS_LIGHT);
  // the tower at the front: brick, then stone stages narrowing, then the crown
  const tz = nz + nd / 2 + 0.22, tw = 0.5;
  k.box(0, 0, tz, tw, 1.5, tw, BRICK_RED);
  for (const y of [0.5, 1.0, 1.5]) k.box(0, y, tz, tw + 0.03, 0.03, tw + 0.03, STONE);
  win(k, b, r, 0, 1.08, tz + tw / 2, 0.12, 0.32, 1, GLASS_LIGHT);
  k.glowBox(0, 1.53, tz, tw * 0.8, 0.4, tw * 0.8, STONE, FLOOD, hex(0xfff0d0));
  k.face(0, 1.75, tz + tw * 0.4 + 0.004, 0.09, hex(0x2a4a8a), 12);
  k.face(0, 1.75, tz + tw * 0.4 + 0.007, 0.02, GOLD, 6);
  k.cyl(0, 1.93, tz, tw * 0.32, 0.36, STONE, 8);
  k.cyl(0, 2.29, tz, tw * 0.24, 0.24, scale(STONE, 0.94), 8);
  // the imperial crown of Maximilian: a blue cap banded in gold, red between, a gold orb and cross
  k.cyl(0, 2.53, tz, tw * 0.26, 0.04, GOLD, 8);
  k.dome(0, 2.57, tz, tw * 0.25, CROWN_BLUE, 8, 3);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU;
    k.bar([Math.cos(a) * tw * 0.25, 2.57, tz + Math.sin(a) * tw * 0.25], [0, 2.57 + tw * 0.27, tz], 0.012, GOLD);
  }
  k.box(0, 2.57, tz, tw * 0.1, tw * 0.16, tw * 0.1, CROWN_RED);
  k.cyl(0, 2.57 + tw * 0.25, tz, 0.03, 0.05, GOLD, 6);
  k.box(0, 2.67 + tw * 0.25, tz, 0.012, 0.12, 0.012, GOLD);
  k.box(0, 2.73 + tw * 0.25, tz, 0.07, 0.012, 0.012, GOLD);
};

// ---- De Gooyer -----------------------------------------------------------------------------------

const deGooyer: Draw = (k) => {
  // the brick base, an octagon with a stage (the gallery) round its top
  k.cyl(0, 0, 0, 0.36, 0.62, BRICK_DARK, 8);
  k.cyl(0, 0.62, 0, 0.44, 0.03, WOOD, 8);
  k.box(0, 0, 0.35, 0.12, 0.2, 0.04, hex(0x3a2a20));
  // the smock: eight thatched faces tapering to the cap
  const seg = 8, y0 = 0.65, H = 0.95, r0 = 0.3, r1 = 0.17;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.quad([Math.cos(a0) * r0, y0, Math.sin(a0) * r0], [Math.cos(a1) * r0, y0, Math.sin(a1) * r0],
      [Math.cos(a1) * r1, y0 + H, Math.sin(a1) * r1], [Math.cos(a0) * r1, y0 + H, Math.sin(a0) * r1], s % 2 ? hex(0x6a5a44) : hex(0x5e5040), [0, y0 + H / 2, 0]);
  }
  // the cap, the stocks and the sails turning in the wind
  k.gable(0, y0 + H, 0, 0.3, 0.16, 0.4, hex(0x4a4038), hex(0x5a4a3a), true);
  const hub = y0 + H + 0.05;
  k.spin(0, hub, 0.22, 'z', 0.45, (s) => {
    s.cyl(0, -0.03, 0, 0.04, 0.06, DARK, 6);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + 0.4, c = Math.cos(a), sn = Math.sin(a);
      s.bar([0, 0, 0.03], [c * 0.95, sn * 0.95, 0.03], 0.016, WOOD);
      s.bar([c * 0.25 - sn * 0.1, sn * 0.25 + c * 0.1, 0.035], [c * 0.95 - sn * 0.1, sn * 0.95 + c * 0.1, 0.035], 0.012, WHITE);
      for (let j = 0; j < 4; j++) {
        const f = 0.32 + j * 0.18;
        s.bar([c * f, sn * f, 0.035], [c * f - sn * 0.1, sn * f + c * 0.1, 0.035], 0.006, WHITE);
      }
    }
  });
  // a lamp at the door: the mill is a brewery's tap room now
  k.glowBox(0.12, 0.22, 0.37, 0.03, 0.05, 0.03, DARK, [16.5, 23.5, 1.6], WARM_GLOW);
};

// ---- a row of canal houses ------------------------------------------------------------------------

const canalHouses: Draw = (k, W, D, b, r) => {
  const d = Math.min(0.78, D - 0.22), front = D / 2 - 0.12, z = front - d / 2;
  const n = Math.max(2, Math.round((W - 0.1) / 0.36)), hw = (W - 0.1) / n;
  const base = Math.max(3, b.floors + 1);
  for (let i = 0; i < n; i++) {
    const x = -(W - 0.1) / 2 + hw * (i + 0.5);
    const floors = base + Math.floor(r() * 2);
    const h = floors * FLOOR * 0.92 + 0.04, w = hw - 0.012;
    const brickHouse = r() < 0.7, wall = brickHouse ? pick(r, [0x8a3a2a, 0x7a3326, 0x9c4a34, 0x5a3228, 0x6e2e26, 0x4a3a34, 0xa85a3e]) : pick(r, PAINTED);
    const trim = hex(0xf6f4ee), roof = pick(r, [0x3a3634, 0x2e2c2e, 0x4a4442, 0x9a4a34]);
    k.box(x, 0, z, w, h, d, wall);
    // a stoop up to the door, the door, the windows two to a floor in white frames
    k.box(x - w * 0.22, 0, front + 0.03, w * 0.34, 0.05, 0.06, hex(0x8a8478));
    k.box(x - w * 0.22, 0.05, front + 0.004, w * 0.26, 0.17, 0.008, pick(r, [0x2f4d3a, 0x1f2a30, 0x6e2a22, 0x2f4a6a]));
    win(k, b, r, x + w * 0.2, 0.07, front, w * 0.3, 0.13, 1);
    for (let f = 1; f < floors; f++) {
      const y = f * FLOOR * 0.92 + 0.05;
      for (const sx of [-0.22, 0.22]) win(k, b, r, x + sx * w, y, front, w * 0.3, 0.14, 1);
    }
    // the gable, the roof running back from it, the hoist beam under its peak
    const kind = GABLES[Math.floor(r() * GABLES.length)], gh = Math.min(0.42, w * 1.15);
    k.gable(x, h, z, w, gh * 0.9, d, roof, wall, true);
    gableFace(k, x, h, front + 0.012, w + 0.01, gh, wall, trim, kind, true, 1);
    hoist(k, x, h + gh * 0.72, front + 0.012, true, 1);
  }
  // bicycles chained to the railings along the front
  const nb = 1 + Math.floor(r() * 3);
  for (let i = 0; i < nb; i++) bike(k, -W / 2 + 0.3 + r() * (W - 0.6), D / 2 - 0.035, pick(r, [0x2e2e32, 0x7a2a2a, 0x2a4a6a, 0xe8e4dc, 0x3a6a3a]));
};

export const AMSTERDAM_DRAW = { rijksmuseum, centraalStation, westerkerk, deGooyer, canalHouses } satisfies Partial<Record<ThemeKind, Draw>>;
