/** Milliseconds a frame may spend building new chunks. */
const BUILD_BUDGET = 4;
/**
 * The same while the camera waits on a far county with the loading card up (game/travelLoading.ts): there is
 * nothing else to see, and fewer, longer frames draw a city county in about a third of the time (each frame's
 * own cost is paid fewer times: 10 s → 3 s, 28 Oct 2026).
 */
const TRAVEL_BUDGET = 60;
/** How near an island must be for its traffic and its people to be about. */
const ALIVE = 130;
/**
 * The fleet's working cells kept in memory with traffic (Fleet.workCells), besides the 3 × 3 round the player:
 * however far off they are, since a driver at work stays at its base (game/convoy.ts), but no more than
 * WORK_CELLS of them, nearest first. Those away from the player and the camera are kept light (docs/farfleet.html):
 * the county's data to drive in and nothing drawn, so there can be four times as many as when each was drawn.
 */
const WORK_CELLS = 16;
/**
 * A county let go with the fleet's drivers still at work in it winds down first (docs/farfleet.html): this many seconds
 * of play at most, at the usual speed (the user, 4 Nov 2026: no delivery is ever hurried along).
 */
const DRAIN_MAX = 60;
/** WORK_CELLS, or less for a test (pr.farfleet.cap). */
let workCap = WORK_CELLS;
/** How near an island must be for goods to turn up on it. */
const TRADING = 260;
/** Counties either way of a flier that are surveyed for airports to show codes over. */
const AIR_REACH = 4;
/** How near a unit of the fleet must pass for the map to count a place as found, in tiles: as near as the player. */
const FLEET_SIGHT = SIGHT;
/** How often the game writes itself down, in seconds. */
const AUTOSAVE = 20;
/**
 * CPU vehicles on the island the player is on, on a megalopolis island, and on the ones nearby: doubled
 * once cars shared their bodies and wore a merged far body when small (render/vehicleMeshes.ts).
 */
const TRAFFIC_HOME = 40, TRAFFIC_MEGA = 70, TRAFFIC_AWAY = 14;

// A see-through double-sided material is drawn in two passes by default, back faces then front, and
// three flags the material changed (needsUpdate) twice per object per frame to do it, so every such
// draw looked its shader program up again. Every overlay here is flat or additive, where one pass
// looks the same: force it for every material, made now or later.
Object.defineProperty(THREE.Material.prototype, 'forceSinglePass', { configurable: true, get: () => true, set: () => { /* always one pass */ } });

// WebGL drawn on the processor (graphics acceleration off, a blocked card, no driver): a card says how to
// turn the graphics card on for this browser (title/gpuCard.ts), counted on the developer's page
gpuCheck((kind) => {
  try { if (/^https?:$/.test(location.protocol)) navigator.sendBeacon?.('/api/visit', new Blob([JSON.stringify({ kind })], { type: 'text/plain' })); } catch { /* only a count */ }
});
// a copy too old for the online world says so at once, and how to update (title/updateCard.ts)
void updateCheck();
const canvas = document.getElementById('game') as HTMLCanvasElement;
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
// counted over the whole frame (shadows, the scene, the tilt-shift passes), reset in frame(): the play reports' draw calls
renderer.info.autoReset = false;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
// checking each program's link log makes its first use wait for the driver to finish it (a 340 ms frame
// in the Oct 2026 playtest): only worth it while developing
renderer.debug.checkShaderErrors = import.meta.env.DEV;
renderer.toneMapping = THREE.NeutralToneMapping;
renderer.toneMappingExposure = 1.05;

const scene = new THREE.Scene();
/** The film's line-of-sight probe (a tracked vehicle hidden behind a tree fails the take). */
const filmRay = new THREE.Raycaster();
/**
 * The film's front of a moving train: of its two end cars, the one furthest along the way the middle has moved since
 * last asked (a train turned back at a station runs last car first; the crop sat on its tail, the user, 7 Nov 2026).
 */
const filmFronts = new WeakMap<object, { x: number; z: number; end: number }>();
function trainFront(t: Train, mid: { x: number; z: number } | null): THREE.Object3D | undefined {
  const a = t.cars[0]?.mesh?.group, b = t.cars[t.cars.length - 1]?.mesh?.group;
  if (!a || !b || a === b || !mid) return a;
  const was = filmFronts.get(t);
  let end = was?.end ?? (t.flipped ? 1 : 0);
  if (was) {
    const mx = mid.x - was.x, mz = mid.z - was.z;
    if (Math.hypot(mx, mz) > 0.05) {
      const pa = a.getWorldPosition(new THREE.Vector3()), pb = b.getWorldPosition(new THREE.Vector3());
      end = (pa.x - mid.x) * mx + (pa.z - mid.z) * mz >= (pb.x - mid.x) * mx + (pb.z - mid.z) * mz ? 0 : 1;
    }
  }
  if (!was || end !== was.end || Math.hypot(mid.x - was.x, mid.z - was.z) > 0.05) filmFronts.set(t, { x: mid.x, z: mid.z, end });
  return end ? b : a;
}
const camera = new THREE.PerspectiveCamera(18, window.innerWidth / window.innerHeight, 2, 1600);
const sky = new DayNight(scene, renderer);
/** Weather: the biome under the player bends the sky, the fog and the ground (render/weather.ts). */
const weather = new Weather(scene);
// a lightning flash in a thunderstorm: the thunder rolls in a beat later (game/sfx.ts)
weather.onLightning = (near) => { if (mode === 'play') sfx.thunder(near); };
/** One real light for the player's headlamps; everything else that glows is emissive. */
const headlight = new THREE.SpotLight(0xfff2d6, 0, 9, 0.55, 0.6, 1.2);
scene.add(headlight, headlight.target);
/** A helicopter's searchlight after dark, aimed with the mouse; N switches it off and on. */
const heliSpot = new HeliSpot(scene);
/** Advertising banners towed behind Barnstormers (0.7.0): the player's and hired pilots' with the workshop part, and the odd CPU one. */
const banners = new Banners(scene);
// the banner's line in the controls help, in the world that has banners
if (NEXT_WORLD) document.getElementById('ctl-banner')?.removeAttribute('hidden');
const lighthouseBeams = new LighthouseBeams(scene);
let spotOn = true;
const post = createTiltShift(renderer, scene, camera);
const input = new Input(canvas);
// the first road's car (render/firstRoad.ts) drives from the same keys while a new player's world loads
loadingShow.keys = input;
const hud = new Hud();
/**
 * The camera mode (docs/postcards.html, phase 1): C online or the 📷 button. Stills and clips of the
 * game's own canvas with the fleet's mark and the game's address on them, for the player to post.
 */
/** The camera mode's pan, as an offset from what the camera is on, and the scratch vectors it is worked out in. */
