/** A town's property, while its island is in memory: every lot's assessment today, and who owns what. */
const propCache = new Map<string, { at: string; p: Property }>();
function townProperty(key: string): Property | null {
  const [cell, id] = key.split('#');
  const [cx, cz] = cell.split(',').map(Number);
  const w = islands?.at(cx, cz);
  const t = w?.towns[Number(id)];
  if (!w || !t || townKey(w, t) !== key) return null;
  const at = `${Math.floor(economy.hours)}|${estate.deeds.size}|${w.revision}`;
  const have = propCache.get(key);
  if (have && have.at === at) return have.p;
  const by = new Map<string, number>();
  let total = 0;
  const rate = (lk: string) => { const l = economy.lots.get(lk); return l ? l.rate * 0.5 ** (Math.max(0, economy.hours - l.at) / ECONOMY.rateHalfLife) : 0; };
  const count = (lk: string, v: number) => {
    total += v;
    const who = estate.deeds.has(lk) ? YOU : online.ownerOf(lk) || (firms.ownerOf(lk)?.id ?? '');
    if (who) by.set(who, (by.get(who) ?? 0) + v);
  };
  const inPorts = new Set(w.ports.flatMap((q) => q.buildings));
  for (const b of t.buildings) {
    if (b.gone || b.uid < 0 || inPorts.has(b)) continue;
    const lk = `${w.cx},${w.cz}#b${b.uid}`;
    count(lk, lotPrice(rate(lk), lotFloor(b), t.kind, !!b.derelict, 0));
  }
  for (const q of w.ports) {
    if (q.town !== t.id) continue;
    const lk = `${w.cx},${w.cz}#p${q.id}`;
    count(lk, lotPrice(rate(lk), q.buildings.filter((b) => !b.gone).reduce((a, b) => a + lotFloor(b), 0), null, false, 0));
  }
  // the airports it serves (world/airportTowns.ts): each building a lot of the town's
  for (const g of airportsOf(w, t)) {
    for (const b of g.buildings) {
      if (b.gone || b.uid < 0) continue;
      const lk = `${w.cx},${w.cz}#b${b.uid}`;
      count(lk, lotPrice(rate(lk), lotFloor(b), t.kind, !!b.derelict, 0));
    }
  }
  const p = { total, by };
  propCache.set(key, { at, p });
  return p;
}

/** A town's kind: from the island in memory, else what the atlas knows of it. */
function townKindOf(key: string): TownKind | null {
  const [cell, id] = key.split('#');
  const [cx, cz] = cell.split(',').map(Number);
  const t = islands?.at(cx, cz)?.towns[Number(id)];
  return t ? t.kind : ((atlas.place(key)?.kind as TownKind | undefined) ?? null);
}

