const RAIL_GHOST = { player: true, prefer: 0 } as Train;
const railA = { x: 0, y: 0, z: 0, ang: 0 }, railB = { x: 0, y: 0, z: 0, ang: 0 };
online.remotes.railBehind = (x, z, h, len, rack) => {
  const near = trains.net.nearest(x, z, 1.5, rack);
  if (!near) return null;
  const { t, s } = near.loc;
  sampleAt(t, Math.max(0, s - 0.3), railA);
  sampleAt(t, Math.min(t.p.length, s + 0.3), railB);
  // the way along the track that runs off behind the engine
  const dir = Math.sin(h) * (railB.x - railA.x) + Math.cos(h) * (railB.z - railA.z) > 0 ? -1 : 1;
  const out: { x: number; y: number; z: number }[] = [];
  trains.walk({ t, s, dir }, len, RAIL_GHOST, (tk, s0, s1) => {
    const n = Math.max(1, Math.ceil(Math.abs(s1 - s0) / 0.4));
    for (let q = out.length ? 1 : 0; q <= n; q++) { sampleAt(tk, s0 + ((s1 - s0) * q) / n, railA); out.push({ x: railA.x, y: railA.y, z: railA.z }); }
    return false;
  });
  return out.length ? out : null;
};
