/** A town is asking: the mayor writes, and the card takes it on or sends the player to the board. */
function askCard(r: Request): void {
  mayor.ask({
    town: r.town, title: r.title, line: r.line,
    steps: r.steps.map((s) => `${s.note} · ${s.type.name} · ${s.from.name} → ${s.to.name}`),
    reward: r.reward, effectLine: r.effectLine,
    whyNot: requests.whyNot(r),
    accept: () => {
      if (requests.whyNot(r)) { board.open(); return; }
      const why = requests.accept(r);
      if (why) { hud.announce(r.title, why); board.open(); return; }
      showChain(r);
    },
  });
}

/** The purse on the last drop: the money to the player, and the same again on the town's own books. */
function payChain(r: Request, purse: number): void {
  wallet.earn(purse, 'other');
  cargoHud.setCash(wallet.cash);
  const paid = r.steps.reduce((s, q) => s + q.value, 0);
  const w = islands?.at(r.cell[0], r.cell[1]) ?? null;
  const t = w?.towns[r.townId];
  if (w && t) economy.creditChain(w, t, paid + purse);
  if (veh && home) cargoHud.float(`+${money(purse)} ${r.title}`, new THREE.Vector3(home.ox + veh.x, veh.y + 0.7, home.oz + veh.z), 'cash');
  deeds.add('chains');
  deeds.mark('helped', `${r.cell[0]},${r.cell[1]}#${r.townId}`);
}

/** What the chain promised the town, done by the town's own rules. False when it could not be. */
function chainEffect(r: Request): boolean {
  const w = islands?.at(r.cell[0], r.cell[1]) ?? null;
  const t = w?.towns[r.townId];
  if (!w || !t) return false;
  switch (r.effect) {
    case 'mend': return economy.mendOne(w, t);
    case 'civic': return economy.growNow(w, t);
    case 'levy': return economy.easeLevy(w, t);
    case 'graduate': {
      const did = economy.graduateNow(w, t);
      if (did) deeds.add('civicPride');
      return did;
    }
    default: {
      // a week of the town's own trade, credited at once
      economy.creditChain(w, t, ECONOMY.norm[t.kind] * 24);
      return true;
    }
  }
}

/** Show me: the camera goes to the step's goods, and the world streams in around them. */
function showChain(r: Request): void {
  const s = r.steps[r.step];
  if (!s) return;
  const it = s.item;
  const x = it ? it.x : s.from.x, z = it ? it.z : s.from.z;
  debug.look(x, z);
  hud.announce(`${r.title} · step ${r.step + 1} of ${r.steps.length}`, `${s.note} · ${s.type.name} at ${s.from.name} → ${s.to.name}`);
}
