/** The driven car's counts of boost pads, take-offs and landings last seen, so each new one is answered once (world/jumps.ts). */
const jumpSeen = { car: null as CarState | null, pads: 0, launches: 0, landings: 0 };
/** A boost pad's whoosh and shove, a jump's roar off the lip and its slam on landing, and the trail between. */
function jumpFx(car: CarState, def: VehicleDef, dt: number): void {
  if (jumpSeen.car !== car) Object.assign(jumpSeen, { car, pads: car.pads, launches: car.launches, landings: car.landings });
  const fx = Math.sin(car.heading), fz = Math.cos(car.heading);
  if (car.pads > jumpSeen.pads) {
    deeds.add('padsHit', car.pads - jumpSeen.pads);
    sfx.whoosh(false);
    pad.rumble(0.45);
    // the car leaps away from the camera, which is left a beat behind
    followCam.kick(-fx, -fz, 0.55, false);
  }
  if (car.launches > jumpSeen.launches) {
    sfx.whoosh(true);
    pad.rumble(0.6);
    followCam.kick(-fx, -fz, 0.7, false);
  }
  if (car.landings > jumpSeen.landings) {
    deeds.add('jumpsLanded', car.landings - jumpSeen.landings);
    // the longest, for the world's Longest Jump record (shared/records.ts)
    deeds.best('longestJump', Math.round(car.lastJump * 10));
    // (the knock itself comes as a soft impact: the dust, the thump and the jolt)
    sfx.knock(0.35 + 0.6 * car.landHit);
    pad.rumble(0.5 + 0.5 * car.landHit);
    followCam.kick(0, 0, 0.4 + 0.8 * car.landHit, true);
  }
  jumpSeen.pads = car.pads;
  jumpSeen.launches = car.launches;
  jumpSeen.landings = car.landings;
  if (car.air || car.surge > 0.25) impactFx.flame(car, halfSize(def)[0], dt);
}
