/** Every ten seconds: a fetcher with none of its kind about gets one made near it (one at a time). */
function fetchTick(dt: number): void {
  fetchLook -= dt;
  if (fetchLook > 0) return;
  fetchLook = 10;
  for (const u of fleet.units) {
    const f = u.order.fetch, a = u.agent;
    if (!f || !a) continue;
    if (!estate.deeds.has(f.key)) { fleet.setFetch(u.uid, null); continue; }
    const x = a.w.ox + a.state.x, z = a.w.oz + a.state.z;
    const last = fetchMade.get(u.uid);
    if (last !== undefined && cargo.whereIs(last) === 'ground') continue;
    if (cargo.items.some((it) => f.ids.includes(it.type.id) && Math.hypot(it.x - x, it.z - z) <= 60 && (!it.claimedBy || it.claimedBy === -u.uid))) continue;
    const t = cargoById(f.ids[Math.floor(Math.random() * f.ids.length)]);
    const it = t && !t.madeOnly ? cargo.spawn(t, { x, z }, [{ x, z }]) : null;
    // made for the fleet: the island's own haulers leave it (cargo.openJobs)
    if (it) { it.for = 'fleet'; fetchMade.set(u.uid, it.id); }
  }
}
