/** A town in memory, by key. */
function liveTown(key: string): { w: World; t: Town } | null {
  const [cellK, id] = key.split('#');
  const [cx, cz] = cellK.split(',').map(Number);
  const w = islands?.at(cx, cz);
  const t = w?.towns[Number(id)];
  return w && t && townKey(w, t) === key ? { w, t } : null;
}
