/**
 * The league round the nearest stadium within the paper's reach: its last finished season's table, the home
 * club's place, and whether the home club won it (the Sport box, and the champions' story).
 */
function pressSport(): SportNow | null {
  if (!islands || !home || !veh) return null;
  const px = home.ox + veh.x, pz = home.oz + veh.z;
  let best: { w: World; b: Building; d: number } | null = null;
  for (const w of islands.live.values()) {
    for (const b of w.allBuildings) {
      if (b.kind !== 'stadium' || b.gone) continue;
      const d = Math.hypot(w.ox + b.x + b.w / 2 - px, w.oz + b.z + b.d / 2 - pz);
      if (d <= LOCAL && (!best || d < best.d)) best = { w, b, d };
    }
  }
  if (!best) return null;
  const { L, slot } = stadiums.leagueOf(best.w, best.b);
  const now = sky.days * 24 + sky.hour;
  const at = leagueSeason(L.sport, now);
  const k = at.inSeason ? at.k - 1 : at.k;
  if (k < L.founded) return null;
  const table = finalTable(L, k, stadiums.overrides);
  if (!table.length) return null;
  const name = (club: number) => stadiums.clubTeam(L, club).name;
  const pos = table.findIndex((r) => r.club === slot);
  return {
    league: L.name, season: seasonLabel(L, k), ended: seasonEnd(L.sport, k),
    rows: table.slice(0, 3).map((r) => ({ name: name(r.club), rec: recordText(L.sport, r), pts: r.pts })),
    ...(pos >= 3 ? { home: { name: name(slot), pos: pos + 1, of: table.length } } : {}),
    homeWon: pos === 0, margin: table[1] ? table[0].pts - table[1].pts : 0,
  };
}

/** A big building has topped out (an Institution or grander, docs/hq.html): the town's news. */
function pressBuilt(w: World, b: Building): void {
  if (gradeOf(b).grade < 4 && b.kind !== 'stadium') return;
  const t = w.towns.find((q) => q.buildings.includes(b));
  if (!t) return;
  press.write({ k: 'built', town: keyOf(w, t), at: buildingAt(w, b), f: { town: t.name, building: plain(buildingLabel(b)) }, pic: buildingPic(w, b, t.style) });
}

/** A still of the frame just drawn, small, for the paper (base64 JPEG, no prefix); null when there is nothing drawn. */
const stillCanvas = document.createElement('canvas');
function frameStill(side = 360): string | null {
  const src = renderer.domElement;
  if (src.width < 8 || src.height < 8) return null;
  const k = side / Math.max(src.width, src.height);
  stillCanvas.width = Math.round(src.width * k);
  stillCanvas.height = Math.round(src.height * k);
  stillCanvas.getContext('2d')!.drawImage(src, 0, 0, stillCanvas.width, stillCanvas.height);
  const url = stillCanvas.toDataURL('image/jpeg', 0.55);
  return url.startsWith('data:image/jpeg;base64,') ? url.slice(23) : null;
}

/** Towns' moods as last seen, and when each was last in the paper, for the turning-fortunes story. */
const moodSeen = new Map<string, string>();
const moodNews = new Map<string, number>();
let moodHour = -1;
/** Once a game hour: a town near the player that has started thriving, or started struggling, is news. */
function watchMoods(): void {
  const hour = Math.floor(sky.days * 24 + sky.hour);
  if (hour === moodHour || !islands || !home || !veh) return;
  moodHour = hour;
  const px = home.ox + veh.x, pz = home.oz + veh.z;
  for (const w of islands.live.values()) {
    for (const t of w.towns) {
      const at = townAt(w, t);
      if (Math.hypot(at.x - px, at.z - pz) > LOCAL) continue;
      const key = keyOf(w, t), mood = economy.mood(w, t), was = moodSeen.get(key);
      moodSeen.set(key, mood);
      if (!was || was === mood || hour - (moodNews.get(key) ?? -1e9) < 48) continue;
      const v = mood === 'Thriving' ? 'up' : mood === 'Struggling' ? 'down' : '';
      if (!v) continue;
      moodNews.set(key, hour);
      press.write({ k: 'mood', v, town: key, at, f: { town: t.name } });
    }
  }
}

