protestNews.on = (w, t, b, n) => {
  if (mode !== 'play') return;
  const key = keyOf(w, t);
  const causes: string[] = [];
  const book = economy.towns.get(key);
  if (book?.tax) causes.push(`the levy of ${book.tax}%`);
  if (economy.mood(w, t) === 'Struggling') causes.push('hard times on the high street');
  const down = t.buildings.filter((q) => q.derelict && !q.gone).length;
  if (down >= 2) causes.push(`${down} boarded-up buildings`);
  const holder = economy.carriage.preferred(key);
  if (holder) {
    const name = holder === YOU ? fleet.brand?.name ?? '' : firms.firms.get(holder)?.name ?? '';
    if (name) causes.push(`${/s$/i.test(name) ? `${name}’` : `${name}’s`} hold on the town’s trade`);
  }
  if (!causes.length) causes.push(b.kind === 'police' ? 'policing in the town' : 'the running of the town');
  const cause = causes[hashString(`${key}|${Math.floor(sky.days)}`) % causes.length];
  press.write({ k: 'protest', town: key, at: buildingAt(w, b), f: { town: t.name, n, to: b.kind === 'police' ? 'police station' : 'city hall', cause } });
};

