const ownedRects = new Map<string, { cx: number; cz: number; x: number; z: number; w: number; d: number }[]>();
function rectsOf(key: string, at?: { x: number; z: number }): { cx: number; cz: number; x: number; z: number; w: number; d: number }[] {
  const r = estate.resolve(key);
  if (r) ownedRects.set(key, r.all.map((b) => ({ cx: r.w.cx, cz: r.w.cz, x: b.x, z: b.z, w: b.w, d: b.d })));
  const have = ownedRects.get(key);
  if (have) return have;
  const m = /^(-?\d+),(-?\d+)#/.exec(key);
  // never seen in memory this session: a point at the deed's middle, which the box over it still contains
  return m && at ? [{ cx: Number(m[1]), cz: Number(m[2]), x: at.x - 0.5, z: at.z - 0.5, w: 1, d: 1 }] : [];
}
