regionView.fleetPaths = () => {
  const out: FleetPath[] = [];
  for (const a of alive.values()) {
    for (const g of a.traffic.agents) {
      if (!g.owner || g.firm) continue;
      const pts = [{ x: g.w.ox + g.state.x, z: g.w.oz + g.state.z }];
      for (let k = g.wp; k < g.path.length; k++) pts.push({ x: g.w.ox + g.path[k].x + 0.5, z: g.w.oz + g.path[k].z + 0.5 });
      const stops = g.run ? g.run.stops.slice(g.run.k).map(stopAt) : pts.length > 1 ? [pts[pts.length - 1]] : [];
      out.push({ pts, stops });
    }
  }
  // the crewed trains: the beat each works, end to end, with its stations as the stops
  for (const { tr } of railCrew.list()) {
    const b = tr.crew?.beat;
    if (b) out.push({ pts: b.line, stops: b.stops.map((s) => { const p = sampleAt(s.t, s.s, { x: 0, y: 0, z: 0, ang: 0 }); return { x: p.x, z: p.z }; }) });
  }
  // a far run: the way to the far station (or back), from the plan
  for (const u of railCrew.farUnits()) {
    const pts = railCrew.farLineOf(u);
    if (pts && pts.length > 1) out.push({ pts, stops: [pts[pts.length - 1]] });
  }
  // the hired jets: from where each is, along what is left of its taxi route, to the airport (or the point
  // overseas) it is bound for, with its loads' destinations as the stops
  for (const { f, aboard } of jetPilots?.flights() ?? []) {
    const pts = [{ x: f.st.x, z: f.st.z }, ...f.path.map((p) => ({ x: p.x, z: p.z }))];
    const g = f.goal, to = g.kind === 'overseas' ? { x: g.x, z: g.z } : (g.r === f.rw ? g.r.stands[f.stand] : undefined) ?? g.r.stands[0];
    // on the stand it was bound for there is nowhere left to go: no line
    if (Math.hypot(to.x - f.st.x, to.z - f.st.z) > 1.5) pts.push({ x: to.x, z: to.z });
    const stops = aboard.map((it) => ({ x: it.to.x, z: it.to.z }));
    if (!stops.length && pts.length > 1) stops.push(pts[pts.length - 1]);
    out.push({ pts, stops });
  }
  // the player: the arrows' way when they are up, and wherever what is aboard (or the tracked mission) is going
  if (home && veh) {
    const me = globalRider();
    const laid = autoPath.laid();
    const pts = laid ? [me, ...laid] : [me];
    const stops: { x: number; z: number }[] = cargo.hold.map((it) => ({ x: it.to.x, z: it.to.z }));
    if (autoPath.pin) stops.push({ x: autoPath.pin.x, z: autoPath.pin.z });
    const tm = missions.ms.tracked, at = tm ? missions.ms.target(tm) : null;
    if (at) stops.push({ x: at.x, z: at.z });
    out.push({ pts, stops });
  }
  return out;
};
