builder.onBuilt = (w, type, nodes, bridges) => {
  // a bridge to the next county over the strait: its near half ends on the platform at the line (Across the Strait)
  if ((bridges ?? []).some((b) => b.level && b.from === nodes.length - 1)) deeds.add('straits');
  // into the books' count of roads built (Home's Roads & bridges tile)
  books.road(Math.max(0, nodes.length - 1), (bridges ?? []).filter((b) => !b.tunnel).length, (bridges ?? []).filter((b) => b.tunnel).length);
  // and a teaching mission's road tiles (game/coach.ts)
  missions.made('road', nodes.length);
  // and its bridge: a deck standing over water (not a tunnel), where it stands. One raised for boats to pass under
  // counts (the user, 28 Oct 2026: every span over 4+ tiles of water is raised, so a lake bridge never counted)
  let spanned = false;
  for (const b of bridges ?? []) {
    if (b.tunnel) continue;
    const span = nodes.slice(b.from, b.to + 1);
    if (!span.some((i) => i >= 0 && i < N * N && w.water[i] >= 0)) continue;
    const mid = span[span.length >> 1];
    missions.made('bridge', 1, { x: w.ox + (mid % N) + 0.5, z: w.oz + Math.floor(mid / N) + 0.5, cell: [w.cx, w.cz] });
    spanned = true;
  }
  // shallows a foot deep are paved straight through, a ford with no deck: across the water all the same, so it
  // counts (the user, 29 Oct 2026: a lesson's river was a ford and "Build the bridge" never ticked)
  const wet = spanned ? [] : nodes.filter((i) => i >= 0 && i < N * N && w.water[i] >= 0);
  if (wet.length) {
    const mid = wet[wet.length >> 1];
    missions.made('bridge', 1, { x: w.ox + (mid % N) + 0.5, z: w.oz + Math.floor(mid / N) + 0.5, cell: [w.cx, w.cz] });
  }
  if (!islands) return;
  noteRoad(islands.delta(w.cx, w.cz), type, nodes, bridges);
};
// a road cut down a ledge re-shapes the ground under it (world/roadGrade.ts): redrawn, and saved and sent as the land tool's is
builder.onGround = (w, cut) => {
  // with a ring round it, so a neighbour draws the new cliff face beside the cutting
  const tiles = ringOf(cut);
  w.revision++;
  stream.refreshGround(w, tiles);
  if (w === home) afterDemolition(tiles); else afterWorldChange(w, tiles);
  stream.rebuildLod(w, tiles);
  if (!islands) return;
  const land = encodeLand(w), d = islands.delta(w.cx, w.cz);
  if (land) d.land = land; else delete d.land;
  online.landEdited(w, land);
};
builder.onUndone = (w) => { if (islands) forgetLastRoad(islands.delta(w.cx, w.cz)); };
// track and stations laid from the builder's Rails side (world/railBuild.ts): saved in the cell's delta and sent online
// with it; the network, the ballast index and the chunks notice the new list of paths on their own
/** On the Line (game/railLinks.ts): each town with no station of the world's that a station of yours puts on its railways. */
const noteLinks = () => { if (islands) for (const k of linkedTowns([...islands.live.values()])) deeds.mark('townsLinked', k); };
builder.rails.onRail = (w, spec) => { if (islands) noteRail(islands.delta(w.cx, w.cz), spec); noteLinks(); };
builder.rails.onStation = (w, spec) => { if (islands) noteStation(islands.delta(w.cx, w.cz), spec); deeds.add('stationsBuilt'); noteLinks(); };
// Online the track has gone to the server already, which keeps every edit: forgetting it here only left it in the
// server's log, back on the next load with every later track one place out in the county's list (the user, 6 Nov
// 2026: a player's whole network gone after the update). So online it is bulldozed, an edit the server keeps too.
builder.rails.onUndone = (w, at) => {
  if (!islands) return;
  const d = islands.delta(w.cx, w.cz);
  if (online.active && at) noteRaze(d, at.x, at.z); else forgetLastRail(d);
};
// the rail lesson's steps (game/coach.ts): track laid, and a track laid beside a line
builder.rails.onLaid = (tiles, parallel, junctions) => {
  missions.made('rail', tiles);
  if (parallel) missions.made('railParallel', 1);
  // the deeds: Platelayer, Double Track, Junction Box
  deeds.add('trackTiles', tiles);
  if (parallel) deeds.add('parallelTracks');
  if (junctions) deeds.add('junctions', junctions);
};

// a boost pad laid, turned or taken up (the builder's K mode): saved in the cell's delta, and sent online with it
builder.onPad = (w, i, d) => { if (islands) notePad(islands.delta(w.cx, w.cz), i, d); };
// scenery placed or taken up (the builder's Scenery side, world/scenery.ts): saved in the cell's delta and sent online
builder.scenery = {
  onProp: (w, x, z, p, r) => { if (islands) noteProp(islands.delta(w.cx, w.cz), x, z, p, r); },
  ghost: (id) => sceneryGhost(propGeos, id),
  icon: (id) => sceneryIcon(propGeos, id),
  mine: (by) => !by || !online.active || by === online.me?.id || online.crew.ours(by),
  owner: (by) => online.fleetName(by),
  // the Folly collection (the Passport's Buildings seal): stamped building kinds as scenery
  ...follyHooks(() => rewards.has('kind')),
};
// online a road is under everyone's wheels the moment it is laid: there is no taking it back, only bulldozing it
builder.undoBarred = () => (online.active ? 'Online, a road you lay is everyone’s at once: bulldoze it (X) instead.' : null);
dozer.ownedCost = (w, b) => estate.owns(w, b)?.paid ?? null;
// a site of the fleet's own still going up refunds on clearing (docs/blueprints.html): all in the first ten seconds, half after
dozer.onBuildingGone = (w, b) => estate.razed(w, b, blueprints.cancelled(w, b));
dozer.refundOf = (w, b) => blueprints.refund(w, b)?.amount ?? null;
// nobody bulldozes a building another player owns
/** Online, a track or station another fleet laid is theirs alone to take up (world/railBuild.ts: the server stamps who). */
const railBarred = (by: string | undefined): string | null =>
  by && online.active && by !== online.me?.id && !online.crew.ours(by) ? `Laid by ${online.fleetName(by)}: only they can take it up` : null;
dozer.barred = (w, b) => {
  const who = online.ownerOf(estate.keyOf(w, b));
  if (who) return `Owned by ${online.fleetName(who)}: it isn’t yours to clear`;
  return railBarred(w.stations.find((st) => st.building === b)?.by);
};
// a road or bridge other players have listed with their hearts is its builder's alone to clear (docs/community.html)
dozer.barredTile = (w, tile) => community.barred(w, tile) ?? railBarred(builtRailAt(w, (tile % N) + 0.5, Math.floor(tile / N) + 0.5)?.path.by);

dozer.onRazed = (x, z, gone) => {
  if (!islands || !home) return;
  const d = islands.delta(home.cx, home.cz);
  noteRaze(d, x, z);
  // online, the server is told which door the tile belonged to, so it can refuse one that was just bought
  if (online.active && gone) (d.edits[d.edits.length - 1] as { lot?: string }).lot = estate.keyOf(home, gone);
};
// earthworks: what sits on the ground, a quick redraw under the drag, everything else once a stroke is done, and the save
earth.occupied = (w) => {
  const out = new Set<number>();
  const mark = (x: number, z: number) => { for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) { const tx = Math.floor(x + dx * 0.6), tz = Math.floor(z + dz * 0.6); if (tx >= 0 && tz >= 0 && tx < N && tz < N) out.add(tz * N + tx); } };
  if (veh && w === home) mark(veh.x, veh.z);
  for (const a of alive.get(w)?.traffic.agents ?? []) mark(a.state.x, a.state.z);
  return out;
};
// the earthworks reach over the border into any county in memory (the user, 5 Nov 2026)
earth.worldAt = (cx, cz) => islands?.at(cx, cz) ?? null;
earth.onGround = (w, tiles) => stream.refreshGround(w, tiles);
earth.onStroke = (w, tiles) => { if (w === home) afterDemolition(tiles); else afterWorldChange(w, tiles); stream.rebuildLod(w, tiles); };
earth.onLand = (w, land) => { if (!islands) return; const d = islands.delta(w.cx, w.cz); if (land) d.land = land; else delete d.land; online.landEdited(w, land); };
// a town the fleet holds as territory, weak or strong, is its to grade (round its buildings); not while another fleet contests it
earth.ownsTown = (w, id) => { const t = w.towns[id]; if (!t) return false; const s = territory.status(townKey(w, t)); return s.who === YOU && !s.contested; };

/**
 * A vehicle state for def at (x, z) on island w: placed where it can exist, or for a train, put on the
 * nearest track within reach and pointed toward the nearest station. Null when a train has no track near.
 */
function stateFor(d: VehicleDef, w: World, x: number, z: number, heading: number, y: number): VehicleState | null {
  if (d.kind !== 'rail') return spawnState(d, w, x, z, heading, y);
  trains.setWorlds(islands ? [...islands.live.values()] : [w]);
  const set = SETS.find((s) => s.id === d.set);
  if (!set) return null;
  if (veh instanceof TrainState) trains.remove(veh.train);
  // a freight's wagons are what the county it was bought in makes
  const unit = [fleet.ridden, ...fleet.units].find((u) => u?.model === d.id && u.origin);
  let producers = producersOf(w);
  if (unit?.origin && islands) {
    const bw = islands.at(unit.origin[0], unit.origin[1]);
    if (bw) producers = producersOf(bw);
  } else if (set.freight) {
    const mine = fleet.units.find((u) => u.model === d.id && !u.origin);
    if (mine) mine.origin = [w.cx, w.cz];
  }
  const tr = trains.placePlayer(set, w.ox + x, w.oz + z, RIDE_RANGE, hashString(`${w.seed}:${d.id}`), producers);
  // the Passport's treats on the engine and the gold on every car (render/treats.ts)
  if (tr) dressTrainTreats(tr.cars.map((c) => c.mesh), d);
  return tr ? new TrainState(d, tr, trains, w) : null;
}

// ---------------------------------------------------------------------------------------------
// the fleet: buying, taking the wheel, tows

/** Where the player is, as a place to leave a unit: an aircraft is left on the ground under it. */
function playerSpot(): { cx: number; cz: number; x: number; z: number; y: number; heading: number } {
  if (!home || !veh) return { cx: cell.cx, cz: cell.cz, x: 0, z: 0, y: 0, heading: 0 };
  const y = def.kind === 'air' ? groundY(home, veh.x, veh.z) : veh.y;
  return { cx: cell.cx, cz: cell.cz, x: veh.x, z: veh.z, y, heading: veh.heading };
}

/** Buy a model at the dealer: a new unit where the player stands, ridden from there; the old one parks beside. */
function buyVehicle(d: VehicleDef, price = priceFor(fleet, d.id)): string | null {
  if (!home || !veh) return 'Not now';
  if (!wallet.canAfford(price)) return `${d.name} costs ${money(price)}`;
  wallet.spend(price, 'vehicles');
  const at = playerSpot();
  const u = fleet.make(d.id, at.cx, at.cz, at.x, at.z, at.heading, at.y);
  deeds.mark('models', d.id);
  missions.bought(d.id);
  deeds.best('motorPool', fleet.units.length);
  // the paper (docs/newspaper.html): a first boat, flyer or train is big news
  const cls = d.kind === 'water' ? 'boat' : d.kind === 'air' ? 'flyer' : d.kind === 'rail' ? 'train' : '';
  const firstOf = !!cls && !fleet.units.some((q) => q !== u && defOf(q.model).kind === d.kind);
  press.write({ k: 'vehicleBought', who: 'you', v: firstOf ? 'first' : undefined, w: firstOf ? 4 : price >= 20000 ? 3 : 2, f: { model: d.name, price, first: firstOf ? cls : '' }, pic: vehiclePic(d.id) });
  if (d.kind === 'rail') {
    const set = SETS.find((s) => s.id === d.id);
    if (set?.freight) u.origin = [cell.cx, cell.cz];
  }
  // a new vehicle goes straight into the garage (docs/hqwindow.html): you keep driving what you came in, and
  // the HQ window opens on it, to drive it instead or put it to work
  fleet.store(u);
  lastBought = u;
  return null;
}

/** The vehicle just bought, for the HQ window to open on once the dealer's counter has closed. */
let lastBought: Unit | null = null;

/** A purchase is done: the HQ window's garage with it picked and glowing, and the first time, how to use it. */
function showBought(): void {
  const u = lastBought;
  lastBought = null;
  if (!u || !hqWin) return;
  const first = fleet.bought === 0;
  fleet.bought++;
  hqWin.openUnit(u);
  hqWin.parts.board.flash(u.uid);
  // the first drive's tour of the Fleet tab (her helping hand) has already shown where things are
  if (first && !missions.ms.taught.has('fleettab')) hqWin.parts.board.coach(u.uid);
  hqWin.say(`${u.name} is yours · it waits in your garage`);
}

/** Why a unit can't come out of the garage beside the player, or null. */
function garageCheck(u: Unit): string | null {
  const d = fleet.defFor(u);
  // a train out of the garage waits in the sheds until it is ridden from beside a railway
  if (d.kind === 'rail') return null;
  return towCheck(u)?.replace(/^A boat can only be towed to water/, 'A boat comes out of the garage onto water') ?? null;
}

/**
 * Out of the garage into a free slot: parked beside the player (a boat on the nearest water; a train in
 * the sheds, until it is ridden from beside a railway). A message when it can't be done.
 */
/** Why a garaged unit can't come out beside the player now, or null: Bring it out and the HQ board's drop both ask. */
/** `freed`: slots about to be freed (the depot board's swap puts one away as this one comes out). */
function deployWhy(u: Unit, freed = 0): string | null {
  if (!home || !veh) return 'Not now';
  if (fleet.free + freed < 1) return fleet.hq ? `Every slot is taken: put one away, or make a grander building than ${fleet.hq.name} your HQ` : 'No fleet slots without an HQ: buy a building and make it your HQ';
  // a jet comes out on an airfield's stand: it needs one near enough, not water or a tow
  const d = fleet.defFor(u);
  if (isJet(d)) { const st = jetStand(d as AirDef); return typeof st === 'string' ? st : null; }
  return garageCheck(u);
}
/**
 * Out of the garage far from where it went in is a tow (Fleet.garageFee; the user, 4 Nov 2026: the garage was a
 * free way across the map). The fee card asks first; `run` does the bring-out again with the fee agreed, and pays
 * it once the unit is out. What the caller says meanwhile, or why it can't be paid.
 */
function askGarageTow(u: Unit, t: { fee: number; gaps: number; tiles: number }, act: string, run: (fee: number) => string | null): string {
  if (feeCard.isOpen) return 'Answer the tow card first';
  const at = fleet.placeName(u);
  const from = at === 'the garage' || at === 'somewhere' ? 'far from here' : `at ${at}`;
  if (wallet.cash < t.fee) return `${u.name} went in ${from}: a tow out here is ${money(t.fee)}, more than you have`;
  const over = t.gaps ? ` and across ${t.gaps === 1 ? 'a strait' : `${t.gaps} straits`}` : '';
  feeCard.ask({
    title: `Bring ${u.name} out here?`,
    line: `${u.name} went into the garage ${from}, ${t.tiles} tiles away${over}. Out here it comes on a tow truck.`,
    fee: t.fee, act,
    accept: () => {
      if (wallet.cash < t.fee) { hud.announce(u.name, `A tow costs ${money(t.fee)}`); return; }
      const why = run(t.fee);
      if (why) hud.announce(u.name, why);
    },
  });
  return `${u.name} went in ${from}: a ${money(t.fee)} tow · accept or decline`;
}
/** An agreed garage tow, paid once the unit is out. */
function payGarageTow(u: Unit, fee: number | undefined): void {
  if (!fee || !wallet.spend(fee, 'fines')) return;
  cargoHud.setCash(wallet.cash);
  hud.announce(u.name, `Towed out of the garage · −${money(fee)}`);
}

/** `fee`: a garage tow the player has agreed to (askGarageTow), paid when it is out; undefined asks when there is one. */
function deployUnit(u: Unit, fee?: number): string | null {
  if (u.where !== 'garaged') return null;
  const why = deployWhy(u);
  if (why) return why;
  // a jet comes out on an airfield's stand, not beside you
  const jd = fleet.defFor(u);
  if (isJet(jd)) {
    const st = jetStand(jd as AirDef);
    if (typeof st === 'string') return st;
    const t = fee === undefined ? fleet.garageFee(u, st.at) : null;
    if (t) return askGarageTow(u, t, 'Bring it out', (f) => deployUnit(u, f));
    fleet.unGarage(u, st.at);
    u.place = fleet.placeName(u);
    fleetDirty = true;
    hud.announce(u.name, `Out of the garage · waiting on a stand at ${st.name}`);
    payGarageTow(u, fee);
    return null;
  }
  const t = fee === undefined ? fleet.garageFee(u, playerSpot()) : null;
  if (t) return askGarageTow(u, t, 'Bring it out', (f) => deployUnit(u, f));
  fleet.unGarage(u, playerSpot());
  if (fleet.defFor(u).kind !== 'rail') placeBeside(u);
  u.place = fleet.placeName(u);
  fleetDirty = true;
  payGarageTow(u, fee);
  return null;
}

/**
 * Drive a unit out of the garage from here: it comes out where the player is (a boat on the nearest
 * water) and the one they were in goes into the garage in its place. A message when it can't be done.
 */
function swapIn(u: Unit, fee?: number): string | null {
  if (!home || !veh || !islands) return 'Not now';
  if (u.where !== 'garaged') return goToUnit(u);
  if (smuggle.run) return 'Not with that in the back';
  const d = fleet.defFor(u);
  // a jet: out onto an airfield's stand, and the band opens on you at its controls there
  if (isJet(d)) {
    const st = jetStand(d as AirDef);
    if (typeof st === 'string') return st;
    const t = fee === undefined ? fleet.garageFee(u, st.at) : null;
    if (t) return askGarageTow(u, t, 'Fly it', (f) => { const no = swapIn(u, f); if (!no) hqWin?.close(); return no; });
    fleet.unGarage(u, st.at);
    u.place = fleet.placeName(u);
    // taking its wheel parks the one you were in, and settles the fleet into its slots (the garage takes any extra)
    const why = goToUnit(u);
    if (why) { fleet.store(u); return why; }
    hud.announce(d.name, `Delivered to ${st.name} · taxi to the runway and open the throttle`, 5000);
    payGarageTow(u, fee);
    return null;
  }
  const why = d.kind === 'rail' ? (railReach(d) ? shedsCheck(u) : null) : garageCheck(u);
  if (why) return why;
  const t = fee === undefined ? fleet.garageFee(u, playerSpot()) : null;
  if (t) return askGarageTow(u, t, 'Drive it', (f) => { const no = swapIn(u, f); if (!no) hqWin?.close(); return no; });
  cut = {
    t: 0, fn: () => {
      if (u.where !== 'garaged') return;
      const was = fleet.ridden;
      fleet.unGarage(u, playerSpot());
      if (d.kind === 'water') placeBeside(u);
      const no = takeUnit(u, playerSpot());
      if (no) { fleet.store(u); hud.announce(u.name, no); return; }
      if (was && was !== u && was.where !== 'garaged') fleet.store(was);
      hud.announce(u.name, `Out of the garage${was && was !== u ? ` · ${was.name} went in` : ''}`);
      payGarageTow(u, fee);
    },
  };
  return null;
}

/**
 * A jet out of the garage (docs/rides.html) can't be set down on a road: it is delivered to a free stand at
 * the nearest airfield whose runway it fits, or a message when there is none near enough.
 */
function jetStand(d: AirDef): { at: { cx: number; cz: number; x: number; z: number; y: number; heading: number }; name: string } | string {
  if (!home || !veh) return 'Not now';
  const gx = home.ox + veh.x, gz = home.oz + veh.z;
  const r = nearestRunway(gx, gz, d.jet!.runway);
  if (!r) return d.jet!.runway > 30 ? `No international airport near enough: the ${d.name} needs a long runway` : `No airfield near enough to deliver the ${d.name} to`;
  // a stand nobody of yours is parked on
  const s = r.stands.find((st) => !fleet.units.some((u) => u.where === 'parked' && u.cx === r.w.cx && u.cz === r.w.cz && Math.hypot(u.x + r.w.ox - st.x, u.z + r.w.oz - st.z) < 2)) ?? r.stands[0];
  return { at: { cx: r.w.cx, cz: r.w.cz, x: s.x - r.w.ox, z: s.z - r.w.oz, y: r.y, heading: s.heading }, name: r.name };
}

/** A spot a car's width to the right of this one, where the vehicle just left is parked. */
function besideSpot(at: { cx: number; cz: number; x: number; z: number; y: number; heading: number }) {
  if (!home) return at;
  const [, hw] = halfSize(def);
  const side = hw * 2 + 0.35;
  const x = at.x + Math.cos(at.heading) * side, z = at.z - Math.sin(at.heading) * side;
  if (x < 0.5 || z < 0.5 || x > N - 0.5 || z > N - 0.5) return at;
  return { ...at, x, z };
}

/**
 * Take the wheel of a unit where it stands. The unit the player was in parks at `leave` (where they
 * are, by default); a working unit's driver goes on the bench and its load stays in the hold. A unit
 * in another cell loads that cell as home. Returns a message when it can't be done.
 */
function takeUnit(u: Unit, leave = playerSpot()): string | null {
  if (!home || !veh || !islands) return 'Not now';
  if (airlift.busy) return 'Not while the chopper has your vehicle';
  if (smuggle.run && u.where !== 'ridden') return 'Not with that in the back';
  const d = fleet.defFor(u);
  if (u.where === 'ridden') return null;
  // a shared fleet's vehicle another member's game is driving (docs/sharedfleets.html)
  const locked = fleet.lockedWhy(u);
  if (locked) return locked;
  // a crewed train away on a long haul: nothing of it here to ride
  if (railCrew.away(u)) return `${u.name} is away on a long haul: Watch it instead`;
  // a working unit's place is where its agent is
  if (u.agent) { u.cx = u.agent.w.cx; u.cz = u.agent.w.cz; u.x = u.agent.state.x; u.z = u.agent.state.z; u.heading = u.agent.state.heading; }
  // a crewed train's place is where its train is on the line (its driver steps down as you take the regulator)
  const crewed = railCrew.train(u);
  const sp = crewed ? railCrew.spotOf(crewed) : null;
  if (sp) { u.cx = sp.cx; u.cz = sp.cz; u.x = sp.x; u.z = sp.z; u.y = sp.y; u.heading = sp.heading; }
  if (d.kind === 'rail' && !onRails(u)) {
    // bought (or left) away from any line: it comes out of the sheds onto the railway beside the player
    const why = shedsCheck(u);
    if (why) return why;
    const at = playerSpot();
    u.cx = at.cx; u.cz = at.cz; u.x = at.x; u.z = at.z; u.y = at.y; u.heading = at.heading;
  }
  const wasHome = home;
  const target = islands.at(u.cx, u.cz) ?? islands.force(u.cx, u.cz);
  fleet.setRidden(u, leave);
  if (veh instanceof TrainState) trains.remove(veh.train);
  if (target !== wasHome) {
    cell.cx = u.cx;
    cell.cz = u.cz;
    home = target;
  }
  const st = stateFor(d, home, u.x, u.z, u.heading, u.y);
  veh = st ?? spawnState(VEHICLES[0], home, u.x, u.z, u.heading, -Infinity);
  wearModel(st ? d : VEHICLES[0]);
  followCam.target.set(home.ox + veh.x, veh.y, home.oz + veh.z);
  if (target !== wasHome) { arrived(true); convoy.settleNow(); }
  syncNeighbourhood();
  fleetDirty = true;
  return null;
}


/** The garage's Ride: the band closes, the player is put in the unit wherever it is, and the band opens. */
function goToUnit(u: Unit): string | null {
  if (!home || !veh || !islands) return 'Not now';
  if (smuggle.run) return 'Not with that in the back';
  if (u.where === 'towing') return `${u.name} is on a tow truck`;
  if (defOf(u.model).kind === 'rail' && !onRails(u)) {
    const why = shedsCheck(u);
    if (why) return why;
  }
  cut = { t: 0, fn: () => { const why = takeUnit(u); if (why) hud.announce(u.name, why); } };
  return null;
}

/**
 * Whether a train stands on a line it can be ridden from. Its cell must be in memory to know; one that
 * isn't is taken to be where it was left on the railway (a train is only ever left on one).
 */
function onRails(u: Unit): boolean {
  if (!islands) return false;
  const tw = islands.at(u.cx, u.cz);
  if (!tw) return true;
  trains.setWorlds([...islands.live.values()]);
  return !!trains.net.nearest(tw.ox + u.x, tw.oz + u.z, RIDE_RANGE);
}

/** A train with no line where it stands is in the sheds: why it can't come out beside the player, or null when it can. */
function shedsCheck(u: Unit): string | null {
  const reach = railReach(fleet.defFor(u));
  return reach ? `${u.name} waits in the sheds until you ride it from beside a railway · ${reach.replace(/^Ride it beside a railway( · | — )/, '')}` : null;
}

/** The band closing over a fast travel: a quarter second shut, the swap, then open. */
let cut: { t: number; fn: (() => void) | null } | null = null;
const CUT_SHUT = -0.62, CUT_CLOSE = 0.35, CUT_OPEN = 0.5;

/** Why a unit can't be towed to the player now. */
function towCheck(u: Unit): string | null {
  if (!home || !veh) return 'Not now';
  const d = defOf(u.model);
  if (d.kind === 'water') {
    const t = findNear(veh.x, veh.z, (tx, tz) => Math.hypot(tx - veh!.x, tz - veh!.z) < 30 && home!.water[idx(tx, tz)] >= 0);
    if (!t || Math.hypot(t[0] - veh.x, t[1] - veh.z) > 30) return 'A boat can only be towed to water: drive nearer the shore';
  }
  return null;
}

/** A tow has arrived: put the unit down beside the player, where it can stand. */
function placeBeside(u: Unit): boolean {
  if (!home || !veh) return false;
  const d = defOf(u.model);
  const spot = besideSpot(playerSpot());
  let x = spot.x - Math.sin(spot.heading) * 1.2, z = spot.z - Math.cos(spot.heading) * 1.2;
  x = Math.min(N - 1, Math.max(1, x)); z = Math.min(N - 1, Math.max(1, z));
  if (d.kind === 'rail') return false;
  const st = d.kind === 'air' ? new AirState(d, x, z, spot.heading, groundY(home, x, z)) : spawnState(d, home, x, z, spot.heading, -Infinity);
  u.cx = cell.cx; u.cz = cell.cz; u.x = st.x; u.z = st.z; u.y = st.y; u.heading = spot.heading;
  fleetDirty = true;
  return true;
}

/**
 * A version 5 save (or a new game): one unit per model owned. The one ridden is under the player; the
 * rest park at free kerbs of the nearest town (boats off its harbour, trains in the sheds where the player is).
 */
/**
 * One unit per model owned, set out round the player. `kept` is a carried-over career's vehicles
 * (docs: online world restarts): each comes back as its own unit, with its name and workshop parts.
 */
function migrateFleet(owned: string[], kept: NonNullable<OnlineStart['carry']>['units'] = []): void {
  if (!home || !veh) return;
  fleet.clear();
  const at = playerSpot();
  const origins = new Map<string, [number, number]>();
  for (const o of owned) {
    const m = /^@(\w+):(-?\d+),(-?\d+)$/.exec(o);
    if (m) origins.set(m[1], [Number(m[2]), Number(m[3])]);
  }
  const known = (id: string): boolean => ALL_VEHICLES.some((v) => v.id === id);
  const models = [...new Set(owned.filter((o) => !o.startsWith('@') && known(o)))];
  if (!models.includes(def.id)) models.unshift(def.id);
  // a second Tomato of the same model, kept from the old world, is a unit of its own too
  for (const id of new Set(kept.map((k) => k.model).filter(known))) {
    for (let n = kept.filter((k) => k.model === id).length - models.filter((m) => m === id).length; n > 0; n--) models.push(id);
  }
  const town = [...home.towns].sort((a, b) => Math.hypot(a.x0 + a.size / 2 - veh!.x, a.z0 + a.size / 2 - veh!.z) - Math.hypot(b.x0 + b.size / 2 - veh!.x, b.z0 + b.size / 2 - veh!.z))[0];
  const taken: { x: number; z: number }[] = [{ x: veh.x, z: veh.z }];
  let rode = false;
  for (const id of models) {
    const d = defOf(id);
    if (id === def.id && !rode) {
      rode = true;
      const u = fleet.make(id, at.cx, at.cz, at.x, at.z, at.heading, at.y);
      fleet.setRidden(u, null);
      u.origin = origins.get(id);
      continue;
    }
    let x = at.x, z = at.z;
    if (d.kind === 'water') {
      const port = [...home.ports].sort((a, b) => Math.hypot(a.x - veh!.x, a.z - veh!.z) - Math.hypot(b.x - veh!.x, b.z - veh!.z))[0];
      const t = port ? findNear(port.root % N, Math.floor(port.root / N), (tx, tz) => home!.water[idx(tx, tz)] >= 0 && !taken.some((q) => Math.hypot(q.x - tx, q.z - tz) < 3)) : null;
      if (t) { x = t[0] + 0.5; z = t[1] + 0.5; }
    } else if (d.kind !== 'rail' && town) {
      const k = kerbNear(home, town.x0 + town.size / 2, town.z0 + town.size / 2, Math.ceil(town.size / 2) + 4, taken);
      if (k) { x = k.x; z = k.z; }
    }
    taken.push({ x, z });
    const u = fleet.make(id, at.cx, at.cz, x, z, at.heading, at.y);
    u.origin = origins.get(id);
    u.place = fleet.placeName(u);
  }
  // the old world's vehicles, model by model in the order they were kept: their names and upgrades
  const left = [...fleet.units];
  for (const k of kept) {
    const i = left.findIndex((u) => u.model === k.model);
    if (i < 0) continue;
    const u = left.splice(i, 1)[0];
    if (k.name) u.name = k.name;
    u.parts = unpackParts(k.parts);
  }
  // one slot without an HQ: the rest wait in the garage
  fleet.settle();
}

/** The walk-up: the unit of the player's that Tab would take the wheel of, if any. */
/** A hidden vehicle found and climbed into: the fleet's for good, and the player drives it away. */
function claimFind(s: Stash): void {
  if (!home || !islands) return;
  const w = islands.at(s.cx, s.cz);
  if (!w) return;
  const d = defOf(s.model);
  const y = s.y ?? groundAt(w, s.x, s.z);
  const u = fleet.make(s.model, s.cx, s.cz, s.x, s.z, s.heading, y);
  u.place = fleet.placeName(u);
  stashLayer.claim(s);
  deeds.mark('models', d.id);
  deeds.best('motorPool', fleet.units.length);
  const why = takeUnit(u);
  const garaged = fleet.settle(why ? u : null).length > 0 && u.where === 'garaged';
  press.write({ k: 'find', who: 'you', f: { model: d.name, place: s.place }, pic: vehiclePic(d.id) });
  hud.announce(`${d.name} found`, why ? (garaged ? `It’s yours · it went to your garage (${why})` : `It’s yours · ${why}`) : `It’s yours to keep · found at ${s.place}`);
  sfx.chime(3);
  fleetDirty = true;
}

function walkUpUnit(): Unit | null {
  if (!home || !veh || veh instanceof TrainState) return null;
  const parked = fleetLayer.nearest(home, veh.x, veh.z, veh.y);
  if (parked) return parked;
  const a = alive.get(home);
  for (const g of a?.traffic.owned ?? []) {
    if (g.w !== home || Math.abs(g.state.v) > 0.3) continue;
    if (Math.hypot(g.state.x - veh.x, g.state.z - veh.z) < 2.5) return fleet.unit(g.owner);
  }
  return null;
}
