/** The fleet's name and livery: painted on every unit, and its badge beside the cash. */
function showBrand(b: FleetBrand | null): void {
  fleet.setBrand(b);
  const el = document.getElementById('fleetname');
  if (!el) return;
  el.hidden = !b;
  el.innerHTML = b ? badgeHtml(b, 28) : '';
  if (b) el.append(b.name);
}

/**
 * The ridden unit's parts changed in the workshop, or a save put them back: the same vehicle where it
 * is, going as fast as it was, rebuilt as its new definition.
 */
function refit(next: VehicleDef): void {
  if (!veh) return;
  if (veh instanceof TrainState) {
    (veh as unknown as { stats: VehicleDef }).stats = next;
    // a train's cars are its own (game/trains.ts): its treats go on and come off them (render/treats.ts)
    dressTrainTreats(veh.train.cars.map((c) => c.mesh), next);
  }
  else (veh as unknown as { def: VehicleDef }).def = next;
  rider.remove(mesh.holder);
  disposeVehicleMesh(mesh);
  def = next;
  mesh = buildVehicleMesh(def);
  rider.add(mesh.holder);
  if (home) cargo.refit(def, globalRider(), home);
  hud.setVehicle(def, false);
}

/** The vehicle a save was in, before its world loads. */
function applyRide(id: string): void {
  def = ALL_VEHICLES.find((v) => v.id === id) ?? def;
  rider.remove(mesh.holder);
  disposeVehicleMesh(mesh);
  mesh = buildVehicleMesh(def);
  rider.add(mesh.holder);
  hud.setVehicle(def, false);
}

