/** Whether the player was in a tunnel last frame: a cave's floor for a car, a rail tunnel for a train. */
let wasUnderground = false;

/** Leaving a tunnel counts one: a cave passage in a car, a bored tunnel in your own train. */
function countUnderground(v: VehicleState): void {
  if (!home) return;
  let under = false;
  if (v instanceof TrainState) {
    const f = v.train.trail[0];
    if (f) {
      const u = f.t.p.under, len = f.t.p.length || 1;
      under = u[Math.min(u.length - 1, Math.max(0, Math.round((f.b / len) * (u.length - 1))))] === Under.Tunnel;
    }
    // a stop at a platform: any car of the train standing on one
    if (Math.abs(v.v) < 0.05) {
      for (const p of v.train.trail) {
        const lo = Math.min(p.a, p.b), hi = Math.max(p.a, p.b);
        for (const { st, index, loop } of p.t.stations) {
          if (st.passing) continue;
          if (loop || (hi >= st.s0 && lo <= st.s1)) deeds.mark('stations', `${home.seed}|${p.t.w.cx},${p.t.w.cz}#${index}`);
        }
      }
    }
  } else {
    const tx = Math.min(N - 1, Math.max(0, Math.floor(v.x))), tz = Math.min(N - 1, Math.max(0, Math.floor(v.z)));
    under = home.surface[idx(tx, tz)] === Surface.Cave;
  }
  if (wasUnderground && !under) deeds.add('tunnels');
  wasUnderground = under;
}

/** How long each weather has been above half strength, for Skywatcher's three seconds. */
const skyHeld = new Map<string, number>();
function watchSkies(dt: number): void {
  if (dt <= 0) return;
  const n = weather.now;
  for (const k of WEATHERS) {
    const v = k === 'mist' ? Math.max(n.mist, n.mistTop) : n[k];
    const held = v > 0.5 ? (skyHeld.get(k) ?? 0) + dt : 0;
    skyHeld.set(k, held);
    // the Weather box: game hours of each weather where the player is
    if (v > 0.5 && mode === 'play') press.weather(k, dt / SECONDS_PER_HOUR);
    if (held >= 3) deeds.mark('weathers', k);
    // the paper (docs/newspaper.html): the county's weather, once a kind a day, when it is worth a line
    if (held >= 3 && held - dt < 3 && k !== 'rain' && home) {
      const tag = `${k}|${Math.floor(sky.days)}|${home.cx},${home.cz}`;
      if (!skyLogged.has(tag)) {
        skyLogged.add(tag);
        if (skyLogged.size > 64) skyLogged.delete(skyLogged.values().next().value!);
        press.write({ k: 'weather', v: k, w: k === 'storm' || k === 'blizzard' || k === 'aurora' ? 3 : 2, f: { wx: WX_WORD[k] ?? k, county: home.name } });
      }
    }
  }
}
/** Weathers already in the paper's log, by kind, day and county. */
const skyLogged = new Set<string>();
const WX_WORD: Record<string, string> = { storm: 'a thunderstorm', blizzard: 'a blizzard', dust: 'a dust storm', mist: 'fog', aurora: 'the aurora', rainbow: 'a rainbow', fireflies: 'fireflies' };

/** Seconds until the next deed card may show: one at a time, 1.5 s apart. */
/** Achievement cards: tiers landing, countdowns to the next one, and milestones on the way (game/deedCards.ts). */
const deedCards = new DeedCards(deeds, sfx);
/** Passport stamps as they are earned, pressed onto their cards in turn (game/stampCards.ts). */
const stampCards = new StampCards(sfx);
stampCards.log = (n) => hud.keep(n.title, n.body, '', n.group, n.img, n.open, n.tip);
// achievements join the stamps' stream: kept in the history, and the batch's best shown (a high tier ranks with a town style)
deedCards.stream = (n) => {
  stampCards.push({
    img: n.seal, title: n.title, body: n.body, group: 'Achievements', quiet: n.milestone,
    score: n.milestone ? 5 : 40 + n.tier * 10, sound: n.milestone ? undefined : () => sfx.chime(n.tier),
    // in the history: hovered, the achievement's description as the Passport has it; clicked, its page there
    tip: deedTip(n.deed), open: () => openPassport(undefined, n.deed.id),
  });
  // Gold and up is in the paper (docs/newspaper.html)
  if (!n.milestone && n.tier >= 3) press.write({ k: 'deed', who: 'you', w: n.tier >= 4 ? 3 : 2, f: { deed: n.deed.name, tier: TIERS[n.tier - 1] } });
};
/**
 * A Passport page filled to the last stamp (game/passportRewards.ts): its seal on a card above every stamp of the
 * batch, the paper, and online a line to the players near (the whole book: to everyone signed in).
 */
rewards.onSeal = (id) => {
  const t = treatOf(id), label = sealLabel(id), book = id === 'book';
  stampCards.push({
    img: () => ringStamp(`seal:${id}`, t.icon, book ? 'The Gilded Fleet' : `${label} · sealed`, '#a8801f'),
    title: book ? 'The Gilded Fleet' : `${label}: page sealed`,
    body: `${t.icon} ${t.name} · ${t.blurb}`, group: 'Passport seals', foil: true,
    score: book ? 10000 : 1000, sound: () => sfx.chime(5),
    tip: t.blurb, open: () => openPassport(id.startsWith('visa:') ? 'visas' : 'sights'),
  });
  press.write({ k: 'sealed', who: 'you', ...(book ? { v: 'book', w: 5 } : {}), f: { page: label.toLowerCase(), treat: t.name } });
  if (online.active) online.post({ t: 'sealed', s: id });
};

/** The wild things' kinds (world/wildKinds.ts), for their curios. */
const WILD_SET = new Set<string>(WILD_KINDS);
/**
 * The seasons played through (game/toppers.ts phase 4): a season is begun when the clock comes into it while the game
 * is in play, and played through when the clock leaves it again with it begun, in the same game year.
 */
let seasonWas = '';
function seasonWatch(): void {
  const s = seasonAt(sky.days, sky.hour), year = Math.floor(sky.days / DAYS_PER_YEAR), key = `${year}:${s.name}`;
  if (seasonWas && seasonWas !== key) {
    if (deeds.has('seasonBegun', seasonWas)) seasonPlayed(seasonWas.split(':')[1]);
    deeds.mark('seasonBegun', key);
  }
  seasonWas = key;
}

/** A topper earned (game/toppers.ts): its card, and the paper. Worn from HQ window → Toppers or a vehicle's pane. */
