// the console's pr holds the wallet, teleports and unlocks: online it is there only for the player the cheats are
// for (cheatsAllowed); a game not signed in (the bots, the gates, a developer's local world) keeps it
Object.defineProperty(window, 'pr', { configurable: true, get: () => (cheatsAllowed() ? debug : undefined) });

// The game keeps the world's seed in the address bar, so a refresh arrives with ?seed= set. A seed
// only means "start this world afresh" when it names a different world from the one saved; the
// same seed is the game being reloaded, and the save is picked up where it left off.
// Boot through the title. The reel plays the most recent save's world (its roads and towns as the
// player left them, starting from their cell), or the world a ?seed= link names, or a fresh one.
// Nothing is written until the player starts or continues a game.
currentPlayer();
// served by an online server? Then Play online offers this very address
const originKnown = online.probeOrigin();
const recent = mostRecent();
const recentSave = recent ? Save.readSlot(recent) : null;
const urlSeed = params.get('seed');
titleMenu.setUrlSeed(urlSeed);
/** The title's world when it isn't the online one: the most recent save's, or a fresh one. */
const localTitle = (): void => { if (recentSave) loadWorld(recentSave.seed, recentSave, 'title'); else loadWorld(randomSeed(), undefined, 'title'); };
/**
 * The title as it always starts: the reel plays the online world, from the cell the player was last in there, so
 * Play online starts on the cells it has already built (world/islands.ts PRISTINE). A world remembered from last
 * time plays at once while the server is asked whether it is still the one; never asked before, the server gets a
 * moment to say, and a game with no server to ask plays a local world as it always did.
 */
function bootTitle(): void {
  // playing online only, the sign-in card is the title, and comes up at once over the loading screen
  titleMenu.showEarly();
  const known = urlSeed ? null : knownWorld();
  if (urlSeed) loadWorld(urlSeed, undefined, 'title');
  else if (known) {
    loadWorld(known.seed, undefined, 'title', { at: known.cell ?? known.start ?? undefined });
    void online.worldSeed(5000).then((s) => {
      if (s && s !== known.seed && mode === 'title' && islands?.seed === known.seed && !online.active) loadWorld(s, undefined, 'title', { at: knownWorld()?.start ?? undefined });
    });
  } else {
    hud.showLoading(null);
    void online.worldSeed(1500).then((s) => {
      if (mode !== 'title' || islands || online.active) return;
      if (s) loadWorld(s, undefined, 'title', { at: knownWorld()?.start ?? undefined });
      else localTitle();
    });
  }
}
// opened from a postcard's link (docs/postcards.html): read it from the server and go straight into the world as a
// guest, no title screen; one that can't be watched (gone, from an earlier world, the server full) is offered on the
// title instead, where signing in goes there
// opened from a shared fleet's invite link (/join/CODE → ?join=CODE, docs/sharedfleets.html): the invite is held for
// the next sign-in, and the sign-in card is opened once the title is up
const joinInUrl = inviteFrom(params.get('join') ?? '');
if (joinInUrl) {
  setPendingInvite(joinInUrl);
  const url = new URL(location.href);
  url.searchParams.delete('join');
  history.replaceState(null, '', url.toString());
  // (a sign-in card up already shows the invite)
  setTimeout(() => { if (mode === 'title' && !online.active && !titleMenu.open) titleMenu.showOnline(); }, 1500);
}
const cardInUrl = postcardInUrl();
if (cardInUrl) {
  hud.showLoading(null);
  void originKnown.then(() => readPostcard(online.defaultServer(), cardInUrl)).then(async (v) => {
    linkCard = !v ? { v: null, why: 'taken down, or the server can’t be reached' }
      : v.epoch !== v.now ? { v, why: 'from an earlier world: the ground has changed since' } : { v };
    if (linkCard.v && !linkCard.why && await startGuest(linkCard.v)) return;
    bootTitle();
  });
} else bootTitle();
requestAnimationFrame(frame);

scene.fog = new THREE.Fog(0xcfe6f5, 900, 1400);
