import * as THREE from 'three';
import { N, CHUNK, World, heightOnTile } from '../world/tiles';
import { hex } from '../world/biomes';
import { SolidBuf } from './lamps';
import type { InterstateInfo, InterstateSign } from '../world/interstatePlan';

/**
 * The generated interstates' signs (world/interstatePlan.ts, docs/interstates.html), one chunk at a time: a green
 * exit board on two posts before each off-ramp ("EXIT 12" over the town it serves), a red-white-and-blue route
 * shield where each on-ramp leaves the county road, and the route's own green board just inside each border it
 * crosses ("I-92" over its name). Posts and board backs are the lamps' lit solids; each face is one quad with its
 * words drawn once onto a small canvas, the texture shared by every sign that says the same thing.
 */

const POST = hex(0x8c939b), BACK = hex(0x5d646c);

interface Face { w: number; h: number; y: number; posts: number; draw: (g: CanvasRenderingContext2D, W: number, H: number) => void }

const GREEN = '#1f6b3a', WHITE = '#f4f6f2';

/** The words on a green board: a big top line and a smaller one under it, white on green with a white rim. */
function greenBoard(top: string, sub: string): Face['draw'] {
  return (g, W, H) => {
    g.fillStyle = GREEN; g.fillRect(0, 0, W, H);
    g.strokeStyle = WHITE; g.lineWidth = Math.max(3, H * 0.04);
    g.strokeRect(g.lineWidth, g.lineWidth, W - g.lineWidth * 2, H - g.lineWidth * 2);
    g.fillStyle = WHITE; g.textAlign = 'center'; g.textBaseline = 'middle';
    const fit = (text: string, size: number, y: number) => {
      g.font = `bold ${size}px "Arial Narrow", Arial, sans-serif`;
      const w = g.measureText(text).width, room = W * 0.88;
      if (w > room) g.font = `bold ${Math.floor(size * room / w)}px "Arial Narrow", Arial, sans-serif`;
      g.fillText(text, W / 2, y);
    };
    fit(top, Math.floor(H * 0.4), H * (sub ? 0.36 : 0.5));
    if (sub) fit(sub, Math.floor(H * 0.26), H * 0.74);
  };
}

/** A route shield: a blue body under a red crown, the number in white. */
function shield(number: string): Face['draw'] {
  return (g, W, H) => {
    g.clearRect(0, 0, W, H);
    const path = () => {
      g.beginPath();
      g.moveTo(W * 0.08, H * 0.06); g.lineTo(W * 0.92, H * 0.06);
      g.quadraticCurveTo(W * 0.98, H * 0.55, W * 0.5, H * 0.96);
      g.quadraticCurveTo(W * 0.02, H * 0.55, W * 0.08, H * 0.06);
      g.closePath();
    };
    path(); g.fillStyle = WHITE; g.fill();
    g.save(); path(); g.clip();
    g.fillStyle = '#1d3f8f'; g.fillRect(0, H * 0.3, W, H);
    g.fillStyle = '#c8282e'; g.fillRect(0, 0, W, H * 0.27);
    g.restore();
    g.lineWidth = W * 0.04; g.strokeStyle = WHITE; path(); g.stroke();
    g.fillStyle = WHITE; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = `bold ${Math.floor(H * 0.42)}px "Arial Narrow", Arial, sans-serif`;
    g.fillText(number, W / 2, H * 0.6);
    g.font = `bold ${Math.floor(H * 0.14)}px Arial, sans-serif`;
    g.fillText('INTERSTATE', W / 2, H * 0.165);
  };
}

/** Faces drawn so far, by what they say. Signs are few (two or three a county), so they are kept. */
const MATS = new Map<string, THREE.MeshBasicMaterial>();
function faceMaterial(key: string, f: Face): THREE.MeshBasicMaterial {
  let m = MATS.get(key);
  if (m) return m;
  const c = document.createElement('canvas');
  const H = 128, W = Math.round(H * f.w / f.h);
  c.width = W; c.height = H;
  f.draw(c.getContext('2d')!, W, H);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  m = new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.4, side: THREE.FrontSide });
  MATS.set(key, m);
  return m;
}

/** What a sign says, and its board's size and height, in tile units. */
function faceOf(info: InterstateInfo, s: InterstateSign): { key: string; face: Face } {
  if (s.kind === 'exit') {
    const e = info.exits[s.exit ?? 0];
    const top = `EXIT ${e?.number ?? ''}`, sub = (e?.town ?? '').toUpperCase();
    return { key: `exit|${top}|${sub}`, face: { w: 1.5, h: 0.6, y: 0.95, posts: 2, draw: greenBoard(top, sub) } };
  }
  if (s.kind === 'shield') {
    return { key: `shield|${info.number}`, face: { w: 0.36, h: 0.4, y: 0.5, posts: 1, draw: shield(String(info.number)) } };
  }
  return { key: `route|${info.label}|${info.name}`, face: { w: 1.4, h: 0.6, y: 0.85, posts: 2, draw: greenBoard(info.label, info.name.toUpperCase()) } };
}

/** The signs standing in chunk (cx, cz) of this county, or null. */
export function buildInterstateSignChunk(w: World, cx: number, cz: number): THREE.Group | null {
  if (!w.interstates?.length) return null;
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const solid = new SolidBuf();
  const faces: THREE.Mesh[] = [];
  for (const info of w.interstates) {
    for (const s of info.signs ?? []) {
      if (s.x < x0 || s.x >= x0 + CHUNK || s.z < z0 || s.z >= z0 + CHUNK) continue;
      const tx = Math.min(N - 1, Math.floor(s.x)), tz = Math.min(N - 1, Math.floor(s.z));
      const ground = heightOnTile(w, tx, tz, s.x, s.z);
      const { key, face } = faceOf(info, s);
      // across the face: to its right, looking at it
      const rx = -s.fz, rz = s.fx;
      const postH = face.y + face.h / 2;
      const offs = face.posts === 2 ? [-face.w * 0.36, face.w * 0.36] : [0];
      // the posts stand behind the board, so they never cross its words
      for (const o of offs) solid.box(s.x + rx * o - s.fx * 0.08, ground - 0.05, s.z + rz * o - s.fz * 0.08, 0.05, postH + 0.05, 0.05, POST);
      // the board's back, a little behind its face
      const bx = s.x - s.fx * 0.03, bz = s.z - s.fz * 0.03, by = ground + face.y - face.h / 2;
      if (s.kind !== 'shield') {
        const hw = face.w / 2, d = 0.02;
        const P = (u: number, v: number, y: number): [number, number, number] => [bx + rx * u - s.fx * v, y, bz + rz * u - s.fz * v];
        solid.hull([P(-hw, -d, by), P(hw, -d, by), P(hw, d, by), P(-hw, d, by), P(-hw, -d, by + face.h), P(hw, -d, by + face.h), P(hw, d, by + face.h), P(-hw, d, by + face.h)], BACK);
      }
      // the face, a hair in front of the back, looking along (fx, fz)
      const geo = new THREE.PlaneGeometry(face.w, face.h);
      const m = new THREE.Mesh(geo, faceMaterial(key, face));
      m.position.set(s.x + s.fx * 0.005, ground + face.y, s.z + s.fz * 0.005);
      m.rotation.y = Math.atan2(s.fx, s.fz);
      faces.push(m);
    }
  }
  const body = solid.mesh();
  if (!body && !faces.length) return null;
  const g = new THREE.Group();
  if (body) g.add(body);
  for (const f of faces) g.add(f);
  return g;
}
