import * as THREE from 'three';
import { N, STEP, type Building, type World } from '../../world/tiles';
import { buildingHeight } from '../../world/towns';
import { roofTopAt } from '../../render/roofTop';
import type { EventParticles } from '../../render/eventParticles';
import type { LightSpec } from '../../render/eventLights';
import { VEHICLES, halfSize, type LandDef, type VehicleDef, type VehicleState } from '../vehicles';
import { CLOSED, CLOSED_REV, landRoute, type Traffic } from '../traffic';
import { KIND_OF } from './kinds';
import { MOTORCADE_HOURS, type Happening } from './calendar';
import { placeOf, mid, type Place, type Pt } from './venues';
import { Bulbs, Crowd, Rig, Way, block, clearGroup, dressed, flat } from './props';

/**
 * The showpieces (docs/events.html, phase 1): each event on stage near the camera, played from the world clock
 * alone, so a player who arrives late finds it where everyone else sees it, and one who leaves and comes back
 * finds it moved on. Nothing here is saved: what is drawn is worked out again from the hour each frame.
 */

export interface ShowCtx {
  /** The stage's group, at the scene's origin: everything is in world tiles. */
  group: THREE.Group;
  particles: EventParticles;
  worldAt(cx: number, cz: number): World | null;
  ground(x: number, z: number): number;
  trafficOf(w: World): Traffic | null;
  /** Light a building (or a box of them); returns the slot it took, -1 when none was free. Null puts a slot out. */
  light(slot: number, spec: LightSpec | null): number;
  /** The event vehicles traffic must stop for, rebuilt each frame. */
  obstacles: { state: VehicleState; def: VehicleDef; w: World }[];
  night(): number;
  /** Dim the day this much, 0..1, this frame (an eclipse); the most asked for wins. */
  dim(k: number): void;
  /** Snow falling where the camera is (a Christmas market's roofs go white). */
  snowing?(): boolean;
}

import { clamp01 } from '../../util/math';
export { clamp01 };
/** Real seconds in a game hour (render/daynight.ts). */
export const HOUR_S = 25;
export const u01 = (h: number, k: number): number => {
  let x = Math.imul(h ^ Math.imul(k + 1, 0x9e3779b1), 0x85ebca6b);
  x ^= x >>> 13; x = Math.imul(x, 0xc2b2ae35); x ^= x >>> 16;
  return (x >>> 0) / 4294967296;
};

export abstract class Show {
  readonly g = new THREE.Group();
  /** The game hour it can be let go. */
  until: number;
  protected slots: number[] = [];
  constructor(readonly e: Happening, protected ctx: ShowCtx) {
    ctx.group.add(this.g);
    this.until = e.end + 0.3;
  }
  abstract update(now: number, dt: number): void;
  /** Where it is, world tiles: its centre, or a moving event's lead. */
  abstract centre(): Pt | null;
  /** Light a slot of ours (k: which of ours), or put it out. */
  protected light(k: number, spec: LightSpec | null): void {
    if (spec && this.slots[k] === undefined) { const s = this.ctx.light(-1, spec); if (s >= 0) this.slots[k] = s; return; }
    if (this.slots[k] === undefined) return;
    this.ctx.light(this.slots[k], spec);
    if (!spec) delete this.slots[k];
  }
  dispose(): void {
    for (const s of this.slots) if (s !== undefined) this.ctx.light(s, null);
    this.slots = [];
    clearGroup(this.g);
  }
}

/** A county's tiles closed to new routes while a procession is on them, and opened again after. */
export class Closure {
  private on = false;
  constructor(private w: World, private tiles: number[]) {}
  set(on: boolean): void {
    if (on === this.on) return;
    this.on = on;
    let set = CLOSED.get(this.w);
    if (!set) CLOSED.set(this.w, (set = new Set()));
    for (const t of this.tiles) { if (on) set.add(t); else set.delete(t); }
    // the county's traffic replans round it (game/traffic.ts roundClosures)
    CLOSED_REV.set(this.w, (CLOSED_REV.get(this.w) ?? 0) + 1);
  }
}

export const toWorld = (w: World, p: Pt): Pt => ({ x: w.ox + p.x, z: w.oz + p.z });

/** A crowd lining both kerbs of a street (tile middles `P`, the county's frame): on the pavement edge, spread its length, at most `n`. */
export function lineStreet(crowd: Crowd, w: World, P: Pt[], h: number, n: number): void {
  const spots: Pt[] = [];
  for (let k = 1; k < P.length - 1; k++) {
    const a = P[k - 1], b = P[k + 1];
    const dx = b.x - a.x, dz = b.z - a.z, d = Math.hypot(dx, dz) || 1;
    const nx = -dz / d, nz = dx / d;
    for (const side of [1, -1]) {
      // on the street's own edge, the pavement, unless the street goes on that way (a junction)
      const ox = Math.floor(P[k].x + nx * side * 0.9), oz = Math.floor(P[k].z + nz * side * 0.9);
      if (ox < 0 || oz < 0 || ox >= N || oz >= N || w.road[ox + oz * N]) continue;
      for (const along of [-0.3, 0, 0.3]) {
        if (u01(h, k * 8 + side * 3 + Math.round(along * 10)) < 0.3) continue;
        const out = 0.4 + u01(h, k * 5 + side) * 0.06;
        spots.push({ x: w.ox + P[k].x + nx * side * out + (dx / d) * along, z: w.oz + P[k].z + nz * side * out + (dz / d) * along });
      }
    }
  }
  const step = Math.max(1, spots.length / n);
  for (let i = 0; i < spots.length && crowd.size < n; i += step) crowd.add(spots[Math.floor(i)].x, spots[Math.floor(i)].z);
}

// ---- the ticker-tape parade ---------------------------------------------------------------------------------------

/**
 * A champion's parade: police cars ahead and behind, the open-top bus in the club's colours with its players
 * aboard, crawling down an avenue from the stadium (or the town hall) between crowds lining both kerbs, paper
 * streaming down from the towers it passes; and that night the town's tallest building in the club's colours.
 */
export class ParadeShow extends Show {
  private way: Way;
  private rigs: { rig: Rig; off: number }[] = [];
  private crowd: Crowd;
  private closure: Closure;
  private towers: Building[];
  private convoyLen = 0;
  private colours: number[];
  private glowUntil: number;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    this.way = new Way(place.path!.map((p) => toWorld(w, p)));
    const team = e.club?.team;
    this.colours = team ? [team.colour, team.alt, 0xffffff] : [0xffffff, 0xf2c14e];
    const units: [VehicleDef, number][] = [
      [dressed('patrol'), 0], [dressed('patrol'), 0],
      [dressed('starTours', team?.colour ?? 0xe2412f, team?.alt), 14],
      [dressed('ambulance'), 0], [dressed('patrol'), 0],
    ];
    let off = 0;
    for (const [def, riders] of units) {
      const half = halfSize(def)[0];
      off += half;
      this.rigs.push({ rig: new Rig(this.g, def, riders), off });
      off += half + 0.45;
    }
    this.convoyLen = off;
    // the crowd lines both kerbs
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    const P = place.path!;
    lineStreet(this.crowd, w, P, e.h, 60);
    this.closure = new Closure(w, P.map((p) => Math.floor(p.x) + Math.floor(p.z) * N));
    this.towers = place.towers ?? [];
    // the town's tallest lit up in the club's colours until late
    this.glowUntil = Math.floor(e.start / 24) * 24 + 25.5;
    this.until = Math.max(this.glowUntil, e.end + 0.3);
  }

  centre(): Pt | null { return this.way.at(this.way.length / 2); }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.parade, D = spec.dur;
    const drive = D * 0.8;
    const pre = clamp01((now - (e.start - spec.lead)) / (spec.lead * 0.8));
    const run = (now - e.start) / drive;
    const leave = clamp01((now - (e.start + drive)) / (D - drive));
    this.closure.set(now >= e.start - spec.lead && now < e.end);
    // the crowd gathers in the hour before, and drifts off once the bus has gone by
    this.crowd.shown = this.crowd.size * (run < 1 ? pre : 1 - leave);
    // the convoy: lined up at the start, then the length of the avenue, then gone
    const L = this.way.length, lead = this.convoyLen + clamp01(run) * Math.max(0, L - this.convoyLen);
    const moving = run > 0 && run < 1;
    const v = moving ? Math.max(0, L - this.convoyLen) / (drive * HOUR_S) : 0;
    const out = now < e.start - spec.lead * 0.6 || now > e.end;
    let bus: Pt | null = null;
    for (const { rig, off } of this.rigs) {
      if (out) { rig.hide(); continue; }
      const p = this.way.at(lead - off);
      rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (rig.def.id === 'starTours') bus = p;
      if (rig.w) this.ctx.obstacles.push({ state: rig.local, def: rig.def, w: rig.w });
    }
    // the crowd cheers the bus by
    this.crowd.cheer = bus && moving ? 1 : 0.2;
    this.crowd.update(dt);
    if (bus && moving) this.paper(bus, dt);
    // the landmark in the club's colours, through the evening
    const top = this.place.tower;
    if (top && now >= e.start && now < this.glowUntil) {
      const c = mid(top);
      this.light(0, {
        x0: this.w.ox + top.x - 0.5, z0: this.w.oz + top.z - 0.5, x1: this.w.ox + top.x + top.w + 0.5, z1: this.w.oz + top.z + top.d + 0.5,
        uid: top.uid, mode: 'bands', a: this.colours[0], b: this.colours[1], strength: 0.35 + 1.1 * this.ctx.night(), phase: c.x,
      });
    } else this.light(0, null);
  }

  /** Ticker tape: from the towers near the bus, and drifting over it. */
  private paper(bus: Pt, dt: number): void {
    const P = this.ctx.particles;
    const near = this.towers.filter((b) => Math.hypot(this.w.ox + b.x + b.w / 2 - bus.x, this.w.oz + b.z + b.d / 2 - bus.z) < 9);
    const n = Math.min(12, Math.floor(70 * dt + Math.random()));
    for (let k = 0; k < n; k++) {
      const colour = Math.random() < 0.55 ? 0xf8f6ee : this.colours[k % 2];
      if (near.length && Math.random() < 0.7) {
        const b = near[Math.floor(Math.random() * near.length)];
        const h = b.level * STEP + buildingHeight(b) * (0.55 + Math.random() * 0.4);
        const side = Math.floor(Math.random() * 4);
        const x = this.w.ox + b.x + (side === 0 ? -0.05 : side === 1 ? b.w + 0.05 : Math.random() * b.w);
        const z = this.w.oz + b.z + (side === 2 ? -0.05 : side === 3 ? b.d + 0.05 : Math.random() * b.d);
        P.slip({ x, y: h, z, vx: (Math.random() - 0.5) * 0.4, vy: 0, vz: (Math.random() - 0.5) * 0.4, life: 9, colour, size: 0.07 });
      } else {
        const y = this.ctx.ground(bus.x, bus.z) + 1.4 + Math.random() * 1.6;
        P.slip({ x: bus.x + (Math.random() - 0.5) * 5, y, z: bus.z + (Math.random() - 0.5) * 5, vx: 0, vy: 0, vz: 0, life: 8, colour, size: 0.07 });
      }
    }
  }

  dispose(): void {
    this.closure.set(false);
    for (const r of this.rigs) r.rig.dispose();
    this.crowd.dispose();
    super.dispose();
  }
}

// ---- the presidential motorcade ---------------------------------------------------------------------------------------

/** Trucks of the convoy, front to back, and the colours of their lights. */
const CONVOY_TRUCKS: [string, number][] = [['dump', 0xd52b1e], ['mixer', 0xf4f2ec], ['mule', 0x1f4e9e], ['liveTruck', 0xf2b632], ['deuce', 0x2f8f4a], ['postal', 0xc8102e], ['dump', 0x6a2c91], ['mailTruck', 0xf4f2ec], ['mule', 0xe86a17], ['dump', 0x2a2a2e]];

/** The motorcade, front to back: police cars, black Badgers, the Statesman with its flags, more Badgers, an ambulance. */
const MOTORCADE: [string, number?][] = [['patrol'], ['patrol'], ['interceptor'], ['humvee', 0x15161a], ['statesman'], ['humvee', 0x15161a], ['humvee', 0x15161a], ['ambulance'], ['patrol']];

/**
 * The president's motorcade across its counties, an hour and a half or so in each: through the streets from one
 * seat of government, along the county roads and over the borders, to the other. Where the camera is, its cars
 * drive the real roads (worked out a county at a time) at the pace that keeps them on the clock everyone shares;
 * traffic ahead of it pulls to the kerb, and a twin-rotor shadows it overhead.
 */
export class MotorcadeShow extends Show {
  private rigs: { rig: Rig; off: number }[] = [];
  /** Game hours in each county. */
  private H: number;
  /** A light-up convoy's bulbs, strung down each truck. */
  private bulbs: Bulbs | null = null;
  private convoy: boolean;
  private ways = new Map<number, Way | null>();
  private total = 0;
  private heli: Rig;
  private heliPos = new THREE.Vector3(NaN, 0, 0);
  private sirenT = 0;
  private leadAt: Pt | null = null;
  private route: [number, number][];

  constructor(e: Happening, ctx: ShowCtx) {
    super(e, ctx);
    this.route = e.route!;
    this.H = KIND_OF[e.kind].perCounty ?? MOTORCADE_HOURS;
    this.convoy = e.kind === 'truckConvoy';
    let off = 0;
    for (const [id, colour] of this.convoy ? CONVOY_TRUCKS : MOTORCADE) {
      const def = dressed(id, colour);
      const half = halfSize(def)[0];
      off += half;
      this.rigs.push({ rig: new Rig(this.g, def), off });
      off += half + 0.7;
    }
    this.total = off;
    this.heli = new Rig(this.g, dressed('chinook'));
    this.heli.hide();
    if (this.convoy) this.bulbs = new Bulbs(this.g, this.rigs.length * 8, [0xff3b3b, 0x3dff8a, 0x5ad1ff, 0xffd166, 0xff6ad5, 0xffffff]);
  }

  centre(): Pt | null { return this.leadAt; }

  /** This county's way, worked out the first time it is wanted (null: not in memory, or no road through). */
  private wayIn(k: number): Way | null {
    if (k < 0 || k >= this.route.length) return null;
    if (this.ways.has(k)) return this.ways.get(k)!;
    const [cx, cz] = this.route[k];
    const w = this.ctx.worldAt(cx, cz);
    if (!w) return null;
    const p = placeOf(w, this.e);
    const def = this.rigs[0].rig.def as LandDef;
    const pts = p?.from && p.to ? landRoute(w, def, p.from.x, p.from.z, p.to.x, p.to.z, new Set()) : null;
    const way = pts && pts.length > 1 ? new Way([p!.from!, ...pts].map((q) => toWorld(w, q))) : null;
    this.ways.set(k, way);
    return way;
  }

  update(now: number, dt: number): void {
    const e = this.e, n = this.route.length;
    const u = Math.max(0, (now - e.start) / this.H);
    const k = Math.min(n - 1, Math.floor(u)), frac = u >= n ? 1 : u - k;
    const gone = now < e.start - KIND_OF[e.kind].lead || now > e.end;
    // its counties out of memory are forgotten, so a county seen again is worked out again
    for (const key of [...this.ways.keys()]) {
      const [cx, cz] = this.route[key];
      if (!this.ctx.worldAt(cx, cz)) this.ways.delete(key);
    }
    const here = gone ? null : this.wayIn(k);
    const moving = !gone && u > 0 && u < n;
    let lead: { x: number; z: number; heading: number } | null = null;
    for (const { rig, off } of this.rigs) {
      if (!here) { rig.hide(); continue; }
      // the first county: lined up at the hall's door, the whole convoy's length along its way
      let way: Way | null = here, s = k === 0 ? frac * Math.max(0, here.length - this.total) + this.total - off : frac * here.length - off;
      if (s < 0) { way = this.wayIn(k - 1); if (way) s += way.length; }
      if (!way) { rig.hide(); continue; }
      const p = way.at(s);
      const v = moving ? way.length / (this.H * HOUR_S) : 0;
      rig.place(this.ctx.worldAt, p.x, p.z, p.heading, v, dt);
      if (rig.w) this.ctx.obstacles.push({ state: rig.local, def: rig.def, w: rig.w });
      if (!lead) lead = p;
      if (rig.def.id === 'statesman') this.leadAt = { x: p.x, z: p.z };
    }
    if (!lead) this.leadAt = null;
    if (this.convoy) {
      // a light-up convoy: strings of bulbs down every truck, the first truck its leader; no sirens, no escort above
      this.leadAt = lead ? { x: lead.x, z: lead.z } : null;
      const b = this.bulbs!;
      b.begin();
      for (const { rig } of this.rigs) {
        if (!rig.shown) continue;
        const s = rig.state, fx = Math.sin(s.heading), fz = Math.cos(s.heading), sx = Math.cos(s.heading), sz = -Math.sin(s.heading);
        const half = halfSize(rig.def)[0];
        for (let k = 0; k < 8; k++) {
          const along = (k % 4 / 3 - 0.5) * half * 1.8, side = (k < 4 ? 1 : -1) * 0.2;
          b.at(s.x + fx * along + sx * side, s.y + 0.42, s.z + fz * along + sz * side);
        }
      }
      b.end();
      b.mesh.visible = this.ctx.night() > 0.15;
      this.heli.hide();
      return;
    }
    // the way ahead cleared by the sirens
    this.sirenT -= dt;
    const first = this.rigs[0].rig;
    if (lead && moving && first.w && this.sirenT <= 0) {
      this.sirenT = 0.25;
      this.ctx.trafficOf(first.w)?.siren(first.local.x, first.local.z, lead.heading, 14);
    }
    // and the twin-rotor overhead, easing after the Statesman
    if (this.leadAt && moving) {
      const gy = this.ctx.ground(this.leadAt.x, this.leadAt.z) + 4.5;
      if (Number.isNaN(this.heliPos.x)) this.heliPos.set(this.leadAt.x - 6, gy, this.leadAt.z - 6);
      const k2 = Math.min(1, dt * 0.8);
      const dx = this.leadAt.x - this.heliPos.x, dz = this.leadAt.z - this.heliPos.z;
      this.heliPos.x += dx * k2; this.heliPos.z += dz * k2; this.heliPos.y += (gy - this.heliPos.y) * k2;
      const s = this.heli.state;
      s.x = this.heliPos.x; s.y = this.heliPos.y; s.z = this.heliPos.z;
      if (Math.hypot(dx, dz) > 0.3) s.heading = Math.atan2(dx, dz);
      s.pitch = -0.08; s.power = 1;
      this.heli.mesh.holder.visible = true;
      this.heli.mesh.root.position.set(s.x, s.y, s.z);
      this.heli.mesh.root.rotation.set(s.pitch, s.heading, 0, 'YXZ');
      for (const sp of this.heli.mesh.spinners) sp.obj.rotation[sp.axis] += sp.speed * dt;
    } else { this.heli.hide(); this.heliPos.x = NaN; }
  }

  dispose(): void {
    for (const r of this.rigs) r.rig.dispose();
    this.heli.dispose();
    super.dispose();
  }
}

// ---- the car show ---------------------------------------------------------------------------------------

/** Paint a show car may have been resprayed in. */
const PAINT = [0xc8102e, 0x0b3d2e, 0xf3e9d2, 0x7fb3d5, 0x111111, 0xf2c14e, 0x8e5cc7, 0xe86a17, 0x5a5f66, 0xffffff];
/** Not on show: the working fleet, the trucks, anything with a trailer. */
const NOT_SHOWN = new Set(['bus', 'dump', 'bulldozer', 'wrecker', 'mixer', 'bigHook', 'postal', 'mailTruck', 'patrol', 'interceptor', 'deuce', 'tank', 'undertaker', 'liveTruck', 'starTours']);

/**
 * A car show on a town's square, car park or lawn: rows of vehicles from the common to the rarest, each with its
 * little stand, a judges' table under a striped canopy, and townsfolk wandering the rows.
 */
export class CarShow extends Show {
  private rigs: Rig[] = [];
  private crowd: Crowd;
  private props = new THREE.Group();
  private placed = false;
  private closure: Closure | null;

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    const pool = VEHICLES.filter((v) => v.kind === 'land' && !(v as LandDef).trailer && !NOT_SHOWN.has(v.id));
    const bays = place.bays!.slice(0, 28);
    bays.forEach((b, i) => {
      // rarer models more often than the streets have them: the show is what people come to see
      const base = pool[Math.floor(u01(e.h, i * 3) ** 0.8 * pool.length) % pool.length];
      const def = u01(e.h, i * 3 + 1) < 0.4 ? dressed(base.id, PAINT[Math.floor(u01(e.h, i * 3 + 2) * PAINT.length)]) : base;
      const rig = new Rig(this.g, def);
      rig.hide();
      this.rigs.push(rig);
      void b;
    });
    const lot = place.lot!;
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    this.crowd.roam = { x0: w.ox + lot.x + 0.2, z0: w.oz + lot.z + 0.2, x1: w.ox + lot.x + lot.w - 0.2, z1: w.oz + lot.z + lot.d - 0.2 };
    const people = Math.min(40, 10 + bays.length);
    for (let i = 0; i < people; i++) this.crowd.add(this.crowd.roam.x0 + u01(e.h, 500 + i) * (lot.w - 0.4), this.crowd.roam.z0 + u01(e.h, 900 + i) * (lot.d - 0.4));
    this.g.add(this.props);
    this.props.visible = false;
    this.closure = place.closes?.length ? new Closure(w, place.closes) : null;
  }

  centre(): Pt | null { const l = this.place.lot!; return { x: this.w.ox + l.x + l.w / 2, z: this.w.oz + l.z + l.d / 2 }; }

  /** The cars on their bays, a stand at each, and the judges' table: put out once, when the show sets up. */
  private setOut(): void {
    this.placed = true;
    const w = this.w, lot = this.place.lot!;
    this.place.bays!.slice(0, this.rigs.length).forEach((b, i) => {
      const x = w.ox + b.x, z = w.oz + b.z;
      this.rigs[i].place(this.ctx.worldAt, x, z, b.yaw, 0, 0);
      // a little stand in front, with the card on it
      const fx = Math.sin(b.yaw), fz = Math.cos(b.yaw), half = halfSize(this.rigs[i].def)[0];
      const sx = x + fx * (half + 0.18) + fz * 0.22, sz = z + fz * (half + 0.18) - fx * 0.22;
      block(this.props, sx, this.ctx.ground(sx, sz), sz, 0.015, 0.09, 0.015, 0x3a3f45);
      block(this.props, sx, this.ctx.ground(sx, sz) + 0.09, sz, 0.12, 0.07, 0.012, 0xf8f6ee, b.yaw);
    });
    // the judges: a table under a striped canopy at the lot's front
    const c = mid(lot), [dx, dz] = [[1, 0], [0, 1], [-1, 0], [0, -1]][lot.facing];
    const tx = w.ox + c.x + dx * (lot.w / 2 - 0.45), tz = w.oz + c.z + dz * (lot.d / 2 - 0.45);
    const gy = this.ctx.ground(tx, tz), yaw = Math.atan2(dx, dz);
    block(this.props, tx, gy + 0.1, tz, 0.7, 0.04, 0.24, 0xf4f2ec, yaw + Math.PI / 2);
    for (const [u, v] of [[-0.4, -0.2], [0.4, -0.2], [-0.4, 0.2], [0.4, 0.2]]) {
      const px = tx + Math.cos(yaw) * u + Math.sin(yaw) * v, pz = tz - Math.sin(yaw) * u + Math.cos(yaw) * v;
      block(this.props, px, gy, pz, 0.02, 0.36, 0.02, 0xdddddd);
    }
    for (let s = 0; s < 5; s++) block(this.props, tx + Math.cos(yaw) * (s - 2) * 0.18, gy + 0.36, tz - Math.sin(yaw) * (s - 2) * 0.18, 0.18, 0.025, 0.5, s % 2 ? 0xffffff : 0xc8102e, yaw);
  }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.carShow;
    const out = now >= e.start - spec.lead && now < e.end + 0.25;
    this.closure?.set(out);
    if (out && !this.placed) this.setOut();
    this.props.visible = out;
    for (const r of this.rigs) { if (!out) r.hide(); else if (!r.shown) r.mesh.holder.visible = r.shown = true; }
    this.crowd.shown = this.crowd.size * clamp01((now - e.start) / 0.6) * (1 - clamp01((now - (e.end - 0.5)) / 0.5));
    this.crowd.update(dt);
  }

  dispose(): void {
    this.closure?.set(false);
    for (const r of this.rigs) r.dispose();
    this.crowd.dispose();
    super.dispose();
  }
}

// ---- New Year's Eve ---------------------------------------------------------------------------------------

/** Fireworks' colours, in pairs. */
const FIRE = [[0xff3b3b, 0xffd166], [0x5ad1ff, 0xffffff], [0x9b5cff, 0xff6ad5], [0x3dff8a, 0xfff36b], [0xffb43d, 0xff3b3b], [0xffffff, 0xc0e8ff]];
interface Rocket { x: number; y: number; z: number; vy: number; top: number; colours: number[] }

/**
 * Midnight at the end of winter in a city's turn of the rotation: the square fills from half past nine, the tallest
 * tower glows gold from eleven, and in a New York-style city a ball of light slides down a mast on top of it in the
 * last quarter hour. At midnight the sky goes up in fireworks, paper falls from the tower, and every building in the
 * city flashes, then their lights chase each other until the crowd goes home.
 */
export class NewYearShow extends Show {
  private crowd: Crowd;
  private top: THREE.Vector3 | null;
  private ball: THREE.Mesh | null = null;
  private rockets: Rocket[] = [];
  private launchers: Pt[] = [];
  private fireT = 0;
  private midnight: number;
  private box: { x0: number; z0: number; x1: number; z1: number };

  constructor(e: Happening, ctx: ShowCtx, private w: World, private place: Place) {
    super(e, ctx);
    this.midnight = Math.floor(e.start / 24) * 24 + 24;
    const t = place.town!, tower = place.tower!;
    this.top = roofTopAt(w, tower) ?? new THREE.Vector3(w.ox + tower.x + tower.w / 2, tower.level * STEP + buildingHeight(tower), w.oz + tower.z + tower.d / 2);
    this.box = { x0: w.ox + t.x0 - 2, z0: w.oz + t.z0 - 2, x1: w.ox + t.x0 + t.size + 2, z1: w.oz + t.z0 + t.size + 2 };
    // the ball and its mast, in a New York-style city or a megalopolis
    if (t.style === 'newyork' || t.kind === 'mega') {
      const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.035, 1.3, 6), flat(0xc9ccd1));
      mast.position.set(this.top.x, this.top.y + 0.65, this.top.z);
      this.g.add(mast);
      this.ball = new THREE.Mesh(new THREE.IcosahedronGeometry(0.17, 2), new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfff2c4, emissiveIntensity: 2.2, roughness: 0.2, metalness: 0.3 }));
      this.ball.position.set(this.top.x, this.top.y + 1.3, this.top.z);
      this.g.add(this.ball);
    }
    // the crowd: on the square nearest the tower, or round its foot
    this.crowd = new Crowd(this.g, ctx.ground, e.h % 12);
    const lot = place.lot;
    const area = lot ? { x0: w.ox + lot.x + 0.2, z0: w.oz + lot.z + 0.2, x1: w.ox + lot.x + lot.w - 0.2, z1: w.oz + lot.z + lot.d - 0.2 }
      : { x0: this.top.x - 2.5, z0: this.top.z - 2.5, x1: this.top.x + 2.5, z1: this.top.z + 2.5 };
    for (let i = 0; i < 60; i++) {
      const x = area.x0 + u01(e.h, 40 + i) * (area.x1 - area.x0), z = area.z0 + u01(e.h, 140 + i) * (area.z1 - area.z0);
      const lx = Math.floor(x - w.ox), lz = Math.floor(z - w.oz);
      if (lx < 0 || lz < 0 || lx >= N || lz >= N || (w.blocked[lx + lz * N] && !lot)) continue;
      this.crowd.add(x, z);
    }
    // launchers ringed round the tower
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + u01(e.h, 7) * 6, r = 5 + u01(e.h, 300 + i) * 7;
      this.launchers.push({ x: this.top.x + Math.cos(a) * r, z: this.top.z + Math.sin(a) * r });
    }
    this.until = e.end;
  }

  centre(): Pt | null { return this.top ? { x: this.top.x, z: this.top.z } : null; }

  update(now: number, dt: number): void {
    const e = this.e, spec = KIND_OF.newYear, M = this.midnight;
    const pre = clamp01((now - (e.start - spec.lead)) / spec.lead);
    this.crowd.shown = this.crowd.size * pre * (1 - clamp01((now - (e.end - 0.4)) / 0.4));
    this.crowd.cheer = now >= M ? 1 : now >= M - 0.25 ? 0.5 : 0.1;
    this.crowd.update(dt);
    // the ball: up at the mast's top, down it in the last quarter hour, lit through the hour after
    if (this.ball && this.top) {
      const d = clamp01((now - (M - 0.25)) / 0.25);
      this.ball.position.y = this.top.y + 1.3 - d * 1.1;
      (this.ball.material as THREE.MeshStandardMaterial).emissiveIntensity = now >= M ? 2.2 + Math.sin(now * 400) * 1.2 : 1.6;
      this.ball.visible = now >= e.start - spec.lead;
    }
    const tower = this.place.tower!;
    const tb = { x0: this.w.ox + tower.x - 0.5, z0: this.w.oz + tower.z - 0.5, x1: this.w.ox + tower.x + tower.w + 0.5, z1: this.w.oz + tower.z + tower.d + 0.5 };
    if (now >= e.start && now < e.end) this.light(0, { ...tb, uid: tower.uid, mode: now >= M ? 'rainbow' : 'solid', a: 0xffc94d, strength: now >= M ? 1.4 : 0.8 + 0.3 * Math.sin(now * 60) });
    else this.light(0, null);
    // the whole city: a flash at midnight, then their lights chasing
    if (now >= M && now < e.end) this.light(1, { ...this.box, uid: -1, walls: true, mode: now < M + 0.12 ? 'flash' : 'chase', a: 0xffd166, b: 0x5ad1ff, strength: now < M + 0.12 ? 0.55 : 0.28 });
    else this.light(1, null);
    // fireworks for the first half hour of the year
    if (this.top && now >= M && now < M + 0.6) {
      this.fireT -= dt;
      while (this.fireT <= 0) {
        this.fireT += 0.22 + Math.random() * 0.3;
        const l = this.launchers[Math.floor(Math.random() * this.launchers.length)];
        const y = this.ctx.ground(l.x, l.z);
        this.rockets.push({ x: l.x, y, z: l.z, vy: 5 + Math.random() * 2, top: this.top.y + 1.5 + Math.random() * 3.5, colours: FIRE[Math.floor(Math.random() * FIRE.length)] });
      }
      if (now < M + 0.08 && Math.random() < dt * 30) {
        const P = this.ctx.particles, b = tower;
        P.slip({ x: this.w.ox + b.x + Math.random() * b.w, y: this.top.y * (0.6 + Math.random() * 0.4), z: this.w.oz + b.z + Math.random() * b.d, vx: (Math.random() - 0.5), vy: 0, vz: (Math.random() - 0.5), life: 9, colour: Math.random() < 0.5 ? 0xffffff : 0xffd166, size: 0.07 });
      }
    }
    for (const r of [...this.rockets]) {
      r.y += r.vy * dt;
      this.ctx.particles.trail(r.x, r.y, r.z);
      if (r.y >= r.top) {
        this.ctx.particles.burst(r.x, r.y, r.z, r.colours, 80 + Math.floor(Math.random() * 40), 3.2 + Math.random() * 1.6);
        this.rockets.splice(this.rockets.indexOf(r), 1);
      }
    }
  }

  dispose(): void {
    this.crowd.dispose();
    super.dispose();
  }
}
