import { httpUrl } from './online';
import type { PerfReport } from './perf';
import type { JourneyReport } from './journey';
import type { MusicStats } from '../game/music';
import type { StatsSave } from './stats';

/**
 * Play reports and feedback for the developer. Every few minutes of play the game sends a summary of
 * the game in hand — the fleet, its vehicles, the driving, the missions, the money, the doors bought,
 * the map explored and the deeds earned — to the TinyFleet server, which keeps the latest for each game
 * (its id travels in the save) and every mission it has ever been told of. Nothing personal is sent:
 * the profile name typed at the title, the fleet's name and what happened in the game.
 *
 * The developer reads it all on the server's private page (server/admin.ts). Sending is best effort:
 * no server, no network, and nothing is lost but the report.
 */

/** Seconds of play between reports; in a game's first EARLY seconds of play, every EARLY_EVERY, so where a new player stopped is seen. */
const EVERY = 120, EARLY = 900, EARLY_EVERY = 30;

interface ReportMission {
  id: number; tpl: string; title: string; kind: string; thread: string;
  giver: string; town: string | null;
  state: string; posted: number; ended: number | null; outcome: string | null;
  arc: string | null; objs: string[]; reward: string[]; why: string;
}

export interface Report {
  gid: string;
  /** The browser's own profile (the title's "Player 1"); online, `pid` and `online` are who the server knows. */
  player: { id: string; name: string };
  online: string | null;
  pid?: string | null;
  /** Online: whether the career's saves are landing (Online.saveState): why not, and when last tried, sent and kept. */
  saves?: { why: string; tried: number; sent: number; ack: number } | null;
  gen: number; save: number;
  where: string;
  fleet: { name: string; livery: [number, number]; logo: string } | null;
  seed: string; mode: string;
  start: [number, number] | null; cell: [number, number];
  played: number; day: number; hour: number;
  money: { cash: number; earned: number; fleetEarned: number; towed: number };
  metrics: Record<string, number> | null;
  delivered: { you: number; fleet: number };
  driven: { you: number; hired: number };
  vehicles: { uid: number; model: string; name: string; driver: string | null; rank: string | null; tiles: number; deliveries: number; earned: number; where: string }[];
  drivers: number;
  missions: ReportMission[];
  buildings: { key: string; kind: string; name: string; town: string; day: number; paid: number; took: number }[];
  explored: { cells: number; seen: number };
  deeds: { id: string; name: string; group: string; tier: number; value: number }[];
  hq: { grade: number; slots: number } | null;
  /** The device, settings, frame rate, first moments and errors (net/perf.ts). */
  perf?: PerfReport;
  /** The first fifteen minutes: milestones, what happened in order, and where they are now (net/journey.ts). */
  journey?: JourneyReport | null;
  /** This page load's listening (game/music.ts): the dev page's Analytics → Music. */
  music?: MusicStats;
  /** The game's whole life in counts (net/stats.ts): missions, models driven and owned, idle time, milestones. */
  stats?: StatsSave;
  /** The books' totals (game/books.ts): income by line and by who [you, crew, other], spend by line. */
  books?: { inc: Record<string, number[]>; out: Record<string, number> };
}

export function newGameId(): string {
  const b = new Uint8Array(12);
  try { crypto.getRandomValues(b); } catch { for (let i = 0; i < b.length; i++) b[i] = Math.floor(Math.random() * 256); }
  return Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
}

/**
 * This copy is a test, not a player's game: an automated or headless browser (the bots), or a page served from this
 * machine (a dev or preview server) other than the download launcher's port 47615. It sends no play reports, so
 * the dev page counts players only (the server turns such reports away too: server/analytics.ts testGame).
 */
export function testCopy(): boolean {
  if ((navigator as Navigator & { webdriver?: boolean }).webdriver || /HeadlessChrome/i.test(navigator.userAgent)) return true;
  const h = location.hostname;
  return (h === 'localhost' || h === '127.0.0.1' || h === '[::1]' || h === '0.0.0.0' || h.endsWith('.localhost')) && location.port !== '47615';
}

export class Reporter {
  /** The first report goes out a few seconds into a game, so even a game left at once is seen. */
  private timer = 5;
  private sentFirst = false;
  private sending = false;
  /** The play seconds the last report carried. */
  private played = 0;

  /**
   * `server`: where reports go (the online server's address); `build`: the report now, or null outside play;
   * `away`: told the page is going out of sight or away, before the report that goes with it is built.
   */
  constructor(private server: () => string, private build: (why: string) => Report | null, private away?: (why: string) => void) {
    window.addEventListener('pagehide', () => { this.away?.('leaving'); this.send(true, 'leaving'); });
    // a phone or a closed laptop may never fire pagehide: going out of sight sends one too
    document.addEventListener('visibilitychange', () => { if (document.hidden) { this.away?.('hidden'); this.send(true, 'hidden'); } });
  }

  private url(path: string): string {
    const base = httpUrl(this.server());
    return base ? `${base}${path}` : '';
  }

  /** A new game or a loaded one: the first report goes out soon. */
  restart(): void { this.timer = 5; this.sentFirst = false; }

  update(dt: number): void {
    this.timer -= dt;
    if (this.timer > 0) return;
    this.timer = !this.sentFirst ? 25 : this.played < EARLY ? EARLY_EVERY : EVERY;
    this.send(false, this.sentFirst ? 'timer' : 'first');
    this.sentFirst = true;
  }

  send(leaving: boolean, why = 'asked'): void {
    const url = this.url('/api/report');
    if (!url || this.sending || testCopy()) return;
    let r: Report | null;
    try { r = this.build(why); } catch (e) { console.warn('report:', e); return; }
    if (!r) return;
    this.played = r.played;
    const body = JSON.stringify(r);
    if (leaving && navigator.sendBeacon) {
      try { navigator.sendBeacon(url, new Blob([body], { type: 'text/plain' })); } catch { /* best effort */ }
      return;
    }
    this.sending = true;
    // text/plain keeps it a simple request: no CORS preflight from a downloaded copy on localhost
    fetch(url, { method: 'POST', headers: { 'content-type': 'text/plain' }, body, keepalive: body.length < 60000 })
      .catch(() => { /* offline: the next one will do */ })
      .finally(() => { this.sending = false; });
  }

  /** Send feedback; null when it went, or why it didn't. */
  async feedback(subject: string, text: string): Promise<string | null> {
    const url = this.url('/api/feedback');
    if (!url) return 'There’s no server to send it to from this copy of the game.';
    let r: Report | null = null;
    try { r = this.build('feedback'); } catch { /* feedback goes without the game's details */ }
    const body = JSON.stringify({
      subject, text,
      gid: r?.gid ?? null, player: r?.player.name ?? null, fleet: r?.fleet?.name ?? null, online: r?.online ?? null,
      seed: r?.seed ?? null, cell: r?.cell ?? null, day: r?.day ?? null, gen: r?.gen ?? null, where: location.host,
    });
    try {
      const res = await fetch(url, { method: 'POST', headers: { 'content-type': 'text/plain' }, body });
      if (res.ok) { this.send(false); return null; }
      if (res.status === 429) return 'That’s a lot of feedback at once: try again in a few minutes.';
      return 'The server wouldn’t take it just now. Try again later.';
    } catch {
      return 'Couldn’t reach the server. Check your connection and try again.';
    }
  }
}
