/**
 * The HQ window's Estate tab (docs/hqwindow.html, "Estate"): the old K window grown up. A totals strip,
 * filter chips and a sort, one row per lot with its last seven days as little bars, and the building's
 * own deed card beside the list (the inspector's, shared through deedCardHtml), so Sell, Mend and Make it
 * your HQ need no trip to the building. A lot on an island not in memory is "quiet": its last-known
 * numbers and a Find button.
 */
import { esc, money } from './cargoHud';
import { WEEK, deedIcon, type Deed, type Estate } from './estate';
import type { Economy } from './ledger';
import type { Fleet } from './fleet';
import { deedAct, deedCardHtml, type DeedCtx } from './inspect';
import { ESTATE } from './economy';
import { CHAIN_NAME, recipeBook, recipesOf } from './chains/recipes';
import { hoursText } from './chains/plantCard';
import { chainsShown } from './chains/shown';
import { cargoById } from './cargoTypes';

/** What a lot would fetch: today's quote while it is in memory, else what was paid at the resale rate (the metrics' basis). */
export const lotWorth = (estate: Estate, d: Deed): number => estate.saleValue(d.key) ?? Math.round((d.paid * ESTATE.sell) / 10) * 10;

type Filter = 'all' | 'paying' | 'quiet' | 'down' | 'plants' | `town:${string}`;
type Sort = 'week' | 'name' | 'town' | 'paid' | 'took' | 'bought' | 'next';
const SORT_LABEL: Record<Sort, string> = { week: 'Last 7 days', name: 'Name', town: 'Town', paid: 'Paid', took: 'Taken', bought: 'Bought', next: 'Next load' };

interface EstateTabHost extends DeedCtx {
  economy: Economy;
  /** Close the window and take the camera to the lot (and its card, once its county is in memory). */
  find(key: string, name: string): void;
  say(text: string): void;
  /** The game day, for the week's bars. */
  day(): number;
}

export class EstateTab {
  readonly el = document.createElement('div');
  private list = document.createElement('div');
  private pane = document.createElement('div');
  private top = document.createElement('div');
  private filter: Filter = 'all';
  private sort: Sort = 'week';
  sel = '';
  private selling = '';
  private html = '';
  private paneHtml = '';

  constructor(private estate: Estate, private fleet: Fleet, private host: EstateTabHost) {
    this.el.className = 'hq-estate';
    this.top.className = 'hq-etop';
    this.list.className = 'hq-elist';
    this.pane.className = 'hq-pane deed';
    const left = document.createElement('div');
    left.className = 'hq-eleft';
    left.append(this.top, this.list);
    this.el.append(left, this.pane);
    this.top.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-filter]');
      if (b) { this.filter = b.dataset.filter as Filter; this.render(true); }
    });
    this.top.addEventListener('change', (e) => {
      const t = e.target as HTMLSelectElement;
      if (t.dataset.sort !== undefined) { this.sort = t.value as Sort; this.render(true); }
    });
    this.list.addEventListener('click', (e) => {
      const row = (e.target as HTMLElement).closest<HTMLElement>('[data-key]');
      if (!row) return;
      this.sel = row.dataset.key!;
      this.selling = '';
      this.render(true);
    });
    // pointerdown, as on the inspector: the pane is redrawn as its numbers move
    this.pane.addEventListener('pointerdown', (e) => {
      const btn = (e.target as HTMLElement).closest<HTMLElement>('button[data-act]');
      if (!btn || btn.classList.contains('off')) return;
      e.preventDefault();
      const d = this.estate.deeds.get(this.sel);
      if (btn.dataset.act === 'find') { if (d) this.host.find(d.key, d.name); return; }
      const r = this.estate.resolve(this.sel);
      if (!r) return;
      const out = deedAct(this.host, r.w, r.b, btn.dataset.act!, this.selling);
      this.selling = out.selling;
      if (out.why) this.host.say(out.why);
      this.render(true);
    });
  }

  private rows(): Deed[] {
    const all = [...this.estate.deeds.values()];
    const keep = (d: Deed): boolean => {
      const r = this.estate.resolve(d.key);
      const down = !!r && !r.port && !!r.b.derelict;
      switch (this.filter) {
        case 'all': return true;
        case 'paying': return !!r && !down && this.estate.trailing(d).took > 0;
        case 'quiet': return !r;
        case 'down': return down;
        case 'plants': return recipesOf(d.kind).length > 0 && d.key.includes('#b');
        default: return d.townKey === this.filter.slice(5);
      }
    };
    const by: Record<Sort, (a: Deed, b: Deed) => number> = {
      // the week's best earners first, then the rest, then the quiet ones (as the K window had it)
      week: (a, b) => this.weekOrder(a) - this.weekOrder(b),
      name: (a, b) => a.name.localeCompare(b.name),
      town: (a, b) => (a.town || '~').localeCompare(b.town || '~'),
      paid: (a, b) => b.paid - a.paid,
      took: (a, b) => b.took - a.took,
      bought: (a, b) => b.day - a.day,
      // the plant whose next load is soonest first (docs/supplychains.html); doors that make nothing last
      next: (a, b) => this.nextIn(a) - this.nextIn(b),
    };
    return all.filter(keep).sort((a, b) => by[this.sort](a, b) || a.name.localeCompare(b.name));
  }

  /** The fleet's plants, while the supply chains show (a level 2 HQ, game/chains/shown.ts); undefined before. */
  private get plants(): EstateTabHost['plants'] { return chainsShown() ? this.host.plants : undefined; }

  /** Game hours to a plant's next load: 0 with one at the kerb, Infinity for a door that makes nothing or waits for inputs. */
  private nextIn(d: Deed): number {
    const v = this.plants?.view(d.key);
    if (!v) return Infinity;
    if (v.stock.length) return 0;
    return v.run && !v.waiting ? v.run.left : 1e6;
  }

  /** The chains strip (docs/supplychains.html): one row a chain the fleet has a door in, its doors as pips, what its plants have made and taken. */
  private chainsStrip(): string {
    const plants = this.plants;
    if (!plants) return '';
    const by = new Map<number, { kinds: Set<string>; have: Set<string>; made: number; fees: number }>();
    for (const [kind, rs] of recipeBook()) for (const r of rs) {
      const e = by.get(r.chain) ?? { kinds: new Set(), have: new Set(), made: 0, fees: 0 };
      e.kinds.add(kind);
      by.set(r.chain, e);
    }
    let any = false;
    for (const d of this.estate.deeds.values()) {
      const v = plants.view(d.key);
      if (!v) continue;
      for (const r of v.recipes) {
        const e = by.get(r.chain)!;
        if (e.have.has(d.kind)) continue;
        e.have.add(d.kind);
        e.made += v.made;
        e.fees += v.fees;
        any = true;
      }
    }
    if (!any) return '';
    const rows = [...by.entries()].filter(([, e]) => e.have.size).sort((a, b) => b[1].have.size - a[1].have.size).map(([n, e]) => {
      const pips = [...e.kinds].map((k) => `<i class="${e.have.has(k) ? 'on' : ''}" title="${esc(k)}"></i>`).join('');
      return `<div class="hq-chain"><b>${esc(CHAIN_NAME[n] ?? '')}</b><span class="pips">${pips}</span><small>${e.have.size} of ${e.kinds.size} kinds · ${e.made} made · ${money(e.fees)} in fees</small></div>`;
    }).join('');
    return `<div class="hq-chains">${rows}</div>`;
  }

  private weekOrder(d: Deed): number { return this.estate.resolve(d.key) ? -this.estate.trailing(d).took : 2e9; }

  /** The last seven game days at a door, oldest on the left. */
  private spark(d: Deed): string {
    const today = this.host.day();
    const vals = Array.from({ length: WEEK }, (_, k) => d.week.find((w) => w[0] === today - (WEEK - 1 - k))?.[1] ?? 0);
    const max = Math.max(1, ...vals);
    const bars = vals.map((v, k) => {
      const h = Math.max(v > 0 ? 1.5 : 0.5, (v / max) * 14);
      return `<rect x="${k * 6}" y="${16 - h}" width="4" height="${h}" rx="1"/>`;
    }).join('');
    return `<svg class="spark" viewBox="0 0 42 16" width="42" height="16" aria-label="takings over the last ${WEEK} days">${bars}</svg>`;
  }

  render(force = false): void {
    // before a level 2 HQ the chains' filter and sort aren't offered: one left on goes back to the plain view
    const chains = chainsShown();
    if (!chains && this.filter === 'plants') this.filter = 'all';
    if (!chains && this.sort === 'next') this.sort = 'week';
    const t = this.estate.totals();
    const deeds = [...this.estate.deeds.values()];
    const sale = deeds.reduce((s, d) => s + lotWorth(this.estate, d), 0);
    const towns = [...new Map(deeds.filter((d) => d.townKey).map((d) => [d.townKey, d.town])).entries()].sort((a, b) => a[1].localeCompare(b[1]));
    const chip = (f: Filter, label: string) => `<button type="button" class="chip${this.filter === f ? ' on' : ''}" data-filter="${esc(f)}">${esc(label)}</button>`;
    const top = `<div class="hq-totals"><b>${t.lots} lot${t.lots === 1 ? '' : 's'}</b> · ${money(t.paid)} paid · <em>${money(t.took)} taken</em> · sell for ${money(sale)} · last ${WEEK} days <em>+${money(t.week)}</em></div>
      ${this.chainsStrip()}
      <div class="hq-filters">${chip('all', 'All')}${chip('paying', 'Paying')}${chains ? chip('plants', 'Plants') : ''}${chip('quiet', 'Quiet')}${chip('down', 'Boarded up')}${towns.map(([k, n]) => chip(`town:${k}`, n)).join('')}
      <label class="sort">Sort <select data-sort>${(Object.keys(SORT_LABEL) as Sort[]).filter((s) => chains || s !== 'next').map((s) => `<option value="${s}"${s === this.sort ? ' selected' : ''}>${SORT_LABEL[s]}</option>`).join('')}</select></label></div>`;
    const rows = this.rows();
    if (!this.sel || !this.estate.deeds.has(this.sel)) this.sel = rows[0]?.key ?? '';
    const hqKey = this.fleet.hq?.key;
    const list = rows.map((d) => {
      const r = this.estate.resolve(d.key);
      const down = !!r && !r.port && !!r.b.derelict;
      const wk = this.estate.trailing(d);
      const lost = this.host.economy.lots.get(d.key)?.lost ?? 0;
      const bits: string[] = [];
      if (!r) bits.push('quiet: nobody is on that island');
      else if (down) bits.push('<b class="bad">boarded up</b> · pays nothing');
      else {
        bits.push(wk.loads ? `${wk.loads} load${wk.loads === 1 ? '' : 's'} in ${WEEK} days` : `nothing in ${WEEK} days`);
        if (wk.visits) bits.push(`${wk.visits} visit${wk.visits === 1 ? '' : 's'}`);
        if (d.today >= d.ceil - 0.5) bits.push('<b class="cap">ceiling reached today</b>');
        if (lost) bits.push(`${lost} spoiled`);
        // a plant's pip: what is next, and when (docs/supplychains.html)
        const v = this.plants?.view(d.key);
        if (v) {
          const next = v.stock[0] ? cargoById(v.stock[0].id) : v.run?.out ? cargoById(v.run.out) : cargoById(v.makes[0]);
          bits.push(v.stock.length ? `🔧 ${next?.icon ?? ''} ${v.stock.length} at the kerb` : v.run && !v.waiting ? `🔧 ${next?.icon ?? ''} in ${hoursText(v.run.left)}` : `🔧 ${esc(v.waiting.toLowerCase())}`);
        }
      }
      const back = d.took >= d.paid && d.paid > 0 ? ' <i class="back" title="Has paid for itself">●</i>' : '';
      const hq = d.key === hqKey ? ' <span class="hqmark" title="Your HQ">🏢 HQ</span>' : '';
      return `<button type="button" class="hq-erow${d.key === this.sel ? ' sel' : ''}${!r ? ' quiet' : down ? ' down' : ''}" data-key="${esc(d.key)}">
        <span class="ic">${deedIcon(d.kind, down)}</span>
        <span class="what"><b>${esc(d.name)}${back}${hq}</b><small>${esc(d.town || 'the countryside')} · bought day ${d.day + 1} · ${money(d.took)} taken of ${money(d.paid)}</small><small class="state">${bits.join(' · ')}</small></span>
        ${this.spark(d)}<span class="pay">${r && !down && wk.took > 0 ? `<em>+${money(wk.took)}</em>` : '<span class="q">—</span>'}</span></button>`;
    }).join('');
    const html = top + '\u0000' + (deeds.length
      ? list || '<p class="none">Nothing matches that filter.</p>'
      : '<p class="none">You own nothing yet. Click any building to see what it would cost and what it would pay: every load that starts or ends at its door pays its owner, whoever drives it.</p>');
    if (force || html !== this.html) {
      this.html = html;
      const [a, b] = html.split('\u0000');
      if (this.top.innerHTML !== a) this.top.innerHTML = a;
      this.list.innerHTML = b;
    }
    this.renderPane(force);
  }

  private renderPane(force: boolean): void {
    const d = this.estate.deeds.get(this.sel);
    let html: string;
    if (!d) html = '<p class="none">Pick a lot to see its card.</p>';
    else {
      const r = this.estate.resolve(d.key);
      const head = `<div class="gname"><h4>${esc(d.name)}</h4><span>${esc(d.town || 'the countryside')}</span><button type="button" class="find" data-act="find">Find</button></div>`;
      html = head + (r ? deedCardHtml(this.host, r.w, r.b, this.selling)
        : `<p class="gnone">Quiet: nobody is on that island, so it earns nothing until someone is (nothing earns off screen). Its books as last seen:</p>
          <div class="tiles"><div class="tile"><small>Paid</small><b>${money(d.paid)}</b><span>day ${d.day + 1}</span></div><div class="tile ${d.took > 0 ? 'earn' : 'dim'}"><small>Taken</small><b>${money(d.took)}</b><span>${d.ins} in · ${d.outs} out</span></div><div class="tile"><small>Sells for</small><b>${money(lotWorth(this.estate, d))}</b><span>at what was paid</span></div></div>
          <p class="gsub">Find takes the camera there; its full card, with Sell and Mend, comes up once its county has loaded.</p>`);
    }
    if (!force && html === this.paneHtml) return;
    this.paneHtml = html;
    this.pane.innerHTML = html;
  }
}
