/**
 * The company's books (docs/hqwindow.html, "Books"): every dollar in or out of the wallet, tagged at the
 * source with a line, kept per game day. Three fixed lists: income (by who earned it), spend, and capital
 * (sales, refunds, grants: money that moves but is never revenue). The order of each list is its colour
 * order in the charts and never changes.
 *
 * One row per game day, made on its first entry. A row also carries the day's closing net worth and cash
 * (stamped by the HQ window's host once a second), so the books can draw the company's whole life.
 */

export const IN_LINES = ['cargo', 'rent', 'contraband', 'missions', 'tolls', 'other', 'exploration'] as const;
/** The income lines a saved row holds in their first places; later lines go after the row's cash, so older saves still read. */
const SAVED_IN = IN_LINES.slice(0, 6);
const LATE_IN = IN_LINES.slice(6);
export const OUT_LINES = ['vehicles', 'parts', 'property', 'roads', 'earthworks', 'crew', 'fines', 'sundries'] as const;
export const CAP_LINES = ['vehicleSales', 'propertySales', 'refunds', 'grants'] as const;
export const WHO = ['you', 'crew', 'other'] as const;

type InLine = typeof IN_LINES[number];
export type OutLine = typeof OUT_LINES[number];
type CapLine = typeof CAP_LINES[number];
export type Who = typeof WHO[number];
/** What may be passed to Wallet.earn: revenue, or capital coming back. */
export type EarnLine = InLine | CapLine;

export const IN_LABEL: Record<InLine, string> = {
  cargo: 'Deliveries', rent: 'Rent', contraband: 'Contraband', missions: 'Missions & prizes', tolls: 'Tolls', other: 'Other', exploration: 'Exploration',
};
export const OUT_LABEL: Record<OutLine, string> = {
  vehicles: 'Vehicles', parts: 'Parts & paint', property: 'Property', roads: 'Roads & bridges', earthworks: 'Earthworks & bulldozing',
  crew: 'Crew', fines: 'Tows & fines', sundries: 'Fares & sundries',
};
export const CAP_LABEL: Record<CapLine, string> = {
  vehicleSales: 'Vehicle sales', propertySales: 'Property sales', refunds: 'Undo refunds', grants: 'Grants (cheats)',
};
export const WHO_LABEL: Record<Who, string> = { you: 'You', crew: 'Your crew', other: 'Others at your doors' };

export const isCap = (l: EarnLine): l is CapLine => (CAP_LINES as readonly string[]).includes(l);

/** One game day of the books. */
export interface Row {
  day: number;
  /** Income by line, then by who: [you, crew, other]. */
  inc: Record<InLine, [number, number, number]>;
  out: Record<OutLine, number>;
  cap: Record<CapLine, number>;
  /** What hired drivers kept of their deliveries: not your money, but what the crew cost. */
  kept: number;
  /** The day's net worth and cash, as last stamped. */
  worth: number;
  cash: number;
}

/** Saved as one flat tuple a day: [day, inc 6×3, out 8, cap 4, kept, worth, cash, exploration×3]; the last three are missing before SAVE 26. */
type SavedRow = number[];
export interface BooksSave {
  rows: SavedRow[];
  /** Revenue earned before the books were opened (a save from before version 22). */
  pre?: number;
  /** Roads built by the player, ever: [tiles, bridges, tunnels]. */
  built?: [number, number, number];
}

/** Rows kept day by day; past this many, the oldest are folded into `pre`-style totals by year. */
const MAX_ROWS = 1500;

const zeroRow = (day: number): Row => ({
  day,
  inc: Object.fromEntries(IN_LINES.map((l) => [l, [0, 0, 0]])) as Row['inc'],
  out: Object.fromEntries(OUT_LINES.map((l) => [l, 0])) as Row['out'],
  cap: Object.fromEntries(CAP_LINES.map((l) => [l, 0])) as Row['cap'],
  kept: 0, worth: 0, cash: 0,
});

export const revenueOf = (r: Row): number => IN_LINES.reduce((s, l) => s + r.inc[l][0] + r.inc[l][1] + r.inc[l][2], 0);
export const spendOf = (r: Row): number => OUT_LINES.reduce((s, l) => s + r.out[l], 0);
export const capitalOf = (r: Row): number => CAP_LINES.reduce((s, l) => s + r.cap[l], 0);

export class Books {
  /** Newest last. */
  rows: Row[] = [];
  /** Revenue before the books opened. */
  pre = 0;
  /** Bumped on every entry, so a window knows when to redraw. */
  version = 0;
  /** Roads the player has built, ever (undoing one doesn't take it off): tiles, bridges and tunnels. */
  built = { tiles: 0, bridges: 0, tunnels: 0 };

  constructor(private day: () => number) {}

  private today(): Row {
    const d = this.day();
    const last = this.rows[this.rows.length - 1];
    if (last && last.day === d) return last;
    // a clock that went back (an online world's server clock, a cheat): the row for that day, or a new one in order
    const at = this.rows.findIndex((r) => r.day >= d);
    if (at >= 0 && this.rows[at].day === d) return this.rows[at];
    const r = zeroRow(d);
    if (last) { r.worth = last.worth; r.cash = last.cash; }
    if (at < 0) this.rows.push(r); else this.rows.splice(at, 0, r);
    if (this.rows.length > MAX_ROWS) this.fold();
    return r;
  }

  income(line: InLine, who: Who, amount: number): void {
    if (!(amount > 0)) return;
    this.today().inc[line][WHO.indexOf(who)] += amount;
    this.version++;
  }

  spend(line: OutLine, amount: number): void {
    if (!(amount > 0)) return;
    this.today().out[line] += amount;
    this.version++;
  }

  capital(line: CapLine, amount: number): void {
    if (!(amount > 0)) return;
    this.today().cap[line] += amount;
    this.version++;
  }

  kept(amount: number): void {
    if (!(amount > 0)) return;
    this.today().kept += amount;
    this.version++;
  }

  /** A road laid by the player: its tiles, and how many of its spans are bridges and tunnels. */
  road(tiles: number, bridges: number, tunnels: number): void {
    this.built.tiles += tiles;
    this.built.bridges += bridges;
    this.built.tunnels += tunnels;
    this.version++;
  }

  /** The day's closing figures (called often: the last call of a day is what it closed on). */
  stamp(worth: number, cash: number): void {
    const r = this.today();
    r.worth = worth;
    r.cash = cash;
  }

  /** Every dollar of revenue the company has earned, books and before. */
  revenue(): number { return this.pre + this.rows.reduce((s, r) => s + revenueOf(r), 0); }

  /** Rows from day `from` to day `to`, inclusive. */
  range(from: number, to: number): Row[] { return this.rows.filter((r) => r.day >= from && r.day <= to); }

  /** Sum rows into one (its day the first's). */
  static sum(rows: Row[], day = rows[0]?.day ?? 0): Row {
    const t = zeroRow(day);
    for (const r of rows) {
      for (const l of IN_LINES) for (let k = 0; k < 3; k++) t.inc[l][k] += r.inc[l][k];
      for (const l of OUT_LINES) t.out[l] += r.out[l];
      for (const l of CAP_LINES) t.cap[l] += r.cap[l];
      t.kept += r.kept;
    }
    const last = rows[rows.length - 1];
    if (last) { t.worth = last.worth; t.cash = last.cash; }
    return t;
  }

  /** Too many days: fold the oldest half into one row (its day the first), so the totals still reconcile. */
  private fold(): void {
    const n = Math.floor(this.rows.length / 2);
    const old = this.rows.splice(0, n);
    this.rows.unshift(Books.sum(old));
  }

  clear(): void { this.rows = []; this.pre = 0; this.built = { tiles: 0, bridges: 0, tunnels: 0 }; this.version++; }

  toSave(): BooksSave {
    const r2 = (v: number) => Math.round(v * 100) / 100;
    return {
      rows: this.rows.map((r) => [
        r.day,
        ...SAVED_IN.flatMap((l) => r.inc[l].map(r2)),
        ...OUT_LINES.map((l) => r2(r.out[l])),
        ...CAP_LINES.map((l) => r2(r.cap[l])),
        r2(r.kept), Math.round(r.worth), Math.round(r.cash),
        ...LATE_IN.flatMap((l) => r.inc[l].map(r2)),
      ]),
      ...(this.pre ? { pre: Math.round(this.pre) } : {}),
      ...(this.built.tiles ? { built: [this.built.tiles, this.built.bridges, this.built.tunnels] as [number, number, number] } : {}),
    };
  }

  /** `earned`: an old save's lifetime counter, which becomes the "before the books" total. */
  fromSave(s: BooksSave | undefined, earned = 0): void {
    this.rows = [];
    this.pre = 0;
    this.built = { tiles: 0, bridges: 0, tunnels: 0 };
    this.version++;
    if (!s) { this.pre = Math.max(0, earned); return; }
    this.pre = s.pre ?? 0;
    if (s.built) this.built = { tiles: s.built[0] || 0, bridges: s.built[1] || 0, tunnels: s.built[2] || 0 };
    for (const t of s.rows ?? []) {
      if (!Array.isArray(t) || t.length < 1 + 18 + 8 + 4 + 3) continue;
      const r = zeroRow(t[0]);
      let k = 1;
      for (const l of SAVED_IN) r.inc[l] = [t[k++] || 0, t[k++] || 0, t[k++] || 0];
      for (const l of OUT_LINES) r.out[l] = t[k++] || 0;
      for (const l of CAP_LINES) r.cap[l] = t[k++] || 0;
      r.kept = t[k++] || 0;
      r.worth = t[k++] || 0;
      r.cash = t[k++] || 0;
      for (const l of LATE_IN) r.inc[l] = [t[k++] || 0, t[k++] || 0, t[k++] || 0];
      this.rows.push(r);
    }
    this.rows.sort((a, b) => a.day - b.day);
  }
}
