/**
 * The mission bus: the moments the game already has, told to whichever objective is listening. Nothing
 * on it is invented for missions — a delivery, an arrival, a ferry landing, a stamp, a part fitted, a
 * vehicle bought — except the two a race and a tow end with.
 */
import type { CargoItem } from '../cargo';
import type { SlotId } from '../parts';
import type { MakeKind } from './model';

interface BusEvents {
  delivered: { it: CargoItem };
  /** A delivery by anybody's hand counts for 'loads' only when it was the player's. */
  ferried: { from: string; to: string };
  stamped: { what: 'biome' | 'arch' | 'wonder' | 'town' | 'island'; key: string; name: string };
  fitted: { slot: SlotId; tier: number };
  bought: { what: 'vehicle' | 'building'; id: string };
  raceEnd: { id: number; won: boolean; margin: number };
  towEnd: { id: number; ok: boolean; snaps: number; scrapes: number };
  /** A night op is over: how well it went (0..1) and the line for the Done list. */
  opEnd: { id: number; ok: boolean; score: number; line: string };
  /**
   * A tail is over (game/tail): followed home unseen (`ok`, `made` false), or made but chased down (`ok` and
   * `made`), or lost; `score` 0..1 is how close to unseen it stayed, and `line` the Done list's.
   */
  tailEnd: { id: number; ok: boolean; made: boolean; score: number; line: string };
  /** Something made with the player's tools (main.ts): road tiles laid, a vehicle unlocked, a building asked of a town. */
  made: { what: MakeKind; n: number; at?: { x: number; z: number; cell: [number, number] } };
  /** A handbrake slide round a corner, told by the first drive's guide. */
  drifted: { dir: 'left' | 'right' };
  /** A clean lap of a circuit, and where the player finished a race there (0: never started). */
  circuitLap: { key: string; secs: number };
  circuitRace: { key: string; place: number; of: number };
}

type Handler<K extends keyof BusEvents> = (e: BusEvents[K]) => void;

export class Bus {
  private map = new Map<keyof BusEvents, Set<Handler<never>>>();

  on<K extends keyof BusEvents>(k: K, fn: Handler<K>): () => void {
    let set = this.map.get(k);
    if (!set) this.map.set(k, (set = new Set()));
    set.add(fn as Handler<never>);
    return () => set!.delete(fn as Handler<never>);
  }

  emit<K extends keyof BusEvents>(k: K, e: BusEvents[K]): void {
    for (const fn of [...(this.map.get(k) ?? [])]) (fn as Handler<K>)(e);
  }
}
