import { DRIFT_LESSONS, type Missions } from './missions/missions';

/**
 * A Friend's Handbrake and Drift the Block, out of the first drive (the user, 8 Nov 2026). They were its fourth and
 * fifth missions; now they come later, at diamonds like the getting-started missions (game/fleetTrack.ts): offered
 * here, opened on their card the next time the player stops, and locked as those are (no turning down).
 *
 *   first:friend  drive to a friend's Auto Shop for a free handbrake, for a car without one
 *   first:drift   drift round a left corner and a right one, once the car has a handbrake
 *
 * Neither comes before LESSONS_AT seconds of play, nor while the first drive runs, nor to a player who has already
 * made DRIFTS_KNOWN handbrake drifts: they know it. A car that already has a handbrake skips the friend.
 *
 * This also counts the drifts, for anything: each one the player makes is told on the missions' bus (`drifted`, which
 * Drift the Block and the drift meets' entries step on) and added to the missions' saved `drifts`. Before 8 Nov 2026 only
 * the first drive's guide watched for them, so a drift meet's entry never counted one.
 */

/** A drift counts once the tail has slid this far (tiles) and the car has swung this much (radians) in one slide. */
export const DRIFT_SLIDE = 0.6, DRIFT_YAW = 0.8;
/** A counted drift is told when the slide ends, or this many seconds after it counted if it goes on. */
const SETTLE = 1.5;
/** Seconds of play before either is offered (the user, 8 Nov 2026: 30 minutes or more). */
export const LESSONS_AT = 30 * 60;
/** Drifts after which neither is offered: the player can already do it. */
export const DRIFTS_KNOWN = 2;
/** A lesson with nowhere to happen (no shop in reach) is looked for again this much later, s. */
const LOOK_AGAIN = 90;
const [FRIEND, DRIFT] = DRIFT_LESSONS;

export interface DriftLessonsHost {
  ms: Missions;
  /** A card, the journal or a menu is up: no new mission is put in front of it. */
  busy(): boolean;
  /** Seconds this game has been played (unpaused), saved with it. */
  played(): number;
  /** The car being driven, while there is one in play: how far its tail has slid this drift (tiles) and its heading. */
  car(): { slide: number; heading: number } | null;
  /** The vehicle being driven has a handbrake. */
  handbrake(): boolean;
}

export class DriftLessons {
  /** The slide being watched: on, the swing so far, the last heading, and a counted drift waiting to be told. */
  private d = { on: false, yaw: 0, last: 0, dir: null as 'left' | 'right' | null, t: 0, counted: false };
  private wait = 0;
  private clock = 0;
  private later = 0;

  constructor(private host: DriftLessonsHost) {}

  /** Every frame. `playing`: the game is on screen and the player is driving. */
  update(dt: number, playing: boolean): void {
    this.clock += dt;
    if (playing) this.watch(dt);
    this.offer(dt);
  }

  /** Watch the tail: a slide far enough, swinging the car far enough, is a drift that way. */
  private watch(dt: number): void {
    const c = this.host.car(), d = this.d;
    if (!c) { d.on = false; this.tell(); return; }
    if (c.slide > 0.05) {
      if (!d.on) { d.on = true; d.yaw = 0; d.last = c.heading; d.counted = false; }
      d.yaw += Math.atan2(Math.sin(c.heading - d.last), Math.cos(c.heading - d.last));
      d.last = c.heading;
      if (!d.counted && c.slide >= DRIFT_SLIDE && Math.abs(d.yaw) >= DRIFT_YAW) {
        d.counted = true;
        d.dir = d.yaw > 0 ? 'left' : 'right';
        d.t = SETTLE;
      }
    } else d.on = false;
    if (d.dir) { d.t -= dt; if (!d.on || d.t <= 0) this.tell(); }
  }

  private tell(): void {
    const dir = this.d.dir;
    if (!dir) return;
    this.d.dir = null;
    const ms = this.host.ms;
    ms.drifts++;
    ms.bus.emit('drifted', { dir });
  }

  /** Once a second: the friend's handbrake or the drift, when its time has come. */
  private offer(dt: number): void {
    this.wait -= dt;
    if (this.wait > 0) return;
    this.wait = 1;
    const h = this.host, ms = h.ms;
    if (ms.intro > 0 || ms.drifts >= DRIFTS_KNOWN || h.played() < LESSONS_AT || h.busy() || this.later > this.clock) return;
    // one at a time: the drift waits for the handbrake's trip to be done
    if (ms.list.some((q) => DRIFT_LESSONS.includes(q.tpl) && (q.state === 'offered' || q.state === 'active'))) return;
    const had = (id: string) => ms.done.has(id) || ms.list.some((q) => q.tpl === id && q.state !== 'rejected');
    // with a handbrake (the friend's, or one bought or stock) the drift; without, the friend's, once
    const id = h.handbrake() ? DRIFT : FRIEND;
    if (had(id) || ms.gateOf(id)) return;
    ms.force(id);
    const f = ms.list.find((q) => q.tpl === id && q.state === 'offered');
    // nowhere near to happen: look again in a while rather than every second
    if (!f) { this.later = this.clock + LOOK_AGAIN; return; }
    // offered on its card the next time the player stops (Missions.maybeOffer), and waiting at its diamond
    f.shown = false;
  }
}
