import * as THREE from 'three';
import { N, heightAt, type World } from '../../world/tiles';
import { GroundRing, drapeMat, laidY } from '../../render/drape';
import { aimCargoMarker, buildCargoMarker, disposeCargoMarker, poseCargoMarker, type CargoMarker } from '../../render/cargoMarkers';
import type { CargoClass, VehicleDef } from '../vehicles';
import type { Door } from '../cargo';
import { esc, type ExtraRow } from '../cargoHud';
import { startPrompt } from '../startPrompt';
import { MEDAL_NAME, MELT_S, RUSH, RUSH_KIND, SLOW_R, SLOW_V, fits, medalOf, secsOf, type Family } from './kinds';
import type { CellDoc, ServerMsg, Welcome } from '../../../shared/protocol';
import { RUSH_HELD_PER_DAY, RUSH_YEAR_HOURS, type RushBoard, type RushRow } from '../../../shared/rushes';
import type { Online, OnlineExtra } from '../../net/online';
import { chip, css } from '../firmSpec';
import { payHeld } from '../challenges/pay';
import { pump, rushesOf, type RushSite } from './sites';
import type { RushCrew } from './crew';
import type { Unit } from '../fleet';
import { inScope, scopeMode } from '../../net/boardScope';

/**
 * Rushes in the game (docs/rushes.html, phases 1–2): the one rush on offer, waiting at its A as a mission diamond;
 * the offer card when the player stops there, to accept (Enter) or decline (Backspace); the countdown; five minutes
 * of loading at A's cargo ring with Space (a pile that never runs out: the hold fills to the brim each time) and
 * unloading by stopping at B, by road, sea, air or rail, with the player's followers and drivers on Work nearby
 * running the same loop on their own (game/rushes/crew.ts); each kind's twist; the bell, the medal and the pay. Once run, a rush doesn't come round
 * for that player again for a game year (RUSH.waitHours), kept in the save. Only one rush is offered at a time,
 * and it takes one of the two diamonds the map shows (Missions.onMap).
 *
 * Phase 3: online, the run is told to the server as it goes (server/rushes.ts checks it) and posted to the rush's
 * board for the game year, Solo and Fleet; the Fleet board's holder is paid ◆ a game day; the Standings tab lists
 * every rush run with its boards. Long rushes (ten minutes) come later in the game; the card says which drivers
 * on Work will join, and its button leaves them at work.
 */

interface RushesHost {
  scene: THREE.Scene;
  /** Rushes may be offered: playing, past the first drive. */
  enabled(): boolean;
  worlds(): World[];
  worldAt(cx: number, cz: number): World | null;
  /** The player at the wheel, world tiles (`y` the vehicle's height); null when not driving. */
  player(): { x: number; z: number; y: number; v: number; def: VehicleDef } | null;
  /** Game hours since the world began, and the season (0 spring … 3 winter). */
  hours(): number;
  season(): number;
  /** Free room in the hold (with the formation's, as it stands now), units; the classes and units the formation lends. */
  room(def: VehicleDef): number;
  /** A word floated over the vehicle: "Stop first", or (`good`) what came aboard. */
  float(text: string, good?: boolean): void;
  /** The hold a follower lends the player's now (0 unless it is in formation). */
  lentBy(u: Unit): number;
  lent(): { classes: CargoClass[]; units: number; names: string[] };
  /** A long rush may be offered: the HQ's grade and the fleet's size are up to it. */
  longOk(): boolean;
  /** ◆ for holding a board, on its own line of the account (`key` the board's id). */
  gems(n: number, what: string, key: string): void;
  /** A rush done: the deed (gold on a kind) and the paper's line. */
  done(kind: string, name: string, units: number, medal: number, where: string): void;
  /** Something the Standings tab shows has changed. */
  refresh(): void;
  modelName(m: string): string;
  /** Units of the rush aboard, kept out of the hold's room for anything else. */
  reserve(n: number): void;
  pay(n: number, what: string): void;
  say(title: string, body: string): void;
  beep(final: boolean): void;
  /** Route arrows to a place (null takes them down). */
  route(to: { x: number; z: number; key: string; near: number } | null): void;
  /** The Storm Rush's rain: on, and off again at the bell. */
  rain(on: boolean): void;
  crew: RushCrew;
}

export interface RushSave {
  /** Rush key → the game hour it may be offered to this player again. */
  waits: Record<string, number>;
  /** Rush key → best units and medal. */
  best?: Record<string, [number, number]>;
}

type State = 'idle' | 'count' | 'run';
/** How often (real s) the offer is chosen again. */
const PICK_EVERY = 0.5;
/** The countdown before the clock starts, seconds. */
const COUNT = 3;
/** The rain comes this many seconds before the bell (the Storm Rush). */
const RAIN_AT = 120;
/** A knock this hard tips a cask off the top (the Pint Rush), at most one a second. */
const SPILL_AT = 0.35;

const FAMILY_NAME: Record<Family, string> = { road: 'A road vehicle', sea: 'A boat', air: 'A helicopter or light aircraft', rail: 'A train' };
/** The cargo model the pile at A shows (render/cargoModels.ts, by cargo type id), by kind. */
const PILE_MODEL: Record<string, string> = {
  brick: 'timber', harvest: 'grain', gravel: 'stone', post: 'parcels', pint: 'beer', melt: 'iceCream', match: 'fans', school: 'students',
  storm: 'reliefConvoy', fleet: 'goods', ferry: 'passengers', catch: 'fish', lifeline: 'reliefConvoy', airlift: 'reliefConvoy', coal: 'coal',
};
/** The pile's hoop (gold, the rush's own) and B's disc (the green every drop wears, cargo.ts DEST_COLOR). */
const PILE_GOLD = 0xf2b33b, DROP_GREEN = 0x39d353;

export class Rushes implements OnlineExtra {
  state: State = 'idle';
  /** The Fleet boards held now (server-told), boards as last sent by id, and the game year the server counts. */
  held: string[] = [];
  private boards = new Map<string, RushBoard>();
  private year = -1;
  private askedAt = 0;
  /** The card's choice: the drivers on Work nearby join the rush (its button leaves them at work). */
  private crewOn = true;
  /** This run: one vehicle alone (on the Solo board too), how many vehicles took part, and its clock. */
  private solo = true;
  private vehicles = 1;
  private secs = RUSH.secs;
  private waits = new Map<string, number>();
  private rests = new Map<string, number>();
  private best = new Map<string, [number, number]>();
  /** The rush on offer, or running. */
  private site: RushSite | null = null;
  private pickT = 0;
  /** A rush offered from the console whatever the hour, season or day (pr.rushes.offerKey). */
  private forced = '';
  /** Seconds since Space, in game frames (a pause stops it): the countdown, then the run. */
  private t = 0;
  private lastCount = 0;
  /** The player's goods aboard, by when each lot came aboard (the Melt Rush's clock). */
  private lots: { n: number; at: number }[] = [];
  private units = 0;
  private trips = 0;
  private hold = 0;
  private paid = 0;
  private lost = 0;
  private crewN = 0;
  /** The School Run: came into the slow zone too fast with pupils aboard. */
  private late = false;
  private rained = false;
  private spillT = 0;
  private cardUp = false;
  private root = new THREE.Group();
  private rings: { a: GroundRing[]; b: GroundRing[]; beams: THREE.Mesh[] } | null = null;
  /** The cargo ring at A (the goods on their hoop, as any load waits) and the drop's disc at B. */
  private pile: { m: CargoMarker; drop: CargoMarker; key: string } | null = null;
  private card = document.createElement('div');
  private strip = document.createElement('div');
  private count = document.createElement('div');
  private cardSig = '';
  /** What the last frame saw, for pr.rushes.state(): a player at the wheel, nothing else up, and how far from A. */
  private seen = { p: false, free: false, dA: -1 };

  constructor(private online: Online, private host: RushesHost) {
    this.root.name = 'rushes';
    host.scene.add(this.root);
    this.card.className = 'rush-card';
    this.strip.className = 'rush-strip';
    this.count.className = 'race-count';
    this.card.hidden = this.strip.hidden = this.count.hidden = true;
    document.body.append(this.card, this.strip, this.count);
    injectCss();
    // the card's buttons: accept, decline, and the drivers on Work nearby in or out
    this.card.addEventListener('pointerdown', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-crew], [data-act]');
      if (!b) return;
      e.preventDefault();
      e.stopPropagation();
      if (b.dataset.act === 'yes') { this.accept(); return; }
      if (b.dataset.act === 'no') { this.giveUp(); return; }
      this.crewOn = !this.crewOn;
      this.cardSig = '';
    });
    // Enter accepts the card while it is up (Backspace declines it: main.ts giveUp)
    window.addEventListener('keydown', (e) => {
      if (!this.cardUp || this.state !== 'idle' || (e.code !== 'Enter' && e.code !== 'NumpadEnter')) return;
      if (this.accept()) { e.preventDefault(); e.stopPropagation(); }
    }, true);
  }

  // ---- the online session (net/online.ts OnlineExtra) ----

  welcome(w: Welcome): void { this.held = w.rush?.held ?? []; }
  cell(_k: string, _doc: CellDoc): void { /* boards are asked for by the tab and told at the end of a run */ }
  ready(): void { this.ask(true); }
  frame(): void { /* driven by update() */ }
  forget(): void { /* nothing kept per cell */ }
  reset(): void { this.held = []; this.boards.clear(); }

  got(m: ServerMsg): boolean {
    switch (m.t) {
      case 'rushBoards':
        for (const b of m.rows) this.boards.set(b.id, b);
        this.held = m.held;
        this.year = m.year;
        this.host.refresh();
        return true;
      case 'rushRes': {
        if (m.b) this.boards.set(m.b.id, m.b);
        if (!m.ok) { this.host.say('⏱ Not on the board', `The server didn’t count that run (${m.why ?? 'unknown'}). The pay stands; the board doesn’t.`); return true; }
        const b = m.b;
        if (b && m.rec) {
          const you = this.solo ? b.you.solo : b.you.fleet;
          const n = this.solo ? b.nSolo : b.nFleet;
          this.host.say(`⏱ ${b.name}: #${you?.place ?? '?'} of ${n}${this.solo ? ' solo' : ''}`, m.held ? `You hold its Fleet board · ◆ ${RUSH_HELD_PER_DAY} a game day while it’s yours` : `Fleet leader ${b.fleet[0]?.name ?? 'nobody'} with ${b.fleet[0]?.s ?? 0}`);
        }
        this.host.refresh();
        return true;
      }
      case 'rushHeld':
        if (m.lost) this.host.say('⏱ Rush board taken', `Another fleet beat you at ${m.lost} · its ◆ stops`);
        else if (m.held.some((id) => !this.held.includes(id))) this.host.say('⏱ You hold a rush board', `◆ ${RUSH_HELD_PER_DAY} a game day while it’s yours`);
        this.held = m.held;
        this.host.refresh();
        return true;
      default: return false;
    }
  }

  /** A game hour: each Fleet board held pays its share of ◆ a day. */
  hourly(): void {
    if (!this.online.active) return;
    payHeld(this.held, (id) => this.boards.get(id)?.name ?? 'a rush', (n, what, key) => this.host.gems(n, `Rush board: ${what}`, `rush:${key}`));
  }

  /** Boards held, for the Diamonds tab. */
  paying(): { name: string; perDay: number }[] {
    return this.online.active ? this.held.map((id) => ({ name: this.boards.get(id)?.name ?? id, perDay: RUSH_HELD_PER_DAY })) : [];
  }

  private ask(force = false): void {
    const now = performance.now();
    if (!this.online.active || (!force && now - this.askedAt < 5000)) return;
    this.askedAt = now;
    this.online.post({ t: 'rushBoards', keys: [...new Set([...this.best.keys(), ...this.waits.keys()])].slice(0, 40) });
  }

  /** The countdown: the vehicle is held still. */
  get holding(): boolean { return this.state === 'count'; }

  private get aboard(): number { return this.lots.reduce((n, l) => n + l.n, 0); }

  // ---- the save ----

  toSave(): RushSave {
    const now = this.host.hours();
    const waits: Record<string, number> = {};
    for (const [k, h] of this.waits) if (h > now) waits[k] = Math.round(h * 100) / 100;
    return { waits, best: Object.fromEntries(this.best) };
  }

  load(s: RushSave | undefined): void {
    this.stop();
    this.waits = new Map(Object.entries(s?.waits ?? {}));
    this.best = new Map(Object.entries(s?.best ?? {}));
    this.rests.clear();
    this.site = null;
  }

  // ---- the offer ----

  /** The rush's diamond for the missions' doors (missions/wire.ts syncDoors), or null. */
  door(): Door | null {
    const s = this.site;
    if (!s || this.state !== 'idle' || !this.host.enabled()) return null;
    const w = this.host.worldAt(s.cx, s.cz);
    if (!w) return null;
    return { key: `rush:${s.key}`, x: s.a.x, z: s.a.z, y: this.ground(s.a.x, s.a.z) ?? heightAt(w, s.a.x - w.ox, s.a.z - w.oz), name: s.kind.name, icon: s.kind.icon, look: 'mission' };
  }

  /** Whether a rush has one of the map's diamonds. */
  up(): boolean { return !!this.door(); }

  private canRun(s: RushSite, def: VehicleDef): boolean { return fits(s.kind, def, this.host.lent().classes); }

  private open(s: RushSite, def: VehicleDef | null): boolean {
    const h = this.host.hours();
    if ((this.waits.get(s.key) ?? -Infinity) > h || (this.rests.get(s.key) ?? -Infinity) > h) return false;
    if (s.key === this.forced) return !def || this.canRun(s, def);
    if (s.kind.long && !this.host.longOk()) return false;
    const hour = ((h % 24) + 24) % 24;
    if (hour < s.kind.hours[0] || hour >= s.kind.hours[1]) return false;
    if (s.kind.season !== undefined && s.kind.season !== this.host.season()) return false;
    // Saturday and Sunday, as the markets count the week (events/calendar.ts: day % 7 === 5 is a Saturday)
    if (s.kind.weekend && Math.floor(h / 24) % 7 < 5) return false;
    return !def || this.canRun(s, def);
  }

  /** The one rush on offer: the one up stays while it can be run, else the nearest that can. */
  private pick(): void {
    const p = this.host.player();
    if (!p) return;
    if (this.site && this.open(this.site, p.def) && Math.hypot(this.site.a.x - p.x, this.site.a.z - p.z) <= RUSH.offerR * 1.2) return;
    const was = this.site;
    this.site = null;
    // the nearest short and the nearest long: the long one is the one on a third of the game days it is there
    let short: RushSite | null = null, long: RushSite | null = null, ds = RUSH.offerR, dl = RUSH.offerR;
    for (const w of this.host.worlds()) {
      for (const s of rushesOf(w) ?? []) {
        const d = Math.hypot(s.a.x - p.x, s.a.z - p.z);
        if (s.kind.long ? d >= dl : d >= ds) continue;
        if (!this.open(s, p.def)) continue;
        if (s.kind.long) { dl = d; long = s; } else { ds = d; short = s; }
      }
    }
    const day = Math.floor(this.host.hours() / 24);
    const longDay = (Math.imul(day + 1, 2654435761) >>> 0) % 1000 < RUSH.longShare * 1000;
    this.site = long && (!short || longDay) ? long : short;
    if (this.site && this.site.key !== was?.key) {
      const s = this.site, dx = s.a.x - p.x, dz = s.a.z - p.z;
      this.host.say(`${s.kind.icon} ${s.kind.name}`, `${s.a.name}, ${Math.round(Math.hypot(dx, dz))} tiles ${compass(dx, dz)} · five minutes, as much as you can carry to ${s.b.name} · go to the diamond`);
    }
  }

  // ---- each frame ----

  /** Enter (or the card's Accept): the countdown starts. Whether it did. */
  accept(): boolean {
    const p = this.host.player();
    if (this.state !== 'idle' || !this.cardUp || !this.site || !p || !this.canRun(this.site, p.def)) return false;
    this.begin(this.site, p.def);
    return true;
  }

  /**
   * Space: in A's ring through a run, the hold fills to the brim from the pile (stopped, as any load is taken on);
   * the countdown swallows it. Whether it was this one's: anywhere else it is the cargo's as usual.
   */
  space(): boolean {
    const p = this.host.player(), s = this.site;
    if (this.state === 'count') return true;
    if (this.state !== 'run' || !s || !p) return false;
    if (Math.hypot(s.a.x - p.x, s.a.z - p.z) > RUSH.rings[s.kind.family]) return false;
    if (!fits(s.kind, p.def, this.host.lent().classes)) { this.host.float(`Can’t carry ${s.kind.goods}`); return true; }
    if (!this.stopped(p, s.kind.family)) { this.host.float(p.def.kind === 'air' ? 'Land first' : 'Stop first'); return true; }
    this.fill(p.def);
    return true;
  }

  /** As much as the hold takes comes aboard from the pile, which never runs out. */
  private fill(def: VehicleDef): void {
    const room = this.host.room(def);
    if (room <= 0) { this.host.float('Hold full'); return; }
    this.lots.push({ n: room, at: this.t - COUNT });
    this.host.reserve(this.aboard);
    this.host.float(`+${room} ${this.site!.kind.goods}`, true);
    this.host.beep(false);
  }

  /** Backspace: a run given up (it counts), or the card turned down. Whether it was this one's. */
  giveUp(): boolean {
    if (this.state === 'run' || this.state === 'count') { this.finish(true); return true; }
    if (this.state === 'idle' && this.cardUp && this.site) {
      this.rests.set(this.site.key, this.host.hours() + RUSH.restHours);
      this.host.say(`${this.site.kind.name} declined`, 'It may come round again later today');
      this.site = null;
      return true;
    }
    return false;
  }

  /** The vehicle hit something (main's impact): the Pint Rush tips a cask off the top. */
  knock(strength: number): void {
    const s = this.site;
    if (this.state !== 'run' || !s || s.kind.twist !== 'spill' || strength < SPILL_AT || this.t < this.spillT || !this.lots.length) return;
    this.spillT = this.t + 1;
    const last = this.lots[this.lots.length - 1];
    last.n--;
    if (!last.n) this.lots.pop();
    this.lost++;
    this.host.reserve(this.aboard);
    this.host.say('🍺 A cask tipped off', `${this.aboard} left aboard · mind the bumps`);
  }

  /** `free`: nothing else is up, so the card may show. */
  update(dt: number, free = true): void {
    pump(this.host.worlds());
    this.cardUp = false;
    if (!this.host.enabled()) {
      if (this.state !== 'idle') this.stop();
      this.site = null;
      this.card.hidden = this.strip.hidden = this.count.hidden = true;
      startPrompt.hide('rush');
      this.showRings(false);
      this.showPile(false);
      return;
    }
    const p = this.host.player();
    this.seen = { p: !!p, free, dA: p && this.site ? Math.round(Math.hypot(this.site.a.x - p.x, this.site.a.z - p.z) * 10) / 10 : -1 };
    if (this.state === 'idle') {
      this.pickT -= dt;
      if (this.pickT <= 0) { this.pickT = PICK_EVERY; this.pick(); }
      const s = this.site;
      if (free && s && p && this.stopped(p, s.kind.family) && Math.hypot(s.a.x - p.x, s.a.z - p.z) <= RUSH.rings[s.kind.family]) {
        this.cardUp = true;
        this.showCard(s, p.def);
      }
    } else this.running(p, dt);
    this.card.hidden = !this.cardUp;
    if (!this.cardUp) this.cardSig = '';
    const s = this.site;
    if (this.cardUp && s && p && this.canRun(s, p.def)) startPrompt.show('rush', { key: 'Enter', title: s.kind.name, action: 'accept', dock: this.card });
    // in A's ring through a run, with room aboard: Space loads, as at any cargo ring
    else if (this.state === 'run' && s && p && Math.hypot(s.a.x - p.x, s.a.z - p.z) <= RUSH.rings[s.kind.family] && this.host.room(p.def) > 0 && fits(s.kind, p.def, this.host.lent().classes)) {
      startPrompt.show('rush', { key: 'Space', title: s.kind.name, action: `load ${s.kind.goods}`, sub: this.stopped(p, s.kind.family) ? undefined : p.def.kind === 'air' ? 'land first' : 'stop first' });
    } else startPrompt.hide('rush');
    this.showRings(this.state !== 'idle' || this.cardUp);
    this.showPile(this.state !== 'idle' || this.cardUp);
    this.render();
  }

  /** Stopped, as a family stops: an aircraft down on the ground too. */
  private stopped(p: NonNullable<ReturnType<RushesHost['player']>>, fam: Family): boolean {
    if (Math.abs(p.v) >= RUSH.stopped) return false;
    if (p.def.kind !== 'air') return true;
    void fam;
    const g = this.ground(p.x, p.z);
    return g !== null && p.y - g < RUSH.landed;
  }

  private begin(s: RushSite, def: VehicleDef): void {
    this.site = s;
    this.forced = '';
    this.state = 'count';
    this.t = 0;
    this.lastCount = 0;
    this.lots = [];
    this.units = this.trips = this.paid = this.lost = this.crewN = 0;
    this.late = this.rained = false;
    this.spillT = 0;
    this.secs = secsOf(s.kind);
    // the followers run the loop on their own (they leave the formation, so the hold is the player's own after);
    // the drivers on Work nearby join unless the card left them at work
    const hands = [...this.host.crew.followers(s), ...(this.crewOn ? this.host.crew.candidates(s) : [])];
    const brought = this.host.crew.take(s, hands);
    this.hold = this.host.room(def) + brought;
    this.crewN = hands.length;
    if (hands.length) this.host.say(`${s.kind.icon} ${hands.length} of your driver${hands.length === 1 ? '' : 's'} run${hands.length === 1 ? 's' : ''} it too`, `${hands.map((u) => u.name).join(', ')} · each loops A to B on their own`);
    const lent = this.host.lent();
    this.solo = !hands.length && !lent.units;
    this.vehicles = 1 + hands.length + lent.names.length;
    // run means done: the year's wait starts now, so a reload mid-run can't give it back
    this.waits.set(s.key, this.host.hours() + RUSH.waitHours);
    if (this.online.active) this.online.post({ t: 'rushGo', key: s.key, name: s.kind.name, kind: s.kind.id, len: s.len, secs: this.secs, hold: Math.max(1, this.hold) });
    startPrompt.hide('rush');
    this.cardSig = '';
  }

  private running(p: ReturnType<RushesHost['player']>, dt: number): void {
    const s = this.site!;
    this.t += dt;
    if (this.state === 'count') {
      const left = Math.ceil(COUNT - this.t);
      if (left !== this.lastCount && left > 0) { this.lastCount = left; this.host.beep(false); }
      if (this.t < COUNT) return;
      this.state = 'run';
      this.host.beep(true);
    }
    const run = this.t - COUNT;
    if (run >= this.secs) { this.finish(false); return; }
    if (s.kind.twist === 'rain' && !this.rained && run >= this.secs - RAIN_AT) {
      this.rained = true;
      this.host.rain(true);
      this.host.say('🌧 The rain is here', 'Two minutes left, and the road is slick');
    }
    this.host.crew.update(s, dt, (u, n) => this.delivered(n, `${u.name}: `, true));
    const ring = RUSH.rings[s.kind.family];
    if (p) {
      const dA = Math.hypot(s.a.x - p.x, s.a.z - p.z), dB = Math.hypot(s.b.x - p.x, s.b.z - p.z);
      // the school gate: in the slow zone too fast with pupils aboard, and they are late
      if (s.kind.twist === 'late' && this.aboard && dB <= SLOW_R && Math.abs(p.v) > SLOW_V && !this.late) {
        this.late = true;
        this.host.say('🎒 Too fast at the gate', 'This lot will be marked late: half count');
      }
      // loading is Space at A's ring (space()); only a trawler over the shoal fills as it goes, its twist
      const trawl = s.kind.twist === 'trawl' && !!p.def.trawl && dA <= ring * 1.6;
      const halted = this.stopped(p, s.kind.family);
      if (trawl && fits(s.kind, p.def, this.host.lent().classes)) {
        const room = this.host.room(p.def);
        if (room > 0) { this.lots.push({ n: room, at: run }); this.host.reserve(this.aboard); this.host.beep(false); }
      } else if (halted && dB <= ring && this.aboard > 0) this.unload(p.def, run);
    }
    // the arrows point at the end needed next: B with goods aboard, A without
    const to = this.aboard > 0 ? s.b : s.a;
    this.host.route({ x: to.x, z: to.z, key: `rush:${s.key}:${this.aboard > 0 ? 'b' : 'a'}`, near: ring });
  }

  /** Everything aboard comes off at B: melted ice cream and late pupils count half. */
  private unload(def: VehicleDef, run: number): void {
    const s = this.site!;
    let n = 0, half = 0;
    for (const l of this.lots) {
      const soft = (s.kind.twist === 'melt' && def.id !== 'sundae' && run - l.at > MELT_S) || (s.kind.twist === 'late' && this.late);
      if (soft) { n += Math.floor(l.n / 2); half += l.n - Math.floor(l.n / 2); } else n += l.n;
    }
    this.lots = [];
    this.late = false;
    this.host.reserve(0);
    this.trips++;
    this.lost += half;
    this.delivered(n, '');
    if (half) this.host.say(s.kind.twist === 'melt' ? '🍦 Some of it melted' : '🎒 Marked late', `${n} counted, ${half} didn’t`);
  }

  private delivered(n: number, who: string, crew = false): void {
    const s = this.site!;
    if (n <= 0) return;
    if (this.online.active) this.online.post({ t: 'rushDrop', key: s.key, n, ...(crew ? { crew: true } : {}) });
    this.units += n;
    const cash = Math.round(n * s.kind.perUnit);
    this.paid += cash;
    this.host.pay(cash, `${s.kind.name}: ${who}${n} ${s.kind.goods}`);
    this.host.beep(true);
  }

  /** The bell (or Backspace): the drivers back to work, the medal's bonus paid and the result told. */
  private finish(gaveUp: boolean): void {
    const s = this.site!;
    const crewLeft = this.host.crew.aboard();
    const crewUnits = this.host.crew.units;
    this.host.crew.release();
    if (this.rained) this.host.rain(false);
    const medal = medalOf(this.units, this.hold);
    const bonus = medal ? Math.round(this.paid * RUSH.bonus[medal - 1]) : 0;
    if (bonus) this.host.pay(bonus, `${s.kind.name}: ${MEDAL_NAME[medal]} medal`);
    if (this.online.active) this.online.post({ t: 'rushEnd', key: s.key, units: this.units, solo: this.solo, v: this.vehicles });
    this.host.done(s.kind.id.replace(/-long$/, ''), s.kind.name, this.units, medal, s.a.name);
    const was = this.best.get(s.key);
    const rec = !was || this.units > was[0];
    if (rec) this.best.set(s.key, [this.units, medal]);
    const par = RUSH.medals[1] * this.hold;
    const share = Math.min(100, Math.round((this.units / Math.max(1, par)) * 100));
    const twist = s.kind.twist === 'crowd' ? ` · the stands are ${share}% full` : s.kind.twist === 'site' ? ` · the houses are ${share}% built` : '';
    const left = this.aboard + crewLeft ? ` · ${this.aboard + crewLeft} still aboard went back` : '';
    const crew = this.crewN ? ` · ${crewUnits} by your ${this.crewN} driver${this.crewN === 1 ? '' : 's'}` : '';
    this.host.say(
      `${s.kind.icon} ${this.units} ${s.kind.goods}${medal ? ` · ${MEDAL_NAME[medal]}` : ''}${gaveUp ? ' · stopped' : ''}`,
      `${s.kind.name} · ${this.trips} trip${this.trips === 1 ? '' : 's'}${crew} · par ${par} · $${(this.paid + bonus).toLocaleString()}${rec && was ? ' · a new best' : ''}${twist}${left} · back for you in a game year${this.online.active ? '' : ' · online, runs go on a board'}`,
    );
    this.stop();
  }

  private stop(): void {
    if (this.host.crew.hands.length) this.host.crew.release();
    if (this.rained) { this.host.rain(false); this.rained = false; }
    this.state = 'idle';
    this.lots = [];
    this.host.reserve(0);
    this.host.route(null);
    if (this.site && (this.waits.get(this.site.key) ?? -Infinity) > this.host.hours()) this.site = null;
  }

  // ---- what is on screen ----

  private showCard(s: RushSite, def: VehicleDef): void {
    const ok = this.canRun(s, def);
    const room = this.host.room(def);
    const crew = ok ? this.host.crew.candidates(s) : [];
    const follow = ok ? this.host.crew.followers(s) : [];
    const sig = `${s.key}|${def.id}|${room}|${ok}|${crew.length}|${follow.length}|${this.crewOn}`;
    if (sig === this.cardSig) return;
    this.cardSig = sig;
    const best = this.best.get(s.key);
    const how = s.kind.family === 'road' ? 'by road' : s.kind.family === 'sea' ? 'by water' : s.kind.family === 'air' ? 'flown' : 'of track';
    const stop = s.kind.family === 'air' ? 'land' : 'stop';
    const why = s.kind.family !== 'road' && !fits(s.kind, def) && !ok ? `${FAMILY_NAME[s.kind.family]}${s.kind.also ? ` or ${FAMILY_NAME[s.kind.also].toLowerCase()}` : ''} only` : `Your hold can’t take ${esc(s.kind.goods)}`;
    // the hold is the player's own: the followers run their own loop (their hold isn't lent to this one)
    const own = Math.max(0, room - follow.reduce((n, u) => n + this.host.lentBy(u), 0));
    const helpers = follow.length + (this.crewOn ? crew.length : 0);
    const decline = '<button type="button" class="no" data-act="no">Decline <kbd>⌫</kbd></button>';
    this.card.innerHTML = `<div class="bar">Rush · ${s.kind.long ? 'ten' : 'five'} minutes</div><h4>${s.kind.icon} ${esc(s.kind.name)}</h4><p class="nm">${esc(s.a.name)} → ${esc(s.b.name)} · ${s.len} tiles ${how}</p>
      <p>${esc(s.kind.blurb)}</p>
      <ol class="how"><li>When the clock starts, ${stop === 'land' ? 'land' : 'stop'} in the gold ring here and press <kbd>Space</kbd>: your hold fills with ${esc(s.kind.goods)}. The pile never runs out.</li>
      <li>${stop === 'land' ? 'Land' : 'Stop'} in the green ring at ${esc(s.b.name)} and it all comes off.</li>
      <li>Go round as often as you can before the bell. Every unit that arrives counts.</li></ol>
      <div class="cl"><span>Your hold</span><b>${own} units a trip</b><em>par ${RUSH.medals[1] * own}</em></div>
      ${follow.length ? `<div class="cl"><span>Following</span><b>${follow.length} run${follow.length === 1 ? 's' : ''} the loop on their own: ${esc(follow.map((u) => u.name).join(', '))}</b><em></em></div>` : ''}
      ${crew.length ? `<div class="cl"><span>On Work</span><b>${this.crewOn ? `${crew.length} nearby join in: ${esc(crew.map((u) => u.name).join(', '))}` : `${crew.length} nearby stay at work`}</b><em><button type="button" data-crew>${this.crewOn ? 'Leave them' : 'Bring them'}</button></em></div>` : ''}
      <div class="cl"><span>Medals</span><b>${RUSH.medals.map((n, k) => `${MEDAL_NAME[k + 1]} ${n}×`).join(' · ')} your hold${helpers ? ' and theirs' : ''}</b><em></em></div>
      ${best ? `<div class="cl"><span>Your best</span><b>${best[0]} ${esc(s.kind.goods)}</b><em>${MEDAL_NAME[best[1]] || '—'}</em></div>` : ''}
      <p class="pay">$${s.kind.perUnit} a unit, more with a medal · once a game year${this.online.active ? ' · on the year’s board' : ''}</p>
      ${ok ? `<div class="acts"><button type="button" class="yes" data-act="yes">Accept <kbd>⏎</kbd></button>${decline}</div>` : `<p class="go no">${why}</p><div class="acts">${decline}</div>`}`;
  }

  private render(): void {
    let txt = '';
    if (this.state === 'count') txt = String(Math.max(1, Math.ceil(COUNT - this.t)));
    else if (this.state === 'run' && this.t - COUNT < 0.8) txt = 'GO';
    this.count.hidden = !txt;
    if (txt && this.count.textContent !== txt) { this.count.textContent = txt; this.count.classList.remove('pop'); void this.count.offsetWidth; this.count.classList.add('pop'); }
    if (this.state === 'idle' || !this.site) { this.strip.hidden = true; return; }
    const s = this.site;
    const left = this.state === 'count' ? this.secs : Math.max(0, this.secs - (this.t - COUNT));
    const m = Math.floor(left / 60), sec = Math.floor(left % 60);
    const next = this.aboard > 0 ? `to ${esc(s.b.name)}` : `· <kbd>Space</kbd> at ${esc(s.a.name)}`;
    const crew = this.host.crew.hands.length ? ` · 🚚 ${this.host.crew.hands.length} driver${this.host.crew.hands.length === 1 ? '' : 's'}` : '';
    const warn = this.late ? ' · <b class="w">late</b>' : s.kind.twist === 'melt' && this.lots.some((l) => this.t - COUNT - l.at > MELT_S) ? ' · <b class="w">melting</b>' : '';
    this.strip.innerHTML = `<span class="nm">${s.kind.icon} ${esc(s.kind.name)}</span>⏱ <b>${m}:${String(sec).padStart(2, '0')}</b> · <b>${this.units}</b> delivered · ${this.trips} trip${this.trips === 1 ? '' : 's'}${crew} · ${this.aboard} aboard ${next}${warn}<span class="nm" style="margin:0 0 0 10px"><kbd>⌫</kbd> stop</span>`;
    this.strip.hidden = false;
  }

  private ground(x: number, z: number): number | null {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    return w ? laidY(w, x - w.ox, z - w.oz) : null;
  }

  /** The rings at A (gold) and B (green), with a beam over each, while the card is up and through a run. */
  private showRings(on: boolean): void {
    const s = this.site;
    if (!on || !s) { if (this.rings) this.root.visible = false; return; }
    const r = RUSH.rings[s.kind.family];
    if (!this.rings || this.rings.a[0].mesh.userData.r !== r) {
      if (this.rings) { this.root.clear(); }
      const ring = (c: number) => [new GroundRing(r, 0.26, drapeMat(c, 0.95)), new GroundRing(r - 0.32, 0.18, drapeMat(0xffffff, 0.8))];
      const beam = (c: number) => new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 60, 12, 1, true), new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: 0.22, depthWrite: false }));
      this.rings = { a: ring(PILE_GOLD), b: ring(DROP_GREEN), beams: [beam(PILE_GOLD), beam(DROP_GREEN)] };
      this.rings.a[0].mesh.userData.r = r;
      for (const g of [...this.rings.a, ...this.rings.b]) this.root.add(g.mesh);
      this.root.add(...this.rings.beams);
    }
    this.root.visible = true;
    const ground = (x: number, z: number): number | null => this.ground(x, z);
    for (const g of this.rings.a) g.place(s.a.x, s.a.z, ground);
    for (const g of this.rings.b) g.place(s.b.x, s.b.z, ground);
    this.rings.beams[0].position.set(s.a.x, (ground(s.a.x, s.a.z) ?? 0) + 30, s.a.z);
    this.rings.beams[1].position.set(s.b.x, (ground(s.b.x, s.b.z) ?? 0) + 30, s.b.z);
    // the end to go to next stands out: its beam bright, the other faint
    const toB = this.state !== 'idle' && this.aboard > 0;
    (this.rings.beams[0].material as THREE.MeshBasicMaterial).opacity = this.state === 'idle' || !toB ? 0.3 : 0.08;
    (this.rings.beams[1].material as THREE.MeshBasicMaterial).opacity = toB ? 0.3 : 0.08;
  }

  /** A's cargo ring (the goods bobbing on their hoop, the arrow at B) and B's drop disc, while the rings show. */
  private showPile(on: boolean): void {
    const s = this.site;
    if (!on || !s) { if (this.pile) this.pile.m.group.visible = this.pile.drop.group.visible = false; return; }
    if (!this.pile || this.pile.key !== s.key) {
      if (this.pile) { this.root.remove(this.pile.m.group, this.pile.drop.group); disposeCargoMarker(this.pile.m); disposeCargoMarker(this.pile.drop); }
      const cls = s.kind.cls === 'any' ? 'freight' : s.kind.cls;
      const m = buildCargoMarker(PILE_GOLD, cls, false, PILE_MODEL[s.kind.id.replace(/-long$/, '')]);
      const drop = buildCargoMarker(DROP_GREEN, null);
      aimCargoMarker(m, s.b.x - s.a.x, s.b.z - s.a.z);
      m.group.position.set(s.a.x, (this.ground(s.a.x, s.a.z) ?? 0) + 0.04, s.a.z);
      drop.group.position.set(s.b.x, (this.ground(s.b.x, s.b.z) ?? 0) + 0.04, s.b.z);
      this.root.add(m.group, drop.group);
      this.pile = { m, drop, key: s.key };
    }
    const r = RUSH.rings[s.kind.family], t = performance.now() / 1000;
    this.pile.m.group.visible = this.pile.drop.group.visible = true;
    poseCargoMarker(this.pile.m, t, r);
    poseCargoMarker(this.pile.drop, t, r);
  }

  // ---- the Standings tab ----

  opened(): void { this.ask(true); }
  tick(): void { this.ask(); }
  press(_target: HTMLElement): boolean { return false; }

  html(): string {
    const on = this.online.active;
    const now = this.host.hours();
    const keys = [...new Set([...this.best.keys(), ...this.waits.keys()])];
    const lead = on
      ? `<div class="lead">${this.held.length ? `You hold <b>${this.held.length}</b> rush board${this.held.length === 1 ? '' : 's'} · <b>◆ ${this.held.length * RUSH_HELD_PER_DAY}</b> a game day` : 'Top a rush’s Fleet board for the year and it pays <b>◆ 1</b> a game day while you hold it.'} · year ${Math.max(0, this.year)}</div>`
      : '<div class="lead">Online, every rush has a board for the game year, Solo and Fleet. Offline, your own bests are kept here.</div>';
    if (!keys.length) return `${lead}<p class="foot">No rushes run yet. One waits at a diamond near you now and then: stop in it, and five minutes is on the clock.</p>`;
    const rows = keys.map((key) => {
      const kind = RUSH_KIND.get(key.split(':')[0]);
      const best = this.best.get(key);
      const back = (this.waits.get(key) ?? 0) - now;
      const b = this.boards.get(`${this.year}:${key}`) ?? [...this.boards.values()].filter((q) => q.key === key).sort((p, q) => q.year - p.year)[0];
      const head = `<p><b>${kind?.icon ?? '⏱'} ${esc(b?.name ?? kind?.name ?? key)}</b> <small>${best ? `your best ${best[0]}${best[1] ? ` · ${MEDAL_NAME[best[1]]}` : ''}` : ''}${back > 0 ? ` · back for you in ${back >= 24 ? `${Math.ceil(back / 24)} day${Math.ceil(back / 24) === 1 ? '' : 's'}` : `${Math.ceil(back)} h`}` : ' · open again'}${b && b.year !== this.year ? ` · last year's board` : ''}${b && this.held.includes(b.id) ? ' · <b>held by you</b>' : ''}</small></p>`;
      if (!b) return `<div class="rush-b">${head}</div>`;
      const me = this.online.me?.id;
      const col = (title: string, list: RushRow[], you: RushRow | null, n: number) => {
        const scoped = scopeMode() !== 'everyone';
        const all = list.filter((r) => r.by === me || inScope(r.by)).map((r) => ({ ...r, you: r.by === me }));
        if (you && !all.some((r) => r.you)) all.push({ ...you, you: true });
        if (scoped) all.sort((p, q) => (p.place ?? 1e9) - (q.place ?? 1e9));
        const top = Math.max(1, ...all.map((r) => r.s));
        return `<div><h5>${title} · ${n}</h5><ul class="ranking">${all.map((r) => `<li class="${r.you ? 'you' : ''}"><span class="nm"><i>${scoped ? all.indexOf(r) + 1 : r.place ?? ''}</i>${chip([r.brand?.primary ?? 0x7d8a92, r.brand?.accent ?? 0xffffff], r.brand?.logo || undefined)}<b${r.you ? '' : ` data-pid="${esc(r.by)}"`}>${esc(r.name)}</b>${r.you ? ' <small>you</small>' : ''}<span class="sub">${esc(this.host.modelName(r.m))}${r.v > 1 ? ` +${r.v - 1}` : ''}${scoped && r.place ? ` · #${r.place} overall` : ''}</span></span><em>${r.s}</em><span class="bar"><i style="width:${Math.max(1.5, (r.s / top) * 100).toFixed(1)}%;background:${css(r.brand?.primary ?? 0x7d8a92)}"></i></span></li>`).join('') || '<li><span class="nm">No runs yet</span></li>'}</ul></div>`;
      };
      return `<div class="rush-b">${head}<div class="cols">${col('Solo', b.solo, b.you.solo, b.nSolo)}${col('Fleet', b.fleet, b.you.fleet, b.nFleet)}</div></div>`;
    });
    return `${lead}<h3 class="rush-h">Rushes you have run</h3>${rows.join('')}<p class="foot">Each rush comes round for you once a game year (${RUSH_YEAR_HOURS / 24} game days); its board stays open to see where you stand. Solo is one vehicle alone; Fleet is anything goes, and its leader holds the board. The server times every delivery.</p>`;
  }

  /** The rush's goods aboard, as a row of the cargo list (cargoHud ExtraRow), or null with none. */
  row(): ExtraRow | null {
    const s = this.site;
    if (!s || this.state !== 'run' || !this.aboard) return null;
    return { icon: s.kind.icon, name: s.kind.name, units: this.aboard, to: s.b.name, x: s.b.x, z: s.b.z, pay: this.aboard * s.kind.perUnit, note: s.kind.family === 'air' ? 'unloads when you land at B' : 'unloads when you stop at B', late: this.late };
  }

  /** Pr console: the rushes in memory, the one on offer, the run, a start that skips the drive there, and the offer forced. */
  console() {
    return {
      sites: () => this.host.worlds().flatMap((w) => rushesOf(w) ?? []),
      offer: () => this.site,
      state: () => ({ state: this.state, t: this.t, units: this.units, trips: this.trips, aboard: this.aboard, hold: this.hold, paid: this.paid, lost: this.lost, crew: this.host.crew.hands.map((h) => ({ name: h.u.name, to: h.to, aboard: h.aboard })), crewUnits: this.host.crew.units, seen: this.seen }),
      waits: () => Object.fromEntries(this.waits),
      start: () => { const p = this.host.player(); if (p && this.site) this.begin(this.site, p.def); return this.state; },
      clear: () => { this.waits.clear(); this.rests.clear(); },
      /** Offer this rush (by key) whatever the hour, season or day: for trying one out. */
      offerKey: (key: string) => { const s = this.host.worlds().flatMap((w) => rushesOf(w) ?? []).find((q) => q.key === key) ?? null; if (s) { this.site = s; this.forced = s.key; } return !!s; },
      /** Jump the run's clock on (seconds), for trying the bell and the rain. */
      skip: (secs: number) => { if (this.state === 'run') this.t += secs; return this.t; },
      knock: (n: number) => this.knock(n),
    };
  }
}

const COMPASS = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
const compass = (dx: number, dz: number): string => COMPASS[((Math.round(Math.atan2(dx, -dz) / (Math.PI / 4)) % 8) + 8) % 8];

