import { hex, scale, type RGB } from '../../world/biomes';
import type { Building, ThemeKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import type { Rng } from '../../world/rng';
import {
  TAU, WARM_GLOW, SHOP_GLOW, WHITE, falseFront, gableFace, onionDome, pick, porch, portico, row,
  styleRoof, styleWall, tiledHip, win,
  type Draw, type Kit,
} from './kit';
import { eastRoof } from './regions/terraces';
import { TOKYO_DRAW } from './tokyo';
import { CAPITALS_DRAW } from './capitals';
import { CHICAGO_DRAW } from './chicago';
import { AMSTERDAM_DRAW } from './amsterdam';
import { ROME_DRAW } from './rome';
import { OSAKA_DRAW } from './osaka';
import { ADRIATIC_DRAW } from './adriatic';
import { STYLE_EXTRA_DRAW } from './expansion';

/**
 * The themed towns' own buildings (swapped in by the town's style, STYLE_SWAPS in world/towns.ts), and two
 * frontier stand-ins drawn in place of an ordinary kind when the town is Old West:
 *
 * - Dutch: the **canal warehouse**, five storeys of brick with loading doors up its middle, a neck gable
 *   and a hoist beam with a bale on its rope (for a store).
 * - Japanese: the **fire lookout** (hinomi-yagura), a splayed timber ladder tower with an alarm bell under
 *   a little flared roof (for a clock tower).
 * - Budapest: the **parliament**, a long cream Gothic Revival range of pinnacles round a ribbed dome, and
 *   the **thermal bath**, a yellow baroque courtyard of green domes round steaming outdoor pools.
 * - Old West: the **saloon**, a false front over a porch with a balcony on it and batwing doors; and, not
 *   kinds of their own, the wooden **water tank** on its trestle and the **sheriff's office** and jail.
 * - Colonial: the white-steepled **meeting house** behind its columned portico (for a chapel), and the
 *   red-brick **statehouse** with its clock tower and cupola and arcaded wings (for a courthouse).
 */

const GOLD = hex(0xd8a83a), IRON = hex(0x2a2a2e), OAK = hex(0x3a2e26), PLANK = hex(0x8a6a48);
const CREAM = hex(0xf0e6cc), CREAM_SHADE = hex(0xd8ccb0), PARLIAMENT_ROOF = hex(0x9a3a2e), DOME = hex(0x7a4a3e);
const YELLOW = hex(0xe8c860), TRIM = hex(0xfaf6e8), ZSOLNAY_GREEN = hex(0x3f7a5a), POOL = hex(0x5fc0d0), DECK = hex(0xe8e0cc);
const CLAPBOARD = hex(0xf8f6ee), SLATE = hex(0x4a4a50), GEORGIAN_BRICK = hex(0xa4583f), SHUTTER_GREEN = hex(0x2f4a3a);
const FIRE_TIMBER = hex(0x3a2e26), FIRE_WOOD = hex(0x6a5038), FIRE_ROOF = hex(0x3a3e44), BELL = hex(0x8a6a2a);
const NIGHT_LAMP: [number, number, number] = [17.5, 30, 2.2];

/** Thin horizontal lines across a front, the shadow under each weatherboard. */
function boards(k: Kit, x: number, y: number, z: number, w: number, h: number, col: RGB, gap = 0.06): void {
  const shade = scale(col, 0.84);
  for (let v = y + gap; v < y + h - 0.01; v += gap) k.box(x, v, z, w, 0.005, 0.006, shade);
}

/** A painted surround behind a pane on a front facing +z at z (the pane itself stands a hair further out). */
function surround(k: Kit, x: number, y: number, z: number, w: number, h: number, col: RGB): void {
  k.box(x, y - 0.015, z + 0.001, w + 0.03, h + 0.03, 0.006, col);
}

// ---- Dutch: the canal warehouse --------------------------------------------------------------------

const canalWarehouse: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), white = hex(0xf6f4ee), shutter = pick(r, [0x2f4d3a, 0x6e2a22, 0x2a3a2e]);
  const floors = Math.max(3, b.floors), fh = FLOOR * 1.1, w = W - 0.14, d = D - 0.3, z = -0.1, h = 0.06 + floors * fh, fz = z + d / 2;
  k.box(0, 0, z, w + 0.02, 0.06, d + 0.02, hex(0x8a8478));
  k.box(0, 0.06, z, w, h - 0.06, d, wall);
  for (let f = 0; f < floors; f++) {
    const y = 0.06 + f * fh;
    // the loading doors up the middle: the great door at the foot, wooden hatches above, now and then one open
    if (f === 0) {
      surround(k, 0, 0.02, fz, 0.2, 0.24, white);
      k.box(0, 0, fz + 0.006, 0.2, 0.24, 0.008, shutter);
    } else {
      surround(k, 0, y + 0.03, fz, 0.18, 0.2, white);
      if (r() < 0.25) k.box(0, y + 0.03, fz + 0.006, 0.16, 0.2, 0.008, hex(0x1e1a18));
      else for (const s of [-1, 1]) k.box(s * 0.042, y + 0.03, fz + 0.006, 0.076, 0.2, 0.008, shutter);
    }
    for (const sx of [-1, 1]) win(k, b, r, sx * w * 0.32, y + 0.06, fz, 0.1, 0.14, 1);
    for (let i = 0; i < 3; i++) for (const sx of [-1, 1]) win(k, b, r, sx * w / 2, y + 0.07, z - d / 2 + (d * (i + 0.5)) / 3, 0.09, 0.12, sx > 0 ? 0 : 2);
  }
  // a neck gable on the canal, a stepped one behind, a steep roof between
  const rh = Math.min(0.7, w * 0.85);
  k.gable(0, h, z, w, rh, d, styleRoof(r), wall, true);
  gableFace(k, 0, h, fz + 0.012, w + 0.02, rh * 1.12, wall, white, 'neck', true, 1);
  gableFace(k, 0, h, z - d / 2 - 0.012, w + 0.02, rh * 1.12, wall, white, 'step', true, -1);
  // the hoist beam out over the street, the rope and a bale on its way up
  k.box(0, h + rh * 0.62, fz + 0.12, 0.035, 0.035, 0.24, OAK);
  k.cyl(0, h + rh * 0.62 - 0.03, fz + 0.21, 0.025, 0.03, IRON, 6);
  k.box(0, h * 0.62, fz + 0.21, 0.006, h + rh * 0.62 - 0.03 - h * 0.62, 0.006, hex(0x8a7a5a));
  k.box(0, h * 0.62 - 0.1, fz + 0.21, 0.12, 0.1, 0.1, hex(0xc9a86a));
  // bollards and a barrel at the foot
  for (const sx of [-1, 1]) k.cyl(sx * 0.32, 0, D / 2 - 0.08, 0.025, 0.08, hex(0x2a3a2e), 6);
  k.cyl(-0.28, 0, fz + 0.12, 0.05, 0.12, hex(0x7a5a3a), 8, hex(0x5a4a3a));
  k.glowBox(0.14, 0.26, fz + 0.012, 0.03, 0.05, 0.03, IRON, NIGHT_LAMP, WARM_GLOW);
};

// ---- Japanese: the fire lookout ----------------------------------------------------------------------

const fireLookout: Draw = (k, _W, _D, _b, r) => {
  const H = 1.75, base = 0.28, top = 0.15, y0 = 0.06;
  k.box(0, 0, 0, 0.74, y0, 0.74, hex(0xa8a49c));
  const at = (f: number) => base + (top - base) * f;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([sx * base, y0, sz * base], [sx * top, H, sz * top], 0.022, FIRE_TIMBER);
  // cross braces up each face, and a tie round the tower at each stage
  const stages = 4;
  for (let i = 0; i < stages; i++) {
    const a = y0 + ((H - y0) * i) / stages, bb = y0 + ((H - y0) * (i + 1)) / stages, wa = at(i / stages), wb = at((i + 1) / stages);
    for (const s of [-1, 1]) {
      k.bar([-wa, a, s * wa], [wb, bb, s * wb], 0.008, FIRE_WOOD);
      k.bar([wa, a, s * wa], [-wb, bb, s * wb], 0.008, FIRE_WOOD);
      k.bar([s * wa, a, -wa], [s * wb, bb, wb], 0.008, FIRE_WOOD);
      k.bar([s * wa, a, wa], [s * wb, bb, -wb], 0.008, FIRE_WOOD);
      k.bar([-wb, bb, s * wb], [wb, bb, s * wb], 0.011, FIRE_TIMBER);
      k.bar([s * wb, bb, -wb], [s * wb, bb, wb], 0.011, FIRE_TIMBER);
    }
  }
  // the ladder up the front
  for (let i = 0; i < 14; i++) {
    const f = (i + 0.5) / 14, y = y0 + (H - y0) * f, zz = at(f) + 0.04;
    k.box(0, y, zz, 0.12, 0.008, 0.01, FIRE_WOOD);
  }
  for (const s of [-1, 1]) k.bar([s * 0.06, y0, base + 0.04], [s * 0.06, H, top + 0.04], 0.007, FIRE_TIMBER);
  // the lookout platform, its rail, the alarm bell and the little roof over it
  k.box(0, H, 0, 0.42, 0.03, 0.42, FIRE_WOOD);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.19, H + 0.03, sz * 0.19, 0.022, 0.26, 0.022, FIRE_TIMBER);
  for (const s of [-1, 1]) {
    k.box(0, H + 0.11, s * 0.19, 0.4, 0.014, 0.014, FIRE_TIMBER);
    k.box(s * 0.19, H + 0.11, 0, 0.014, 0.014, 0.4, FIRE_TIMBER);
  }
  k.cyl(0, H + 0.1, 0, 0.05, 0.1, BELL, 8, scale(BELL, 0.8));
  k.box(0, H + 0.2, 0, 0.012, 0.09, 0.012, IRON);
  eastRoof(k, 0, H + 0.29, 0, 0.56, 0.56, 0.2, FIRE_ROOF, 0.05);
  // a lantern on the platform after dark, and fire buckets stacked by the foot
  k.glowBox(0.12, H + 0.03, 0.12, 0.05, 0.07, 0.05, hex(0x6a4a22), [18, 6.5, 2.5], WARM_GLOW);
  const bucket = hex(0xb5402f);
  for (let i = 0; i < 3; i++) k.cyl(-0.22 + i * 0.07, y0, 0.3, 0.03, 0.05, bucket, 6);
  for (let i = 0; i < 2; i++) k.cyl(-0.185 + i * 0.07, y0 + 0.05, 0.3, 0.03, 0.05, bucket, 6);
  void r;
};

// ---- Budapest: the parliament --------------------------------------------------------------------------

const parliament: Draw = (k, W, D, b, r) => {
  const w = W - 0.3, d = D - 0.9, z = -0.2, h = 0.72, y0 = 0.06, fz = z + d / 2;
  k.box(0, 0, z, w + 0.12, y0, d + 0.3, CREAM_SHADE);
  k.box(0, y0, z, w, h, d, CREAM);
  k.gable(0, y0 + h, z, w, 0.34, d, PARLIAMENT_ROOF, CREAM, false);
  // a pavilion at each end, standing forward and taller under its own steep hip
  for (const sx of [-1, 1]) {
    const px = sx * (w / 2 - 0.3);
    k.box(px, y0, z + 0.06, 0.52, h + 0.2, d + 0.14, CREAM);
    k.hip(px, y0 + h + 0.2, z + 0.06, 0.56, 0.44, d + 0.18, PARLIAMENT_ROOF);
    for (const cz of [-1, 1]) k.cone(px + 0.24, y0 + h + 0.2, z + 0.06 + cz * (d / 2 + 0.05), 0.04, 0.3, CREAM_SHADE, 5);
    for (const cz of [-1, 1]) k.cone(px - 0.24, y0 + h + 0.2, z + 0.06 + cz * (d / 2 + 0.05), 0.04, 0.3, CREAM_SHADE, 5);
  }
  // pinnacles all along the front, and two rows of tall windows between them
  const n = Math.max(6, Math.round(w / 0.26));
  for (let i = 0; i <= n; i++) {
    const px = -w / 2 + (w * i) / n;
    if (Math.abs(px) < 0.5) continue;
    k.box(px, y0, fz + 0.02, 0.045, h + 0.14, 0.045, CREAM_SHADE);
    k.cone(px, y0 + h + 0.14, fz + 0.02, 0.032, 0.2, CREAM_SHADE, 4);
  }
  const span = w / 2 - 0.62 - 0.5;
  for (const sx of [-1, 1]) {
    for (const y of [0.18, 0.46]) row(k, b, r, sx * (0.5 + span / 2), y, fz, span, 0.18, Math.max(2, Math.round(span / 0.2)), 1);
  }
  for (const sx of [-1, 1]) row(k, b, r, sx * w / 2, 0.3, z, d - 0.2, 0.2, 3, sx > 0 ? 0 : 2);
  // the dome: a drum ringed in pinnacles, a ribbed dome, a lantern and a spire
  const cy = y0 + h, R = Math.min(0.5, d * 0.36);
  k.cyl(0, cy, z, R, 0.36, CREAM, 16);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    k.box(Math.cos(a) * (R + 0.004), cy + 0.08, z + Math.sin(a) * (R + 0.004), 0.05, 0.2, 0.05, hex(0x3a3a44));
  }
  k.cyl(0, cy + 0.36, z, R * 1.08, 0.04, CREAM_SHADE, 16);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    k.cone(Math.cos(a) * R * 1.05, cy + 0.4, z + Math.sin(a) * R * 1.05, 0.03, 0.22, CREAM_SHADE, 4);
  }
  k.dome(0, cy + 0.4, z, R, DOME, 16, 5);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2;
    k.bar([Math.cos(a) * R * 0.98, cy + 0.42, z + Math.sin(a) * R * 0.98], [Math.cos(a) * R * 0.25, cy + 0.4 + R * 0.95, z + Math.sin(a) * R * 0.25], 0.012, CREAM_SHADE);
  }
  k.cyl(0, cy + 0.4 + R * 0.92, z, 0.1, 0.16, CREAM, 8);
  k.cone(0, cy + 0.56 + R * 0.92, z, 0.1, 0.55, DOME, 8);
  k.box(0, cy + 1.1 + R * 0.92, z, 0.02, 0.14, 0.02, GOLD);
  // the entrance: three pointed arches under a gable, steps down to the square, and the tricolour either side
  const pz = fz + 0.12;
  k.box(0, y0, pz, 0.78, 0.44, 0.24, CREAM);
  k.gable(0, y0 + 0.44, pz, 0.82, 0.22, 0.26, PARLIAMENT_ROOF, CREAM, true);
  for (const ax of [-0.24, 0, 0.24]) {
    k.box(ax, y0, pz + 0.121, 0.13, 0.26, 0.01, hex(0x3a3228));
    k.cone(ax, y0 + 0.26, pz + 0.121, 0.065, 0.08, hex(0x3a3228), 4);
  }
  k.box(0, 0, pz + 0.2, 0.9, y0, 0.2, CREAM_SHADE);
  for (const sx of [-1, 1]) {
    const x = sx * 0.62, fzz = D / 2 - 0.12;
    k.box(x, 0, fzz, 0.02, 1.0, 0.02, IRON);
    for (const [i, c] of [[0, 0xc8352a], [1, 0xf4f2ec], [2, 0x2f7a3a]] as [number, number][]) k.box(x + 0.13, 0.94 - i * 0.05, fzz, 0.24, 0.05, 0.008, hex(c));
  }
  // floodlit after dark
  for (let i = 0; i < 6; i++) k.glowBox(-w / 2 + 0.3 + (i * (w - 0.6)) / 5, y0, fz + 0.1, 0.06, 0.03, 0.03, hex(0x8a8a7a), [17, 30, 2.4], hex(0xfff0c8));
};

// ---- Budapest: the thermal bath ------------------------------------------------------------------------

const thermalBath: Draw = (k, W, D, b, r) => {
  const w = W - 0.2, d = D - 0.2, bd = 0.72, sw = 0.56, bz = -d / 2 + bd / 2, bh = 0.64, wh = 0.5;
  // the back range with the domed hall, and a wing down each side of the courtyard
  k.box(0, 0, bz, w, bh, bd, YELLOW);
  k.box(0, bh, bz, w + 0.04, 0.03, bd + 0.04, TRIM);
  tiledHip(k, 0, bh + 0.03, bz, w + 0.02, 0.26, bd + 0.02, ZSOLNAY_GREEN, GOLD);
  const wz = bz + bd / 2 + (d - bd - 0.1) / 2, wd = d - bd - 0.1;
  for (const sx of [-1, 1]) {
    const x = sx * (w / 2 - sw / 2);
    k.box(x, 0, wz, sw, wh, wd, YELLOW);
    k.box(x, wh, wz, sw + 0.04, 0.03, wd + 0.04, TRIM);
    k.hip(x, wh + 0.03, wz, sw + 0.02, 0.2, wd + 0.02, ZSOLNAY_GREEN);
    // a domed pavilion on the street end of each wing
    const pz = wz + wd / 2 - 0.2;
    k.cyl(x, wh + 0.03, pz, 0.2, 0.14, YELLOW, 12);
    k.dome(x, wh + 0.17, pz, 0.2, ZSOLNAY_GREEN, 12, 4);
    k.cone(x, wh + 0.37, pz, 0.04, 0.12, GOLD, 6);
    row(k, b, r, x - sx * sw / 2, 0.16, wz, wd - 0.3, 0.16, 4, sx > 0 ? 2 : 0);
    row(k, b, r, x + sx * sw / 2, 0.16, wz, wd - 0.3, 0.16, 4, sx > 0 ? 0 : 2);
  }
  row(k, b, r, 0, 0.18, bz + bd / 2, w - 2 * sw - 0.2, 0.24, 6, 1);
  // the great dome over the hall
  k.cyl(0, bh + 0.03, bz, 0.36, 0.16, YELLOW, 16);
  k.cyl(0, bh + 0.19, bz, 0.38, 0.025, TRIM, 16);
  k.dome(0, bh + 0.215, bz, 0.36, ZSOLNAY_GREEN, 16, 5);
  k.cyl(0, bh + 0.215 + 0.33, bz, 0.08, 0.1, TRIM, 8);
  k.cone(0, bh + 0.315 + 0.33, bz, 0.08, 0.14, GOLD, 8);
  // the courtyard: a deck, a long pool and a round one, and parasols
  const cw = w - 2 * sw, cz = bz + bd / 2 + (d / 2 - (bz + bd / 2)) / 2, cd = d / 2 - (bz + bd / 2);
  k.box(0, 0, cz, cw, 0.03, cd, DECK);
  k.box(0, 0.03, cz - 0.25, cw - 0.3, 0.012, cd * 0.45, POOL);
  k.box(0, 0.03, cz - 0.25, cw - 0.26, 0.008, cd * 0.45 + 0.04, TRIM);
  k.cyl(0, 0.03, cz + cd * 0.3, 0.26, 0.014, POOL, 14, POOL);
  for (const sx of [-1, 1]) {
    const px = sx * (cw / 2 - 0.16), pz = cz + cd * 0.3;
    k.box(px, 0.03, pz, 0.012, 0.22, 0.012, WHITE);
    k.cone(px, 0.2, pz, 0.14, 0.07, pick(r, [0xc8352a, 0xf2f0e8, 0x2f6a72]), 8);
  }
  // wisps of steam off the water
  for (let i = 0; i < 4; i++) k.box(-cw * 0.3 + i * cw * 0.2, 0.06 + (i % 2) * 0.05, cz - 0.25, 0.1, 0.05, 0.08, hex(0xf2f4f4));
  // a balustrade and gate on the street
  const gz = d / 2 - 0.04;
  k.box(-cw / 4 - 0.12, 0, gz, cw / 2 - 0.24, 0.12, 0.05, TRIM);
  k.box(cw / 4 + 0.12, 0, gz, cw / 2 - 0.24, 0.12, 0.05, TRIM);
  for (const sx of [-1, 1]) k.box(sx * 0.2, 0, gz, 0.08, 0.26, 0.08, YELLOW);
  k.glowBox(0, 0.3, bz + bd / 2 + 0.01, 0.4, 0.06, 0.02, hex(0xd8c070), [17, 23, 1.6], SHOP_GLOW);
};

// ---- Old West: the saloon ------------------------------------------------------------------------------

const saloon: Draw = (k, _W, _D, b, r) => {
  const wall = pick(r, [0xa8503a, 0x8a6a4a, 0xc8a878, 0x7a8a82, 0xd8c8a8]), roof = hex(0x6e6a64), trim = hex(0xf0e6d0);
  const w = 0.86, d = 0.7, z = -0.1, h = 2 * FLOOR + 0.04, fz = z + d / 2;
  k.box(0, 0, z, w, h, d, wall);
  boards(k, 0, 0, fz + 0.003, w, h, wall);
  falseFront(k, r, 0, h, z, w, d, wall, roof);
  // the porch, and the balcony on its roof with the door out onto it
  const ph = FLOOR * 0.95;
  porch(k, r, 0, 0, z, w, d, ph);
  const out = 0.16, by = ph + 0.02;
  k.box(0, by + 0.07, fz + out, w + 0.04, 0.014, 0.014, trim);
  for (let i = 0; i <= 10; i++) k.box(-w / 2 + (w * i) / 10, by, fz + out, 0.01, 0.07, 0.01, trim);
  for (const sx of [-1, 1]) win(k, b, r, sx * 0.27, FLOOR + 0.08, fz, 0.12, 0.14, 1);
  k.box(0, FLOOR + 0.04, fz + 0.005, 0.12, 0.2, 0.008, hex(0x3a2a1e));
  // downstairs: a dark doorway with a pair of batwing doors, and a window each side
  k.box(0, 0.03, fz + 0.004, 0.18, 0.24, 0.008, hex(0x1e1814));
  for (const s of [-1, 1]) k.box(s * 0.045, 0.09, fz + 0.012, 0.084, 0.11, 0.01, PLANK);
  for (const sx of [-1, 1]) win(k, b, r, sx * 0.28, 0.09, fz, 0.16, 0.12, 1, hex(0x4a4a3a));
  k.glowBox(0, 0.28, fz + 0.04, 0.035, 0.05, 0.035, IRON, [17, 29, 2], WARM_GLOW);
  // the hitching rail and a barrel
  k.box(0, 0.12, fz + 0.2, 0.56, 0.018, 0.018, PLANK);
  for (const sx of [-1, 1]) k.box(sx * 0.27, 0, fz + 0.2, 0.024, 0.13, 0.024, PLANK);
  k.cyl(0.37, 0.03, fz + 0.1, 0.04, 0.1, hex(0x7a5a3a), 7, hex(0x5a4a3a));
};

/** The frontier's water tank: a hooped wooden tub under a shingle cone, on a braced timber trestle, a spout swung out. */
export function woodTank(k: Kit, r: Rng): void {
  const leg = hex(0x6a5038), tank = pick(r, [0x9a7650, 0x8a6a4a, 0xa8845a]), roof = hex(0x5a4a3a), H = 0.92;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([sx * 0.32, 0, sz * 0.32], [sx * 0.21, H, sz * 0.21], 0.022, leg);
  for (const s of [-1, 1]) {
    k.bar([-0.3, 0.08, s * 0.3], [0.22, H - 0.06, s * 0.22], 0.008, leg);
    k.bar([0.3, 0.08, s * 0.3], [-0.22, H - 0.06, s * 0.22], 0.008, leg);
    k.bar([s * 0.3, 0.08, -0.3], [s * 0.22, H - 0.06, 0.22], 0.008, leg);
    k.bar([s * 0.3, 0.08, 0.3], [s * 0.22, H - 0.06, -0.22], 0.008, leg);
  }
  k.box(0, H, 0, 0.52, 0.03, 0.52, leg);
  k.cyl(0, H + 0.03, 0, 0.3, 0.38, tank, 12);
  for (const y of [0.08, 0.2, 0.32]) k.cyl(0, H + 0.03 + y, 0, 0.306, 0.014, IRON, 12);
  k.cone(0, H + 0.41, 0, 0.34, 0.22, roof, 12);
  k.bar([0.26, H + 0.1, 0], [0.44, H - 0.08, 0], 0.022, IRON);
  k.bar([0.44, H - 0.08, 0], [0.44, H - 0.3, 0], 0.012, IRON);
  for (let i = 0; i < 8; i++) k.box(0, 0.1 + i * 0.1, 0.27 - i * 0.012, 0.1, 0.008, 0.01, leg);
}

/** The Old West's police station: a boarded sheriff's office and jail behind a false front, a star by the door, a porch, a trough. */
export function sheriffOffice(k: Kit, b: Building, r: Rng): void {
  const wall = pick(r, [0xc8a878, 0xb08a5e, 0xd8c8a8]), fz = 0.4, cap = scale(wall, 0.66);
  // the flat roof stays at 0.74, where the helipad table puts the pad
  k.box(0, 0, -0.2, 1.6, 0.74, 1.2, wall, hex(0x8a8680));
  boards(k, 0, 0, fz + 0.003, 1.6, 0.74, wall);
  k.box(0, 0.74, fz - 0.025, 1.64, 0.24, 0.05, wall);
  k.box(0, 0.98, fz - 0.03, 1.7, 0.03, 0.08, cap);
  k.box(0, 0.78, fz + 0.004, 1.0, 0.13, 0.01, hex(0x2a2a2e));
  for (let i = 0; i < 7; i++) k.box(-0.36 + i * 0.12, 0.81, fz + 0.011, 0.07, 0.07, 0.004, hex(0xf2e8cc));
  // the office on the left, the jail on the right with bars over its windows
  k.box(-0.35, 0.03, fz + 0.005, 0.16, 0.26, 0.008, hex(0x3a2a1e));
  k.face(-0.35, 0.36, fz + 0.012, 0.055, GOLD, 5);
  win(k, b, r, -0.62, 0.1, fz, 0.2, 0.14, 1);
  for (const x of [0.2, 0.55]) {
    win(k, b, r, x, 0.14, fz, 0.16, 0.12, 1);
    for (let i = 0; i < 4; i++) k.box(x - 0.06 + i * 0.04, 0.14, fz + 0.012, 0.008, 0.12, 0.008, IRON);
  }
  for (const x of [0.2, 0.55]) win(k, b, r, x, 0.46, fz, 0.16, 0.12, 1);
  win(k, b, r, -0.62, 0.46, fz, 0.2, 0.12, 1);
  porch(k, r, 0, 0, -0.2, 1.6, 1.2, FLOOR * 0.95);
  // a wanted poster, a horse trough and a hitching rail
  k.box(-0.12, 0.12, fz + 0.006, 0.08, 0.1, 0.006, hex(0xe8dcb8));
  k.box(0.5, 0, 0.8, 0.34, 0.09, 0.12, PLANK);
  k.box(0.5, 0.09, 0.8, 0.3, 0.004, 0.08, hex(0x5f9fb8));
  k.box(-0.5, 0.12, 0.8, 0.5, 0.018, 0.018, PLANK);
  for (const sx of [-1, 1]) k.box(-0.5 + sx * 0.24, 0, 0.8, 0.024, 0.13, 0.024, PLANK);
  k.glowBox(-0.35, 0.3, fz + 0.04, 0.035, 0.05, 0.035, IRON, [17, 30, 2], WARM_GLOW);
}

// ---- Colonial: the meeting house --------------------------------------------------------------------------

const meetingHouse: Draw = (k, W, D, b, r) => {
  const roof = pick(r, [0x4a4a50, 0x5a4a44, 0x3a4048]), granite = hex(0xb0a898);
  const w = W - 0.3, d = D - 0.55, z = -0.12, h = 0.56, fz = z + d / 2;
  k.box(0, 0, z, w + 0.02, 0.04, d + 0.02, granite);
  k.box(0, 0.04, z, w, h, d, CLAPBOARD);
  for (let v = 0.1; v < h; v += 0.06) k.box(0, 0.04 + v, z, w + 0.006, 0.005, d + 0.006, scale(CLAPBOARD, 0.88));
  k.gable(0, 0.04 + h, z, w + 0.06, 0.34, d + 0.06, roof, CLAPBOARD, true);
  // tall shuttered windows down both sides
  for (let i = 0; i < 4; i++) {
    const wz = z - d / 2 + (d * (i + 0.5)) / 4;
    for (const sx of [-1, 1]) {
      win(k, b, r, sx * w / 2, 0.16, wz, 0.1, 0.3, sx > 0 ? 0 : 2);
      for (const s of [-1, 1]) k.box(sx * (w / 2 + 0.006), 0.16, wz + s * 0.085, 0.01, 0.3, 0.05, SHUTTER_GREEN);
    }
  }
  // the portico: steps, four columns, the entablature and a pediment
  const pz = fz + 0.14;
  k.box(0, 0, pz, w, 0.04, 0.3, granite);
  for (let i = 0; i < 4; i++) k.cyl(-w * 0.36 + i * w * 0.24, 0.04, pz + 0.1, 0.026, 0.5, WHITE, 6);
  k.box(0, 0.54, pz, w + 0.02, 0.05, 0.3, CLAPBOARD);
  k.gable(0, 0.59, pz, w + 0.02, 0.16, 0.3, roof, CLAPBOARD, true);
  k.box(0, 0.04, fz + 0.006, 0.14, 0.28, 0.01, SHUTTER_GREEN);
  k.face(0, 0.33, fz + 0.012, 0.06, hex(0xf2e8c8), 8);
  // the steeple: a square tower, the open belfry, an octagonal lantern and a tall white spire
  const tz = fz - 0.22, by = 0.6;
  k.box(0, by, tz, 0.32, 0.36, 0.32, CLAPBOARD);
  k.face(0, by + 0.2, tz + 0.162, 0.07, hex(0xf2f0e8), 12);
  k.box(0, by + 0.2, tz + 0.166, 0.008, 0.05, 0.004, IRON);
  k.box(0, by + 0.36, tz, 0.36, 0.03, 0.36, WHITE);
  k.box(0, by + 0.39, tz, 0.26, 0.24, 0.26, CLAPBOARD);
  for (let f = 0; f < 4; f++) {
    const a = (f * TAU) / 4, cx = Math.sin(a) * 0.131, cz = Math.cos(a) * 0.131;
    if (f % 2 === 0) k.box(cx, by + 0.44, tz + cz, 0.12, 0.15, 0.004, hex(0x2a2a30));
    else k.box(cx, by + 0.44, tz + cz, 0.004, 0.15, 0.12, hex(0x2a2a30));
  }
  k.cone(0, by + 0.46, tz, 0.05, 0.09, GOLD, 6);
  k.box(0, by + 0.63, tz, 0.3, 0.03, 0.3, WHITE);
  k.cyl(0, by + 0.66, tz, 0.11, 0.2, CLAPBOARD, 8);
  k.cone(0, by + 0.86, tz, 0.115, 0.72, CLAPBOARD, 8);
  k.box(0, by + 1.58, tz, 0.012, 0.12, 0.012, GOLD);
  k.box(0.02, by + 1.66, tz, 0.07, 0.02, 0.008, GOLD);
  k.glowBox(0, 0.36, pz + 0.12, 0.04, 0.05, 0.04, IRON, NIGHT_LAMP, WARM_GLOW);
};

// ---- Colonial: the statehouse ------------------------------------------------------------------------------

const statehouse: Draw = (k, W, D, b, r) => {
  const w = W - 1.3, d = D - 0.7, z = -0.2, h = 0.62, fz = z + d / 2;
  k.box(0, 0, z, w, h, d, GEORGIAN_BRICK);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (w / 2 - 0.02), 0, z + sz * (d / 2 - 0.02), 0.05, h, 0.05, WHITE);
  k.box(0, h * 0.5, z, w + 0.012, 0.02, d + 0.012, WHITE);
  k.box(0, h, z, w + 0.05, 0.035, d + 0.05, WHITE);
  k.hip(0, h + 0.035, z, w + 0.03, 0.3, d + 0.03, SLATE);
  // a balustrade walk on the ridge, and a chimney at each end
  k.box(0, h + 0.3, z, w * 0.4, 0.04, 0.12, WHITE);
  for (const sx of [-1, 1]) k.box(sx * (w / 2 - 0.2), h + 0.1, z, 0.1, 0.34, 0.14, GEORGIAN_BRICK);
  // two storeys of white-framed sashes
  const n = 7;
  for (const y of [0.1, 0.38]) {
    for (let i = 0; i < n; i++) {
      const x = -w / 2 + (w * (i + 0.5)) / n;
      if (Math.abs(x) < 0.2) continue;
      surround(k, x, y, fz, 0.1, 0.16, WHITE);
      win(k, b, r, x, y, fz, 0.1, 0.16, 1);
    }
    for (const sx of [-1, 1]) win(k, b, r, sx * w / 2, y, z, 0.1, 0.16, sx > 0 ? 0 : 2);
  }
  // the tower on the front: brick, then a white clock stage, an arched belfry, a cupola and a spire
  const tz = fz + 0.12, ts = 0.38;
  k.box(0, 0, tz, ts, h + 0.3, ts, GEORGIAN_BRICK);
  for (const sx of [-1, 1]) k.box(sx * (ts / 2 - 0.015), 0, tz + ts / 2 - 0.015, 0.035, h + 0.3, 0.035, WHITE);
  k.box(0, 0, tz + ts / 2 + 0.004, 0.14, 0.26, 0.01, hex(0x2a3a5a));
  k.gable(0, 0.28, tz + ts / 2 + 0.02, 0.22, 0.07, 0.04, WHITE, WHITE, true);
  surround(k, 0, 0.42, tz + ts / 2, 0.1, 0.18, WHITE);
  win(k, b, r, 0, 0.42, tz + ts / 2, 0.1, 0.18, 1);
  const cy = h + 0.3;
  k.box(0, cy, tz, ts + 0.04, 0.03, ts + 0.04, WHITE);
  k.box(0, cy + 0.03, tz, 0.3, 0.26, 0.3, WHITE);
  k.face(0, cy + 0.16, tz + 0.152, 0.08, hex(0xf6f2e8), 12);
  k.box(0, cy + 0.16, tz + 0.156, 0.008, 0.06, 0.004, IRON);
  k.box(0.02, cy + 0.16, tz + 0.156, 0.04, 0.008, 0.004, IRON);
  k.box(0, cy + 0.29, tz, 0.34, 0.03, 0.34, WHITE);
  k.cyl(0, cy + 0.32, tz, 0.12, 0.2, WHITE, 8);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    k.box(Math.cos(a) * 0.121, cy + 0.35, tz + Math.sin(a) * 0.121, 0.03, 0.12, 0.03, hex(0x2a2a30));
  }
  k.dome(0, cy + 0.52, tz, 0.12, WHITE, 8, 3);
  k.cone(0, cy + 0.62, tz, 0.04, 0.3, WHITE, 6);
  k.box(0, cy + 0.9, tz, 0.012, 0.1, 0.012, GOLD);
  // the two small wings, joined to the hall by white arcades
  for (const sx of [-1, 1]) {
    const x = sx * (W / 2 - 0.26), wz = z + 0.1;
    k.box(x, 0, wz, 0.36, 0.44, 0.6, GEORGIAN_BRICK);
    k.hip(x, 0.44, wz, 0.4, 0.16, 0.64, SLATE);
    win(k, b, r, x, 0.14, wz + 0.3, 0.1, 0.16, 1);
    const ax = sx * (w / 2 + (W / 2 - 0.26 - 0.18 - w / 2) / 2), aw = W / 2 - 0.26 - 0.18 - w / 2;
    k.box(ax, 0.3, wz, aw + 0.02, 0.04, 0.3, WHITE);
    for (const s of [-1, 1]) k.box(ax, 0, wz + s * 0.12, 0.03, 0.3, 0.03, WHITE);
  }
  // the green, a flag and a lamp
  k.box(0, 0.002, D / 2 - 0.2, 0.9, 0.01, 0.3, hex(0x6fae55));
  k.box(0.6, 0, D / 2 - 0.15, 0.02, 1.1, 0.02, IRON);
  k.box(0.72, 0.96, D / 2 - 0.15, 0.22, 0.14, 0.008, hex(0x2a3a7a));
  k.box(0.72, 0.96, D / 2 - 0.15 + 0.005, 0.22, 0.03, 0.008, hex(0xc8352a));
  k.glowBox(0, 0.3, tz + ts / 2 + 0.04, 0.04, 0.05, 0.04, IRON, NIGHT_LAMP, WARM_GLOW);
};


// ---- Russia: the kremlin ------------------------------------------------------------------------------

const BRICK_RED = hex(0x9a3f33), BRICK_SHADE = hex(0x86352b), TENT_GREEN = hex(0x2f5a3f), LIME = hex(0xf2ece0);
const STAR_RED = hex(0xc8352a), STONE_GREY = hex(0xbfb49a);

/** Swallowtail merlons along the top of a wall running along x (or z when `alongZ`). */
function merlons(k: Kit, x: number, y: number, z: number, span: number, alongZ: boolean, col: RGB): void {
  const n = Math.max(3, Math.round(span / 0.22)), cell = span / n;
  for (let i = 0; i < n; i++) {
    const o = -span / 2 + cell * (i + 0.5);
    const mx = alongZ ? x : x + o, mz = alongZ ? z + o : z;
    k.box(mx, y, mz, alongZ ? 0.07 : cell * 0.6, 0.1, alongZ ? cell * 0.6 : 0.07, col);
    // the swallowtail: two little horns either side of a notch
    for (const s of [-1, 1]) {
      const hx = alongZ ? mx : mx + s * cell * 0.18, hz = alongZ ? mz + s * cell * 0.18 : mz;
      k.box(hx, y + 0.1, hz, alongZ ? 0.07 : cell * 0.2, 0.05, alongZ ? cell * 0.2 : 0.07, col);
    }
  }
}

/**
 * The kremlin: a red brick wall with swallowtail merlons round a raised yard, a tented tower on each
 * corner, a gate tower with a clock and a red star on its spire, and the town's cathedral inside under
 * five onion domes.
 */
const kremlin: Draw = (k, W, D, b, r) => {
  const w = W - 0.3, d = D - 0.3, wallH = 0.62, t = 0.12;
  // the yard, a hand above the street, and the wall round it
  k.box(0, 0, 0, w, 0.06, d, STONE_GREY);
  for (const sz of [-1, 1]) {
    k.box(0, 0.06, sz * (d / 2 - t / 2), w, wallH, t, BRICK_RED, BRICK_SHADE);
    merlons(k, 0, 0.06 + wallH, sz * (d / 2 - t / 2), w, false, BRICK_RED);
  }
  for (const sx of [-1, 1]) {
    k.box(sx * (w / 2 - t / 2), 0.06, 0, t, wallH, d - 2 * t, BRICK_RED, BRICK_SHADE);
    merlons(k, sx * (w / 2 - t / 2), 0.06 + wallH, 0, d - 2 * t, true, BRICK_RED);
  }
  // a tower on each corner, under a green tent roof with a gilded finial
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const tx = sx * (w / 2 - 0.1), tz = sz * (d / 2 - 0.1), th = wallH + 0.26;
    k.box(tx, 0.06, tz, 0.22, th, 0.22, BRICK_RED, BRICK_SHADE);
    merlons(k, tx, 0.06 + th, tz, 0.22, false, BRICK_RED);
    k.cone(tx, 0.06 + th + 0.1, tz, 0.16, 0.34, TENT_GREEN, 4);
    k.cone(tx, 0.06 + th + 0.44, tz, 0.02, 0.06, GOLD, 4);
  }
  // the gate tower on the street front: an arch through it, a clock and a spire with a star
  const gz = d / 2 - t / 2, gh = wallH + 0.72;
  k.box(0, 0.06, gz, 0.46, gh, 0.2, BRICK_RED, BRICK_SHADE);
  k.box(0, 0.06, gz + 0.101, 0.18, 0.34, 0.01, hex(0x2a211c));
  k.cyl(0, 0.06 + 0.34, gz + 0.101, 0.09, 0.01, hex(0x2a211c), 8);
  k.cyl(0, 0.06 + gh - 0.22, gz + 0.101, 0.07, 0.012, LIME, 10);
  k.box(0, 0.06 + gh - 0.22, gz + 0.107, 0.012, 0.05, 0.008, IRON);
  merlons(k, 0, 0.06 + gh, gz, 0.46, false, BRICK_RED);
  k.cone(0, 0.06 + gh + 0.1, gz, 0.16, 0.5, TENT_GREEN, 6);
  k.cyl(0, 0.06 + gh + 0.6, gz, 0.018, 0.12, GOLD, 6);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU + 0.3;
    k.box(Math.cos(a) * 0.05, 0.06 + gh + 0.72, gz + Math.sin(a) * 0.05, 0.04, 0.04, 0.04, STAR_RED);
  }
  // the cathedral in the yard: a white block under a great gold dome and four smaller ones
  const cz = -d / 2 + Math.min(d * 0.42, 0.9), cw = Math.min(0.8, w * 0.42), ch = 0.5;
  k.box(0, 0.06, cz, cw, ch, cw, LIME);
  row(k, b, r, 0, 0.16, cz + cw / 2, cw - 0.16, 0.16, 3, 1);
  k.box(0, 0.06 + ch, cz, cw + 0.05, 0.03, cw + 0.05, STONE_GREY);
  onionDome(k, 0, 0.09 + ch, cz, 0.17, hex(0xd8a83a), LIME);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    onionDome(k, sx * cw * 0.3, 0.09 + ch, cz + sz * cw * 0.3, 0.095, hex(r() < 0.5 ? 0x2f7a72 : 0xb8bcc0), LIME);
  }
  // lanterns either side of the gate
  for (const sx of [-1, 1]) k.glowBox(sx * 0.3, 0.06 + 0.3, gz + 0.11, 0.05, 0.07, 0.05, IRON, NIGHT_LAMP, WARM_GLOW);
};

// ---- Russia: the wedding-cake tower --------------------------------------------------------------------

/**
 * A Stalin-era tower: a broad base, three setbacks stepping in under ribbed pilasters, and a lantern and
 * spire with a star on top. Cream and ochre stone, deep window reveals, flood-lit after dark.
 */
const stalinTower: Draw = (k, W, D, b, r) => {
  const stone = styleWall(r), trim = hex(0xf2e8d0);
  const floors = Math.max(6, b.floors), w = W - 0.2, d = D - 0.2;
  // four stages, each shorter and narrower than the one under it
  const stages = [0.42, 0.26, 0.2, 0.12].map((f) => Math.max(1, Math.round(floors * f)));
  let y = 0, sw = w, sd = d;
  for (const [i, n] of stages.entries()) {
    const h = n * FLOOR;
    k.box(0, y, 0, sw, h, sd, stone);
    // pilasters up the corners and a cornice over the stage
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (sw / 2 - 0.03), y, sz * (sd / 2 - 0.03), 0.07, h, 0.07, trim);
    k.box(0, y + h, 0, sw + 0.06, 0.05, sd + 0.06, trim);
    for (let f = 0; f < n; f++) {
      const wy = y + f * FLOOR + 0.06;
      for (const face of [0, 1, 2, 3]) {
        const span = face === 1 || face === 3 ? sw - 0.16 : sd - 0.16;
        row(k, b, r, face === 0 ? sw / 2 : face === 2 ? -sw / 2 : 0, wy, face === 1 ? sd / 2 : face === 3 ? -sd / 2 : 0,
          span, 0.16, Math.max(2, Math.round(span / 0.22)), face);
      }
    }
    // urns at the corners of each setback
    if (i < stages.length - 1) for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      k.cyl(sx * (sw / 2 - 0.06), y + h + 0.05, sz * (sd / 2 - 0.06), 0.045, 0.12, trim, 6);
    }
    y += h + 0.05;
    sw *= 0.68;
    sd *= 0.68;
  }
  // the lantern, the spire and its star
  k.cyl(0, y, 0, Math.max(0.12, sw * 0.5), 0.22, trim, 8);
  k.cone(0, y + 0.22, 0, Math.max(0.1, sw * 0.42), 0.8, hex(0xd8c8a0), 8);
  k.cyl(0, y + 1.02, 0, 0.015, 0.16, GOLD, 6);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU + 0.3;
    k.box(Math.cos(a) * 0.05, y + 1.18, Math.sin(a) * 0.05, 0.04, 0.04, 0.04, STAR_RED);
  }
  k.glowBox(0, y + 1.18, 0, 0.05, 0.05, 0.05, STAR_RED, [17, 30, 2.6], STAR_RED);
  for (const sx of [-1, 1]) k.glowBox(sx * (w / 2 - 0.1), 0.06, d / 2 - 0.04, 0.06, 0.04, 0.04, hex(0x8a8a7a), [17, 30, 2.2], hex(0xfff0c8));
};

// ---- the Ottoman city: the friday mosque ----------------------------------------------------------------

const TILE_BLUE = hex(0x1f5fa8), TILE_TURQ = hex(0x2f9aa8), LEAD = hex(0x8a9096), SAND = hex(0xe8d6b0), SAND_SHADE = hex(0xd2b488);

/** A pencil minaret from its foot at y: the shaft, a balcony, the upper stage, a conical cap and a finial. */
function minaret(k: Kit, x: number, z: number, y: number, h: number, R: number): void {
  k.box(x, y, z, R * 2.4, h * 0.16, R * 2.4, SAND_SHADE);
  k.cyl(x, y + h * 0.16, z, R, h * 0.52, SAND, 10);
  k.cyl(x, y + h * 0.68, z, R * 1.5, h * 0.05, SAND_SHADE, 10);
  k.cyl(x, y + h * 0.73, z, R * 0.82, h * 0.18, SAND, 10);
  k.cone(x, y + h * 0.91, z, R * 1.05, h * 0.22, LEAD, 10);
  k.cyl(x, y + h * 1.13, z, R * 0.12, h * 0.06, GOLD, 6);
};

/**
 * The friday mosque: a square prayer hall under a great lead dome on a tiled drum, half-domes buttressing
 * it, an arcaded courtyard in front with a fountain, and a pencil minaret at each front corner.
 */
const blueMosque: Draw = (k, W, D, b, r) => {
  const w = Math.min(W - 0.4, 1.9), hall = w, hz = -D / 2 + w / 2 + 0.25, h = 0.62;
  // the prayer hall and its tiled band
  k.box(0, 0, hz, hall, h, hall, SAND, SAND_SHADE);
  k.box(0, h * 0.62, hz + hall / 2 + 0.002, hall - 0.1, 0.07, 0.008, TILE_BLUE);
  for (let i = 0; i < 5; i++) k.box(-hall / 2 + 0.12 + (i * (hall - 0.24)) / 4, h * 0.62, hz + hall / 2 + 0.006, 0.05, 0.06, 0.006, TILE_TURQ);
  row(k, b, r, 0, 0.14, hz + hall / 2, hall - 0.2, 0.18, 3, 1);
  for (const sx of [-1, 1]) row(k, b, r, sx * hall / 2, 0.14, hz, hall - 0.2, 0.18, 3, sx > 0 ? 0 : 2);
  // four half-domes round the drum, then the great dome
  const R = hall * 0.34;
  for (const [dx, dz] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
    k.dome(dx * hall * 0.32, h - 0.04, hz + dz * hall * 0.32, R * 0.52, TILE_TURQ, 10, 3);
  }
  k.cyl(0, h, hz, R * 1.04, 0.16, TILE_BLUE, 14);
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    k.box(Math.cos(a) * R * 1.05, h + 0.03, hz + Math.sin(a) * R * 1.05, 0.05, 0.1, 0.05, TILE_TURQ);
  }
  k.cyl(0, h + 0.16, hz, R * 1.1, 0.03, SAND_SHADE, 14);
  k.dome(0, h + 0.19, hz, R, TILE_BLUE, 14, 5);
  k.cyl(0, h + 0.19 + R * 0.95, hz, 0.03, 0.14, GOLD, 6);
  // the courtyard in front: a low arcade round three sides and a fountain in the middle
  const cz = hz + hall / 2 + (D / 2 - (hz + hall / 2)) / 2, cd = D / 2 - (hz + hall / 2) - 0.1, cw = W - 0.4;
  k.box(0, 0, cz, cw, 0.03, cd, hex(0xe4dcc8));
  for (const sx of [-1, 1]) {
    k.box(sx * (cw / 2 - 0.08), 0.03, cz, 0.16, 0.3, cd, SAND, SAND_SHADE);
    for (let i = 0; i < 4; i++) k.box(sx * (cw / 2 - 0.08), 0.03, cz - cd / 2 + (i + 0.5) * (cd / 4), 0.17, 0.2, 0.06, hex(0x2a211c));
    k.dome(sx * (cw / 2 - 0.08), 0.33, cz, 0.09, LEAD, 8, 3);
  }
  k.cyl(0, 0.03, cz, 0.12, 0.09, SAND_SHADE, 10);
  k.cyl(0, 0.12, cz, 0.08, 0.012, hex(0x5fc0d0), 10);
  // a minaret at each corner of the courtyard front
  for (const sx of [-1, 1]) minaret(k, sx * (cw / 2 - 0.12), D / 2 - 0.18, 0, 1.6, 0.075);
  k.glowBox(0, 0.36, hz + hall / 2 + 0.01, 0.3, 0.05, 0.02, hex(0xd8c070), NIGHT_LAMP, SHOP_GLOW);
};

// ---- the Ottoman city: the covered bazaar --------------------------------------------------------------

/**
 * The covered bazaar: a long stone hall roofed with a grid of little lead domes, a great pointed arch
 * (an iwan) over the street door with tiled spandrels, and lamps burning in the dark under the vaults.
 */
const bazaar: Draw = (k, W, D, b, r) => {
  const w = W - 0.2, d = D - 0.2, h = 0.46;
  k.box(0, 0, 0, w, h, d, SAND, SAND_SHADE);
  k.box(0, h, 0, w + 0.05, 0.04, d + 0.05, SAND_SHADE);
  // the roof: rows of little domes, each with a lantern at its crown
  const cols = Math.max(2, Math.round(w / 0.42)), rows = Math.max(1, Math.round(d / 0.42));
  const cw = w / cols, cd = d / rows, R = Math.min(cw, cd) * 0.46;
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const x = -w / 2 + cw * (i + 0.5), z = -d / 2 + cd * (j + 0.5);
      k.cyl(x, h + 0.04, z, R * 1.02, 0.03, SAND_SHADE, 8);
      k.dome(x, h + 0.07, z, R, LEAD, 8, 3);
      k.glowBox(x, h + 0.07 + R * 0.92, z, 0.035, 0.05, 0.035, hex(0xd8c070), [17, 29, 1.8], SHOP_GLOW);
    }
  }
  // the iwan: a tall recessed portal with a pointed head, tiled all round
  const fz = d / 2, pw = Math.min(0.72, w * 0.42), ph = h + 0.34;
  k.box(0, 0, fz + 0.04, pw + 0.18, ph, 0.1, SAND);
  k.box(0, 0, fz + 0.045, pw + 0.24, 0.06, 0.11, TILE_BLUE);
  k.box(0, ph - 0.06, fz + 0.045, pw + 0.24, 0.06, 0.11, TILE_BLUE);
  for (const sx of [-1, 1]) k.box(sx * (pw / 2 + 0.06), 0.06, fz + 0.095, 0.06, ph - 0.12, 0.012, TILE_TURQ);
  // the recess and the arch's point, stepped in courses
  k.box(0, 0, fz + 0.06, pw, ph - 0.22, 0.06, hex(0x2a211c));
  for (let i = 0; i < 4; i++) {
    const f = 1 - (i + 1) * 0.22;
    k.box(0, ph - 0.22 + i * 0.05, fz + 0.06, pw * Math.max(0.1, f), 0.05, 0.062, hex(0x2a211c));
  }
  for (const sx of [-1, 1]) k.box(sx * (pw / 2 + 0.03), ph - 0.16, fz + 0.1, 0.05, 0.1, 0.012, TILE_BLUE);
  // awnings and a bolt of cloth propped against the front
  for (const sx of [-1, 1]) {
    const ax = sx * (w / 2 - 0.22);
    k.box(ax, 0.3, fz + 0.06, 0.32, 0.02, 0.14, pick(r, [0xc8352a, 0x2f6a72, 0xd8a83a]));
    k.box(ax, 0, fz + 0.1, 0.1, 0.22, 0.06, pick(r, [0xb5402f, 0x2f5a8a, 0xd8b44a]));
  }
};

// ---- Mesoamerica: the step pyramid ----------------------------------------------------------------------

const LIMESTONE = hex(0xe6dcc4), LIME_SHADE = hex(0xc9b894), OCHRE = hex(0xb5402f), JADE = hex(0x2f7a5a);

/**
 * The step pyramid over the plaza: five battered tiers of limestone banded in red ochre, a stair straight
 * up the front with a balustrade each side, a temple with a roof comb on the platform, and stelae below.
 */
const stepPyramid: Draw = (k, W, D, b, r) => {
  const tiers = 5, base = Math.min(W, D) - 0.4;
  // steep, as they are: each tier is taller than it is set back, so the thing reads as a pyramid and not a terrace
  const th = 0.42, top = base * 0.34, inset = (base - top) / (2 * tiers), stairW = base * 0.28;
  let y = 0, s = base;
  for (let i = 0; i < tiers; i++) {
    k.box(0, y, 0, s, th, s, LIMESTONE, LIME_SHADE);
    // a band of red ochre under the lip of every tier
    k.box(0, y + th - 0.07, 0, s + 0.02, 0.05, s + 0.02, OCHRE);
    y += th;
    s -= 2 * inset;
  }
  // the stair: one flight straight up the front. Each tread is a column standing on the plaza, so the
  // flight reads as one solid stair from any angle instead of a ladder of floating slabs.
  // its foot stands out on the plaza, so the flight is proud of the face all the way up: run it at the
  // pyramid's own slope and it lies flush inside the tiers and all you see is a slab on each one.
  const rise = tiers * th, sz0 = base / 2, foot = sz0 + 0.5, head = sz0 - tiers * inset;
  const run = foot - head, steps = 12;
  for (let t = 0; t < steps; t++) {
    const z = foot - ((t + 0.5) * run) / steps;
    k.box(0, 0, z, stairW, ((t + 1) * rise) / steps, run / steps + 0.03, LIME_SHADE, LIMESTONE);
    for (const sx of [-1, 1]) k.box(sx * (stairW / 2 + 0.07), 0, z, 0.14, ((t + 1) * rise) / steps + 0.1, run / steps + 0.03, LIMESTONE);
  }
  // a serpent head at the foot of each balustrade
  for (const sx of [-1, 1]) {
    k.box(sx * (stairW / 2 + 0.07), 0, foot + 0.08, 0.16, 0.18, 0.18, LIME_SHADE);
    k.box(sx * (stairW / 2 + 0.07), 0.18, foot + 0.08, 0.1, 0.06, 0.12, OCHRE);
  }
  // the temple on top: a doorway, a banded cornice and a tall pierced roof comb
  const tw = s + 2 * inset + 0.12, hh = 0.36;
  k.box(0, y, 0, tw, hh, tw, LIMESTONE, LIME_SHADE);
  k.box(0, y + hh - 0.06, 0, tw + 0.05, 0.05, tw + 0.05, OCHRE);
  k.box(0, y, tw / 2 + 0.002, tw * 0.32, hh * 0.66, 0.012, hex(0x241c18));
  for (const sx of [-1, 1]) k.box(sx * tw * 0.32, y + hh * 0.3, tw / 2 + 0.004, 0.09, 0.14, 0.008, JADE);
  const comb = tw * 0.92;
  k.box(0, y + hh, 0, comb, 0.4, 0.08, LIMESTONE);
  for (let i = 0; i < 4; i++) k.box(-comb / 2 + (comb * (i + 0.5)) / 4, y + hh + 0.1, 0, comb * 0.11, 0.2, 0.09, hex(0x241c18));
  k.box(0, y + hh + 0.4, 0, comb * 0.7, 0.05, 0.09, OCHRE);
  // braziers at the stair's foot and a pair of carved stelae out on the plaza
  for (const sx of [-1, 1]) {
    k.cyl(sx * (stairW / 2 + 0.26), 0, foot + 0.1, 0.07, 0.13, LIME_SHADE, 8);
    k.glowBox(sx * (stairW / 2 + 0.26), 0.13, foot + 0.1, 0.09, 0.05, 0.09, hex(0xe0a050), [17.2, 29, 2.2], hex(0xff8a3a));
    k.box(sx * (base / 2 - 0.16), 0, base / 2 + 0.2, 0.1, 0.44, 0.07, LIME_SHADE);
    k.box(sx * (base / 2 - 0.16), 0.14, base / 2 + 0.236, 0.07, 0.22, 0.006, JADE);
  }
  void b; void r;
};

// ---- Mesoamerica: the ball court -------------------------------------------------------------------------

/**
 * The ball court: two long platforms with battered benches facing each other across a sunken alley, a
 * stone ring high on each side wall, and markers set into the floor between them.
 */
const ballCourt: Draw = (k, W, D, b, r) => {
  const alongX = W >= D;
  const len = (alongX ? W : D) - 0.3, span = (alongX ? D : W) - 0.3;
  // a wide enough alley to read as a lane between the platforms (and to drive down: see world/footprint.ts)
  const alley = Math.min(0.95, span * 0.46), pw = (span - alley) / 2, ph = 0.34;
  const at = (a: number, c: number): [number, number] => (alongX ? [a, c] : [c, a]);
  // the alley floor, sunk a little, with its centre marker
  {
    const [x, z] = at(0, 0);
    k.box(x, 0, z, alongX ? len : alley, 0.02, alongX ? alley : len, hex(0xd8cdb2));
    k.cyl(x, 0.02, z, alley * 0.16, 0.01, OCHRE, 10);
  }
  for (const s of [-1, 1]) {
    const [px, pz] = at(0, s * (alley + pw) / 2);
    // the platform, its sloping bench on the alley side and the plain wall above
    k.box(px, 0, pz, alongX ? len : pw, ph, alongX ? pw : len, LIMESTONE, LIME_SHADE);
    const [bx, bz] = at(0, s * (alley / 2 + pw * 0.16));
    k.wedge(bx, 0, bz, alongX ? len : pw * 0.4, 0.22, alongX ? pw * 0.4 : len, LIME_SHADE);
    // a band of ochre along the alley edge only: over the whole top it reads as a red roof
    const [ox, oz] = at(0, s * (alley / 2 + 0.06));
    k.box(ox, ph, oz, alongX ? len : 0.12, 0.04, alongX ? 0.12 : len, OCHRE);
    k.box(px, ph, pz, (alongX ? len : pw) + 0.02, 0.02, (alongX ? pw : len) + 0.02, LIMESTONE);
    // the ring, standing proud of the wall halfway along
    const [rx, rz] = at(0, s * (alley / 2 + 0.02));
    k.cyl(rx, ph - 0.12, rz, 0.075, 0.03, LIME_SHADE, 10);
    k.cyl(rx, ph - 0.12, rz, 0.032, 0.032, hex(0x241c18), 8);
    // end stones along the top of each platform
    for (let i = 0; i < 4; i++) {
      const o = -len / 2 + len * (i + 0.5) / 4;
      const [sx2, sz2] = at(o, s * (pw / 2 + alley / 2 - 0.05));
      k.box(sx2, ph + 0.04, sz2, 0.07, 0.1, 0.07, LIMESTONE);
    }
  }
  // a low stair up the end of each platform, and a brazier at the head of the alley
  for (const s of [-1, 1]) {
    const [ex, ez] = at(s * (len / 2 - 0.1), 0);
    k.box(ex, 0, ez, alongX ? 0.2 : alley, 0.1, alongX ? alley : 0.2, LIME_SHADE);
    k.glowBox(ex, 0.1, ez, 0.06, 0.05, 0.06, hex(0xe0a050), [17.2, 29, 2], hex(0xff8a3a));
  }
};


// ---- the classical world: the amphitheatre, the aqueduct and the forum -----------------------------------

const TRAVERTINE = hex(0xf0e6d2), TRAVERTINE_SHADE = hex(0xd8ccb2), PANTILE = hex(0xb5603a), MARBLE = hex(0xf6f2e6);
const BRONZE_GREEN = hex(0x5a7a6a);

// (the amphitheatre, the Colosseum, is drawn with the rest of Rome's buildings: render/buildings/rome.ts)

/**
 * The aqueduct: a double tier of arches striding across the lot with the water channel on top, and a
 * fountain basin at the near end where the town draws from it.
 */
const aqueduct: Draw = (k, W, D, b, r) => {
  const alongX = W >= D;
  const len = (alongX ? W : D) - 0.2, h = 1.35;
  const at = (a: number, c: number): [number, number] => (alongX ? [a, c] : [c, a]);
  const bays = Math.max(3, Math.round(len / 0.7)), bay = len / bays;
  for (let i = 0; i < bays; i++) {
    const o = -len / 2 + bay * (i + 0.5);
    // a big pier and arch below, two small ones above
    const [px, pz] = at(o - bay / 2, 0);
    k.box(px, 0, pz, alongX ? 0.18 : 0.42, h * 0.62, alongX ? 0.42 : 0.18, TRAVERTINE, TRAVERTINE_SHADE);
    const [ax2, az2] = at(o, 0);
    k.box(ax2, h * 0.44, az2, alongX ? bay : 0.42, h * 0.18, alongX ? 0.42 : bay, TRAVERTINE);
    // the head of the big arch under it, stepped in so the opening reads as an arch and not a doorway
    for (const [j, f] of [0.86, 0.6].entries()) {
      k.box(ax2, h * (0.32 + j * 0.06), az2, alongX ? bay * f : 0.44, h * 0.06, alongX ? 0.44 : bay * f, TRAVERTINE_SHADE);
    }
    for (const sx of [-1, 1]) {
      const [ux, uz] = at(o + (sx * bay) / 4, 0);
      k.box(ux, h * 0.62, uz, alongX ? 0.1 : 0.36, h * 0.24, alongX ? 0.36 : 0.1, TRAVERTINE_SHADE);
    }
  }
  // the channel along the top, and its water
  const [cx2, cz2] = at(0, 0);
  k.box(cx2, h * 0.86, cz2, alongX ? len : 0.46, 0.16, alongX ? 0.46 : len, TRAVERTINE);
  k.box(cx2, h * 1.0, cz2, alongX ? len + 0.02 : 0.2, 0.03, alongX ? 0.2 : len + 0.02, hex(0x5fb8d0));
  // the fountain at the near end: a basin, a spout and a puddle round it
  const [fx, fz] = at(-len / 2 + 0.2, D / 2 - 0.35);
  k.cyl(fx, 0, fz, 0.22, 0.1, TRAVERTINE_SHADE, 10);
  k.cyl(fx, 0.1, fz, 0.17, 0.02, hex(0x5fb8d0), 10);
  k.box(fx, 0.1, fz, 0.1, 0.3, 0.1, MARBLE);
  k.box(fx, 0.34, fz, 0.16, 0.06, 0.16, BRONZE_GREEN);
  void b; void r;
};

/**
 * The forum: a paved square closed on three sides by a colonnade, a basilica across the head of it with
 * a pedimented porch, and a rostrum and a pair of honorific columns out on the paving.
 */
const forum: Draw = (k, W, D, b, r) => {
  const w = W - 0.2, d = D - 0.2;
  k.box(0, 0, 0, w, 0.04, d, hex(0xe4ddcc));
  // the basilica at the back
  const bz = -d / 2 + Math.min(d * 0.34, 1.1), bh = 0.66, bw = Math.min(w - 0.4, 2.4);
  k.box(0, 0.04, bz, bw, bh, Math.min(d * 0.3, 0.9), TRAVERTINE, TRAVERTINE_SHADE);
  k.box(0, 0.04 + bh, bz, bw + 0.08, 0.05, Math.min(d * 0.3, 0.9) + 0.08, MARBLE);
  k.hip(0, 0.09 + bh, bz, bw + 0.06, 0.22, Math.min(d * 0.3, 0.9) + 0.06, PANTILE);
  row(k, b, r, 0, 0.2, bz + Math.min(d * 0.3, 0.9) / 2, bw - 0.3, 0.22, 5, 1);
  portico(k, bz + Math.min(d * 0.3, 0.9) / 2 + 0.16, Math.min(1.5, bw * 0.6), 0.5, 4, MARBLE, PANTILE);
  // the colonnade down each side and along the front, its roof low and tiled
  for (const sx of [-1, 1]) {
    const cx2 = sx * (w / 2 - 0.16);
    for (let i = 0; i < 7; i++) k.cyl(cx2, 0.04, -d / 2 + 0.3 + (i * (d - 0.6)) / 6, 0.055, 0.42, MARBLE, 8);
    k.box(cx2, 0.46, 0, 0.3, 0.05, d - 0.3, TRAVERTINE_SHADE);
    k.box(cx2, 0.51, 0, 0.34, 0.08, d - 0.3, PANTILE);
  }
  // the rostrum and two columns on the open paving
  k.box(0, 0.04, d / 2 - 0.5, 0.7, 0.16, 0.26, TRAVERTINE_SHADE);
  k.box(0, 0.2, d / 2 - 0.5, 0.6, 0.04, 0.2, MARBLE);
  for (const sx of [-1, 1]) {
    const px = sx * 0.5, pz = d / 2 - 0.22;
    k.box(px, 0.04, pz, 0.14, 0.06, 0.14, MARBLE);
    k.cyl(px, 0.1, pz, 0.05, 0.62, MARBLE, 8);
    k.box(px, 0.72, pz, 0.14, 0.05, 0.14, MARBLE);
    k.box(px, 0.77, pz, 0.07, 0.18, 0.07, BRONZE_GREEN);
  }
  k.glowBox(0, 0.28, d / 2 - 0.5, 0.2, 0.05, 0.05, hex(0xd8c070), NIGHT_LAMP, WARM_GLOW);
};

// ---- China: the earth house, the gateway and the drum tower ---------------------------------------------

const GREY_BRICK = hex(0x9a948a), WHITEWASH = hex(0xf0ece2), LACQUER = hex(0x9a3a2a), IMPERIAL = hex(0x8a7a2a);
const JADE_TILE = hex(0x3f6a4a), RAMMED = hex(0xd8c8a4), RAMMED_SHADE = hex(0xc2b08c);

/** A swept tile roof: a hipped body with its eaves flicked up at the corners. */
function sweptRoof(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, tile: RGB): void {
  k.hip(x, y, z, w, h, d, tile);
  // the flick: a thin lifted plate at each corner, and a ridge along the top
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(x + sx * (w / 2 + 0.02), y + 0.02, z + sz * (d / 2 + 0.02), 0.11, 0.035, 0.11, tile);
    k.box(x + sx * (w / 2 + 0.05), y + 0.055, z + sz * (d / 2 + 0.05), 0.07, 0.035, 0.07, tile);
  }
  k.box(x, y + h - 0.01, z, w * 0.9, 0.04, 0.06, scale(tile, 0.85));
}

/**
 * A tulou: a round rammed-earth house three storeys high, one ring of rooms round an open court, a
 * tiled roof sloping in and a single gate on the street.
 */
const tulou: Draw = (k, W, D, b, r) => {
  const R = Math.min(W, D) / 2 - 0.25, h = Math.max(3, Math.min(4, b.floors)) * FLOOR * 0.9;
  const seg = 18;
  k.cyl(0, 0, 0, R, 0.06, GREY_BRICK, seg);
  k.cyl(0, 0.06, 0, R, h, RAMMED, seg, RAMMED_SHADE);
  // windows only on the upper floors, as they were built
  for (let f = 1; f < 3; f++) {
    for (let i = 0; i < seg; i++) {
      const a = (i / seg) * TAU;
      k.box(Math.cos(a) * (R + 0.002), 0.06 + f * (h / 3) + 0.08, Math.sin(a) * (R + 0.002), 0.09, 0.11, 0.09, hex(0x2a211c));
    }
  }
  // the roof: a ring of tile sloping in over the rooms, and the court left open in the middle of it.
  // The inner disc is the yard seen from above, set below the tiles so the ring reads as a roof with a
  // hole in it rather than a lid.
  k.cyl(0, 0.06 + h, 0, R + 0.12, 0.05, JADE_TILE, seg);
  // the upper slope is laid as a ring of tiles, not a disc: a disc would roof the court over
  for (const [j, f] of [0.88, 0.74].entries()) {
    for (let i = 0; i < seg; i++) {
      const a2 = ((i + 0.5) / seg) * TAU, rr = R * f;
      k.box(Math.cos(a2) * rr, 0.09 + h + j * 0.05, Math.sin(a2) * rr, R * 0.34, 0.06, R * 0.34, scale(JADE_TILE, 0.94 - j * 0.06));
    }
  }
  // the inner wall of the ring and the yard at the bottom of it
  k.cyl(0, 0.06, 0, R * 0.58, h + 0.02, RAMMED_SHADE, seg);
  k.cyl(0, 0.07, 0, R * 0.54, h + 0.01, hex(0x3a3228), seg);
  k.cyl(0, 0.08, 0, R * 0.5, 0.02, hex(0xcfc7b4), seg);
  // the gallery rail round the court
  for (let i = 0; i < seg; i++) {
    const a = ((i + 0.5) / seg) * TAU;
    k.box(Math.cos(a) * R * 0.56, 0.06 + h * 0.66, Math.sin(a) * R * 0.56, 0.1, 0.05, 0.1, hex(0x7a4a24));
  }
  // the gate, with a lantern each side
  const gz = R - 0.02;
  k.box(0, 0.06, gz, 0.34, 0.42, 0.14, LACQUER);
  k.box(0, 0.48, gz, 0.44, 0.06, 0.18, JADE_TILE);
  for (const sx of [-1, 1]) k.glowBox(sx * 0.26, 0.38, gz + 0.06, 0.07, 0.1, 0.07, hex(0xd83a2a), [17.4, 29, 2], hex(0xff6a4a));
  void r;
};

/**
 * A paifang: a ceremonial gateway over the street, four lacquered posts on stone feet under three
 * swept roofs, with a gilded board naming the town across the middle.
 */
const paifang: Draw = (k, W, D, b, r) => {
  const w = Math.min(W - 0.2, 2.6), h = 1.0;
  for (const [i, sx] of [-1.5, -0.5, 0.5, 1.5].entries()) {
    const x = (sx * w) / 3.4;
    k.box(x, 0, 0, 0.16, 0.1, 0.22, GREY_BRICK);
    k.box(x, 0.1, 0, 0.1, h * (i === 0 || i === 3 ? 0.62 : 0.9), 0.12, LACQUER);
    // a stone drum bracing the outer posts
    if (i === 0 || i === 3) k.box(x, 0.1, 0, 0.16, 0.3, 0.2, hex(0xb8b2a6));
    void i;
  }
  // the beams: a wide one across all four posts and a short one over the middle bay
  k.box(0, h * 0.62, 0, w, 0.09, 0.16, LACQUER);
  k.box(0, h * 0.74, 0, w, 0.06, 0.2, IMPERIAL);
  k.box(0, h * 0.86, 0, w * 0.44, 0.1, 0.14, hex(0x7a2f2a));
  k.box(0, h * 0.88, 0.075, w * 0.36, 0.07, 0.01, IMPERIAL);
  // three roofs: the middle one higher, all swept
  sweptRoof(k, 0, h * 0.96, 0, w * 0.5, 0.2, 0.3, JADE_TILE);
  for (const sx of [-1, 1]) sweptRoof(k, (sx * w) / 2.9, h * 0.6, 0, w * 0.36, 0.2, 0.3, JADE_TILE);
  k.glowBox(0, h * 0.88, 0.09, w * 0.3, 0.05, 0.01, IMPERIAL, [17.4, 29, 1.8], hex(0xffd08a));
  void b; void r;
};

/**
 * The drum tower: a grey brick base with an arched way through it, a two-storey timber pavilion on top
 * under swept roofs, and the great drum hung in its upper gallery.
 */
const drumTower: Draw = (k, W, D, b, r) => {
  const w = Math.min(W - 0.2, 1.8), d = Math.min(D - 0.2, 1.8), bh = 0.72;
  k.box(0, 0, 0, w, bh, d, GREY_BRICK, hex(0x8a8478));
  k.box(0, bh, 0, w + 0.06, 0.05, d + 0.06, WHITEWASH);
  // the way through, on both faces
  for (const sz of [-1, 1]) k.box(0, 0, sz * (d / 2 - 0.01), w * 0.3, bh * 0.62, 0.03, hex(0x2a211c));
  // the pavilion: two storeys of red posts and white panels, each under a swept roof
  let y = bh + 0.05;
  for (const [i, f] of [0.82, 0.62].entries()) {
    const pw = w * f, pd = d * f, ph = 0.34;
    k.box(0, y, 0, pw, ph, pd, WHITEWASH);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (pw / 2 - 0.04), y, sz * (pd / 2 - 0.04), 0.07, ph, 0.07, LACQUER);
    row(k, b, r, 0, y + 0.08, pd / 2, pw - 0.16, 0.16, 3, 1);
    // the drum, hung on the upper floor and seen through the gallery
    if (i === 1) {
      k.cyl(0, y + 0.08, pd / 2 - 0.06, 0.12, 0.18, hex(0xb5402f), 10, hex(0xd8a83a));
      k.box(0, y + 0.26, pd / 2 - 0.06, 0.03, 0.08, 0.03, hex(0x3a2c24));
    }
    sweptRoof(k, 0, y + ph, 0, pw + 0.14, 0.16, pd + 0.14, IMPERIAL);
    y += ph + 0.16;
  }
  k.cone(0, y, 0, 0.06, 0.14, IMPERIAL, 6);
  for (const sx of [-1, 1]) k.glowBox(sx * (w / 2 - 0.12), 0.5, d / 2 + 0.02, 0.07, 0.1, 0.07, hex(0xd83a2a), [17.4, 29, 2], hex(0xff6a4a));
};

// ---- Southeast Asia: the wat, the temple-mountain and the split gate --------------------------------------

const TEAK = hex(0x7a4a24), GILT = hex(0xd8a83a), LAC_RED = hex(0x8a3a2a), WHITE_LIME = hex(0xf4efe2);
const SANDSTONE = hex(0xbfae94), SANDSTONE_SHADE = hex(0xa89880), MOSS = hex(0x6a7a58);

/** A tier of a Thai roof: a steep gable with gilded barge-boards that finish in a horn at the ridge. */
function watTier(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, tile: RGB): void {
  k.gable(x, y, z, w, h, d, tile, WHITE_LIME, true);
  for (const sz of [-1, 1]) {
    k.bar([x - w / 2 - 0.02, y, z + sz * (d / 2 + 0.01)], [x, y + h + 0.03, z + sz * (d / 2 + 0.01)], 0.022, GILT);
    k.bar([x + w / 2 + 0.02, y, z + sz * (d / 2 + 0.01)], [x, y + h + 0.03, z + sz * (d / 2 + 0.01)], 0.022, GILT);
    k.cone(x, y + h + 0.04, z + sz * (d / 2 + 0.01), 0.03, 0.16, GILT, 4);
  }
}

/**
 * A wat: a white ordination hall on a moulded plinth under three steps of steep gilt-edged roof, a
 * gilded stupa beside it and a pair of guardian figures at the stair.
 */
const wat: Draw = (k, W, D, b, r) => {
  const w = Math.min(W - 0.5, 1.6), d = Math.min(D - 0.6, 2.0), pz = -D / 2 + d / 2 + 0.3;
  // the plinth and the hall
  k.box(0, 0, pz, w + 0.3, 0.14, d + 0.3, WHITE_LIME, hex(0xe0d8c4));
  k.box(0, 0.14, pz, w, 0.46, d, WHITE_LIME);
  row(k, b, r, 0, 0.22, pz + d / 2, w - 0.2, 0.2, 3, 1);
  for (const sx of [-1, 1]) row(k, b, r, sx * w / 2, 0.22, pz, d - 0.3, 0.2, 4, sx > 0 ? 0 : 2);
  // three roofs, each shorter and steeper than the one below
  let y = 0.6, rw = w + 0.22, rd = d + 0.1;
  for (let i = 0; i < 3; i++) {
    watTier(k, 0, y, pz, rw, 0.26, rd, i === 1 ? GILT : LAC_RED);
    y += 0.2;
    rw *= 0.82;
    rd *= 0.86;
  }
  // the porch and its steps, with a guardian either side
  const fz = pz + d / 2 + 0.16;
  for (const sx of [-1, 1]) {
    k.cyl(sx * (w / 2 - 0.1), 0.14, fz, 0.04, 0.46, TEAK, 6);
    k.box(sx * (w / 2 + 0.14), 0, fz + 0.12, 0.1, 0.26, 0.1, hex(0x5a6a58));
    k.cone(sx * (w / 2 + 0.14), 0.26, fz + 0.12, 0.05, 0.1, GILT, 6);
  }
  k.box(0, 0, fz + 0.1, w * 0.5, 0.14, 0.16, WHITE_LIME);
  // the gilded stupa beside the hall
  const sx2 = w / 2 + 0.34, sz2 = pz - d / 4;
  k.box(sx2, 0, sz2, 0.34, 0.12, 0.34, WHITE_LIME);
  k.cyl(sx2, 0.12, sz2, 0.15, 0.16, GILT, 10);
  k.dome(sx2, 0.28, sz2, 0.14, GILT, 10, 4);
  for (let i = 0; i < 4; i++) k.cyl(sx2, 0.42 + i * 0.06, sz2, 0.07 - i * 0.014, 0.06, GILT, 8);
  k.cone(sx2, 0.66, sz2, 0.02, 0.2, GILT, 6);
  k.glowBox(0, 0.3, fz + 0.14, 0.12, 0.06, 0.04, GILT, [17.4, 29, 2], hex(0xffd08a));
};

/**
 * A Khmer temple-mountain: three sandstone terraces with a stair up each face, five corn-cob towers on
 * the top platform, and a lily moat round the foot of it.
 */
const khmerTemple: Draw = (k, W, D, b, r) => {
  const base = Math.min(W, D) - 0.5;
  // the moat and its causeway
  k.box(0, 0, 0, base + 0.44, 0.02, base + 0.44, hex(0x4a7a6a));
  k.box(0, 0.02, base / 2 + 0.16, 0.44, 0.04, 0.32, SANDSTONE);
  let y = 0, s = base;
  for (let i = 0; i < 3; i++) {
    k.box(0, y, 0, s, 0.3, s, SANDSTONE, SANDSTONE_SHADE);
    k.box(0, y + 0.26, 0, s + 0.04, 0.05, s + 0.04, SANDSTONE_SHADE);
    // a stair up the middle of each face
    for (const [dx, dz] of [[0, 1], [0, -1], [1, 0], [-1, 0]] as const) {
      k.box(dx * (s / 2 + 0.05), y, dz * (s / 2 + 0.05), dx ? 0.16 : 0.26, 0.3, dz ? 0.16 : 0.26, SANDSTONE_SHADE);
    }
    y += 0.3;
    s -= (base - base * 0.44) / 3;
  }
  // five towers: one in the middle and one at each corner of the top terrace
  const towerAt = (tx: number, tz: number, hh: number, R: number) => {
    k.box(tx, y, tz, R * 2.3, 0.12, R * 2.3, SANDSTONE);
    k.box(tx, y + 0.12, tz, R * 2, hh * 0.4, R * 2, SANDSTONE, SANDSTONE_SHADE);
    // the corn-cob: bands narrowing to a lotus bud
    let ty = y + 0.12 + hh * 0.4, rr = R * 1.9;
    for (let i = 0; i < 5; i++) {
      k.cyl(tx, ty, tz, rr / 2, hh * 0.1, i % 2 ? SANDSTONE : SANDSTONE_SHADE, 8);
      ty += hh * 0.1;
      rr *= 0.82;
    }
    k.cone(tx, ty, tz, rr / 2, hh * 0.28, SANDSTONE, 8);
    k.cone(tx, ty + hh * 0.28, tz, 0.02, 0.08, GILT, 6);
  };
  const off = s / 2 - 0.16;
  towerAt(0, 0, 1.0, 0.16);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) towerAt(sx * off, sz * off, 0.6, 0.1);
  // lilies on the water and moss on the lower course
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    k.disc(Math.cos(a) * (base / 2 + 0.14), 0.025, Math.sin(a) * (base / 2 + 0.14), 0.05, MOSS, 6);
  }
  void b; void r;
};

/**
 * A candi bentar: a gateway split clean down the middle into two carved halves, a paved path between
 * them, and a guardian statue and parasol on each side.
 */
const splitGate: Draw = (k, W, D, b, r) => {
  const gap = 0.38, h = 0.95, tw = Math.min(0.42, (W - 0.4 - gap) / 2);
  k.box(0, 0, 0, W - 0.2, 0.05, D - 0.2, hex(0xcfc7b4));
  k.box(0, 0.05, 0, gap, 0.02, D - 0.4, hex(0xe8e2d2));
  for (const sx of [-1, 1]) {
    const x = sx * (gap / 2 + tw / 2);
    // the half-tower: a stepped body that battered inward, banded in carved courses
    let y = 0.05, w = tw;
    for (let i = 0; i < 5; i++) {
      k.box(x, y, 0, w, h / 5, tw * 0.9, i % 2 ? SANDSTONE : SANDSTONE_SHADE);
      k.box(x, y + h / 5 - 0.03, 0, w + 0.03, 0.03, tw * 0.9 + 0.03, hex(0x8a7a62));
      y += h / 5;
      w *= 0.88;
    }
    k.cone(x, y, 0, w * 0.5, 0.16, SANDSTONE_SHADE, 4);
    // the flat inner face the gate is split along, and a black-and-white cloth at its foot
    k.box(x - sx * (tw / 2 - 0.01), 0.05, 0, 0.02, h * 0.8, tw * 0.9, hex(0xd8d2c4));
    k.box(x, 0.05, tw * 0.5, tw * 0.9, 0.16, 0.03, hex(0x2a2a2e));
    // a guardian and a parasol out front
    const gz = D / 2 - 0.3;
    k.box(x, 0, gz, 0.12, 0.3, 0.12, hex(0x9a948a));
    k.cyl(x, 0.3, gz, 0.02, 0.24, TEAK, 6);
    k.cone(x, 0.5, gz, 0.14, 0.1, pick(r, [0xd8a83a, 0xf0ece2, 0x8a3a2a]), 8);
    k.glowBox(x, 0.42, 0.06, 0.06, 0.08, 0.06, GILT, [17.4, 29, 1.8], hex(0xffd08a));
  }
  void b;
};


// ---- the bay city: the tower on the hill, the rotunda, the pyramid and the glass spire ------------------

const CONCRETE_PALE = hex(0xe8e4d8), CONCRETE_SHADE = hex(0xd0cabc), TERRACOTTA = hex(0xc98a6a);
const OXIDE = hex(0x8a6a5a), BAY_GLASS = hex(0x9fc4d8), LAGOON = hex(0x4a8a9a), COPPER_GREEN = hex(0x5a9a8a);
const QUARTZ = hex(0xf4f2ec), SPIRE_GLASS = hex(0x7fb0cc), WHITE_STONE = hex(0xf6f4ee);

/**
 * The tower on the hill: a plain fluted column of pale concrete, wider at its foot, with an arcaded
 * observation deck under a shallow crown and a beacon on top. Floodlit after dark.
 */
const coitTower: Draw = (k, W, D, b, r) => {
  // slender: a fluted column, not a gasholder. The lot is wide because of its terrace, not the shaft.
  const R = Math.min(0.42, Math.min(W, D) / 2 - 0.9), H = 4.2;
  // the podium it stands on, and a low wall round its terrace
  const T = Math.min(W, D) / 2 - 0.35;
  k.cyl(0, 0, 0, T, 0.12, CONCRETE_SHADE, 16);
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * TAU;
    k.box(Math.cos(a) * (T - 0.06), 0.12, Math.sin(a) * (T - 0.06), 0.12, 0.1, 0.12, CONCRETE_PALE);
  }
  // the shaft: slightly battered, with flutes running up it
  k.cyl(0, 0.12, 0, R, H * 0.2, CONCRETE_PALE, 16);
  k.cyl(0, 0.12 + H * 0.2, 0, R * 0.9, H * 0.6, CONCRETE_PALE, 16);
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * TAU, rr = R * 0.9;
    k.box(Math.cos(a) * rr, 0.12 + H * 0.2, Math.sin(a) * rr, 0.05, H * 0.6, 0.05, CONCRETE_SHADE);
  }
  // the observation stage: an arcade of tall openings under a plain band
  const oy = 0.12 + H * 0.8, orr = R * 0.94;
  k.cyl(0, oy, 0, orr, H * 0.16, CONCRETE_PALE, 16);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    k.box(Math.cos(a) * orr, oy + H * 0.02, Math.sin(a) * orr, 0.12, H * 0.1, 0.12, hex(0x3a3a3f));
  }
  k.cyl(0, oy + H * 0.16, 0, orr * 1.06, 0.06, CONCRETE_SHADE, 16);
  k.cyl(0, oy + H * 0.16 + 0.06, 0, orr * 0.8, 0.1, CONCRETE_PALE, 12);
  // the beacon, and floodlights round the foot
  k.glowBox(0, oy + H * 0.16 + 0.16, 0, 0.09, 0.08, 0.09, hex(0xd8c070), [17, 30, 2.6], hex(0xffe6b0));
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + 0.5;
    k.glowBox(Math.cos(a) * (T - 0.2), 0.12, Math.sin(a) * (T - 0.2), 0.08, 0.05, 0.08, hex(0x8a8a7a), [17, 30, 2.2], hex(0xfff0c8));
  }
  void b; void r;
};

/**
 * The palace by its lagoon: a domed rotunda on coupled columns, a curving colonnade running away from
 * it either side, and a still green lagoon in front with reeds along the near shore.
 */
const palaceFineArts: Draw = (k, W, D, b, r) => {
  const w = W - 0.4, d = D - 0.4;
  // the lagoon takes the front half of the lot
  const lz = d / 2 - d * 0.28;
  // the kerb first and the water on top of it: the other way round the kerb roofs the lagoon over
  k.box(0, 0, lz, w * 0.86 + 0.08, 0.02, d * 0.42 + 0.08, hex(0xc4bfa8));
  k.box(0, 0.02, lz, w * 0.86, 0.015, d * 0.42, LAGOON);
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    k.box(Math.cos(a) * w * 0.4, 0.02, lz + Math.sin(a) * d * 0.2, 0.06, 0.12, 0.06, hex(0x6a8a5a));
  }
  // the rotunda at the back: a stepped base, eight coupled columns, an entablature and a shallow dome
  const rz = -d / 2 + d * 0.3, R = Math.min(w, d) * 0.2;
  k.cyl(0, 0, rz, R + 0.14, 0.1, CONCRETE_SHADE, 12);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    for (const o of [-0.06, 0.06]) {
      k.cyl(Math.cos(a) * R + Math.cos(a + 1.57) * o, 0.1, rz + Math.sin(a) * R + Math.sin(a + 1.57) * o, 0.05, 0.8, TERRACOTTA, 8);
    }
  }
  k.cyl(0, 0.9, rz, R + 0.16, 0.12, TERRACOTTA, 12);
  k.cyl(0, 1.02, rz, R + 0.2, 0.05, OXIDE, 12);
  k.cyl(0, 1.07, rz, R * 0.92, 0.16, TERRACOTTA, 12);
  k.dome(0, 1.23, rz, R * 0.88, COPPER_GREEN, 12, 5);
  k.cyl(0, 1.23 + R * 0.84, rz, 0.05, 0.14, OXIDE, 8);
  // the colonnade: a curving row of columns either side, each pair under its own block of entablature
  for (const sx of [-1, 1]) {
    for (let i = 0; i < 6; i++) {
      const t = i / 5, cxp = sx * (R + 0.3 + t * (w / 2 - R - 0.5)), czp = rz + t * t * d * 0.3;
      k.cyl(cxp, 0, czp, 0.045, 0.62, TERRACOTTA, 8);
      k.box(cxp, 0.62, czp, 0.16, 0.1, 0.16, TERRACOTTA);
      if (i % 2 === 1) k.box(cxp, 0.72, czp, 0.2, 0.06, 0.2, OXIDE);
    }
  }
  // a path round the near shore, and lamps along it
  k.box(0, 0.005, d / 2 - 0.16, w * 0.9, 0.01, 0.2, hex(0xd8d2c0));
  for (const sx of [-1, 1]) k.glowBox(sx * w * 0.3, 0.02, d / 2 - 0.16, 0.05, 0.16, 0.05, hex(0x3a3a3f), NIGHT_LAMP, WARM_GLOW);
  void b; void r;
};

/**
 * The pyramid downtown: a tall white spire on a splayed base, a wing of lifts standing out of each
 * flank, and a lit crown above the last floor.
 */
const pyramidTower: Draw = (k, W, D, b, r) => {
  const floors = Math.max(20, b.floors), H = floors * FLOOR * 0.62;
  const base = Math.min(W, D) - 0.5;
  // the splayed feet: four legs the tower sits on, with the lobby between them
  const legH = 0.5;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(sx * base * 0.34, 0, sz * base * 0.34, 0.16, legH, 0.16, QUARTZ);
  }
  k.box(0, 0, 0, base * 0.62, legH * 0.7, base * 0.62, hex(0xdfe4e8), QUARTZ);
  // the shaft: a stack of storeys, each a little smaller than the one below
  const n = 14;
  let y = legH, wdt = base * 0.86;
  for (let i = 0; i < n; i++) {
    const h = H / n, next = wdt * 0.88;
    k.box(0, y, 0, wdt, h, wdt, QUARTZ, hex(0xe4e8ea));
    // the window bands, a dark line on each face
    k.box(0, y + h * 0.4, 0, wdt + 0.004, h * 0.34, wdt + 0.004, BAY_GLASS);
    y += h;
    wdt = next;
  }
  // the two wings of lifts, standing out of the east and west flanks two thirds of the way up
  for (const sx of [-1, 1]) {
    const wy = legH + H * 0.16, wh = H * 0.52;
    k.box(sx * base * 0.34, wy, 0, 0.18, wh, base * 0.3, QUARTZ, hex(0xe4e8ea));
    k.box(sx * base * 0.34, wy + wh, 0, 0.2, 0.06, base * 0.32, hex(0xdfe4e8));
  }
  // the crown and its light
  k.box(0, y, 0, wdt * 1.2, 0.1, wdt * 1.2, hex(0xdfe4e8));
  k.cyl(0, y + 0.1, 0, 0.05, 0.5, QUARTZ, 6);
  k.glowBox(0, y + 0.6, 0, 0.07, 0.07, 0.07, hex(0xe2412f), [17, 30, 2.6], hex(0xff6a4a));
  void r;
};

/**
 * The glass spire: a tall tapered tower of blue-green glass, its corners rounded off, standing on a
 * podium and finishing in an open lantern that glows all night. The tallest thing any city builds.
 */
const glassSpire: Draw = (k, W, D, b, r) => {
  const floors = Math.max(30, b.floors), H = floors * FLOOR * 0.7;
  const base = Math.min(W, D) - 0.3;
  // the podium, with an awning over its doors
  k.box(0, 0, 0, base + 0.2, 0.34, base + 0.2, hex(0xdfe4e8), QUARTZ);
  k.box(0, 0.34, 0, base + 0.26, 0.04, base + 0.26, WHITE_STONE);
  k.box(0, 0.1, base / 2 + 0.16, base * 0.5, 0.04, 0.14, WHITE_STONE);
  // the shaft: sixteen sides, tapering, with the corners chamfered so it reads as a rounded tower
  const seg = 16, n = 12;
  let y = 0.38, R = base * 0.44;
  for (let i = 0; i < n; i++) {
    const h = H / n;
    k.cyl(0, y, 0, R, h, SPIRE_GLASS, seg, scale(SPIRE_GLASS, 1.05));
    // the mullions: a pale rib at every second face
    if (i % 2 === 0) {
      for (let j = 0; j < seg; j += 2) {
        const a = (j / seg) * TAU;
        k.box(Math.cos(a) * R, y, Math.sin(a) * R, 0.05, h, 0.05, QUARTZ);
      }
    }
    // a band of pale stone every third floor, to break the glass up
    if (i % 3 === 2) k.cyl(0, y + h - 0.04, 0, R * 1.02, 0.05, WHITE_STONE, seg);
    y += h;
    R *= 0.93;
  }
  // the lantern: an open crown of fins that glows after dark, and an aircraft light above it
  for (let j = 0; j < seg; j += 1) {
    const a = (j / seg) * TAU;
    k.box(Math.cos(a) * R, y, Math.sin(a) * R, 0.05, 0.42, 0.05, QUARTZ);
  }
  k.glowBox(0, y + 0.06, 0, R * 1.4, 0.3, R * 1.4, scale(SPIRE_GLASS, 0.9), [17, 30, 2.4], hex(0xbfe4ff));
  k.cyl(0, y + 0.42, 0, R * 0.5, 0.06, WHITE_STONE, seg);
  k.glowBox(0, y + 0.48, 0, 0.06, 0.06, 0.06, hex(0xe2412f), [0, 30, 2.8], hex(0xff4a3a));
  void r;
};

