import type { World } from '../world/tiles';
import type { CargoType } from './cargoTypes';
import { isHelicopter, isJet, type CargoClass, type VehicleDef } from './vehicles';

/**
 * Cargo turns up for somebody (the cargo study, Oct 2026). Twenty game years of a small fleet showed the
 * board full nine-tenths of the time with loads nobody near could take — a third of everything expired —
 * while the HQ's own town had nothing waiting more often than not, and the fleet drifted off after the
 * goods that turned up round it. Now the island's work is written for its carriers: the player, the
 * player's hired drivers and the rival firms out on the road. Each is kept a few loads it could take a
 * short drive from where it stands; a load is never set down on top of another one waiting; goods
 * nobody is near enough to matter are not made, and go when everyone has left; and a carrier with nothing
 * it can take round it is given a load that carries it to a town where there is more.
 */
export const DEMAND = {
  /** Seconds between looks at who is short of work. */
  tick: 0.5,
  /** Loads made in one look at most (the board fills quickly after a crossing, without a burst in one frame). */
  perTick: 2,
  /** Tiles from a carrier a pick-up counts as its own: a short drive. */
  near: 60,
  /** Closer than this to a carrier a new load isn't put (it would be under its wheels). */
  close: 4,
  /** No new load within this many tiles of one already waiting: two rings on one kerb are one choice, not two. */
  cluster: 6,
  /** A load with less time than this left doesn't count toward anybody's supply. */
  minTtl: 30,
  /**
   * Loads kept within `near` of each carrier: the player; a hired driver looking for work, or one busy on a
   * run (whose supply is kept where the run ends, for when it looks again); a rival's vehicle.
   */
  you: 3, fleet: 1, fleetLooking: 3, rival: 1,
  /** How much each kind of carrier's shortfall weighs when choosing whom the next load is for. */
  weight: { you: 1.5, fleet: 1.2, rival: 0.5 } as Record<CarrierKind, number>,
  /** Waiting loads further than this from every carrier are going nowhere: they go after `farGrace` seconds. */
  far: 170, farGrace: 20,
  /**
   * The island's own haulers and the look of a busy place: a little work besides, never more than this
   * many waiting per trading cell with a carrier in reach, and only within `relevant` tiles of one.
   */
  ambientPerCell: 1.5, relevant: 130,
  /** Seconds a carrier goes short with nothing near to make before it is given a load out to busier country. */
  dryLure: 4,
  /** A lure's pick-up is at most this far from its carrier, and its trip at most `lureTrip` long. */
  lurePick: 100, lureTrip: 160,
  /** A busy place: from-sites within `busyR` of a destination, counted on a grid of `grid` tiles. */
  busyR: 32, grid: 16,
  /** A hired driver further than this from its base is given work that heads back toward it. */
  homePull: 90,
  /** Most loads waiting at once over all the trading islands, whatever anybody needs (a frame-time ceiling). */
  most: 64,
};

type CarrierKind = 'you' | 'fleet' | 'rival';

/** Somebody the island's work is written for. */
export interface Carrier {
  kind: CarrierKind;
  /** Stable while it is about (the unit's uid, the firm agent's id): its shortfall is remembered by it. */
  key: string;
  def: VehicleDef;
  /** Its island and where on it, and the same in world tiles. */
  w: World;
  lx: number; lz: number;
  x: number; z: number;
  /** Free for work now — no run under way, or room in the hold — rather than busy on one. */
  looking: boolean;
  /** Who it is to the towns' first refusal (game/carriage.ts): 'you' for the player and the fleet, a firm's id. */
  who: string;
  /** A hired driver's order: the classes it takes (empty for all), and the cells it may work. */
  takes?: CargoClass[];
  home?: { cx: number; cz: number };
  reach?: number;
  /** Its base in world tiles: a driver far from it is offered work that heads home. */
  base?: { x: number; z: number };
  /** A load has just been made for it: a driver idling between its looks for work looks again now. */
  wake?: () => void;
}

const cells = (a: { cx: number; cz: number }, b: { cx: number; cz: number }): number => Math.abs(a.cx - b.cx) + Math.abs(a.cz - b.cz);

/** Could this carrier take this kind of work at all — its hold, its licence, its order? (Where is another question.) */
export function takesType(c: Carrier, t: CargoType): boolean {
  if (t.missionOnly) return false;
  if (t.ultra) return false; // Ultra-Bulk work has its own spawner (game/cargo.ts spawnUltra)
  if (t.longHaul) return false; // and so does long-haul work (game/cargo.ts longHaulTick): it is never ordinary work
  if (t.sea) return false; // the boats' harbour work is kept separately (SEA_WORK)
  if (t.heli) return c.kind === 'you' && isHelicopter(c.def);
  if (t.jet) return c.kind === 'you' && isJet(c.def);
  if (c.def.kind === 'water' || c.def.kind === 'rail') return false;
  if (!c.def.holds.includes(t.cls) || t.units > c.def.capacity) return false;
  if (c.takes && c.takes.length && !c.takes.includes(t.cls)) return false;
  return true;
}

/** Do both ends of a trip lie where this carrier's order lets it work? */
export function inReach(c: Carrier, from: World, to: World): boolean {
  if (!c.home || c.reach === undefined) return true;
  return cells(from, c.home) <= c.reach && cells(to, c.home) <= c.reach;
}

/** How many loads this carrier wants kept near it. */
export function wantOf(c: Carrier): number {
  return c.kind === 'you' ? DEMAND.you : c.kind === 'fleet' ? (c.looking ? DEMAND.fleetLooking : DEMAND.fleet) : DEMAND.rival;
}

/** A weighted pick: each entry's chance is its weight over the sum. */
export function weighted<T>(list: { v: T; w: number }[]): T | null {
  let sum = 0;
  for (const e of list) sum += Math.max(0, e.w);
  if (sum <= 0) return null;
  let r = Math.random() * sum;
  for (const e of list) { r -= Math.max(0, e.w); if (r <= 0) return e.v; }
  return list[list.length - 1].v;
}
