// ---- the chain's places --------------------------------------------------------------------------

/** The fishing harbour the chain starts at: a little harbour first, a big one if there is none. */
const dock = (c: MissionCtx) => anchored(c, 'deep:dock', ['minorPort', 'majorPort'], null, 320, () => 'the harbour', { root: true });
const aq = (c: MissionCtx, near: Spot) => anchored(c, 'deep:aq', ['aquarium', 'university', 'researchStation', 'cannery'], near, 420, the);
const lightName = (k: string) => (k === 'capeLight' || k === 'lighthouse' ? 'the lighthouse' : k === 'hermitCabin' ? 'the keeper’s cabin' : the(k));
const light = (c: MissionCtx, near: Spot) => anchored(c, 'deep:light', ['capeLight', 'lighthouse', 'hermitCabin', 'harbourOffice'], near, 480, lightName);
const coast = (c: MissionCtx, near: Spot) => anchored(c, 'deep:cg', ['harbourOffice', 'police'], near, 320, (k) => (k === 'harbourOffice' ? 'the coastguard' : the(k)));
/** The dry dock: a naval dock if one is in reach, else a harbour's own dock, else a big harbour's quay. */
function yard(c: MissionCtx, near: Spot): Spot | null {
  return anchored(c, 'deep:yard', ['navalDock'], near, 900, () => 'the naval dock')
    ?? anchored(c, 'deep:yard', ['dryDock', 'majorPort', 'minorPort'], near, 700, (k) => (k === 'dryDock' ? 'the dry dock' : 'the harbour'), { root: true });
}
const studio = (c: MissionCtx, near: Spot) => anchored(c, 'deep:film', ['filmStudio', 'cinema', 'theatre', 'operaHouse', 'concertHall', 'techCampus', 'hotel', 'driveIn', 'motel', 'villageHall', 'pub'], near, 620, (k) => (k === 'filmStudio' ? 'the film studio' : the(k)));
const wreckName = (k: string) => (k === 'shipwreck' ? 'the wreck' : k === 'planeWreck' || k === 'ghostTown' || k === 'abandonedMine' ? 'the old wreck' : 'the far quay');

/** A harbour a good drive from this one, where a wreck's salvage would be landed. */
function farHarbour(c: MissionCtx, d: Spot): Spot | null {
  let best: Spot | null = null, bd = 0;
  for (const kind of ['majorPort', 'minorPort']) {
    for (let k = 0; k < 8; k++) {
      const a = (k / 8) * Math.PI * 2;
      const s = findSpot(c, [kind], { x: d.x + Math.sin(a) * 220, z: d.z + Math.cos(a) * 220 }, 200, () => 'the far quay', [d]);
      const far = s ? Math.hypot(s.x - d.x, s.z - d.z) : 0;
      if (s && far > bd && far < 400) { best = s; bd = far; }
    }
  }
  return bd >= 60 ? best : null;
}

/** Out on the water off the fishing harbour, `near` to `far` tiles from its pier: a buoy, a castaway (the boat forms, 0.7.0). */
function offHarbour(d: Spot, h: number, name: string, near = 14, far = 40): Spot | null {
  const port = [...d.w.ports].sort((a, b) => Math.hypot(d.w.ox + a.x - d.x, d.w.oz + a.z - d.z) - Math.hypot(d.w.ox + b.x - d.x, d.w.oz + b.z - d.z))[0];
  const o = port && offshore(d.w, port.root, port.dir, h, near, far);
  if (!o) return null;
  const x = d.w.ox + o.lx, z = d.w.oz + o.lz;
  return { w: d.w, b: null, town: d.town, kind: 'buoy', x, z, at: { x, z, cell: [d.w.cx, d.w.cz], name } };
}

function bearing(from: { x: number; z: number }, to: { x: number; z: number }): string {
  const W = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
  return W[((Math.round(Math.atan2(to.x - from.x, -(to.z - from.z)) / (Math.PI / 4)) % 8) + 8) % 8];
}

const HOLT = (s: Spot) => giver('harbour', 'Skipper Holt', s);
const LIND = (s: Spot) => giver('aquarium', 'Dr. Lind', s);
const ROOK = (s: Spot) => giver('coastguard', 'CPO Rook', s);
const RAFE = (s: Spot) => giver('studio', 'Rafe Castellanos', s);
const ADEYEMI = (s: Spot) => giver('navy', 'Commander Adeyemi', s);
const crate = (colour: number): HeroSpec => ({ kind: 'crate', colour });

const card = (o: { title: string; why: string; details: string; giver: Draft['giver']; hero: HeroSpec; caption: string; objs: (Obj | null)[]; reward: Reward[]; hours?: number }): Draft | null =>
  o.objs.some((q) => !q) ? null : { ...o, objs: o.objs as Obj[] };

/**
 * A wreck on the seabed near the fishing harbour that the submarine being driven can go down to (world/seabed.ts,
 * docs/underwater.html): the chain's wreck, in its submarine form.
 */
function seaWreck(c: MissionCtx, d: Spot, hi = 520): Site | null {
  const need = c.def.kind === 'water' && c.def.dive ? c.def.dive.need : null;
  if (need === null) return null;
  let best: Site | null = null, bd = hi;
  for (const s of c.sites(['seaWreck'])) {
    const far = Math.hypot(s.x - d.x, s.z - d.z);
    // deep enough for this sub anywhere in the dive's ring, not only over the wreck's middle
    if (s.seabed && (s.depth ?? 0) >= need && far < bd && roomAt(s.w, Math.floor(s.lx), Math.floor(s.lz), WRECK_R) >= need) { bd = far; best = s; }
  }
  return best;
}
/** The ring the race to the wreck is won in, in tiles. */
const WRECK_R = 2;
/** A seabed site's own name for a card ("the wreck of the Calypso"). */
const seaName = (s: Site): string => { const n = s.name.split(' · ')[0]; return n.charAt(0).toLowerCase() + n.slice(1); };

